fn observeSearchFailureMetric(name: ?[]const u8, query_type: db_query_metrics.QueryType, duration_ns: u64) void {
    if (db_query_search.peekLastSortRejectionDiagnostic()) |diagnostic| {
        db_query_metrics.observeSortRejection(name, query_type, duration_ns, diagnostic.reason, diagnostic.detail);
        return;
    }
    db_query_metrics.observe(name, query_type, duration_ns);
}

fn validateDocumentExtractionInlineSources(db: *DB, doc_value: []const u8) !void {
    var has_document_extraction_asset = false;
    for (db.core.index_manager.enrichments.items) |entry| {
        if (entry.kind != .asset) continue;
        var producer_cfg = asset_producer_mod.parseProducerConfig(db.alloc, entry.producer_json) catch continue;
        defer producer_cfg.deinit(db.alloc);
        if (producer_cfg.type == .document_extraction) {
            has_document_extraction_asset = true;
            break;
        }
    }
    if (!has_document_extraction_asset) return;

    const parsed = try std.json.parseFromSlice(std.json.Value, db.alloc, doc_value, .{});
    defer parsed.deinit();
    if (parsed.value != .object) return;

    for (db.core.index_manager.enrichments.items) |entry| {
        if (entry.kind != .asset) continue;
        var producer_cfg = asset_producer_mod.parseProducerConfig(db.alloc, entry.producer_json) catch continue;
        defer producer_cfg.deinit(db.alloc);
        if (producer_cfg.type != .document_extraction) continue;

        if (entry.source_template.len > 0) {
            const rendered = renderSourceTemplateText(db.alloc, db.secret_store, db.remote_content, entry.source_template, doc_value) catch |err| switch (err) {
                error.PermanentPromptFailure, error.TransientPromptFailure => return err,
                else => continue,
            };
            defer db.alloc.free(rendered);
            try document_extraction_mod.validateInlineSourceSize(db.remote_content, rendered);
            continue;
        }

        const source = parsed.value.object.get(entry.source_field) orelse continue;
        if (source != .string) continue;
        try document_extraction_mod.validateInlineSourceSize(db.remote_content, source.string);
    }
}

test "document extraction inline source size uses remote content limit" {
    const security = scraping.ContentSecurityConfig{ .max_download_size_bytes = 4 };
    var remote_content = scraping.RemoteContentConfig{ .security = security };
    try std.testing.expect(try document_extraction_mod.inlineDataUriSourceTooLarge(&remote_content, "data:text/plain;base64,aGVsbG8="));
    try std.testing.expect(!try document_extraction_mod.inlineDataUriSourceTooLarge(&remote_content, "data:text/plain;base64,Zm9v"));
    try std.testing.expect(!try document_extraction_mod.inlineDataUriSourceTooLarge(&remote_content, "data:"));
}

test "document extraction templated inline source size is rejected before persistence" {
    const alloc = std.testing.allocator;

    var path_buf: [256]u8 = undefined;
    const path = tempPath(&path_buf);
    defer cleanupTempDir(path);

    const security = scraping.ContentSecurityConfig{ .max_download_size_bytes = 4 };
    var remote_content = scraping.RemoteContentConfig{ .security = security };
    var db = try DB.open(alloc, std.mem.span(path), .{
        .remote_content = &remote_content,
        .start_index_workers = false,
        .ttl_cleanup = .{ .enabled = false },
    });
    defer db.close();

    try db.addEnrichment(.{
        .name = "document_units_v1",
        .kind = .asset,
        .template = "{{url}}",
        .content_type = "application/json",
        .producer_json = "{\"type\":\"document_extraction\",\"config\":{}}",
    });
    try std.testing.expectError(error.StreamTooLong, db.batch(.{
        .writes = &.{.{
            .key = "doc:templated-too-large",
            .value = "{\"url\":\"data:text/plain;base64,aGVsbG8=\"}",
        }},
        .sync_level = .write,
    }));

    const doc_key = try internal_keys.documentKeyAlloc(alloc, "doc:templated-too-large");
    defer alloc.free(doc_key);
    try std.testing.expectError(error.NotFound, db.core.store.get(alloc, doc_key));
}

pub const OpenOptions = struct {
    pub const PhysicalRootMode = enum {
        /// The DB path names a directory-backed physical root. DB owns its
        /// publication lease and persists the projection incarnation there.
        filesystem_managed,
        /// The DB path is only a logical namespace. An external backend owns
        /// physical publication, locking, and durability for that namespace.
        external_backend,
    };

    pub const OpenMode = enum {
        writer,
        writer_no_replay,
        query_readonly,
        status_only,

        fn allowsReplay(self: @This()) bool {
            return self == .writer;
        }

        fn allowsIndexWorkers(self: @This()) bool {
            return self == .writer or self == .writer_no_replay;
        }

        fn allowsOptionalRuntimes(self: @This()) bool {
            return self == .writer or self == .writer_no_replay;
        }
    };

    open_mode: OpenOptions.OpenMode = .writer,
    map_size: usize = 256 * 1024 * 1024,
    no_sync: bool = false,
    primary_backend: PrimaryBackend = .{ .lsm = db_config.primary_lsm_options_default },
    primary_runtime_store: ?*backend_erased_mod.Store = null,
    storage: ?lsm_backend_mod.Storage = null,
    lsm_cache: ?*lsm_backend_mod.Cache = null,
    hbc_cache: ?*hbc_mod.Cache = null,
    lsm_root_generation: u64 = 0,
    staged_generation: ?*const generation_lifecycle.StagedGeneration = null,
    resource_manager: ?*resource_manager_mod.ResourceManager = null,
    /// Optional storage-backend capacity probe. BackendRuntime configurators
    /// may install this while composing a DB open; it is resource policy input,
    /// not executor ownership.
    capacity_source: ?types.RepairCapacitySource = null,
    change_journal_backend: ?change_journal_mod.StorageBackend = null,
    change_journal_storage: ?lsm_backend_mod.Storage = null,
    index_backends: db_config.IndexBackendOptions = .{},
    index_base_path: ?[]const u8 = null,
    index_open_parallelism: ?usize = null,
    /// Authoritative local-provisioning schema to persist after the primary
    /// store is open but before any configured index is opened or backfilled.
    /// The caller retains ownership for the duration of `open`. This closes a
    /// schema-migration ordering hole where an interrupted target-generation
    /// backfill could resume with the previously persisted (or schema-less)
    /// mapper before the provisioner got a chance to call `setSchema`.
    schema_before_index_load: ?schema_mod.TableSchema = null,
    identity_namespace: ?doc_identity.Namespace = null,
    prefer_existing_identity_namespace: bool = false,
    executor: derived_executor_mod.Config = .{},
    backend_runtime: ?*background_runtime_mod.BackendRuntime = null,
    secret_store: ?*common_secrets.FileStore = null,
    remote_content: ?*const scraping.RemoteContentConfig = null,
    start_index_workers: bool = true,
    start_optional_runtimes: bool = true,
    start_optional_runtime_workers: bool = true,
    external_derived_checkpoints: bool = true,
    /// Optional durable namespace for replica-local index repair state.
    /// Externally owned roots use this to keep crash-resume intent and replay
    /// pins inside the same atomic storage generation as their indexes.
    index_repair_checkpoint_storage: ?lsm_backend_mod.Storage = null,
    physical_root_mode: PhysicalRootMode = .filesystem_managed,
    /// Optional enrichment providers. `DB.open` takes ownership of every
    /// non-null provider when called, including when the open subsequently
    /// fails. A successfully opened DB releases them from `close`.
    enrichment: ?enrichment_runtime_mod.Config = null,
    ttl_cleanup: ttl_runtime_mod.Config = .{},
    transaction_recovery: transaction_runtime_mod.Config = .{},
    text_merge: text_merge_runtime_mod.Config = .{},
    sparse_compaction: sparse_compaction_runtime_mod.Config = .{},
    /// Optional cross-shard candidate source for entity resolution blocking,
    /// injected by the serving layer (see `api/distributed_candidate_source.zig`).
    /// Null means local-only blocking against the worker's own store. Must
    /// outlive the DB.
    resolution_candidate_source: ?resolution_runtime_mod.CandidateSource = null,
    /// Optional cross-shard entity sink for the promoter, injected by the serving
    /// layer (see `api/distributed_entity_sink.zig`). Must outlive the DB.
    entity_sink: ?promotion_runtime_mod.EntitySink = null,
    /// Optional ownership guard for promotion. Raft apply-side DBs set this so
    /// only the source shard leader emits entity writes; standalone DBs leave it
    /// null and are treated as local owners.
    promotion_owner: ?promotion_runtime_mod.PromotionOwner = null,
    /// What the promoter does when no sink is currently available. The safe
    /// default holds replay so a later sink injection or routing repair can retry.
    entity_sink_missing_policy: promotion_runtime_mod.MissingSinkPolicy = .wait,
    /// Optional name embedder for resolution: backfills a mention's name
    /// embedding (for cosine/ann blocking) when a resolver declares a
    /// `name_embedding` model and the extraction artifact carries no vector.
    /// Caller-owned; must outlive the DB. Null disables backfill.
    resolution_embedder: ?embedder_mod.DenseEmbedder = null,
    /// Optional mirror for committed derived/change-journal effects into the HA
    /// replication stream. The default policy is async/best-effort; configuring
    /// a non-async sync_policy makes normal DB writes evaluate the HA commit
    /// gate for the appended replication record.
    ha_async_effect_mirror: ?HAAsyncEffectMirror = null,
    /// Optional mirror for committed user batch mutations into the HA
    /// replication stream. This emits versioned `batch_mutation` envelopes for
    /// catch-up/read-replica apply and can be paired with sync_policy for
    /// remote-write/remote-apply gate decisions.
    ha_async_batch_mirror: ?HAAsyncBatchMirror = null,
    /// Optional mirror for committed metadata/catalog changes into the HA
    /// replication stream. The initial metadata mutation payload covers table
    /// schema changes; additional catalog mutation kinds should be nested under
    /// the stable HA `metadata_mutation` envelope.
    ha_async_metadata_mirror: ?HAAsyncMetadataMirror = null,
    /// Optional HA write ownership gate. Client/API writes are allowed only
    /// when this DB is attached to the current HA primary. Standby apply paths
    /// must use replicated-apply entry points that explicitly bypass this
    /// client-write guard. A standby gate also suppresses mutating background
    /// runtimes at open, even if the generic runtime defaults are enabled.
    ha_write_gate: ?HAWriteGate = null,
};

pub const OpenMode = OpenOptions.OpenMode;

pub const HAMutationBarrier = ha_mutation_barrier_mod.MutationBarrier;

fn deinitOwnedEnrichmentConfig(alloc: Allocator, cfg: *enrichment_runtime_mod.Config) void {
    if (cfg.dense_embedder) |dense_embedder| {
        dense_embedder.deinit(alloc);
        cfg.dense_embedder = null;
    }
    if (cfg.sparse_embedder) |sparse_embedder| {
        sparse_embedder.deinit(alloc);
        cfg.sparse_embedder = null;
    }
    if (cfg.asset_producer) |producer| {
        producer.deinit(alloc);
        cfg.asset_producer = null;
    }
}

pub const HAAsyncEffectMirror = struct {
    primary: *ha_primary_mod.Primary,
    /// Shared across every DB/catalog writer owned by one HA runtime. Mutations
    /// hold a shared lease from before their first persistent side effect until
    /// WAL publication and the sync durability decision finish. Seed capture
    /// takes the exclusive lease before choosing its checkpoint.
    mutation_barrier: ?*HAMutationBarrier = null,
    /// Serializes the final client-write gate check, HA WAL append, and sync
    /// acknowledgement with a node-local promotion fence. When configured,
    /// every acknowledged write is wholly before or wholly after the frozen
    /// former-primary boundary.
    transition_mutex: ?*std.atomic.Mutex = null,
    last_lsn: ?*std.atomic.Value(u64) = null,
    failure_count: ?*std.atomic.Value(u64) = null,
    sync_policy: ha_primary_mod.SyncPolicy = .{},
    sync_wait_ctx: ?*anyopaque = null,
    sync_wait_fn: ?HASyncWaitFn = null,
    last_gate_lsn: ?*std.atomic.Value(u64) = null,
    last_gate_action: ?*std.atomic.Value(u8) = null,
    sync_reject_count: ?*std.atomic.Value(u64) = null,
    sync_wait_count: ?*std.atomic.Value(u64) = null,
    sync_degraded_count: ?*std.atomic.Value(u64) = null,
};

pub const HASyncWaitFn = *const fn (
    ctx: *anyopaque,
    primary: *ha_primary_mod.Primary,
    target_lsn: u64,
    policy: ha_primary_mod.SyncPolicy,
) anyerror!void;

pub const HAProgressPollFn = *const fn (
    ctx: *anyopaque,
    primary: *ha_primary_mod.Primary,
    target_lsn: u64,
    policy: ha_primary_mod.SyncPolicy,
    round: usize,
) anyerror!void;

pub const HAPrimaryProgressSyncWait = struct {
    max_rounds: usize = 64,
    sleep_ns: u64 = 0,
    poll_ctx: ?*anyopaque = null,
    poll_fn: ?HAProgressPollFn = null,

    pub fn wait(ctx: *anyopaque, primary: *ha_primary_mod.Primary, target_lsn: u64, policy: ha_primary_mod.SyncPolicy) !void {
        const self: *@This() = @ptrCast(@alignCast(ctx));
        if (policy.mode == .async) return;
        if (self.max_rounds == 0) return error.HASyncCommitWaitLimitExceeded;

        var round: usize = 0;
        while (round < self.max_rounds) : (round += 1) {
            if (self.poll_fn) |poll| {
                const poll_ctx = self.poll_ctx orelse return error.HASyncCommitWaitMissingContext;
                try poll(poll_ctx, primary, target_lsn, policy, round);
            }

            const gate = try ha_commit_gate_mod.evaluate(primary, target_lsn, policy);
            if (gate.shouldAcknowledge()) return;
            if (gate.action == .reject) return error.SyncPolicyUnsatisfied;
            if (self.sleep_ns > 0) sleepNs(self.sleep_ns);
        }

        return error.HASyncCommitWouldBlock;
    }
};

pub const HASessionSyncWait = struct {
    alloc: Allocator,
    slot_name: []const u8,
    standby: *ha_standby_mod.Standby,
    apply_ctx: *anyopaque,
    apply_fn: ha_standby_mod.ApplyFn,
    max_rounds: usize = 8,

    pub fn wait(ctx: *anyopaque, primary: *ha_primary_mod.Primary, target_lsn: u64, policy: ha_primary_mod.SyncPolicy) !void {
        const self: *@This() = @ptrCast(@alignCast(ctx));
        if (policy.mode == .async) return;
        if (!haSyncPolicyIncludesStandby(policy, self.slot_name)) return error.HASyncCommitWaitStandbyNotInPolicy;
        if (self.max_rounds == 0) return error.HASyncCommitWaitLimitExceeded;

        var progress = self.standby.currentProgress();
        var round: usize = 0;
        while (round < self.max_rounds) : (round += 1) {
            const result = ha_session_mod.replicateAvailable(
                self.alloc,
                primary,
                self.slot_name,
                self.standby,
                self.apply_ctx,
                self.apply_fn,
            ) catch |err| {
                if (policy.mode == .remote_write) {
                    const gate = ha_commit_gate_mod.evaluate(primary, target_lsn, policy) catch return err;
                    if (gate.shouldAcknowledge()) return;
                }
                return err;
            };

            const gate = try ha_commit_gate_mod.evaluate(primary, target_lsn, policy);
            if (gate.shouldAcknowledge()) return;
            if (gate.action == .reject) return error.SyncPolicyUnsatisfied;
            if (result.received_count == 0 and result.applied_count == 0) break;

            const next_progress = self.standby.currentProgress();
            if (next_progress.received_lsn == progress.received_lsn and
                next_progress.applied_lsn == progress.applied_lsn and
                next_progress.safe_read_lsn == progress.safe_read_lsn)
            {
                break;
            }
            progress = next_progress;
        }

        return error.HASyncCommitWouldBlock;
    }
};

fn haSyncPolicyIncludesStandby(policy: ha_primary_mod.SyncPolicy, slot_name: []const u8) bool {
    for (policy.standby_names) |name| {
        if (std.mem.eql(u8, name, slot_name)) return true;
    }
    return false;
}

