    start_optional_runtimes_ns: u64 = 0,
    total_ns: u64 = 0,
};

fn recordProfileNs(profile: ?*BatchProfile, field: *u64, start_ns: u64) void {
    if (profile == null) return;
    field.* += monotonicTimeNs() - start_ns;
}

