fn denseLsmWriteStatsSnapshot(ctx: *AsyncContext, index_name: []const u8) ?hbc_mod.LsmWriteStats {
    const entry = ctx.index_manager.denseIndex(index_name) orelse return null;
    return entry.index.snapshotLsmWriteStats();
}

fn denseLsmWriteStatsDelta(after: hbc_mod.LsmWriteStats, before: hbc_mod.LsmWriteStats) hbc_mod.LsmWriteStats {
    var delta = after;
    inline for (std.meta.fields(hbc_mod.LsmWriteStats)) |field| {
        if (field.type == u64) {
            @field(delta, field.name) = @field(after, field.name) -| @field(before, field.name);
        }
    }
    return delta;
}

fn sleepNs(duration_ns: u64) void {
    if (comptime builtin.os.tag == .freestanding) {
        return;
    }

    var req = std.posix.timespec{
        .sec = @intCast(duration_ns / std.time.ns_per_s),
        .nsec = @intCast(duration_ns % std.time.ns_per_s),
    };
    while (true) switch (std.posix.errno(std.posix.system.nanosleep(&req, &req))) {
        .SUCCESS => return,
        .INTR => continue,
        else => return,
    };
}

fn groupCreatedAtMetadataKeyAlloc(alloc: Allocator, group_id: u64) ![]u8 {
    return try std.fmt.allocPrint(alloc, "\x00\x00__metadata__:data_group_created_at:{d}", .{group_id});
}

fn sleepPollInterval() void {
    platform_clock.Clock.real().sleepMs(10);
}

fn yieldToBackground() void {
    var spins: usize = 0;
    while (spins < 16) : (spins += 1) {
        spinOrYield();
    }
    sleepPollInterval();
}

const PrimaryStoreOpenPlan = union(enum) {
    lmdb: struct {
        map_size: usize,
        no_sync: bool,
        read_only: bool,
    },
    mem: mem_backend_mod.Options,
    lsm_memory: lsm_backend_mod.Options,
    lsm: lsm_backend_mod.Options,
};

const SplitDestinationStorePlan = union(enum) {
    lmdb,
    lsm: lsm_backend_mod.Options,
    unsupported,
};

fn primaryStoreOpenPlan(opts: db_config.CoreOpenOptions) PrimaryStoreOpenPlan {
    return switch (opts.primary_backend) {
        .lmdb => .{
            .lmdb = .{
                .map_size = opts.map_size,
                .no_sync = opts.no_sync,
                .read_only = opts.read_only,
            },
        },
        .mem => |mem_opts| .{ .mem = mem_opts },
        .lsm_memory => |lsm_opts| .{ .lsm_memory = db_config.mergedLsmOptions(opts.storage, opts.lsm_cache, opts.resource_manager, opts.bind_cache_resource_manager, opts.no_sync, lsm_opts) },
        .lsm => |lsm_opts| .{ .lsm = db_config.mergedLsmOptions(opts.storage, opts.lsm_cache, opts.resource_manager, opts.bind_cache_resource_manager, opts.no_sync, lsm_opts) },
    };
}

fn openModeRequiresReadOnlyBackends(open_mode: OpenOptions.OpenMode) bool {
    return open_mode == .query_readonly or open_mode == .status_only;
}

fn makeLsmOptionsReadOnly(options: *lsm_backend_mod.Options) void {
    options.backend.read_only = true;
    options.backend.create_if_missing = false;
    options.background_executor = null;
}

fn applyReadOnlyToPrimaryBackend(primary_backend: *PrimaryBackend) void {
    switch (primary_backend.*) {
        .lsm => |*lsm_opts| makeLsmOptionsReadOnly(lsm_opts),
        .lsm_memory => |*lsm_opts| makeLsmOptionsReadOnly(lsm_opts),
        .lmdb, .mem => {},
    }
}

fn applyReadOnlyToIndexBackends(index_backends: *db_config.IndexBackendOptions) void {
    makeLsmOptionsReadOnly(&index_backends.text_main_lsm_options);
    makeLsmOptionsReadOnly(&index_backends.text_wal_lsm_options);
    makeLsmOptionsReadOnly(&index_backends.dense_lsm_options);
    makeLsmOptionsReadOnly(&index_backends.sparse_lsm_options);
    makeLsmOptionsReadOnly(&index_backends.graph_reverse_lsm_options);
}

fn splitDestinationStorePlan(self: *DB) SplitDestinationStorePlan {
    return switch (self.primary_backend) {
        .lmdb => .lmdb,
        .lsm => |opts| .{ .lsm = db_config.splitLsmOptions(.{ .lsm = opts }, self.primary_lsm_storage, opts.cache).? },
        .mem, .lsm_memory => .unsupported,
    };
}

fn makeLsmBackgroundExecutor(runtime: *background_runtime_mod.BackendRuntime, owner_id: u64) lsm_backend_mod.BackgroundExecutor {
    return lsm_backend_mod.BackgroundExecutor.init(runtime, owner_id);
}

fn installLsmReadRuntime(options: *lsm_backend_mod.Options, runtime: *background_runtime_mod.BackendRuntime) void {
    if (options.native_storage_pool == null) options.native_storage_pool = runtime.nativeStoragePool();
    if (options.read_runtime != null) return;
    if (runtime.io()) |io| options.read_runtime = lsm_backend_mod.storage_io.ReadRuntime.init(io);
}

fn installIndexLsmReadRuntime(index_backends: anytype, runtime: *background_runtime_mod.BackendRuntime) void {
    installLsmReadRuntime(&index_backends.text_main_lsm_options, runtime);
    installLsmReadRuntime(&index_backends.text_wal_lsm_options, runtime);
    installLsmReadRuntime(&index_backends.dense_lsm_options, runtime);
    installLsmReadRuntime(&index_backends.sparse_lsm_options, runtime);
    installLsmReadRuntime(&index_backends.graph_reverse_lsm_options, runtime);
}

fn openPrimaryStore(alloc: Allocator, path: []const u8, opts: db_config.CoreOpenOptions) !db_core.OpenedPrimaryStore {
    if (opts.primary_runtime_store) |runtime_store| {
        return .{
            .store = try docstore_mod.DocStore.openRuntime(alloc, runtime_store),
        };
    }

    const zpath = try alloc.dupeZ(u8, path);
    defer alloc.free(zpath);

    return switch (primaryStoreOpenPlan(opts)) {
        .lmdb => |lmdb_opts| .{
            .store = try docstore_mod.DocStore.open(alloc, zpath, .{
                .map_size = lmdb_opts.map_size,
                .no_sync = lmdb_opts.no_sync,
                .read_only = lmdb_opts.read_only,
            }),
        },
        .mem => |mem_opts| mem_blk: {
            const backend = try alloc.create(mem_backend_mod.Backend);
            errdefer alloc.destroy(backend);
            backend.* = mem_backend_mod.Backend.init(alloc, mem_opts);
            errdefer backend.close();

            var runtime_store = try backend.runtimeStore(alloc, .{ .name = "docs" });
            errdefer runtime_store.deinit();

            break :mem_blk .{
                .store = try docstore_mod.DocStore.openRuntime(alloc, runtime_store),
                .owner = .{ .mem = backend },
            };
        },
        .lsm_memory => |lsm_opts| lsm_mem_blk: {
            var handle = try lsm_backend_mod.BackendHandle.init(alloc, lsm_opts);
            errdefer handle.close();

            var runtime_store = try handle.backend.runtimeStore(alloc, .{ .name = "docs" });
            errdefer runtime_store.deinit();

            break :lsm_mem_blk .{
                .store = try docstore_mod.DocStore.openRuntime(alloc, runtime_store),
                .owner = .{ .lsm = .{
                    .handle = handle,
                    .split_options = null,
                } },
            };
        },
        .lsm => |lsm_opts| lsm_blk: {
            var handle = try lsm_backend_mod.BackendHandle.open(alloc, path, lsm_opts);
            errdefer handle.close();

            var runtime_store = try handle.backend.runtimeStore(alloc, .{ .name = "docs" });
            errdefer runtime_store.deinit();

            break :lsm_blk .{
                .store = try docstore_mod.DocStore.openRuntime(alloc, runtime_store),
                .owner = .{ .lsm = .{
                    .handle = handle,
                    .split_options = db_config.splitLsmOptions(opts.primary_backend, opts.storage, opts.lsm_cache),
                } },
            };
        },
    };
}

const ShadowState = struct {
    manager: *index_manager_mod.IndexManager,
    base_path: []u8,
    indexes_path: []u8,
    range_start: []u8,
    range_end: []u8,
};

pub const DB = struct {
    closed: bool = false,
    alloc: Allocator,
    runtime_alloc: Allocator,
    generation_read_lease: ?generation_lifecycle.ReadLease,
    open_mode: OpenOptions.OpenMode,
    primary_backend: PrimaryBackend,
    primary_lsm_storage: ?lsm_backend_mod.Storage,
    index_backends: db_config.IndexBackendOptions,
    core: db_core.DBCore,
    /// Durable identity of the physical DB root. Unlike `core.root_generation`,
    /// this survives process restart and changes whenever a root is rebound.
    root_incarnation: u128 = 0,
    async_context: *AsyncContext,
    backend_runtime: *background_runtime_mod.BackendRuntime,
    backend_owner_id: u64,
    repair_cleanup_owner_id: u64,
    algebraic_hll_owner_id: u64 = 0,
    owned_backend_runtime: ?background_runtime_mod.BackendRuntimeHandle,
    owned_resource_manager: ?*resource_manager_mod.ResourceManager,
    capacity_source: ?types.RepairCapacitySource,
    executor: *derived_executor_mod.Executor,
    start_index_workers: bool,
    optional_runtime_workers_enabled: bool,
    secret_store: ?*common_secrets.FileStore,
    remote_content: ?*const scraping.RemoteContentConfig,
    enrichment_append_context: ?*EnrichmentAppendContext,
    enrichment_runtime: ?*enrichment_runtime_mod.EnrichmentRuntime,
    resolution_append_context: ?*EnrichmentAppendContext = null,
    resolution_runtime: ?*resolution_runtime_mod.ResolutionRuntime = null,
    resolution_candidate_source: ?resolution_runtime_mod.CandidateSource = null,
    resolution_embedder: ?embedder_mod.DenseEmbedder = null,
    promotion_runtime: ?*promotion_runtime_mod.PromotionRuntime = null,
    entity_sink: ?promotion_runtime_mod.EntitySink = null,
    promotion_owner: ?promotion_runtime_mod.PromotionOwner = null,
    entity_sink_missing_policy: promotion_runtime_mod.MissingSinkPolicy = .wait,
    ha_async_effect_mirror: ?HAAsyncEffectMirror = null,
    ha_async_batch_mirror: ?HAAsyncBatchMirror = null,
    ha_async_metadata_mirror: ?HAAsyncMetadataMirror = null,
    ha_write_gate: ?HAWriteGate = null,
    ttl_cleanup_context: ?*TtlCleanupContext,
    ttl_runtime: ?*ttl_runtime_mod.TtlRuntime,
    transaction_recovery_identity_context: ?*db_core.TransactionRecoveryIdentityContext,
    transaction_runtime: ?*transaction_runtime_mod.Runtime,
    text_merge_runtime: ?*text_merge_runtime_mod.TextMergeRuntime,
    sparse_compaction_runtime: ?*sparse_compaction_runtime_mod.SparseCompactionRuntime,
    // Background retry of quarantined index loads (see retryQuarantinedIndexLoads).
    // Spawned at open only when the load left failures behind; exits once all
    // quarantined indexes recover or the DB closes.
    quarantine_retry_thread: ?std.Thread = null,
    quarantine_retry_stop: std.atomic.Value(bool) = std.atomic.Value(bool).init(false),
    artifact_repair_metadata_future: ?Io.Future(void) = null,
    artifact_repair_metadata_stop: std.atomic.Value(bool) = std.atomic.Value(bool).init(false),
    shadow: ?ShadowState,
    bulk_ingest_coalescer: @This().BulkIngestCoalescer = .{},
    flushing_bulk_ingest_coalescer: bool = false,
    bulk_ingest_identity_all_new: bool = false,
    bulk_ingest_identity_state: doc_identity.AllNewTrustedState = .{},
    identity_visibility_summary_cache: ?doc_identity.VisibilitySummary = null,
    // Memoizes the resolved live-doc set for broad (.all) live filtering at a
    // single identity read generation. Visibility at a fixed generation is
    // stable, so the entry only turns over when queries arrive at a newer
    // generation. Guarded by its own mutex because published-path queries do
    // not hold the apply lock.
    live_doc_set_cache_mutex: std.atomic.Mutex = .unlocked,
    live_doc_set_cache_generation: ?u64 = null,
    live_doc_set_cache_set: ?doc_set.ResolvedDocSet = null,
    nonvisible_doc_set_cache_mutex: std.atomic.Mutex = .unlocked,
    nonvisible_doc_set_cache_generation: ?u64 = null,
    nonvisible_doc_set_cache_set: ?doc_set.ResolvedDocSet = null,
    nonvisible_doc_set_cache_overflow: bool = false,
    nonvisible_doc_set_cache_entries: AtomicU64 = AtomicU64.init(0),
    bulk_ingest_seen_doc_keys: std.StringHashMapUnmanaged(void) = .{},
    doc_set_planning_stats: DocSetPlanningRuntimeStats = .{},
    visibility_runtime_stats: VisibilityRuntimeStats = .{},
    /// High bit closes lock-free dense admission; the remaining bits count
    /// readers that hold an inline-catalog generation alive. Keeping both in
    /// one atomic gives reader admission and catalog closure a single
    /// modification order on weak-memory targets.
    published_dense_admission: std.atomic.Value(u32) = .init(0),
    // Managed admission is a durable outbox. Requested/completed generations
    // prevent a drain from erasing work committed while its marker snapshot is
    // in flight; the mutex makes concurrent drainers a single-flight loop.
    managed_admission_materialization_requested: std.atomic.Value(u64) = .init(0),
    managed_admission_materialization_completed: std.atomic.Value(u64) = .init(0),
    managed_admission_materialization_mutex: std.atomic.Mutex = .unlocked,
    index_structural_mutation_mutex: std.atomic.Mutex = .unlocked,
    index_repair_mutex: std.atomic.Mutex = .unlocked,
    generation_replace_mutex: std.atomic.Mutex = .unlocked,
    active_index_repairs: std.StringHashMapUnmanaged(bool) = .{},
    shadow_index_repair_hook: ?@This().ShadowIndexRepairHook = null,

    const engine_vtable = db_core.Engine.VTable{
        .batch = engineBatch,
        .lookup = engineLookup,
        .scan = engineScan,
        .search = engineSearch,
        .stats = engineStats,
        .list_indexes = engineListIndexes,
        .list_enrichments = engineListEnrichments,
    };

    pub const ShadowIndexRepairHook = struct {
        ptr: *anyopaque,
        after_snapshot_build: *const fn (ptr: *anyopaque, db: *DB, index_name: []const u8, build_floor_sequence: u64) anyerror!void,
        after_pointer_activation: ?*const fn (ptr: *anyopaque, db: *DB, index_name: []const u8) anyerror!void = null,
        after_clean_checkpoint: ?*const fn (ptr: *anyopaque, db: *DB, index_name: []const u8) anyerror!void = null,
        after_phase_persisted: ?*const fn (
            ptr: *anyopaque,
            db: *DB,
            repair_id: u128,
            phase: index_repair_state.Phase,
        ) anyerror!void = null,
    };

    fn batchContext(self: *DB) BatchExecutionContext {
        const resources = self.core.batchExecutionResources();
        return .{
            .alloc = self.alloc,
            .store = resources.store,
            .applied_sequence_checkpoint_path = resources.applied_sequence_checkpoint_path,
            .index_repair_checkpoint = resources.index_repair_checkpoint,
            .shard_manager = resources.shard_manager,
            .change_journal = resources.change_journal,
            .replay_source = resources.replay_source,
            .index_manager = resources.index_manager,
            .apply_mutex = resources.apply_mutex,
            .repair_replay_mutex = resources.repair_replay_mutex,
            .log_mutex = resources.log_mutex,
            .identity_namespace = resources.identity_namespace,
            .artifact_cleanup_maybe = resources.artifact_cleanup_maybe,
            .executor = self.executor,
            .io = self.backend_runtime.io(),
            .enrichment_runtime = self.enrichment_runtime,
            .resolution_runtime = self.resolution_runtime,
            .promotion_runtime = self.promotion_runtime,
            .async_context = self.async_context,
            .ha_async_effect_mirror = self.ha_async_effect_mirror,
            .ha_async_batch_mirror = self.ha_async_batch_mirror,
            .ha_async_metadata_mirror = self.ha_async_metadata_mirror,
            .ha_write_gate = self.ha_write_gate,
        };
    }

    fn enforceHAWriteGate(self: *DB) !void {
        try enforceHAWriteGateOptional(self.ha_write_gate);
    }

    fn haMutationBarrier(self: *const DB) ?*HAMutationBarrier {
        var barrier: ?*HAMutationBarrier = null;
        const mirrors = .{
            self.ha_async_effect_mirror,
            self.ha_async_batch_mirror,
            self.ha_async_metadata_mirror,
        };
        inline for (mirrors) |maybe_mirror| {
            if (maybe_mirror) |mirror| {
                if (mirror.mutation_barrier) |candidate| {
                    if (barrier) |configured| {
                        std.debug.assert(configured == candidate);
                    } else {
                        barrier = candidate;
                    }
                }
            }
        }
        return barrier;
    }

    fn acquireHAMutationShared(self: *const DB) ?HAMutationBarrier.SharedLease {
        const barrier = self.haMutationBarrier() orelse return null;
        return barrier.acquireShared();
    }

    fn mirrorHAReplayPayloadBestEffort(self: *DB, payload: []const u8) void {
        var ctx = self.batchContext();
        mirrorHAReplayPayloadBestEffortContext(&ctx, payload);
    }

    fn mirrorHABatchMutationBestEffort(self: *DB, request: types.BatchRequest) void {
        var ctx = self.batchContext();
        mirrorHABatchMutationBestEffortContext(&ctx, request);
    }

    fn mirrorHASchemaMetadataBestEffort(self: *DB, table_schema: schema_mod.TableSchema) void {
        var ctx = self.batchContext();
        mirrorHASchemaMetadataBestEffortContext(&ctx, table_schema);
    }

    fn preflightHABatchSyncCommit(self: *DB) !void {
        var ctx = self.batchContext();
        try preflightHAMirrorSyncCommitContext(&ctx, ctx.ha_async_batch_mirror);
        try preflightHAMirrorSyncCommitContext(&ctx, ctx.ha_async_effect_mirror);
    }

    fn preflightHAMetadataSyncCommit(self: *DB) !void {
        var ctx = self.batchContext();
        try preflightHAMirrorSyncCommitContext(&ctx, ctx.ha_async_metadata_mirror);
    }

    fn mirrorHABatchMutationCommit(self: *DB, request: types.BatchRequest) !void {
        var ctx = self.batchContext();
        try mirrorHABatchMutationCommitContext(&ctx, request);
    }

    fn mirrorHAEncodedBatchMutationCommit(self: *DB, payload: []const u8) !void {
        var ctx = self.batchContext();
        try mirrorHAEncodedBatchMutationCommitContext(&ctx, payload);
    }

    fn mirrorHAReplayPayloadCommit(self: *DB, payload: []const u8) !void {
        var ctx = self.batchContext();
        try mirrorHAReplayPayloadCommitContext(&ctx, payload);
    }

    fn flushTransactionHAOutbox(self: *DB, txn_id: transactions_mod.TxnId) !void {
        var outbox = try self.core.loadTransactionHAOutbox(self.alloc, txn_id);
        defer outbox.deinit(self.alloc);
        if (outbox.batch_payload == null and outbox.replay_payload == null) return;

        // An outbox entry is a durable synchronous-replication obligation. Do
        // not silently discard it if a restart temporarily removes or
        // downgrades the corresponding mirror configuration.
        if (outbox.batch_payload != null) {
            const mirror = self.ha_async_batch_mirror orelse return error.HAMirrorUnavailable;
            if (!haMirrorSyncEnabled(mirror)) return error.HAMirrorUnavailable;
        }
        if (outbox.replay_payload != null) {
            const mirror = self.ha_async_effect_mirror orelse return error.HAMirrorUnavailable;
            if (!haMirrorSyncEnabled(mirror)) return error.HAMirrorUnavailable;
        }
        try self.enforceHAWriteGate();
        var ctx = self.batchContext();
        if (outbox.batch_payload != null) try preflightHAMirrorSyncCommitContext(&ctx, ctx.ha_async_batch_mirror);
        if (outbox.replay_payload != null) try preflightHAMirrorSyncCommitContext(&ctx, ctx.ha_async_effect_mirror);

        if (outbox.batch_payload) |payload| {
            try self.mirrorHAEncodedBatchMutationCommit(payload);
            lockApply(self);
            defer self.core.unlockApply();
            try self.core.clearTransactionHAOutbox(txn_id, .batch);
        }
        if (outbox.replay_payload) |payload| {
            try self.mirrorHAReplayPayloadCommit(payload);
            lockApply(self);
            defer self.core.unlockApply();
            try self.core.clearTransactionHAOutbox(txn_id, .replay);
        }
    }

    fn mirrorHASchemaMetadataCommit(self: *DB, table_schema: schema_mod.TableSchema) !void {
        var ctx = self.batchContext();
        try mirrorHASchemaMetadataCommitContext(&ctx, table_schema);
    }

    fn attachAlgebraicHllMaintenanceLane(self: *DB) !void {
        const owner_id = try self.backend_runtime.allocOwnerId();
        self.algebraic_hll_owner_id = owner_id;
        self.core.index_manager.attachHllMaintenance(self.backend_runtime.durable_jobs, owner_id);
    }

    fn hydrateAlgebraicObservationStatusBestEffort(self: *DB) void {
        for (self.core.index_manager.algebraic_indexes.items) |*entry| {
            entry.index.loadPersistedObservations(self.core.store) catch {};
        }
    }

    fn hydrateAlgebraicObservationStatusForIndexBestEffort(self: *DB, index_name: []const u8) void {
        const entry = self.core.index_manager.algebraicIndex(index_name) orelse return;
        entry.index.loadPersistedObservations(self.core.store) catch {};
    }

    const maintenance_driver_vtable = db_core.MaintenanceDriver.VTable{
        .pending_work_stats = maintenanceDriverPendingWorkStats,
        .run_derived_until = maintenanceDriverRunDerivedUntil,
        .run_enrichment_until = maintenanceDriverRunEnrichmentUntil,
        .run_maintenance_until = maintenanceDriverRunMaintenanceUntil,
        .run_until_idle = maintenanceDriverRunUntilIdle,
    };

    pub fn open(alloc: Allocator, path: []const u8, requested_opts: OpenOptions) !DB {
        return blk: {
            var opts = requested_opts;
            // Provider interfaces are move-only. Keep them in the mutable
            // options until a runtime has adopted them so partial opens have
            // exactly one cleanup owner.
            errdefer if (opts.enrichment) |*cfg| deinitOwnedEnrichmentConfig(alloc, cfg);
            if (opts.backend_runtime) |runtime| {
                if (runtime.db_open_configurator) |configurator| {
                    try configurator.configure(path, &opts);
                }
            }
            var generation_read_lease = if (opts.staged_generation) |staged_generation| staged_blk: {
                try staged_generation.validatePath(path);
                break :staged_blk null;
            } else if (opts.physical_root_mode == .external_backend)
                null
            else
                try generation_lifecycle.acquirePublishedGenerationReadWithRuntime(alloc, path, opts.backend_runtime);
            errdefer if (generation_read_lease) |*lease| lease.deinit();
            const open_started_ns = monotonicTimeNs();
            const ha_write_gate = if (opts.ha_write_gate) |gate| gate.pinned() else null;
            var profile = OpenProfile{};
            const runtime_alloc = backgroundRuntimeAllocator(alloc);
            var owned_resource_manager: ?*resource_manager_mod.ResourceManager = null;
            const bind_cache_resource_manager = opts.resource_manager != null;
            if (opts.resource_manager == null) {
                const manager = try alloc.create(resource_manager_mod.ResourceManager);
                manager.* = resource_manager_mod.ResourceManager.init(standaloneResourceManagerOptions(alloc));
                owned_resource_manager = manager;
                opts.resource_manager = manager;
            }
            errdefer if (owned_resource_manager) |manager| {
                manager.deinit(alloc);
                alloc.destroy(manager);
            };
            var owned_async_context: ?*AsyncContext = null;
            var owned_backend_runtime: ?background_runtime_mod.BackendRuntimeHandle = null;
            var owned_executor: ?*derived_executor_mod.Executor = null;
            errdefer {
                if (owned_executor) |ptr| runtime_alloc.destroy(ptr);
                if (owned_backend_runtime) |*handle| handle.deinit();
                if (owned_async_context) |ptr| runtime_alloc.destroy(ptr);
            }
            const backend_runtime = opts.backend_runtime orelse blk_runtime: {
                owned_backend_runtime = try background_runtime_mod.BackendRuntimeHandle.init(runtime_alloc, .{
                    .backend = opts.executor.backend,
                });
                break :blk_runtime owned_backend_runtime.?.runtime;
            };
            var effective_executor = opts.executor;
            if (backend_runtime.io_impl == null and effective_executor.backend == .io_threaded) {
                effective_executor.backend = .manual;
            }
            const backend_owner_id = try backend_runtime.allocOwnerId();
            var backend_owner_transferred = false;
            errdefer if (!backend_owner_transferred)
                backend_runtime.durable_jobs.closeOwner(backend_owner_id);
            const repair_cleanup_owner_id = try backend_runtime.allocOwnerId();
            var repair_cleanup_owner_transferred = false;
            errdefer if (!repair_cleanup_owner_transferred)
                backend_runtime.durable_jobs.closeOwner(repair_cleanup_owner_id);
            var primary_lsm_background_executor: lsm_backend_mod.BackgroundExecutor = undefined;
            var effective_primary_backend = opts.primary_backend;
            var effective_index_backends = opts.index_backends;
            if (openModeRequiresReadOnlyBackends(opts.open_mode)) {
                applyReadOnlyToPrimaryBackend(&effective_primary_backend);
                applyReadOnlyToIndexBackends(&effective_index_backends);
            }
            switch (effective_primary_backend) {
                .lsm => |*lsm_opts| {
                    lsm_opts.cache = opts.lsm_cache orelse lsm_opts.cache;
                    lsm_opts.root_generation = opts.lsm_root_generation;
                    installLsmReadRuntime(lsm_opts, backend_runtime);
                    primary_lsm_background_executor = makeLsmBackgroundExecutor(backend_runtime, backend_owner_id);
                    lsm_opts.background_executor = &primary_lsm_background_executor;
                },
                .lsm_memory => |*lsm_opts| {
                    lsm_opts.cache = opts.lsm_cache orelse lsm_opts.cache;
                    lsm_opts.root_generation = opts.lsm_root_generation;
                    installLsmReadRuntime(lsm_opts, backend_runtime);
                    primary_lsm_background_executor = makeLsmBackgroundExecutor(backend_runtime, backend_owner_id);
                    lsm_opts.background_executor = &primary_lsm_background_executor;
                },
                .lmdb, .mem => {},
            }
            installIndexLsmReadRuntime(&effective_index_backends, backend_runtime);
            const core_opts: db_config.CoreOpenOptions = .{
                .map_size = opts.map_size,
                .no_sync = opts.no_sync,
                .read_only = openModeRequiresReadOnlyBackends(opts.open_mode),
                .primary_backend = effective_primary_backend,
                .primary_runtime_store = opts.primary_runtime_store,
                .storage = opts.storage,
                .lsm_cache = opts.lsm_cache,
                .hbc_cache = opts.hbc_cache,
                .lsm_root_generation = opts.lsm_root_generation,
                .resource_manager = opts.resource_manager,
                .bind_cache_resource_manager = bind_cache_resource_manager,
                .index_backends = effective_index_backends,
            };
            const resolved_config = db_config.ResolvedOpenConfig.init(
                effective_primary_backend,
                opts.storage,
                opts.lsm_cache,
                opts.hbc_cache,
                opts.lsm_root_generation,
                opts.resource_manager,
                bind_cache_resource_manager,
                effective_index_backends,
            );
            const open_primary_started_ns = monotonicTimeNs();
            const opened_primary = try openPrimaryStore(alloc, path, core_opts);
            profile.primary_store_ns = elapsedSince(open_primary_started_ns);
            const core_resources_started_ns = monotonicTimeNs();
            const core = try db_core.openCoreResourcesFromPrimaryStore(
                alloc,
                path,
                opts.index_base_path orelse path,
                opts.map_size,
                opts.no_sync,
                resolved_config.primary_backend_kind,
                resolved_config.primary_lsm_storage,
                opts.change_journal_backend,
                opts.change_journal_storage,
                resolved_config.index_backends,
                opened_primary,
                opts.identity_namespace,
                false,
                if (opts.prefer_existing_identity_namespace) .use_existing else .reject,
                opts.external_derived_checkpoints,
                opts.index_repair_checkpoint_storage,
                opts.lsm_root_generation,
                openModeRequiresReadOnlyBackends(opts.open_mode),
            );
            profile.core_resources_ns = elapsedSince(core_resources_started_ns);
            const async_context = try runtime_alloc.create(AsyncContext);
            owned_async_context = async_context;
            const executor = try runtime_alloc.create(derived_executor_mod.Executor);
            owned_executor = executor;
            var stored_primary_backend = effective_primary_backend;
            switch (stored_primary_backend) {
                .lsm => |*lsm_opts| lsm_opts.background_executor = null,
                .lsm_memory => |*lsm_opts| lsm_opts.background_executor = null,
                .lmdb, .mem => {},
            }
            const ha_standby_role = haWriteGateIsStandby(ha_write_gate);
            const start_index_workers = opts.open_mode.allowsIndexWorkers() and opts.start_index_workers and !ha_standby_role;

            var db = DB{
                .alloc = alloc,
                .runtime_alloc = runtime_alloc,
                .generation_read_lease = generation_read_lease,
                .open_mode = opts.open_mode,
                .primary_backend = stored_primary_backend,
                .primary_lsm_storage = resolved_config.primary_lsm_storage,
                .index_backends = resolved_config.index_backends,
                .core = db_core.DBCore.fromOpened(alloc, core),
                .async_context = async_context,
                .backend_runtime = backend_runtime,
                .backend_owner_id = backend_owner_id,
                .repair_cleanup_owner_id = repair_cleanup_owner_id,
                .owned_backend_runtime = owned_backend_runtime,
                .owned_resource_manager = owned_resource_manager,
                .capacity_source = opts.capacity_source orelse opts.resource_manager.?.capacitySource(),
                .executor = executor,
                .start_index_workers = start_index_workers,
                .optional_runtime_workers_enabled = false,
                .secret_store = opts.secret_store,
                .remote_content = opts.remote_content,
                .enrichment_append_context = null,
                .enrichment_runtime = null,
                .resolution_candidate_source = opts.resolution_candidate_source,
                .resolution_embedder = opts.resolution_embedder,
                .entity_sink = opts.entity_sink,
                .promotion_owner = opts.promotion_owner,
                .entity_sink_missing_policy = opts.entity_sink_missing_policy,
                .ha_async_effect_mirror = opts.ha_async_effect_mirror,
                .ha_async_batch_mirror = opts.ha_async_batch_mirror,
                .ha_async_metadata_mirror = opts.ha_async_metadata_mirror,
                .ha_write_gate = ha_write_gate,
                .ttl_cleanup_context = null,
                .ttl_runtime = null,
                .transaction_recovery_identity_context = null,
                .transaction_runtime = null,
                .text_merge_runtime = null,
                .sparse_compaction_runtime = null,
                .shadow = null,
            };
            backend_owner_transferred = true;
            repair_cleanup_owner_transferred = true;
            var executor_ready = false;
            owned_async_context = null;
            owned_backend_runtime = null;
            owned_resource_manager = null;
            owned_executor = null;
            generation_read_lease = null;
            errdefer db.deinitWrapperState(executor_ready);
            db.core.index_manager.setIo(db.backend_runtime.io());
            db.core.setIndexOpenParallelism(opts.index_open_parallelism);
            const init_async_started_ns = monotonicTimeNs();
            try db.initAsyncInfrastructure(effective_executor, opts.resource_manager);
            profile.init_async_infrastructure_ns = elapsedSince(init_async_started_ns);
            executor_ready = true;
            if (!openModeRequiresReadOnlyBackends(opts.open_mode) and
                opts.physical_root_mode == .filesystem_managed)
            {
                const identity = try loadOrCreateDurableRootIdentity(alloc, db.backend_runtime, path);
                db.root_incarnation = identity.incarnation;
            }
            if (opts.schema_before_index_load) |table_schema| {
                // This option is used by the metadata-authoritative local
                // provisioner. Persist directly through the core before index
                // open; no index runtime exists yet and the metadata record is
                // already the durable authority for this replica projection.
                try db.core.setSchema(table_schema);
            }
            const optional_runtimes_initialized = opts.open_mode.allowsOptionalRuntimes() and opts.start_optional_runtimes and !ha_standby_role;
            const optional_runtime_workers_enabled = optional_runtimes_initialized and opts.start_optional_runtime_workers;
            db.optional_runtime_workers_enabled = optional_runtime_workers_enabled;
            if (optional_runtimes_initialized) {
                const init_optional_started_ns = monotonicTimeNs();
                try db.initOptionalRuntimes(&opts);
                profile.init_optional_runtimes_ns = elapsedSince(init_optional_started_ns);
            } else if (opts.enrichment) |*cfg| {
                // Read-only/status and standby opens never construct an
                // enrichment runtime, but the open contract still owns the
                // moved providers.
                deinitOwnedEnrichmentConfig(alloc, cfg);
                opts.enrichment = null;
            }

            try db.attachAlgebraicHllMaintenanceLane();

            const admission_prefix = try internal_keys.managedIndexAdmissionRootPrefixAlloc(alloc);
            defer alloc.free(admission_prefix);
            const managed_admissions = try db.core.store.scanPrefix(alloc, admission_prefix);
            defer docstore_mod.DocStore.freeResults(alloc, managed_admissions);
            try db.core.index_manager.replaceManagedAdmissionSnapshot(managed_admissions);
            if (managed_admissions.len != 0 and !openModeRequiresReadOnlyBackends(opts.open_mode)) {
                db.requestManagedAdmissionMaterialization();
            }

            if (opts.open_mode == .status_only) {
                try db.core.loadIndexCatalogOnly();
            } else if (opts.open_mode == .query_readonly) {
                const load_indexes_started_ns = monotonicTimeNs();
                try db.core.loadIndexesNoBackfill();
                profile.load_indexes_ns = elapsedSince(load_indexes_started_ns);
            } else {
                const load_indexes_started_ns = monotonicTimeNs();
                try db.core.loadIndexes();
                profile.load_indexes_ns = elapsedSince(load_indexes_started_ns);
            }
            if (!openModeRequiresReadOnlyBackends(opts.open_mode)) {
                // Catalog admission and its outbox are one primary-store
                // commit. Materialize any crash-surviving outbox before replay
                // or workers can observe the newly loaded generation.
                try db.drainManagedIndexAdmissions(alloc);
                var repair_state: ?index_repair_state.State = db.loadOrCreateCurrentIndexRepairState(alloc) catch |err| switch (err) {
                    error.DurableIndexRepairStateUnavailable => null,
                    error.InvalidIndexRepairState => invalid_state_blk: {
                        // Preserve primary availability, but fail every derived
                        // index closed and retain the complete replay journal.
                        // Without a trustworthy intent/pin checkpoint no
                        // projection may prove serviceability or authorize
                        // truncation.
                        db.async_context.index_repair_state_corrupt.store(true, .release);
                        db.async_context.index_repair_replay_pinned.store(true, .release);
                        break :invalid_state_blk null;
                    },
                    else => return err,
                };
                if (repair_state) |*state| {
                    state.deinit(alloc);
                    repair_state = null;
                    try db.removeOrphanedIndexRepairIntents(alloc);
                    repair_state = db.loadIndexRepairState(alloc) catch |err| switch (err) {
                        error.FileNotFound => null,
                        else => return err,
                    };
                }
                if (repair_state) |*state| {
                    for (state.entries.items) |entry| {
                        if (entry.intent.phase != .terminal and entry.intent.automation == .enabled) {
                            db.async_context.index_repair_notification_pending = true;
                            break;
                        }
                    }
                    db.async_context.index_repair_replay_pinned.store(state.minimumRetainAfterSequence() != null, .release);
                    state.deinit(alloc);
                }
            }
            // The primary-store marker is the admission authority. Install its
            // gate in every mode before consulting the materialized checkpoint so
            // a crash between those two writes cannot expose an empty index.
            try db.core.index_manager.markManagedAdmissionsUnavailable();
            try db.refreshIndexRepairAvailabilityGate(alloc);
            if (opts.open_mode != .status_only) {
                db.hydrateAlgebraicObservationStatusBestEffort();
            }
            if (!openModeRequiresReadOnlyBackends(opts.open_mode)) {
                // A pending intent may still need both its candidate and the
                // previously active generation for rollback. Orphan cleanup
                // is safe only after durable repair debt is absent; malformed
                // state also fails closed and retains every possible anchor.
                const has_durable_repair_debt = db.hasPendingIndexRepairIntents(alloc) catch true;
                if (!has_durable_repair_debt) db.scheduleInactiveRepairShadowCleanup();
            }
            if (opts.open_mode != .status_only) {
                try db.rebaseManagedIndexAppliedSequencesIfNeeded();
            }
            if (!openModeRequiresReadOnlyBackends(opts.open_mode)) {
                _ = try db.rebuildArtifactRepairSummaryIfMissing(alloc);
                _ = try db.rebuildArtifactRepairKindIndexIfMissing(alloc);
                try db.persistIndexLoadFailuresFromManager(alloc);
            }
            db.recordStartupOpenStats(profile);
            if (opts.open_mode.allowsReplay()) {
                const replay_started_ns = monotonicTimeNs();
                replayPendingDerivedBatches(&db, null, null, .{}) catch |err| switch (err) {
                    error.ArtifactRepairRequired => {},
                    else => return err,
                };
                profile.replay_pending_derived_ns = elapsedSince(replay_started_ns);
            }
            if (optional_runtime_workers_enabled) {
                try db.resumeGeneratedReplayFromJournalIfNeeded();
            }
            if (db.start_index_workers) {
                const start_workers_started_ns = monotonicTimeNs();
                try startAsyncWorkers(&db);
                if (opts.open_mode.allowsReplay()) {
                    db.resumeAsyncReplayFromJournalIfNeeded();
                }
                profile.start_index_workers_ns = elapsedSince(start_workers_started_ns);
            }
            if (optional_runtime_workers_enabled) {
                const start_optional_started_ns = monotonicTimeNs();
                try db.startOptionalRuntimes();
                profile.start_optional_runtimes_ns = elapsedSince(start_optional_started_ns);
            }
            if (optional_runtime_workers_enabled and opts.open_mode == .writer) {
                db.startQuarantineRetryWorkerIfNeeded();
            }
            if (!openModeRequiresReadOnlyBackends(opts.open_mode)) {
                // Cleanup jobs can call back into repair/coverage state. Submit
                // them only after startup replay and optional runtimes have
                // completed initialization, so open remains single-threaded.
                db.scheduleGeneratedArtifactCleanup();
            }
            profile.total_ns = monotonicTimeNs() - open_started_ns;
            if (openProfileEnabled()) {
                logOpenProfile(path, opts.open_mode, db.start_index_workers, profile);
            }
            break :blk db;
        };
    }

    pub fn close(self: *DB) void {
        if (self.closed) return;
        self.closed = true;
        self.deinitWrapperState(true);
    }

    pub fn isClosed(self: *const DB) bool {
        return self.closed;
    }

    fn resumeGeneratedReplayFromJournalIfNeeded(self: *DB) !void {
        const runtime = self.enrichment_runtime orelse return;
        if (!self.core.hasGeneratedEnrichmentTargets()) return;

        const target_sequence = self.core.nextEnrichmentSequence();
        if (target_sequence == 0) return;
        runtime.resumeTargetPreservingRetryDebt(target_sequence);
    }

    fn resumeAsyncReplayFromJournalIfNeeded(self: *DB) void {
        const target_sequence = self.core.nextDerivedSequence();
        if (target_sequence == 0) return;
        self.executor.notifySequence(target_sequence);
    }

    pub fn maintenanceDriver(self: *DB) db_core.MaintenanceDriver {
        return .{
            .ptr = self,
            .vtable = &maintenance_driver_vtable,
        };
    }

    pub fn engine(self: *DB) db_core.Engine {
        return .{
            .ptr = self,
            .vtable = &engine_vtable,
        };
    }

    pub fn services(self: *DB) db_core.Services {
        return self.core.services(self.engine(), self.maintenanceDriver());
    }

    fn initAsyncInfrastructure(
        self: *DB,
        executor_config: derived_executor_mod.Config,
        resource_manager: ?*resource_manager_mod.ResourceManager,
    ) !void {
        const async_resources = self.core.asyncResources();
        self.async_context.* = .{
            .alloc = self.runtime_alloc,
            .resource_manager = resource_manager,
            .store = async_resources.store,
            .applied_sequence_checkpoint_path = async_resources.applied_sequence_checkpoint_path,
            .index_repair_checkpoint = async_resources.index_repair_checkpoint,
            .index_manager = async_resources.index_manager,
            .apply_mutex = async_resources.apply_mutex,
            .repair_replay_mutex = async_resources.repair_replay_mutex,
            .io = self.backend_runtime.io(),
            .require_graph_resolution_contract = true,
            .query_visibility_hook = null,
            .text_merge_runtime = null,
        };
        self.executor.* = try derived_executor_mod.init(
            self.runtime_alloc,
            executor_config,
            self.core.replaySource(),
            self.async_context,
            applyDerivedBatchToIndexAsync,
            persistAppliedSequenceAsync,
            truncateReplaySequenceAsync,
            beginDerivedCatchUpSessionAsync,
            finishDerivedCatchUpSessionAsync,
            canAdvanceDerivedToTargetAsync,
            notifyDerivedAppliedSequenceAdvanced,
            resource_manager,
            self.backend_runtime,
        );
    }

    pub fn setQueryVisibilityHook(self: *DB, hook: ?QueryVisibilityHook) void {
        if (hook != null) self.bindTtlIdentityVisibilityOwner();
        var pending_hook: ?QueryVisibilityHook = null;
        lockAtomic(&self.async_context.query_visibility_hook_mutex);
        self.async_context.query_visibility_hook = hook;
        if (hook) |attached| {
            if (self.async_context.index_repair_notification_pending) {
                self.async_context.index_repair_notification_pending = false;
                _ = self.async_context.query_visibility_hook_in_flight.fetchAdd(1, .acquire);
                pending_hook = attached;
            }
        }
        self.async_context.query_visibility_hook_mutex.unlock();
        if (pending_hook) |attached| {
            attached.notify(.index_repair_pending);
            _ = self.async_context.query_visibility_hook_in_flight.fetchSub(1, .release);
        }
        if (hook == null) {
            // A notifier copies the hook before invoking it so the callback may
            // inspect the DB without holding this mutex. Detachment is also a
            // teardown barrier: once it returns, no callback can still inspect
            // optional runtimes or index state that close is about to destroy.
            while (self.async_context.query_visibility_hook_in_flight.load(.acquire) != 0) {
                spinOrYield();
            }
        }
        if (self.enrichment_runtime) |runtime| {
            runtime.setStatusHook(if (hook == null) null else .{
                .ptr = self.async_context,
                .on_change = notifyAsyncContextVisibilityHook,
            });
        }
    }

    fn bindTtlIdentityVisibilityOwner(self: *DB) void {
        const ttl_ctx = self.ttl_cleanup_context orelse return;
        ttl_ctx.identity_visibility_owner.store(self, .release);

        // DB.open returns the wrapper by value, so optional runtimes are
        // initialized before a managed writer reaches its stable cache
        // address. Refresh any TTL mutation that may have landed during that
        // move window when the serving layer attaches its visibility hook.
        lockApply(self);
        defer self.core.unlockApply();
        if (doc_identity.visibilitySummaryFromStore(self.core.store) catch null) |summary| {
            self.identity_visibility_summary_cache = summary;
            self.clearLiveDocSetCache();
            self.clearNonVisibleDocSetCache();
        }
    }

    fn notifyAsyncContextVisibilityHook(ptr: *anyopaque) void {
        const ctx: *AsyncContext = @ptrCast(@alignCast(ptr));
        notifyQueryVisibilityHook(ctx, .status);
    }

    fn notifyDerivedAppliedSequenceAdvanced(ptr: *anyopaque, index_name: []const u8, _: u64) void {
        const ctx: *AsyncContext = @ptrCast(@alignCast(ptr));
        // The executor invokes this only after persistence, publishing its live
        // applied watermark, and releasing its mutex. Dense lifecycle status
        // must be captured at this post-watermark boundary: the preceding
        // persistence callback cannot yet observe the new live sequence, and a
        // best-effort follow-up may lose the only completion edge to a writer.
        // Provisioned runtimes translate this edge into an owner-thread
        // publication; no DB apply or applied-sequence lock is held while the
        // notification is delivered. Other index kinds retain the cheaper
        // overlay path.
        notifyQueryVisibilityHook(
            ctx,
            if (ctx.index_manager.denseProjectionCheckpointMetadata(index_name) != null)
                .publish_blocking
            else
                .status,
        );
    }

    fn hasQueryVisibilityHook(ctx: *AsyncContext) bool {
        lockAtomic(&ctx.query_visibility_hook_mutex);
        defer ctx.query_visibility_hook_mutex.unlock();
        return ctx.query_visibility_hook != null;
    }

    fn notifyQueryVisibilityHook(ctx: *AsyncContext, change: QueryVisibilityChange) void {
        lockAtomic(&ctx.query_visibility_hook_mutex);
        const hook = ctx.query_visibility_hook orelse {
            switch (change) {
                .index_repair_pending => ctx.index_repair_notification_pending = true,
                else => {},
            }
            ctx.query_visibility_hook_mutex.unlock();
            return;
        };
        if (change == .index_repair_pending or change == .index_repair_cleared) {
            ctx.index_repair_notification_pending = false;
        }
        _ = ctx.query_visibility_hook_in_flight.fetchAdd(1, .acquire);
        ctx.query_visibility_hook_mutex.unlock();
        defer _ = ctx.query_visibility_hook_in_flight.fetchSub(1, .release);
        hook.notify(change);
    }

    const DetachedEnrichmentRuntime = struct {
        append_ctx: ?*EnrichmentAppendContext = null,
        runtime: ?*enrichment_runtime_mod.EnrichmentRuntime = null,

        fn deinit(self: *@This(), alloc: Allocator) void {
            if (self.runtime) |runtime| {
                runtime.deinit();
                alloc.destroy(runtime);
                self.runtime = null;
            }
            if (self.append_ctx) |ctx| {
                alloc.destroy(ctx);
                self.append_ctx = null;
            }
        }

        fn take(self: *@This()) struct {
            append_ctx: *EnrichmentAppendContext,
            runtime: *enrichment_runtime_mod.EnrichmentRuntime,
        } {
            const append_ctx = self.append_ctx.?;
            const runtime = self.runtime.?;
            self.append_ctx = null;
            self.runtime = null;
            return .{
                .append_ctx = append_ctx,
                .runtime = runtime,
            };
        }
    };

    fn createDetachedEnrichmentRuntime(self: *DB, enrichment_cfg: enrichment_runtime_mod.Config) !?DetachedEnrichmentRuntime {
        if (enrichment_cfg.dense_embedder == null and enrichment_cfg.sparse_embedder == null and enrichment_cfg.asset_producer == null and !enrichment_cfg.enable_without_producers) return null;

        const append_ctx = try self.runtime_alloc.create(EnrichmentAppendContext);
        errdefer self.runtime_alloc.destroy(append_ctx);
        const resources = self.core.batchExecutionResources();
        append_ctx.* = .{
            .alloc = self.runtime_alloc,
            .store = resources.store,
            .applied_sequence_checkpoint_path = resources.applied_sequence_checkpoint_path,
            .index_repair_checkpoint = resources.index_repair_checkpoint,
            .shard_manager = resources.shard_manager,
            .index_manager = resources.index_manager,
            .apply_mutex = resources.apply_mutex,
            .repair_replay_mutex = resources.repair_replay_mutex,
            .change_journal = resources.change_journal,
            .replay_source = resources.replay_source,
            .executor = self.executor,
            .async_context = self.async_context,
            .log_mutex = resources.log_mutex,
            .ha_async_effect_mirror = self.ha_async_effect_mirror,
            .ha_async_batch_mirror = self.ha_async_batch_mirror,
            .ha_async_metadata_mirror = self.ha_async_metadata_mirror,
            .ha_write_gate = self.ha_write_gate,
            .resolution_runtime = self.resolution_runtime,
            .promotion_runtime = self.promotion_runtime,
        };

        const runtime = try self.runtime_alloc.create(enrichment_runtime_mod.EnrichmentRuntime);
        errdefer self.runtime_alloc.destroy(runtime);
        runtime.* = try enrichment_runtime_mod.EnrichmentRuntime.init(
            self.runtime_alloc,
            self.core.batchExecutionResources().store,
            self.core.batchExecutionResources().change_journal,
            self.core.replaySource(),
            self.core.batchExecutionResources().index_manager,
            self.core.batchExecutionResources().apply_mutex,
            append_ctx,
            appendGeneratedBatchFromEnrichment,
            append_ctx,
            recordEnrichmentRequestFailure,
            enrichmentRequestFailurePending,
            enrichmentRequestFailureRangePending,
            .{
                .ptr = append_ctx,
                .lock_fn = lockEnrichmentFailurePendingFence,
                .unlock_fn = unlockEnrichmentFailurePendingFence,
            },
            self.executor,
            notifyDerivedExecutorSequence,
            self.backend_runtime,
            enrichment_cfg,
        );
        errdefer runtime.deinit();
        // The repair ledger and its sequence marker are committed before the
        // enrichment runtime status. A crash in that narrow interval must not
        // make replay invoke a permanently failing provider again. Rebuild the
        // conservative in-memory gate from the authoritative marker index.
        try mergeEnrichmentTerminalFailureEnvelope(resources.store, runtime);
        return .{
            .append_ctx = append_ctx,
            .runtime = runtime,
        };
    }

    fn mergeEnrichmentTerminalFailureEnvelope(
        store: *docstore_mod.DocStore,
        runtime: *enrichment_runtime_mod.EnrichmentRuntime,
    ) !void {
        const marker_envelope = try enrichmentTerminalFailureSequenceEnvelope(store);
        if (marker_envelope.min != 0) {
            runtime.terminal_failure_min_sequence = if (runtime.terminal_failure_min_sequence == 0)
                marker_envelope.min
            else
                @min(runtime.terminal_failure_min_sequence, marker_envelope.min);
            runtime.terminal_failure_max_sequence = @max(runtime.terminal_failure_max_sequence, marker_envelope.max);
        }
    }

    fn initOptionalEnrichmentRuntime(self: *DB, enrichment_cfg: enrichment_runtime_mod.Config) !void {
        var detached = (try self.createDetachedEnrichmentRuntime(enrichment_cfg)) orelse return;
        const owned = detached.take();
        self.enrichment_append_context = owned.append_ctx;
        self.enrichment_runtime = owned.runtime;
        self.async_context.enrichment_runtime = owned.runtime;
    }

    fn deinitEnrichmentConfig(self: *DB, cfg: *enrichment_runtime_mod.Config) void {
        deinitOwnedEnrichmentConfig(self.runtime_alloc, cfg);
    }

    pub fn reconfigureEnrichmentRuntime(self: *DB, cfg: enrichment_runtime_mod.Config) !void {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;

        var owned_cfg = cfg;
        var cfg_owned = true;
        errdefer if (cfg_owned) self.deinitEnrichmentConfig(&owned_cfg);

        const query_visibility_hook_present = hasQueryVisibilityHook(self.async_context);
        var detached = try self.createDetachedEnrichmentRuntime(owned_cfg);
        cfg_owned = false;
        errdefer if (detached) |*runtime| runtime.deinit(self.runtime_alloc);
        if (builtin.is_test) {
            if (test_enrichment_reconfigure_after_detached_hook) |hook| try hook(self);
        }
        if (detached) |*runtime| {
            if (query_visibility_hook_present) {
                runtime.runtime.?.setStatusHook(.{
                    .ptr = self.async_context,
                    .on_change = notifyAsyncContextVisibilityHook,
                });
            }
        }

        const should_start_replacement = detached != null and self.open_mode.allowsOptionalRuntimes();
        const previous_desired = self.async_context.enrichment_desired_running.swap(false, .acq_rel);
        var stopped_existing_runtime = false;
        if (should_start_replacement) {
            lockAtomicWithBackoff(&self.async_context.enrichment_lifecycle_mutex);
            if (self.async_context.enrichment_runtime) |runtime| {
                runtime.stop();
                stopped_existing_runtime = true;
            }
            self.async_context.enrichment_lifecycle_mutex.unlock();
        }
        errdefer if (stopped_existing_runtime) {
            self.async_context.enrichment_desired_running.store(previous_desired or stopped_existing_runtime, .release);
            self.restartEnrichmentAfterStructuralMutation("failed enrichment reconfiguration", "") catch |err| {
                std.log.err("failed to restart previous enrichment runtime after reconfigure failure: {}", .{err});
            };
        };

        if (should_start_replacement) {
            // stop() joins the previous worker. Only now is its durable
            // checkpoint/status/repair-marker state final enough to seed the
            // replacement. Taking this snapshot before the join can resurrect
            // a terminal request that the old worker parks concurrently.
            const replacement = detached.?.runtime.?;
            try replacement.reloadDurableState();
            try mergeEnrichmentTerminalFailureEnvelope(self.core.batchExecutionResources().store, replacement);
            if (self.core.hasGeneratedEnrichmentTargets()) {
                const target_sequence = self.core.nextEnrichmentSequence();
                if (target_sequence != 0) replacement.resumeTargetPreservingRetryDebt(target_sequence);
            }
            try replacement.start();
        }

        lockAtomicWithBackoff(&self.async_context.enrichment_lifecycle_mutex);
        if (self.enrichment_runtime) |runtime| {
            runtime.deinit();
            self.runtime_alloc.destroy(runtime);
            self.enrichment_runtime = null;
            self.async_context.enrichment_runtime = null;
        }
        if (self.enrichment_append_context) |ctx| {
            self.runtime_alloc.destroy(ctx);
            self.enrichment_append_context = null;
        }

        if (detached) |*runtime| {
            const owned = runtime.take();
            self.enrichment_append_context = owned.append_ctx;
            self.enrichment_runtime = owned.runtime;
            self.async_context.enrichment_runtime = owned.runtime;
        }
        self.async_context.enrichment_desired_running.store(should_start_replacement, .release);
        self.async_context.enrichment_lifecycle_mutex.unlock();
        if (!query_visibility_hook_present) self.setQueryVisibilityHook(null);
    }

    fn initResolutionRuntime(self: *DB) !void {
        // Always constructed so catalog/status/runUntilIdle APIs can observe
        // and drain replay. The background worker is started lazily only while
        // the resolver catalog is non-empty.
        const append_ctx = try self.runtime_alloc.create(EnrichmentAppendContext);
        errdefer self.runtime_alloc.destroy(append_ctx);
        const resources = self.core.batchExecutionResources();
        append_ctx.* = .{
            .alloc = self.runtime_alloc,
            .store = resources.store,
            .applied_sequence_checkpoint_path = resources.applied_sequence_checkpoint_path,
            .index_repair_checkpoint = resources.index_repair_checkpoint,
            .shard_manager = resources.shard_manager,
            .index_manager = resources.index_manager,
            .apply_mutex = resources.apply_mutex,
            .repair_replay_mutex = resources.repair_replay_mutex,
            .change_journal = resources.change_journal,
            .replay_source = resources.replay_source,
            .executor = self.executor,
            .async_context = self.async_context,
            .log_mutex = resources.log_mutex,
            .ha_async_effect_mirror = self.ha_async_effect_mirror,
            .ha_async_batch_mirror = self.ha_async_batch_mirror,
            .ha_async_metadata_mirror = self.ha_async_metadata_mirror,
            .ha_write_gate = self.ha_write_gate,
        };

        const runtime = try self.runtime_alloc.create(resolution_runtime_mod.ResolutionRuntime);
        errdefer self.runtime_alloc.destroy(runtime);
        runtime.* = try resolution_runtime_mod.ResolutionRuntime.init(
            self.runtime_alloc,
            self.core.batchExecutionResources().store,
            self.core.replaySource(),
            self.core.batchExecutionResources().index_manager,
            append_ctx,
            appendResolutionRecord,
            self.backend_runtime,
            // Cross-shard blocking source when the serving layer injected one
            // (via OpenOptions); null means local-only blocking against this
            // worker's own store.
            self.resolution_candidate_source,
            // Optional name embedder for mention-embedding backfill.
            self.resolution_embedder,
        );
        errdefer runtime.deinit();
        append_ctx.resolution_runtime = runtime;
        self.resolution_append_context = append_ctx;
        self.resolution_runtime = runtime;
        self.async_context.resolution_runtime = runtime;
        if (self.enrichment_append_context) |ctx| ctx.resolution_runtime = runtime;
    }

    fn initPromotionRuntime(self: *DB) !void {
        // Always constructed (like the resolution runtime) so synchronous
        // drains and status APIs remain available. The background worker is
        // started lazily only while resolver replay can produce promotion work.
        const runtime = try self.runtime_alloc.create(promotion_runtime_mod.PromotionRuntime);
        errdefer self.runtime_alloc.destroy(runtime);
        runtime.* = try promotion_runtime_mod.PromotionRuntime.init(
            self.runtime_alloc,
            self.core.batchExecutionResources().store,
            self.core.replaySource(),
            self.backend_runtime,
            self.promotion_owner,
            // Cross-shard entity sink when the serving layer injected one (via
            // OpenOptions or setEntitySink); the missing-sink policy decides
            // whether null means wait or explicit no-op.
            self.entity_sink,
            self.entity_sink_missing_policy,
        );
        errdefer runtime.deinit();
        self.promotion_runtime = runtime;
        self.async_context.promotion_runtime = runtime;
        // Patch the resolution stage's append context so journaling a resolution
        // artifact (tagged with the promotion hint) wakes the promoter.
        if (self.resolution_append_context) |ctx| ctx.promotion_runtime = runtime;
    }

    fn initOptionalTtlRuntime(self: *DB, cfg: ttl_runtime_mod.Config) !void {
        const ttl_ctx = try self.runtime_alloc.create(TtlCleanupContext);
        errdefer self.runtime_alloc.destroy(ttl_ctx);
        const batch_resources = self.core.batchExecutionResources();
        ttl_ctx.* = .{
            .batch = .{
                .alloc = self.runtime_alloc,
                .store = batch_resources.store,
                .applied_sequence_checkpoint_path = batch_resources.applied_sequence_checkpoint_path,
                .shard_manager = batch_resources.shard_manager,
                .change_journal = batch_resources.change_journal,
                .replay_source = batch_resources.replay_source,
                .index_manager = batch_resources.index_manager,
                .apply_mutex = batch_resources.apply_mutex,
                .log_mutex = batch_resources.log_mutex,
                .identity_namespace = batch_resources.identity_namespace,
                .executor = self.executor,
                .enrichment_runtime = self.enrichment_runtime,
                .resolution_runtime = self.resolution_runtime,
                .promotion_runtime = self.promotion_runtime,
                .ha_async_effect_mirror = self.ha_async_effect_mirror,
                .ha_async_batch_mirror = self.ha_async_batch_mirror,
                .ha_async_metadata_mirror = self.ha_async_metadata_mirror,
                .ha_write_gate = self.ha_write_gate,
            },
            .grace_period_ns = cfg.grace_period_ns,
        };
        ttl_ctx.batch.identity_visibility_owner_slot = &ttl_ctx.identity_visibility_owner;
        const runtime = try self.runtime_alloc.create(ttl_runtime_mod.TtlRuntime);
        errdefer self.runtime_alloc.destroy(runtime);
        runtime.* = try ttl_runtime_mod.TtlRuntime.init(
            self.runtime_alloc,
            self.core.batchExecutionResources().store,
            ttl_ctx,
            deleteExpiredDocumentsFromCandidates,
            &self.async_context.text_merge_deferred,
            self.backend_runtime,
            cfg,
        );
        errdefer runtime.deinit();
        self.ttl_cleanup_context = ttl_ctx;
        self.ttl_runtime = runtime;
    }

    fn initOptionalTransactionRuntime(self: *DB, cfg: transaction_runtime_mod.Config) !void {
        const identity_ctx = try self.runtime_alloc.create(db_core.TransactionRecoveryIdentityContext);
        errdefer self.runtime_alloc.destroy(identity_ctx);
        identity_ctx.* = .{
            .store = self.core.store,
            .identity_namespace = self.core.identity_namespace,
            .alloc = self.runtime_alloc,
        };
        var effective_cfg = cfg;
        effective_cfg.resolution_extra_hooks = db_core.transactionRecoveryIdentityHooks(identity_ctx);

        const runtime = try self.runtime_alloc.create(transaction_runtime_mod.Runtime);
        errdefer self.runtime_alloc.destroy(runtime);
        runtime.* = try transaction_runtime_mod.Runtime.init(
            self.runtime_alloc,
            self.core.batchExecutionResources().store,
            self.backend_runtime,
            effective_cfg,
        );
        errdefer runtime.deinit();
        self.transaction_recovery_identity_context = identity_ctx;
        self.transaction_runtime = runtime;
    }

    fn initOptionalTextMergeRuntime(self: *DB, cfg: text_merge_runtime_mod.Config) !void {
        if (!self.start_index_workers) return;
        if (!cfg.enabled) return;
        const resources = self.core.asyncResources();
        const runtime = try self.runtime_alloc.create(text_merge_runtime_mod.TextMergeRuntime);
        errdefer self.runtime_alloc.destroy(runtime);
        runtime.* = try text_merge_runtime_mod.TextMergeRuntime.init(
            self.runtime_alloc,
            resources.index_manager,
            resources.apply_mutex,
            self.backend_runtime,
            cfg,
        );
        errdefer runtime.deinit();
        self.text_merge_runtime = runtime;
        self.async_context.text_merge_runtime = runtime;
    }

    fn initOptionalSparseCompactionRuntime(self: *DB, cfg: sparse_compaction_runtime_mod.Config) !void {
        if (!self.start_index_workers) return;
        if (!cfg.enabled) return;
        const resources = self.core.asyncResources();
        const runtime = try self.runtime_alloc.create(sparse_compaction_runtime_mod.SparseCompactionRuntime);
        errdefer self.runtime_alloc.destroy(runtime);
        runtime.* = try sparse_compaction_runtime_mod.SparseCompactionRuntime.init(
            self.runtime_alloc,
            resources.index_manager,
            resources.apply_mutex,
            self.backend_runtime,
            cfg,
        );
        errdefer runtime.deinit();
        self.sparse_compaction_runtime = runtime;
        self.async_context.sparse_compaction_runtime = runtime;
    }

    fn initOptionalRuntimes(self: *DB, opts: *OpenOptions) !void {
        // Created before enrichment so the enrichment append context can notify
        // it when extraction artifacts land.
        try self.initResolutionRuntime();
        // Created after the resolution runtime so it can patch the resolution
        // append context to wake the promoter when resolution artifacts land.
        try self.initPromotionRuntime();
        if (opts.enrichment) |raw_enrichment_cfg| {
            var enrichment_cfg = raw_enrichment_cfg;
            if (enrichment_cfg.secret_store == null) enrichment_cfg.secret_store = opts.secret_store;
            if (enrichment_cfg.remote_content == null) enrichment_cfg.remote_content = opts.remote_content;
            if (enrichment_cfg.resource_manager == null) enrichment_cfg.resource_manager = opts.resource_manager;
            try self.initOptionalEnrichmentRuntime(enrichment_cfg);
            // A successful initialization transfers every provider into the
            // runtime; later open failures are then cleaned up with the DB.
            opts.enrichment = null;
        }
        if (opts.ttl_cleanup.enabled) {
            try self.initOptionalTtlRuntime(opts.ttl_cleanup);
        }
        if (opts.transaction_recovery.enabled) {
            try self.initOptionalTransactionRuntime(opts.transaction_recovery);
        }
        try self.initOptionalTextMergeRuntime(opts.text_merge);
        try self.initOptionalSparseCompactionRuntime(opts.sparse_compaction);
    }

    fn startOptionalRuntimes(self: *DB) !void {
        try self.startResolverReplayRuntimesIfConfigured();
        if (self.enrichment_runtime) |runtime| {
            try runtime.start();
            self.async_context.enrichment_desired_running.store(true, .release);
        }
        if (self.ttl_runtime) |runtime| try runtime.start();
        if (self.transaction_runtime) |runtime| {
            runtime.config.local_resolution_ctx = self;
            runtime.config.resolve_local_fn = resolveRecoveredLocalTransaction;
            try runtime.start();
        }
        if (self.text_merge_runtime) |runtime| try runtime.start();
        if (self.sparse_compaction_runtime) |runtime| try runtime.start();
    }

    pub fn ensureTransactionRecoveryRuntime(self: *DB, cfg: transaction_runtime_mod.Config) !void {
        if (!cfg.enabled or self.transaction_runtime != null) return;
        lockApply(self);
        defer self.core.unlockApply();
        if (self.transaction_runtime != null) return;
        try self.initOptionalTransactionRuntime(cfg);
        if (self.optional_runtime_workers_enabled) {
            const runtime = self.transaction_runtime.?;
            runtime.config.local_resolution_ctx = self;
            runtime.config.resolve_local_fn = resolveRecoveredLocalTransaction;
            try runtime.start();
        }
    }

    fn hasConfiguredResolvers(self: *const DB) bool {
        return self.core.index_manager.resolvers.items.len > 0;
    }

    fn resolverReplayNeedsDrain(self: *DB) bool {
        if (self.hasConfiguredResolvers()) return true;
        if (self.resolution_runtime) |runtime| {
            const replay_stats = runtime.stats();
            if (replay_stats.catch_up_required or replay_stats.blocked) return true;
        }
        if (self.promotion_runtime) |runtime| {
            const replay_stats = runtime.stats();
            if (replay_stats.catch_up_required or replay_stats.blocked) return true;
        }
        return false;
    }

    fn notifyResolverReplayRuntimes(self: *DB, sequence: u64) void {
        if (!self.hasConfiguredResolvers()) return;
        self.notifyResolverReplayRuntimesForced(sequence);
    }

    fn notifyResolverReplayRuntimesForced(self: *DB, sequence: u64) void {
        if (self.resolution_runtime) |runtime| runtime.notifySequence(sequence);
        if (self.promotion_runtime) |runtime| runtime.notifySequence(sequence);
    }

    fn startResolverReplayRuntimesIfConfigured(self: *DB) !void {
        if (!self.hasConfiguredResolvers()) return;
        try self.startResolverReplayRuntimes();
    }

    fn startResolverReplayRuntimes(self: *DB) !void {
        if (self.resolution_runtime) |runtime| try runtime.start();
        if (self.promotion_runtime) |runtime| try runtime.start();
    }

    fn stopResolverReplayRuntimesIfUnconfigured(self: *DB) void {
        if (self.hasConfiguredResolvers()) return;
        if (self.resolution_runtime) |runtime| runtime.stop();
        if (self.promotion_runtime) |runtime| runtime.stop();
    }

    fn clearLiveDocSetCache(self: *DB) void {
        lockAtomic(&self.live_doc_set_cache_mutex);
        defer self.live_doc_set_cache_mutex.unlock();
        if (self.live_doc_set_cache_set) |*cached| cached.deinit(self.alloc);
        self.live_doc_set_cache_set = null;
        self.live_doc_set_cache_generation = null;
    }

    fn clearNonVisibleDocSetCache(self: *DB) void {
        lockAtomic(&self.nonvisible_doc_set_cache_mutex);
        defer self.nonvisible_doc_set_cache_mutex.unlock();
        if (self.nonvisible_doc_set_cache_set) |*cached| cached.deinit(self.alloc);
        self.nonvisible_doc_set_cache_set = null;
        self.nonvisible_doc_set_cache_generation = null;
        self.nonvisible_doc_set_cache_overflow = false;
        self.nonvisible_doc_set_cache_entries.store(0, .monotonic);
    }

    fn deinitWrapperState(self: *DB, executor_ready: bool) void {
        // Stop background workers before tearing down stores, runtimes, and
        // index state they may inspect.
        self.stopArtifactRepairMetadataWorker();
        self.stopQuarantineRetryWorker();
        // Close may flush/coalesce derived watermarks while workers are
        // stopping. That must not call back into the write/status cache after
        // optional runtimes or index state have started tearing down.
        self.setQueryVisibilityHook(null);
        self.async_context.background_closing.store(true, .release);
        self.async_context.enrichment_desired_running.store(false, .release);
        if (self.algebraic_hll_owner_id != 0) {
            self.backend_runtime.durable_jobs.closeOwner(self.algebraic_hll_owner_id);
            self.algebraic_hll_owner_id = 0;
        }
        self.backend_runtime.durable_jobs.closeOwner(self.repair_cleanup_owner_id);
        self.backend_runtime.durable_jobs.closeOwner(self.backend_owner_id);
        self.clearLiveDocSetCache();
        self.clearNonVisibleDocSetCache();
        self.bulk_ingest_coalescer.deinit(self.alloc);
        self.bulk_ingest_identity_state.deinit(self.alloc);
        self.bulk_ingest_identity_all_new = false;
        self.clearBulkIngestSeenDocKeysLocked();
        self.bulk_ingest_seen_doc_keys.deinit(self.alloc);
        self.clearActiveIndexRepairsLocked();
        self.active_index_repairs.deinit(self.alloc);
        self.closeShadowIndexManager() catch {};
        if (self.transaction_runtime) |runtime| {
            runtime.deinit();
            self.runtime_alloc.destroy(runtime);
        }
        if (self.transaction_recovery_identity_context) |ctx| self.runtime_alloc.destroy(ctx);
        if (self.ttl_runtime) |runtime| {
            runtime.deinit();
            self.runtime_alloc.destroy(runtime);
        }
        if (self.ttl_cleanup_context) |ctx| self.runtime_alloc.destroy(ctx);
        if (self.enrichment_runtime) |runtime| {
            runtime.deinit();
            self.runtime_alloc.destroy(runtime);
        }
        if (self.enrichment_append_context) |ctx| self.runtime_alloc.destroy(ctx);
        if (self.resolution_runtime) |runtime| {
            runtime.deinit();
            self.runtime_alloc.destroy(runtime);
        }
        self.async_context.resolution_runtime = null;
        // After the resolution runtime (its final catch-up may journal
        // resolution artifacts that notify the promoter) but before the
        // resolution append context the promoter is wired into is destroyed.
        if (self.promotion_runtime) |runtime| {
            runtime.deinit();
            self.runtime_alloc.destroy(runtime);
        }
        self.async_context.promotion_runtime = null;
        if (self.resolution_append_context) |ctx| self.runtime_alloc.destroy(ctx);
        // Derived full-text publishers may be asleep in merge backpressure
        // admission. Close that admission before joining their executor: the
        // merge runtime is the owner of the wakeup predicate, so joining the
        // publishers first can otherwise strand shutdown behind a predicate
        // that is not closed until later in this function. Drain the merge
        // worker too because its tasks borrow inline index generations.
        if (executor_ready) self.executor.beginShutdown();
        if (self.text_merge_runtime) |runtime| _ = runtime.stop();
        if (executor_ready) self.executor.deinit(self.runtime_alloc);
        self.runtime_alloc.destroy(self.executor);
        if (self.text_merge_runtime) |runtime| {
            self.async_context.text_merge_runtime = null;
            runtime.deinit();
            self.runtime_alloc.destroy(runtime);
        }
        if (self.sparse_compaction_runtime) |runtime| {
            self.async_context.sparse_compaction_runtime = null;
            runtime.deinit();
            self.runtime_alloc.destroy(runtime);
        }
        self.core.deinit();
        if (self.owned_backend_runtime) |*runtime| runtime.deinit();
        self.async_context.deinit(self.runtime_alloc);
        self.runtime_alloc.destroy(self.async_context);
        if (self.owned_resource_manager) |manager| {
            manager.deinit(self.alloc);
            self.alloc.destroy(manager);
        }
        if (self.generation_read_lease) |*lease| lease.deinit();
        self.generation_read_lease = null;
        self.* = undefined;
        self.closed = true;
    }

    pub fn runTransactionRecoveryOnce(self: *DB, config: transaction_runtime_mod.Config) !types.TransactionRecoveryStats {
        var ha_mutation = self.acquireHAMutationShared();
        defer if (ha_mutation) |*lease| lease.release();
        try self.enforceHAWriteGate();
        if (!config.enabled) return .{};
        if (config.replicated_metadata) {
            return try transaction_runtime_mod.recoverOnce(
                self.alloc,
                self.core.batchExecutionResources().store,
                config,
            );
        }
        const resolve_participant = config.resolve_participant_fn orelse return error.MissingParticipantResolver;
        const resolver_ctx = config.resolver_ctx orelse return error.MissingParticipantResolver;
        const now_ns = config.clock.nowRealtimeNs();
        const resolved_finalized = try self.resolveFinalizedTransactionIntentsForRecovery(now_ns);

        var recovery_stats: types.TransactionRecoveryStats = .{
            .enabled = true,
            .lease_owned = config.lease_owned,
            .runs = 1,
            .resolved_finalized = resolved_finalized,
            .last_run_ns = now_ns,
        };

        // Notification may perform network I/O or route back to this DB. Keep
        // it entirely outside the apply lock and acknowledge each successful
        // delivery with a separate short, idempotent locked update.
        const txns = try self.core.listTransactions(self.alloc);
        defer self.alloc.free(txns);
        for (txns) |txn| {
            if (txn.status == .pending) continue;
            const unresolved = self.core.getUnresolvedTransactionParticipants(self.alloc, txn.txn_id) catch |err| switch (err) {
                transactions_mod.TxnError.TxnNotFound => continue,
                else => return err,
            };
            defer transactions_mod.freeParticipantList(self.alloc, unresolved);
            for (unresolved) |participant| {
                recovery_stats.notification_attempts += 1;
                if (config.local_participant) |local| {
                    if (std.mem.eql(u8, local, participant)) {
                        self.markTransactionParticipantResolved(txn.txn_id, participant) catch |err| switch (err) {
                            transactions_mod.TxnError.TxnNotFound => {},
                            else => return err,
                        };
                        recovery_stats.notification_successes += 1;
                        continue;
                    }
                }
                resolve_participant(resolver_ctx, txn.txn_id, participant, txn.status, txn.commit_version) catch {
                    recovery_stats.notification_failures += 1;
                    continue;
                };
                self.markTransactionParticipantResolved(txn.txn_id, participant) catch |err| switch (err) {
                    transactions_mod.TxnError.TxnNotFound => {},
                    else => return err,
                };
                recovery_stats.notification_successes += 1;
            }
        }

        // Serialize presumed-abort and metadata cleanup with prepare/resolve,
        // but do not hold the lock across participant callbacks above.
        lockApply(self);
        const local_stats = self.core.recoverTransactions(now_ns -| config.cutoff_ns, now_ns) catch |err| {
            self.core.unlockApply();
            return err;
        };
        self.core.unlockApply();
        recovery_stats.scanned_records = local_stats.scanned_records;
        recovery_stats.auto_aborted = local_stats.auto_aborted;
        recovery_stats.resolved_finalized += local_stats.resolved_finalized;
        recovery_stats.cleaned_records = local_stats.cleaned_records;
        recovery_stats.kept_recent_pending = local_stats.kept_recent_pending;
        recovery_stats.deferred_unresolved = local_stats.deferred_unresolved;
        return recovery_stats;
    }

    pub fn beginBulkIngestSession(self: *DB) !void {
        var ha_mutation = self.acquireHAMutationShared();
        defer if (ha_mutation) |*lease| lease.release();
        try self.enforceHAWriteGate();
        try beginExternalDenseBulkSessionTrackedWait(self.async_context, self.backend_runtime.io());
        errdefer finishExternalDenseBulkSessionTrackedBestEffort(self.async_context);
        lockApply(self);
        defer self.core.unlockApply();
        const resources = self.core.batchExecutionResources();
        try resources.store.beginBulkIngestSession();
        errdefer resources.store.abortBulkIngestSession();
        // A table bulk window is a primary-store optimization, not permission
        // to mutate active dense topology across committed batches. Dense
        // projection is published afterward through structurally reopenable
        // streaming replay.
        try resources.index_manager.beginSparseBulkIngestSessions();
        errdefer resources.index_manager.abortSparseBulkIngestSessions();
        try resources.index_manager.beginAlgebraicBulkIngestSessions();
        self.configureBulkIngestIdentityAllNewLocked() catch |err| {
            resources.index_manager.abortAlgebraicBulkIngestSessions();
            return err;
        };
        errdefer self.clearBulkIngestIdentityAllNewLocked();
        self.bulk_ingest_coalescer.begin();
    }

    pub fn finishBulkIngestSessionWithOptions(self: *DB, options: backend_types.BulkIngestFinishOptions) !void {
        var ha_mutation = self.acquireHAMutationShared();
        defer if (ha_mutation) |*lease| lease.release();
        try self.enforceHAWriteGate();
        try self.flushBulkIngestCoalescerWithSyncLevel(.write, null);
        var external_session_tracked = true;
        defer if (external_session_tracked) finishExternalDenseBulkSessionTrackedBestEffort(self.async_context);
        {
            lockApply(self);
            defer self.core.unlockApply();
            const resources = self.core.batchExecutionResources();
            var first_err: ?anyerror = null;
            resources.index_manager.finishAlgebraicBulkIngestSessionsWithOptions(resources.store, options) catch |err| {
                first_err = err;
            };
            resources.store.finishBulkIngestSessionWithOptions(options) catch |err| {
                if (first_err == null) first_err = err;
            };
            resources.index_manager.finishSparseBulkIngestSessionsWithOptions(options) catch |err| {
                if (first_err == null) first_err = err;
            };
            self.bulk_ingest_coalescer.clear(self.alloc);
            self.clearBulkIngestIdentityAllNewLocked();
            if (first_err) |err| return err;
        }
        external_session_tracked = false;
        _ = try finishExternalDenseBulkSessionTrackedAndFinalize(self.async_context);
        // External bulk finish is the user-visible publication boundary for the
        // staged batch. Publish the primary LSM session, release the deferred
        // replay wake, then wait for structurally reopenable dense replay before
        // returning.
        flushDeferredExternalBulkExecutorNotificationOrTarget(
            self.async_context,
            self.executor,
            self.core.nextDerivedSequence(),
        );
        try self.waitForCurrentSyncLevel(.full_index);
        notifyQueryVisibilityHook(self.async_context, .publish);
    }

    pub fn beginDenseAutoBulkIngestSession(self: *DB) !void {
        var ha_mutation = self.acquireHAMutationShared();
        defer if (ha_mutation) |*lease| lease.release();
        try self.enforceHAWriteGate();
        try beginExternalDenseBulkSessionTrackedWait(self.async_context, self.backend_runtime.io());
        errdefer finishExternalDenseBulkSessionTrackedBestEffort(self.async_context);
        lockApply(self);
        defer self.core.unlockApply();
        const resources = self.core.batchExecutionResources();
        try resources.index_manager.beginDenseBulkIngestSessions();
        self.bulk_ingest_coalescer.begin();
    }

    pub fn beginPrimaryStoreAutoBulkIngestSession(self: *DB) !void {
        var ha_mutation = self.acquireHAMutationShared();
        defer if (ha_mutation) |*lease| lease.release();
        try self.enforceHAWriteGate();
        lockApply(self);
        defer self.core.unlockApply();
        const resources = self.core.batchExecutionResources();
        try resources.store.beginBulkIngestSession();
        errdefer resources.store.abortBulkIngestSession();
        try self.configureBulkIngestIdentityAllNewLocked();
        errdefer self.clearBulkIngestIdentityAllNewLocked();
        self.bulk_ingest_coalescer.begin();
    }

    pub fn finishPrimaryStoreAutoBulkIngestSessionWithOptions(self: *DB, options: backend_types.BulkIngestFinishOptions) !void {
        var ha_mutation = self.acquireHAMutationShared();
        defer if (ha_mutation) |*lease| lease.release();
        try self.enforceHAWriteGate();
        try self.flushBulkIngestCoalescerWithSyncLevel(.write, null);
        {
            lockApply(self);
            defer self.core.unlockApply();
            const resources = self.core.batchExecutionResources();
            resources.store.finishBulkIngestSessionWithOptions(options) catch |err| {
                self.bulk_ingest_coalescer.clear(self.alloc);
                self.clearBulkIngestIdentityAllNewLocked();
                return err;
            };
            self.bulk_ingest_coalescer.clear(self.alloc);
            self.clearBulkIngestIdentityAllNewLocked();
        }
        flushDeferredExternalBulkExecutorNotificationOrTarget(
            self.async_context,
            self.executor,
            self.core.nextDerivedSequence(),
        );
        notifyQueryVisibilityHook(self.async_context, .publish);
    }

    pub fn rollPrimaryStoreAutoBulkIngestSessionWithOptions(self: *DB, options: backend_types.BulkIngestFinishOptions) !void {
        try self.finishPrimaryStoreAutoBulkIngestSessionWithOptions(options);
        try self.beginPrimaryStoreAutoBulkIngestSession();
    }

    pub fn finishDenseAutoBulkIngestSessionWithOptions(self: *DB, options: backend_types.BulkIngestFinishOptions) !void {
        try self.finishDenseAutoBulkIngestSessionWithOptionsInternal(options, true);
    }

    pub fn rollDenseAutoBulkIngestSessionWithOptions(self: *DB, options: backend_types.BulkIngestFinishOptions) !void {
        try self.finishDenseAutoBulkIngestSessionWithOptionsInternal(options, true);
        try self.beginDenseAutoBulkIngestSession();
    }

    fn finishDenseAutoBulkIngestSessionWithOptionsInternal(self: *DB, options: backend_types.BulkIngestFinishOptions, notify_executor: bool) !void {
        var ha_mutation = self.acquireHAMutationShared();
        defer if (ha_mutation) |*lease| lease.release();
        try self.enforceHAWriteGate();
        try self.flushBulkIngestCoalescerWithSyncLevel(.write, null);
        var external_session_tracked = true;
        defer if (external_session_tracked) finishExternalDenseBulkSessionTrackedBestEffort(self.async_context);
        {
            lockApply(self);
            defer self.core.unlockApply();
            const resources = self.core.batchExecutionResources();
            resources.store.flushBufferedWritesWithOptions(options) catch |err| {
                self.bulk_ingest_coalescer.clear(self.alloc);
                return err;
            };
            resources.index_manager.finishDenseBulkIngestSessionsWithOptions(options) catch |err| {
                self.bulk_ingest_coalescer.clear(self.alloc);
                self.clearBulkIngestIdentityAllNewLocked();
                return err;
            };
            self.bulk_ingest_coalescer.clear(self.alloc);
            self.clearBulkIngestIdentityAllNewLocked();
        }
        external_session_tracked = false;
        _ = try finishExternalDenseBulkSessionTrackedAndFinalize(self.async_context);
        if (notify_executor) {
            flushDeferredExternalBulkExecutorNotificationOrTarget(
                self.async_context,
                self.executor,
                self.core.nextDerivedSequence(),
            );
        }
        notifyQueryVisibilityHook(self.async_context, .publish);
    }

    pub fn abortDenseAutoBulkIngestSession(self: *DB) void {
        var ha_mutation = self.acquireHAMutationShared();
        defer if (ha_mutation) |*lease| lease.release();
        lockApply(self);
        {
            defer self.core.unlockApply();
            const resources = self.core.batchExecutionResources();
            self.bulk_ingest_coalescer.clear(self.alloc);
            resources.index_manager.abortDenseBulkIngestSessions();
        }
        finishExternalDenseBulkSessionTrackedBestEffort(self.async_context);
        flushDeferredExternalBulkExecutorNotification(self.async_context, self.executor);
    }

    pub fn abortPrimaryStoreAutoBulkIngestSession(self: *DB) void {
        var ha_mutation = self.acquireHAMutationShared();
        defer if (ha_mutation) |*lease| lease.release();
        lockApply(self);
        defer self.core.unlockApply();
        const resources = self.core.batchExecutionResources();
        self.bulk_ingest_coalescer.clear(self.alloc);
        self.clearBulkIngestIdentityAllNewLocked();
        resources.store.abortBulkIngestSession();
    }

    pub fn abortBulkIngestSession(self: *DB) void {
        var ha_mutation = self.acquireHAMutationShared();
        defer if (ha_mutation) |*lease| lease.release();
        lockApply(self);
        {
            defer self.core.unlockApply();
            const resources = self.core.batchExecutionResources();
            self.bulk_ingest_coalescer.clear(self.alloc);
            self.clearBulkIngestIdentityAllNewLocked();
            resources.index_manager.abortAlgebraicBulkIngestSessions();
            resources.index_manager.abortSparseBulkIngestSessions();
            resources.store.abortBulkIngestSession();
        }
        finishExternalDenseBulkSessionTrackedBestEffort(self.async_context);
        flushDeferredExternalBulkExecutorNotification(self.async_context, self.executor);
    }

