    pub fn runLsmMaintenanceStep(self: *DB) !bool {
        var ha_mutation = self.acquireHAMutationShared();
        defer if (ha_mutation) |*lease| lease.release();
        return try self.runLsmMaintenanceStepWithHAMutationHeld();
    }

    fn runLsmMaintenanceStepWithHAMutationHeld(self: *DB) !bool {
        if (try self.core.index_manager.runLsmObsoleteReclaimDue()) return true;
        const primary_reclaim_due = if (self.core.primary_store_owner.nextLsmMaintenanceWakeDelayNsBestEffort()) |delay_ns| delay_ns == 0 else false;
        if (primary_reclaim_due) {
            if (try self.core.primary_store_owner.runLsmMaintenanceStep()) return true;
        }

        const primary_score = self.core.primary_store_owner.lsmMaintenanceScore();
        const index_score = self.core.index_manager.lsmMaintenanceScore();
        if (primary_score == 0 and index_score == 0) {
            self.core.primary_store_owner.refreshLsmMaintenanceDebtHint();
            self.core.index_manager.refreshLsmMaintenanceDebtHint();
            return false;
        }
        if (primary_score >= index_score) {
            return try self.core.primary_store_owner.runLsmMaintenanceStep();
        }
        return try self.core.index_manager.runLsmMaintenanceStep();
    }

    pub fn runLsmMaintenanceStepBestEffort(self: *DB) !bool {
        var ha_mutation = self.acquireHAMutationShared();
        defer if (ha_mutation) |*lease| lease.release();
        if (try self.core.index_manager.runLsmObsoleteReclaimDueBestEffort()) return true;
        const primary_reclaim_due = if (self.core.primary_store_owner.nextLsmMaintenanceWakeDelayNsBestEffort()) |delay_ns| delay_ns == 0 else false;
        if (primary_reclaim_due) {
            if (try self.core.primary_store_owner.runLsmMaintenanceStepBestEffort()) return true;
        }

        const primary_score = self.core.primary_store_owner.lsmMaintenanceDebtHint();
        if (primary_score > 0) {
            if (try self.core.primary_store_owner.runLsmMaintenanceStepBestEffort()) return true;
        }
        if (try self.core.index_manager.runLsmMaintenanceStepBestEffort()) return true;
        if (primary_score > 0) {
            self.core.primary_store_owner.refreshLsmMaintenanceDebtHint();
        }
        return false;
    }

    pub fn runPrimaryLsmMaintenanceStep(self: *DB) !bool {
        var ha_mutation = self.acquireHAMutationShared();
        defer if (ha_mutation) |*lease| lease.release();
        if (try self.core.primary_store_owner.runDueLsmObsoleteReclaim()) return true;
        const primary_score = self.core.primary_store_owner.lsmMaintenanceScore();
        const primary_reclaim_due = if (self.core.primary_store_owner.nextLsmMaintenanceWakeDelayNsBestEffort()) |delay_ns| delay_ns == 0 else false;
        if (primary_score == 0 and !primary_reclaim_due) return false;
        if (try self.core.primary_store_owner.runLsmMaintenanceStep()) return true;
        self.core.primary_store_owner.refreshLsmMaintenanceDebtHint();
        return false;
    }

    pub fn runPrimaryLsmMaintenanceStepBestEffort(self: *DB) !bool {
        var ha_mutation = self.acquireHAMutationShared();
        defer if (ha_mutation) |*lease| lease.release();
        if (try self.core.primary_store_owner.runDueLsmObsoleteReclaim()) return true;
        const primary_score = self.core.primary_store_owner.lsmMaintenanceDebtHint();
        const primary_reclaim_due = if (self.core.primary_store_owner.nextLsmMaintenanceWakeDelayNsBestEffort()) |delay_ns| delay_ns == 0 else false;
        if (primary_score == 0 and !primary_reclaim_due) return false;
        if (try self.core.primary_store_owner.runLsmMaintenanceStepBestEffort()) return true;
        self.core.primary_store_owner.refreshLsmMaintenanceDebtHint();
        return false;
    }

    pub fn hasActiveDenseBulkWork(self: *const DB) bool {
        return asyncContextHasActiveDenseBulkWork(self.async_context);
    }

    pub fn runLsmMaintenanceUntilIdle(self: *DB) !usize {
        var steps: usize = 0;
        while (try self.runLsmMaintenanceStep()) {
            steps += 1;
        }
        return steps;
    }

    pub fn runDueLsmObsoleteReclaimUntilIdle(self: *DB, max_steps: usize) !usize {
        var ha_mutation = self.acquireHAMutationShared();
        defer if (ha_mutation) |*lease| lease.release();
        var steps: usize = 0;
        while (steps < max_steps) : (steps += 1) {
            var progressed = false;
            if (try self.core.primary_store_owner.runDueLsmObsoleteReclaim()) progressed = true;
            if (try self.core.index_manager.runLsmObsoleteReclaimDue()) progressed = true;

            if (!progressed) {
                const wake_due = if (self.nextLsmMaintenanceWakeDelayNsBestEffort()) |delay_ns| delay_ns == 0 else false;
                if (!wake_due) break;
                if (!try self.runLsmMaintenanceStepWithHAMutationHeld()) break;
            }
        }
        return steps;
    }

    test "db lsm maintenance reclaims due index obsolete paths before primary compaction" {
        const alloc = std.testing.allocator;
        var path_buf: [256]u8 = undefined;
        const path = tempPath(&path_buf);
        defer cleanupTempDir(path);

        var db = try DB.open(alloc, std.mem.span(path), .{
            .start_index_workers = false,
            // This test drives primary maintenance explicitly; keep detached
            // primary LSM maintenance from racing the precondition checks.
            .executor = .{ .backend = .manual },
            .primary_backend = .{ .lsm = .{
                .flush_threshold = 1,
                .defer_flush_on_commit = true,
                .l0_soft_limit_runs = 100,
                .obsolete_retention_ns = 0,
            } },
            .index_backends = .{
                .dense_lsm_options = .{
                    .flush_threshold = 1,
                    .defer_flush_on_commit = true,
                    .l0_soft_limit_runs = 100,
                    .obsolete_retention_ns = 0,
                },
            },
        });
        defer db.close();

        try db.addIndex(.{
            .name = "dv_v1",
            .kind = .dense_vector,
            .config_json = "{\"field\":\"embedding\",\"dims\":2,\"metric\":\"l2_squared\"}",
        });

        var key_buf: [16]u8 = undefined;
        for (0..4) |i| {
            const key = try std.fmt.bufPrint(&key_buf, "doc:{d}", .{i});
            try db.batch(.{
                .writes = &.{.{ .key = key, .value = "{\"embedding\":[1,2]}" }},
                .sync_level = .write,
            });
            switch (db.core.primary_store_owner) {
                .lsm => |*owner| try owner.handle.backend.sync(true),
                else => return error.SkipZigTest,
            }
        }

        switch (db.core.primary_store_owner) {
            .lsm => |*owner| try owner.handle.backend.flushBufferedWritesWithOptions(.{ .compact = false, .flush = true }),
            else => return error.SkipZigTest,
        }

        switch (db.core.primary_store_owner) {
            .lsm => |*owner| owner.handle.backend.options.l0_soft_limit_runs = 1,
            else => return error.SkipZigTest,
        }

        const dense_entry = db.core.index_manager.denseIndex("dv_v1") orelse return error.TestUnexpectedResult;
        const dense_backend = switch (dense_entry.index.env_owner) {
            .lsm => |*handle| handle.backend,
            else => return error.SkipZigTest,
        };
        const dense_root = dense_backend.root_dir orelse return error.TestUnexpectedResult;
        const obsolete_path = try lsm_backend_mod.repository.runPath(alloc, dense_root, 999_999);
        defer alloc.free(obsolete_path);

        try lsm_backend_mod.repository.writeFileAbsoluteWithStorage(dense_backend.storage.?, obsolete_path, "obsolete");
        {
            const locked = lsm_backend_mod.runtime.lockBackend(lsm_backend_mod.Backend, dense_backend);
            defer lsm_backend_mod.runtime.unlockBackend(lsm_backend_mod.Backend, dense_backend, locked);
            try dense_backend.queueObsoleteFilePath(try alloc.dupe(u8, obsolete_path));
            dense_backend.manifest_dirty = false;
        }

        try expectObsoletePathsReclaimable(dense_backend, 1);
        try std.testing.expect(try db.runLsmMaintenanceStepBestEffort());
        try std.testing.expectEqual(@as(u64, 0), dense_backend.snapshotMaintenanceStats().obsolete_paths);
        try std.testing.expectError(error.FileNotFound, dense_backend.storage.?.readFileAlloc(alloc, obsolete_path, 1024));
    }

    /// A queued obsolete path only counts as reclaimable once no reader pins
    /// the backend; transient background readers (index loads, status probes)
    /// mask it as pinned_by_readers for a moment. Poll instead of asserting a
    /// single snapshot so loaded CI machines don't flake.
    fn expectObsoletePathsReclaimable(backend: *lsm_backend_mod.Backend, expected: u64) !void {
        var attempts: usize = 0;
        while (backend.snapshotMaintenanceStats().obsolete_paths_reclaimable != expected) : (attempts += 1) {
            if (attempts >= 2000) {
                return std.testing.expectEqual(expected, backend.snapshotMaintenanceStats().obsolete_paths_reclaimable);
            }
            std.Thread.yield() catch {};
        }
    }

    test "db primary lsm maintenance step does not reclaim index obsolete paths" {
        const alloc = std.testing.allocator;
        var path_buf: [256]u8 = undefined;
        const path = tempPath(&path_buf);
        defer cleanupTempDir(path);

        var db = try DB.open(alloc, std.mem.span(path), .{
            .start_index_workers = false,
            // This test verifies the explicit primary-only maintenance entry
            // point; keep detached LSM maintenance from consuming the queued
            // primary obsolete path before the assertion.
            .executor = .{ .backend = .manual },
            .primary_backend = .{ .lsm = .{
                .flush_threshold = 1,
                .defer_flush_on_commit = true,
                .l0_soft_limit_runs = 100,
                .obsolete_retention_ns = 0,
            } },
            .index_backends = .{
                .dense_lsm_options = .{
                    .flush_threshold = 1,
                    .defer_flush_on_commit = true,
                    .l0_soft_limit_runs = 100,
                    .obsolete_retention_ns = 0,
                },
            },
        });
        defer db.close();

        try db.addIndex(.{
            .name = "dv_v1",
            .kind = .dense_vector,
            .config_json = "{\"field\":\"embedding\",\"dims\":2,\"metric\":\"l2_squared\"}",
        });

        const primary_backend = switch (db.core.primary_store_owner) {
            .lsm => |*owner| owner.handle.backend,
            else => return error.SkipZigTest,
        };
        const primary_root = primary_backend.root_dir orelse return error.TestUnexpectedResult;
        const primary_obsolete_path = try lsm_backend_mod.repository.runPath(alloc, primary_root, 888_888);
        defer alloc.free(primary_obsolete_path);

        const dense_entry = db.core.index_manager.denseIndex("dv_v1") orelse return error.TestUnexpectedResult;
        const dense_backend = switch (dense_entry.index.env_owner) {
            .lsm => |*handle| handle.backend,
            else => return error.SkipZigTest,
        };
        const dense_root = dense_backend.root_dir orelse return error.TestUnexpectedResult;
        const dense_obsolete_path = try lsm_backend_mod.repository.runPath(alloc, dense_root, 999_999);
        defer alloc.free(dense_obsolete_path);

        try lsm_backend_mod.repository.writeFileAbsoluteWithStorage(primary_backend.storage.?, primary_obsolete_path, "primary obsolete");
        {
            const locked = lsm_backend_mod.runtime.lockBackend(lsm_backend_mod.Backend, primary_backend);
            defer lsm_backend_mod.runtime.unlockBackend(lsm_backend_mod.Backend, primary_backend, locked);
            try primary_backend.queueObsoleteFilePath(try alloc.dupe(u8, primary_obsolete_path));
            primary_backend.manifest_dirty = false;
        }

        try lsm_backend_mod.repository.writeFileAbsoluteWithStorage(dense_backend.storage.?, dense_obsolete_path, "dense obsolete");
        {
            const locked = lsm_backend_mod.runtime.lockBackend(lsm_backend_mod.Backend, dense_backend);
            defer lsm_backend_mod.runtime.unlockBackend(lsm_backend_mod.Backend, dense_backend, locked);
            try dense_backend.queueObsoleteFilePath(try alloc.dupe(u8, dense_obsolete_path));
            dense_backend.manifest_dirty = false;
        }

        try expectObsoletePathsReclaimable(primary_backend, 1);
        try expectObsoletePathsReclaimable(dense_backend, 1);

        _ = try db.runPrimaryLsmMaintenanceStep();

        try std.testing.expectEqual(@as(u64, 0), primary_backend.snapshotMaintenanceStats().obsolete_paths);
        try std.testing.expectError(error.FileNotFound, primary_backend.storage.?.readFileAlloc(alloc, primary_obsolete_path, 1024));
        try std.testing.expectEqual(@as(u64, 1), dense_backend.snapshotMaintenanceStats().obsolete_paths);
        const dense_bytes = try dense_backend.storage.?.readFileAlloc(alloc, dense_obsolete_path, 1024);
        alloc.free(dense_bytes);
    }

    pub fn batch(self: *DB, req: types.BatchRequest) anyerror!void {
        if (benchMetricsEnabled()) {
            var profile = BatchProfile{};
            try self.batchInternal(req, &profile, .{});
            logBatchProfile(req, profile);
        } else {
            try self.batchInternal(req, null, .{});
        }
    }

    pub fn batchWithVisibilityCancellation(self: *DB, req: types.BatchRequest, cancellation: types.CancellationToken) anyerror!void {
        if (benchMetricsEnabled()) {
            var profile = BatchProfile{};
            try self.batchInternal(req, &profile, .{ .visibility_cancellation = cancellation });
            logBatchProfile(req, profile);
        } else {
            try self.batchInternal(req, null, .{ .visibility_cancellation = cancellation });
        }
    }

    /// Applies a one-participant transaction through the ordinary atomic DB
    /// batch while preserving the distributed transaction's representability
    /// contract for transforms. This avoids durable 2PC bookkeeping without
    /// making graph-transform behavior depend on the current shard count.
    pub fn batchTransactionCompatible(self: *DB, req: types.BatchRequest) anyerror!void {
        try self.batchTransactionCompatibleWithVisibilityCancellation(req, .none);
    }

    pub fn batchTransactionCompatibleWithVisibilityCancellation(self: *DB, req: types.BatchRequest, cancellation: types.CancellationToken) anyerror!void {
        var compatible_req = req;
        compatible_req.reject_graph_transform_projections = true;
        if (benchMetricsEnabled()) {
            var profile = BatchProfile{};
            try self.batchInternal(compatible_req, &profile, .{ .visibility_cancellation = cancellation });
            logBatchProfile(compatible_req, profile);
        } else {
            try self.batchInternal(compatible_req, null, .{ .visibility_cancellation = cancellation });
        }
    }

    pub fn batchProfiled(self: *DB, req: types.BatchRequest, profile: *BatchProfile) anyerror!void {
        try self.batchInternal(req, profile, .{});
    }

    pub fn batchWithDocumentArtifactChildRangeDispatcher(
        self: *DB,
        req: types.BatchRequest,
        dispatcher: DocumentArtifactChildRangeDispatcher,
    ) anyerror!void {
        if (benchMetricsEnabled()) {
            var profile = BatchProfile{};
            try self.batchInternal(req, &profile, .{ .document_child_range_dispatcher = dispatcher });
            logBatchProfile(req, profile);
        } else {
            try self.batchInternal(req, null, .{ .document_child_range_dispatcher = dispatcher });
        }
    }

    fn projectedBatchLsmAdmissionBytes(req: types.BatchRequest) u64 {
        var payload_bytes: u64 = 0;
        var operations: u64 = 0;
        for (req.writes) |write| {
            payload_bytes +|= @intCast(write.key.len);
            payload_bytes +|= @intCast(write.value.len);
            operations +|= 1;
        }
        for (req.deletes) |key| {
            payload_bytes +|= @intCast(key.len);
            operations +|= 1;
        }
        for (req.transforms) |transform| {
            payload_bytes +|= @intCast(transform.key.len);
            operations +|= 1;
            for (transform.operations) |operation| {
                payload_bytes +|= @intCast(operation.path.len);
                if (operation.value_json) |value| payload_bytes +|= @intCast(value.len);
                operations +|= 1;
            }
        }
        for (req.graph_writes) |write| {
            payload_bytes +|= @intCast(write.index_name.len);
            payload_bytes +|= @intCast(write.source.len);
            payload_bytes +|= @intCast(write.target.len);
            payload_bytes +|= @intCast(write.edge_type.len);
            payload_bytes +|= @intCast(write.metadata_json.len);
            operations +|= 1;
        }
        for (req.graph_deletes) |delete| {
            payload_bytes +|= @intCast(delete.index_name.len);
            payload_bytes +|= @intCast(delete.source.len);
            payload_bytes +|= @intCast(delete.target.len);
            payload_bytes +|= @intCast(delete.edge_type.len);
            operations +|= 1;
        }
        for (req.predicates) |predicate| payload_bytes +|= @intCast(predicate.key.len);

        // Primary rows are accompanied by internal identity/timestamp/replay
        // records, allocator capacity, and the memtable hash index. Two times
        // encoded payload plus a per-operation allowance is deliberately a
        // conservative preflight; the backend still performs the exact guard
        // immediately before WAL append.
        return (payload_bytes *| 2) +| (operations *| 512);
    }

    pub fn drainDocumentArtifactChildRangeOutbox(
        self: *DB,
        dispatcher: DocumentArtifactChildRangeDispatcher,
        limit: usize,
    ) anyerror!DocumentArtifactChildRangeOutboxDrainResult {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        var ha_mutation = self.acquireHAMutationShared();
        defer if (ha_mutation) |*lease| lease.release();
        try self.enforceHAWriteGate();

        const prefix = try internal_keys.documentChildRangeOutboxRootPrefixAlloc(self.alloc);
        defer self.alloc.free(prefix);

        lockApply(self);
        var apply_mutex_held = true;
        errdefer if (apply_mutex_held) self.core.unlockApply();
        const scanned = try self.core.scanStorePrefix(self.alloc, prefix);
        self.core.unlockApply();
        apply_mutex_held = false;
        defer docstore_mod.DocStore.freeResults(self.alloc, scanned);

        var result = DocumentArtifactChildRangeOutboxDrainResult{};
        const max_entries = if (limit == 0 or limit > scanned.len) scanned.len else limit;
        for (scanned[0..max_entries]) |entry| {
            result.scanned += 1;
            var parsed = try std.json.parseFromSlice(DocumentArtifactChildRangeOutboxRecord, self.alloc, entry.value, .{
                .allocate = .alloc_always,
            });
            defer parsed.deinit();
            if (parsed.value.version != 1) return error.InvalidDocumentChildRangeOutboxRecord;
            try dispatcher.applyDispatch(self.alloc, .{
                .owner_group_id = parsed.value.owner_group_id,
                .doc_key = parsed.value.doc_key,
                .artifact_name = parsed.value.artifact_name,
                .child_batch = parsed.value.child_batch,
            });
            result.dispatched += 1;
            try self.deleteDocumentArtifactChildRangeOutboxEntry(entry.key);
            result.deleted += 1;
        }
        return result;
    }

    fn deleteDocumentArtifactChildRangeOutboxEntry(self: *DB, key: []const u8) !void {
        var ha_mutation = self.acquireHAMutationShared();
        defer if (ha_mutation) |*lease| lease.release();
        try self.enforceHAWriteGate();
        lockApply(self);
        defer self.core.unlockApply();
        const deletes = [_][]const u8{key};
        try self.core.store.putBatch(&.{}, deletes[0..]);
    }

    pub fn batchWithoutRangeValidation(self: *DB, req: types.BatchRequest) anyerror!void {
        try self.batchInternal(req, null, .{ .validate_range_ownership = false });
    }

    pub fn batchReplicatedApply(self: *DB, req: types.BatchRequest) anyerror!void {
        try self.batchReplicatedApplyWithMarker(req, null);
    }

    fn batchReplicatedApplyWithMarker(self: *DB, req: types.BatchRequest, applied_lsn_marker: ?u64) anyerror!void {
        var apply_req = req;
        apply_req.sync_level = .write;
        try self.batchInternal(apply_req, null, .{
            .validate_range_ownership = false,
            .wait_for_sync_level = false,
            .bypass_ha_write_gate = true,
            .ha_applied_lsn_marker = applied_lsn_marker,
        });
    }

    fn splitMarkerMatches(marker: range_state_mod.SplitBootstrapMarker, transition_id: u64, attempt_epoch: u64, source_group_id: u64, destination_group_id: u64) bool {
        return marker.transition_id == transition_id and
            marker.attempt_epoch == attempt_epoch and
            marker.source_group_id == source_group_id and
            marker.destination_group_id == destination_group_id;
    }

    /// Runs under the DB apply lock. False means the replicated operation was
    /// already durably applied and must not produce another document replay.
    fn shouldApplySplitReplicationLocked(self: *DB, req: types.BatchRequest) !bool {
        if (req.split_replication) |replication| {
            if (replication.transition_id == 0 or
                replication.attempt_epoch == 0 or
                replication.source_group_id == replication.destination_group_id)
            {
                return error.InvalidBatchRequest;
            }
            const marker = try self.core.loadSplitBootstrapMarker(self.alloc);
            switch (replication.operation) {
                .bootstrap_chunk => {
                    const bootstrap_sequence = replication.bootstrap_sequence orelse
                        return error.InvalidBatchRequest;
                    const existing = marker orelse return error.SplitBootstrapIncomplete;
                    if (!splitMarkerMatches(existing, replication.transition_id, replication.attempt_epoch, replication.source_group_id, replication.destination_group_id)) {
                        return error.ConflictingSplitTransition;
                    }
                    if (existing.bootstrap_complete) return false;
                    if (bootstrap_sequence != try self.core.loadSplitDeltaFinalSeq(self.alloc))
                        return error.StaleSplitBootstrap;
                },
                .delta => {
                    const complete = marker orelse return error.SplitBootstrapIncomplete;
                    if (!splitMarkerMatches(complete, replication.transition_id, replication.attempt_epoch, replication.source_group_id, replication.destination_group_id)) {
                        return error.ConflictingSplitTransition;
                    }
                    if (!complete.bootstrap_complete) return error.SplitBootstrapIncomplete;
                    if (replication.sequence == 0) return error.InvalidBatchRequest;
                    const applied = try self.core.loadSplitDeltaFinalSeq(self.alloc);
                    if (replication.sequence <= applied) return false;
                    if (replication.sequence != applied + 1) return error.SplitReplicationSequenceGap;
                },
                .checkpoint => {
                    const checkpoint = req.split_checkpoint orelse return error.MissingSplitReplicationCheckpoint;
                    if (checkpoint.kind == .source_ack or
                        checkpoint.transition_id != replication.transition_id or
                        checkpoint.attempt_epoch != replication.attempt_epoch or
                        checkpoint.source_group_id != replication.source_group_id or
                        checkpoint.destination_group_id != replication.destination_group_id or
                        checkpoint.delta_sequence != replication.sequence)
                    {
                        return error.InvalidBatchRequest;
                    }
                    if (replication.bootstrap_sequence) |bootstrap_sequence| {
                        if (bootstrap_sequence != checkpoint.delta_sequence) return error.StaleSplitBootstrap;
                    } else if (checkpoint.kind == .destination_begin) {
                        return error.InvalidBatchRequest;
                    }
                    if (marker) |existing| {
                        if (!splitMarkerMatches(existing, replication.transition_id, replication.attempt_epoch, replication.source_group_id, replication.destination_group_id)) {
                            return error.ConflictingSplitTransition;
                        }
                        const applied = try self.core.loadSplitDeltaFinalSeq(self.alloc);
                        if (checkpoint.delta_sequence > applied) return error.SplitReplicationSequenceGap;
                        if (checkpoint.kind == .destination_begin or existing.bootstrap_complete) return false;
                    } else if (checkpoint.kind == .destination_complete) {
                        return error.SplitBootstrapIncomplete;
                    }
                },
            }
        } else if (req.split_checkpoint) |checkpoint| {
            if (checkpoint.kind != .source_ack or checkpoint.transition_id == 0) return error.MissingSplitReplicationContext;
            if (try self.core.loadSplitBootstrapMarker(self.alloc)) |marker| {
                if (!splitMarkerMatches(marker, checkpoint.transition_id, checkpoint.attempt_epoch, checkpoint.source_group_id, checkpoint.destination_group_id)) {
                    return error.ConflictingSplitTransition;
                }
                if (checkpoint.delta_sequence <= try self.core.loadSplitDeltaFinalSeq(self.alloc)) return false;
            }
        }
        return true;
    }

    fn setSchemaReplicatedApplyWithMarker(self: *DB, table_schema: schema_mod.TableSchema, applied_lsn_marker: ?u64) anyerror!void {
        try self.core.setSchema(table_schema);
        if (applied_lsn_marker) |lsn| try self.markHAReplicationRecordApplied(lsn);
    }

    pub fn applyHAReplicationRecord(self: *DB, record: ha_replication_record_mod.RecordView) anyerror!void {
        if (try self.haReplicationRecordAlreadyApplied(record)) return;

        switch (record.kind) {
            .batch_mutation => {
                var decoded = try ha_effects_mod.decodeBatchMutationRequest(self.alloc, record);
                defer decoded.deinit();
                try self.batchReplicatedApplyWithMarker(decoded.value.request, record.lsn);
            },
            .metadata_mutation => {
                const decoded_schema = try ha_effects_mod.decodeSchemaMetadataMutation(self.alloc, record);
                defer schema_mod.freeSchema(self.alloc, decoded_schema);
                try self.setSchemaReplicatedApplyWithMarker(decoded_schema, record.lsn);
            },
            .derived_effect => {
                _ = try self.applyHADerivedEffectRecord(record);
                try self.markHAReplicationRecordApplied(record.lsn);
            },
            .backup_start,
            .backup_end,
            .checkpoint,
            .manifest,
            .truncate,
            .timeline_switch,
            => try self.markHAReplicationRecordApplied(record.lsn),
            _ => return error.HAReplicationRecordApplyUnsupported,
        }
    }

    pub fn applyHADerivedEffectRecord(self: *DB, record: ha_replication_record_mod.RecordView) anyerror!u64 {
        var ctx = self.batchContext();
        return try appendReplicatedHADerivedEffectContext(&ctx, record);
    }

    pub fn haAppliedReplicationLsn(self: *DB) anyerror!u64 {
        return try readHAAppliedReplicationLsn(self.alloc, self.core.store);
    }

    fn haReplicationRecordAlreadyApplied(self: *DB, record: ha_replication_record_mod.RecordView) !bool {
        if (record.lsn == 0) return false;
        return (try self.haAppliedReplicationLsn()) >= record.lsn;
    }

    fn markHAReplicationRecordApplied(self: *DB, lsn: u64) !void {
        if (lsn == 0) return;
        const current = try self.haAppliedReplicationLsn();
        if (current >= lsn) return;
        var value_buf: [ha_applied_lsn_value_len]u8 = undefined;
        const marker = haAppliedReplicationLsnWrite(lsn, &value_buf);
        try self.core.store.putBatch(&.{marker}, &.{});
    }

    pub fn applyHAReplicationRecordCallback(ctx: *anyopaque, record: ha_replication_record_mod.RecordView) anyerror!void {
        const self: *DB = @ptrCast(@alignCast(ctx));
        try self.applyHAReplicationRecord(record);
    }

    pub fn applyDocumentArtifactChildRangeBatch(self: *DB, child_batch: DocumentArtifactChildRangeApplyBatch) anyerror!u64 {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        var ha_mutation = self.acquireHAMutationShared();
        defer if (ha_mutation) |*lease| lease.release();
        try self.enforceHAWriteGate();
        if (child_batch.artifact_writes.len == 0 and
            child_batch.artifact_delete_keys.len == 0 and
            child_batch.documents.len == 0 and
            child_batch.dense_embeddings.len == 0 and
            child_batch.sparse_embeddings.len == 0 and
            child_batch.generated_enrichment_refs.len == 0)
        {
            return 0;
        }

        try self.executor.failIfUnhealthy();

        lockApply(self);
        var apply_mutex_held = true;
        errdefer if (apply_mutex_held) self.core.unlockApply();

        var store_writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
        defer store_writes.deinit(self.alloc);
        var delete_keys = std.ArrayListUnmanaged([]const u8).empty;
        defer delete_keys.deinit(self.alloc);
        var owned_store_keys = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (owned_store_keys.items) |key| self.alloc.free(key);
            owned_store_keys.deinit(self.alloc);
        }
        var owned_store_values = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (owned_store_values.items) |value| self.alloc.free(value);
            owned_store_values.deinit(self.alloc);
        }
        var owned_delete_keys = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (owned_delete_keys.items) |key| self.alloc.free(key);
            owned_delete_keys.deinit(self.alloc);
        }
        var changed_artifact_keys = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (changed_artifact_keys.items) |key| self.alloc.free(key);
            changed_artifact_keys.deinit(self.alloc);
        }
        var materialized_graph_artifact_writes = std.ArrayListUnmanaged(types.BatchWrite).empty;
        defer {
            for (materialized_graph_artifact_writes.items) |write| {
                self.alloc.free(@constCast(write.key));
                self.alloc.free(@constCast(write.value));
            }
            materialized_graph_artifact_writes.deinit(self.alloc);
        }

        for (child_batch.artifact_writes) |write| {
            try store_writes.append(self.alloc, .{
                .key = write.key,
                .value = write.value,
            });
            try appendUniqueOwnedKey(self.alloc, &changed_artifact_keys, write.key);
        }
        for (child_batch.artifact_delete_keys) |key| {
            try delete_keys.append(self.alloc, key);
            if (internal_keys.isAssetArtifactKey(key) or internal_keys.isGraphEdgeArtifactKey(key)) {
                try appendUniqueOwnedKey(self.alloc, &changed_artifact_keys, key);
            }
        }

        try appendPrecomputedGraphSourceArtifacts(
            self,
            child_batch.artifact_writes,
            child_batch.artifact_delete_keys,
            &materialized_graph_artifact_writes,
            &store_writes,
            &delete_keys,
            &owned_delete_keys,
            &changed_artifact_keys,
        );

        if (child_batch.artifact_writes.len > 0 or materialized_graph_artifact_writes.items.len > 0) {
            try self.core.appendArtifactPresenceMarker(&store_writes);
        }
        try appendAssetArtifactSourceIndexMutations(
            self.alloc,
            &store_writes,
            child_batch.artifact_delete_keys,
            &delete_keys,
            &owned_store_keys,
            &owned_store_values,
            &owned_delete_keys,
        );

        const sequence = self.core.reserveDerivedAppendSequence();
        const derived_seed = derived_types.DerivedBatch{
            .sequence = sequence,
            .documents = child_batch.documents,
            .deleted_keys = child_batch.artifact_delete_keys,
            .changed_artifact_keys = changed_artifact_keys.items,
            .dense_embeddings = child_batch.dense_embeddings,
            .sparse_embeddings = child_batch.sparse_embeddings,
            .generated_enrichment_refs = child_batch.generated_enrichment_refs,
        };
        var derived_batch = try derived_types.cloneBatch(self.alloc, derived_seed);
        defer derived_types.deinitDerivedBatch(self.alloc, &derived_batch);
        derived_batch.sequence = sequence;

        var sync_targets = try collectManagedSyncTargets(self.alloc, self.core.index_manager, derived_batch);
        defer sync_targets.deinit(self.alloc);
        const replay_payload = try encodeChangeRecordPayload(&self.batchContext(), derived_batch, sequence);
        defer self.alloc.free(replay_payload);

        try appendDenseArtifactCounterMutations(
            self.alloc,
            self.core.store,
            self.core.index_manager,
            &store_writes,
            delete_keys.items,
            &owned_store_keys,
            &owned_store_values,
        );
        try self.core.store.putBatchWithReplay(
            self.backend_runtime.io(),
            store_writes.items,
            delete_keys.items,
            .{
                .sequence = sequence,
                .payload = replay_payload,
            },
        );
        self.mirrorHAReplayPayloadBestEffort(replay_payload);
        if (shouldAppendSplitDelta(self)) {
            try self.core.appendSplitDelta(currentTimeNs(), store_writes.items, delete_keys.items);
        }

        self.executor.trackBacklogBytes(sequence, @intCast(replay_payload.len)) catch {};
        self.core.unlockApply();
        apply_mutex_held = false;

        var pressure_ctx = self.batchContext();
        try self.markPrecomputedEnrichmentAppliedForSync(child_batch.sync_level, sequence);
        try applyDerivedBacklogPressureContext(&pressure_ctx, sequence, child_batch.sync_level, sync_targets);
        if (self.executor.hasWorkers()) {
            notifyExecutorForSyncLevelWithDenseBulkDeferral(self.async_context, self.executor, child_batch.sync_level, sequence, sync_targets);
            try self.waitForSyncLevel(child_batch.sync_level, sequence, sync_targets);
        } else {
            if (syncLevelRequiresDerivedVisibility(child_batch.sync_level)) {
                if (child_batch.sync_level == .full_text) {
                    try applyDerivedBatchTargetsProfiled(self, derived_batch, sync_targets.full_text_indexes, null);
                } else {
                    try applyDerivedBatchProfiled(self, derived_batch, null);
                }
            }
            try self.waitForSyncLevel(child_batch.sync_level, sequence, sync_targets);
        }
        if (self.enrichment_runtime) |runtime| runtime.notifySequence(sequence);
        self.notifyResolverReplayRuntimes(sequence);
        return sequence;
    }

    fn batchInternal(self: *DB, req: types.BatchRequest, profile: ?*BatchProfile, opts: BatchExecutionOptions) anyerror!void {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        if (!opts.bypass_ha_write_gate and self.denseRepairWriteBackpressured()) return error.DenseRepairBackpressure;
        var ha_mutation = if (opts.bypass_ha_write_gate) null else self.acquireHAMutationShared();
        defer if (ha_mutation) |*lease| lease.release();
        if (!opts.bypass_ha_write_gate) try self.enforceHAWriteGate();
        if (!opts.bypass_ha_write_gate) try self.preflightHABatchSyncCommit();
        const total_start_ns = monotonicTimeNs();
        defer {
            if (profile) |active_profile| {
                active_profile.total_ns += monotonicTimeNs() - total_start_ns;
            }
        }

        try self.executor.failIfUnhealthy();

        // Global LSM throttling must happen before the DB apply lock. Derived
        // and maintenance workers may need that lock to publish or flush the
        // state that releases aggregate pressure. The backend commit performs
        // the final projected check before WAL append, so this non-reserving
        // preflight is an early wait, not the durability guard.
        if (self.core.index_manager.resource_manager) |manager| {
            try manager.awaitAdmission(.lsm_in_memory_state, projectedBatchLsmAdmissionBytes(req));
        }

        lockApply(self);
        var apply_mutex_held = true;
        errdefer if (apply_mutex_held) self.core.unlockApply();

        if (opts.transaction_resolution) |resolution| {
            const intent_snapshot = try self.core.validateTransactionIntentSnapshot(
                resolution.txn_id,
                resolution.expected_intent_revision,
            );
            if (!intent_snapshot.has_intents) {
                // Validate the requested decision while still avoiding mapper
                // and index preparation on an idempotent resolve retry.
                const outcome = try self.core.resolveTransactionIntentsWithExtraBatch(
                    resolution.txn_id,
                    resolution.status,
                    resolution.commit_version,
                    .{
                        .expected_intent_revision = resolution.expected_intent_revision,
                        .known_intent_keys = resolution.intent_keys,
                    },
                );
                self.core.unlockApply();
                apply_mutex_held = false;
                if (!opts.bypass_ha_write_gate) try self.flushTransactionHAOutbox(resolution.txn_id);
                try self.waitForResolvedTransactionSync(req.sync_level, outcome.replay_sequence);
                return;
            }
        }

        if (self.bulk_ingest_coalescer.active and !self.flushing_bulk_ingest_coalescer) {
            if (self.bulk_ingest_coalescer.hasPending()) {
                self.core.unlockApply();
                apply_mutex_held = false;
                try self.flushBulkIngestCoalescerWithSyncLevel(req.sync_level, profile);
                lockApply(self);
                apply_mutex_held = true;
            }
        }

        if (!try self.shouldApplySplitReplicationLocked(req)) {
            self.core.unlockApply();
            return;
        }

        const resolve_transforms_start_ns = monotonicTimeNs();
        var effective_ops = try coalesceKeyValueRequest(self, types.BatchWrite, req.writes, req.deletes, req.transforms);
        defer effective_ops.deinit(self.alloc);
        if (profile) |active_profile| recordProfileNs(profile, &active_profile.resolve_transforms_ns, resolve_transforms_start_ns);

        // Transaction intents carry primary key/value rows but not projected
        // graph deltas. Evaluate this after transform expansion so absent
        // non-upsert documents retain their established no-op semantics, and
        // before any request mutation is persisted.
        if (req.reject_graph_transform_projections and effective_ops.graph_writes.items.len != 0) {
            return error.UnsupportedTransformOperation;
        }

        const merge_effective_req_start_ns = monotonicTimeNs();

        var owned_effective_graph_writes: ?[]types.GraphEdgeWrite = null;
        defer if (owned_effective_graph_writes) |owned| self.alloc.free(owned);
        const effective_graph_writes = if (effective_ops.graph_writes.items.len == 0)
            req.graph_writes
        else blk: {
            const combined = try self.alloc.alloc(types.GraphEdgeWrite, req.graph_writes.len + effective_ops.graph_writes.items.len);
            @memcpy(combined[0..req.graph_writes.len], req.graph_writes);
            @memcpy(combined[req.graph_writes.len..], effective_ops.graph_writes.items);
            owned_effective_graph_writes = combined;
            break :blk combined;
        };

        const effective_req: types.BatchRequest = .{
            .writes = effective_ops.writes,
            .deletes = effective_ops.deletes,
            .graph_writes = effective_graph_writes,
            .graph_deletes = req.graph_deletes,
            .transforms = &.{},
            .predicates = req.predicates,
            .timestamp_ns = req.timestamp_ns,
            .sync_level = req.sync_level,
        };
        if (profile) |active_profile| recordProfileNs(profile, &active_profile.merge_effective_req_ns, merge_effective_req_start_ns);

        // Prepared transaction intents fence the ordinary single-group fast
        // path too. The key-oriented intent index keeps this O(touched keys)
        // instead of scanning every outstanding transaction.
        if (opts.transaction_resolution == null) {
            try self.core.checkOrdinaryWriteConflicts(effective_ops.writes, effective_ops.deletes);
        }

        if (effective_req.predicates.len > 0) {
            const predicates_start_ns = monotonicTimeNs();
            var predicates = std.ArrayListUnmanaged(transactions_mod.VersionPredicate).empty;
            defer predicates.deinit(self.alloc);
            for (effective_req.predicates) |predicate| {
                try predicates.append(self.alloc, .{
                    .key = predicate.key,
                    .expected_version = predicate.expected_version,
                });
            }
            try self.core.checkVersionPredicates(predicates.items, null);
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.predicates_ns, predicates_start_ns);
        }

        if (opts.validate_range_ownership) {
            const validate_range_start_ns = monotonicTimeNs();
            try self.core.validateBatchRangeOwnership(effective_req);
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.validate_range_ns, validate_range_start_ns);
        }

        const extract_writes_start_ns = monotonicTimeNs();
        var extracted = try self.alloc.alloc(mapper.ExtractedWrite, effective_req.writes.len);
        var extracted_initialized: usize = 0;
        defer {
            for (extracted[0..extracted_initialized]) |*item| item.deinit(self.alloc);
            self.alloc.free(extracted);
        }

        var store_writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
        defer store_writes.deinit(self.alloc);
        var owned_store_keys = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (owned_store_keys.items) |key| self.alloc.free(key);
            owned_store_keys.deinit(self.alloc);
        }
        var owned_store_values = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (owned_store_values.items) |value| self.alloc.free(value);
            owned_store_values.deinit(self.alloc);
        }
        const vector_field_names_start_ns = monotonicTimeNs();
        const vector_store_field_names = try self.core.index_manager.vectorStoreFieldNamesAlloc(self.alloc);
        if (profile) |active_profile| recordProfileNs(profile, &active_profile.extract_vector_field_names_ns, vector_field_names_start_ns);
        defer {
            for (vector_store_field_names) |field| self.alloc.free(field);
            if (vector_store_field_names.len > 0) self.alloc.free(vector_store_field_names);
        }
        var timestamp_writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
        defer {
            for (timestamp_writes.items) |item| {
                self.alloc.free(@constCast(item.key));
                self.alloc.free(@constCast(item.value));
            }
            timestamp_writes.deinit(self.alloc);
        }
        var explicit_embedding_artifact_writes = std.ArrayListUnmanaged(types.BatchWrite).empty;
        defer {
            for (explicit_embedding_artifact_writes.items) |item| {
                self.alloc.free(@constCast(item.key));
                self.alloc.free(@constCast(item.value));
            }
            explicit_embedding_artifact_writes.deinit(self.alloc);
        }
        var explicit_graph_artifact_writes = std.ArrayListUnmanaged(types.BatchWrite).empty;
        defer {
            for (explicit_graph_artifact_writes.items) |item| {
                self.alloc.free(@constCast(item.key));
                self.alloc.free(@constCast(item.value));
            }
            explicit_graph_artifact_writes.deinit(self.alloc);
        }
        var delete_keys = std.ArrayListUnmanaged([]const u8).empty;
        defer delete_keys.deinit(self.alloc);
        var owned_delete_keys = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (owned_delete_keys.items) |key| self.alloc.free(key);
            owned_delete_keys.deinit(self.alloc);
        }
        var graph_artifact_clears = std.ArrayListUnmanaged(GraphArtifactClear).empty;
        defer {
            for (graph_artifact_clears.items) |*item| item.deinit(self.alloc);
            graph_artifact_clears.deinit(self.alloc);
        }
        var timestamp_delete_keys = std.ArrayListUnmanaged([]const u8).empty;
        defer {
            for (timestamp_delete_keys.items) |key| self.alloc.free(@constCast(key));
            timestamp_delete_keys.deinit(self.alloc);
        }
        var overwritten_flags = try self.alloc.alloc(bool, effective_req.writes.len);
        defer self.alloc.free(overwritten_flags);
        @memset(overwritten_flags, false);
        var derived_changed_flags = try self.alloc.alloc(bool, effective_req.writes.len);
        defer self.alloc.free(derived_changed_flags);
        @memset(derived_changed_flags, true);
        var overwrite_probe_entries = std.ArrayListUnmanaged(OverwriteProbeEntry).empty;
        defer overwrite_probe_entries.deinit(self.alloc);
        var identity_upsert_keys = std.ArrayListUnmanaged([]const u8).empty;
        defer identity_upsert_keys.deinit(self.alloc);
        var identity_upsert_write_indexes = std.ArrayListUnmanaged(usize).empty;
        defer identity_upsert_write_indexes.deinit(self.alloc);
        var identity_writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
        defer {
            for (identity_writes.items) |item| {
                self.alloc.free(@constCast(item.key));
                self.alloc.free(@constCast(item.value));
            }
            identity_writes.deinit(self.alloc);
        }
        var identity_visibility_deletes = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (identity_visibility_deletes.items) |key| self.alloc.free(key);
            identity_visibility_deletes.deinit(self.alloc);
        }

        const batch_timestamp_ns = if (effective_req.timestamp_ns != 0) effective_req.timestamp_ns else currentTimeNs();

        for (effective_req.writes, 0..) |write, i| {
            if (isMetadataKey(write.key)) {
                extracted[i] = .{
                    .cleaned_value = null,
                    .graph_writes = &.{},
                    .mentioned_graph_indexes = &.{},
                    .dense_embeddings = &.{},
                    .sparse_embeddings = &.{},
                };
                extracted_initialized += 1;
                try store_writes.append(self.alloc, .{
                    .key = write.key,
                    .value = write.value,
                });
                continue;
            }
            const mapper_extract_start_ns = monotonicTimeNs();
            extracted[i] = try mapper.extractWrite(self.alloc, write.key, write.value);
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.extract_mapper_ns, mapper_extract_start_ns);
            const graph_field_extract_start_ns = monotonicTimeNs();
            try augmentExtractedWriteWithGraphFieldEdges(self, self.alloc, write.key, write.value, &extracted[i]);
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.extract_graph_fields_ns, graph_field_extract_start_ns);
            const index_field_embeddings_start_ns = monotonicTimeNs();
            try self.core.index_manager.appendIndexFieldEmbeddingsToExtractedWrite(self.alloc, write.key, write.value, &extracted[i]);
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.extract_index_field_embeddings_ns, index_field_embeddings_start_ns);
            extracted_initialized += 1;
            const embedding_artifacts_start_ns = monotonicTimeNs();
            for (extracted[i].dense_embeddings) |*embedding| {
                if (embedding.artifact_key != null) continue;
                embedding.artifact_key = try appendEmbeddingArtifactWrite(
                    self.alloc,
                    &explicit_embedding_artifact_writes,
                    write.key,
                    write.key,
                    embedding.index_name,
                    "_embeddings",
                    null,
                    null,
                    embedding.vector,
                );
            }
            for (extracted[i].sparse_embeddings) |*embedding| {
                if (embedding.artifact_key != null) continue;
                embedding.artifact_key = try appendSparseEmbeddingArtifactWrite(
                    self.alloc,
                    &explicit_embedding_artifact_writes,
                    write.key,
                    embedding.index_name,
                    null,
                    embedding.indices,
                    embedding.values,
                );
            }
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.extract_embedding_artifacts_ns, embedding_artifacts_start_ns);
            const graph_artifacts_start_ns = monotonicTimeNs();
            for (extracted[i].graph_writes) |graph_write| {
                const generation = (self.core.index_manager.graphIndex(graph_write.index_name) orelse return error.IndexNotFound).config.coverage_generation;
                try appendGraphEdgeArtifactWrite(self.alloc, &explicit_graph_artifact_writes, graph_write, generation);
            }
            for (extracted[i].mentioned_graph_indexes) |index_name| {
                try graph_artifact_clears.append(self.alloc, .{
                    .doc_key = try self.alloc.dupe(u8, write.key),
                    .index_name = try self.alloc.dupe(u8, index_name),
                });
            }
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.extract_graph_artifacts_ns, graph_artifacts_start_ns);
            if (extracted[i].cleaned_value) |cleaned| {
                try validateDocumentExtractionInlineSources(self, cleaned);
                const strip_store_value_start_ns = monotonicTimeNs();
                const store_value = try strippedStoredDocumentValueAlloc(
                    self.alloc,
                    cleaned,
                    vector_store_field_names,
                    &owned_store_values,
                );
                if (profile) |active_profile| recordProfileNs(profile, &active_profile.extract_strip_store_value_ns, strip_store_value_start_ns);
                const store_key = try internal_keys.documentKeyAlloc(self.alloc, write.key);
                try owned_store_keys.append(self.alloc, store_key);
                try overwrite_probe_entries.append(self.alloc, .{
                    .key = store_key,
                    .value = store_value,
                    .write_index = i,
                });
                try store_writes.append(self.alloc, .{
                    .key = store_key,
                    .value = store_value,
                });
                try identity_upsert_keys.append(self.alloc, write.key);
                try identity_upsert_write_indexes.append(self.alloc, i);
                if (shouldWriteTimestamp(write.key)) {
                    const timestamp_start_ns = monotonicTimeNs();
                    const write_timestamp_ns = try resolveWriteTimestampNs(self, batch_timestamp_ns, write.value);
                    const timestamp_key = try makeTimestampKey(self.alloc, write.key);
                    const timestamp_value = try encodeTimestampValue(self.alloc, write_timestamp_ns);
                    try timestamp_writes.append(self.alloc, .{
                        .key = timestamp_key,
                        .value = timestamp_value,
                    });
                    if (profile) |active_profile| recordProfileNs(profile, &active_profile.extract_timestamp_ns, timestamp_start_ns);
                }
            }
        }
        if (profile) |active_profile| {
            active_profile.identity_upsert_keys += @intCast(identity_upsert_keys.items.len);
            active_profile.identity_delete_keys += @intCast(effective_req.deletes.len);
        }
        const identity_capacity_start_ns = monotonicTimeNs();
        if (!self.bulk_ingest_identity_all_new or effective_req.deletes.len != 0) {
            try self.failIfIdentityOrdinalExhaustedForNewUpserts(identity_upsert_keys.items);
        }
        if (profile) |active_profile| recordProfileNs(profile, &active_profile.identity_capacity_check_ns, identity_capacity_start_ns);

        var assume_all_new_identity_upserts = false;
        if (self.bulk_ingest_identity_all_new and effective_req.deletes.len == 0 and identity_upsert_keys.items.len > 0) {
            assume_all_new_identity_upserts = try self.rememberBulkIngestAllNewIdentityUpserts(identity_upsert_keys.items);
            if (!assume_all_new_identity_upserts) self.clearBulkIngestIdentityAllNewLocked();
        }

        if (!assume_all_new_identity_upserts and overwrite_probe_entries.items.len > 0) {
            const overwrite_probe_start_ns = monotonicTimeNs();
            const unchanged_derived_targets_serviceable = try self.unchangedDerivedReplayTargetsServiceable(self.alloc);
            std.sort.pdq(OverwriteProbeEntry, overwrite_probe_entries.items, {}, overwriteProbeLessThan);
            const probe_keys = try self.alloc.alloc([]const u8, overwrite_probe_entries.items.len);
            defer self.alloc.free(probe_keys);
            const probe_values = try self.alloc.alloc(?[]const u8, overwrite_probe_entries.items.len);
            defer self.alloc.free(probe_values);
            for (overwrite_probe_entries.items, 0..) |entry, i| {
                probe_keys[i] = entry.key;
            }
            var overwrite_probe_txn = try self.core.store.beginProbeTxn();
            defer overwrite_probe_txn.abort();
            try overwrite_probe_txn.getManySorted(probe_keys, probe_values);
            for (overwrite_probe_entries.items, 0..) |entry, i| {
                const existing = probe_values[i] orelse continue;
                overwritten_flags[entry.write_index] = true;
                const extracted_write = extracted[entry.write_index];
                if (unchanged_derived_targets_serviceable and
                    storedDocumentValuesEqual(self.alloc, existing, entry.value) and
                    extracted_write.dense_embeddings.len == 0 and
                    extracted_write.sparse_embeddings.len == 0 and
                    extracted_write.graph_writes.len == 0 and
                    extracted_write.mentioned_graph_indexes.len == 0)
                {
                    derived_changed_flags[entry.write_index] = false;
                }
            }
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.overwrite_probe_ns, overwrite_probe_start_ns);
        }

        // A semantic no-op may avoid rewriting the primary document and
        // derived journal. Keep its timestamp write: timestamps are observable
        // write metadata and, when a TTL field is absent, define the document's
        // expiry baseline. This preserves logical-write and TTL-refresh
        // semantics without paying the much larger source/derived replay cost.
        for (overwrite_probe_entries.items) |entry| {
            if (derived_changed_flags[entry.write_index]) continue;
            removePendingStoreWriteByKey(&store_writes, entry.key);
        }

        for (effective_req.graph_writes) |graph_write| {
            const generation = (self.core.index_manager.graphIndex(graph_write.index_name) orelse return error.IndexNotFound).config.coverage_generation;
            try appendGraphEdgeArtifactWrite(self.alloc, &explicit_graph_artifact_writes, graph_write, generation);
        }

        var changed_graph_artifact_keys = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (changed_graph_artifact_keys.items) |key| self.alloc.free(key);
            changed_graph_artifact_keys.deinit(self.alloc);
        }
        for (graph_artifact_clears.items) |clear| {
            const existing = try collectGraphArtifactsForDocIndex(self.alloc, self.core.store, clear.doc_key, clear.index_name);
            defer docstore_mod.DocStore.freeResults(self.alloc, existing);
            for (existing) |entry| {
                if (containsBatchWriteKey(explicit_graph_artifact_writes.items, entry.key)) continue;
                if (containsOwnedKey(owned_delete_keys.items, entry.key)) continue;
                const owned_key = try self.alloc.dupe(u8, entry.key);
                try owned_delete_keys.append(self.alloc, owned_key);
                try delete_keys.append(self.alloc, owned_key);
                try appendUniqueOwnedKey(self.alloc, &changed_graph_artifact_keys, entry.key);
            }
        }

        try store_writes.appendSlice(self.alloc, timestamp_writes.items);
        for (explicit_embedding_artifact_writes.items) |write| {
            try store_writes.append(self.alloc, .{
                .key = write.key,
                .value = write.value,
            });
        }
        for (explicit_graph_artifact_writes.items) |write| {
            try store_writes.append(self.alloc, .{
                .key = write.key,
                .value = write.value,
            });
            try appendUniqueOwnedKey(self.alloc, &changed_graph_artifact_keys, write.key);
        }
        for (effective_req.graph_deletes) |delete| {
            const artifact_key = try internal_keys.graphEdgeArtifactKeyAlloc(self.alloc, delete.source, delete.index_name, delete.edge_type, delete.target);
            defer self.alloc.free(artifact_key);
            if (containsBatchWriteKey(explicit_graph_artifact_writes.items, artifact_key)) continue;
            if (containsOwnedKey(owned_delete_keys.items, artifact_key)) continue;
            const owned_key = try self.alloc.dupe(u8, artifact_key);
            try owned_delete_keys.append(self.alloc, owned_key);
            try delete_keys.append(self.alloc, owned_key);
            try appendUniqueOwnedKey(self.alloc, &changed_graph_artifact_keys, artifact_key);
        }
        for (effective_req.deletes) |key| {
            const store_key = try internal_keys.documentKeyAlloc(self.alloc, key);
            try owned_delete_keys.append(self.alloc, store_key);
            try delete_keys.append(self.alloc, store_key);
            if (shouldWriteTimestamp(key)) {
                const timestamp_key = try makeTimestampKey(self.alloc, key);
                try timestamp_delete_keys.append(self.alloc, timestamp_key);
                try delete_keys.append(self.alloc, timestamp_key);
            }
        }
        if (profile) |active_profile| recordProfileNs(profile, &active_profile.extract_writes_ns, extract_writes_start_ns);

        const delete_artifacts_start_ns = monotonicTimeNs();
        const deleted_artifact_keys = try collectEnrichmentArtifactDeletesForBatch(
            self,
            effective_req,
            extracted[0..extracted_initialized],
            &delete_keys,
            &owned_delete_keys,
        );
        defer self.alloc.free(deleted_artifact_keys);
        if (profile) |active_profile| recordProfileNs(profile, &active_profile.delete_artifacts_ns, delete_artifacts_start_ns);

        const use_thin_replay_fast_path =
            effective_req.sync_level != .full_text and
            effective_req.sync_level != .enrichments and
            effective_req.sync_level != .full_index and
            !splitShadowRequiresMaterializedDerivedBatch(self);
        const include_generated_enrichment_hint = use_thin_replay_fast_path and
            self.core.hasGeneratedEnrichmentTargets();

        var precomputed_generated: PrecomputedGeneratedBatch = .{};
        defer precomputed_generated.deinit(self.alloc);
        var remote_child_range_dispatches = std.ArrayListUnmanaged(DocumentChildRangeDispatchGroup).empty;
        defer {
            for (remote_child_range_dispatches.items) |*dispatch| dispatch.deinit(self.alloc);
            remote_child_range_dispatches.deinit(self.alloc);
        }
        var owned_child_range_outbox_keys = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (owned_child_range_outbox_keys.items) |key| self.alloc.free(key);
            owned_child_range_outbox_keys.deinit(self.alloc);
        }
        var owned_child_range_outbox_values = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (owned_child_range_outbox_values.items) |value| self.alloc.free(value);
            owned_child_range_outbox_values.deinit(self.alloc);
        }
        var materialized_graph_artifact_writes = std.ArrayListUnmanaged(types.BatchWrite).empty;
        defer {
            for (materialized_graph_artifact_writes.items) |write| {
                self.alloc.free(@constCast(write.key));
                self.alloc.free(@constCast(write.value));
            }
            materialized_graph_artifact_writes.deinit(self.alloc);
        }
        if (!use_thin_replay_fast_path) {
            const precompute_generated_start_ns = monotonicTimeNs();
            precomputed_generated = try prepareGeneratedEnrichments(
                self,
                effective_req,
                extracted[0..extracted_initialized],
                generatedPrecomputeModeForSyncLevel(effective_req.sync_level),
                opts.force_generated_artifact_names,
            );

            if (opts.document_child_range_dispatcher != null) {
                try partitionRemoteDocumentChildRangeGeneratedBatch(self, &precomputed_generated, &remote_child_range_dispatches);
            }

            for (precomputed_generated.artifact_writes) |write| {
                try store_writes.append(self.alloc, .{
                    .key = write.key,
                    .value = write.value,
                });
                try appendUniqueOwnedKey(self.alloc, &changed_graph_artifact_keys, write.key);
            }
            for (precomputed_generated.artifact_delete_keys) |key| {
                try delete_keys.append(self.alloc, key);
                if (internal_keys.isAssetArtifactKey(key)) {
                    try appendUniqueOwnedKey(self.alloc, &changed_graph_artifact_keys, key);
                }
            }
            try appendPrecomputedGraphSourceArtifacts(
                self,
                precomputed_generated.artifact_writes,
                precomputed_generated.artifact_delete_keys,
                &materialized_graph_artifact_writes,
                &store_writes,
                &delete_keys,
                &owned_delete_keys,
                &changed_graph_artifact_keys,
            );
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.precompute_generated_ns, precompute_generated_start_ns);
        }
        if (explicit_embedding_artifact_writes.items.len > 0 or
            explicit_graph_artifact_writes.items.len > 0 or
            materialized_graph_artifact_writes.items.len > 0 or
            precomputed_generated.artifact_writes.len > 0)
        {
            try self.core.appendArtifactPresenceMarker(&store_writes);
        }
        try appendAssetArtifactSourceIndexMutations(
            self.alloc,
            &store_writes,
            deleted_artifact_keys,
            &delete_keys,
            &owned_store_keys,
            &owned_store_values,
            &owned_delete_keys,
        );

        var sync_targets: ManagedSyncTargets = .{};
        defer sync_targets.deinit(self.alloc);
        var materialized_derived_batch: ?derived_types.DerivedBatch = null;
        defer if (materialized_derived_batch) |*materialized_batch| derived_types.deinitDerivedBatch(self.alloc, materialized_batch);
        // An exact source retry that only refreshes timestamp metadata has no
        // derived visibility transition. Reuse the current committed fence
        // instead of reserving a sequence that would either be lost (and make
        // the in-memory generation move backwards after restart) or require a
        // synthetic replay item that every managed consumer must drain.
        const elide_semantic_noop_replay = use_thin_replay_fast_path and
            opts.extra_store_writes.len == 0 and
            opts.transaction_resolution == null and
            opts.ha_applied_lsn_marker == null and
            !thinReplayInputsHaveDerivedWork(
                effective_req,
                deleted_artifact_keys,
                changed_graph_artifact_keys.items,
                derived_changed_flags,
            );
        const sequence = if (elide_semantic_noop_replay)
            self.core.nextDerivedSequence()
        else
            self.core.reserveDerivedAppendSequence();
        const identity_metadata_start_ns = monotonicTimeNs();
        const identity_live_before = if (identity_upsert_keys.items.len != 0 or effective_req.deletes.len != 0)
            (try doc_identity.fastStatsFromStore(self.core.store)).live_ordinals
        else
            0;
        var used_trusted_identity_path = false;
        if (effective_req.deletes.len != 0) {
            self.clearBulkIngestIdentityAllNewLocked();
        }
        if (self.bulk_ingest_identity_all_new and
            effective_req.deletes.len == 0 and
            identity_upsert_keys.items.len > 0 and
            (assume_all_new_identity_upserts or identityUpsertStoreWritesAreNew(identity_upsert_write_indexes.items, overwritten_flags)))
        {
            used_trusted_identity_path = try doc_identity.appendBatchIdentityMetadataAllNewTrustedStateWithVisibilityDeletesForNamespaceAlloc(
                self.alloc,
                self.core.identity_namespace,
                sequence,
                &identity_writes,
                &identity_visibility_deletes,
                identity_upsert_keys.items,
                &self.bulk_ingest_identity_state,
            );
            if (!used_trusted_identity_path) self.clearBulkIngestIdentityAllNewLocked();
        }
        if (!used_trusted_identity_path) {
            try doc_identity.appendBatchIdentityMetadataForNamespaceWithVisibilityDeletesAlloc(
                self.alloc,
                self.core.store,
                self.core.identity_namespace,
                sequence,
                &identity_writes,
                &identity_visibility_deletes,
                identity_upsert_keys.items,
                effective_req.deletes,
            );
        }
        if (profile) |active_profile| {
            recordProfileNs(profile, &active_profile.identity_metadata_ns, identity_metadata_start_ns);
            active_profile.identity_metadata_writes += @intCast(identity_writes.items.len);
        }
        const pending_identity_visibility_summary = try doc_identity.visibilitySummaryFromWrites(identity_writes.items);
        if (pending_identity_visibility_summary) |summary| {
            try range_cardinality.appendIdentityTransitionAlloc(
                self.alloc,
                self.core.store,
                self.core.byteRange(),
                identity_live_before,
                summary.live_ordinals,
                &identity_writes,
            );
        }
        try store_writes.appendSlice(self.alloc, identity_writes.items);
        try appendDocumentChildRangeOutboxWrites(
            self.alloc,
            sequence,
            remote_child_range_dispatches.items,
            effective_req.sync_level,
            &store_writes,
            &owned_child_range_outbox_keys,
            &owned_child_range_outbox_values,
        );
        const build_derived_start_ns = monotonicTimeNs();
        const replay_payload = if (use_thin_replay_fast_path)
            try encodeThinReplayRecordPayload(
                self.alloc,
                effective_req,
                extracted[0..extracted_initialized],
                deleted_artifact_keys,
                changed_graph_artifact_keys.items,
                overwritten_flags,
                derived_changed_flags,
                sequence,
                include_generated_enrichment_hint,
            )
        else blk: {
            materialized_derived_batch = try buildDerivedBatch(self.alloc, effective_req, extracted[0..extracted_initialized], deleted_artifact_keys, changed_graph_artifact_keys.items);
            for (materialized_derived_batch.?.overwritten_doc_keys) |key| self.alloc.free(@constCast(key));
            if (materialized_derived_batch.?.overwritten_doc_keys.len > 0) self.alloc.free(materialized_derived_batch.?.overwritten_doc_keys);
            materialized_derived_batch.?.overwritten_doc_keys = try buildOverwrittenDocKeys(self.alloc, effective_req.writes, overwritten_flags);
            materialized_derived_batch.?.documents = try takeOwnedSlice(derived_types.DerivedDocument, self.alloc, materialized_derived_batch.?.documents, &precomputed_generated.documents);
            materialized_derived_batch.?.dense_embeddings = try takeOwnedSlice(derived_types.DerivedDenseEmbeddingWrite, self.alloc, materialized_derived_batch.?.dense_embeddings, &precomputed_generated.dense_embeddings);
            materialized_derived_batch.?.sparse_embeddings = try takeOwnedSlice(derived_types.DerivedSparseEmbeddingWrite, self.alloc, materialized_derived_batch.?.sparse_embeddings, &precomputed_generated.sparse_embeddings);
            materialized_derived_batch.?.generated_enrichment_refs = precomputed_generated.generated_enrichment_refs;
            precomputed_generated.generated_enrichment_refs = &.{};
            materialized_derived_batch.?.sequence = sequence;
            const payload = try encodeChangeRecordPayload(&self.batchContext(), materialized_derived_batch.?, sequence);
            try attachInlineUpsertDocumentValues(self.alloc, &materialized_derived_batch.?, effective_req, extracted[0..extracted_initialized]);

            const apply_shadow_start_ns = monotonicTimeNs();
            try applyDerivedBatchToShadowIfNeeded(self, materialized_derived_batch.?);
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.apply_shadow_ns, apply_shadow_start_ns);

            const collect_sync_targets_start_ns = monotonicTimeNs();
            sync_targets = try collectManagedSyncTargets(self.alloc, self.core.index_manager, materialized_derived_batch.?);
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.collect_sync_targets_ns, collect_sync_targets_start_ns);
            break :blk payload;
        };
        defer self.alloc.free(replay_payload);
        const append_derived_replay = !opts.suppress_derived_replay_append and
            !elide_semantic_noop_replay;
        if (profile) |active_profile| recordProfileNs(profile, &active_profile.build_derived_ns, build_derived_start_ns);

        const store_write_start_ns = monotonicTimeNs();
        const store_batch_options: backend_types.BatchOptions = if (opts.store_batch_options.mode != .default)
            opts.store_batch_options
        else if (self.bulk_ingest_coalescer.active)
            .{ .mode = .bulk_ingest, .defer_commit_flush = true }
        else
            .{};
        var ha_applied_lsn_value_buf: [ha_applied_lsn_value_len]u8 = undefined;
        if (opts.ha_applied_lsn_marker) |lsn| {
            if (lsn != 0) {
                try store_writes.append(self.alloc, haAppliedReplicationLsnWrite(lsn, &ha_applied_lsn_value_buf));
            }
        }
        var split_range_value: ?[]u8 = null;
        defer if (split_range_value) |value| self.alloc.free(value);
        var split_sequence_buf: [8]u8 = undefined;
        var split_marker_buf: [4 * @sizeOf(u64) + 1]u8 = undefined;
        var persisted_range: ?types.ByteRange = null;
        var persisted_range_start_owned: ?[]u8 = null;
        defer if (persisted_range_start_owned) |value| self.alloc.free(value);
        var persisted_range_end_owned: ?[]u8 = null;
        defer if (persisted_range_end_owned) |value| self.alloc.free(value);
        if (req.split_replication) |replication| {
            if (replication.operation == .delta) {
                try store_writes.append(self.alloc, .{
                    .key = range_state_mod.split_delta_final_seq_key,
                    .value = range_state_mod.encodeSplitDeltaFinalSeq(replication.sequence, &split_sequence_buf),
                });
            }
        }
        if (req.split_checkpoint) |checkpoint| {
            if (checkpoint.kind != .source_ack) {
                persisted_range = .{ .start = checkpoint.range_start, .end = checkpoint.range_end };
                persisted_range_start_owned = try self.alloc.dupe(u8, checkpoint.range_start);
                persisted_range_end_owned = try self.alloc.dupe(u8, checkpoint.range_end);
                split_range_value = try range_state_mod.encodeRangeAlloc(self.alloc, persisted_range.?);
                try store_writes.append(self.alloc, .{
                    .key = range_state_mod.range_key,
                    .value = split_range_value.?,
                });
            }
            try store_writes.append(self.alloc, .{
                .key = range_state_mod.split_delta_final_seq_key,
                .value = range_state_mod.encodeSplitDeltaFinalSeq(checkpoint.delta_sequence, &split_sequence_buf),
            });
            try store_writes.append(self.alloc, .{
                .key = range_state_mod.split_bootstrap_marker_key,
                .value = range_state_mod.encodeSplitBootstrapMarker(.{
                    .transition_id = checkpoint.transition_id,
                    .attempt_epoch = checkpoint.attempt_epoch,
                    .source_group_id = checkpoint.source_group_id,
                    .destination_group_id = checkpoint.destination_group_id,
                    .bootstrap_complete = checkpoint.kind == .destination_complete,
                }, &split_marker_buf),
            });
        }
        try appendDenseArtifactCounterMutations(
            self.alloc,
            self.core.store,
            self.core.index_manager,
            &store_writes,
            delete_keys.items,
            &owned_store_keys,
            &owned_store_values,
        );
        try store_writes.appendSlice(self.alloc, opts.extra_store_writes);
        try delete_keys.appendSlice(self.alloc, identity_visibility_deletes.items);

        // A synchronous HA append can fail after the local transaction commit.
        // Persist the exact committed payloads in the same backend batch so an
        // idempotent resolve retry can finish mirroring without reconstructing
        // data from already-deleted intents.
        var transaction_ha_batch_payload: ?[]const u8 = null;
        var transaction_ha_replay_payload: ?[]const u8 = null;
        if (opts.transaction_resolution) |resolution| if (!opts.bypass_ha_write_gate) {
            if (self.ha_async_batch_mirror) |mirror| if (haMirrorSyncEnabled(mirror)) {
                const payload = try ha_effects_mod.encodeBatchMutationRequestAlloc(self.alloc, effective_req);
                try owned_store_values.append(self.alloc, payload);
                const key_array = transactions_mod.makeTransactionHABatchOutboxKey(resolution.txn_id);
                const key = try self.alloc.dupe(u8, &key_array);
                try owned_store_keys.append(self.alloc, key);
                try store_writes.append(self.alloc, .{ .key = key, .value = payload });
                transaction_ha_batch_payload = payload;
            };
            if (append_derived_replay) if (self.ha_async_effect_mirror) |mirror| if (haMirrorSyncEnabled(mirror)) {
                const payload = try self.alloc.dupe(u8, replay_payload);
                try owned_store_values.append(self.alloc, payload);
                const key_array = transactions_mod.makeTransactionHAReplayOutboxKey(resolution.txn_id);
                const key = try self.alloc.dupe(u8, &key_array);
                try owned_store_keys.append(self.alloc, key);
                try store_writes.append(self.alloc, .{ .key = key, .value = payload });
                transaction_ha_replay_payload = payload;
            };
        };
        const replay_append: ?docstore_mod.DocStore.ReplayAppend = if (append_derived_replay)
            .{
                .sequence = sequence,
                .payload = replay_payload,
            }
        else
            null;
        const transaction_applied = if (opts.transaction_resolution) |resolution| blk: {
            const outcome = try self.core.resolveTransactionIntentsWithExtraBatch(
                resolution.txn_id,
                resolution.status,
                resolution.commit_version,
                .{
                    .writes = store_writes.items,
                    .deletes = delete_keys.items,
                    .replay = if (replay_append) |entry| .{ .sequence = entry.sequence, .payload = entry.payload } else null,
                    .expected_intent_revision = resolution.expected_intent_revision,
                    .known_intent_keys = resolution.intent_keys,
                },
            );
            if (outcome.applied) {
                if (replay_append) |entry| self.core.store.observeExternalReplayCommit(entry.sequence);
            }
            break :blk outcome;
        } else blk: {
            try self.core.store.putBatchWithReplayWithOptions(
                self.backend_runtime.io(),
                store_writes.items,
                delete_keys.items,
                replay_append,
                store_batch_options,
            );
            break :blk transactions_mod.ResolutionOutcome{ .applied = true, .replay_sequence = sequence };
        };
        if (!transaction_applied.applied) {
            self.core.unlockApply();
            apply_mutex_held = false;
            try self.waitForResolvedTransactionSync(effective_req.sync_level, transaction_applied.replay_sequence);
            return;
        }
        if (persisted_range != null) {
            self.core.adoptPersistedRangeOwned(persisted_range_start_owned.?, persisted_range_end_owned.?);
            persisted_range_start_owned = null;
            persisted_range_end_owned = null;
        }
        if (!opts.bypass_ha_write_gate) {
            if (transaction_ha_batch_payload) |payload| {
                try self.mirrorHAEncodedBatchMutationCommit(payload);
                try self.core.clearTransactionHAOutbox(opts.transaction_resolution.?.txn_id, .batch);
            } else try self.mirrorHABatchMutationCommit(effective_req);
            if (transaction_ha_replay_payload) |payload| {
                try self.mirrorHAReplayPayloadCommit(payload);
                try self.core.clearTransactionHAOutbox(opts.transaction_resolution.?.txn_id, .replay);
            } else if (append_derived_replay) try self.mirrorHAReplayPayloadCommit(replay_payload);
        }
        if (pending_identity_visibility_summary) |summary| {
            self.identity_visibility_summary_cache = summary;
            self.clearLiveDocSetCache();
            self.clearNonVisibleDocSetCache();
        }
        if (profile) |active_profile| {
            recordProfileNs(profile, &active_profile.store_write_ns, store_write_start_ns);
            active_profile.store_write_count += @intCast(store_writes.items.len);
            active_profile.store_delete_count += @intCast(delete_keys.items.len);
        }
        const is_split_progress_checkpoint = if (req.split_checkpoint) |checkpoint|
            checkpoint.kind == .source_ack
        else
            false;
        if (shouldAppendSplitDelta(self) and !is_split_progress_checkpoint) {
            const split_delta_start_ns = monotonicTimeNs();
            try self.core.appendSplitDelta(batch_timestamp_ns, store_writes.items, delete_keys.items);
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.split_delta_ns, split_delta_start_ns);
        }

        if (append_derived_replay) {
            const append_replay_journal_start_ns = monotonicTimeNs();
            self.executor.trackBacklogBytes(sequence, @intCast(replay_payload.len)) catch {};
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.append_replay_journal_ns, append_replay_journal_start_ns);
        }
        self.core.unlockApply();
        apply_mutex_held = false;
        if (opts.document_child_range_dispatcher) |dispatcher| {
            _ = try self.drainDocumentArtifactChildRangeOutbox(dispatcher, 0);
        }
        if (append_derived_replay) {
            var pressure_ctx = self.batchContext();
            const backlog_pressure_start_ns = monotonicTimeNs();
            try self.markPrecomputedEnrichmentAppliedForSync(effective_req.sync_level, sequence);
            try applyDerivedBacklogPressureContext(&pressure_ctx, sequence, effective_req.sync_level, sync_targets);
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.backlog_pressure_ns, backlog_pressure_start_ns);
        }
        const wait_sync_start_ns = monotonicTimeNs();
        if (append_derived_replay and self.executor.hasWorkers()) {
            const notify_executor_start_ns = monotonicTimeNs();
            notifyExecutorForSyncLevelWithDenseBulkDeferral(self.async_context, self.executor, effective_req.sync_level, sequence, sync_targets);
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.executor_notify_ns, notify_executor_start_ns);
            if (opts.wait_for_sync_level) {
                const sync_wait_start_ns = monotonicTimeNs();
                try self.waitForSyncLevelWithCancellation(effective_req.sync_level, sequence, sync_targets, opts.visibility_cancellation);
                if (profile) |active_profile| recordProfileNs(profile, &active_profile.sync_wait_ns, sync_wait_start_ns);
            }
        } else if (append_derived_replay) {
            if (opts.wait_for_sync_level and syncLevelRequiresDerivedVisibility(effective_req.sync_level)) {
                const derived_apply_start_ns = monotonicTimeNs();
                if (effective_req.sync_level == .full_text) {
                    try applyDerivedBatchTargetsProfiled(self, materialized_derived_batch.?, sync_targets.full_text_indexes, profile);
                } else {
                    try applyDerivedBatchProfiled(self, materialized_derived_batch.?, profile);
                }
                if (profile) |active_profile| recordProfileNs(profile, &active_profile.derived_apply_ns, derived_apply_start_ns);
            }
            if (opts.wait_for_sync_level) {
                const sync_wait_start_ns = monotonicTimeNs();
                try self.waitForSyncLevelWithCancellation(effective_req.sync_level, sequence, sync_targets, opts.visibility_cancellation);
                if (profile) |active_profile| recordProfileNs(profile, &active_profile.sync_wait_ns, sync_wait_start_ns);
            }
        }
        if (profile) |active_profile| recordProfileNs(profile, &active_profile.wait_sync_ns, wait_sync_start_ns);
        if (append_derived_replay) {
            if (self.enrichment_runtime) |runtime| {
                const notify_enrichment_start_ns = monotonicTimeNs();
                runtime.notifySequence(sequence);
                if (profile) |active_profile| recordProfileNs(profile, &active_profile.notify_enrichment_ns, notify_enrichment_start_ns);
            }
            self.notifyResolverReplayRuntimes(sequence);
        }
    }

    /// Exact source replays may omit derived journal work while each existing
    /// artifact-backed dense generation is nonempty. A partial-generation
    /// mismatch belongs to durable repair; replaying unchanged source into it
    /// amplifies a small maintenance discrepancy into destructive HBC churn.
    /// A reset or a newly admitted empty generation still needs the replay so
    /// cached artifacts can populate it without re-embedding.
    fn unchangedDerivedReplayTargetsServiceable(self: *DB, alloc: Allocator) !bool {
        for (self.core.index_manager.dense_indexes.items) |*entry| {
            if (!try index_manager_mod.denseConfigRequiresArtifactCoverage(alloc, entry.config)) continue;
            const expected = (try loadDenseArtifactTargetCounter(alloc, self.core.store, entry.config.name)) orelse return false;
            if (expected != 0 and entry.index.stats().active_count == 0) return false;
        }
        return true;
    }

    fn storedDocumentValuesEqual(alloc: Allocator, lhs: []const u8, rhs: []const u8) bool {
        if (std.mem.eql(u8, lhs, rhs)) return true;

        var lhs_parsed = ant_json.parseFromSlice(ant_json.Value, alloc, lhs, .{}) catch return false;
        defer lhs_parsed.deinit();
        var rhs_parsed = ant_json.parseFromSlice(ant_json.Value, alloc, rhs, .{}) catch return false;
        defer rhs_parsed.deinit();
        return json_helpers.jsonValuesEqual(lhs_parsed.value, rhs_parsed.value);
    }

    fn thinReplayInputsHaveDerivedWork(
        req: types.BatchRequest,
        deleted_artifact_keys: []const []u8,
        changed_artifact_keys: []const []u8,
        derived_changed_flags: []const bool,
    ) bool {
        if (req.deletes.len != 0 or
            req.graph_writes.len != 0 or
            req.graph_deletes.len != 0 or
            deleted_artifact_keys.len != 0 or
            changed_artifact_keys.len != 0 or
            req.split_checkpoint != null or
            req.split_replication != null or
            req.split_transition != null or
            req.transaction != null)
        {
            return true;
        }
        for (derived_changed_flags) |changed| {
            if (changed) return true;
        }
        return false;
    }

    fn removePendingStoreWriteByKey(writes: *std.ArrayListUnmanaged(docstore_mod.KVPair), key: []const u8) void {
        for (writes.items, 0..) |write, i| {
            if (!std.mem.eql(u8, write.key, key)) continue;
            _ = writes.orderedRemove(i);
            return;
        }
    }

    /// Inject (or clear) the cross-shard entity-resolution candidate source on
    /// an already-open DB. The serving layer (managed write cache) calls this
    /// right after a DB is opened, since managed DBs open lazily and cannot
    /// thread the source through `OpenOptions`. No-op when this DB has no
    /// resolution runtime (e.g. read-only / status opens).
    pub fn setResolutionCandidateSource(self: *DB, src: ?resolution_runtime_mod.CandidateSource) void {
        self.resolution_candidate_source = src;
        if (self.resolution_runtime) |runtime| runtime.setCandidateSource(src);
    }

    /// Inject (or clear) the cross-shard entity sink on an already-open DB. The
    /// serving layer (managed write cache) calls this right after a DB is opened,
    /// since managed DBs open lazily and cannot thread the sink through
    /// `OpenOptions`. No-op when this DB has no promotion runtime.
    pub fn setEntitySink(self: *DB, sink: ?promotion_runtime_mod.EntitySink) void {
        self.entity_sink = sink;
        if (self.promotion_runtime) |runtime| runtime.setSink(sink);
    }

    /// Inject (or clear) the source-shard promotion owner on an already-open DB.
    /// Serving-layer managed DBs use this to keep follower raft apply from
    /// turning replay into public entity-table writes.
    pub fn setPromotionOwner(self: *DB, owner: ?promotion_runtime_mod.PromotionOwner) void {
        self.promotion_owner = owner;
        if (self.promotion_runtime) |runtime| runtime.setOwner(owner);
    }

    fn failIfIdentityOrdinalExhaustedForNewUpserts(self: *DB, doc_ids: []const []const u8) !void {
        if (doc_ids.len == 0) return;

        var txn = try self.core.store.beginProbeTxn();
        defer txn.abort();

        const raw_next = txn.get(internal_keys.identity_next_ordinal_key[0..]) catch |err| switch (err) {
            error.NotFound => return,
            else => return err,
        };
        if (raw_next.len != @sizeOf(doc_identity.DocOrdinal)) return error.InvalidDocIdentity;
        const next_ordinal = std.mem.readInt(doc_identity.DocOrdinal, raw_next[0..4], .big);
        if (next_ordinal != 0 and next_ordinal < std.math.maxInt(doc_identity.DocOrdinal)) return;

        var seen = std.StringHashMapUnmanaged(void).empty;
        defer seen.deinit(self.alloc);
        for (doc_ids) |doc_id| {
            if (seen.contains(doc_id)) continue;
            try seen.put(self.alloc, doc_id, {});
            if (try doc_identity.lookupOrdinalTxn(self.alloc, &txn, doc_id) != null) continue;
            return error.DocOrdinalExhausted;
        }
    }

    fn configureBulkIngestIdentityAllNewLocked(self: *DB) !void {
        self.clearBulkIngestIdentityAllNewLocked();
        if (!try self.primaryUserNamespaceIsEmptyLocked()) return;
        if (try doc_identity.loadAllNewTrustedStateForNamespace(self.core.store, self.core.identity_namespace)) |state| {
            self.bulk_ingest_identity_state = state;
            self.identity_visibility_summary_cache = state.visibility_summary;
            self.clearLiveDocSetCache();
            self.clearNonVisibleDocSetCache();
            self.bulk_ingest_identity_all_new = true;
        }
    }

    fn clearBulkIngestIdentityAllNewLocked(self: *DB) void {
        self.bulk_ingest_identity_all_new = false;
        self.bulk_ingest_identity_state.deinit(self.alloc);
        self.clearBulkIngestSeenDocKeysLocked();
    }

    fn clearBulkIngestSeenDocKeysLocked(self: *DB) void {
        var it = self.bulk_ingest_seen_doc_keys.keyIterator();
        while (it.next()) |key_ptr| self.alloc.free(@constCast(key_ptr.*));
        self.bulk_ingest_seen_doc_keys.clearRetainingCapacity();
    }

    fn clearActiveIndexRepairsLocked(self: *DB) void {
        var it = self.active_index_repairs.keyIterator();
        while (it.next()) |key_ptr| self.alloc.free(@constCast(key_ptr.*));
        self.active_index_repairs.clearRetainingCapacity();
    }

    const RepairShadowCleanupWork = struct {
        manager: *index_manager_mod.IndexManager,
        lane: background_runtime_mod.DurableJobLane,
        owner_id: u64,

        const pages_per_job: usize = 8;
        const retries_per_job: usize = 8;
        const retry_initial_ms: i64 = 25;
        const retry_max_ms: i64 = 1000;

        fn run(ptr: *anyopaque) anyerror!void {
            const work: *@This() = @ptrCast(@alignCast(ptr));
            var pages: usize = 0;
            var retries: usize = 0;
            while (true) {
                const progressed = work.manager.cleanupInactiveRepairShadowRootsPage() catch |err| {
                    retries += 1;
                    if (retries == 1 or std.math.isPowerOfTwo(retries))
                        std.log.warn("repair-generation cleanup retry attempt={} err={s}", .{ retries, @errorName(err) });
                    const shift: u6 = @intCast(@min(retries - 1, 5));
                    const delay_ms = if (builtin.is_test) 1 else @min(retry_initial_ms << shift, retry_max_ms);
                    work.manager.checkpointIo().sleep(std.Io.Duration.fromMilliseconds(delay_ms), .awake) catch {};
                    if (retries >= retries_per_job) {
                        work.manager.repair_cleanup_state.store(0, .release);
                        // Manual lanes run `submit` synchronously. Propagate the
                        // failure to that caller and leave the filesystem/key
                        // namespace as the durable retry marker; resubmitting
                        // here would recurse forever on a persistent error.
                        if (work.lane.executesInline()) return err;
                        scheduleInactiveRepairShadowCleanupContext(work.manager, work.lane, work.owner_id);
                        return;
                    }
                    continue;
                };
                retries = 0;
                if (progressed) {
                    pages += 1;
                    if (pages < pages_per_job) continue;
                    // Orphaned key deletion is itself durable. Yield the shared
                    // cleanup lane between bounded slices and rediscover the
                    // first remaining namespace on the next job.
                    work.manager.repair_cleanup_state.store(0, .release);
                    // A manual runtime has no autonomous queue. Bound the
                    // foreground call and let the next maintenance request or
                    // reopen rediscover the durable orphan marker.
                    if (work.lane.executesInline()) return;
                    scheduleInactiveRepairShadowCleanupContext(work.manager, work.lane, work.owner_id);
                    return;
                }
                if (work.manager.repair_cleanup_state.cmpxchgStrong(1, 0, .acq_rel, .acquire) == null) return;
                if (work.manager.repair_cleanup_state.cmpxchgStrong(2, 1, .acq_rel, .acquire) == null) {
                    pages = 0;
                    continue;
                }
                return;
            }
        }

        fn deinit(ptr: *anyopaque) void {
            const work: *@This() = @ptrCast(@alignCast(ptr));
            std.heap.page_allocator.destroy(work);
        }
    };

    fn scheduleInactiveRepairShadowCleanup(self: *DB) void {
        scheduleInactiveRepairShadowCleanupContext(
            self.core.index_manager,
            self.backend_runtime.durable_jobs,
            self.repair_cleanup_owner_id,
        );
    }

    fn scheduleInactiveRepairShadowCleanupContext(
        manager: *index_manager_mod.IndexManager,
        lane: background_runtime_mod.DurableJobLane,
        owner_id: u64,
    ) void {
        if (manager.repair_cleanup_state.cmpxchgStrong(0, 1, .acq_rel, .acquire) != null) {
            _ = manager.repair_cleanup_state.cmpxchgStrong(1, 2, .acq_rel, .acquire);
            return;
        }
        const work = std.heap.page_allocator.create(RepairShadowCleanupWork) catch {
            manager.repair_cleanup_state.store(0, .release);
            return;
        };
        work.* = .{ .manager = manager, .lane = lane, .owner_id = owner_id };
        lane.submit(.{
            .owner_id = owner_id,
            .class = .cleanup,
            .ptr = work,
            .run = RepairShadowCleanupWork.run,
            .deinit = RepairShadowCleanupWork.deinit,
        }) catch |err| {
            std.heap.page_allocator.destroy(work);
            manager.repair_cleanup_state.store(0, .release);
            std.log.warn("deferred index-generation cleanup was not scheduled err={s}", .{@errorName(err)});
        };
    }

    const GeneratedArtifactCleanupWork = struct {
        ctx: *AsyncContext,
        lane: background_runtime_mod.DurableJobLane,
        owner_id: u64,

        const pages_per_job: usize = 8;
        const retries_per_job: usize = 8;
        const retry_initial_ms: i64 = 25;
        const retry_max_ms: i64 = 1000;

        fn drainOnePage(work: *@This()) !GeneratedArtifactCleanupAdvanceResult {
            return try advanceGeneratedArtifactCleanupContext(work.ctx, null);
        }

        fn run(ptr: *anyopaque) anyerror!void {
            const work: *@This() = @ptrCast(@alignCast(ptr));
            var pages: usize = 0;
            var retries: usize = 0;
            var contention_retries: usize = 0;
            while (true) {
                if (work.ctx.background_closing.load(.acquire)) {
                    work.ctx.index_manager.artifact_cleanup_state.store(0, .release);
                    return;
                }
                const advance = work.drainOnePage() catch |err| {
                    retries += 1;
                    if (retries == 1 or std.math.isPowerOfTwo(retries))
                        std.log.warn("generated-artifact cleanup retry attempt={} err={s}", .{ retries, @errorName(err) });
                    if (work.ctx.io) |io| {
                        const shift: u6 = @intCast(@min(retries - 1, 5));
                        const delay_ms = if (builtin.is_test) 1 else @min(retry_initial_ms << shift, retry_max_ms);
                        io.sleep(std.Io.Duration.fromMilliseconds(delay_ms), .awake) catch {};
                    } else {
                        // Manual/freestanding lanes have no autonomous timer.
                        // Leave the durable marker pending for the next explicit
                        // maintenance poll or reopen instead of monopolizing the
                        // caller that is executing the lane synchronously.
                        work.ctx.index_manager.artifact_cleanup_state.store(0, .release);
                        return err;
                    }
                    if (retries >= retries_per_job) {
                        // A persistent failure must not monopolize a shared
                        // durable-job worker. Requeue at the tail while the
                        // durable tombstone remains the source of truth.
                        work.ctx.index_manager.artifact_cleanup_state.store(0, .release);
                        scheduleGeneratedArtifactCleanupContext(work.ctx, work.lane, work.owner_id);
                        return;
                    }
                    continue;
                };
                retries = 0;

                if (advance == .busy) {
                    // Another caller owns a bounded page or terminal filesystem
                    // finalization. Yield without turning expected contention
                    // into an error or spinning on the shared durable-job lane.
                    const io = work.ctx.io orelse {
                        work.ctx.index_manager.artifact_cleanup_state.store(0, .release);
                        return;
                    };
                    contention_retries += 1;
                    if (contention_retries < retries_per_job) {
                        const shift: u6 = @intCast(@min(contention_retries - 1, 5));
                        const delay_ms = if (builtin.is_test) 1 else @min(retry_initial_ms << shift, retry_max_ms);
                        io.sleep(std.Io.Duration.fromMilliseconds(delay_ms), .awake) catch {};
                        continue;
                    }
                    work.ctx.index_manager.artifact_cleanup_state.store(0, .release);
                    scheduleGeneratedArtifactCleanupContext(work.ctx, work.lane, work.owner_id);
                    return;
                }
                contention_retries = 0;

                if (advance == .idle) {
                    if (work.ctx.index_manager.artifact_cleanup_state.cmpxchgStrong(1, 0, .acq_rel, .acquire) == null) return;
                    if (work.ctx.index_manager.artifact_cleanup_state.cmpxchgStrong(2, 1, .acq_rel, .acquire) == null) {
                        pages = 0;
                        continue;
                    }
                    return;
                }

                pages += 1;
                if (pages < pages_per_job) continue;

                // Yield the durable-job lane between bounded slices. The
                // outbox cursor makes resubmission idempotent across failures.
                work.ctx.index_manager.artifact_cleanup_state.store(0, .release);
                if (work.lane.executesInline()) return;
                scheduleGeneratedArtifactCleanupContext(work.ctx, work.lane, work.owner_id);
                return;
            }
        }

        fn deinit(ptr: *anyopaque) void {
            const work: *@This() = @ptrCast(@alignCast(ptr));
            std.heap.page_allocator.destroy(work);
        }
    };

    const EnrichmentRestartWork = struct {
        ctx: *AsyncContext,
        lane: background_runtime_mod.DurableJobLane,
        owner_id: u64,

        const retry_initial_ms: i64 = 25;
        const retry_max_ms: i64 = 1000;
        const retries_per_job: usize = 8;

        fn run(ptr: *anyopaque) anyerror!void {
            const work: *@This() = @ptrCast(@alignCast(ptr));
            var retries: usize = 0;
            while (true) {
                if (work.ctx.background_closing.load(.acquire)) {
                    work.ctx.enrichment_restart_state.store(0, .release);
                    return;
                }
                if (!work.ctx.enrichment_desired_running.load(.acquire)) {
                    if (work.ctx.enrichment_restart_state.cmpxchgStrong(1, 0, .acq_rel, .acquire) == null) return;
                    if (work.ctx.enrichment_restart_state.cmpxchgStrong(2, 1, .acq_rel, .acquire) == null) {
                        retries = 0;
                        continue;
                    }
                    return;
                }

                lockAtomicWithBackoff(&work.ctx.enrichment_lifecycle_mutex);
                const runtime = work.ctx.enrichment_runtime;
                const should_start = runtime != null and
                    work.ctx.enrichment_desired_running.load(.acquire) and
                    !work.ctx.background_closing.load(.acquire) and
                    !runtime.?.isStarted();
                const start_result: ?anyerror = if (should_start) blk: {
                    startEnrichmentRuntimeForLifecycle(runtime.?) catch |err| break :blk err;
                    break :blk null;
                } else null;
                const started = runtime == null or runtime.?.isStarted();
                work.ctx.enrichment_lifecycle_mutex.unlock();

                if (started) {
                    notifyQueryVisibilityHook(work.ctx, .status);
                    if (work.ctx.enrichment_restart_state.cmpxchgStrong(1, 0, .acq_rel, .acquire) == null) return;
                    if (work.ctx.enrichment_restart_state.cmpxchgStrong(2, 1, .acq_rel, .acquire) == null) {
                        retries = 0;
                        continue;
                    }
                    return;
                }

                retries += 1;
                if (retries == 1 or std.math.isPowerOfTwo(retries)) {
                    std.log.warn("enrichment runtime restart retry attempt={} err={s}", .{
                        retries,
                        if (start_result) |err| @errorName(err) else "RuntimeNotStarted",
                    });
                }
                if (work.ctx.io) |io| {
                    const shift: u6 = @intCast(@min(retries - 1, 5));
                    const delay_ms = if (builtin.is_test) 1 else @min(retry_initial_ms << shift, retry_max_ms);
                    io.sleep(std.Io.Duration.fromMilliseconds(delay_ms), .awake) catch {};
                } else {
                    work.ctx.enrichment_restart_state.store(0, .release);
                    return start_result orelse error.EnrichmentRuntimeUnavailable;
                }
                if (retries >= retries_per_job) {
                    // Preserve autonomous recovery while allowing unrelated
                    // durable work to run on a persistently failing runtime.
                    work.ctx.enrichment_restart_state.store(0, .release);
                    scheduleEnrichmentRestartContext(work.ctx, work.lane, work.owner_id);
                    return;
                }
            }
        }

        fn deinit(ptr: *anyopaque) void {
            const work: *@This() = @ptrCast(@alignCast(ptr));
            std.heap.page_allocator.destroy(work);
        }
    };

    var test_enrichment_restart_failures_remaining: std.atomic.Value(u32) = .init(0);
    var test_enrichment_reconfigure_after_detached_hook: ?*const fn (*DB) anyerror!void = null;

    fn startEnrichmentRuntimeForLifecycle(runtime: *enrichment_runtime_mod.EnrichmentRuntime) !void {
        if (builtin.is_test) {
            var remaining = test_enrichment_restart_failures_remaining.load(.acquire);
            while (remaining != 0) {
                if (test_enrichment_restart_failures_remaining.cmpxchgWeak(
                    remaining,
                    remaining - 1,
                    .acq_rel,
                    .acquire,
                )) |actual| {
                    remaining = actual;
                    continue;
                }
                return error.TestTransientEnrichmentRestart;
            }
        }
        try runtime.start();
    }

    fn scheduleEnrichmentRestartContext(
        ctx: *AsyncContext,
        lane: background_runtime_mod.DurableJobLane,
        owner_id: u64,
    ) void {
        if (ctx.background_closing.load(.acquire) or
            !ctx.enrichment_desired_running.load(.acquire)) return;
        if (ctx.enrichment_restart_state.cmpxchgStrong(0, 1, .acq_rel, .acquire) != null) {
            _ = ctx.enrichment_restart_state.cmpxchgStrong(1, 2, .acq_rel, .acquire);
            return;
        }
        const work = std.heap.page_allocator.create(EnrichmentRestartWork) catch {
            ctx.enrichment_restart_state.store(0, .release);
            return;
        };
        work.* = .{ .ctx = ctx, .lane = lane, .owner_id = owner_id };
        lane.submit(.{
            .owner_id = owner_id,
            .class = .maintenance,
            .ptr = work,
            .run = EnrichmentRestartWork.run,
            .deinit = EnrichmentRestartWork.deinit,
        }) catch |err| {
            std.heap.page_allocator.destroy(work);
            ctx.enrichment_restart_state.store(0, .release);
            std.log.warn("enrichment runtime restart was not scheduled err={s}", .{@errorName(err)});
        };
    }

    const MaintenanceRuntimeKind = enum {
        text_merge,
        sparse_compaction,
    };

    fn maintenanceRestartState(ctx: *AsyncContext, kind: MaintenanceRuntimeKind) *std.atomic.Value(u8) {
        return switch (kind) {
            .text_merge => &ctx.text_merge_restart_state,
            .sparse_compaction => &ctx.sparse_compaction_restart_state,
        };
    }

    fn ensureMaintenanceRuntimeRunning(ctx: *AsyncContext, kind: MaintenanceRuntimeKind) !bool {
        return switch (kind) {
            .text_merge => if (ctx.text_merge_runtime) |runtime| try runtime.ensureRunning() else true,
            .sparse_compaction => if (ctx.sparse_compaction_runtime) |runtime| try runtime.ensureRunning() else true,
        };
    }

    const MaintenanceRestartWork = struct {
        ctx: *AsyncContext,
        lane: background_runtime_mod.DurableJobLane,
        owner_id: u64,
        kind: MaintenanceRuntimeKind,

        const retry_initial_ms: i64 = 25;
        const retry_max_ms: i64 = 1000;
        const retries_per_job: usize = 8;

        fn run(ptr: *anyopaque) anyerror!void {
            const work: *@This() = @ptrCast(@alignCast(ptr));
            const restart_state = maintenanceRestartState(work.ctx, work.kind);
            var retries: usize = 0;
            while (true) {
                if (work.ctx.background_closing.load(.acquire)) {
                    restart_state.store(0, .release);
                    return;
                }

                var start_error: ?anyerror = null;
                const running = ensureMaintenanceRuntimeRunning(work.ctx, work.kind) catch |err| blk: {
                    start_error = err;
                    break :blk false;
                };
                if (running) {
                    if (restart_state.cmpxchgStrong(1, 0, .acq_rel, .acquire) == null) return;
                    if (restart_state.cmpxchgStrong(2, 1, .acq_rel, .acquire) == null) {
                        retries = 0;
                        continue;
                    }
                    return;
                }

                retries += 1;
                if (start_error) |err| {
                    if (retries == 1 or std.math.isPowerOfTwo(retries)) {
                        std.log.warn("{s} runtime restart retry attempt={} err={s}", .{
                            @tagName(work.kind),
                            retries,
                            @errorName(err),
                        });
                    }
                }
                // A paused runtime is owned by a subsequent structural
                // mutation. Wait without starting it behind that mutation.
                if (work.ctx.io) |io| {
                    const shift: u6 = @intCast(@min(retries - 1, 5));
                    const delay_ms = if (builtin.is_test) 1 else @min(retry_initial_ms << shift, retry_max_ms);
                    io.sleep(std.Io.Duration.fromMilliseconds(delay_ms), .awake) catch {};
                } else {
                    restart_state.store(0, .release);
                    return error.MaintenanceRuntimeUnavailable;
                }
                if (retries >= retries_per_job) {
                    // Yield the shared durable lane during persistent failure;
                    // the desired-running bit makes resubmission idempotent.
                    restart_state.store(0, .release);
                    scheduleMaintenanceRestartContext(work.ctx, work.lane, work.owner_id, work.kind);
                    return;
                }
            }
        }

        fn deinit(ptr: *anyopaque) void {
            const work: *@This() = @ptrCast(@alignCast(ptr));
            std.heap.page_allocator.destroy(work);
        }
    };

    fn scheduleMaintenanceRestartContext(
        ctx: *AsyncContext,
        lane: background_runtime_mod.DurableJobLane,
        owner_id: u64,
        kind: MaintenanceRuntimeKind,
    ) void {
        if (ctx.background_closing.load(.acquire)) return;
        const restart_state = maintenanceRestartState(ctx, kind);
        if (restart_state.cmpxchgStrong(0, 1, .acq_rel, .acquire) != null) {
            _ = restart_state.cmpxchgStrong(1, 2, .acq_rel, .acquire);
            return;
        }
        const work = std.heap.page_allocator.create(MaintenanceRestartWork) catch {
            restart_state.store(0, .release);
            return;
        };
        work.* = .{ .ctx = ctx, .lane = lane, .owner_id = owner_id, .kind = kind };
        lane.submit(.{
            .owner_id = owner_id,
            .class = .maintenance,
            .ptr = work,
            .run = MaintenanceRestartWork.run,
            .deinit = MaintenanceRestartWork.deinit,
        }) catch |err| {
            std.heap.page_allocator.destroy(work);
            restart_state.store(0, .release);
            std.log.warn("{s} runtime restart was not scheduled err={s}", .{ @tagName(kind), @errorName(err) });
        };
    }

    fn quiesceEnrichmentForStructuralMutation(self: *DB) bool {
        const desired = self.async_context.enrichment_desired_running.swap(false, .acq_rel);
        lockAtomicWithBackoff(&self.async_context.enrichment_lifecycle_mutex);
        defer self.async_context.enrichment_lifecycle_mutex.unlock();
        const runtime = self.async_context.enrichment_runtime orelse return desired;
        const started = runtime.isStarted();
        if (started) runtime.stop();
        return desired or started;
    }

    fn quiesceTextMergeForStructuralMutation(self: *DB) bool {
        const runtime = self.text_merge_runtime orelse return false;
        return runtime.pause();
    }

    fn quiesceSparseCompactionForStructuralMutation(self: *DB) bool {
        const runtime = self.sparse_compaction_runtime orelse return false;
        return runtime.pause();
    }

    fn restartTextMergeAfterStructuralMutation(self: *DB, operation: []const u8, index_name: []const u8) void {
        const runtime = self.text_merge_runtime orelse return;
        runtime.resumeAfterPause() catch |err| {
            // Index catalog durability is already decided at this point.
            // Queries and foreground indexing remain available; surface the
            // maintenance degradation without misreporting the mutation.
            std.log.err("failed to restart text merge runtime after {s} index={s} err={s}", .{ operation, index_name, @errorName(err) });
            scheduleMaintenanceRestartContext(
                self.async_context,
                self.backend_runtime.durable_jobs,
                self.repair_cleanup_owner_id,
                .text_merge,
            );
        };
    }

    fn restartSparseCompactionAfterStructuralMutation(self: *DB, operation: []const u8, index_name: []const u8) void {
        const runtime = self.sparse_compaction_runtime orelse return;
        runtime.resumeAfterPause() catch |err| {
            std.log.err("failed to restart sparse compaction runtime after {s} index={s} err={s}", .{ operation, index_name, @errorName(err) });
            scheduleMaintenanceRestartContext(
                self.async_context,
                self.backend_runtime.durable_jobs,
                self.repair_cleanup_owner_id,
                .sparse_compaction,
            );
        };
    }

    const IndexStructuralMutationGuard = struct {
        db: *DB,
        operation: []const u8,
        index_name: []const u8,
        restart_text_merge: bool,
        restart_sparse_compaction: bool,
        catalog_barrier_held: bool = false,
        active: bool = true,

        fn acquireCatalogBarrierUntil(self: *@This(), deadline_ns: u64) bool {
            std.debug.assert(self.active and !self.catalog_barrier_held);
            if (!self.db.beginIndexCatalogBarrierUntil(deadline_ns)) return false;
            self.catalog_barrier_held = true;
            return true;
        }

        fn releaseCatalogBarrier(self: *@This()) void {
            if (!self.catalog_barrier_held) return;
            self.db.endIndexCatalogBarrier();
            self.catalog_barrier_held = false;
        }

        fn release(self: *@This()) void {
            if (!self.active) return;
            // The catalog is stable once the caller releases apply exclusive;
            // let lock-free dense searches resume before runtime startup work.
            self.releaseCatalogBarrier();
            // Restart while serialization is still held: another structural
            // mutation must not stop a runtime between this restart and the
            // corresponding unlock.
            if (self.restart_sparse_compaction) {
                self.db.restartSparseCompactionAfterStructuralMutation(self.operation, self.index_name);
            }
            if (self.restart_text_merge) {
                self.db.restartTextMergeAfterStructuralMutation(self.operation, self.index_name);
            }
            self.db.index_structural_mutation_mutex.unlock();
            self.active = false;
        }

        fn deinit(self: *@This()) void {
            self.release();
        }
    };

    const QuarantineIndexPublicationFence = struct {
        db: *DB,
        structural_guard: ?IndexStructuralMutationGuard = null,
        apply_locked: bool = false,

        fn iface(self: *@This()) index_manager_mod.IndexManager.CatalogPublicationFence {
            return .{
                .ptr = self,
                .lock_fn = lockOpaque,
                .unlock_fn = unlockOpaque,
            };
        }

        fn lockOpaque(ptr: *anyopaque) void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            std.debug.assert(self.structural_guard == null and !self.apply_locked);
            self.structural_guard = self.db.beginIndexStructuralMutation("quarantined index publication", "*");
            if (builtin.is_test) test_quarantine_publication_fence_entered.store(true, .release);
            lockApply(self.db);
            self.apply_locked = true;
        }

        fn unlockOpaque(ptr: *anyopaque) void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            std.debug.assert(self.apply_locked and self.structural_guard != null);
            self.db.core.unlockApply();
            self.apply_locked = false;
            self.structural_guard.?.release();
            self.structural_guard = null;
        }
    };

    /// Serializes every live index-catalog publication and drains background
    /// tasks that borrow inline index generations. Callers must acquire this
    /// before the DB apply lock; active tasks retire under that lock while the
    /// guard waits for their workers to stop.
    fn beginIndexStructuralMutation(
        self: *DB,
        operation: []const u8,
        index_name: []const u8,
    ) IndexStructuralMutationGuard {
        var guard = self.beginDrainedIndexStructuralMutation(operation, index_name);
        if (!guard.acquireCatalogBarrierUntil(std.math.maxInt(u64))) unreachable;
        return guard;
    }

    fn beginDrainedIndexStructuralMutation(
        self: *DB,
        operation: []const u8,
        index_name: []const u8,
    ) IndexStructuralMutationGuard {
        lockAtomicWithBackoff(&self.index_structural_mutation_mutex);
        return .{
            .db = self,
            .operation = operation,
            .index_name = index_name,
            .restart_text_merge = self.quiesceTextMergeForStructuralMutation(),
            .restart_sparse_compaction = self.quiesceSparseCompactionForStructuralMutation(),
        };
    }

    fn scheduleGeneratedArtifactCleanup(self: *DB) void {
        scheduleGeneratedArtifactCleanupContext(
            self.async_context,
            self.backend_runtime.durable_jobs,
            self.repair_cleanup_owner_id,
        );
    }

    /// Try to advance one bounded page of retired-index artifact records.
    /// Terminal filesystem finalization owns a separate lease, so callers never
    /// wait behind checkpoint or directory deletion performed by another job.
    pub const GeneratedArtifactCleanupAdvanceResult = enum {
        idle,
        progressed,
        busy,
    };

    pub fn advanceGeneratedArtifactCleanupPage(self: *DB, index_name: ?[]const u8) !GeneratedArtifactCleanupAdvanceResult {
        return try advanceGeneratedArtifactCleanupContext(self.async_context, index_name);
    }

    fn advanceGeneratedArtifactCleanupContext(
        ctx: *AsyncContext,
        index_name: ?[]const u8,
    ) !GeneratedArtifactCleanupAdvanceResult {
        if (!ctx.index_artifact_cleanup_mutex.tryLock()) return .busy;
        var cleanup_locked = true;
        defer if (cleanup_locked) ctx.index_artifact_cleanup_mutex.unlock();

        if (index_name) |name| {
            var targeted = try ctx.index_manager.drainGeneratedArtifactCleanupForIndexPage(
                ctx.store,
                name,
            );
            defer targeted.deinit();
            if (targeted.found) {
                if (!targeted.completed) return .progressed;
                return try finalizeClaimedRetiredIndexCleanup(ctx, &cleanup_locked, targeted.index_name, targeted.key);
            }
        }

        var result = try ctx.index_manager.drainGeneratedArtifactCleanupOutboxPage(ctx.store);
        defer result.deinit();
        if (!result.found) return .idle;
        if (!result.completed) return .progressed;
        return try finalizeClaimedRetiredIndexCleanup(ctx, &cleanup_locked, result.index_name, result.key);
    }

    fn finalizeClaimedRetiredIndexCleanup(
        ctx: *AsyncContext,
        cleanup_locked: *bool,
        index_name: []const u8,
        cleanup_key: []const u8,
    ) !GeneratedArtifactCleanupAdvanceResult {
        if (!ctx.index_artifact_finalization_mutex.tryLock()) return .busy;
        defer ctx.index_artifact_finalization_mutex.unlock();

        // Repair issues describe one concrete consumer generation. A
        // same-name replacement has different artifact identities and cannot
        // resolve diagnoses left by the retired generation. Keep the durable
        // cleanup tombstone authoritative until every issue and its terminal
        // failure history have drained in bounded, crash-idempotent pages.
        if (try drainRetiredIndexArtifactRepairIssuesPageContext(ctx, index_name)) return .progressed;

        // The durable tombstone remains visible while finalization runs, so
        // namespace admission stays fenced. Release page arbitration before
        // checkpoint and filesystem I/O; other indexes can continue draining.
        ctx.index_artifact_cleanup_mutex.unlock();
        cleanup_locked.* = false;
        if (builtin.is_test and test_block_generated_artifact_finalization.load(.acquire)) {
            test_generated_artifact_finalization_entered.store(true, .release);
            while (!test_release_generated_artifact_finalization.load(.acquire)) {
                std.Thread.yield() catch {};
            }
        }
        try finalizeRetiredIndexCleanupContext(ctx, index_name, cleanup_key);
        return .progressed;
    }

    fn scheduleGeneratedArtifactCleanupContext(
        ctx: *AsyncContext,
        lane: background_runtime_mod.DurableJobLane,
        owner_id: u64,
    ) void {
        if (ctx.background_closing.load(.acquire)) return;
        if (ctx.index_manager.artifact_cleanup_state.cmpxchgStrong(0, 1, .acq_rel, .acquire) != null) {
            _ = ctx.index_manager.artifact_cleanup_state.cmpxchgStrong(1, 2, .acq_rel, .acquire);
            return;
        }
        const work = std.heap.page_allocator.create(GeneratedArtifactCleanupWork) catch {
            ctx.index_manager.artifact_cleanup_state.store(0, .release);
            return;
        };
        work.* = .{ .ctx = ctx, .lane = lane, .owner_id = owner_id };
        lane.submit(.{
            .owner_id = owner_id,
            .class = .cleanup,
            .ptr = work,
            .run = GeneratedArtifactCleanupWork.run,
            .deinit = GeneratedArtifactCleanupWork.deinit,
        }) catch |err| {
            std.heap.page_allocator.destroy(work);
            ctx.index_manager.artifact_cleanup_state.store(0, .release);
            std.log.warn("generated-artifact cleanup was not scheduled err={s}", .{@errorName(err)});
        };
    }

    const retired_index_artifact_repair_cleanup_page_size: usize = 64;

    const RetiredArtifactRepairIssueKeyParse = union(enum) {
        valid: internal_keys.ArtifactRepairIssueKeyParts,
        malformed: anyerror,
    };

    fn parseRetiredArtifactRepairIssueKeyAlloc(
        alloc: Allocator,
        key: []const u8,
    ) !RetiredArtifactRepairIssueKeyParse {
        const parts = internal_keys.artifactRepairIssueKeyPartsAlloc(alloc, key) catch |err| switch (err) {
            error.OutOfMemory => return err,
            error.InvalidInternalUserKey => return .{ .malformed = err },
        };
        return .{ .valid = parts };
    }

    const RetiredArtifactRepairIssueValueDecode = union(enum) {
        valid: types.ArtifactRepairIssue,
        malformed: anyerror,
    };

    fn decodeRetiredArtifactRepairIssueAlloc(
        alloc: Allocator,
        raw: []const u8,
    ) !RetiredArtifactRepairIssueValueDecode {
        const issue = decodeArtifactRepairIssueValueAlloc(alloc, raw) catch |err| switch (err) {
            error.OutOfMemory => return err,
            else => return .{ .malformed = err },
        };
        return .{ .valid = issue };
    }

    fn drainRetiredIndexArtifactRepairIssuesPageContext(
        ctx: *AsyncContext,
        index_name: []const u8,
    ) !bool {
        // Summary rebuilds own the apply lock, while issue publication and
        // terminal-marker transitions own the repair mutex. This ordering is
        // shared by derived apply paths and prevents a cleanup batch from
        // racing either authority.
        ctx.apply_mutex.lockExclusive();
        defer ctx.apply_mutex.unlockExclusive();
        lockAtomicWithBackoff(&ctx.artifact_repair_issue_mutex);
        defer ctx.artifact_repair_issue_mutex.unlock();

        const prefix = try internal_keys.artifactRepairIssueIndexPrefixAlloc(ctx.alloc, index_name);
        defer ctx.alloc.free(prefix);
        const rows = try ctx.store.scanPrefixPage(
            ctx.alloc,
            prefix,
            null,
            retired_index_artifact_repair_cleanup_page_size,
        );
        defer docstore_mod.DocStore.freeResults(ctx.alloc, rows);
        if (rows.len == 0) {
            // Primary records are authoritative. Sweep legacy orphaned
            // kind-index rows in bounded pages before releasing admission.
            for (std.meta.tags(types.ArtifactRepairKind)) |kind| {
                const kind_prefix = try internal_keys.artifactRepairIssueKindIndexPrefixAlloc(
                    ctx.alloc,
                    @tagName(kind),
                    index_name,
                );
                defer ctx.alloc.free(kind_prefix);
                const secondary_rows = try ctx.store.scanPrefixPage(
                    ctx.alloc,
                    kind_prefix,
                    null,
                    retired_index_artifact_repair_cleanup_page_size,
                );
                defer docstore_mod.DocStore.freeResults(ctx.alloc, secondary_rows);
                if (secondary_rows.len == 0) continue;
                const secondary_deletes = try ctx.alloc.alloc([]const u8, secondary_rows.len);
                defer ctx.alloc.free(secondary_deletes);
                for (secondary_rows, 0..) |row, i| secondary_deletes[i] = row.key;
                try ctx.store.putBatch(&.{}, secondary_deletes);
                return true;
            }
            return false;
        }

        var writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
        defer {
            for (writes.items) |write| ctx.alloc.free(@constCast(write.value));
            writes.deinit(ctx.alloc);
        }
        var deletes = std.ArrayListUnmanaged([]const u8).empty;
        defer deletes.deinit(ctx.alloc);
        var owned_keys = std.ArrayListUnmanaged([]const u8).empty;
        defer {
            for (owned_keys.items) |key| ctx.alloc.free(@constCast(key));
            owned_keys.deinit(ctx.alloc);
        }
        const Batch = struct {
            fn appendOwnedDelete(
                alloc: Allocator,
                out_deletes: *std.ArrayListUnmanaged([]const u8),
                out_owned_keys: *std.ArrayListUnmanaged([]const u8),
                key: []u8,
            ) !void {
                errdefer alloc.free(key);
                const owned_len = out_owned_keys.items.len;
                try out_owned_keys.append(alloc, key);
                errdefer out_owned_keys.shrinkRetainingCapacity(owned_len);
                try out_deletes.append(alloc, key);
            }
        };

        var removed_issue_count: usize = 0;
        for (rows) |row| {
            // A coalesced issue can own arbitrarily many historical failure
            // markers. Drain exactly one marker page and leave the primary
            // issue present until a later pass observes the reverse namespace
            // empty; this is the durable cursor across crashes and reopen.
            const marker_count = try appendEnrichmentTerminalFailureMarkerDeletePageForIssue(
                ctx.alloc,
                ctx.store,
                row.key,
                &deletes,
                &owned_keys,
            );
            if (marker_count != 0) {
                if (removed_issue_count != 0) {
                    try appendArtifactRepairSummaryDirtyMarkerForStore(ctx.alloc, &writes, &deletes, &owned_keys);
                }
                try ctx.store.putBatch(writes.items, deletes.items);
                return true;
            }

            try deletes.append(ctx.alloc, row.key);
            removed_issue_count += 1;

            // The marker generation is keyed by the authoritative primary
            // key, so it is safe to retire even when the value is malformed.
            const generation_key = try internal_keys.enrichmentTerminalFailureGenerationKeyAlloc(ctx.alloc, row.key);
            try Batch.appendOwnedDelete(ctx.alloc, &deletes, &owned_keys, generation_key);

            var parts = switch (try parseRetiredArtifactRepairIssueKeyAlloc(ctx.alloc, row.key)) {
                .valid => |value| value,
                .malformed => |err| {
                    std.log.warn("retired index cleanup removed malformed artifact repair key index={s} err={s}", .{
                        index_name,
                        @errorName(err),
                    });
                    continue;
                },
            };
            defer parts.deinit(ctx.alloc);
            if (!std.mem.eql(u8, parts.index_name, index_name)) return error.InvalidInternalUserKey;

            const kind_key = try internal_keys.artifactRepairIssueKindKeyAlloc(
                ctx.alloc,
                parts.repair_artifact_kind,
                parts.index_name,
                parts.issue_id,
            );
            try Batch.appendOwnedDelete(ctx.alloc, &deletes, &owned_keys, kind_key);

            var issue_valid = true;
            var issue = switch (try decodeRetiredArtifactRepairIssueAlloc(ctx.alloc, row.value)) {
                .valid => |value| value,
                .malformed => |err| issue: {
                    issue_valid = false;
                    std.log.warn("retired index cleanup removed malformed artifact repair issue index={s} err={s}", .{
                        index_name,
                        @errorName(err),
                    });
                    break :issue types.ArtifactRepairIssue{};
                },
            };
            defer if (issue_valid) issue.deinit(ctx.alloc);
            if (issue_valid) {
                const expected_issue_key = try artifactRepairIssueKeyForIssueAlloc(ctx.alloc, issue);
                defer ctx.alloc.free(expected_issue_key);
                issue_valid = std.mem.eql(u8, issue.index_name, index_name) and
                    std.mem.eql(u8, expected_issue_key, row.key);
                if (!issue_valid) {
                    issue.deinit(ctx.alloc);
                    std.log.warn("retired index cleanup removed mismatched artifact repair issue index={s}", .{index_name});
                }
            }

            const completion_key = try internal_keys.artifactRepairCompletionKeyAlloc(
                ctx.alloc,
                parts.repair_artifact_kind,
                parts.issue_id,
            );
            var completion_key_local = true;
            defer if (completion_key_local) ctx.alloc.free(completion_key);
            if (!issue_valid) {
                // Completion fences are only a single-flight optimization. A
                // corrupt consumer value cannot safely contribute to their
                // shared count, so discard the fence rather than let stale
                // completed state suppress future repair.
                try Batch.appendOwnedDelete(ctx.alloc, &deletes, &owned_keys, completion_key);
                completion_key_local = false;
                continue;
            }
            if (issue.reason != .enrichment_failed) {
                continue;
            }

            const completion = (try loadArtifactRepairCompletionStateFromStore(
                ctx.alloc,
                ctx.store,
                completion_key,
            )) orelse continue;
            var updated_completion = completion;
            updated_completion.pending_issues -|= 1;
            if (updated_completion.pending_issues == 0) {
                try Batch.appendOwnedDelete(ctx.alloc, &deletes, &owned_keys, completion_key);
                completion_key_local = false;
            } else {
                const owned_len = owned_keys.items.len;
                owned_keys.append(ctx.alloc, completion_key) catch |err| {
                    return err;
                };
                errdefer owned_keys.shrinkRetainingCapacity(owned_len);
                const encoded = try ctx.alloc.create([artifact_repair_completion_state_len]u8);
                errdefer ctx.alloc.destroy(encoded);
                encodeArtifactRepairCompletionState(encoded, updated_completion);
                try writes.append(ctx.alloc, .{ .key = completion_key, .value = encoded });
                completion_key_local = false;
            }
        }

        try appendArtifactRepairSummaryDirtyMarkerForStore(ctx.alloc, &writes, &deletes, &owned_keys);
        try ctx.store.putBatch(writes.items, deletes.items);
        return true;
    }

    fn finalizeRetiredIndexCleanupContext(ctx: *AsyncContext, index_name: []const u8, cleanup_key: []const u8) !void {
        // Filesystem/cache cleanup is intentionally outside the DB apply lock.
        // The durable tombstone blocks overlapping artifact namespaces while
        // this runs.
        try ctx.index_manager.finalizeRetiredIndexStorage(ctx.store, index_name);

        ctx.apply_mutex.lockExclusive();
        defer ctx.apply_mutex.unlockExclusive();
        if (ctx.index_manager.get(index_name) != null) return error.IndexGenerationStillActive;

        const storage_alloc = ctx.index_manager.alloc;
        if (try indexRepairIdForIndexContext(ctx, storage_alloc, index_name)) |repair_id| {
            removeIndexRepairIntentAndPinContext(ctx, storage_alloc, repair_id) catch |err| switch (err) {
                error.IndexRepairIntentNotFound, error.FileNotFound => {},
                else => return err,
            };
        }
        try deleteDenseArtifactCounterMetadataContext(storage_alloc, ctx.store, index_name);
        ctx.store.delete(cleanup_key) catch |err| switch (err) {
            error.NotFound => {},
            else => return err,
        };
    }

    fn rejectConflictingRetiredIndexCleanupForAdmission(self: *DB, cfg: types.IndexConfig) !void {
        lockAtomicWithBackoff(&self.async_context.index_artifact_cleanup_mutex);
        defer self.async_context.index_artifact_cleanup_mutex.unlock();
        const retired_name = (try self.core.index_manager.pendingGeneratedArtifactCleanupIndexForConfigAlloc(
            self.core.store,
            cfg,
        )) orelse return;
        defer self.alloc.free(retired_name);
        self.scheduleGeneratedArtifactCleanup();
        return error.IndexArtifactCleanupPending;
    }

    fn beginIndexRepairLease(self: *DB, index_name: []const u8) !bool {
        lockAtomic(&self.index_repair_mutex);
        defer self.index_repair_mutex.unlock();
        if (self.active_index_repairs.contains(index_name)) return false;
        const owned = try self.alloc.dupe(u8, index_name);
        errdefer self.alloc.free(owned);
        try self.active_index_repairs.put(self.alloc, owned, false);
        return true;
    }

    fn activeIndexRepairCancellationRequested(self: *DB, index_name: []const u8) bool {
        lockAtomic(&self.index_repair_mutex);
        defer self.index_repair_mutex.unlock();
        return self.active_index_repairs.get(index_name) orelse false;
    }

    fn requestActiveIndexRepairCancellation(self: *DB, index_name: []const u8) bool {
        lockAtomic(&self.index_repair_mutex);
        defer self.index_repair_mutex.unlock();
        const requested = self.active_index_repairs.getPtr(index_name) orelse return false;
        requested.* = true;
        return true;
    }

    fn endIndexRepairLease(self: *DB, index_name: []const u8) void {
        lockAtomic(&self.index_repair_mutex);
        defer self.index_repair_mutex.unlock();
        if (self.active_index_repairs.fetchRemove(index_name)) |removed| {
            self.alloc.free(@constCast(removed.key));
        }
    }

    fn primaryUserNamespaceIsEmptyLocked(self: *DB) !bool {
        var txn = try self.core.store.beginCurrentScanTxn();
        defer txn.abort();
        var cur = try txn.openCursor();
        defer cur.close();

        const lower = [_]u8{internal_keys.user_namespace};
        const first = (try cur.seekAtOrAfter(lower[0..])) orelse return true;
        return first.key.len == 0 or first.key[0] != internal_keys.user_namespace;
    }

    fn rememberBulkIngestAllNewIdentityUpserts(self: *DB, doc_ids: []const []const u8) !bool {
        var batch_seen = std.StringHashMapUnmanaged(void).empty;
        defer batch_seen.deinit(self.alloc);
        for (doc_ids) |doc_id| {
            if (self.bulk_ingest_seen_doc_keys.contains(doc_id)) return false;
            if (batch_seen.contains(doc_id)) return false;
            try batch_seen.put(self.alloc, doc_id, {});
        }

        for (doc_ids) |doc_id| {
            const owned = try self.alloc.dupe(u8, doc_id);
            errdefer self.alloc.free(owned);
            try self.bulk_ingest_seen_doc_keys.put(self.alloc, owned, {});
        }
        return true;
    }

    fn identityUpsertStoreWritesAreNew(write_indexes: []const usize, overwritten_flags: []const bool) bool {
        for (write_indexes) |write_index| {
            if (write_index >= overwritten_flags.len) return false;
            if (overwritten_flags[write_index]) return false;
        }
        return true;
    }

    fn CoalescedKeyValueRequest(comptime T: type) type {
        return struct {
            const Entry = struct {
                key: []const u8,
                value: ?[]const u8 = null,
                kind: enum { write, delete },
                owned_key: bool = false,
                owned_value: bool = false,
            };

            entries: []Entry = &.{},
            writes: []T = &.{},
            deletes: [][]const u8 = &.{},
            graph_writes: std.ArrayListUnmanaged(types.GraphEdgeWrite) = .empty,

            fn deinit(self: *@This(), alloc: Allocator) void {
                for (self.entries) |entry| {
                    if (entry.owned_key) alloc.free(@constCast(entry.key));
                    if (entry.owned_value) alloc.free(@constCast(entry.value.?));
                }
                if (self.entries.len > 0) alloc.free(self.entries);
                if (self.writes.len > 0) alloc.free(self.writes);
                if (self.deletes.len > 0) alloc.free(self.deletes);
                for (self.graph_writes.items) |*write| deinitOwnedGraphEdgeWrite(alloc, write);
                self.graph_writes.deinit(alloc);
                self.* = .{};
            }
        };
    }

    fn deinitOwnedGraphEdgeWrite(alloc: Allocator, write: *types.GraphEdgeWrite) void {
        alloc.free(@constCast(write.index_name));
        alloc.free(@constCast(write.source));
        alloc.free(@constCast(write.target));
        alloc.free(@constCast(write.edge_type));
        if (write.metadata_json.len > 0) alloc.free(@constCast(write.metadata_json));
        write.* = undefined;
    }

    fn appendGraphTransformWrite(
        self: *DB,
        writes: *std.ArrayListUnmanaged(types.GraphEdgeWrite),
        source: []const u8,
        path: transform_mod.GraphProjectionPath,
        value_json: []const u8,
    ) !void {
        var parsed = try std.json.parseFromSlice(std.json.Value, self.alloc, value_json, .{});
        defer parsed.deinit();
        if (parsed.value != .object) return error.InvalidGraphEdges;

        const target_value = parsed.value.object.get("target") orelse return error.InvalidGraphEdges;
        if (target_value != .string or target_value.string.len == 0) return error.InvalidGraphEdges;

        const weight: f64 = if (parsed.value.object.get("weight")) |value| switch (value) {
            .integer => |integer| @floatFromInt(integer),
            .float => |float| float,
            .number_string => |number| try std.fmt.parseFloat(f64, number),
            else => return error.InvalidGraphEdges,
        } else 1.0;
        if (!std.math.isFinite(weight)) return error.InvalidGraphEdges;

        const metadata_json: []const u8 = if (parsed.value.object.get("metadata")) |metadata|
            try std.json.Stringify.valueAlloc(self.alloc, metadata, .{})
        else
            "";
        errdefer if (metadata_json.len > 0) self.alloc.free(@constCast(metadata_json));

        const index_name = try self.alloc.dupe(u8, path.index_name);
        errdefer self.alloc.free(index_name);
        const owned_source = try self.alloc.dupe(u8, source);
        errdefer self.alloc.free(owned_source);
        const target = try self.alloc.dupe(u8, target_value.string);
        errdefer self.alloc.free(target);
        const edge_type = try self.alloc.dupe(u8, path.edge_type);
        errdefer self.alloc.free(edge_type);

        try writes.append(self.alloc, .{
            .index_name = index_name,
            .source = owned_source,
            .target = target,
            .edge_type = edge_type,
            .weight = weight,
            .metadata_json = metadata_json,
        });
    }

    const BulkIngestCoalescer = struct {
        const Stats = struct {
            active_session: std.atomic.Value(u8) = .init(0),
            staged_keys: AtomicU64 = .init(0),
            stage_batches: AtomicU64 = .init(0),
            stage_writes: AtomicU64 = .init(0),
            stage_deletes: AtomicU64 = .init(0),
            stage_transforms: AtomicU64 = .init(0),
            flush_calls: AtomicU64 = .init(0),
            flushed_keys: AtomicU64 = .init(0),

            fn snapshot(self: *const @This()) types.BulkCoalescingStats {
                return .{
                    .active_session = self.active_session.load(.monotonic) != 0,
                    .staged_keys = self.staged_keys.load(.monotonic),
                    .stage_batches = self.stage_batches.load(.monotonic),
                    .stage_writes = self.stage_writes.load(.monotonic),
                    .stage_deletes = self.stage_deletes.load(.monotonic),
                    .stage_transforms = self.stage_transforms.load(.monotonic),
                    .flush_calls = self.flush_calls.load(.monotonic),
                    .flushed_keys = self.flushed_keys.load(.monotonic),
                };
            }
        };

        const Entry = struct {
            key: []u8,
            value: ?[]u8 = null,
            kind: enum { write, delete },
        };

        const RequestView = struct {
            writes: []types.BatchWrite = &.{},
            deletes: [][]const u8 = &.{},

            fn deinit(self: @This(), alloc: Allocator) void {
                if (self.writes.len > 0) alloc.free(self.writes);
                if (self.deletes.len > 0) alloc.free(self.deletes);
            }
        };

        active: bool = false,
        entries: std.ArrayListUnmanaged(Entry) = .empty,
        positions: std.StringHashMapUnmanaged(usize) = .empty,
        stats: Stats = .{},

        fn begin(self: *@This()) void {
            self.active = true;
            self.stats.active_session.store(1, .monotonic);
        }

        fn deinit(self: *@This(), alloc: Allocator) void {
            self.clear(alloc);
            self.entries.deinit(alloc);
            self.positions.deinit(alloc);
            self.* = .{};
        }

        fn clear(self: *@This(), alloc: Allocator) void {
            self.resetPending(alloc);
            self.active = false;
            self.stats.active_session.store(0, .monotonic);
        }

        fn resetPending(self: *@This(), alloc: Allocator) void {
            for (self.entries.items) |entry| {
                alloc.free(entry.key);
                if (entry.value) |value| alloc.free(value);
            }
            self.entries.clearRetainingCapacity();
            self.positions.clearRetainingCapacity();
            self.stats.staged_keys.store(0, .monotonic);
        }

        fn hasPending(self: *const @This()) bool {
            return self.entries.items.len > 0;
        }

        fn snapshotRequestView(self: *const @This(), alloc: Allocator) !RequestView {
            var result = RequestView{};
            errdefer result.deinit(alloc);

            var write_count: usize = 0;
            var delete_count: usize = 0;
            for (self.entries.items) |entry| {
                switch (entry.kind) {
                    .write => write_count += 1,
                    .delete => delete_count += 1,
                }
            }

            if (write_count > 0) result.writes = try alloc.alloc(types.BatchWrite, write_count);
            if (delete_count > 0) result.deletes = try alloc.alloc([]const u8, delete_count);

            var write_index: usize = 0;
            var delete_index: usize = 0;
            for (self.entries.items) |entry| {
                switch (entry.kind) {
                    .write => {
                        result.writes[write_index] = .{
                            .key = entry.key,
                            .value = entry.value.?,
                        };
                        write_index += 1;
                    },
                    .delete => {
                        result.deletes[delete_index] = entry.key;
                        delete_index += 1;
                    },
                }
            }
            return result;
        }

        fn stageBatch(self: *@This(), db: *DB, req: types.BatchRequest) !void {
            std.debug.assert(self.active);
            _ = self.stats.stage_batches.fetchAdd(1, .monotonic);
            _ = self.stats.stage_writes.fetchAdd(@intCast(req.writes.len), .monotonic);
            _ = self.stats.stage_deletes.fetchAdd(@intCast(req.deletes.len), .monotonic);
            _ = self.stats.stage_transforms.fetchAdd(@intCast(req.transforms.len), .monotonic);

            for (req.writes) |write| {
                try self.stageWrite(db.alloc, write.key, write.value);
            }
            for (req.deletes) |key| {
                try self.stageDelete(db.alloc, key);
            }
            for (req.transforms) |transform| {
                try self.stageTransform(db, transform);
            }
            self.stats.staged_keys.store(@intCast(self.entries.items.len), .monotonic);
        }

        fn stageWrite(self: *@This(), alloc: Allocator, key: []const u8, value: []const u8) !void {
            const gop = try self.positions.getOrPut(alloc, key);
            if (!gop.found_existing) {
                const owned_key = try alloc.dupe(u8, key);
                errdefer alloc.free(owned_key);
                const owned_value = try alloc.dupe(u8, value);
                errdefer alloc.free(owned_value);
                gop.key_ptr.* = owned_key;
                gop.value_ptr.* = self.entries.items.len;
                try self.entries.append(alloc, .{
                    .key = owned_key,
                    .value = owned_value,
                    .kind = .write,
                });
                return;
            }

            const entry = &self.entries.items[gop.value_ptr.*];
            if (entry.value) |existing| alloc.free(existing);
            entry.value = try alloc.dupe(u8, value);
            entry.kind = .write;
        }

        fn stageDelete(self: *@This(), alloc: Allocator, key: []const u8) !void {
            const gop = try self.positions.getOrPut(alloc, key);
            if (!gop.found_existing) {
                const owned_key = try alloc.dupe(u8, key);
                errdefer alloc.free(owned_key);
                gop.key_ptr.* = owned_key;
                gop.value_ptr.* = self.entries.items.len;
                try self.entries.append(alloc, .{
                    .key = owned_key,
                    .kind = .delete,
                });
                return;
            }

            const entry = &self.entries.items[gop.value_ptr.*];
            if (entry.value) |existing| {
                alloc.free(existing);
                entry.value = null;
            }
            entry.kind = .delete;
        }

        fn stageTransform(self: *@This(), db: *DB, transform: types.DocumentTransform) !void {
            const existing = if (self.positions.get(transform.key)) |entry_index|
                switch (self.entries.items[entry_index].kind) {
                    .write => self.entries.items[entry_index].value,
                    .delete => null,
                }
            else
                try db.get(db.alloc, transform.key);
            defer if (self.positions.get(transform.key) == null) {
                if (existing) |body| db.alloc.free(body);
            };

            const resolved = try transform_mod.resolveDocumentTransform(db.alloc, existing, transform) orelse return;
            errdefer db.alloc.free(resolved);
            try self.stageWriteOwned(db.alloc, transform.key, resolved);
        }

        fn stageWriteOwned(self: *@This(), alloc: Allocator, key: []const u8, owned_value: []u8) !void {
            const gop = try self.positions.getOrPut(alloc, key);
            if (!gop.found_existing) {
                const owned_key = try alloc.dupe(u8, key);
                errdefer alloc.free(owned_key);
                gop.key_ptr.* = owned_key;
                gop.value_ptr.* = self.entries.items.len;
                try self.entries.append(alloc, .{
                    .key = owned_key,
                    .value = owned_value,
                    .kind = .write,
                });
                return;
            }

            const entry = &self.entries.items[gop.value_ptr.*];
            if (entry.value) |existing| alloc.free(existing);
            entry.value = owned_value;
            entry.kind = .write;
        }
    };

    fn resetCoalescedEntryToDelete(comptime T: type, entry: *CoalescedKeyValueRequest(T).Entry) void {
        if (entry.owned_value) {
            // Caller frees previous owned value before switching the entry.
            entry.owned_value = false;
        }
        entry.value = null;
        entry.kind = .delete;
    }

    fn setCoalescedEntryToBorrowedWrite(comptime T: type, entry: *CoalescedKeyValueRequest(T).Entry, write: T) void {
        entry.key = write.key;
        entry.value = write.value;
        entry.kind = .write;
        entry.owned_key = false;
        entry.owned_value = false;
    }

    fn setCoalescedEntryToOwnedWrite(
        comptime T: type,
        alloc: Allocator,
        entry: *CoalescedKeyValueRequest(T).Entry,
        key: []const u8,
        value: []u8,
    ) !void {
        if (!entry.owned_key) {
            entry.key = try alloc.dupe(u8, key);
            entry.owned_key = true;
        }
        entry.value = value;
        entry.kind = .write;
        entry.owned_value = true;
    }

    fn coalesceKeyValueRequest(
        self: *DB,
        comptime T: type,
        writes: []const T,
        deletes: []const []const u8,
        transforms: []const types.DocumentTransform,
    ) !CoalescedKeyValueRequest(T) {
        var result = CoalescedKeyValueRequest(T){};
        var order = std.ArrayListUnmanaged(CoalescedKeyValueRequest(T).Entry).empty;
        defer order.deinit(self.alloc);
        var entries_transferred = false;
        errdefer {
            if (!entries_transferred) {
                result.entries = order.items;
                order.items = &.{};
                order.capacity = 0;
            }
            result.deinit(self.alloc);
        }

        var positions = std.StringHashMapUnmanaged(usize){};
        defer positions.deinit(self.alloc);

        for (writes) |write| {
            const gop = try positions.getOrPut(self.alloc, write.key);
            if (!gop.found_existing) {
                gop.value_ptr.* = order.items.len;
                try order.append(self.alloc, .{
                    .key = write.key,
                    .value = write.value,
                    .kind = .write,
                });
                continue;
            }
            const entry = &order.items[gop.value_ptr.*];
            if (entry.owned_value) self.alloc.free(@constCast(entry.value.?));
            if (entry.owned_key) self.alloc.free(@constCast(entry.key));
            setCoalescedEntryToBorrowedWrite(T, entry, write);
        }

        for (deletes) |key| {
            const gop = try positions.getOrPut(self.alloc, key);
            if (!gop.found_existing) {
                gop.value_ptr.* = order.items.len;
                try order.append(self.alloc, .{
                    .key = key,
                    .kind = .delete,
                });
                continue;
            }
            const entry = &order.items[gop.value_ptr.*];
            if (entry.owned_value) self.alloc.free(@constCast(entry.value.?));
            entry.owned_value = false;
            resetCoalescedEntryToDelete(T, entry);
        }

        for (transforms) |transform| {
            const maybe_index = positions.get(transform.key);
            const base_json = blk: {
                if (maybe_index) |entry_index| {
                    const entry = order.items[entry_index];
                    break :blk if (entry.kind == .write) entry.value.? else null;
                }
                break :blk try self.get(self.alloc, transform.key);
            };
            defer if (maybe_index == null) {
                if (base_json) |body| self.alloc.free(body);
            };

            var document_operations = std.ArrayListUnmanaged(types.TransformOp).empty;
            defer document_operations.deinit(self.alloc);
            var graph_operations = std.ArrayListUnmanaged(struct {
                path: transform_mod.GraphProjectionPath,
                value_json: []const u8,
            }).empty;
            defer graph_operations.deinit(self.alloc);
            for (transform.operations) |operation| {
                const graph_path = try transform_mod.graphProjectionPath(operation.path);
                if (graph_path) |path| {
                    switch (operation.op) {
                        .push, .add_to_set => {},
                        else => return error.UnsupportedTransformOperation,
                    }
                    try graph_operations.append(self.alloc, .{
                        .path = path,
                        .value_json = operation.value_json orelse return error.InvalidArgument,
                    });
                } else {
                    try document_operations.append(self.alloc, operation);
                }
            }

            const graph_writes_start = result.graph_writes.items.len;
            for (graph_operations.items) |operation| {
                try self.appendGraphTransformWrite(
                    &result.graph_writes,
                    transform.key,
                    operation.path,
                    operation.value_json,
                );
            }

            const document_transform: types.DocumentTransform = .{
                .key = transform.key,
                .operations = document_operations.items,
                .upsert = transform.upsert,
            };

            // A non-upsert transform against an absent (or same-batch deleted)
            // document is a no-op, but malformed document operations remain
            // errors independent of state. Graph operands were validated while
            // constructing their pending deltas above.
            if (base_json == null and !transform.upsert) {
                try transform_mod.validateDocumentTransform(self.alloc, document_transform);
                for (result.graph_writes.items[graph_writes_start..]) |*write| {
                    deinitOwnedGraphEdgeWrite(self.alloc, write);
                }
                result.graph_writes.shrinkRetainingCapacity(graph_writes_start);
                continue;
            }

            // Even a graph-only transform remains a logical document write:
            // preserve source version/timestamp and change-journal semantics
            // while applying the projected edge as a delta. The mapper sees
            // the unchanged stripped document and therefore does not clear
            // the graph generation.
            const resolved = try transform_mod.resolveDocumentTransform(self.alloc, base_json, document_transform);

            const resolved_document = resolved orelse continue;
            var resolved_document_owned = true;
            defer if (resolved_document_owned) self.alloc.free(resolved_document);

            const gop = try positions.getOrPut(self.alloc, transform.key);
            if (!gop.found_existing) {
                gop.value_ptr.* = order.items.len;
                try order.append(self.alloc, .{
                    .key = try self.alloc.dupe(u8, transform.key),
                    .value = resolved_document,
                    .kind = .write,
                    .owned_key = true,
                    .owned_value = true,
                });
                resolved_document_owned = false;
                continue;
            }

            const entry = &order.items[gop.value_ptr.*];
            if (entry.owned_value) self.alloc.free(@constCast(entry.value.?));
            try setCoalescedEntryToOwnedWrite(T, self.alloc, entry, transform.key, resolved_document);
            resolved_document_owned = false;
        }

        var write_count: usize = 0;
        var delete_count: usize = 0;
        for (order.items) |entry| {
            switch (entry.kind) {
                .write => write_count += 1,
                .delete => delete_count += 1,
            }
        }

        const final_entries = try order.toOwnedSlice(self.alloc);
        result.entries = final_entries;
        entries_transferred = true;
        if (write_count > 0) result.writes = try self.alloc.alloc(T, write_count);
        if (delete_count > 0) result.deletes = try self.alloc.alloc([]const u8, delete_count);

        var write_index: usize = 0;
        var delete_index: usize = 0;
        for (final_entries) |entry| {
            switch (entry.kind) {
                .write => {
                    result.writes[write_index] = .{
                        .key = entry.key,
                        .value = entry.value.?,
                    };
                    write_index += 1;
                },
                .delete => {
                    result.deletes[delete_index] = entry.key;
                    delete_index += 1;
                },
            }
        }
        return result;
    }

    fn flushBulkIngestCoalescerWithSyncLevel(self: *DB, sync_level: types.SyncLevel, profile: ?*BatchProfile) anyerror!void {
        if (!self.bulk_ingest_coalescer.active or !self.bulk_ingest_coalescer.hasPending()) return;
        _ = self.bulk_ingest_coalescer.stats.flush_calls.fetchAdd(1, .monotonic);
        _ = self.bulk_ingest_coalescer.stats.flushed_keys.fetchAdd(@intCast(self.bulk_ingest_coalescer.entries.items.len), .monotonic);

        lockApply(self);
        var view = try self.bulk_ingest_coalescer.snapshotRequestView(self.alloc);
        self.core.unlockApply();
        defer view.deinit(self.alloc);

        self.flushing_bulk_ingest_coalescer = true;
        defer self.flushing_bulk_ingest_coalescer = false;

        try self.batchInternal(.{
            .writes = view.writes,
            .deletes = view.deletes,
            .sync_level = sync_level,
        }, profile, .{ .store_batch_options = .{ .mode = .bulk_ingest, .defer_commit_flush = true } });

        lockApply(self);
        defer self.core.unlockApply();
        self.bulk_ingest_coalescer.resetPending(self.alloc);
        self.bulk_ingest_coalescer.active = true;
    }

    pub fn get(self: *DB, alloc: Allocator, key: []const u8) !?[]u8 {
        const store_key = try encodeStoreLookupKeyAlloc(alloc, key);
        defer alloc.free(store_key);
        return try self.core.getStoreValue(alloc, store_key);
    }

    pub fn getGroupCreatedAtMillis(self: *DB, alloc: Allocator, group_id: u64) !?u64 {
        const key = try groupCreatedAtMetadataKeyAlloc(alloc, group_id);
        defer alloc.free(key);
        const raw = try self.get(alloc, key) orelse return null;
        defer alloc.free(raw);
        return try std.fmt.parseInt(u64, raw, 10);
    }

    pub fn ensureGroupCreatedAtMillis(self: *DB, alloc: Allocator, group_id: u64, now_ms: u64) !u64 {
        if (try self.getGroupCreatedAtMillis(alloc, group_id)) |created_at_millis| return created_at_millis;

        const key = try groupCreatedAtMetadataKeyAlloc(alloc, group_id);
        defer alloc.free(key);
        const encoded = try std.fmt.allocPrint(alloc, "{d}", .{now_ms});
        defer alloc.free(encoded);

        try self.batch(.{
            .writes = &.{
                .{
                    .key = key,
                    .value = encoded,
                },
            },
        });
        return now_ms;
    }

    pub fn getArtifact(self: *DB, alloc: Allocator, artifact_id: []const u8) !?types.ArtifactRecord {
        var artifact_ref = (try artifact_ids.decodeArtifactPublicIdAlloc(alloc, artifact_id)) orelse return error.InvalidArgument;
        errdefer artifact_ref.deinit(alloc);

        const internal_key = try artifact_ids.internalKeyForArtifactRefAlloc(alloc, artifact_ref);
        defer alloc.free(internal_key);

        const value = try self.core.getStoreValue(alloc, internal_key) orelse return null;
        errdefer alloc.free(value);

        return .{
            .id = try alloc.dupe(u8, artifact_id),
            .value = value,
            .artifact_ref = artifact_ref,
        };
    }

    /// Returns an artifact through a public response boundary. Raw artifact
    /// values are retained internally because compute/apply transports need
    /// storage metadata, while public lookup must never expose hierarchy
    /// revision fingerprints or coordinator envelopes.
    pub fn getPublicArtifact(self: *DB, alloc: Allocator, artifact_id: []const u8) !?types.ArtifactRecord {
        var artifact = (try self.getArtifact(alloc, artifact_id)) orelse return null;
        errdefer artifact.deinit(alloc);
        const public_value = try hierarchy_navigation.publicArtifactPayloadAlloc(alloc, artifact.value);
        alloc.free(artifact.value);
        artifact.value = public_value;
        return artifact;
    }

    pub fn getDocumentArtifactManifest(
        self: *DB,
        alloc: Allocator,
        doc_key: []const u8,
        artifact_name: []const u8,
    ) !?types.DocumentArtifactManifest {
        lockApplyShared(self);
        defer self.core.unlockApplyShared();

        const manifest_key = try internal_keys.artifactNamedPrefixAlloc(alloc, doc_key, "asset", artifact_name);
        defer alloc.free(manifest_key);
        const manifest = try self.core.getStoreValue(alloc, manifest_key) orelse return null;
        errdefer alloc.free(manifest);

        const state_key = try assetStateKeyAlloc(alloc, doc_key, artifact_name);
        defer alloc.free(state_key);
        const state = self.core.getStoreValue(alloc, state_key) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
        errdefer if (state) |value| alloc.free(value);

        return try documentArtifactManifestFromJsonAlloc(alloc, doc_key, artifact_name, manifest, state);
    }

    pub fn listDocumentArtifactManifests(
        self: *DB,
        alloc: Allocator,
        doc_key: []const u8,
    ) !types.DocumentArtifactManifestList {
        lockApplyShared(self);
        defer self.core.unlockApplyShared();

        const prefix = try internal_keys.artifactTypePrefixAlloc(alloc, doc_key, "asset");
        defer alloc.free(prefix);
        const rows = try self.core.scanStorePrefix(alloc, prefix);
        defer docstore_mod.DocStore.freeResults(alloc, rows);

        var artifacts = std.ArrayListUnmanaged(types.DocumentArtifactManifest).empty;
        errdefer {
            for (artifacts.items) |*artifact| artifact.deinit(alloc);
            artifacts.deinit(alloc);
        }

        for (rows) |row| {
            var artifact_ref = (try decodeArtifactRefIfKnownAlloc(alloc, row.key)) orelse continue;
            defer artifact_ref.deinit(alloc);
            if (artifact_ref.kind != .asset) continue;
            if (artifact_ref.unit_id != null) continue;
            if (!std.mem.eql(u8, artifact_ref.document_id, doc_key)) continue;

            const state_key = try assetStateKeyAlloc(alloc, doc_key, artifact_ref.name);
            defer alloc.free(state_key);
            const state = self.core.getStoreValue(alloc, state_key) catch |err| switch (err) {
                error.NotFound => null,
                else => return err,
            };
            errdefer if (state) |value| alloc.free(value);

            const manifest_json = try alloc.dupe(u8, row.value);
            errdefer alloc.free(manifest_json);
            try artifacts.append(
                alloc,
                try documentArtifactManifestFromJsonAlloc(alloc, doc_key, artifact_ref.name, manifest_json, state),
            );
        }

        return .{
            .document_id = try alloc.dupe(u8, doc_key),
            .artifacts = try artifacts.toOwnedSlice(alloc),
        };
    }

    pub fn updateDocumentArtifactChildRangePlacement(
        self: *DB,
        alloc: Allocator,
        doc_key: []const u8,
        artifact_name: []const u8,
        update: types.DocumentArtifactChildRangePlacementUpdate,
    ) !bool {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        var ha_mutation = self.acquireHAMutationShared();
        defer if (ha_mutation) |*lease| lease.release();
        try self.enforceHAWriteGate();
        try self.executor.failIfUnhealthy();

        lockApply(self);
        var apply_mutex_held = true;
        errdefer if (apply_mutex_held) self.core.unlockApply();

        const manifest_key = try internal_keys.artifactNamedPrefixAlloc(alloc, doc_key, "asset", artifact_name);
        defer alloc.free(manifest_key);
        const manifest = try self.core.getStoreValue(alloc, manifest_key) orelse {
            self.core.unlockApply();
            apply_mutex_held = false;
            return false;
        };
        defer alloc.free(manifest);

        var arena = std.heap.ArenaAllocator.init(alloc);
        defer arena.deinit();
        const arena_alloc = arena.allocator();
        var manifest_value = try std.json.parseFromSliceLeaky(std.json.Value, arena_alloc, manifest, .{ .allocate = .alloc_always });
        if (manifest_value != .object) return error.InvalidArgument;
        const child_ranges = manifest_value.object.getPtr("child_ranges") orelse return error.InvalidArgument;
        if (child_ranges.* != .array) return error.InvalidArgument;

        var changed = false;
        for (child_ranges.array.items) |*item| {
            if (item.* != .object) return error.InvalidArgument;
            const range_id = item.object.get("range_id") orelse return error.InvalidArgument;
            if (range_id != .string) return error.InvalidArgument;
            if (!std.mem.eql(u8, range_id.string, update.range_id)) continue;

            try putLeakyJsonStringField(arena_alloc, &item.object, "placement", update.placement);
            if (update.owner_group_id) |owner_group_id| try putLeakyJsonU64Field(arena_alloc, &item.object, "owner_group_id", owner_group_id);
            if (update.placement_generation) |placement_generation| try putLeakyJsonU64Field(arena_alloc, &item.object, "placement_generation", placement_generation);
            if (update.route_status) |route_status| try putLeakyJsonStringField(arena_alloc, &item.object, "route_status", route_status);
            if (update.split_eligible) |split_eligible| try item.object.put(arena_alloc, "split_eligible", .{ .bool = split_eligible });
            changed = true;
            break;
        }

        if (!changed) {
            self.core.unlockApply();
            apply_mutex_held = false;
            return false;
        }

        const updated_manifest = try std.json.Stringify.valueAlloc(alloc, manifest_value, .{});
        defer alloc.free(updated_manifest);

        const sequence = self.core.reserveDerivedAppendSequence();
        const changed_artifact_keys = [_][]const u8{manifest_key};
        const replay_payload = try encodeChangeRecordPayload(&self.batchContext(), .{
            .sequence = sequence,
            .changed_artifact_keys = changed_artifact_keys[0..],
        }, sequence);
        defer alloc.free(replay_payload);

        const writes = [_]docstore_mod.KVPair{.{
            .key = manifest_key,
            .value = updated_manifest,
        }};
        try self.core.store.putBatchWithReplay(self.backend_runtime.io(), writes[0..], &.{}, .{
            .sequence = sequence,
            .payload = replay_payload,
        });
        self.mirrorHAReplayPayloadBestEffort(replay_payload);
        self.executor.trackBacklogBytes(sequence, @intCast(replay_payload.len)) catch {};
        self.core.unlockApply();
        apply_mutex_held = false;

        if (self.executor.hasWorkers()) {
            self.executor.forceSequence(sequence);
        } else {
            self.executor.notifySequence(sequence);
        }
        self.notifyResolverReplayRuntimes(sequence);
        return true;
    }

    pub fn reprocessDocumentArtifact(
        self: *DB,
        alloc: Allocator,
        doc_key: []const u8,
        artifact_name: []const u8,
    ) !bool {
        var cfg = (try self.getEnrichment(alloc, .asset, artifact_name)) orelse return false;
        defer cfg.deinit(alloc);
        // A missing producer definition means this artifact cannot currently be
        // regenerated. A missing source document is a distinct, actionable
        // repair outcome and must reach the repair API as `missing_source_docs`.
        const value = try self.get(alloc, doc_key) orelse return error.NotFound;
        defer alloc.free(value);

        const writes = [_]types.BatchWrite{.{ .key = doc_key, .value = value }};
        const force_artifacts = [_][]const u8{artifact_name};
        try self.batchInternal(.{
            .writes = &writes,
            .sync_level = .full_index,
        }, null, .{
            .force_generated_artifact_names = &force_artifacts,
        });
        return true;
    }

    pub fn reprocessDocumentEmbeddingArtifact(
        self: *DB,
        alloc: Allocator,
        doc_key: []const u8,
        artifact_name: []const u8,
    ) !bool {
        const issue = types.ArtifactRepairIssue{
            .artifact_kind = .embedding,
            .doc_key = doc_key,
            .artifact_name = artifact_name,
        };
        return self.reprocessEmbeddingArtifactIssue(alloc, issue) catch |err| switch (err) {
            error.NotFound => false,
            else => return err,
        };
    }

    fn reprocessEmbeddingArtifactIssue(
        self: *DB,
        alloc: Allocator,
        issue: types.ArtifactRepairIssue,
    ) !bool {
        var cfg = (try self.getEnrichment(alloc, .embedding, issue.artifact_name)) orelse return false;
        defer cfg.deinit(alloc);

        const source_doc_key = if (issue.parent_doc_key.len > 0) issue.parent_doc_key else issue.doc_key;
        const value = try self.get(alloc, source_doc_key) orelse return error.NotFound;
        defer alloc.free(value);

        const writes = [_]types.BatchWrite{.{ .key = source_doc_key, .value = value }};
        const force_artifacts = [_][]const u8{issue.artifact_name};
        try self.batchInternal(.{
            .writes = &writes,
            .sync_level = .full_index,
        }, null, .{
            .force_generated_artifact_names = &force_artifacts,
        });
        return true;
    }

    fn reprocessChunkArtifactIssue(
        self: *DB,
        alloc: Allocator,
        issue: types.ArtifactRepairIssue,
    ) !bool {
        var cfg = (try self.getEnrichment(alloc, .chunk, issue.artifact_name)) orelse return false;
        defer cfg.deinit(alloc);

        const source_doc_key = if (issue.parent_doc_key.len > 0) issue.parent_doc_key else issue.doc_key;
        const value = try self.get(alloc, source_doc_key) orelse return error.NotFound;
        defer alloc.free(value);

        const writes = [_]types.BatchWrite{.{ .key = source_doc_key, .value = value }};
        const force_artifacts = [_][]const u8{issue.artifact_name};
        try self.batchInternal(.{
            .writes = &writes,
            .sync_level = .full_index,
        }, null, .{
            .force_generated_artifact_names = &force_artifacts,
        });
        return true;
    }

    fn repairIssueKeyForIssueAlloc(self: *DB, alloc: Allocator, issue: types.ArtifactRepairIssue) ![]u8 {
        _ = self;
        return try artifactRepairIssueKeyForIssueAlloc(alloc, issue);
    }

    fn repairIssueKindKeyForIssueAlloc(self: *DB, alloc: Allocator, issue: types.ArtifactRepairIssue) ![]u8 {
        _ = self;
