    fn resolveDocSetForIdsAlloc(self: *DB, alloc: Allocator, doc_ids: []const []const u8) !doc_set.ResolvedDocSet {
        lockApplyShared(self);
        defer self.core.unlockApplyShared();
        return try self.resolveDocSetForIdsNoLockAlloc(alloc, doc_ids);
    }

    fn resolveDocSetForIdsNoLockAlloc(self: *DB, alloc: Allocator, doc_ids: []const []const u8) !doc_set.ResolvedDocSet {
        return try self.resolveDocSetForIdsNoLockAtGenerationAlloc(alloc, doc_ids, null);
    }

    fn resolveDocSetForIdsNoLockAtGenerationAlloc(
        self: *DB,
        alloc: Allocator,
        doc_ids: []const []const u8,
        generation: ?u64,
    ) !doc_set.ResolvedDocSet {
        var txn = try self.core.store.beginProbeTxn();
        defer txn.abort();
        const resolved = try doc_identity.resolvedDocSetForIdsAtGenerationTxn(alloc, &txn, doc_ids, generation);
        self.recordResolvedDocSet(&resolved, doc_ids.len > 0 and switch (resolved) {
            .doc_keys => true,
            else => false,
        });
        return resolved;
    }

    fn resolvedDocFilterForIdsAlloc(
        self: *DB,
        include_positive: bool,
        include_doc_ids: []const []const u8,
        exclude_doc_ids: []const []const u8,
        generation: ?u64,
    ) !doc_set.ResolvedDocFilter {
        var filter = doc_set.ResolvedDocFilter{};
        errdefer filter.deinit(self.alloc);
        if (include_positive) {
            filter.include = try self.resolveDocSetForIdsNoLockAtGenerationAlloc(self.alloc, include_doc_ids, generation);
        }
        if (exclude_doc_ids.len > 0) {
            filter.exclude = try self.resolveDocSetForIdsNoLockAtGenerationAlloc(self.alloc, exclude_doc_ids, generation);
        }
        return filter;
    }

    fn docIdsForResolvedDocSetAlloc(self: *DB, alloc: Allocator, set: *const doc_set.ResolvedDocSet) !?[]const []const u8 {
        lockApplyShared(self);
        defer self.core.unlockApplyShared();
        return try self.docIdsForResolvedDocSetNoLockAlloc(alloc, set);
    }

    fn docIdsForResolvedDocSetNoLockAlloc(self: *DB, alloc: Allocator, set: *const doc_set.ResolvedDocSet) !?[]const []const u8 {
        return try self.docIdsForResolvedDocSetNoLockAtGenerationAlloc(alloc, set, null);
    }

    fn docIdsForResolvedDocSetNoLockAtGenerationAlloc(
        self: *DB,
        alloc: Allocator,
        set: *const doc_set.ResolvedDocSet,
        generation: ?u64,
    ) !?[]const []const u8 {
        switch (set.*) {
            .all => return null,
            .none => return try alloc.alloc([]const u8, 0),
            .doc_keys => |keys| return try dupeConstDocIdsAlloc(alloc, keys),
            .ordinals => |ordinals| {
                var txn = try self.core.store.beginProbeTxn();
                defer txn.abort();
                return try docIdsForOrdinalsAtGenerationTxnAlloc(alloc, &txn, ordinals, generation);
            },
            .ordinal_bitmap => |*bitmap| {
                var txn = try self.core.store.beginProbeTxn();
                defer txn.abort();
                var ordinals = std.ArrayListUnmanaged(doc_set.DocOrdinal).empty;
                defer ordinals.deinit(alloc);
                var iter = bitmap.iterator();
                while (iter.next()) |ordinal| try ordinals.append(alloc, ordinal);
                return try docIdsForOrdinalsAtGenerationTxnAlloc(alloc, &txn, ordinals.items, generation);
            },
        }
    }

    pub fn extractEnrichments(self: *DB, alloc: Allocator, writes: []const types.BatchWrite) !types.ExtractEnrichmentsResult {
        lockApplyShared(self);
        defer self.core.unlockApplyShared();

        var cleaned_writes = std.ArrayListUnmanaged(types.BatchWrite).empty;
        errdefer {
            for (cleaned_writes.items) |write| {
                alloc.free(@constCast(write.key));
                alloc.free(@constCast(write.value));
            }
            cleaned_writes.deinit(alloc);
        }
        var dense_embeddings = std.ArrayListUnmanaged(types.EnrichmentDenseEmbeddingWrite).empty;
        errdefer {
            for (dense_embeddings.items) |*embedding| embedding.deinit(alloc);
            dense_embeddings.deinit(alloc);
        }
        var sparse_embeddings = std.ArrayListUnmanaged(types.EnrichmentSparseEmbeddingWrite).empty;
        errdefer {
            for (sparse_embeddings.items) |*embedding| embedding.deinit(alloc);
            sparse_embeddings.deinit(alloc);
        }
        var graph_writes = std.ArrayListUnmanaged(types.GraphEdgeWrite).empty;
        errdefer {
            for (graph_writes.items) |*write| {
                alloc.free(@constCast(write.index_name));
                alloc.free(@constCast(write.source));
                alloc.free(@constCast(write.target));
                alloc.free(@constCast(write.edge_type));
                if (write.metadata_json.len > 0) alloc.free(@constCast(write.metadata_json));
            }
            graph_writes.deinit(alloc);
        }

        for (writes) |write| {
            var extracted = try mapper.extractWrite(alloc, write.key, write.value);
            try augmentExtractedWriteWithGraphFieldEdges(self, alloc, write.key, write.value, &extracted);
            defer extracted.deinit(alloc);

            if (extracted.cleaned_value) |cleaned| {
                try cleaned_writes.append(alloc, .{
                    .key = try alloc.dupe(u8, write.key),
                    .value = try alloc.dupe(u8, cleaned),
                });
            }
            for (extracted.dense_embeddings) |embedding| {
                const public_artifact = if (embedding.artifact_key) |artifact_key|
                    try artifact_ids.resolvePublicArtifactIdentityAlloc(alloc, artifact_key)
                else
                    null;
                defer if (public_artifact) |identity| {
                    var owned = identity;
                    owned.deinit(alloc);
                };

                try dense_embeddings.append(alloc, .{
                    .index_name = try alloc.dupe(u8, embedding.index_name),
                    .doc_key = try alloc.dupe(u8, embedding.doc_key),
                    .artifact_id = if (public_artifact) |identity| try alloc.dupe(u8, identity.id) else null,
                    .artifact_ref = if (public_artifact) |identity| try identity.artifact_ref.?.clone(alloc) else null,
                    .vector = try alloc.dupe(f32, embedding.vector),
                });
            }
            for (extracted.sparse_embeddings) |embedding| {
                try sparse_embeddings.append(alloc, .{
                    .index_name = try alloc.dupe(u8, embedding.index_name),
                    .doc_key = try alloc.dupe(u8, embedding.doc_key),
                    .indices = try alloc.dupe(u32, embedding.indices),
                    .values = try alloc.dupe(f32, embedding.values),
                });
            }
            for (extracted.graph_writes) |graph_write| {
                try graph_writes.append(alloc, .{
                    .index_name = try alloc.dupe(u8, graph_write.index_name),
                    .source = try alloc.dupe(u8, graph_write.source),
                    .target = try alloc.dupe(u8, graph_write.target),
                    .edge_type = try alloc.dupe(u8, graph_write.edge_type),
                    .weight = graph_write.weight,
                    .created_at = graph_write.created_at,
                    .updated_at = graph_write.updated_at,
                    .metadata_json = if (graph_write.metadata_json.len > 0) try alloc.dupe(u8, graph_write.metadata_json) else "",
                });
            }
        }

        return .{
            .cleaned_writes = try cleaned_writes.toOwnedSlice(alloc),
            .dense_embeddings = try dense_embeddings.toOwnedSlice(alloc),
            .sparse_embeddings = try sparse_embeddings.toOwnedSlice(alloc),
            .graph_writes = try graph_writes.toOwnedSlice(alloc),
        };
    }

    pub fn computeEnrichments(self: *DB, alloc: Allocator, writes: []const types.BatchWrite) !types.ComputeEnrichmentsResult {
        lockApplyShared(self);
        defer self.core.unlockApplyShared();

        var artifact_writes = std.ArrayListUnmanaged(types.BatchWrite).empty;
        errdefer {
            for (artifact_writes.items) |write| {
                alloc.free(@constCast(write.key));
                alloc.free(@constCast(write.value));
            }
            artifact_writes.deinit(alloc);
        }
        var documents = std.ArrayListUnmanaged(types.EnrichmentDocumentWrite).empty;
        errdefer {
            for (documents.items) |*doc| doc.deinit(alloc);
            documents.deinit(alloc);
        }
        var dense_embeddings = std.ArrayListUnmanaged(types.EnrichmentDenseEmbeddingWrite).empty;
        errdefer {
            for (dense_embeddings.items) |*embedding| embedding.deinit(alloc);
            dense_embeddings.deinit(alloc);
        }
        var failed_keys = std.ArrayListUnmanaged([]u8).empty;
        errdefer {
            for (failed_keys.items) |key| alloc.free(key);
            failed_keys.deinit(alloc);
        }

        for (writes) |write| {
            var extracted = try mapper.extractWrite(alloc, write.key, write.value);
            try augmentExtractedWriteWithGraphFieldEdges(self, alloc, write.key, write.value, &extracted);
            defer extracted.deinit(alloc);
            const cleaned = extracted.cleaned_value orelse continue;

            var explicit_dense = std.ArrayListUnmanaged(types.EnrichmentDenseEmbeddingWrite).empty;
            defer {
                for (explicit_dense.items) |*embedding| embedding.deinit(alloc);
                explicit_dense.deinit(alloc);
            }
            for (extracted.dense_embeddings) |embedding| {
                try appendClonedExplicitDenseEmbedding(
                    alloc,
                    &explicit_dense,
                    embedding.index_name,
                    embedding.doc_key,
                    embedding.vector,
                );
            }
            var explicit_sparse = std.ArrayListUnmanaged(types.EnrichmentSparseEmbeddingWrite).empty;
            defer {
                for (explicit_sparse.items) |*embedding| embedding.deinit(alloc);
                explicit_sparse.deinit(alloc);
            }
            for (extracted.sparse_embeddings) |embedding| {
                try appendClonedExplicitSparseEmbedding(
                    alloc,
                    &explicit_sparse,
                    embedding.index_name,
                    embedding.doc_key,
                    embedding.indices,
                    embedding.values,
                );
            }

            const generated = try self.core.planGeneratedEnrichments(
                alloc,
                write.key,
                cleaned,
                explicit_dense.items,
                explicit_sparse.items,
            );
            defer enrichment_types.deinitGeneratedRequests(alloc, generated);

            var chunk_cache = std.ArrayListUnmanaged(ChunkCacheEntry).empty;
            defer {
                for (chunk_cache.items) |entry| {
                    alloc.free(entry.key);
                    chunker_mod.freeChunks(alloc, entry.chunks);
                }
                chunk_cache.deinit(alloc);
            }

            for (generated) |request| {
                switch (request.kind) {
                    .chunk_text => try computeChunkRequest(alloc, self, cleaned, request, &artifact_writes, &documents, &chunk_cache),
                    .dense_embedding => computeDenseRequest(alloc, self, cleaned, request, &artifact_writes, &dense_embeddings, &chunk_cache) catch |err| switch (err) {
                        error.MissingDenseEmbedder => try appendUniqueOwnedKey(alloc, &failed_keys, write.key),
                        else => return err,
                    },
                    else => {},
                }
            }
        }

        const public_artifact_writes = try externalizeArtifactWritesAlloc(alloc, try artifact_writes.toOwnedSlice(alloc));
        return .{
            .artifact_writes = public_artifact_writes,
            .documents = try documents.toOwnedSlice(alloc),
            .dense_embeddings = try dense_embeddings.toOwnedSlice(alloc),
            .failed_keys = try failed_keys.toOwnedSlice(alloc),
        };
    }

    fn deleteIndexWhileEnrichmentQuiesced(self: *DB, name: []const u8) !bool {
        self.executor.removeWorker(name);
        lockApply(self);
        defer self.core.unlockApply();
        const repair_id = try self.prepareIndexRepairForDeletion(self.alloc, name);
        defer if (repair_id != null) self.endIndexRepairLease(name);
        const admission_key = try internal_keys.managedIndexAdmissionKeyAlloc(self.alloc, name);
        defer self.alloc.free(admission_key);
        const removed = try self.core.deleteManagedIndex(name, admission_key);
        if (removed) {
            if (builtin.is_test and test_fail_managed_index_delete_after_catalog_commit)
                return error.TestManagedIndexDeleteCrash;
            self.core.index_manager.clearManagedAdmissionSnapshotForIndex(name);
            if (repair_id) |id| {
                const repair_cleanup = if (builtin.is_test and test_fail_managed_index_repair_cleanup_after_catalog_commit)
                    error.TestPostCommitRepairCleanup
                else
                    self.removeIndexRepairIntentAndPin(self.alloc, id);
                repair_cleanup catch |err| {
                    std.log.warn("index removal committed with stale repair intent name={s} err={s}", .{ name, @errorName(err) });
                };
            }
            self.deleteDenseArtifactCounterMetadata(name) catch |err| {
                std.log.warn("index removal committed with stale dense coverage counters name={s} err={s}", .{ name, @errorName(err) });
            };
        }
        return removed;
    }

    pub fn deleteIndex(self: *DB, name: []const u8) !bool {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        var ha_mutation = self.acquireHAMutationShared();
        defer if (ha_mutation) |*lease| lease.release();
        try self.enforceHAWriteGate();
        var structural_guard = self.beginIndexStructuralMutation("index deletion", name);
        defer structural_guard.deinit();
        const restart_enrichment = self.quiesceEnrichmentForStructuralMutation();
        const removed = self.deleteIndexWhileEnrichmentQuiesced(name) catch |delete_err| {
            if (restart_enrichment) self.restartEnrichmentAfterStructuralMutation("failed index deletion", name) catch |restart_err| {
                std.log.err("failed to restore enrichment runtime after index deletion error index={s} err={s}", .{ name, @errorName(restart_err) });
            };
            return delete_err;
        };
        if (removed) self.scheduleGeneratedArtifactCleanup();
        // Catalog absence is the committed API result. A runtime restart is a
        // supervised availability fault, not a reason to report that the
        // durable deletion failed.
        if (restart_enrichment) self.restartEnrichmentAfterStructuralMutation("index deletion", name) catch |restart_err| {
            std.log.err("failed to restart enrichment runtime after committed index deletion index={s} err={s}", .{ name, @errorName(restart_err) });
        };
        return removed;
    }

    fn refreshManagedIndexWorkersLocked(self: *DB) !void {
        if (!self.start_index_workers) return;

        const managed_indexes = try self.core.managedIndexes(self.alloc);
        defer {
            for (managed_indexes) |index_ref| self.alloc.free(@constCast(index_ref.name));
            self.alloc.free(managed_indexes);
        }

        for (managed_indexes) |index_ref| {
            self.executor.removeWorker(index_ref.name);
        }
        for (managed_indexes) |index_ref| {
            const applied = try self.core.loadAppliedSequence(self.alloc, index_ref.name);
            try self.executor.addWorker(index_ref.name, index_ref, applied);
        }
    }

    fn resetManagedIndexAppliedSequences(self: *DB) !void {
        const managed_indexes = try self.core.managedIndexes(self.alloc);
        defer {
            for (managed_indexes) |index_ref| self.alloc.free(@constCast(index_ref.name));
            self.alloc.free(managed_indexes);
        }

        for (managed_indexes) |index_ref| {
            try self.core.saveAppliedSequence(index_ref.name, 0);
        }
    }

    fn resetManagedIndexAppliedSequencesForRestoreRepair(self: *DB, alloc: Allocator) !void {
        const managed_indexes = try self.core.managedIndexes(alloc);
        defer {
            for (managed_indexes) |index_ref| alloc.free(@constCast(index_ref.name));
            alloc.free(managed_indexes);
        }

        for (managed_indexes) |index_ref| {
            const sequence: u64 = switch (index_ref.kind) {
                .full_text => try self.probeDerivedReplayTargetSequence(
                    alloc,
                    self.core.replaySource(),
                    index_ref,
                    0,
                ),
                else => 0,
            };
            try self.core.saveAppliedSequence(index_ref.name, sequence);
        }
    }

    fn rebaseManagedIndexAppliedSequencesIfNeeded(self: *DB) !void {
        const managed_indexes = try self.core.managedIndexes(self.alloc);
        defer {
            for (managed_indexes) |index_ref| self.alloc.free(@constCast(index_ref.name));
            self.alloc.free(managed_indexes);
        }

        var max_applied: u64 = 0;
        for (managed_indexes) |index_ref| {
            const applied = try self.core.loadAppliedSequence(self.alloc, index_ref.name);
            max_applied = @max(max_applied, applied);
        }
        if (max_applied == 0) return;

        // Applied watermarks are independent of the retained replay log. Once
        // replay entries are truncated, a valid applied watermark can be above
        // the current append floor recovered from replay metadata. Preserve the
        // watermark and advance the floor so future replay sequence allocation
        // cannot reuse already-applied sequence numbers.
        try ensureReplayFloor(self.core.store, max_applied + 1);
    }

    pub fn deleteEnrichment(self: *DB, kind: types.EnrichmentKind, name: []const u8) !bool {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        var ha_mutation = self.acquireHAMutationShared();
        defer if (ha_mutation) |*lease| lease.release();
        try self.enforceHAWriteGate();
        lockApply(self);
        defer self.core.unlockApply();
        return try self.core.deleteEnrichment(kind, name);
    }

    pub fn pendingWorkStats(self: *DB) db_core.PendingWorkStats {
        return .{
            .derived_target_sequence = self.core.nextDerivedSequence(),
            .has_async_indexes = self.executor.hasWorkers(),
            .enrichment = self.enrichmentStatsWithSupervisorState(.{}),
            .resolution = self.resolutionStageStats(),
            .promotion = self.promotionStageStats(),
            .text_merge = if (self.text_merge_runtime) |runtime| runtime.statsAssumeApplyLockHeld() else self.core.index_manager.textMergeStats(),
            .repair_metadata_rebuild_pending = self.artifactRepairMetadataRebuildPending(),
        };
    }

    fn artifactRepairMetadataRebuildPending(self: *DB) bool {
        const summary_ready = self.artifactRepairSummaryReady(self.alloc) catch return true;
        if (!summary_ready) return true;
        const kind_index_ready = self.artifactRepairKindIndexReady(self.alloc) catch return true;
        return !kind_index_ready;
    }

    fn persistedReplayStageStats(self: *DB, scope_name: []const u8, force_enabled: bool) !types.ReplayStageStats {
        const resources = self.core.batchExecutionResources();
        const applied = try enrichment_state.loadAppliedSequence(self.alloc, resources.store, scope_name);
        const target = @max(applied, self.core.nextDerivedSequence());
        return .{
            .enabled = force_enabled or target > 0 or applied < target,
            .target_sequence = target,
            .applied_sequence = applied,
            .catch_up_required = applied < target,
        };
    }

    fn resolutionStageStats(self: *DB) types.ReplayStageStats {
        if (!self.hasConfiguredResolvers()) return .{};
        if (self.resolution_runtime) |runtime| return runtime.stats();
        return self.persistedReplayStageStats(resolution_runtime_mod.scope_name, false) catch .{};
    }

    fn promotionStageStats(self: *DB) types.ReplayStageStats {
        if (!self.hasConfiguredResolvers()) return .{};
        if (self.promotion_runtime) |runtime| return runtime.stats();
        return self.persistedReplayStageStats(promotion_runtime_mod.scope_name, false) catch .{};
    }

    fn resolverReplayDiagnosticsLocked(self: *DB, alloc: Allocator) !types.ResolverReplayDiagnostics {
        const catalog = self.core.index_manager.resolvers.items;
        var resolvers = try alloc.alloc(types.ResolverReplayDiagnostic, catalog.len);
        var initialized: usize = 0;
        errdefer {
            for (resolvers[0..initialized]) |resolver| {
                alloc.free(resolver.name);
                alloc.free(resolver.table);
                alloc.free(resolver.source_artifact);
                alloc.free(resolver.resolution_artifact);
            }
            if (resolvers.len > 0) alloc.free(resolvers);
        }

        for (catalog) |cfg| {
            const name = try alloc.dupe(u8, cfg.name);
            errdefer alloc.free(name);
            const table = try alloc.dupe(u8, cfg.table);
            errdefer alloc.free(table);
            const source_artifact = try alloc.dupe(u8, cfg.source_artifact);
            errdefer alloc.free(source_artifact);
            const resolution_artifact = try alloc.dupe(u8, cfg.resolution_artifact);
            errdefer alloc.free(resolution_artifact);
            resolvers[initialized] = .{
                .name = name,
                .table = table,
                .source_artifact = source_artifact,
                .resolution_artifact = resolution_artifact,
            };
            initialized += 1;
        }

        return .{
            .resolver_count = @intCast(catalog.len),
            .resolution_runtime_present = self.resolution_runtime != null,
            .resolution_worker_started = if (self.resolution_runtime) |runtime| runtime.worker_started.load(.acquire) else false,
            .promotion_runtime_present = self.promotion_runtime != null,
            .promotion_worker_started = if (self.promotion_runtime) |runtime| runtime.worker_started.load(.acquire) else false,
            .resolvers = resolvers[0..initialized],
        };
    }

    fn persistedEnrichmentStats(self: *DB) !types.EnrichmentStats {
        if (!self.core.hasGeneratedEnrichmentTargets()) return .{};
        const resources = self.core.batchExecutionResources();
        const checkpoint = try enrichment_state.loadProjectionCheckpoint(self.alloc, resources.store, enrichment_runtime_mod.scope_name);
        const applied = checkpoint.applied_sequence;
        const status = try enrichment_state.loadRuntimeStatus(self.alloc, resources.store, enrichment_runtime_mod.scope_name);
        const target = @max(applied, status.target_sequence);
        return .{
            .enabled = target > 0 or status.error_count > 0 or status.retrying or status.worker_failed,
            .target_sequence = target,
            .applied_sequence = applied,
            .projection_checkpoint_status = enrichment_state.projectionStatusName(checkpoint.status),
            .projection_checkpoint_applied_sequence = checkpoint.applied_sequence,
            .projection_checkpoint_generation = checkpoint.generation,
            .projection_checkpoint_config_hash = checkpoint.config_hash,
            .checkpoint_replay_tail_sequence_count = target -| checkpoint.applied_sequence,
            .error_count = status.error_count,
            .retryable_error_count = status.retryable_error_count,
            .fatal_error_count = status.fatal_error_count,
            .consecutive_retry_count = status.consecutive_retry_count,
            .next_retry_at_ms = status.next_retry_at_ms,
            .retrying = status.retrying,
            .worker_failed = status.worker_failed,
        };
    }

    const ReplayDrainOptions = struct {
        truncate_replay: bool = true,
        wait_for_enrichment_retries: bool = false,
    };

    fn runDerivedUntilWithOptions(self: *DB, sequence: u64, options: ReplayDrainOptions) !void {
        if (sequence == 0) return;
        if (!self.executor.hasWorkers()) {
            try replayPendingDerivedBatches(self, null, null, options);
            return;
        }
        self.executor.notifySequence(sequence);
        try self.executor.waitForAll(sequence);
    }

    pub fn runDerivedUntil(self: *DB, sequence: u64) !void {
        try self.runDerivedUntilWithOptions(sequence, .{});
    }

    fn runDerivedUntilWithVisibilityWait(self: *DB, sequence: u64, wait: derived_executor_mod.VisibilityWait) !void {
        if (sequence == 0) return;
        if (!self.executor.hasWorkers()) {
            try wait.check();
            try replayPendingDerivedBatches(self, null, null, .{});
            try wait.check();
            return;
        }
        self.executor.notifySequence(sequence);
        try self.executor.waitForAllWithVisibilityWait(sequence, wait);
    }

    pub fn runDerivedUntilTargets(self: *DB, sequence: u64, index_names: []const []const u8) !void {
        if (sequence == 0 or index_names.len == 0) return;
        if (!self.executor.hasWorkers()) return;
        self.executor.notifyIndexes(sequence, index_names);
        try self.executor.waitForIndexes(sequence, index_names);
    }

    fn runDerivedUntilTargetsWithVisibilityWait(
        self: *DB,
        sequence: u64,
        index_names: []const []const u8,
        wait: derived_executor_mod.VisibilityWait,
    ) !void {
        if (sequence == 0 or index_names.len == 0) return;
        try wait.check();
        if (!self.executor.hasWorkers()) return;
        self.executor.notifyIndexes(sequence, index_names);
        try self.executor.waitForIndexesWithVisibilityWait(sequence, index_names, wait);
    }

    pub fn runEnrichmentUntil(self: *DB, sequence: u64) !void {
        try self.runEnrichmentUntilWithCancellation(sequence, .none);
    }

    fn runEnrichmentUntilWithCancellation(self: *DB, sequence: u64, cancellation: types.CancellationToken) !void {
        try self.runEnrichmentUntilWithVisibilityDeadline(sequence, cancellation, null);
    }

    fn runEnrichmentUntilWithVisibilityDeadline(
        self: *DB,
        sequence: u64,
        cancellation: types.CancellationToken,
        deadline_ns: ?u64,
    ) !void {
        if (sequence == 0) return;
        if (self.enrichment_runtime) |runtime| {
            if (!self.optional_runtime_workers_enabled) {
                if (deadline_ns == null and cancellation.ptr == null) {
                    // Explicit maintenance/drain callers historically execute
                    // custom providers inline. They are not request waiters and
                    // retain that source-compatible behavior; API visibility
                    // always supplies the shared finite deadline below.
                    try runtime.catchUpUntil(sequence);
                    return;
                }
                // Foreground ownership is still a post-commit visibility
                // barrier. Honor the borrowed request token and the runtime's
                // hard wait deadline, but never reinterpret cancellation as a
                // rollback of the durable primary mutation.
                try runtime.catchUpUntilWithVisibilityDeadline(sequence, cancellation, deadline_ns);
                return;
            }
            runtime.notifySequence(sequence);
            try runtime.waitForAppliedWithVisibilityDeadline(sequence, cancellation, deadline_ns);
        }
    }

    fn runEnrichmentUntilForDrain(self: *DB, sequence: u64, options: ReplayDrainOptions) !void {
        while (true) {
            self.runEnrichmentUntil(sequence) catch |err| switch (err) {
                error.EnrichmentRetryInProgress => {
                    if (!options.wait_for_enrichment_retries) return err;
                    sleepNs(25 * std.time.ns_per_ms);
                    continue;
                },
                else => return err,
            };
            return;
        }
    }

    fn markPrecomputedEnrichmentAppliedForSync(self: *DB, sync_level: types.SyncLevel, sequence: u64) !void {
        if (sync_level != .enrichments or sequence == 0) return;
        const runtime = self.enrichment_runtime orelse return;
        const runtime_stats = runtime.stats();
        if (runtime_stats.applied_sequence >= sequence -| 1 or
            try self.noPendingEnrichmentReplayThrough(runtime_stats.applied_sequence, sequence))
        {
            try runtime.markAppliedThrough(sequence);
        }
    }

    fn noPendingEnrichmentReplayThrough(self: *DB, applied_sequence: u64, sequence: u64) !bool {
        const pending = try enrichment_worker.collectPendingDocumentGroups(self.alloc, self.core.replaySource(), applied_sequence);
        defer enrichment_worker.freePendingDocumentGroups(self.alloc, pending);
        for (pending) |group| {
            if (group.sequence <= sequence) return false;
        }
        return true;
    }

    fn markEnrichmentAppliedIfNoPendingThrough(self: *DB, sequence: u64) !void {
        if (sequence == 0) return;
        const runtime = self.enrichment_runtime orelse return;
        const runtime_stats = runtime.stats();
        if (runtime_stats.applied_sequence >= sequence) return;
        if (try self.noPendingEnrichmentReplayThrough(runtime_stats.applied_sequence, sequence)) {
            try runtime.markAppliedThrough(sequence);
        }
    }

    fn runMaintenanceUntilWithOptions(self: *DB, sequence: u64, sync_targets: ManagedSyncTargets, options: ReplayDrainOptions) !void {
        var stable_target = sequence;
        while (true) {
            try self.runDerivedUntilWithOptions(stable_target, options);
            try self.runEnrichmentUntilForDrain(stable_target, options);

            const next_target = self.core.nextDerivedSequence();
            if (next_target <= stable_target) {
                try waitForManagedIndexesApplied(self, sequence, sync_targets.all_indexes);
                _ = try self.runArtifactRepairMetadataMaintenancePass();
                return;
            }
            stable_target = next_target;
        }
    }

    pub fn runMaintenanceUntil(self: *DB, sequence: u64, sync_targets: ManagedSyncTargets) !void {
        try self.runMaintenanceUntilWithOptions(sequence, sync_targets, .{});
    }

    fn runMaintenanceUntilWithCancellation(
        self: *DB,
        sequence: u64,
        sync_targets: ManagedSyncTargets,
        cancellation: types.CancellationToken,
        deadline_ns: u64,
    ) !void {
        const wait = derived_executor_mod.VisibilityWait{
            .cancellation = cancellation,
            .deadline_ns = deadline_ns,
        };
        var stable_target = sequence;
        while (true) {
            try self.runDerivedUntilWithVisibilityWait(stable_target, wait);
            try self.runEnrichmentUntilWithVisibilityDeadline(stable_target, cancellation, deadline_ns);

            const next_target = self.core.nextDerivedSequence();
            if (next_target <= stable_target) {
                try waitForManagedIndexesApplied(self, sequence, sync_targets.all_indexes);
                _ = try self.runArtifactRepairMetadataMaintenancePass();
                return;
            }
            stable_target = next_target;
        }
    }

    pub fn runMaintenanceUntilTargets(self: *DB, sequence: u64, index_names: []const []const u8) !void {
        if (index_names.len == 0) return;
        var stable_target = sequence;
        while (true) {
            try self.runDerivedUntilTargets(stable_target, index_names);
            try self.runEnrichmentUntil(stable_target);

            const next_target = self.core.nextDerivedSequence();
            if (next_target <= stable_target) {
                try waitForManagedIndexesApplied(self, sequence, index_names);
                return;
            }
            stable_target = next_target;
        }
    }

    pub fn waitForCurrentSyncLevel(self: *DB, sync_level: types.SyncLevel) !void {
        try self.waitForCurrentSyncLevelWithCancellation(sync_level, .none);
    }

    pub fn waitForCurrentSyncLevelWithCancellation(self: *DB, sync_level: types.SyncLevel, cancellation: types.CancellationToken) !void {
        try self.executor.failIfUnhealthy();
        const sequence = self.core.nextDerivedSequence();
        try self.markPrecomputedEnrichmentAppliedForSync(sync_level, sequence);
        var sync_targets = try self.currentManagedSyncTargets(sync_level);
        defer sync_targets.deinit(self.alloc);
        if (self.executor.hasWorkers()) {
            notifyExecutorForSyncLevelWithDenseBulkDeferral(self.async_context, self.executor, sync_level, sequence, sync_targets);
        }
        try self.waitForSyncLevelWithCancellation(sync_level, sequence, sync_targets, cancellation);
    }

    fn waitForResolvedTransactionSync(self: *DB, sync_level: types.SyncLevel, sequence: u64) !void {
        try self.waitForResolvedTransactionSyncWithCancellation(sync_level, sequence, .none);
    }

    fn waitForResolvedTransactionSyncWithCancellation(self: *DB, sync_level: types.SyncLevel, sequence: u64, cancellation: types.CancellationToken) !void {
        if (sequence == 0 or sync_level == .propose or sync_level == .write) {
            try self.executor.failIfUnhealthy();
            return;
        }
        try self.executor.failIfUnhealthy();
        try self.markPrecomputedEnrichmentAppliedForSync(sync_level, sequence);
        var sync_targets = try self.currentManagedSyncTargets(sync_level);
        defer sync_targets.deinit(self.alloc);
        if (self.executor.hasWorkers()) {
            notifyExecutorForSyncLevelWithDenseBulkDeferral(self.async_context, self.executor, sync_level, sequence, sync_targets);
        }
        if (self.enrichment_runtime) |runtime| runtime.notifySequence(sequence);
        self.notifyResolverReplayRuntimes(sequence);
        try self.waitForSyncLevelWithCancellation(sync_level, sequence, sync_targets, cancellation);
        if (sync_level == .full_index and self.text_merge_runtime == null) {
            try self.drainScheduledTextMerges();
        }
    }

    fn currentManagedSyncTargets(self: *DB, sync_level: types.SyncLevel) !ManagedSyncTargets {
        const managed_indexes = try self.core.managedIndexes(self.alloc);
        defer {
            for (managed_indexes) |index_ref| self.alloc.free(@constCast(index_ref.name));
            self.alloc.free(managed_indexes);
        }

        var full_text_indexes = std.ArrayListUnmanaged([]const u8).empty;
        errdefer {
            for (full_text_indexes.items) |name| self.alloc.free(@constCast(name));
            full_text_indexes.deinit(self.alloc);
        }
        var all_indexes = std.ArrayListUnmanaged([]const u8).empty;
        errdefer {
            for (all_indexes.items) |name| self.alloc.free(@constCast(name));
            all_indexes.deinit(self.alloc);
        }

        for (managed_indexes) |index_ref| {
            switch (sync_level) {
                .propose, .write => {},
                .enrichments => {},
                .full_text => {
                    if (index_ref.kind == .full_text) {
                        try appendUniqueOwnedName(self.alloc, &full_text_indexes, index_ref.name);
                        try appendUniqueOwnedName(self.alloc, &all_indexes, index_ref.name);
                    }
                },
                .full_index => {
                    try appendUniqueOwnedName(self.alloc, &all_indexes, index_ref.name);
                    if (index_ref.kind == .full_text) {
                        try appendUniqueOwnedName(self.alloc, &full_text_indexes, index_ref.name);
                    }
                },
            }
        }

        return .{
            .full_text_indexes = try full_text_indexes.toOwnedSlice(self.alloc),
            .all_indexes = try all_indexes.toOwnedSlice(self.alloc),
        };
    }

    pub fn catchUpPendingDerivedReplay(self: *DB) !void {
        try replayPendingDerivedBatches(self, null, null, .{});
    }

    pub fn catchUpPendingDerivedReplayWithProgress(
        self: *DB,
        progress_ctx: *anyopaque,
        progress_hook: ReplayProgressHook,
    ) !void {
        try replayPendingDerivedBatches(self, progress_ctx, progress_hook, .{});
    }

    const run_until_idle_max_replay_rounds: usize = 16;

    fn currentMaintenanceTargetSequence(self: *DB) u64 {
        var target_sequence = self.core.nextDerivedSequence();
        if (self.enrichment_runtime) |runtime| {
            target_sequence = @max(target_sequence, runtime.stats().target_sequence);
        }
        return target_sequence;
    }

    fn resolverReplayBlockedAfterRunnableDrain(self: *DB) bool {
        const resolution_stats = self.resolutionStageStats();
        if (resolution_stats.catch_up_required and !resolution_stats.blocked) return false;
        const promotion_stats = self.promotionStageStats();
        return promotion_stats.blocked;
    }

    fn drainReplayStagesUntilStableWithOptions(self: *DB, options: ReplayDrainOptions) !void {
        var rounds: usize = 0;
        while (rounds < run_until_idle_max_replay_rounds) : (rounds += 1) {
            const starting_sequence = self.core.nextDerivedSequence();
            const starting_resolution_applied = if (self.resolution_runtime) |runtime| runtime.stats().applied_sequence else 0;
            const starting_promotion_applied = if (self.promotion_runtime) |runtime| runtime.stats().applied_sequence else 0;
            try self.runMaintenanceUntilWithOptions(self.currentMaintenanceTargetSequence(), .{}, options);
            const drained_sequence = self.core.nextDerivedSequence();

            const drain_resolver_replay = self.resolverReplayNeedsDrain();
            if (drain_resolver_replay) {
                if (self.resolution_runtime) |runtime| {
                    // nextDerivedSequence() is the highest committed sequence,
                    // not the next append sequence. Include that record when
                    // recovering a missed runtime notification.
                    if (drained_sequence > 0) runtime.notifySequence(drained_sequence);
                    try runtime.catchUp();
                }

                if (self.promotion_runtime) |runtime| {
                    const latest = self.core.nextDerivedSequence();
                    if (latest > 0) runtime.notifySequence(latest);
                    try runtime.catchUp();
                }

                // Resolution can append graph/promotion replay before
                // promotion discovers that its external sink is unavailable.
                // Drain those independent derived consumers before reporting
                // the blocked stage; otherwise runUntilIdle can return with a
                // durable resolution artifact that is absent from the graph.
                if (self.core.nextDerivedSequence() > drained_sequence) {
                    try self.runMaintenanceUntilWithOptions(self.currentMaintenanceTargetSequence(), .{}, options);
                }
                if (self.resolverReplayBlockedAfterRunnableDrain()) return;
            }

            const resolution_advanced = if (self.resolution_runtime) |runtime|
                runtime.stats().applied_sequence > starting_resolution_applied
            else
                false;
            const promotion_advanced = if (self.promotion_runtime) |runtime|
                runtime.stats().applied_sequence > starting_promotion_applied
            else
                false;
            if (self.core.nextDerivedSequence() <= starting_sequence and !resolution_advanced and !promotion_advanced) return;
        }
        return error.RunUntilIdleDidNotConverge;
    }

    /// Re-attempts opening quarantined indexes (artifacts that failed to
    /// load at open time). `force` ignores per-index backoff — used by tests
    /// and operator-triggered recovery. Runs the same detached-open path as
    /// the initial load, so a recovered full-text/sparse/graph index resumes
    /// its persisted rebuild state and catches up before registering.
    pub fn retryQuarantinedIndexLoads(self: *DB, force: bool) !index_manager_mod.IndexManager.QuarantineRetryResult {
        var publication_fence = QuarantineIndexPublicationFence{ .db = self };
        return try self.core.index_manager.retryFailedIndexLoads(
            self.core.store,
            monotonicTimeNs(),
            force,
            publication_fence.iface(),
        );
    }

    fn runArtifactRepairMetadataMaintenancePass(self: *DB) !bool {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return false;
        lockApply(self);
        defer self.core.unlockApply();

        var more = false;
        more = (try self.rebuildArtifactRepairSummaryIfMissing(self.alloc)) or more;
        more = (try self.rebuildArtifactRepairKindIndexIfMissing(self.alloc)) or more;
        return more;
    }

    pub fn runArtifactRepairMetadataMaintenanceUntilIdle(self: *DB) !void {
        while (try self.runArtifactRepairMetadataMaintenancePass()) {}
    }

    const quarantine_retry_poll_ns: u64 = 10 * std.time.ns_per_s;
    const quarantine_retry_sleep_slice_ns: u64 = 25 * std.time.ns_per_ms;
    const artifact_repair_metadata_poll_ns: u64 = 5 * std.time.ns_per_s;
    const artifact_repair_metadata_active_poll_ns: u64 = 100 * std.time.ns_per_ms;
    const artifact_repair_metadata_sleep_slice_ns: u64 = 25 * std.time.ns_per_ms;

    /// Start only after the DB has reached its final address. DB.open returns
    /// by value, so cache owners invoke this after installing that value in a
    /// stable heap entry rather than letting an async task capture the open
    /// function's temporary stack address.
    pub fn startArtifactRepairMetadataWorkerIfNeeded(self: *DB) void {
        if (comptime builtin.single_threaded or builtin.os.tag == .freestanding) return;
        if (comptime builtin.is_test) return;
        if (!self.start_index_workers) return;
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return;
        if (self.artifact_repair_metadata_future != null) return;
        const io_impl = self.backend_runtime.io_impl orelse return;
        self.artifact_repair_metadata_stop.store(false, .release);
        self.artifact_repair_metadata_future = io_impl.io().concurrent(artifactRepairMetadataWorkerMain, .{self}) catch |err| {
            std.log.warn("artifact repair metadata worker spawn failed: {}", .{err});
            return;
        };
    }

    fn stopArtifactRepairMetadataWorker(self: *DB) void {
        self.artifact_repair_metadata_stop.store(true, .release);
        if (self.artifact_repair_metadata_future) |*future| {
            if (self.backend_runtime.io_impl) |io_impl| {
                _ = future.await(io_impl.io());
            }
            self.artifact_repair_metadata_future = null;
        }
    }

    fn drainReplayStagesUntilStable(self: *DB) !void {
        try self.drainReplayStagesUntilStableWithOptions(.{ .wait_for_enrichment_retries = true });
    }

    fn sleepArtifactRepairMetadataWorker(self: *DB, target_ns: u64) bool {
        var slept: u64 = 0;
        while (slept < target_ns) : (slept += artifact_repair_metadata_sleep_slice_ns) {
            if (self.artifact_repair_metadata_stop.load(.acquire)) return false;
            sleepNs(artifact_repair_metadata_sleep_slice_ns);
        }
        return !self.artifact_repair_metadata_stop.load(.acquire);
    }

    fn artifactRepairMetadataWorkerMain(self: *DB) void {
        while (true) {
            const active = self.artifactRepairMetadataRebuildPending();
            if (!self.sleepArtifactRepairMetadataWorker(if (active) artifact_repair_metadata_active_poll_ns else artifact_repair_metadata_poll_ns)) return;
            if (self.artifact_repair_metadata_stop.load(.acquire)) return;
            _ = self.runArtifactRepairMetadataMaintenancePass() catch |err| {
                std.log.warn("artifact repair metadata maintenance pass failed: {}", .{err});
                continue;
            };
        }
    }

    fn startQuarantineRetryWorkerIfNeeded(self: *DB) void {
        if (comptime builtin.single_threaded or builtin.os.tag == .freestanding) return;
        // Tests drive retries deterministically via retryQuarantinedIndexLoads;
        // a background worker racing them turns every quarantine-shaped test
        // into a timing assumption.
        if (comptime builtin.is_test) return;
        if (!self.core.index_manager.hasLoadFailures()) return;
        self.quarantine_retry_thread = std.Thread.spawn(.{}, quarantineRetryWorkerMain, .{self}) catch |err| {
            // Self-healing is best-effort: the quarantine still recovers on
            // the next open or via drop+recreate.
            std.log.warn("quarantine retry worker spawn failed: {}", .{err});
            return;
        };
    }

    fn stopQuarantineRetryWorker(self: *DB) void {
        self.quarantine_retry_stop.store(true, .release);
        if (self.quarantine_retry_thread) |thread| {
            thread.join();
            self.quarantine_retry_thread = null;
        }
    }

    fn quarantineRetryWorkerMain(self: *DB) void {
        while (true) {
            var slept: u64 = 0;
            while (slept < quarantine_retry_poll_ns) : (slept += quarantine_retry_sleep_slice_ns) {
                if (self.quarantine_retry_stop.load(.acquire)) return;
                sleepNs(quarantine_retry_sleep_slice_ns);
            }
            if (self.quarantine_retry_stop.load(.acquire)) return;
            const result = self.retryQuarantinedIndexLoads(false) catch |err| {
                std.log.warn("quarantine retry pass failed: {}", .{err});
                continue;
            };
            if (result.remaining == 0) return;
        }
    }

    fn runRestoreRepairDrainAsync(self: *DB) !void {
        // Generated enrichment replay is asynchronous with respect to the
        // replay append performed by the preceding repair phase. The restore
        // completion marker is also the query-readiness barrier, so drain all
        // replay stages to a stable sequence before publishing it. Keep
        // posting, text-merge, artifact-metadata, and LSM maintenance outside
        // this barrier; those can continue in the background without hiding
        // logically restored query results.
        if (self.enrichment_runtime) |runtime| {
            const before = runtime.stats();
            std.log.info("restore runtime repair enrichment drain begin path={s} applied={d} target={d} processed={d} skipped={d}", .{
                self.core.path,
                before.applied_sequence,
                before.target_sequence,
                before.processed_requests,
                before.skip_by_hash_count,
            });
        }
        // Do not truncate the replay journal here: subsequent restore repair
        // phases still use its durable target to prove derived-state coverage.
        try self.drainReplayStagesUntilStableWithOptions(.{
            .truncate_replay = false,
            .wait_for_enrichment_retries = true,
        });
        if (self.enrichment_runtime) |runtime| {
            const after = runtime.stats();
            std.log.info("restore runtime repair enrichment drain complete path={s} applied={d} target={d} processed={d} skipped={d} errors={d}", .{
                self.core.path,
                after.applied_sequence,
                after.target_sequence,
                after.processed_requests,
                after.skip_by_hash_count,
                after.error_count,
            });
        }
        try self.flushAppliedSequencesForIdle();
    }

    pub fn runUntilIdle(self: *DB) !void {
        try self.drainReplayStagesUntilStable();
        _ = try self.evaluateAlgebraicAdaptiveCandidates();
        while (try self.runAlgebraicAdaptiveWork() != 0) {}
        try self.flushAppliedSequencesForIdle();
        try self.drainScheduledTextMerges();
        try self.runArtifactRepairMetadataMaintenanceUntilIdle();
        _ = try self.runDensePostingMaintenanceForIdle();
        _ = try self.runLsmMaintenanceUntilIdle();
    }

    pub fn rebuildDenseIndexesForTargetCoverage(self: *DB, alloc: Allocator) !usize {
        var names = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (names.items) |name| alloc.free(name);
            names.deinit(alloc);
        }

        for (self.core.index_manager.dense_indexes.items) |*entry| {
            try names.append(alloc, try alloc.dupe(u8, entry.config.name));
        }

        var rebuilt: usize = 0;
        for (names.items) |name| {
            rebuilt += try rebuildDenseIndexForTargetCoverageContext(self.async_context, name, 2048);
        }
        return rebuilt;
    }

    pub fn rebuildSparseIndexesForTargetCoverage(self: *DB, alloc: Allocator) !usize {
        var names = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (names.items) |name| alloc.free(name);
            names.deinit(alloc);
        }

        for (self.core.index_manager.sparse_indexes.items) |*entry| {
            try names.append(alloc, try alloc.dupe(u8, entry.config.name));
        }

        var rebuilt: usize = 0;
        for (names.items) |name| {
            rebuilt += try rebuildSparseIndexFromStoredEmbeddingArtifactsContext(self.async_context, name, 2048);
        }
        return rebuilt;
    }

    pub fn rebuildGraphIndexesForTargetCoverage(self: *DB, alloc: Allocator) !void {
        try applySplitGraphArtifactsInRange(
            alloc,
            "",
            "",
            self.core.store,
            self.core.index_manager,
        );
    }

    pub fn runDensePostingMaintenanceForIdle(self: *DB) !usize {
        lockApply(self);
        defer self.core.unlockApply();
        return try self.core.index_manager.runDensePostingMaintenance(.{
            .max_postings_per_index = densePostingIdleMaxPostingsPerIndex(),
            .max_layout_changes_per_index = densePostingIdleMaxLayoutChangesPerIndex(),
            .max_boundary_reassignments_per_index = densePostingIdleMaxBoundaryReassignmentsPerIndex(),
        });
    }

    fn flushAppliedSequencesForIdle(self: *DB) !void {
        var lifecycle_completed = false;
        const published = blk: {
            var seq_lock = lockAtomicWithBackoffProfiled(
                &self.async_context.applied_sequence_mutex,
                &self.async_context.stats.applied_sequence_mutex,
            );
            defer seq_lock.unlock();
            break :blk try flushPendingAppliedSequencesLocked(self.async_context, true, &lifecycle_completed);
        };
        if (lifecycle_completed) {
            notifyQueryVisibilityHook(self.async_context, .publish_blocking);
        } else if (published) {
            notifyQueryVisibilityHook(self.async_context, .publish_consistent);
        }
    }

    fn isRecoverableEmbeddingArtifactError(err: anyerror) bool {
        return switch (err) {
            error.InvalidArtifactHeader,
            error.InvalidArtifactMagic,
            error.UnsupportedArtifactCodecVersion,
            error.InvalidArtifactKind,
            error.InvalidArtifactPayload,
            error.InvalidVectorDimensions,
            error.InvalidSparseEmbedding,
            => true,
            else => false,
        };
    }

    fn freeDenseArtifactRebuildWrites(alloc: Allocator, writes: *std.ArrayListUnmanaged(mapper.DenseEmbeddingWrite)) void {
        for (writes.items) |write| {
            alloc.free(write.index_name);
            alloc.free(write.doc_key);
            if (write.parent_doc_key) |parent_doc_key| alloc.free(@constCast(parent_doc_key));
            if (write.artifact_key) |artifact_key| alloc.free(artifact_key);
            if (write.vector.len > 0) alloc.free(write.vector);
        }
        writes.clearRetainingCapacity();
    }

    fn freeSparseArtifactRebuildWrites(alloc: Allocator, writes: *std.ArrayListUnmanaged(mapper.SparseEmbeddingWrite)) void {
        for (writes.items) |write| {
            alloc.free(write.doc_key);
            if (write.artifact_key) |artifact_key| alloc.free(artifact_key);
            if (write.indices.len > 0) alloc.free(write.indices);
            if (write.values.len > 0) alloc.free(write.values);
        }
        writes.clearRetainingCapacity();
    }

    fn flushDenseArtifactRebuildChunk(
        self: *DB,
        alloc: Allocator,
        writes: *std.ArrayListUnmanaged(mapper.DenseEmbeddingWrite),
    ) !void {
        defer freeDenseArtifactRebuildWrites(alloc, writes);
        if (writes.items.len == 0) return;

        for (self.core.index_manager.dense_indexes.items) |entry| {
            try self.core.index_manager.applyDenseEmbeddingWritesByNameWithOptions(
                self.core.store,
                entry.config.name,
                writes.items,
                .{ .mode = .bulk_ingest },
            );
        }
    }

    const DenseArtifactRebuildResumeHook = *const fn (ctx: *anyopaque, last_key: []const u8) anyerror!void;

    const DenseArtifactRebuildTarget = struct {
        dense_index_idx: usize,
        resume_from: ?[]u8 = null,
        /// True only when resume_from came from a cursor owned by the current
        /// catalog generation. Fresh and stale-generation targets must publish
        /// a generation-owned restart cursor during execution, never probing.
        resume_state_current: bool = false,
        artifact_target_count: u64 = 0,

        fn deinit(self: *@This(), alloc: Allocator) void {
            if (self.resume_from) |buf| alloc.free(buf);
            self.* = .{
                .dense_index_idx = 0,
            };
        }
    };

    const DenseGenerationRepairTarget = struct {
        dense_index_idx: usize,
        trigger: index_repair_state.Trigger,
        last_error: []const u8,
    };

    const DenseArtifactRebuildPlan = struct {
        targets: []DenseArtifactRebuildTarget = &.{},
        generation_repairs: []DenseGenerationRepairTarget = &.{},
        rebuild_state_cleanups: []usize = &.{},
        target_sequence: u64 = 0,

        fn deinit(self: *@This(), alloc: Allocator) void {
            for (self.targets) |*target| target.deinit(alloc);
            if (self.targets.len > 0) alloc.free(self.targets);
            if (self.generation_repairs.len > 0) alloc.free(self.generation_repairs);
            if (self.rebuild_state_cleanups.len > 0) alloc.free(self.rebuild_state_cleanups);
            self.* = .{};
        }
    };

    const DenseArtifactRebuildOutcome = struct {
        /// Preserves the public helper's historical count: rebuilt artifact
        /// records, or discovered generation-repair targets when no in-place
        /// target exists.
        reported_work: usize = 0,
        /// True only when this invocation changed durable/in-memory repair
        /// state. Existing debt rediscovered by a probe is not progress.
        made_progress: bool = false,
        /// Dense vectors changed, so HBC query caches must be retired.
        dense_visibility_changed: bool = false,
    };

    const DenseArtifactRebuildPreparation = struct {
        made_progress: bool = false,
        dense_visibility_changed: bool = false,
    };

    const DenseArtifactTargetCounts = struct {
        per_target_index: std.AutoHashMapUnmanaged(usize, u64) = .empty,
        authoritative_targets: std.AutoHashMapUnmanaged(usize, void) = .empty,
        total_target_artifacts: u64 = 0,

        fn deinit(self: *@This(), alloc: Allocator) void {
            self.per_target_index.deinit(alloc);
            self.authoritative_targets.deinit(alloc);
            self.* = .{};
        }
    };

    const dense_artifact_target_counter_prefix = "\x00\x00__metadata__:dense_artifact_target_count:";
    const dense_artifact_counter_bootstrap_prefix = "\x00\x00__metadata__:dense_artifact_counter_bootstrap:";
    const dense_artifact_counter_bootstrap_magic = "AFDCB001";
    const dense_artifact_counter_bootstrap_encoded_len = dense_artifact_counter_bootstrap_magic.len + 2 * @sizeOf(u128) + @sizeOf(i64);

    const DenseArtifactCounterBootstrap = struct {
        repair_id: u128,
        attempt_id: u128,
        delta: i64 = 0,
    };

    fn denseIndexRebuildStatePathAlloc(self: *DB, alloc: Allocator, index_name: []const u8) ![]u8 {
        return try std.fmt.allocPrint(
            alloc,
            "{s}/indexes/{s}",
            .{ self.core.index_manager.base_path, index_name },
        );
    }

    fn denseArtifactNameForEntry(entry: anytype) []const u8 {
        return entry.embedding_name orelse entry.config.name;
    }

    const DenseArtifactTargetKey = struct {
        artifact_name: []const u8,
        dims: u32,
    };

    const DenseArtifactTargetKeyContext = struct {
        pub fn hash(_: @This(), key: DenseArtifactTargetKey) u64 {
            var hasher = std.hash.Wyhash.init(0);
            const artifact_name_len: u64 = @intCast(key.artifact_name.len);
            hasher.update(std.mem.asBytes(&artifact_name_len));
            hasher.update(key.artifact_name);
            hasher.update(std.mem.asBytes(&key.dims));
            return hasher.final();
        }

        pub fn eql(_: @This(), lhs: DenseArtifactTargetKey, rhs: DenseArtifactTargetKey) bool {
            return lhs.dims == rhs.dims and std.mem.eql(u8, lhs.artifact_name, rhs.artifact_name);
        }
    };

    const DenseArtifactTargetLookup = struct {
        by_artifact: std.HashMapUnmanaged(DenseArtifactTargetKey, std.ArrayListUnmanaged(usize), DenseArtifactTargetKeyContext, 80) = .empty,

        fn deinit(self: *@This(), alloc: Allocator) void {
            var values = self.by_artifact.valueIterator();
            while (values.next()) |indices| indices.deinit(alloc);
            self.by_artifact.deinit(alloc);
            self.* = .{};
        }

        fn add(self: *@This(), alloc: Allocator, artifact_name: []const u8, dims: u32, dense_index_idx: usize) !void {
            const key: DenseArtifactTargetKey = .{
                .artifact_name = artifact_name,
                .dims = dims,
            };
            var entry = try self.by_artifact.getOrPut(alloc, key);
            if (!entry.found_existing) entry.value_ptr.* = .empty;
            try entry.value_ptr.append(alloc, dense_index_idx);
        }
    };

    const DenseArtifactCounterTarget = struct {
        index_name: []u8,
        artifact_names: std.ArrayListUnmanaged([]u8) = .empty,
        dims: u32,

        fn deinit(self: *@This(), alloc: Allocator) void {
            alloc.free(self.index_name);
            for (self.artifact_names.items) |name| alloc.free(name);
            self.artifact_names.deinit(alloc);
            self.* = undefined;
        }
    };

    /// Per-commit routing table for authoritative dense-artifact counters.
    /// Unlike the runtime dense-index list, this includes status-only configs:
    /// a quarantined index is exactly the index whose bootstrap marker must
    /// continue observing concurrent artifact mutations.
    const DenseArtifactCounterCatalog = struct {
        targets: std.ArrayListUnmanaged(DenseArtifactCounterTarget) = .empty,
        by_artifact: std.HashMapUnmanaged(DenseArtifactTargetKey, std.ArrayListUnmanaged(usize), DenseArtifactTargetKeyContext, 80) = .empty,

        fn deinit(self: *@This(), alloc: Allocator) void {
            var values = self.by_artifact.valueIterator();
            while (values.next()) |indices| indices.deinit(alloc);
            self.by_artifact.deinit(alloc);
            for (self.targets.items) |*target| target.deinit(alloc);
            self.targets.deinit(alloc);
            self.* = .{};
        }

        fn indexTarget(self: *const @This(), index_name: []const u8) ?usize {
            for (self.targets.items, 0..) |target, i| {
                if (std.mem.eql(u8, target.index_name, index_name)) return i;
            }
            return null;
        }

        fn add(
            self: *@This(),
            alloc: Allocator,
            index_name: []const u8,
            artifact_name: []const u8,
            dims: u32,
        ) !void {
            if (self.indexTarget(index_name)) |target_idx| {
                const target = &self.targets.items[target_idx];
                for (target.artifact_names.items) |configured| {
                    if (std.mem.eql(u8, configured, artifact_name)) return;
                }
                const owned_name = try alloc.dupe(u8, artifact_name);
                errdefer alloc.free(owned_name);
                try target.artifact_names.append(alloc, owned_name);
                const key: DenseArtifactTargetKey = .{ .artifact_name = owned_name, .dims = dims };
                var entry = try self.by_artifact.getOrPut(alloc, key);
                if (!entry.found_existing) entry.value_ptr.* = .empty;
                try entry.value_ptr.append(alloc, target_idx);
                return;
            }
            var owned_index_name: ?[]u8 = try alloc.dupe(u8, index_name);
            errdefer if (owned_index_name) |value| alloc.free(value);
            var owned_artifact_name: ?[]u8 = try alloc.dupe(u8, artifact_name);
            errdefer if (owned_artifact_name) |value| alloc.free(value);
            var artifact_names = std.ArrayListUnmanaged([]u8).empty;
            errdefer artifact_names.deinit(alloc);
            try artifact_names.append(alloc, owned_artifact_name.?);
            try self.targets.append(alloc, .{
                .index_name = owned_index_name.?,
                .artifact_names = artifact_names,
                .dims = dims,
            });
            artifact_names = .empty;
            owned_index_name = null;
            owned_artifact_name = null;
            var keep_target = false;
            errdefer if (!keep_target) {
                var removed = self.targets.pop().?;
                removed.deinit(alloc);
            };

            const target_idx = self.targets.items.len - 1;
            const target = &self.targets.items[target_idx];
            const key: DenseArtifactTargetKey = .{
                .artifact_name = target.artifact_names.items[0],
                .dims = target.dims,
            };
            var entry = try self.by_artifact.getOrPut(alloc, key);
            if (!entry.found_existing) entry.value_ptr.* = .empty;
            errdefer if (!entry.found_existing) {
                entry.value_ptr.deinit(alloc);
                _ = self.by_artifact.remove(key);
            };
            try entry.value_ptr.append(alloc, target_idx);
            keep_target = true;
        }

        fn init(
            alloc: Allocator,
            index_manager: *const index_manager_mod.IndexManager,
        ) !DenseArtifactCounterCatalog {
            var catalog: DenseArtifactCounterCatalog = .{};
            errdefer catalog.deinit(alloc);

            for (index_manager.dense_indexes.items) |*entry| {
                const artifact_backed = entry.external or entry.chunk_name != null or entry.embedding_name != null or entry.embedding_names.len > 0;
                if (!artifact_backed) continue;
                if (entry.embedding_names.len > 0) {
                    for (entry.embedding_names) |artifact_name| try catalog.add(alloc, entry.config.name, artifact_name, entry.dims);
                } else {
                    try catalog.add(alloc, entry.config.name, denseArtifactNameForEntry(entry), entry.dims);
                }
            }
            for (index_manager.status_only_index_configs) |cfg| {
                if (cfg.kind != .dense_vector or catalog.indexTarget(cfg.name) != null) continue;
                const requires_coverage = index_manager_mod.denseConfigRequiresArtifactCoverage(alloc, cfg) catch |err| switch (err) {
                    error.OutOfMemory => return err,
                    // Invalid/unsupported quarantined configs are deliberately
                    // isolated from healthy indexes. They cannot have a valid
                    // counter target and must not make unrelated writes fail.
                    else => continue,
                };
                if (!requires_coverage) continue;
                const artifact_names = index_manager_mod.denseConfigArtifactNamesAlloc(alloc, cfg) catch |err| switch (err) {
                    error.OutOfMemory => return err,
                    else => continue,
                };
                defer {
                    for (artifact_names) |name| alloc.free(name);
                    alloc.free(artifact_names);
                }
                const dims = index_manager_mod.denseConfigDimensions(alloc, cfg) catch |err| switch (err) {
                    error.OutOfMemory => return err,
                    else => continue,
                };
                for (artifact_names) |artifact_name| try catalog.add(alloc, cfg.name, artifact_name, dims);
            }
            return catalog;
        }

        fn targetsFor(
            self: *const @This(),
            artifact_name: []const u8,
            dims: u32,
        ) []const usize {
            const indices = self.by_artifact.get(.{
                .artifact_name = artifact_name,
                .dims = dims,
            }) orelse return &.{};
            return indices.items;
        }
    };

    fn denseArtifactTargetCounterKeyAlloc(alloc: Allocator, index_name: []const u8) ![]u8 {
        return try std.fmt.allocPrint(alloc, "{s}{s}", .{ dense_artifact_target_counter_prefix, index_name });
    }

    fn denseArtifactCounterBootstrapKeyAlloc(alloc: Allocator, index_name: []const u8) ![]u8 {
        return try std.fmt.allocPrint(alloc, "{s}{s}", .{ dense_artifact_counter_bootstrap_prefix, index_name });
    }

    fn encodeDenseArtifactCounterBootstrap(value: DenseArtifactCounterBootstrap, out: *[dense_artifact_counter_bootstrap_encoded_len]u8) void {
        @memcpy(out[0..dense_artifact_counter_bootstrap_magic.len], dense_artifact_counter_bootstrap_magic);
        var offset = dense_artifact_counter_bootstrap_magic.len;
        std.mem.writeInt(u128, out[offset..][0..@sizeOf(u128)], value.repair_id, .little);
        offset += @sizeOf(u128);
        std.mem.writeInt(u128, out[offset..][0..@sizeOf(u128)], value.attempt_id, .little);
        offset += @sizeOf(u128);
        std.mem.writeInt(i64, out[offset..][0..@sizeOf(i64)], value.delta, .little);
    }

    fn decodeDenseArtifactCounterBootstrap(raw: []const u8) !DenseArtifactCounterBootstrap {
        if (raw.len != dense_artifact_counter_bootstrap_encoded_len or
            !std.mem.eql(u8, raw[0..dense_artifact_counter_bootstrap_magic.len], dense_artifact_counter_bootstrap_magic))
        {
            return error.InvalidDenseArtifactCounterBootstrap;
        }
        var offset = dense_artifact_counter_bootstrap_magic.len;
        const repair_id = std.mem.readInt(u128, raw[offset..][0..@sizeOf(u128)], .little);
        offset += @sizeOf(u128);
        const attempt_id = std.mem.readInt(u128, raw[offset..][0..@sizeOf(u128)], .little);
        offset += @sizeOf(u128);
        return .{
            .repair_id = repair_id,
            .attempt_id = attempt_id,
            .delta = std.mem.readInt(i64, raw[offset..][0..@sizeOf(i64)], .little),
        };
    }

    fn loadDenseArtifactCounterBootstrap(
        alloc: Allocator,
        store: *docstore_mod.DocStore,
        index_name: []const u8,
    ) !?DenseArtifactCounterBootstrap {
        const key = try denseArtifactCounterBootstrapKeyAlloc(alloc, index_name);
        defer alloc.free(key);
        const raw = store.get(alloc, key) catch |err| switch (err) {
            error.NotFound => return null,
            else => return err,
        };
        defer alloc.free(raw);
        return try decodeDenseArtifactCounterBootstrap(raw);
    }

    fn loadDenseArtifactTargetCounter(alloc: Allocator, store: *docstore_mod.DocStore, index_name: []const u8) !?u64 {
        const key = try denseArtifactTargetCounterKeyAlloc(alloc, index_name);
        defer alloc.free(key);
        const raw = store.get(alloc, key) catch |err| switch (err) {
            error.NotFound => return null,
            else => return err,
        };
        defer alloc.free(raw);
        if (raw.len != 8) return error.InvalidDenseArtifactTargetCounter;
        return std.mem.readInt(u64, raw[0..8], .little);
    }

    fn initializeDenseArtifactTargetCounterIfNeeded(self: *DB, cfg: types.IndexConfig) !void {
        if (!try index_manager_mod.denseConfigRequiresArtifactCoverage(self.alloc, cfg)) return;

        // Every catalog add owns a fresh coverage generation. Reset this
        // name-scoped counter so debris from an interrupted deletion cannot
        // become coverage evidence for a recreated generation.
        const key = try denseArtifactTargetCounterKeyAlloc(self.alloc, cfg.name);
        defer self.alloc.free(key);
        var value: [8]u8 = undefined;
        std.mem.writeInt(u64, &value, 0, .little);
        try self.core.store.putBatch(&.{.{ .key = key, .value = &value }}, &.{});
    }

    fn deleteDenseArtifactCounterMetadata(self: *DB, index_name: []const u8) !void {
        return try deleteDenseArtifactCounterMetadataContext(self.alloc, self.core.store, index_name);
    }

    fn deleteDenseArtifactCounterMetadataContext(alloc: Allocator, store: *docstore_mod.DocStore, index_name: []const u8) !void {
        const counter_key = try denseArtifactTargetCounterKeyAlloc(alloc, index_name);
        defer alloc.free(counter_key);
        const bootstrap_key = try denseArtifactCounterBootstrapKeyAlloc(alloc, index_name);
        defer alloc.free(bootstrap_key);
        try store.putBatch(&.{}, &.{ counter_key, bootstrap_key });
    }

    fn appendDenseArtifactTargetCounterWrite(
        alloc: Allocator,
        store_writes: *std.ArrayListUnmanaged(docstore_mod.KVPair),
        owned_keys: *std.ArrayListUnmanaged([]u8),
        owned_values: *std.ArrayListUnmanaged([]u8),
        index_name: []const u8,
        count: u64,
    ) !void {
        const key = try denseArtifactTargetCounterKeyAlloc(alloc, index_name);
        errdefer alloc.free(key);
        const value = try alloc.alloc(u8, 8);
        errdefer alloc.free(value);
        std.mem.writeInt(u64, value[0..8], count, .little);
        try owned_keys.append(alloc, key);
        try owned_values.append(alloc, value);
        try store_writes.append(alloc, .{
            .key = key,
            .value = value,
        });
    }

    fn appendDenseArtifactCounterBootstrapWrite(
        alloc: Allocator,
        store_writes: *std.ArrayListUnmanaged(docstore_mod.KVPair),
        owned_keys: *std.ArrayListUnmanaged([]u8),
        owned_values: *std.ArrayListUnmanaged([]u8),
        index_name: []const u8,
        bootstrap: DenseArtifactCounterBootstrap,
    ) !void {
        const key = try denseArtifactCounterBootstrapKeyAlloc(alloc, index_name);
        errdefer alloc.free(key);
        const value = try alloc.alloc(u8, dense_artifact_counter_bootstrap_encoded_len);
        errdefer alloc.free(value);
        encodeDenseArtifactCounterBootstrap(bootstrap, value[0..dense_artifact_counter_bootstrap_encoded_len]);
        try owned_keys.append(alloc, key);
        try owned_values.append(alloc, value);
        try store_writes.append(alloc, .{ .key = key, .value = value });
    }

    const PendingDenseArtifactCounterMutation = union(enum) {
        counter: u64,
        bootstrap: DenseArtifactCounterBootstrap,
        unavailable,
    };

    fn applyDenseArtifactCounterDelta(
        alloc: Allocator,
        store: *docstore_mod.DocStore,
        catalog: *const DenseArtifactCounterCatalog,
        mutations: *std.AutoHashMapUnmanaged(usize, PendingDenseArtifactCounterMutation),
        artifact_key: []const u8,
        artifact_value: ?[]const u8,
        delta: i64,
    ) !void {
        if (delta == 0) return;
        var identity = (artifact_ids.decodeEmbeddingArtifactIdentityAlloc(alloc, artifact_key) catch |err| switch (err) {
            error.InvalidInternalUserKey => return,
            else => return err,
        }) orelse return;
        defer identity.deinit(alloc);
        const value = artifact_value orelse return;
        const dims = enrichment_artifact_codec.decodeDenseEmbeddingDims(value) catch return;
        if (dims == 0) return;

        for (catalog.targetsFor(identity.embedding_name, dims)) |target_idx| {
            const target = &catalog.targets.items[target_idx];
            const gop = try mutations.getOrPut(alloc, target_idx);
            if (!gop.found_existing) {
                if (try loadDenseArtifactTargetCounter(alloc, store, target.index_name)) |count| {
                    gop.value_ptr.* = .{ .counter = count };
                } else if (try loadDenseArtifactCounterBootstrap(alloc, store, target.index_name)) |bootstrap| {
                    gop.value_ptr.* = .{ .bootstrap = bootstrap };
                } else {
                    // A missing counter without an active bootstrap is metadata
                    // debt. Do not manufacture a partial counter from the
                    // next mutation; repair will establish an authoritative
                    // snapshot plus concurrent signed delta.
                    gop.value_ptr.* = .unavailable;
                }
            }
            switch (gop.value_ptr.*) {
                .counter => |*count| {
                    if (delta > 0) {
                        count.* +|= @as(u64, @intCast(delta));
                    } else {
                        count.* -|= @as(u64, @intCast(-delta));
                    }
                },
                .bootstrap => |*bootstrap| {
                    bootstrap.delta = std.math.add(i64, bootstrap.delta, delta) catch
                        return error.DenseArtifactCounterBootstrapOverflow;
                },
                .unavailable => {},
            }
        }
    }

    fn appendDenseArtifactCounterMutations(
        alloc: Allocator,
        store: *docstore_mod.DocStore,
        index_manager: *const index_manager_mod.IndexManager,
        store_writes: *std.ArrayListUnmanaged(docstore_mod.KVPair),
        delete_keys: []const []const u8,
        owned_keys: *std.ArrayListUnmanaged([]u8),
        owned_values: *std.ArrayListUnmanaged([]u8),
    ) !void {
        var may_mutate_embedding_artifact = false;
        for (delete_keys) |key| {
            if (internal_keys.isEmbeddingArtifactKey(key) or internal_keys.isDerivedEmbeddingArtifactKey(key)) {
                may_mutate_embedding_artifact = true;
                break;
            }
        }
        if (!may_mutate_embedding_artifact) {
            for (store_writes.items) |write| {
                if (internal_keys.isEmbeddingArtifactKey(write.key) or internal_keys.isDerivedEmbeddingArtifactKey(write.key)) {
                    may_mutate_embedding_artifact = true;
                    break;
                }
            }
        }
        // Ordinary document-only writes stay allocation-free in counter
        // routing. Build the catalog lookup only for commits that can actually
        // change embedding-artifact coverage.
        if (!may_mutate_embedding_artifact) return;

        var catalog = try DenseArtifactCounterCatalog.init(alloc, index_manager);
        defer catalog.deinit(alloc);
        if (catalog.targets.items.len == 0) return;
        var mutations = std.AutoHashMapUnmanaged(usize, PendingDenseArtifactCounterMutation){};
        defer mutations.deinit(alloc);
        const deleted_sentinel = std.math.maxInt(usize);
        var final_artifact_mutations = std.StringHashMapUnmanaged(usize).empty;
        defer final_artifact_mutations.deinit(alloc);

        for (delete_keys) |key| {
            if (!internal_keys.isEmbeddingArtifactKey(key) and !internal_keys.isDerivedEmbeddingArtifactKey(key)) continue;
            const gop = try final_artifact_mutations.getOrPut(alloc, key);
            if (!gop.found_existing) gop.value_ptr.* = deleted_sentinel;
        }
        for (store_writes.items, 0..) |write, write_idx| {
            if (!internal_keys.isEmbeddingArtifactKey(write.key) and !internal_keys.isDerivedEmbeddingArtifactKey(write.key)) continue;
            try final_artifact_mutations.put(alloc, write.key, write_idx);
        }

        var final_it = final_artifact_mutations.iterator();
        while (final_it.next()) |entry| {
            const artifact_key = entry.key_ptr.*;
            const old_value = store.get(alloc, artifact_key) catch |err| switch (err) {
                error.NotFound => null,
                else => return err,
            };
            defer if (old_value) |value| alloc.free(value);
            if (old_value) |value| {
                try applyDenseArtifactCounterDelta(alloc, store, &catalog, &mutations, artifact_key, value, -1);
            }
            if (entry.value_ptr.* != deleted_sentinel) {
                const write = store_writes.items[entry.value_ptr.*];
                try applyDenseArtifactCounterDelta(alloc, store, &catalog, &mutations, write.key, write.value, 1);
            }
        }

        var it = mutations.iterator();
        while (it.next()) |entry| {
            const target = &catalog.targets.items[entry.key_ptr.*];
            switch (entry.value_ptr.*) {
                .counter => |count| try appendDenseArtifactTargetCounterWrite(
                    alloc,
                    store_writes,
                    owned_keys,
                    owned_values,
                    target.index_name,
                    count,
                ),
                .bootstrap => |bootstrap| try appendDenseArtifactCounterBootstrapWrite(
                    alloc,
                    store_writes,
                    owned_keys,
                    owned_values,
                    target.index_name,
                    bootstrap,
                ),
                .unavailable => {},
            }
        }
    }

    fn collectDenseArtifactTargetCounts(
        self: *DB,
        alloc: Allocator,
        rebuild_targets: ?[]const DenseArtifactRebuildTarget,
    ) !DenseArtifactTargetCounts {
        var counts: DenseArtifactTargetCounts = .{};
        errdefer counts.deinit(alloc);

        var target_lookup: DenseArtifactTargetLookup = .{};
        defer target_lookup.deinit(alloc);

        if (rebuild_targets) |targets| {
            for (targets) |target| {
                const entry = &self.core.index_manager.dense_indexes.items[target.dense_index_idx];
                try counts.per_target_index.put(alloc, target.dense_index_idx, 0);
                if (entry.embedding_names.len > 0) {
                    for (entry.embedding_names) |embedding_name| try target_lookup.add(alloc, embedding_name, entry.dims, target.dense_index_idx);
                } else {
                    try target_lookup.add(alloc, denseArtifactNameForEntry(entry), entry.dims, target.dense_index_idx);
                }
            }
        } else {
            for (self.core.index_manager.dense_indexes.items, 0..) |*entry, dense_index_idx| {
                const artifact_backed = entry.external or entry.chunk_name != null or entry.embedding_name != null or entry.embedding_names.len > 0;
                if (!artifact_backed) continue;
                try counts.per_target_index.put(alloc, dense_index_idx, 0);
                if (entry.embedding_names.len > 0) {
                    for (entry.embedding_names) |embedding_name| try target_lookup.add(alloc, embedding_name, entry.dims, dense_index_idx);
                } else {
                    try target_lookup.add(alloc, denseArtifactNameForEntry(entry), entry.dims, dense_index_idx);
                }
            }
        }

        if (target_lookup.by_artifact.count() == 0) return counts;

        const lower = try self.core.documentRangeLowerAlloc("");
        defer self.core.alloc.free(lower);

        const ScanState = struct {
            alloc: Allocator,
            counts: *DenseArtifactTargetCounts,
            target_lookup: *const DenseArtifactTargetLookup,

            fn scanEntry(ctx: ?*anyopaque, key: []const u8, value: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
                const state: *@This() = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
                if (!internal_keys.isInternalUserKey(key)) return .@"continue";

                var artifact_ref = (try decodeArtifactRefIfKnownAlloc(state.alloc, key)) orelse return .@"continue";
                defer artifact_ref.deinit(state.alloc);
                if (artifact_ref.kind != .embedding) return .@"continue";

                const dims = enrichment_artifact_codec.decodeDenseEmbeddingDims(value) catch |err| {
                    if (isRecoverableEmbeddingArtifactError(err)) return .@"continue";
                    return err;
                };
                if (dims == 0) return .@"continue";

                const lookup_key: DenseArtifactTargetKey = .{
                    .artifact_name = artifact_ref.name,
                    .dims = dims,
                };
                const indices = state.target_lookup.by_artifact.get(lookup_key) orelse return .@"continue";
                for (indices.items) |dense_index_idx| {
                    const count = state.counts.per_target_index.getPtr(dense_index_idx).?;
                    count.* += 1;
                }
                state.counts.total_target_artifacts += 1;
                return .@"continue";
            }
        };

        var state = ScanState{
            .alloc = alloc,
            .counts = &counts,
            .target_lookup = &target_lookup,
        };
        try self.core.store.scanWithContext(lower, "", .{}, &state, ScanState.scanEntry);
        return counts;
    }

    fn collectDenseArtifactTargetCountsFromCounters(
        self: *DB,
        alloc: Allocator,
        rebuild_targets: []const DenseArtifactRebuildTarget,
    ) !DenseArtifactTargetCounts {
        var counts: DenseArtifactTargetCounts = .{};
        errdefer counts.deinit(alloc);

        for (rebuild_targets) |target| {
            const entry = &self.core.index_manager.dense_indexes.items[target.dense_index_idx];
            // Startup planning and shadow activation must use the same
            // generation-fenced target after same-name recreation.
            const maybe_count = try denseTargetCountForIndexContext(self.async_context, entry.config.name);
            const count = maybe_count orelse 0;
            try counts.per_target_index.put(alloc, target.dense_index_idx, count);
            if (maybe_count != null) try counts.authoritative_targets.put(alloc, target.dense_index_idx, {});

            // Per-index counters drive coverage decisions below. Their sum is
            // only an upper bound when multiple indexes consume overlapping
            // artifact streams, so the final rebuild plan computes its exact
            // union after selecting the targets that actually need repair.
            counts.total_target_artifacts +|= count;
        }

        return counts;
    }

    fn collectDenseArtifactRebuildPlan(self: *DB, alloc: Allocator) !DenseArtifactRebuildPlan {
        const Candidate = struct {
            dense_index_idx: usize,
            persisted_resume: ?[]u8 = null,
            resume_state_current: bool = false,
            applied_sequence: u64,
            target_sequence: u64,
            artifact_counter_required: bool,
            fallback_target_count: u64 = 0,
            invalid_generation_error: ?[]const u8 = null,

            fn deinit(candidate: *@This(), local_alloc: Allocator) void {
                if (candidate.persisted_resume) |buf| local_alloc.free(buf);
                candidate.* = .{
                    .dense_index_idx = 0,
                    .applied_sequence = 0,
                    .target_sequence = 0,
                    .artifact_counter_required = false,
                };
            }
        };

        const recoverable_dense_integrity_errors = struct {
            fn check(err: anyerror) bool {
                return err == error.NotFound or err == error.FileNotFound or err == error.Corrupted;
            }
        };

        var targets = std.ArrayListUnmanaged(DenseArtifactRebuildTarget).empty;
        errdefer {
            for (targets.items) |*target| target.deinit(alloc);
            targets.deinit(alloc);
        }

        var generation_repairs = std.ArrayListUnmanaged(DenseGenerationRepairTarget).empty;
        errdefer generation_repairs.deinit(alloc);

        var rebuild_state_cleanups = std.ArrayListUnmanaged(usize).empty;
        errdefer rebuild_state_cleanups.deinit(alloc);

        var candidates = std.ArrayListUnmanaged(Candidate).empty;
        defer {
            for (candidates.items) |*candidate| candidate.deinit(alloc);
            candidates.deinit(alloc);
        }

        for (self.core.index_manager.dense_indexes.items, 0..) |*entry, dense_index_idx| {
            const artifact_backed = entry.external or entry.chunk_name != null or entry.embedding_name != null or entry.embedding_names.len > 0;
            const artifact_counter_required = try index_manager_mod.denseConfigRequiresArtifactCoverage(alloc, entry.config);
            const status_snapshot = try self.loadIndexStatusSnapshot(alloc, entry.config.name);
            const watermark_count = if (status_snapshot) |status_value|
                if (status_value.kind == .dense_vector) status_value.doc_count else 0
            else
                0;
            const watermark_regressed = watermark_count > entry.index.stats().active_count;
            if (!artifact_backed and !watermark_regressed) continue;

            const rebuild_root_path = try self.denseIndexRebuildStatePathAlloc(alloc, entry.config.name);
            defer alloc.free(rebuild_root_path);
            const rebuild_state = self.core.index_manager.rebuildState(.dense_vector, rebuild_root_path, entry.config);
            var loaded_rebuild_state = try rebuild_state.loadWithIo(alloc, self.core.index_manager.checkpointIo());
            defer loaded_rebuild_state.deinit(alloc);
            const persisted_resume: ?[]u8 = switch (loaded_rebuild_state) {
                .absent => null,
                // A cursor without the current catalog-generation identity is
                // proof of interrupted work, but never a safe position. Carry
                // an empty restart through the plan; execution owns the write.
                .legacy => try alloc.dupe(u8, ""),
                .corrupt => return error.InvalidRebuildState,
                .valid => |key| try alloc.dupe(u8, key),
            };
            errdefer if (persisted_resume) |buf| alloc.free(buf);
            const projection_checkpoint = try self.core.loadProjectionCheckpoint(alloc, entry.config.name);
            const config_hash = types.indexConfigHash(entry.config);
            const checkpoint_config_mismatch = projection_checkpoint.config_hash != config_hash;
            const applied_sequence = projection_checkpoint.applied_sequence;
            const target_sequence = try self.probeDerivedReplayTargetSequence(
                alloc,
                self.core.replaySource(),
                .{
                    .name = entry.config.name,
                    .kind = .dense_vector,
                },
                applied_sequence,
            );
            if (persisted_resume == null and
                !checkpoint_config_mismatch and
                applied_sequence < target_sequence and
                projection_checkpoint.status != .rebuilding and
                projection_checkpoint.status != .repair_required)
            {
                continue;
            }
            const invalid_generation_error: ?[]const u8 = blk: {
                if (checkpoint_config_mismatch) break :blk "dense_projection_config_mismatch";
                if (projection_checkpoint.status == .repair_required) break :blk "dense_projection_checkpoint_repair_required";
                if (entry.index.stats().active_count == 0) break :blk null;
                if (@hasDecl(@TypeOf(entry.index), "validateStoredStructure")) {
                    entry.index.validateStoredStructure(alloc) catch |err| {
                        if (recoverable_dense_integrity_errors.check(err)) break :blk "dense_projection_structure_invalid";
                        return err;
                    };
                }
                break :blk null;
            };
            try candidates.append(alloc, .{
                .dense_index_idx = dense_index_idx,
                .persisted_resume = persisted_resume,
                .resume_state_current = loaded_rebuild_state == .valid,
                .applied_sequence = applied_sequence,
                .target_sequence = target_sequence,
                .artifact_counter_required = artifact_counter_required,
                .fallback_target_count = watermark_count,
                .invalid_generation_error = invalid_generation_error,
            });
        }

        var candidate_targets = std.ArrayListUnmanaged(DenseArtifactRebuildTarget).empty;
        defer candidate_targets.deinit(alloc);
        for (candidates.items) |candidate| {
            try candidate_targets.append(alloc, .{ .dense_index_idx = candidate.dense_index_idx });
        }

        var target_counts = try self.collectDenseArtifactTargetCountsFromCounters(alloc, candidate_targets.items);
        defer target_counts.deinit(alloc);

        for (candidates.items) |*candidate| {
            const dense_index_idx = candidate.dense_index_idx;
            const entry = &self.core.index_manager.dense_indexes.items[dense_index_idx];
            const active_count = entry.index.stats().active_count;
            if (candidate.invalid_generation_error) |last_error| {
                try generation_repairs.append(alloc, .{
                    .dense_index_idx = dense_index_idx,
                    .trigger = .projection_generation_invalid,
                    .last_error = last_error,
                });
                if (candidate.persisted_resume != null) try rebuild_state_cleanups.append(alloc, dense_index_idx);
                continue;
            }
            if (candidate.artifact_counter_required and
                !target_counts.authoritative_targets.contains(dense_index_idx))
            {
                try generation_repairs.append(alloc, .{
                    .dense_index_idx = dense_index_idx,
                    .trigger = .artifact_counter_missing,
                    .last_error = "dense_artifact_counter_missing",
                });
                if (candidate.persisted_resume != null) try rebuild_state_cleanups.append(alloc, dense_index_idx);
                continue;
            }
            const artifact_target_count = if (target_counts.authoritative_targets.contains(dense_index_idx))
                target_counts.per_target_index.get(dense_index_idx).?
            else
                candidate.fallback_target_count;
            // Missing vectors can be filled in place. Surplus vectors and other
            // reset-class anomalies cannot: replay only upserts live keys and
            // would leave stale keys searchable. Reconstruct those through a
            // separately published generation instead.
            if (active_count > artifact_target_count) {
                // Never close/delete the published HBC generation in place.
                // Persist debt for the BackendRuntime-owned shadow-generation
                // state machine; the current generation remains queryable until
                // its replacement passes the fenced activation checks.
                try generation_repairs.append(alloc, .{
                    .dense_index_idx = dense_index_idx,
                    .trigger = .artifact_coverage_mismatch,
                    .last_error = "dense_artifact_coverage_surplus",
                });
                if (candidate.persisted_resume != null) try rebuild_state_cleanups.append(alloc, dense_index_idx);
                continue;
            }
            const already_repaired = denseCoverageMatchesTarget(active_count, artifact_target_count) and
                candidate.applied_sequence >= candidate.target_sequence;

            if (candidate.persisted_resume) |buf| {
                if (artifact_target_count == 0) {
                    try rebuild_state_cleanups.append(alloc, dense_index_idx);
                    continue;
                }
                if (already_repaired) {
                    try rebuild_state_cleanups.append(alloc, dense_index_idx);
                    continue;
                }
                try targets.append(alloc, .{
                    .dense_index_idx = dense_index_idx,
                    .resume_from = try alloc.dupe(u8, buf),
                    .resume_state_current = candidate.resume_state_current,
                    .artifact_target_count = artifact_target_count,
                });
                continue;
            }

            if (artifact_target_count == 0) continue;
            if (denseCoverageMatchesTarget(active_count, artifact_target_count)) continue;

            try targets.append(alloc, .{
                .dense_index_idx = dense_index_idx,
                .artifact_target_count = artifact_target_count,
            });
        }

        const owned_targets = try targets.toOwnedSlice(alloc);
        errdefer {
            for (owned_targets) |*target| target.deinit(alloc);
            if (owned_targets.len > 0) alloc.free(owned_targets);
        }
        const exact_target_sequence = if (owned_targets.len == 0) 0 else blk: {
            // Rebuild progress counts source artifacts, not index applications.
            // A repair already scans the artifact keyspace to rebuild vectors;
            // this lightweight dimensions-only pass keeps its progress total
            // exact for identical, partially overlapping, and disjoint source
            // sets without burdening every foreground artifact mutation with
            // another family of durable counters.
            var exact_counts = try self.collectDenseArtifactTargetCounts(alloc, owned_targets);
            defer exact_counts.deinit(alloc);
            break :blk exact_counts.total_target_artifacts;
        };
        const owned_generation_repairs = try generation_repairs.toOwnedSlice(alloc);
        errdefer if (owned_generation_repairs.len > 0) alloc.free(owned_generation_repairs);
        const owned_rebuild_state_cleanups = try rebuild_state_cleanups.toOwnedSlice(alloc);
        return .{
            .targets = owned_targets,
            .generation_repairs = owned_generation_repairs,
            .rebuild_state_cleanups = owned_rebuild_state_cleanups,
            .target_sequence = exact_target_sequence,
        };
    }

    fn prepareDenseArtifactRebuildPlan(
        self: *DB,
        plan: DenseArtifactRebuildPlan,
        dense_visibility_attempted: *bool,
    ) !DenseArtifactRebuildPreparation {
        var outcome: DenseArtifactRebuildPreparation = .{};
        for (plan.rebuild_state_cleanups) |dense_index_idx| {
            const entry = &self.core.index_manager.dense_indexes.items[dense_index_idx];
            const rebuild_root_path = try self.denseIndexRebuildStatePathAlloc(self.alloc, entry.config.name);
            defer self.alloc.free(rebuild_root_path);
            const rebuild_state = self.core.index_manager.rebuildState(.dense_vector, rebuild_root_path, entry.config);
            try rebuild_state.clearAllWithIo(self.core.index_manager.checkpointIo());
            outcome.made_progress = true;
        }
        for (plan.generation_repairs) |repair| {
            const entry = &self.core.index_manager.dense_indexes.items[repair.dense_index_idx];
            const repair_intent = self.ensureAutomaticDenseGenerationRepairIntentOutcome(
                self.alloc,
                entry.config,
                repair.trigger,
                repair.last_error,
            ) catch |err| switch (err) {
                error.DurableIndexRepairStateUnavailable => {
                    // Embedded/Lite runtimes intentionally have no durable
                    // maintenance owner. They still use a shadow generation and
                    // the same search/apply activation fences; only crash-resume
                    // scheduling is omitted.
                    var cfg = try types.IndexConfig.clone(self.alloc, entry.config);
                    defer cfg.deinit(self.alloc);
                    if (repair.trigger == .artifact_counter_missing) {
                        const bootstrap_id = try index_repair_state.newRepairId(self.alloc);
                        try self.ensureDenseArtifactTargetCounterForRepair(
                            self.alloc,
                            cfg,
                            bootstrap_id,
                            null,
                        );
                    }
                    // Shadow publication can complete before a later durable
                    // bookkeeping failure escapes. Arm cache retirement before
                    // entering the mutation boundary.
                    dense_visibility_attempted.* = true;
                    const rebuilt = try self.rebuildIndexWithShadowReplacement(self.alloc, cfg, .{}, null);
                    if (rebuilt.yielded) return error.ShadowIndexCatchUpIncomplete;
                    outcome.made_progress = true;
                    outcome.dense_visibility_changed = true;
                    continue;
                },
                else => return err,
            };
            outcome.made_progress = outcome.made_progress or repair_intent.made_progress;
        }
        for (plan.targets) |target| {
            const entry = &self.core.index_manager.dense_indexes.items[target.dense_index_idx];
            const checkpoint = try self.core.loadProjectionCheckpoint(self.alloc, entry.config.name);
            const config_hash = types.indexConfigHash(entry.config);
            if (checkpoint.status != .rebuilding or checkpoint.config_hash != config_hash) {
                try self.core.saveProjectionCheckpoint(entry.config.name, .{
                    .applied_sequence = checkpoint.applied_sequence,
                    .status = .rebuilding,
                    .generation = checkpoint.generation,
                    .config_hash = config_hash,
                });
                outcome.made_progress = true;
            }
            // Only a cursor owned by this catalog generation is reusable.
            // Fresh targets and stale-generation restart markers are persisted
            // here so read-only readiness probes never perform migration I/O.
            if (!target.resume_state_current) {
                const rebuild_root_path = try self.denseIndexRebuildStatePathAlloc(self.alloc, entry.config.name);
                defer self.alloc.free(rebuild_root_path);
                const rebuild_state = self.core.index_manager.rebuildState(.dense_vector, rebuild_root_path, entry.config);
                try rebuild_state.restartWithIo(self.core.index_manager.checkpointIo());
                outcome.made_progress = true;
            }
        }
        return outcome;
    }

    fn finalizeDenseArtifactRebuildPlan(self: *DB, alloc: Allocator, plan: DenseArtifactRebuildPlan) !bool {
        var made_progress = false;
        for (plan.targets) |target| {
            const entry = &self.core.index_manager.dense_indexes.items[target.dense_index_idx];
            const rebuild_root_path = try self.denseIndexRebuildStatePathAlloc(alloc, entry.config.name);
            defer alloc.free(rebuild_root_path);
            const rebuild_state = self.core.index_manager.rebuildState(.dense_vector, rebuild_root_path, entry.config);
            const applied_sequence = try self.core.loadAppliedSequence(alloc, entry.config.name);
            const target_sequence = try self.probeDerivedReplayTargetSequence(
                alloc,
                self.core.replaySource(),
                .{
                    .name = entry.config.name,
                    .kind = .dense_vector,
                },
                applied_sequence,
            );
            const repaired = denseCoverageMatchesTarget(entry.index.stats().active_count, target.artifact_target_count) and
                applied_sequence >= target_sequence;
            if (repaired) {
                try rebuild_state.clearAllWithIo(self.core.index_manager.checkpointIo());
                const checkpoint = try self.core.loadProjectionCheckpoint(alloc, entry.config.name);
                try self.core.saveProjectionCheckpoint(entry.config.name, .{
                    .applied_sequence = applied_sequence,
                    .status = .clean,
                    .generation = checkpoint.generation +| 1,
                    .config_hash = types.indexConfigHash(entry.config),
                });
                made_progress = true;
            }
        }
        return made_progress;
    }

    fn denseArtifactWatermarkRepairNeeded(self: *DB, alloc: Allocator) !bool {
        return (try self.repairDenseArtifactAppliedSequencesFromCoverage(alloc, false)) > 0;
    }

    /// Restore repair operates on a private staged generation with index
    /// workers disabled. Replay can change the final artifact set after an
    /// earlier counter bootstrap, so recompute each durable counter from that
    /// final store and rebuild any unpublished generation whose exact coverage
    /// differs. No live shadow-generation job is needed or allowed here.
    const RestoreDenseArtifactCoverageRepair = struct {
        rebuilt: usize = 0,
        made_progress: bool = false,
        waiting_for_workers: bool = false,
    };

    fn repairRestoreDenseArtifactCoverageFromFinalArtifacts(self: *DB, alloc: Allocator) !RestoreDenseArtifactCoverageRepair {
        var target_counts = try self.collectDenseArtifactTargetCounts(alloc, null);
        defer target_counts.deinit(alloc);

        var names = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (names.items) |name| alloc.free(name);
            names.deinit(alloc);
        }
        var result = RestoreDenseArtifactCoverageRepair{};
        for (self.core.index_manager.dense_indexes.items, 0..) |*entry, dense_index_idx| {
            if (!try index_manager_mod.denseConfigRequiresArtifactCoverage(alloc, entry.config)) continue;
            const expected = target_counts.per_target_index.get(dense_index_idx) orelse 0;
            const current = try loadDenseArtifactTargetCounter(alloc, self.core.store, entry.config.name);
            if (current == null or current.? != expected) {
                var raw: [8]u8 = undefined;
                std.mem.writeInt(u64, raw[0..8], expected, .little);
                const counter_key = try denseArtifactTargetCounterKeyAlloc(alloc, entry.config.name);
                defer alloc.free(counter_key);
                try self.core.store.put(counter_key, &raw);
                result.made_progress = true;
            }
            if (entry.index.stats().active_count == expected) continue;
            try names.append(alloc, try alloc.dupe(u8, entry.config.name));
        }
        if (names.items.len > 0 and self.start_index_workers) {
            result.waiting_for_workers = true;
            return result;
        }

        for (names.items) |name| {
            try self.core.index_manager.resetDenseIndexForArtifactRebuild(name);
            result.rebuilt += try rebuildDenseIndexForTargetCoverageContext(self.async_context, name, 2048);
        }
        if (names.items.len > 0) {
            self.clearDenseHbcCaches();
            result.made_progress = true;
        }
        return result;
    }

    /// Portable restore owns the complete logical corpus and rebuilds every
    /// derived projection before publication. Missing-counter and surplus
    /// coverage debt can therefore be repaired from the final restored
    /// snapshot without waiting for the ordinary background generation-repair
    /// worker. Clear only the matching durable debt after counter coverage,
    /// replay, and checkpoint identity all prove the active generation
    /// queryable.
    const RestoreDenseArtifactCompletion = enum {
        complete,
        progressed,
        completed_with_progress,
    };

    fn completeRestoreDenseArtifactRepairs(self: *DB, alloc: Allocator) !RestoreDenseArtifactCompletion {
        var state = self.loadIndexRepairState(alloc) catch |err| switch (err) {
            error.FileNotFound, error.DurableIndexRepairStateUnavailable => return .complete,
            else => return err,
        };
        defer state.deinit(alloc);

        // Validate every durable intent before changing counters or removing
        // any intent. A pending proof error must be observably mutation-free.
        for (state.entries.items) |entry| {
            if (entry.intent.trigger != .artifact_counter_missing and
                entry.intent.trigger != .artifact_coverage_mismatch)
            {
                continue;
            }
            const cfg = self.core.index_manager.get(entry.intent.index_name) orelse
                return error.RestoreDenseIndexProofIncomplete;
            if (cfg.kind != .dense_vector or
                types.indexConfigHash(cfg.*) != entry.intent.config_hash)
            {
                return error.RestoreDenseConfigProofIncomplete;
            }
        }

        // Counter bootstrap is required input for worker convergence. Publish
        // it as its own successful bounded quantum, then retry all proofs from
        // a stable state instead of returning a pending error after mutation.
        var bootstrapped = false;
        for (state.entries.items) |entry| {
            if (entry.intent.trigger != .artifact_counter_missing) continue;
            const cfg = self.core.index_manager.get(entry.intent.index_name) orelse unreachable;
            if (try loadDenseArtifactTargetCounter(alloc, self.core.store, cfg.name) != null) continue;
            try self.ensureDenseArtifactTargetCounterForRepair(
                alloc,
                cfg.*,
                entry.intent.repair_id,
                null,
            );
            bootstrapped = true;
        }
        if (bootstrapped) return .progressed;

        // Complete every proof before removing the first intent. This keeps
        // all pending exits side-effect free and avoids partially publishing a
        // multi-index restore proof.
        for (state.entries.items) |entry| {
            if (entry.intent.trigger != .artifact_counter_missing and
                entry.intent.trigger != .artifact_coverage_mismatch)
            {
                continue;
            }
            const cfg = self.core.index_manager.get(entry.intent.index_name) orelse unreachable;
            const expected = (try loadDenseArtifactTargetCounter(alloc, self.core.store, cfg.name)) orelse
                return error.RestoreDenseCounterProofIncomplete;
            const dense = self.core.index_manager.denseIndex(cfg.name) orelse
                return error.RestoreDenseIndexProofIncomplete;
            if (!denseCoverageMatchesTarget(dense.index.stats().active_count, expected)) {
                return error.RestoreDenseCoverageProofIncomplete;
            }

            const applied = try self.core.loadAppliedSequence(alloc, cfg.name);
            const target = try self.probeDerivedReplayTargetSequence(
                alloc,
                self.core.replaySource(),
                .{ .name = cfg.name, .kind = .dense_vector },
                applied,
            );
            const checkpoint = try self.core.loadProjectionCheckpoint(alloc, cfg.name);
            if (applied < target or
                checkpoint.status != .clean or
                checkpoint.applied_sequence < target or
                checkpoint.config_hash != entry.intent.config_hash)
            {
                return error.RestoreDenseCheckpointIncomplete;
            }
        }

        var removed_any = false;
        for (state.entries.items) |entry| {
            if (entry.intent.trigger != .artifact_counter_missing and
                entry.intent.trigger != .artifact_coverage_mismatch)
            {
                continue;
            }
            // This is restore-owned metadata debt, not a shadow-generation
            // attempt, so there is no candidate phase chain to advance. All
            // entries passed proof before the first durable removal.
            try self.removeIndexRepairIntentAndPin(alloc, entry.intent.repair_id);
            removed_any = true;
        }
        return if (removed_any) .completed_with_progress else .complete;
    }

    fn repairDenseArtifactAppliedSequencesIfCovered(self: *DB, alloc: Allocator) !usize {
        return try self.repairDenseArtifactAppliedSequencesFromCoverage(alloc, true);
    }

    fn repairDenseArtifactAppliedSequencesFromCoverage(self: *DB, alloc: Allocator, repair: bool) !usize {
        var target_counts = try self.collectDenseArtifactTargetCounts(alloc, null);
        defer target_counts.deinit(alloc);

        var repaired: usize = 0;
        for (self.core.index_manager.dense_indexes.items, 0..) |*entry, dense_index_idx| {
            const artifact_backed = entry.external or entry.chunk_name != null or entry.embedding_name != null or entry.embedding_names.len > 0;
            if (!artifact_backed) continue;

            const artifact_target_count = target_counts.per_target_index.get(dense_index_idx) orelse 0;
            if (artifact_target_count == 0) continue;
            if (entry.index.stats().active_count != artifact_target_count) continue;

            const applied_sequence = try self.core.loadAppliedSequence(alloc, entry.config.name);
            const checkpoint = try self.core.loadProjectionCheckpoint(alloc, entry.config.name);
            const target_sequence = try self.probeDerivedReplayTargetSequence(
                alloc,
                self.core.replaySource(),
                .{
                    .name = entry.config.name,
                    .kind = .dense_vector,
                },
                applied_sequence,
            );
            const checkpoint_needs_finalization = checkpoint.status == .rebuilding or
                checkpoint.applied_sequence < target_sequence;
            if (applied_sequence >= target_sequence and !checkpoint_needs_finalization) continue;

            repaired += 1;
            if (repair) {
                if (applied_sequence < target_sequence) try self.core.saveAppliedSequence(entry.config.name, target_sequence);
                const rebuild_root_path = try self.denseIndexRebuildStatePathAlloc(alloc, entry.config.name);
                defer alloc.free(rebuild_root_path);
                const rebuild_state = self.core.index_manager.rebuildState(.dense_vector, rebuild_root_path, entry.config);
                try rebuild_state.clearAllWithIo(self.core.index_manager.checkpointIo());
                try self.core.saveProjectionCheckpoint(entry.config.name, .{
                    .applied_sequence = target_sequence,
                    .status = .clean,
                    .generation = checkpoint.generation + @intFromBool(checkpoint.status == .rebuilding),
                    .config_hash = types.indexConfigHash(entry.config),
                });
            }
        }
        return repaired;
    }

    fn rebuildDenseIndexesFromStoredEmbeddingArtifacts(self: *DB, alloc: Allocator) !usize {
        return try self.rebuildDenseIndexesFromStoredEmbeddingArtifactsWithProgress(alloc, null, null);
    }

    fn rebuildDenseIndexesFromStoredEmbeddingArtifactsResumeWithProgress(
        self: *DB,
        alloc: Allocator,
        resume_from: ?[]const u8,
        rebuild_targets: ?[]const DenseArtifactRebuildTarget,
        target_sequence_override: ?u64,
        progress_ctx: ?*anyopaque,
        progress_hook: ?ReplayProgressHook,
        resume_ctx: ?*anyopaque,
        resume_hook: ?DenseArtifactRebuildResumeHook,
        dense_visibility_attempted: *bool,
        rebuild_chunk_size: usize,
        rebuild_progress_interval: usize,
    ) !usize {
        errdefer if (dense_visibility_attempted.*) {
            self.clearDenseHbcCaches();
            // The nested mutation boundary has already retired every cache;
            // keep the outer error guard from repeating the O(indexes) walk.
            dense_visibility_attempted.* = false;
        };
        const lower = try self.core.documentRangeLowerAlloc("");
        defer self.core.alloc.free(lower);

        const target_sequence = if (target_sequence_override) |value| value else blk: {
            var target_counts = try self.collectDenseArtifactTargetCounts(alloc, rebuild_targets);
            defer target_counts.deinit(alloc);
            break :blk target_counts.total_target_artifacts;
        };
        if (progress_hook != null) {
            const initial_progress: ReplayProgress = .{
                .sequence = 0,
                .target_sequence = target_sequence,
                .scanned_entries = 0,
                .applied_entries = 0,
                .active = true,
            };
            setDenseCatchUpProgress(self.async_context, initial_progress);
            try progress_hook.?(progress_ctx.?, "", initial_progress);
        }

        const ScanState = struct {
            db: *DB,
            alloc: Allocator,
            resume_from: ?[]const u8,
            target_sequence: u64,
            progress_ctx: ?*anyopaque,
            progress_hook: ?ReplayProgressHook,
            resume_ctx: ?*anyopaque,
            resume_hook: ?DenseArtifactRebuildResumeHook,
            dense_visibility_attempted: *bool,
            rebuild_chunk_size: usize,
            rebuild_progress_interval: usize,
            rebuild_targets: ?[]const DenseArtifactRebuildTarget = null,
            rebuild_target_lookup: std.StringHashMapUnmanaged(usize) = .empty,
            writes: std.ArrayListUnmanaged(mapper.DenseEmbeddingWrite) = .empty,
            rebuilt: usize = 0,
            scanned_entries: usize = 0,
            last_reported_scanned_entries: usize = 0,
            last_reported_rebuilt: usize = 0,
            last_matching_key: ?[]u8 = null,
            last_flushed_key: ?[]u8 = null,

            fn deinit(state: *@This()) void {
                freeDenseArtifactRebuildWrites(state.alloc, &state.writes);
                state.writes.deinit(state.alloc);
                state.rebuild_target_lookup.deinit(state.alloc);
                if (state.last_matching_key) |buf| state.alloc.free(buf);
                if (state.last_flushed_key) |buf| state.alloc.free(buf);
            }

            fn updateOwnedKey(state: *@This(), slot: *?[]u8, key: []const u8) !void {
                if (slot.*) |buf| state.alloc.free(buf);
                slot.* = try state.alloc.dupe(u8, key);
            }

            fn rebuildTargetForIndex(
                state: *const @This(),
                index_name: []const u8,
            ) ?*const DenseArtifactRebuildTarget {
                const targets = state.rebuild_targets orelse return null;
                const target_idx = state.rebuild_target_lookup.get(index_name) orelse return null;
                return &targets[target_idx];
            }

            fn publishProgress(state: *@This(), active: bool) !void {
                const hook = state.progress_hook orelse return;
                const progress: ReplayProgress = .{
                    .sequence = @intCast(state.rebuilt),
                    .target_sequence = state.target_sequence,
                    .scanned_entries = @intCast(state.scanned_entries),
                    .applied_entries = @intCast(state.rebuilt),
                    .active = active,
                };
                state.last_reported_scanned_entries = state.scanned_entries;
                state.last_reported_rebuilt = state.rebuilt;
                setDenseCatchUpProgress(state.db.async_context, progress);
                try hook(state.progress_ctx.?, "", progress);
            }

            fn flushChunk(state: *@This(), key: []const u8) !void {
                // Dense apply may publish its HBC generation before returning
                // a later cache/bookkeeping error. Mark the attempt first so
                // every subsequent failure retires potentially stale readers.
                state.dense_visibility_attempted.* = true;
                try state.db.flushDenseArtifactRebuildChunk(state.alloc, &state.writes);
                try state.updateOwnedKey(&state.last_flushed_key, key);
                if (state.resume_hook) |hook| try hook(state.resume_ctx.?, key);
                try state.publishProgress(true);
            }

            fn scanEntry(ctx: ?*anyopaque, key: []const u8, value: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
                const state: *@This() = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
                if (!internal_keys.isInternalUserKey(key)) return .@"continue";
                if (state.resume_from) |resume_key| {
                    if (resume_key.len > 0 and std.mem.order(u8, key, resume_key) != .gt) return .@"continue";
                }

                var artifact_ref = (try decodeArtifactRefIfKnownAlloc(state.alloc, key)) orelse return .@"continue";
                defer artifact_ref.deinit(state.alloc);
                if (artifact_ref.kind != .embedding) return .@"continue";
                state.scanned_entries += 1;
                try state.updateOwnedKey(&state.last_matching_key, key);

                const vector = enrichment_artifact_codec.decodeDenseEmbeddingAlloc(state.alloc, value) catch |err| {
                    if (isRecoverableEmbeddingArtifactError(err)) {
                        return .@"continue";
                    }
                    return err;
                };
                defer state.alloc.free(vector);
                const dims: u32 = @intCast(vector.len);
                if (dims == 0) return .@"continue";

                const consumer_indexes = state.db.core.index_manager.denseIndexesForEmbedding(state.alloc, artifact_ref.name, dims) catch |err| switch (err) {
                    error.ConflictingEnrichmentConfig => return .@"continue",
                    else => return err,
                };
                defer {
                    for (consumer_indexes) |index_name| state.alloc.free(index_name);
                    state.alloc.free(consumer_indexes);
                }
                if (consumer_indexes.len == 0) return .@"continue";

                const source_key = if (artifact_ref.source) |source| blk: {
                    var source_ref = types.ArtifactRef{
                        .document_id = try state.alloc.dupe(u8, artifact_ref.document_id),
                        .name = try state.alloc.dupe(u8, source.name),
                        .kind = source.kind,
                        .chunk_id = source.chunk_id,
                        .unit_id = if (source.unit_id) |unit_id| try state.alloc.dupe(u8, unit_id) else null,
                    };
                    defer source_ref.deinit(state.alloc);
                    break :blk try artifact_ids.internalKeyForArtifactRefAlloc(state.alloc, source_ref);
                } else try state.alloc.dupe(u8, artifact_ref.document_id);
                defer state.alloc.free(source_key);

                var emitted_any_target = false;
                for (consumer_indexes) |index_name| {
                    if (state.rebuild_targets) |_| {
                        const target = state.rebuildTargetForIndex(index_name) orelse continue;
                        if (target.resume_from) |target_resume| {
                            if (target_resume.len > 0 and std.mem.order(u8, key, target_resume) != .gt) continue;
                        }
                    }
                    try state.writes.append(state.alloc, .{
                        .index_name = try state.alloc.dupe(u8, index_name),
                        .doc_key = try state.alloc.dupe(u8, source_key),
                        .artifact_key = try state.alloc.dupe(u8, key),
                        .vector = &.{},
                    });
                    emitted_any_target = true;
                }
                if (emitted_any_target) {
                    state.rebuilt += 1;
                }

                if (state.progress_hook != null and
                    (state.scanned_entries - state.last_reported_scanned_entries >= state.rebuild_progress_interval or
                        state.rebuilt - state.last_reported_rebuilt >= state.rebuild_progress_interval))
                {
                    try state.publishProgress(true);
                }

                if (state.writes.items.len >= state.rebuild_chunk_size) {
                    try state.flushChunk(key);
                }
                return .@"continue";
            }
        };

        var state = ScanState{
            .db = self,
            .alloc = alloc,
            .resume_from = resume_from,
            .target_sequence = target_sequence,
            .progress_ctx = progress_ctx,
            .progress_hook = progress_hook,
            .resume_ctx = resume_ctx,
            .resume_hook = resume_hook,
            .dense_visibility_attempted = dense_visibility_attempted,
            .rebuild_chunk_size = rebuild_chunk_size,
            .rebuild_progress_interval = rebuild_progress_interval,
            .rebuild_targets = rebuild_targets,
        };
        defer state.deinit();

        if (rebuild_targets) |targets| {
            for (targets, 0..) |target, target_idx| {
                const entry = &self.core.index_manager.dense_indexes.items[target.dense_index_idx];
                try state.rebuild_target_lookup.put(state.alloc, entry.config.name, target_idx);
            }
        }

        try self.core.store.scanWithContext(lower, "", .{}, &state, ScanState.scanEntry);

        if (state.writes.items.len > 0) {
            dense_visibility_attempted.* = true;
            try self.flushDenseArtifactRebuildChunk(alloc, &state.writes);
        }
        if (state.last_flushed_key == null and state.last_matching_key != null) {
            try state.updateOwnedKey(&state.last_flushed_key, state.last_matching_key.?);
        }
        if (resume_hook) |hook| {
            if (state.last_flushed_key) |last_key| try hook(resume_ctx.?, last_key);
        }
        if (progress_hook != null) {
            const final_progress: ReplayProgress = .{
                .sequence = @intCast(state.rebuilt),
                .target_sequence = target_sequence,
                .scanned_entries = @intCast(state.scanned_entries),
                .applied_entries = @intCast(state.rebuilt),
                .active = false,
            };
            setDenseCatchUpProgress(self.async_context, final_progress);
            try progress_hook.?(progress_ctx.?, "", final_progress);
        }
        if (state.rebuilt == 0) return 0;
        return state.rebuilt;
    }

    fn rebuildDenseIndexesFromStoredEmbeddingArtifactsWithProgress(
        self: *DB,
        alloc: Allocator,
        progress_ctx: ?*anyopaque,
        progress_hook: ?ReplayProgressHook,
    ) !usize {
        var dense_visibility_attempted = false;
        errdefer if (dense_visibility_attempted) self.clearDenseHbcCaches();
        const rebuilt = try self.rebuildDenseIndexesFromStoredEmbeddingArtifactsResumeWithProgress(
            alloc,
            null,
            null,
            null,
            progress_ctx,
            progress_hook,
            null,
            null,
            &dense_visibility_attempted,
            2048,
            128,
        );
        if (dense_visibility_attempted) self.clearDenseHbcCaches();
        return rebuilt;
    }

    pub fn rebuildDenseIndexesFromStoredEmbeddingArtifactsIfNeeded(self: *DB, alloc: Allocator) !usize {
        return try self.rebuildDenseIndexesFromStoredEmbeddingArtifactsIfNeededWithProgress(alloc, null, null);
    }

    pub fn hasPendingDenseArtifactRebuild(self: *DB, alloc: Allocator) !bool {
        var plan = try self.collectDenseArtifactRebuildPlan(alloc);
        defer plan.deinit(alloc);
        // Stale resume metadata without a logical target is maintenance-only:
        // the execution helper clears it, but readiness must not surface it as
        // rebuild debt (and this probe must remain mutation-free).
        return plan.targets.len > 0 or plan.generation_repairs.len > 0;
    }

    /// Internal scheduler predicate. Unlike logical readiness, maintenance
    /// includes stale cursor cleanup, but excludes generation debt already
    /// delegated to an equivalent durable repair intent. The probe is
    /// read-only: cursor migration and query-gate changes happen in execution.
    pub fn denseArtifactRebuildMaintenanceNeeded(self: *DB, alloc: Allocator) !bool {
        var plan = try self.collectDenseArtifactRebuildPlan(alloc);
        defer plan.deinit(alloc);
        if (plan.targets.len > 0 or plan.rebuild_state_cleanups.len > 0) return true;
        for (plan.generation_repairs) |repair| {
            const entry = &self.core.index_manager.dense_indexes.items[repair.dense_index_idx];
            if (!self.core.index_manager.repairUnavailable(entry.config.name)) return true;
            const repair_id = (try self.indexRepairIdForIndex(alloc, entry.config.name)) orelse return true;
            var existing = self.loadIndexRepairEntryById(alloc, repair_id) catch |err| switch (err) {
                error.FileNotFound, error.IndexRepairIntentNotFound => return true,
                else => return err,
            };
            defer existing.deinit(alloc);
            if (automaticDenseGenerationRepairTriggerPriority(repair.trigger) >
                automaticDenseGenerationRepairTriggerPriority(existing.intent.trigger)) return true;
        }
        return false;
    }

    /// Executes one internal maintenance pass and reports only state mutation,
    /// not the legacy public work count. Cache retirement is owned here so
    /// managed callers cannot mistake rediscovered repair debt for visibility.
    pub fn runDenseArtifactRebuildMaintenanceWithProgress(
        self: *DB,
        alloc: Allocator,
        progress_ctx: ?*anyopaque,
        progress_hook: ?ReplayProgressHook,
    ) !bool {
        const outcome = try self.rebuildDenseIndexesFromStoredEmbeddingArtifactsOutcomeWithProgress(
            alloc,
            progress_ctx,
            progress_hook,
        );
        if (outcome.dense_visibility_changed) self.clearDenseHbcCaches();
        return outcome.made_progress;
    }

    pub fn rebuildDenseIndexesFromStoredEmbeddingArtifactsIfNeededWithProgress(
        self: *DB,
        alloc: Allocator,
        progress_ctx: ?*anyopaque,
        progress_hook: ?ReplayProgressHook,
    ) !usize {
        return (try self.rebuildDenseIndexesFromStoredEmbeddingArtifactsOutcomeWithProgress(
            alloc,
            progress_ctx,
            progress_hook,
        )).reported_work;
    }

    fn rebuildDenseIndexesFromStoredEmbeddingArtifactsOutcomeWithProgress(
        self: *DB,
        alloc: Allocator,
        progress_ctx: ?*anyopaque,
        progress_hook: ?ReplayProgressHook,
    ) !DenseArtifactRebuildOutcome {
        var dense_visibility_attempted = false;
        errdefer if (dense_visibility_attempted) self.clearDenseHbcCaches();
        var plan = try self.collectDenseArtifactRebuildPlan(alloc);
        defer plan.deinit(alloc);
        if (plan.targets.len == 0 and
            plan.generation_repairs.len == 0 and
            plan.rebuild_state_cleanups.len == 0)
        {
            const repaired_watermarks = try self.repairDenseArtifactAppliedSequencesIfCovered(alloc);
            return .{
                .reported_work = repaired_watermarks,
                .made_progress = repaired_watermarks > 0,
            };
        }

        const prepared = try self.prepareDenseArtifactRebuildPlan(plan, &dense_visibility_attempted);
        if (plan.targets.len == 0) {
            // Collection used to clear stale resume metadata before reaching
            // the no-plan watermark path. Preserve that behavior now that
            // collection is pure, without conflating an existing generation
            // repair intent with new progress.
            const repaired_watermarks = if (plan.generation_repairs.len == 0)
                try self.repairDenseArtifactAppliedSequencesIfCovered(alloc)
            else
                0;
            return .{
                .reported_work = if (plan.generation_repairs.len > 0)
                    plan.generation_repairs.len
                else
                    repaired_watermarks,
                .made_progress = prepared.made_progress or repaired_watermarks > 0,
                .dense_visibility_changed = prepared.dense_visibility_changed,
            };
        }
        const ResumePersistCtx = struct {
            db: *DB,
            alloc: Allocator,
            targets: []DenseArtifactRebuildTarget,
            made_progress: bool = false,

            fn run(ctx: *anyopaque, last_key: []const u8) !void {
                const persist: *@This() = @ptrCast(@alignCast(ctx));
                for (persist.targets) |*target| {
                    if (target.resume_from) |resume_from| {
                        if (std.mem.order(u8, last_key, resume_from) != .gt) continue;
                    }
                    const entry = &persist.db.core.index_manager.dense_indexes.items[target.dense_index_idx];
                    const rebuild_root_path = try persist.db.denseIndexRebuildStatePathAlloc(persist.alloc, entry.config.name);
                    defer persist.alloc.free(rebuild_root_path);
                    const rebuild_state = persist.db.core.index_manager.rebuildState(.dense_vector, rebuild_root_path, entry.config);
                    try rebuild_state.updateWithIo(persist.db.core.index_manager.checkpointIo(), last_key);
                    const owned_key = try persist.alloc.dupe(u8, last_key);
                    errdefer persist.alloc.free(owned_key);
                    if (target.resume_from) |resume_from| persist.alloc.free(resume_from);
                    target.resume_from = owned_key;
                    persist.made_progress = true;
                }
            }
        };
        var persist_ctx = ResumePersistCtx{
            .db = self,
            .alloc = alloc,
            .targets = plan.targets,
        };
        const rebuilt = try self.rebuildDenseIndexesFromStoredEmbeddingArtifactsResumeWithProgress(
            alloc,
            null,
            plan.targets,
            plan.target_sequence,
            progress_ctx,
            progress_hook,
            &persist_ctx,
            ResumePersistCtx.run,
            &dense_visibility_attempted,
            2048,
            128,
        );
        const finalized = try self.finalizeDenseArtifactRebuildPlan(alloc, plan);
        const repaired_watermarks = try self.repairDenseArtifactAppliedSequencesIfCovered(alloc);
        return .{
            .reported_work = rebuilt,
            .made_progress = prepared.made_progress or persist_ctx.made_progress or rebuilt > 0 or finalized or repaired_watermarks > 0,
            .dense_visibility_changed = prepared.dense_visibility_changed or rebuilt > 0,
        };
    }

    const StoredGeneratedReplayBatch = struct {
        writes: []types.BatchWrite = &.{},
        extracted: []mapper.ExtractedWrite = &.{},
        next_lower: ?[]u8 = null,

        fn deinit(self: *@This(), alloc: Allocator) void {
            for (self.writes) |write| {
                alloc.free(@constCast(write.key));
                alloc.free(@constCast(write.value));
            }
            if (self.writes.len > 0) alloc.free(self.writes);
            for (self.extracted) |*item| item.deinit(alloc);
            if (self.extracted.len > 0) alloc.free(self.extracted);
            if (self.next_lower) |buf| alloc.free(buf);
            self.* = .{};
        }
    };

    fn collectStoredGeneratedReplayBatch(
        self: *DB,
        alloc: Allocator,
        lower: []const u8,
        lower_exclusive: bool,
        limit: usize,
    ) !StoredGeneratedReplayBatch {
        const ScanState = struct {
            alloc: Allocator,
            limit: usize,
            writes: std.ArrayListUnmanaged(types.BatchWrite) = .empty,
            extracted: std.ArrayListUnmanaged(mapper.ExtractedWrite) = .empty,
            last_store_key: ?[]u8 = null,

            fn deinitPartial(state: *@This()) void {
                for (state.writes.items) |write| {
                    state.alloc.free(@constCast(write.key));
                    state.alloc.free(@constCast(write.value));
                }
                state.writes.deinit(state.alloc);
                for (state.extracted.items) |*item| item.deinit(state.alloc);
                state.extracted.deinit(state.alloc);
                if (state.last_store_key) |key| state.alloc.free(key);
            }

            fn scanEntry(ctx: ?*anyopaque, key: []const u8, value: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
                const state: *@This() = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
                if (!isPrimaryDocumentStoreKey(key)) return .@"continue";
                const raw_key = (try internal_keys.decodePrimaryDocumentKeyAlloc(state.alloc, key)) orelse return .@"continue";
                errdefer state.alloc.free(raw_key);
                const raw_value = try state.alloc.dupe(u8, value);
                errdefer state.alloc.free(raw_value);
                try state.writes.append(state.alloc, .{
                    .key = raw_key,
                    .value = raw_value,
                });
                var extracted = try mapper.extractWrite(state.alloc, raw_key, raw_value);
                errdefer extracted.deinit(state.alloc);
                const next_last_store_key = try state.alloc.dupe(u8, key);
                errdefer state.alloc.free(next_last_store_key);
                try state.extracted.append(state.alloc, extracted);
                if (state.last_store_key) |last| state.alloc.free(last);
                state.last_store_key = next_last_store_key;
                if (state.writes.items.len >= state.limit) return .stop;
                return .@"continue";
            }
        };

        var state = ScanState{ .alloc = alloc, .limit = limit };
        errdefer state.deinitPartial();
        try self.core.store.scanWithContext(lower, "", .{ .lower_exclusive = lower_exclusive }, &state, ScanState.scanEntry);

        var next_lower: ?[]u8 = null;
        if (state.last_store_key) |last| {
            next_lower = try alloc.dupe(u8, last);
            alloc.free(last);
            state.last_store_key = null;
        }

        return .{
            .writes = try state.writes.toOwnedSlice(alloc),
            .extracted = try state.extracted.toOwnedSlice(alloc),
            .next_lower = next_lower,
        };
    }

    pub const GeneratedEnrichmentReplayAppendResult = struct {
        generated_ref_count: usize = 0,
        target_sequence: u64 = 0,
    };

    fn appendGeneratedEnrichmentsFromStoredDocs(
        self: *DB,
        alloc: Allocator,
        force_generated_artifact_names: []const []const u8,
        skip_terminally_covered: bool,
    ) !GeneratedEnrichmentReplayAppendResult {
        if (self.enrichment_runtime == null) return .{};

        const chunk_size: usize = 128;
        const initial_lower = try self.core.documentRangeLowerAlloc("");
        defer self.core.alloc.free(initial_lower);
        var lower = try alloc.dupe(u8, initial_lower);
        defer alloc.free(lower);
        var lower_exclusive = false;

        var generated_ref_count: usize = 0;
        var latest_sequence: u64 = 0;
        while (true) {
            var replay_batch = try self.collectStoredGeneratedReplayBatch(alloc, lower, lower_exclusive, chunk_size);
            defer replay_batch.deinit(alloc);
            if (replay_batch.writes.len == 0) break;

            var pending_batch = derived_types.DerivedBatch{};
            defer derived_types.deinitDerivedBatch(self.alloc, &pending_batch);
            try appendGeneratedEnrichments(self, &pending_batch, .{
                .writes = replay_batch.writes,
                .sync_level = .write,
            }, replay_batch.extracted, force_generated_artifact_names, skip_terminally_covered);
            if (pending_batch.generated_enrichment_refs.len != 0) {
                generated_ref_count += pending_batch.generated_enrichment_refs.len;
                const sequence = try appendDerivedBatchRecord(self, pending_batch);
                latest_sequence = @max(latest_sequence, sequence);
            }

            const next_lower = replay_batch.next_lower orelse break;
            replay_batch.next_lower = null;
            alloc.free(lower);
            lower = next_lower;
            lower_exclusive = true;
        }
        if (latest_sequence != 0) {
            self.executor.notifySequence(latest_sequence);
            if (self.enrichment_runtime) |runtime| runtime.notifySequence(latest_sequence);
            self.notifyResolverReplayRuntimes(latest_sequence);
        }
        return .{
            .generated_ref_count = generated_ref_count,
            .target_sequence = latest_sequence,
        };
    }

    pub fn replayGeneratedEnrichmentsFromStoredDocs(self: *DB, alloc: Allocator) !usize {
        return (try self.appendGeneratedEnrichmentsFromStoredDocs(alloc, &.{}, true)).generated_ref_count;
    }

    pub fn reprocessGeneratedEnrichmentFromStoredDocs(
        self: *DB,
        alloc: Allocator,
        artifact_name: ?[]const u8,
    ) !usize {
        return (try self.reprocessGeneratedEnrichmentFromStoredDocsWithProgress(alloc, artifact_name)).generated_ref_count;
    }

    pub fn reprocessGeneratedEnrichmentFromStoredDocsWithProgress(
        self: *DB,
        alloc: Allocator,
        artifact_name: ?[]const u8,
    ) !GeneratedEnrichmentReplayAppendResult {
        if (artifact_name) |name| {
            const force_artifacts = [_][]const u8{name};
            return try self.appendGeneratedEnrichmentsFromStoredDocs(alloc, &force_artifacts, false);
        }
        return try self.appendGeneratedEnrichmentsFromStoredDocs(alloc, &.{}, false);
    }

    fn waitForSyncLevel(self: *DB, sync_level: types.SyncLevel, sequence: u64, sync_targets: ManagedSyncTargets) !void {
        try self.waitForSyncLevelWithCancellation(sync_level, sequence, sync_targets, .none);
    }

    fn waitForSyncLevelWithCancellation(self: *DB, sync_level: types.SyncLevel, sequence: u64, sync_targets: ManagedSyncTargets, cancellation: types.CancellationToken) !void {
        const timeout_ms = if (self.enrichment_runtime) |runtime|
            runtime.syncWaitTimeoutMs()
        else
            default_visibility_wait_timeout_ms;
        const timeout_ns = std.math.mul(u64, timeout_ms, std.time.ns_per_ms) catch std.math.maxInt(u64);
        const deadline_ns = platform_time.monotonicNs() +| timeout_ns;
        const wait = derived_executor_mod.VisibilityWait{
            .cancellation = cancellation,
            .deadline_ns = deadline_ns,
        };
        switch (sync_level) {
            .propose, .write => try self.executor.failIfUnhealthy(),
            .enrichments => {
                try self.executor.failIfUnhealthy();
                try self.runEnrichmentUntilWithVisibilityDeadline(sequence, cancellation, deadline_ns);
            },
            .full_text => {
                try self.runDerivedUntilTargetsWithVisibilityWait(sequence, sync_targets.full_text_indexes, wait);
                try waitForManagedIndexesApplied(self, sequence, sync_targets.full_text_indexes);
            },
            .full_index => {
                try self.runMaintenanceUntilWithCancellation(sequence, sync_targets, cancellation, deadline_ns);
                if (self.text_merge_runtime == null) {
                    try wait.check();
                    try self.drainScheduledTextMerges();
                    try wait.check();
                }
            },
        }
    }

    fn generatedPrecomputeModeForSyncLevel(sync_level: types.SyncLevel) GeneratedPrecomputeMode {
        return switch (sync_level) {
            .enrichments, .full_index => .all,
            .propose, .write, .full_text => .none,
        };
    }

