    fn searchGraphWithSets(self: *DB, alloc: Allocator, req: types.SearchRequest, graph_query: graph_query_mod.GraphQuery, named_sets: []const NamedResultSet) !types.SearchResult {
        _ = req.index_name;

        if (graph_query.query_type == .pattern) {
            const named_query: types.NamedGraphQuery = .{
                .name = "__graph",
                .query = graph_query,
            };
            const graph_results = try alloc.alloc(types.GraphSearchResult, 1);
            errdefer alloc.free(graph_results);
            graph_results[0] = try self.executeSinglePatternQueryWithSets(alloc, req, &named_query, named_sets);
            return .{
                .alloc = alloc,
                .hits = &.{},
                .total_hits = graph_results[0].total_hits,
                .graph_results = graph_results,
            };
        }
        const predicate_aware = graphRequestRequiresAdmission(req, graph_query.params.node_filter);
        var admission = GraphNodeAdmissionCache.init(self, alloc, req, graph_query.index_name, graph_query.params.node_filter);
        defer admission.deinit();
        var execution = GraphPredicateExecutionContext{
            .db = self,
            .admission = &admission,
        };
        const raw = try db_query_graph.executeSearchGraphWithSets(alloc, req, graph_query, named_sets, .{
            .ctx = self,
            .graph_ctx = if (predicate_aware) &execution else null,
            .predicate_aware = predicate_aware,
            .execute_graph_query = if (predicate_aware)
                executeSearchGraphQueryWithAdmissionCallback
            else
                executeSearchGraphQueryCallback,
            .load_projected_document = loadProjectedSearchDocumentCallback,
            .resolve_doc_set_doc_ids = resolveDocSetDocIdsForGraphCallback,
            .lookup_doc_ordinal = lookupLiveDocOrdinalNoLockCallback,
            .filter_keys = filterGraphKeysCallback,
        });
        return try filterExpiredSearchResult(self, alloc, raw);
    }

    fn fuseNamedSets(self: *DB, alloc: Allocator, req: types.SearchRequest, named_sets: []const NamedResultSet) !types.SearchResult {
        const raw = try db_query_graph.fuseNamedSets(alloc, req, named_sets, .{
            .ctx = self,
            .load_projected_document = loadProjectedSearchDocumentCallback,
        });
        return try filterExpiredSearchResult(self, alloc, raw);
    }

    fn applyGraphExpandStrategy(self: *DB, alloc: Allocator, result: *types.SearchResult, strategy: ?graph_query_mod.ExpandStrategy) !void {
        _ = self;
        try db_query_graph.applyGraphExpandStrategy(alloc, result, strategy);
    }

    fn executeGraphQueryWithTargets(
        self: *DB,
        alloc: Allocator,
        graph_query: graph_query_mod.GraphQuery,
        start_key_refs: []const []const u8,
        target_keys: [][]u8,
    ) !graph_query_mod.GraphQueryResult {
        const entry = self.core.graphIndex(graph_query.index_name) orelse {
            try self.failIfIndexQuarantined(graph_query.index_name);
            return error.IndexNotFound;
        };
        if (entry.index.supportsAlgebraicSemiringTraversal()) {
            try self.proveGraphTraversalProgram(graph_query.index_name, target_keys.len > 0);
        }

        var resolved_query = graph_query;
        if (graph_query.target_nodes != null) {
            resolved_query.target_nodes = .{ .keys = try castOwnedKeysToConst(alloc, target_keys) };
        }
        defer if (graph_query.target_nodes != null) {
            switch (resolved_query.target_nodes.?) {
                .keys => |owned| alloc.free(owned),
                .result_ref => unreachable,
            }
        };

        var graph_engine = graph_query_mod.GraphQueryEngine{ .alloc = alloc };
        return try graph_engine.execute(&entry.index, resolved_query, start_key_refs);
    }

    fn executeGraphQueryWithAdmission(
        self: *DB,
        alloc: Allocator,
        graph_query: graph_query_mod.GraphQuery,
        start_key_refs: []const []const u8,
        target_keys: [][]u8,
        admission: NodeAdmission,
    ) !graph_query_mod.GraphQueryResult {
        const entry = self.core.graphIndex(graph_query.index_name) orelse {
            try self.failIfIndexQuarantined(graph_query.index_name);
            return error.IndexNotFound;
        };

        var resolved_query = graph_query;
        if (graph_query.target_nodes != null) {
            resolved_query.target_nodes = .{ .keys = try castOwnedKeysToConst(alloc, target_keys) };
        }
        defer if (graph_query.target_nodes != null) {
            switch (resolved_query.target_nodes.?) {
                .keys => |owned| alloc.free(owned),
                .result_ref => unreachable,
            }
        };

        var graph_engine = graph_query_mod.GraphQueryEngine{
            .alloc = alloc,
            .node_admission = admission,
        };
        return try graph_engine.execute(&entry.index, resolved_query, start_key_refs);
    }

    fn proveGraphTraversalProgram(self: *DB, index_name: []const u8, constrained_targets: bool) !void {
        const graph_access_path = self.core.index_manager.graphTraversalAccessPath(index_name) orelse return error.InvalidIndexConfig;
        var tensor_program = (try algebraic_mod.planner.planGraphTraversalTensorProgramAlloc(self.alloc, index_name, constrained_targets)) orelse return error.InvalidIndexConfig;
        defer tensor_program.deinit(self.alloc);
        if (tensor_program.access_paths.len != 1 or
            tensor_program.access_paths[0].layout != .graph_edges or
            !std.mem.eql(u8, tensor_program.access_paths[0].owner, index_name) or
            !std.mem.eql(algebraic_mod.ir.Dimension, tensor_program.access_paths[0].output_dims, graph_access_path.output_dims))
        {
            return error.InvalidIndexConfig;
        }
        if (!algebraic_mod.ir.graphTraversalProgramMatchesTarget(tensor_program.asProgram(), index_name, constrained_targets)) {
            return error.InvalidIndexConfig;
        }
    }
};

fn freeJsonValue(alloc: Allocator, value: *std.json.Value) void {
    db_query_projection.freeJsonValue(alloc, value);
}

fn putLeakyJsonStringField(alloc: Allocator, obj: *std.json.ObjectMap, key: []const u8, value: []const u8) !void {
    try obj.put(alloc, key, .{ .string = try alloc.dupe(u8, value) });
}

fn putLeakyJsonU64Field(alloc: Allocator, obj: *std.json.ObjectMap, key: []const u8, value: u64) !void {
    if (value > @as(u64, @intCast(std.math.maxInt(i64)))) return error.InvalidArgument;
    try obj.put(alloc, key, .{ .integer = @intCast(value) });
}

fn cloneJsonValue(alloc: Allocator, value: std.json.Value) !std.json.Value {
    return try db_query_projection.cloneJsonValue(alloc, value);
}

fn putOwnedValue(
    alloc: Allocator,
    obj: *std.json.ObjectMap,
    key: []const u8,
    value: std.json.Value,
) !void {
    try db_query_projection.putOwnedValue(alloc, obj, key, value);
}

fn loadChunkFieldValue(self: *DB, alloc: Allocator, doc_key: []const u8) !?std.json.Value {
    const prefix = try internal_keys.artifactTypePrefixAlloc(alloc, doc_key, "chunk");
    defer alloc.free(prefix);

    const artifacts = try self.core.scanStorePrefix(alloc, prefix);
    defer docstore_mod.DocStore.freeResults(alloc, artifacts);

    var chunks_obj = std.json.ObjectMap.empty;
    errdefer {
        var it = chunks_obj.iterator();
        while (it.next()) |entry| {
            alloc.free(entry.key_ptr.*);
            freeJsonValue(alloc, entry.value_ptr);
        }
        chunks_obj.deinit(alloc);
    }

    var chunk_count: usize = 0;
    for (artifacts) |entry| {
        if (!internal_keys.isChunkArtifactRecordKey(entry.key)) continue;

        var artifact_ref = (try decodeArtifactRefIfKnownAlloc(alloc, entry.key)) orelse continue;
        defer artifact_ref.deinit(alloc);
        if (artifact_ref.kind != .chunk or artifact_ref.chunk_id == null) continue;

        var parsed = try std.json.parseFromSlice(std.json.Value, alloc, entry.value, .{});
        defer parsed.deinit();
        var cloned = try cloneJsonValue(alloc, parsed.value);
        errdefer freeJsonValue(alloc, &cloned);
        try db_query_projection.normalizeChunkArtifactForQuery(alloc, &cloned);

        const chunk_name = artifact_ref.name;
        if (chunks_obj.getPtr(chunk_name)) |existing| {
            if (existing.* != .array) {
                freeJsonValue(alloc, existing);
                existing.* = .{ .array = std.json.Array.init(alloc) };
            }
            try existing.array.append(cloned);
        } else {
            var arr = std.json.Array.init(alloc);
            errdefer {
                var mutable = cloned;
                freeJsonValue(alloc, &mutable);
                arr.deinit();
            }
            try arr.append(cloned);
            try chunks_obj.put(alloc, try alloc.dupe(u8, chunk_name), .{ .array = arr });
        }

        chunk_count += 1;
    }

    if (chunk_count == 0) {
        var empty = std.json.Value{ .object = chunks_obj };
        freeJsonValue(alloc, &empty);
        return null;
    }
    return .{ .object = chunks_obj };
}

fn loadEmbeddingFieldValue(self: *DB, alloc: Allocator, doc_key: []const u8) !?std.json.Value {
    const prefix = try internal_keys.artifactTypePrefixAlloc(alloc, doc_key, "embedding");
    defer alloc.free(prefix);

    const artifacts = try self.core.scanStorePrefix(alloc, prefix);
    defer docstore_mod.DocStore.freeResults(alloc, artifacts);

    var embeddings_obj = std.json.ObjectMap.empty;
    errdefer {
        var it = embeddings_obj.iterator();
        while (it.next()) |entry| {
            alloc.free(entry.key_ptr.*);
            freeJsonValue(alloc, entry.value_ptr);
        }
        embeddings_obj.deinit(alloc);
    }

    var embedding_count: usize = 0;
    for (artifacts) |entry| {
        if (!internal_keys.isInternalUserKey(entry.key)) continue;

        var artifact_ref = (try decodeArtifactRefIfKnownAlloc(alloc, entry.key)) orelse continue;
        defer artifact_ref.deinit(alloc);
        if (artifact_ref.kind != .embedding or artifact_ref.source != null) continue;

        var vector = enrichment_artifact_codec.decodeDenseEmbeddingJsonVectorAlloc(alloc, entry.value) catch continue;
        errdefer freeJsonValue(alloc, &vector);
        try putOwnedValue(alloc, &embeddings_obj, artifact_ref.name, vector);
        embedding_count += 1;
    }

    if (embedding_count == 0) {
        var empty = std.json.Value{ .object = embeddings_obj };
        freeJsonValue(alloc, &empty);
        return null;
    }
    return .{ .object = embeddings_obj };
}

fn loadArtifactFieldValue(self: *DB, alloc: Allocator, doc_key: []const u8) !?std.json.Value {
    const prefix = try internal_keys.artifactRootPrefixAlloc(alloc, doc_key);
    defer alloc.free(prefix);

    const artifacts = try self.core.scanStorePrefix(alloc, prefix);
    defer docstore_mod.DocStore.freeResults(alloc, artifacts);

    var artifacts_obj = std.json.ObjectMap.empty;
    errdefer {
        var it = artifacts_obj.iterator();
        while (it.next()) |entry| {
            alloc.free(entry.key_ptr.*);
            freeJsonValue(alloc, entry.value_ptr);
        }
        artifacts_obj.deinit(alloc);
    }

    var artifact_count: usize = 0;
    for (artifacts) |entry| {
        var artifact_ref = (try decodeArtifactRefIfKnownAlloc(alloc, entry.key)) orelse continue;
        defer artifact_ref.deinit(alloc);

        var artifact_value = try artifactProjectionValue(self, alloc, artifact_ref, entry.value);
        errdefer freeJsonValue(alloc, &artifact_value);

        try appendArtifactProjectionValue(alloc, &artifacts_obj, artifact_ref.name, artifact_ref.kind, artifact_value);
        artifact_count += 1;
    }

    if (artifact_count == 0) {
        var empty = std.json.Value{ .object = artifacts_obj };
        freeJsonValue(alloc, &empty);
        return null;
    }
    return .{ .object = artifacts_obj };
}

fn artifactProjectionValue(self: *DB, alloc: Allocator, artifact_ref: types.ArtifactRef, raw: []const u8) !std.json.Value {
    var obj = std.json.ObjectMap.empty;
    errdefer {
        var value = std.json.Value{ .object = obj };
        freeJsonValue(alloc, &value);
    }

    {
        const artifact_id = try artifact_ids.artifactPublicIdAlloc(alloc, artifact_ref);
        errdefer alloc.free(artifact_id);
        try putOwnedValue(alloc, &obj, "artifact_id", .{ .string = artifact_id });
    }

    {
        var ref_value = try artifactRefJsonValue(alloc, artifact_ref);
        errdefer freeJsonValue(alloc, &ref_value);
        try putOwnedValue(alloc, &obj, "artifact_ref", ref_value);
    }

    try putOwnedValue(alloc, &obj, "kind", .{ .string = try alloc.dupe(u8, artifactKindText(artifact_ref.kind)) });
    const content_type = try artifactContentTypeAlloc(self, alloc, artifact_ref.kind, artifact_ref.name);
    try putOwnedValue(alloc, &obj, "content_type", .{ .string = content_type });
    try putOwnedValue(alloc, &obj, "status", .{ .string = try alloc.dupe(u8, "ready") });

    if (enrichment_artifact_codec.sourceHash(raw) catch null) |source_hash| {
        try putOwnedValue(alloc, &obj, "source_hash", .{ .string = try std.fmt.allocPrint(alloc, "xxh64:{x}", .{source_hash}) });
    }

    switch (artifact_ref.kind) {
        .chunk => {
            var parsed = std.json.parseFromSlice(std.json.Value, alloc, raw, .{}) catch null;
            if (parsed) |*owned| {
                defer owned.deinit();
                var cloned = try cloneJsonValue(alloc, owned.value);
                errdefer freeJsonValue(alloc, &cloned);
                try db_query_projection.normalizeChunkArtifactForQuery(alloc, &cloned);
                try putOwnedValue(alloc, &obj, "value", cloned);
            } else {
                try putOwnedValue(alloc, &obj, "value", .{ .string = try alloc.dupe(u8, raw) });
            }
        },
        .asset => {
            var value = try assetPayloadJsonValue(alloc, content_type, raw);
            errdefer freeJsonValue(alloc, &value);
            hierarchy_navigation.stripPublicInternalFieldsValue(alloc, &value);
            try putOwnedValue(alloc, &obj, "value", value);
        },
        .embedding => {
            if (enrichment_artifact_codec.decodeDenseEmbeddingDims(raw) catch null) |dims| {
                try putOwnedValue(alloc, &obj, "dims", .{ .integer = @intCast(dims) });
            }
            try putOwnedValue(alloc, &obj, "value", .null);
        },
    }

    return .{ .object = obj };
}

fn appendArtifactProjectionValue(
    alloc: Allocator,
    artifacts_obj: *std.json.ObjectMap,
    artifact_name: []const u8,
    artifact_kind: types.ArtifactKind,
    artifact_value: std.json.Value,
) !void {
    if (artifacts_obj.getPtr(artifact_name)) |existing| {
        if (existing.* == .object) {
            if (existing.object.getPtr("items")) |items| {
                if (items.* == .array) {
                    try items.array.append(artifact_value);
                    return;
                }
            }
        }

        var first = try cloneJsonValue(alloc, existing.*);
        var first_moved = false;
        errdefer if (!first_moved) freeJsonValue(alloc, &first);
        var items = std.json.Array.init(alloc);
        errdefer {
            for (items.items) |*item| freeJsonValue(alloc, item);
            items.deinit();
        }
        try items.append(first);
        first_moved = true;
        try items.append(artifact_value);

        var grouped = std.json.ObjectMap.empty;
        errdefer {
            var value = std.json.Value{ .object = grouped };
            freeJsonValue(alloc, &value);
        }
        try putOwnedValue(alloc, &grouped, "kind", .{ .string = try alloc.dupe(u8, artifactSetKindText(artifact_kind)) });
        try putOwnedValue(alloc, &grouped, "status", .{ .string = try alloc.dupe(u8, "ready") });
        try putOwnedValue(alloc, &grouped, "items", .{ .array = items });

        freeJsonValue(alloc, existing);
        existing.* = .{ .object = grouped };
        return;
    }

    try artifacts_obj.put(alloc, try alloc.dupe(u8, artifact_name), artifact_value);
}

fn artifactRefJsonValue(alloc: Allocator, artifact_ref: types.ArtifactRef) !std.json.Value {
    var obj = std.json.ObjectMap.empty;
    errdefer {
        var value = std.json.Value{ .object = obj };
        freeJsonValue(alloc, &value);
    }
    try putOwnedValue(alloc, &obj, "document_id", .{ .string = try alloc.dupe(u8, artifact_ref.document_id) });
    try putOwnedValue(alloc, &obj, "name", .{ .string = try alloc.dupe(u8, artifact_ref.name) });
    try putOwnedValue(alloc, &obj, "kind", .{ .string = try alloc.dupe(u8, artifactKindText(artifact_ref.kind)) });
    if (artifact_ref.chunk_id) |chunk_id| {
        try putOwnedValue(alloc, &obj, "chunk_id", .{ .integer = @intCast(chunk_id) });
    }
    if (artifact_ref.source) |source| {
        var source_obj = std.json.ObjectMap.empty;
        errdefer {
            var value = std.json.Value{ .object = source_obj };
            freeJsonValue(alloc, &value);
        }
        try putOwnedValue(alloc, &source_obj, "kind", .{ .string = try alloc.dupe(u8, artifactKindText(source.kind)) });
        try putOwnedValue(alloc, &source_obj, "name", .{ .string = try alloc.dupe(u8, source.name) });
        if (source.chunk_id) |chunk_id| {
            try putOwnedValue(alloc, &source_obj, "chunk_id", .{ .integer = @intCast(chunk_id) });
        }
        try putOwnedValue(alloc, &obj, "source", .{ .object = source_obj });
    }
    return .{ .object = obj };
}

fn artifactKindText(kind: types.ArtifactKind) []const u8 {
    return switch (kind) {
        .chunk => "chunk",
        .asset => "asset",
        .embedding => "embedding",
    };
}

fn artifactSetKindText(kind: types.ArtifactKind) []const u8 {
    return switch (kind) {
        .chunk => "chunk_set",
        .asset => "asset_set",
        .embedding => "embedding_set",
    };
}

fn artifactContentType(kind: types.ArtifactKind) []const u8 {
    return switch (kind) {
        .chunk => "application/json",
        .asset => "application/octet-stream",
        .embedding => "application/vnd.antfly.embedding+binary",
    };
}

fn artifactContentTypeAlloc(self: *DB, alloc: Allocator, kind: types.ArtifactKind, artifact_name: []const u8) ![]u8 {
    if (kind == .asset) {
        if (self.core.index_manager.getEnrichment(.asset, artifact_name)) |cfg| {
            if (cfg.content_type.len > 0) return try alloc.dupe(u8, cfg.content_type);
            return try alloc.dupe(u8, "text/plain");
        }
    }
    return try alloc.dupe(u8, artifactContentType(kind));
}

fn assetPayloadJsonValue(alloc: Allocator, content_type: []const u8, raw: []const u8) !std.json.Value {
    if (assetContentTypeIsJson(content_type)) {
        var parsed = try std.json.parseFromSlice(std.json.Value, alloc, raw, .{ .allocate = .alloc_always });
        defer parsed.deinit();
        return try cloneJsonValue(alloc, parsed.value);
    }
    return .{ .string = try alloc.dupe(u8, raw) };
}

fn assetContentTypeIsJson(content_type: []const u8) bool {
    const media_type = std.mem.trim(u8, if (std.mem.indexOfScalar(u8, content_type, ';')) |semi| content_type[0..semi] else content_type, &std.ascii.whitespace);
    return std.mem.eql(u8, media_type, "application/json") or std.mem.endsWith(u8, media_type, "+json");
}

fn projectLookupStoredBytes(self: *DB, alloc: Allocator, doc_key: []const u8, raw: []const u8, opts: types.LookupOptions) ![]u8 {
    return try db_query_projection.projectLookupStoredBytes(alloc, doc_key, raw, opts, .{
        .ctx = self,
        .load_chunks = loadChunkFieldValueCallback,
        .load_embeddings = loadEmbeddingFieldValueCallback,
        .load_artifacts = loadArtifactFieldValueCallback,
    });
}

fn projectStoredBytesForSearch(self: *DB, alloc: Allocator, req: types.SearchRequest, doc_key: []const u8, raw: []const u8) ![]u8 {
    if (req.defer_stored_projection and db_query_projection.shouldProjectSearchStored(req)) {
        return try alloc.dupe(u8, raw);
    }
    return try db_query_projection.projectStoredBytesForSearch(alloc, req, doc_key, raw, .{
        .ctx = self,
        .load_chunks = loadChunkFieldValueCallback,
        .load_embeddings = loadEmbeddingFieldValueCallback,
        .load_artifacts = loadArtifactFieldValueCallback,
    });
}

fn projectOwnedStoredBytesForSearch(self: *DB, alloc: Allocator, req: types.SearchRequest, doc_key: []const u8, raw: []u8) ![]u8 {
    if (req.defer_stored_projection and db_query_projection.shouldProjectSearchStored(req)) {
        return raw;
    }
    return try db_query_projection.projectOwnedStoredBytesForSearch(alloc, req, doc_key, raw, .{
        .ctx = self,
        .load_chunks = loadChunkFieldValueCallback,
        .load_embeddings = loadEmbeddingFieldValueCallback,
        .load_artifacts = loadArtifactFieldValueCallback,
    });
}

fn loadStoredSearchDocumentsMany(self: *DB, alloc: Allocator, keys: []const []const u8) ![]?[]u8 {
    const bench_profile = benchQueryProfileEnabled();
    const total_start_ns = if (bench_profile) platform_time.monotonicNs() else 0;
    var key_ns: u64 = 0;
    var sort_ns: u64 = 0;
    var txn_ns: u64 = 0;
    var get_many_ns: u64 = 0;
    var dupe_ns: u64 = 0;
    const PendingStoredSearchLoad = struct {
        original_index: usize,
        store_key: []u8,
    };

    const loaded = try alloc.alloc(?[]u8, keys.len);
    errdefer alloc.free(loaded);
    @memset(loaded, null);
    if (keys.len == 0) return loaded;

    var pending = std.ArrayListUnmanaged(PendingStoredSearchLoad).empty;
    defer {
        for (pending.items) |item| alloc.free(item.store_key);
        pending.deinit(alloc);
    }

    errdefer freeOptionalOwnedBytes(alloc, loaded);

    const key_start_ns = if (bench_profile) platform_time.monotonicNs() else 0;
    for (keys, 0..) |key, i| {
        try pending.append(alloc, .{
            .original_index = i,
            .store_key = try encodeStoreLookupKeyAlloc(alloc, key),
        });
    }
    if (bench_profile) key_ns = platform_time.monotonicNs() - key_start_ns;

    const sort_start_ns = if (bench_profile) platform_time.monotonicNs() else 0;
    std.mem.sort(PendingStoredSearchLoad, pending.items, {}, struct {
        fn lessThan(_: void, lhs: PendingStoredSearchLoad, rhs: PendingStoredSearchLoad) bool {
            return std.mem.order(u8, lhs.store_key, rhs.store_key) == .lt;
        }
    }.lessThan);
    if (bench_profile) sort_ns = platform_time.monotonicNs() - sort_start_ns;

    const read_keys = try alloc.alloc([]const u8, pending.items.len);
    defer alloc.free(read_keys);
    const read_values = try alloc.alloc(?[]const u8, pending.items.len);
    defer alloc.free(read_values);
    @memset(read_values, null);

    for (pending.items, 0..) |item, i| read_keys[i] = item.store_key;

    const txn_start_ns = if (bench_profile) platform_time.monotonicNs() else 0;
    var txn = try self.core.store.beginProbeTxn();
    defer txn.abort();
    if (bench_profile) txn_ns = platform_time.monotonicNs() - txn_start_ns;
    const get_many_start_ns = if (bench_profile) platform_time.monotonicNs() else 0;
    try txn.getManySorted(read_keys, read_values);
    if (bench_profile) get_many_ns = platform_time.monotonicNs() - get_many_start_ns;

    const dupe_start_ns = if (bench_profile) platform_time.monotonicNs() else 0;
    for (pending.items, 0..) |item, i| {
        const value = read_values[i] orelse continue;
        loaded[item.original_index] = try alloc.dupe(u8, value);
    }
    if (bench_profile) dupe_ns = platform_time.monotonicNs() - dupe_start_ns;
    if (bench_profile) {
        std.log.info(
            "antfly_bench_stored_many total_us={d} key_us={d} sort_us={d} txn_us={d} get_many_us={d} dupe_us={d} keys={d}",
            .{ (platform_time.monotonicNs() - total_start_ns) / 1000, key_ns / 1000, sort_ns / 1000, txn_ns / 1000, get_many_ns / 1000, dupe_ns / 1000, keys.len },
        );
    }
    return loaded;
}

fn freeOptionalOwnedBytes(alloc: Allocator, values: []?[]u8) void {
    for (values) |value| {
        if (value) |bytes| alloc.free(bytes);
    }
    alloc.free(values);
}

fn loadChunkFieldValueCallback(
    ctx: ?*anyopaque,
    alloc: Allocator,
    doc_key: []const u8,
) anyerror!?std.json.Value {
    const self: *DB = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
    return try loadChunkFieldValue(self, alloc, doc_key);
}

fn loadEmbeddingFieldValueCallback(
    ctx: ?*anyopaque,
    alloc: Allocator,
    doc_key: []const u8,
) anyerror!?std.json.Value {
    const self: *DB = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
    return try loadEmbeddingFieldValue(self, alloc, doc_key);
}

fn loadArtifactFieldValueCallback(
    ctx: ?*anyopaque,
    alloc: Allocator,
    doc_key: []const u8,
) anyerror!?std.json.Value {
    const self: *DB = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
    return try loadArtifactFieldValue(self, alloc, doc_key);
}

fn dupeConstDocIdsAlloc(alloc: Allocator, doc_ids: []const []const u8) ![]const []const u8 {
    const out = try alloc.alloc([]const u8, doc_ids.len);
    var initialized: usize = 0;
    errdefer {
        for (out[0..initialized]) |doc_id| alloc.free(@constCast(doc_id));
        alloc.free(out);
    }
    for (doc_ids, 0..) |doc_id, i| {
        out[i] = try alloc.dupe(u8, doc_id);
        initialized += 1;
    }
    return out;
}

fn freeConstDocIds(alloc: Allocator, doc_ids: []const []const u8) void {
    for (doc_ids) |doc_id| alloc.free(@constCast(doc_id));
    alloc.free(doc_ids);
}

fn docIdsForOrdinalsTxnAlloc(alloc: Allocator, txn: anytype, ordinals: []const doc_set.DocOrdinal) ![]const []const u8 {
    return (try docIdsForOrdinalsAtGenerationTxnAlloc(alloc, txn, ordinals, null)) orelse error.InvalidDocIdentity;
}

fn docIdsForOrdinalsAtGenerationTxnAlloc(
    alloc: Allocator,
    txn: anytype,
    ordinals: []const doc_set.DocOrdinal,
    generation: ?u64,
) !?[]const []const u8 {
    const out = try alloc.alloc([]const u8, ordinals.len);
    var initialized: usize = 0;
    errdefer {
        for (out[0..initialized]) |doc_id| alloc.free(@constCast(doc_id));
        alloc.free(out);
    }
    for (ordinals, 0..) |ordinal, i| {
        if (try doc_identity.lookupStateTxn(txn, ordinal)) |state| {
            const visible = if (generation) |at| state.isVisibleAt(at) else state.isLive();
            if (!visible) {
                for (out[0..initialized]) |doc_id| alloc.free(@constCast(doc_id));
                alloc.free(out);
                return null;
            }
        } else {
            for (out[0..initialized]) |doc_id| alloc.free(@constCast(doc_id));
            alloc.free(out);
            return null;
        }
        out[i] = (try doc_identity.lookupDocIdTxn(alloc, txn, ordinal)) orelse return error.InvalidDocIdentity;
        initialized += 1;
    }
    return out;
}

fn resolvedDocSetFromSearchHitOrdinalsAlloc(alloc: Allocator, hits: []const types.SearchHit) !?doc_set.ResolvedDocSet {
    const ordinals = try alloc.alloc(doc_set.DocOrdinal, hits.len);
    defer if (ordinals.len > 0) alloc.free(ordinals);

    for (hits, 0..) |hit, i| {
        ordinals[i] = hit.doc_ordinal orelse return null;
    }
    return try doc_set.fromOrdinalsAlloc(alloc, ordinals);
}

test "resolved doc set from search hits uses complete hit ordinals" {
    const alloc = std.testing.allocator;

    const hits = [_]types.SearchHit{
        .{ .id = @constCast("doc:a"), .doc_ordinal = 3 },
        .{ .id = @constCast("doc:b"), .doc_ordinal = 1 },
    };
    var resolved = (try resolvedDocSetFromSearchHitOrdinalsAlloc(alloc, &hits)) orelse return error.TestUnexpectedResult;
    defer resolved.deinit(alloc);
    try std.testing.expect(resolved.containsOrdinal(1));
    try std.testing.expect(resolved.containsOrdinal(3));
    try std.testing.expect(!resolved.containsOrdinal(2));

    const mixed = [_]types.SearchHit{
        .{ .id = @constCast("doc:a"), .doc_ordinal = 1 },
        .{ .id = @constCast("doc:b") },
    };
    try std.testing.expect((try resolvedDocSetFromSearchHitOrdinalsAlloc(alloc, &mixed)) == null);
}

fn isMetadataKey(key: []const u8) bool {
    return std.mem.startsWith(u8, key, "\x00\x00__metadata__:") or
        isSplitMetadataKey(key) or
        internal_keys.isTtlKey(key);
}

fn isPrimaryDocumentStoreKey(key: []const u8) bool {
    return internal_keys.isPrimaryDocumentKey(key);
}

fn skipNonPrimaryMedianKey(key: []const u8) bool {
    return !isPrimaryDocumentStoreKey(key);
}

fn encodeStoreLookupKeyAlloc(alloc: Allocator, key: []const u8) ![]u8 {
    if (internal_keys.isInternalUserKey(key) or std.mem.startsWith(u8, key, "\x00\x00__metadata__:") or isSplitMetadataKey(key)) {
        return try alloc.dupe(u8, key);
    }
    return try internal_keys.documentKeyAlloc(alloc, key);
}

fn documentRangeLowerAlloc(alloc: Allocator, raw_key: []const u8) ![]u8 {
    return try internal_keys.documentRangeLowerAlloc(alloc, raw_key);
}

fn documentRangeUpperAlloc(alloc: Allocator, raw_key: []const u8) !?[]u8 {
    return try internal_keys.documentRangeUpperAlloc(alloc, raw_key);
}

fn shouldAppendSplitDelta(self: *DB) bool {
    const state = self.core.splitState() orelse return false;
    return state.phase == .splitting;
}

fn shouldAppendSplitDeltaForContext(ctx: *const BatchExecutionContext) bool {
    const state = ctx.shard_manager.getSplitState() orelse return false;
    return state.phase == .splitting;
}

fn splitShadowRequiresMaterializedDerivedBatch(self: *DB) bool {
    if (self.shadow == null) return false;
    const state = self.core.splitState() orelse return false;
    return state.phase == .splitting;
}

fn resolveGraphSelector(alloc: Allocator, selector: graph_query_mod.NodeSelector, base_hits: ?[]const types.SearchHit) ![][]u8 {
    return try db_query_graph.resolveGraphSelector(alloc, selector, base_hits);
}

fn freeOwnedKeySlice(alloc: Allocator, keys: [][]u8) void {
    for (keys) |key| alloc.free(key);
    alloc.free(keys);
}

fn decodeArtifactRefIfKnownAlloc(alloc: Allocator, key: []const u8) !?types.ArtifactRef {
    return artifact_ids.decodeArtifactRefAlloc(alloc, key) catch |err| switch (err) {
        error.InvalidInternalUserKey => null,
        else => return err,
    };
}

fn buildOverwrittenDocKeys(
    alloc: Allocator,
    writes: []const types.BatchWrite,
    overwritten_flags: []const bool,
) ![]const []const u8 {
    var keys = std.ArrayListUnmanaged([]const u8).empty;
    errdefer {
        for (keys.items) |key| alloc.free(@constCast(key));
        keys.deinit(alloc);
    }

    for (writes, 0..) |write, i| {
        if (!overwritten_flags[i]) continue;
        try keys.append(alloc, try alloc.dupe(u8, write.key));
    }

    return try keys.toOwnedSlice(alloc);
}

fn appendUniqueReplayRecordKeyWithSet(
    alloc: Allocator,
    list: *std.ArrayListUnmanaged([]const u8),
    seen: *std.StringHashMapUnmanaged(void),
    key: []const u8,
) !void {
    if (key.len == 0) return;
    if (seen.contains(key)) return;
    const owned = try alloc.dupe(u8, key);
    errdefer alloc.free(owned);
    try seen.put(alloc, owned, {});
    errdefer _ = seen.remove(owned);
    try list.append(alloc, owned);
}

fn appendUniqueReplayRecordHint(
    alloc: Allocator,
    list: *std.ArrayListUnmanaged(change_journal_mod.TargetHint),
    hint: change_journal_mod.TargetHint,
) !void {
    for (list.items) |existing| {
        if (existing == hint) return;
    }
    try list.append(alloc, hint);
}

fn encodeThinReplayRecordPayload(
    alloc: Allocator,
    req: types.BatchRequest,
    extracted: []const mapper.ExtractedWrite,
    deleted_artifact_keys: []const []u8,
    changed_artifact_keys: []const []u8,
    overwritten_flags: []const bool,
    derived_changed_flags: []const bool,
    sequence: u64,
    include_generated_enrichment_hint: bool,
) ![]u8 {
    if (derived_changed_flags.len != req.writes.len) return error.InvalidArgument;
    var changed_doc_keys = std.ArrayListUnmanaged([]const u8).empty;
    var changed_doc_key_set = std.StringHashMapUnmanaged(void).empty;
    errdefer {
        for (changed_doc_keys.items) |key| alloc.free(@constCast(key));
        changed_doc_keys.deinit(alloc);
    }
    var deleted_doc_keys = std.ArrayListUnmanaged([]const u8).empty;
    var deleted_doc_key_set = std.StringHashMapUnmanaged(void).empty;
    errdefer {
        for (deleted_doc_keys.items) |key| alloc.free(@constCast(key));
        deleted_doc_keys.deinit(alloc);
    }
    var overwritten_doc_keys = std.ArrayListUnmanaged([]const u8).empty;
    var overwritten_doc_key_set = std.StringHashMapUnmanaged(void).empty;
    errdefer {
        for (overwritten_doc_keys.items) |key| alloc.free(@constCast(key));
        overwritten_doc_keys.deinit(alloc);
    }
    var thin_changed_artifact_keys = std.ArrayListUnmanaged([]const u8).empty;
    var thin_changed_artifact_key_set = std.StringHashMapUnmanaged(void).empty;
    errdefer {
        for (thin_changed_artifact_keys.items) |key| alloc.free(@constCast(key));
        thin_changed_artifact_keys.deinit(alloc);
    }
    var target_hints = std.ArrayListUnmanaged(change_journal_mod.TargetHint).empty;
    errdefer target_hints.deinit(alloc);
    defer {
        changed_doc_key_set.deinit(alloc);
        deleted_doc_key_set.deinit(alloc);
        overwritten_doc_key_set.deinit(alloc);
        thin_changed_artifact_key_set.deinit(alloc);
    }

    var saw_overwritten = false;

    for (req.writes, 0..) |write, i| {
        if (!derived_changed_flags[i]) continue;
        const extracted_write = extracted[i];
        if (extracted_write.cleaned_value != null or include_generated_enrichment_hint) {
            try appendUniqueReplayRecordKeyWithSet(alloc, &changed_doc_keys, &changed_doc_key_set, write.key);
            if (extracted_write.cleaned_value != null) {
                try appendUniqueReplayRecordHint(alloc, &target_hints, .full_text);
                try appendUniqueReplayRecordHint(alloc, &target_hints, .algebraic);
            }
            if (include_generated_enrichment_hint) {
                try appendUniqueReplayRecordHint(alloc, &target_hints, .enrichment);
            }
        }

        for (extracted_write.dense_embeddings) |embedding| {
            if (embedding.artifact_key) |artifact_key| try appendUniqueReplayRecordKeyWithSet(alloc, &thin_changed_artifact_keys, &thin_changed_artifact_key_set, artifact_key);
            try appendUniqueReplayRecordHint(alloc, &target_hints, .dense_vector);
        }
        for (extracted_write.sparse_embeddings) |embedding| {
            if (embedding.artifact_key) |artifact_key| try appendUniqueReplayRecordKeyWithSet(alloc, &thin_changed_artifact_keys, &thin_changed_artifact_key_set, artifact_key);
            try appendUniqueReplayRecordHint(alloc, &target_hints, .sparse_vector);
        }
        if (extracted_write.mentioned_graph_indexes.len > 0 or extracted_write.graph_writes.len > 0) {
            try appendUniqueReplayRecordKeyWithSet(alloc, &changed_doc_keys, &changed_doc_key_set, write.key);
            try appendUniqueReplayRecordHint(alloc, &target_hints, .graph);
        }
        if (overwritten_flags[i] and extracted_write.cleaned_value != null) {
            try appendUniqueReplayRecordKeyWithSet(alloc, &overwritten_doc_keys, &overwritten_doc_key_set, write.key);
            saw_overwritten = true;
        }
    }

    if (saw_overwritten) {
        try appendUniqueReplayRecordHint(alloc, &target_hints, .full_text);
        try appendUniqueReplayRecordHint(alloc, &target_hints, .dense_vector);
        try appendUniqueReplayRecordHint(alloc, &target_hints, .sparse_vector);
        try appendUniqueReplayRecordHint(alloc, &target_hints, .algebraic);
    }

    for (changed_artifact_keys) |key| {
        try appendUniqueReplayRecordKeyWithSet(alloc, &thin_changed_artifact_keys, &thin_changed_artifact_key_set, key);
        if (internal_keys.isChunkArtifactRecordKey(key)) try appendUniqueReplayRecordHint(alloc, &target_hints, .full_text);
        if (internal_keys.isGraphEdgeArtifactKey(key) or internal_keys.isAssetArtifactKey(key) or internal_keys.isChunkArtifactRecordKey(key)) try appendUniqueReplayRecordHint(alloc, &target_hints, .graph);
        if (internal_keys.isAssetArtifactKey(key)) {
            try appendUniqueReplayRecordHint(alloc, &target_hints, .resolution);
        }
    }

    for (req.graph_writes) |write| {
        try appendUniqueReplayRecordKeyWithSet(alloc, &changed_doc_keys, &changed_doc_key_set, write.source);
        const artifact_key = try internal_keys.graphEdgeArtifactKeyAlloc(alloc, write.source, write.index_name, write.edge_type, write.target);
        defer alloc.free(artifact_key);
        try appendUniqueReplayRecordKeyWithSet(alloc, &thin_changed_artifact_keys, &thin_changed_artifact_key_set, artifact_key);
        try appendUniqueReplayRecordHint(alloc, &target_hints, .graph);
    }
    for (req.graph_deletes) |delete| {
        try appendUniqueReplayRecordKeyWithSet(alloc, &deleted_doc_keys, &deleted_doc_key_set, delete.source);
        const artifact_key = try internal_keys.graphEdgeArtifactKeyAlloc(alloc, delete.source, delete.index_name, delete.edge_type, delete.target);
        defer alloc.free(artifact_key);
        try appendUniqueReplayRecordKeyWithSet(alloc, &thin_changed_artifact_keys, &thin_changed_artifact_key_set, artifact_key);
        try appendUniqueReplayRecordHint(alloc, &target_hints, .graph);
    }

    for (req.deletes) |key| {
        try appendUniqueReplayRecordKeyWithSet(alloc, &deleted_doc_keys, &deleted_doc_key_set, key);
        try appendUniqueReplayRecordHint(alloc, &target_hints, .full_text);
        try appendUniqueReplayRecordHint(alloc, &target_hints, .dense_vector);
        try appendUniqueReplayRecordHint(alloc, &target_hints, .sparse_vector);
        try appendUniqueReplayRecordHint(alloc, &target_hints, .algebraic);
        try appendUniqueReplayRecordHint(alloc, &target_hints, .graph);
    }
    for (deleted_artifact_keys) |key| {
        try appendUniqueReplayRecordKeyWithSet(alloc, &deleted_doc_keys, &deleted_doc_key_set, key);
        try appendUniqueReplayRecordHint(alloc, &target_hints, .full_text);
        try appendUniqueReplayRecordHint(alloc, &target_hints, .dense_vector);
        try appendUniqueReplayRecordHint(alloc, &target_hints, .sparse_vector);
        try appendUniqueReplayRecordHint(alloc, &target_hints, .algebraic);
        try appendUniqueReplayRecordHint(alloc, &target_hints, .graph);
        if (internal_keys.isAssetArtifactKey(key) or internal_keys.isChunkArtifactRecordKey(key) or internal_keys.isGraphEdgeArtifactKey(key)) {
            try appendUniqueReplayRecordKeyWithSet(alloc, &thin_changed_artifact_keys, &thin_changed_artifact_key_set, key);
            if (internal_keys.isChunkArtifactRecordKey(key)) try appendUniqueReplayRecordHint(alloc, &target_hints, .full_text);
            try appendUniqueReplayRecordHint(alloc, &target_hints, .graph);
            if (internal_keys.isAssetArtifactKey(key)) try appendUniqueReplayRecordHint(alloc, &target_hints, .resolution);
        }
    }

    var record: change_journal_mod.Record = .{
        .sequence = sequence,
        .changed_doc_keys = try changed_doc_keys.toOwnedSlice(alloc),
        .deleted_doc_keys = try deleted_doc_keys.toOwnedSlice(alloc),
        .overwritten_doc_keys = try overwritten_doc_keys.toOwnedSlice(alloc),
        .changed_artifact_keys = try thin_changed_artifact_keys.toOwnedSlice(alloc),
        .target_hints = try target_hints.toOwnedSlice(alloc),
    };
    defer change_journal_mod.deinitRecord(alloc, &record);
    return try change_journal_mod.encodeRecord(alloc, record);
}

fn appendUniqueOwnedKey(alloc: Allocator, list: *std.ArrayListUnmanaged([]u8), key: []const u8) !void {
    for (list.items) |existing| {
        if (std.mem.eql(u8, existing, key)) return;
    }
    try list.append(alloc, try alloc.dupe(u8, key));
}

fn containsName(names: []const []const u8, name: []const u8) bool {
    for (names) |existing| {
        if (std.mem.eql(u8, existing, name)) return true;
    }
    return false;
}

fn strippedStoredDocumentValueAlloc(
    alloc: Allocator,
    cleaned: []const u8,
    vector_store_field_names: []const []const u8,
    owned_values: *std.ArrayListUnmanaged([]u8),
) ![]const u8 {
    if (vector_store_field_names.len == 0) return cleaned;
    const stripped = (try mapper.stripTopLevelFieldsAlloc(alloc, cleaned, vector_store_field_names)) orelse try alloc.dupe(u8, "{}");
    errdefer alloc.free(stripped);
    try owned_values.append(alloc, stripped);
    return stripped;
}

fn containsOwnedKey(list: []const []u8, key: []const u8) bool {
    for (list) |existing| {
        if (std.mem.eql(u8, existing, key)) return true;
    }
    return false;
}

fn containsDeleteKey(list: []const []const u8, key: []const u8) bool {
    for (list) |existing| {
        if (std.mem.eql(u8, existing, key)) return true;
    }
    return false;
}

fn appendResolutionHandoffDeleteKey(
    alloc: Allocator,
    deletes: *std.ArrayListUnmanaged([]const u8),
    resolution_key: []const u8,
) !void {
    const handoff_key = try resolution_handoff.keyAlloc(alloc, resolution_key);
    errdefer alloc.free(handoff_key);
    if (containsDeleteKey(deletes.items, handoff_key)) {
        alloc.free(handoff_key);
        return;
    }
    try deletes.append(alloc, handoff_key);
}

fn overwriteProbeLessThan(_: void, lhs: OverwriteProbeEntry, rhs: OverwriteProbeEntry) bool {
    return std.mem.order(u8, lhs.key, rhs.key) == .lt;
}

fn extractStringField(alloc: Allocator, doc_value: []const u8, field_name: []const u8) !?[]u8 {
    const parsed = try std.json.parseFromSlice(std.json.Value, alloc, doc_value, .{});
    defer parsed.deinit();
    if (parsed.value != .object) return null;
    const field = parsed.value.object.get(field_name) orelse return null;
    if (field != .string) return null;
    return try alloc.dupe(u8, field.string);
}

fn appendGraphFieldTargets(
    alloc: Allocator,
    targets: *std.ArrayListUnmanaged([]u8),
    root: std.json.ObjectMap,
    field_name: []const u8,
) !void {
    const field = root.get(field_name) orelse return;
    switch (field) {
        .string => try appendUniqueOwnedKey(alloc, targets, field.string),
        .array => {
            for (field.array.items) |item| {
                if (item != .string) return error.InvalidGraphEdges;
                try appendUniqueOwnedKey(alloc, targets, item.string);
            }
        },
        else => return error.InvalidGraphEdges,
    }
}

fn augmentExtractedWriteWithGraphFieldEdges(
    self: *DB,
    alloc: Allocator,
    key: []const u8,
    doc_value: []const u8,
    extracted: *mapper.ExtractedWrite,
) !void {
    if (!self.core.hasGraphIndexes() or extracted.cleaned_value == null) return;

    var parsed = try std.json.parseFromSlice(std.json.Value, alloc, doc_value, .{});
    defer parsed.deinit();
    if (parsed.value != .object) return;

    var extra_writes = std.ArrayListUnmanaged(types.GraphEdgeWrite).empty;
    errdefer {
        for (extra_writes.items) |*write| {
            alloc.free(@constCast(write.index_name));
            alloc.free(@constCast(write.source));
            alloc.free(@constCast(write.target));
            alloc.free(@constCast(write.edge_type));
            if (write.metadata_json.len > 0) alloc.free(@constCast(write.metadata_json));
        }
        extra_writes.deinit(alloc);
    }

    var extra_indexes = std.ArrayListUnmanaged([]u8).empty;
    errdefer {
        for (extra_indexes.items) |index_name| alloc.free(index_name);
        extra_indexes.deinit(alloc);
    }

    for (self.core.graphIndexes()) |entry| {
        var index_has_field_edges = false;
        for (entry.edge_type_configs) |edge_cfg| {
            const field_name = edge_cfg.field_name orelse continue;
            index_has_field_edges = true;

            var targets = std.ArrayListUnmanaged([]u8).empty;
            defer {
                for (targets.items) |target| alloc.free(target);
                targets.deinit(alloc);
            }
            try appendGraphFieldTargets(alloc, &targets, parsed.value.object, field_name);

            for (targets.items) |target| {
                try extra_writes.append(alloc, .{
                    .index_name = try alloc.dupe(u8, entry.config.name),
                    .source = try alloc.dupe(u8, key),
                    .target = try alloc.dupe(u8, target),
                    .edge_type = try alloc.dupe(u8, edge_cfg.name),
                    .weight = 1.0,
                    .created_at = 0,
                    .updated_at = 0,
                    .metadata_json = "",
                });
            }
        }

        if (index_has_field_edges and
            !containsOwnedKey(extracted.mentioned_graph_indexes, entry.config.name) and
            !containsOwnedKey(extra_indexes.items, entry.config.name))
        {
            try extra_indexes.append(alloc, try alloc.dupe(u8, entry.config.name));
        }
    }

    if (extra_writes.items.len > 0) {
        const merged = try alloc.alloc(types.GraphEdgeWrite, extracted.graph_writes.len + extra_writes.items.len);
        @memcpy(merged[0..extracted.graph_writes.len], extracted.graph_writes);
        @memcpy(merged[extracted.graph_writes.len..], extra_writes.items);
        if (extracted.graph_writes.len > 0) alloc.free(extracted.graph_writes);
        extracted.graph_writes = merged;
    }
    extra_writes.deinit(alloc);

    if (extra_indexes.items.len > 0) {
        const merged = try alloc.alloc([]u8, extracted.mentioned_graph_indexes.len + extra_indexes.items.len);
        @memcpy(merged[0..extracted.mentioned_graph_indexes.len], extracted.mentioned_graph_indexes);
        @memcpy(merged[extracted.mentioned_graph_indexes.len..], extra_indexes.items);
        if (extracted.mentioned_graph_indexes.len > 0) alloc.free(extracted.mentioned_graph_indexes);
        extracted.mentioned_graph_indexes = merged;
    }
    extra_indexes.deinit(alloc);
}

fn requestArtifactName(request: enrichment_types.GeneratedEnrichmentRequest) []const u8 {
    return if (request.artifact_name.len > 0) request.artifact_name else request.index_name;
}

fn requestEmbeddingName(request: enrichment_types.GeneratedEnrichmentRequest) []const u8 {
    return if (request.embedding_name.len > 0) request.embedding_name else request.index_name;
}

fn generatedRequestMatchesForcedArtifact(
    force_generated_artifact_names: []const []const u8,
    request: enrichment_types.GeneratedEnrichmentRequest,
) bool {
    if (force_generated_artifact_names.len == 0) return true;
    return containsName(force_generated_artifact_names, requestArtifactName(request)) or
        containsName(force_generated_artifact_names, requestEmbeddingName(request));
}

fn requestHasChunking(request: enrichment_types.GeneratedEnrichmentRequest) bool {
    return request.chunk_size > 0 or request.chunker_json.len > 0;
}

fn requestUsesMaterializedChunkArtifact(db: *const DB, artifact_name: []const u8) bool {
    if (artifact_name.len == 0) return false;
    const chunk_cfg = db.core.index_manager.getEnrichment(.chunk, artifact_name) orelse return false;
    return chunk_cfg.source_artifact_name.len > 0;
}

fn generatedEmbedBatchItems() usize {
    if (comptime builtin.os.tag == .freestanding) return generated_embed_default_batch_items;
    const raw = getenv("ANTFLY_ENRICHMENT_EMBED_BATCH_ITEMS") orelse return generated_embed_default_batch_items;
    if (raw.len == 0) return generated_embed_default_batch_items;
    const parsed = std.fmt.parseUnsigned(usize, raw, 10) catch return generated_embed_default_batch_items;
    return @max(@as(usize, 1), parsed);
}

fn generatedEmbedBatchBytes() usize {
    if (comptime builtin.os.tag == .freestanding) return generated_embed_default_batch_bytes;
    const raw = getenv("ANTFLY_ENRICHMENT_EMBED_BATCH_BYTES") orelse return generated_embed_default_batch_bytes;
    if (raw.len == 0) return generated_embed_default_batch_bytes;
    const parsed = std.fmt.parseUnsigned(usize, raw, 10) catch return generated_embed_default_batch_bytes;
    return @max(@as(usize, 1), parsed);
}

fn remoteRenderConfig(
    secret_store: ?*common_secrets.FileStore,
    remote_content: ?*const scraping.RemoteContentConfig,
    max_media_parts: ?usize,
) template_remote.RenderConfig {
    var config: template_remote.RenderConfig = .{};
    if (comptime @hasField(template_remote.RenderConfig, "secret_store")) {
        config.secret_store = secret_store;
    }
    if (comptime @hasField(template_remote.RenderConfig, "remote_content")) {
        config.remote_content = remote_content;
    }
    if (comptime @hasField(template_remote.RenderConfig, "max_media_parts")) {
        config.max_media_parts = max_media_parts;
    }
    return config;
}

fn renderSourceTemplateText(
    alloc: Allocator,
    secret_store: ?*common_secrets.FileStore,
    remote_content: ?*const scraping.RemoteContentConfig,
    template_source: []const u8,
    doc_value: []const u8,
) ![]const u8 {
    if (comptime @hasDecl(template_remote, "renderJsonToValidatedTextWithConfig")) {
        return try template_remote.renderJsonToValidatedTextWithConfig(
            alloc,
            template_source,
            doc_value,
            remoteRenderConfig(secret_store, remote_content, null),
        );
    }
    return try template_remote.renderJsonToTextWithConfig(
        alloc,
        template_source,
        doc_value,
        remoteRenderConfig(secret_store, remote_content, null),
    );
}

fn renderSourceTemplateParts(
    alloc: Allocator,
    secret_store: ?*common_secrets.FileStore,
    remote_content: ?*const scraping.RemoteContentConfig,
    template_source: []const u8,
    doc_value: []const u8,
    max_media_parts: ?usize,
) ![]template_mod.ContentPart {
    if (comptime @hasDecl(template_remote, "renderJsonToPartsWithConfig")) {
        return try template_remote.renderJsonToPartsWithConfig(
            alloc,
            template_source,
            doc_value,
            remoteRenderConfig(secret_store, remote_content, max_media_parts),
        );
    }
    return try template_remote.renderJsonToParts(alloc, template_source, doc_value);
}

fn makeChunkCacheKey(alloc: Allocator, request: enrichment_types.GeneratedEnrichmentRequest) ![]u8 {
    var chunk_size: [@sizeOf(u32)]u8 = undefined;
    var chunk_overlap: [@sizeOf(u32)]u8 = undefined;
    std.mem.writeInt(u32, &chunk_size, request.chunk_size, .big);
    std.mem.writeInt(u32, &chunk_overlap, request.chunk_overlap, .big);
    return try chunkCacheTupleKeyAlloc(alloc, &.{
        request.doc_key,
        requestArtifactName(request),
        request.source_field,
        &chunk_size,
        &chunk_overlap,
        request.chunker_json,
    });
}

fn chunkCacheTupleKeyAlloc(alloc: Allocator, components: []const []const u8) ![]u8 {
    var out = std.ArrayListUnmanaged(u8).empty;
    errdefer out.deinit(alloc);

    for (components) |component| {
        if (component.len > std.math.maxInt(u32)) return error.KeyComponentTooLarge;
        var len_buf: [@sizeOf(u32)]u8 = undefined;
        std.mem.writeInt(u32, &len_buf, @intCast(component.len), .big);
        try out.appendSlice(alloc, &len_buf);
        try out.appendSlice(alloc, component);
    }

    return try out.toOwnedSlice(alloc);
}

test "db chunk cache keys preserve embedded separators" {
    const alloc = std.testing.allocator;

    const left = try makeChunkCacheKey(alloc, .{
        .kind = .chunk_text,
        .index_name = "idx",
        .artifact_name = "artifact",
        .doc_key = "doc\x1fartifact",
        .source_field = "body",
        .chunk_size = 64,
        .chunk_overlap = 8,
        .chunker_json = "{\"mode\":\"a\"}",
    });
    defer alloc.free(left);

    const right = try makeChunkCacheKey(alloc, .{
        .kind = .chunk_text,
        .index_name = "idx",
        .artifact_name = "artifact\x1fartifact",
        .doc_key = "doc",
        .source_field = "body",
        .chunk_size = 64,
        .chunk_overlap = 8,
        .chunker_json = "{\"mode\":\"a\"}",
    });
    defer alloc.free(right);

    try std.testing.expect(!std.mem.eql(u8, left, right));
}

fn getOrCreateChunks(
    alloc: Allocator,
    db: *DB,
    doc_value: []const u8,
    request: enrichment_types.GeneratedEnrichmentRequest,
    cache: *std.ArrayListUnmanaged(ChunkCacheEntry),
) ![]chunker_mod.Chunk {
    const cache_key = try makeChunkCacheKey(alloc, request);
    errdefer alloc.free(cache_key);

    for (cache.items) |entry| {
        if (std.mem.eql(u8, entry.key, cache_key)) {
            alloc.free(cache_key);
            return entry.chunks;
        }
    }

    const source_text = if (request.source_template.len > 0)
        renderSourceTemplateText(alloc, db.secret_store, db.remote_content, request.source_template, doc_value) catch |err| switch (err) {
            error.PermanentPromptFailure, error.TransientPromptFailure => return err,
            else => null,
        }
    else
        try extractStringField(alloc, doc_value, request.source_field);
    if (source_text == null or source_text.?.len == 0) {
        if (source_text) |s| alloc.free(s);
        const empty = try alloc.alloc(chunker_mod.Chunk, 0);
        try cache.append(alloc, .{
            .key = cache_key,
            .chunks = empty,
        });
        return cache.items[cache.items.len - 1].chunks;
    }
    defer alloc.free(source_text.?);

    const chunks = if (request.chunker_json.len > 0)
        try chunker_mod.chunkTextWithConfigJson(alloc, source_text.?, request.chunker_json)
    else
        try chunker_mod.chunkText(alloc, source_text.?, request.chunk_size, request.chunk_overlap);
    try cache.append(alloc, .{
        .key = cache_key,
        .chunks = chunks,
    });
    return cache.items[cache.items.len - 1].chunks;
}

fn shouldStoreChunkArtifacts(alloc: Allocator, request: enrichment_types.GeneratedEnrichmentRequest) !bool {
    if (request.persist_artifact) return true;
    if (request.full_text_index) return true;
    if (request.chunker_json.len == 0) return true;
    if (try chunking_types_mod.parseHasFullTextIndexFromSlice(alloc, request.chunker_json)) return true;
    return try chunking_types_mod.parseStoreChunksFromSlice(alloc, request.chunker_json);
}

fn appendChunkArtifactWrites(
    alloc: Allocator,
    doc_key: []const u8,
    source_field: []const u8,
    artifact_name: []const u8,
    chunks: []const chunker_mod.Chunk,
    artifact_writes: *std.ArrayListUnmanaged(types.BatchWrite),
    include_payload: bool,
) !void {
    var arena_state = std.heap.ArenaAllocator.init(alloc);
    defer arena_state.deinit();
    const scratch = arena_state.allocator();

    for (chunks) |chunk| {
        const key = try internal_keys.chunkArtifactKeyAlloc(alloc, doc_key, artifact_name, @intCast(chunk.chunk_id));
        defer alloc.free(key);
        const payload = try buildChunkArtifactPayloadAlloc(scratch, doc_key, artifact_name, source_field, chunk, include_payload);

        try artifact_writes.append(alloc, .{
            .key = try alloc.dupe(u8, key),
            .value = try alloc.dupe(u8, payload),
        });

        _ = arena_state.reset(.retain_capacity);
    }
}

fn buildChunkArtifactPayloadAlloc(
    alloc: Allocator,
    doc_key: []const u8,
    artifact_name: []const u8,
    source_field: []const u8,
    chunk: chunker_mod.Chunk,
    include_payload: bool,
) ![]u8 {
    var obj = std.json.ObjectMap.empty;
    try obj.put(alloc, try alloc.dupe(u8, "_parent_doc_key"), .{ .string = try alloc.dupe(u8, doc_key) });
    try obj.put(alloc, try alloc.dupe(u8, "_artifact_name"), .{ .string = try alloc.dupe(u8, artifact_name) });
    try obj.put(alloc, try alloc.dupe(u8, "_source_field"), .{ .string = try alloc.dupe(u8, source_field) });
    try chunk_artifact_mod.appendArtifactFields(alloc, &obj, source_field, chunk, include_payload);
    return try std.json.Stringify.valueAlloc(alloc, std.json.Value{ .object = obj }, .{});
}

fn appendDerivedDenseEmbeddingForConsumers(
    alloc: Allocator,
    out: *std.ArrayListUnmanaged(derived_types.DerivedDenseEmbeddingWrite),
    doc_key: []const u8,
    parent_doc_key: ?[]const u8,
    artifact_key: []const u8,
    vector: []const f32,
    consumer_indexes: []const []const u8,
) !void {
    _ = vector;
    for (consumer_indexes) |index_name| {
        try out.append(alloc, .{
            .index_name = try alloc.dupe(u8, index_name),
            .parent_doc_key = if (parent_doc_key) |key| try alloc.dupe(u8, key) else null,
            .doc_key = try alloc.dupe(u8, doc_key),
            .artifact_key = try alloc.dupe(u8, artifact_key),
            .vector = &.{},
        });
    }
}

fn appendDerivedSparseEmbeddingForConsumers(
    alloc: Allocator,
    out: *std.ArrayListUnmanaged(derived_types.DerivedSparseEmbeddingWrite),
    doc_key: []const u8,
    artifact_key: []const u8,
    indices: []const u32,
    values: []const f32,
    consumer_indexes: []const []const u8,
) !void {
    _ = indices;
    _ = values;
    for (consumer_indexes) |index_name| {
        try out.append(alloc, .{
            .index_name = try alloc.dupe(u8, index_name),
            .doc_key = try alloc.dupe(u8, doc_key),
            .artifact_key = try alloc.dupe(u8, artifact_key),
            .indices = &.{},
            .values = &.{},
        });
    }
}

fn computeChunkRequestDerived(
    alloc: Allocator,
    db: *DB,
    doc_value: []const u8,
    request: enrichment_types.GeneratedEnrichmentRequest,
    artifact_writes: *std.ArrayListUnmanaged(types.BatchWrite),
    artifact_delete_keys: *std.ArrayListUnmanaged([]const u8),
    documents: *std.ArrayListUnmanaged(derived_types.DerivedDocument),
    cache: *std.ArrayListUnmanaged(ChunkCacheEntry),
) !void {
    if (!requestHasChunking(request)) return;

    const artifact_name = requestArtifactName(request);
    const chunks = try getOrCreateChunks(alloc, db, doc_value, request, cache);
    const desired_chunk_keys = try chunkArtifactKeysForChunksAlloc(alloc, request.doc_key, artifact_name, chunks);
    defer freeChunkArtifactKeys(alloc, desired_chunk_keys);

    const persist_chunks = try shouldStoreChunkArtifacts(alloc, request);
    if (persist_chunks) {
        try appendChunkArtifactWrites(alloc, request.doc_key, request.source_field, artifact_name, chunks, artifact_writes, true);
    }
    try appendStaleChunkArtifactDeleteKeys(
        alloc,
        db,
        request.doc_key,
        artifact_name,
        desired_chunk_keys,
        artifact_delete_keys,
    );
    if (chunks.len == 0) return;

    const include_default_full_text = request.full_text_index or
        try chunking_types_mod.parseHasFullTextIndexFromSlice(alloc, request.chunker_json);
    const text_indexes = try db.core.index_manager.textIndexesForChunk(alloc, artifact_name, include_default_full_text);
    defer {
        for (text_indexes) |name| alloc.free(name);
        alloc.free(text_indexes);
    }
    if (text_indexes.len == 0) return;

    var arena_state = std.heap.ArenaAllocator.init(alloc);
    defer arena_state.deinit();
    const scratch = arena_state.allocator();

    for (chunks) |chunk| {
        if (!chunk.isText()) continue;
        const key = try internal_keys.chunkArtifactKeyAlloc(alloc, request.doc_key, artifact_name, @intCast(chunk.chunk_id));
        defer alloc.free(key);

        const targets = try alloc.alloc(derived_types.DerivedTargetRef, text_indexes.len);
        errdefer {
            for (targets) |target| alloc.free(target.index_name);
            alloc.free(targets);
        }
        for (text_indexes, 0..) |index_name, i| {
            targets[i] = .{
                .kind = .full_text,
                .index_name = try alloc.dupe(u8, index_name),
            };
        }
        const payload = try buildChunkArtifactPayloadAlloc(scratch, request.doc_key, artifact_name, request.source_field, chunk, true);

        try documents.append(alloc, .{
            .key = try alloc.dupe(u8, key),
            .action = .upsert,
            .cleaned_value = try alloc.dupe(u8, payload),
            .targets = targets,
        });

        _ = arena_state.reset(.retain_capacity);
    }
}

fn appendStaleChunkArtifactDeleteKeys(
    alloc: Allocator,
    db: *DB,
    doc_key: []const u8,
    artifact_name: []const u8,
    desired_chunk_keys: []const []u8,
    artifact_delete_keys: *std.ArrayListUnmanaged([]const u8),
) !void {
    const prefix = try internal_keys.artifactNamedPrefixAlloc(alloc, doc_key, "chunk", artifact_name);
    defer alloc.free(prefix);
    const existing = try db.core.store.scanPrefix(alloc, prefix);
    defer docstore_mod.DocStore.freeResults(alloc, existing);

    for (existing) |entry| {
        if (containsKey(desired_chunk_keys, entry.key)) continue;
        if (internal_keys.isDerivedEmbeddingArtifactKey(entry.key)) {
            const base_key = try internal_keys.derivedEmbeddingBaseKeyAlloc(alloc, entry.key);
            defer if (base_key) |key| alloc.free(key);
            if (base_key != null and containsKey(desired_chunk_keys, base_key.?)) continue;
        }
        var already_deleted = false;
        for (artifact_delete_keys.items) |key| {
            if (std.mem.eql(u8, key, entry.key)) {
                already_deleted = true;
                break;
            }
        }
        if (!already_deleted) try artifact_delete_keys.append(alloc, try alloc.dupe(u8, entry.key));
    }
}

fn chunkArtifactKeysForChunksAlloc(
    alloc: Allocator,
    doc_key: []const u8,
    artifact_name: []const u8,
    chunks: []const chunker_mod.Chunk,
) ![][]u8 {
    const keys = try alloc.alloc([]u8, chunks.len);
    var initialized: usize = 0;
    errdefer {
        for (keys[0..initialized]) |key| alloc.free(key);
        alloc.free(keys);
    }
    for (chunks, 0..) |chunk, i| {
        keys[i] = try internal_keys.chunkArtifactKeyAlloc(alloc, doc_key, artifact_name, @intCast(chunk.chunk_id));
        initialized += 1;
    }
    return keys;
}

fn freeChunkArtifactKeys(alloc: Allocator, keys: []const []u8) void {
    for (keys) |key| alloc.free(key);
    alloc.free(keys);
}

fn containsKey(keys: []const []u8, target: []const u8) bool {
    for (keys) |key| {
        if (std.mem.eql(u8, key, target)) return true;
    }
    return false;
}

fn computeAssetRequestDerived(
    alloc: Allocator,
    db: *DB,
    doc_value: []const u8,
    request: enrichment_types.GeneratedEnrichmentRequest,
    artifact_writes: *std.ArrayListUnmanaged(types.BatchWrite),
    artifact_delete_keys: *std.ArrayListUnmanaged([]const u8),
    documents: *std.ArrayListUnmanaged(derived_types.DerivedDocument),
    dense_embeddings: *std.ArrayListUnmanaged(derived_types.DerivedDenseEmbeddingWrite),
    sparse_embeddings: *std.ArrayListUnmanaged(derived_types.DerivedSparseEmbeddingWrite),
    deferred_asset_producer_items: ?*std.ArrayListUnmanaged(PrecomputeAssetProducerBatchItem),
    force_reprocess: bool,
) !void {
    var producer_cfg = try asset_producer_mod.parseProducerConfig(alloc, request.producer_json);
    defer producer_cfg.deinit(alloc);

    const artifact_name = requestArtifactName(request);
    const key = try internal_keys.artifactNamedPrefixAlloc(alloc, request.doc_key, "asset", artifact_name);
    defer alloc.free(key);

    const text_indexes = try db.core.index_manager.textIndexesForChunk(alloc, artifact_name, request.full_text_index);
    defer {
        for (text_indexes) |name| alloc.free(name);
        alloc.free(text_indexes);
    }

    const source_text = try extractAssetSourceValue(alloc, db, doc_value, request);
    if (source_text == null or source_text.?.len == 0) {
        if (source_text) |s| alloc.free(s);
        try appendFullTextDeleteDocument(alloc, documents, key, text_indexes);
        if (producer_cfg.type == .document_extraction) {
            try appendDocumentExtractionDeleteKeys(alloc, db, request.doc_key, artifact_name, key, artifact_delete_keys);
            return;
        }
        try artifact_delete_keys.append(alloc, try alloc.dupe(u8, key));
        const state_key = try assetStateKeyAlloc(alloc, request.doc_key, artifact_name);
        errdefer alloc.free(state_key);
        try artifact_delete_keys.append(alloc, state_key);
        return;
    }
    defer alloc.free(source_text.?);

    if (producer_cfg.type == .document_extraction) {
        return try computeDocumentExtractionAssetRequestDerived(
            alloc,
            db,
            doc_value,
            source_text.?,
            request,
            producer_cfg.config_json,
            key,
            artifact_writes,
            artifact_delete_keys,
            documents,
            dense_embeddings,
            sparse_embeddings,
            force_reprocess,
        );
    }

    const source_parts_json = if (producer_cfg.type != .copy and request.source_template.len > 0)
        try renderSourcePartsJson(alloc, db, doc_value, request)
    else
        null;
    defer if (source_parts_json) |value| alloc.free(value);

    const state_key = if (producer_cfg.type != .copy)
        try assetStateKeyAlloc(alloc, request.doc_key, artifact_name)
    else
        null;
    defer if (state_key) |value| alloc.free(value);
    const state_value = if (producer_cfg.type != .copy)
        try assetStateValueAlloc(alloc, source_text.?, source_parts_json, request.producer_json)
    else
        null;
    defer if (state_value) |value| alloc.free(value);
    if (!force_reprocess and state_key != null and state_value != null) {
        const existing_state = try db.core.getStoreValue(alloc, state_key.?);
        defer if (existing_state) |value| alloc.free(value);
        if (existing_state != null and std.mem.eql(u8, existing_state.?, state_value.?)) {
            const existing_asset = try db.core.getStoreValue(alloc, key);
            defer if (existing_asset) |value| alloc.free(value);
            if (existing_asset) |value| {
                try artifact_writes.append(alloc, .{
                    .key = try alloc.dupe(u8, key),
                    .value = try alloc.dupe(u8, value),
                });
                try appendInlineFullTextDocument(alloc, documents, key, value, text_indexes);
                return;
            }
        }
    }

    if (producer_cfg.type != .copy) {
        if (deferred_asset_producer_items) |items| {
            const request_clone = try enrichment_types.cloneGeneratedRequest(alloc, request);
            errdefer enrichment_types.freeGeneratedRequest(alloc, request_clone);
            const config_json = producer_cfg.config_json;
            producer_cfg.config_json = "";
            errdefer if (config_json.len > 0) alloc.free(@constCast(config_json));
            const item_source_text = try alloc.dupe(u8, source_text.?);
            errdefer alloc.free(item_source_text);
            const item_source_parts_json = if (source_parts_json) |parts| try alloc.dupe(u8, parts) else null;
            errdefer if (item_source_parts_json) |parts| alloc.free(parts);
            const item_artifact_key = try alloc.dupe(u8, key);
            errdefer alloc.free(item_artifact_key);
            const item_state_key = try alloc.dupe(u8, state_key.?);
            errdefer alloc.free(item_state_key);
            const item_state_value = try alloc.dupe(u8, state_value.?);
            errdefer alloc.free(item_state_value);
            const item = PrecomputeAssetProducerBatchItem{
                .request = request_clone,
                .producer_type = producer_cfg.type,
                .config_json = @constCast(config_json),
                .source_text = item_source_text,
                .source_parts_json = item_source_parts_json,
                .artifact_key = item_artifact_key,
                .state_key = item_state_key,
                .state_value = item_state_value,
            };
            try appendPrecomputeAssetProducerBatchItem(alloc, db, items, item, artifact_writes, documents);
            return;
        }
    }

    const value = if (producer_cfg.type == .copy) source_text.? else blk: {
        const runtime = db.enrichment_runtime orelse return error.MissingAssetProducer;
        const producer = runtime.config.asset_producer orelse return error.MissingAssetProducer;
        break :blk try producer.produce(alloc, .{
            .producer_type = producer_cfg.type,
            .config_json = producer_cfg.config_json,
            .source_text = source_text.?,
            .source_parts_json = source_parts_json,
            .content_type = request.content_type,
        });
    };
    defer if (producer_cfg.type != .copy) alloc.free(value);

    try artifact_writes.append(alloc, .{
        .key = try alloc.dupe(u8, key),
        .value = try alloc.dupe(u8, value),
    });
    try appendInlineFullTextDocument(alloc, documents, key, value, text_indexes);

    if (producer_cfg.type != .copy) {
        try artifact_writes.append(alloc, .{
            .key = try alloc.dupe(u8, state_key.?),
            .value = try alloc.dupe(u8, state_value.?),
        });
    }
}

const PrecomputeAssetProducerBatchItem = struct {
    request: enrichment_types.GeneratedEnrichmentRequest,
    producer_type: asset_producer_mod.ProducerType,
    config_json: []u8,
    source_text: []u8,
    source_parts_json: ?[]u8 = null,
    artifact_key: []u8,
    state_key: []u8,
    state_value: []u8,

    fn asRequest(self: *const @This()) asset_producer_mod.Request {
        return .{
            .producer_type = self.producer_type,
            .config_json = self.config_json,
            .source_text = self.source_text,
            .source_parts_json = self.source_parts_json,
            .content_type = self.request.content_type,
        };
    }
};

fn freePrecomputeAssetProducerBatchItem(alloc: Allocator, item: PrecomputeAssetProducerBatchItem) void {
    enrichment_types.freeGeneratedRequest(alloc, item.request);
    if (item.config_json.len > 0) alloc.free(item.config_json);
    alloc.free(item.source_text);
    if (item.source_parts_json) |parts| alloc.free(parts);
    alloc.free(item.artifact_key);
    alloc.free(item.state_key);
    alloc.free(item.state_value);
}

fn clearPrecomputeAssetProducerBatchItems(
    alloc: Allocator,
    items: *std.ArrayListUnmanaged(PrecomputeAssetProducerBatchItem),
) void {
    for (items.items) |item| freePrecomputeAssetProducerBatchItem(alloc, item);
    items.clearRetainingCapacity();
}

fn samePrecomputeAssetProducerBatchKey(lhs: PrecomputeAssetProducerBatchItem, rhs: PrecomputeAssetProducerBatchItem) bool {
    return lhs.producer_type == rhs.producer_type and
        std.mem.eql(u8, lhs.config_json, rhs.config_json) and
        std.mem.eql(u8, lhs.request.content_type, rhs.request.content_type) and
        std.mem.eql(u8, lhs.request.execution_json, rhs.request.execution_json);
}

fn addPrecomputeAssetProducerBytes(lhs: usize, rhs: usize) usize {
    return std.math.add(usize, lhs, rhs) catch std.math.maxInt(usize);
}

fn precomputeAssetProducerBatchItemBytes(item: PrecomputeAssetProducerBatchItem) usize {
    return addPrecomputeAssetProducerBytes(
        addPrecomputeAssetProducerBytes(item.config_json.len, item.source_text.len),
        if (item.source_parts_json) |parts| parts.len else 0,
    );
}

fn precomputeAssetProducerBatchBytes(items: []const PrecomputeAssetProducerBatchItem) usize {
    var total: usize = 0;
    for (items) |item| total = addPrecomputeAssetProducerBytes(total, precomputeAssetProducerBatchItemBytes(item));
    return total;
}

fn isRetryableAssetProducerError(err: anyerror) bool {
    return switch (err) {
        error.EmbedRateLimited,
        error.EmbedTransientFailure,
        error.ModelNotFound,
        error.ConnectionRefused,
        error.ConnectionResetByPeer,
        error.ConnectionTimedOut,
        error.Timeout,
        error.NetworkUnreachable,
        error.HostLacksNetworkAddresses,
        error.TemporaryNameServerFailure,
        error.NameServerFailure,
        error.UnexpectedReadFailure,
        error.SendFailed,
        error.RecvFailed,
        error.ResourceBudgetExceeded,
        error.GenerateBatchTransientFailure,
        error.ReadTransientFailure,
        => true,
        else => false,
    };
}

fn appendPrecomputeAssetProducerBatchItem(
    alloc: Allocator,
    db: *DB,
    items: *std.ArrayListUnmanaged(PrecomputeAssetProducerBatchItem),
    item: PrecomputeAssetProducerBatchItem,
    artifact_writes: *std.ArrayListUnmanaged(types.BatchWrite),
    documents: *std.ArrayListUnmanaged(derived_types.DerivedDocument),
) !void {
    const policy = enrichment_types.parseExecutionPolicyJson(alloc, item.request.execution_json) catch enrichment_types.ExecutionPolicy{};
    const max_items = @max(@as(usize, 1), policy.batch_items orelse 1);
    const max_bytes = @max(@as(usize, 1), policy.batch_bytes orelse std.math.maxInt(usize));
    if (items.items.len > 0) {
        const current_bytes = precomputeAssetProducerBatchBytes(items.items);
        const item_bytes = precomputeAssetProducerBatchItemBytes(item);
        if (!samePrecomputeAssetProducerBatchKey(items.items[0], item) or
            items.items.len >= max_items or
            addPrecomputeAssetProducerBytes(current_bytes, item_bytes) > max_bytes)
        {
            try flushPrecomputeAssetProducerBatch(alloc, db, items, artifact_writes, documents);
        }
    }
    try items.append(alloc, item);
}

fn applyPrecomputeAssetProducerOutput(
    alloc: Allocator,
    db: *DB,
    item: PrecomputeAssetProducerBatchItem,
    produced: []const u8,
    artifact_writes: *std.ArrayListUnmanaged(types.BatchWrite),
    documents: *std.ArrayListUnmanaged(derived_types.DerivedDocument),
) !void {
    try artifact_writes.append(alloc, .{
        .key = try alloc.dupe(u8, item.artifact_key),
        .value = try alloc.dupe(u8, produced),
    });
    try artifact_writes.append(alloc, .{
        .key = try alloc.dupe(u8, item.state_key),
        .value = try alloc.dupe(u8, item.state_value),
    });

    const artifact_name = requestArtifactName(item.request);
    const text_indexes = try db.core.index_manager.textIndexesForChunk(alloc, artifact_name, item.request.full_text_index);
    defer {
        for (text_indexes) |name| alloc.free(name);
        alloc.free(text_indexes);
    }
    try appendInlineFullTextDocument(alloc, documents, item.artifact_key, produced, text_indexes);
}

fn flushPrecomputeAssetProducerBatchSequential(
    alloc: Allocator,
    producer: asset_producer_mod.Producer,
    items: []const PrecomputeAssetProducerBatchItem,
    db: *DB,
    artifact_writes: *std.ArrayListUnmanaged(types.BatchWrite),
    documents: *std.ArrayListUnmanaged(derived_types.DerivedDocument),
) !void {
    for (items) |item| {
        const produced = producer.produce(alloc, item.asRequest()) catch |err| {
            if (err == error.OutOfMemory) return err;
            if (isRetryableAssetProducerError(err)) return err;
            return err;
        };
        defer alloc.free(produced);
        applyPrecomputeAssetProducerOutput(alloc, db, item, produced, artifact_writes, documents) catch |err| {
            if (err == error.OutOfMemory) return err;
            if (isRetryableAssetProducerError(err)) return err;
            return err;
        };
    }
}

fn flushPrecomputeAssetProducerBatch(
    alloc: Allocator,
    db: *DB,
    items: *std.ArrayListUnmanaged(PrecomputeAssetProducerBatchItem),
    artifact_writes: *std.ArrayListUnmanaged(types.BatchWrite),
    documents: *std.ArrayListUnmanaged(derived_types.DerivedDocument),
) !void {
    if (items.items.len == 0) return;
    defer clearPrecomputeAssetProducerBatchItems(alloc, items);

    const runtime = db.enrichment_runtime orelse return error.MissingAssetProducer;
    const producer = runtime.config.asset_producer orelse return error.MissingAssetProducer;
    const requests = try alloc.alloc(asset_producer_mod.Request, items.items.len);
    defer alloc.free(requests);
    for (items.items, 0..) |*item, idx| requests[idx] = item.asRequest();

    const can_batch = producer.canProduceBatch(alloc, requests) catch |err| {
        if (err == error.OutOfMemory) return err;
        if (isRetryableAssetProducerError(err)) return err;
        return try flushPrecomputeAssetProducerBatchSequential(alloc, producer, items.items, db, artifact_writes, documents);
    };
    if (!can_batch)
        return try flushPrecomputeAssetProducerBatchSequential(alloc, producer, items.items, db, artifact_writes, documents);

    var produced = producer.produceBatch(alloc, requests) catch |err| {
        if (err == error.OutOfMemory) return err;
        if (isRetryableAssetProducerError(err)) return err;
        return try flushPrecomputeAssetProducerBatchSequential(alloc, producer, items.items, db, artifact_writes, documents);
    };
    if (produced.len != items.items.len) {
        for (produced) |output| {
            if (output.len > 0) alloc.free(output);
        }
        alloc.free(produced);
        return try flushPrecomputeAssetProducerBatchSequential(alloc, producer, items.items, db, artifact_writes, documents);
    }

    defer alloc.free(produced);
    errdefer {
        for (produced) |output| {
            if (output.len > 0) alloc.free(output);
        }
    }

    for (items.items, produced, 0..) |item, output, idx| {
        applyPrecomputeAssetProducerOutput(alloc, db, item, output, artifact_writes, documents) catch |err| {
            alloc.free(output);
            produced[idx] = "";
            if (err == error.OutOfMemory) return err;
            if (isRetryableAssetProducerError(err)) return err;
            return err;
        };
        alloc.free(output);
        produced[idx] = "";
    }
}

fn computeDocumentExtractionAssetRequestDerived(
    alloc: Allocator,
    db: *DB,
    doc_value: []const u8,
    source_url: []const u8,
    request: enrichment_types.GeneratedEnrichmentRequest,
    config_json: []const u8,
    manifest_key: []const u8,
    artifact_writes: *std.ArrayListUnmanaged(types.BatchWrite),
    artifact_delete_keys: *std.ArrayListUnmanaged([]const u8),
    documents: *std.ArrayListUnmanaged(derived_types.DerivedDocument),
    dense_embeddings: *std.ArrayListUnmanaged(derived_types.DerivedDenseEmbeddingWrite),
    sparse_embeddings: *std.ArrayListUnmanaged(derived_types.DerivedSparseEmbeddingWrite),
    force_reprocess: bool,
) !void {
    const artifact_name = requestArtifactName(request);
    var config = try document_extraction_mod.parseConfig(alloc, config_json);
    defer config.deinit(alloc);
    try document_extraction_mod.applySourceMetadataFromJson(alloc, &config, doc_value);

    const state_key = try assetStateKeyAlloc(alloc, request.doc_key, artifact_name);
    defer alloc.free(state_key);
    const existing_state = db.core.getStoreValue(alloc, state_key) catch |err| switch (err) {
        error.NotFound => null,
        else => return err,
    };
    defer if (existing_state) |value| alloc.free(value);
    const existing_manifest = db.core.getStoreValue(alloc, manifest_key) catch |err| switch (err) {
        error.NotFound => null,
        else => return err,
    };
    defer if (existing_manifest) |value| alloc.free(value);
    var previous_child_ranges: []types.DocumentArtifactChildRange = &.{};
    defer freeDocumentArtifactChildRanges(alloc, previous_child_ranges);
    if (existing_manifest) |value| {
        previous_child_ranges = documentArtifactChildRangesFromManifestJsonAlloc(alloc, value) catch |err| switch (err) {
            error.OutOfMemory => return err,
            else => &.{},
        };
    }

    const from_generation = if (existing_manifest) |value|
        documentExtractionManifestGeneration(alloc, value) catch 0
    else
        0;
    const to_generation = from_generation + 1;

    const metadata_fingerprint = try document_extraction_mod.metadataFingerprintAlloc(alloc, source_url, config_json, config);
    defer if (metadata_fingerprint) |fingerprint| alloc.free(fingerprint);
    if (!force_reprocess) {
        if (metadata_fingerprint) |fingerprint| {
            if (existing_state) |state| {
                if (documentExtractionStateFingerprintMatches(alloc, state, fingerprint) and
                    documentExtractionStateHasChunkUnitFingerprints(alloc, state))
                {
                    if (existing_manifest) |value| {
                        const manifest_has_last_error = documentExtractionManifestHasLastError(alloc, value) catch |err| switch (err) {
                            error.OutOfMemory => return err,
                            else => true,
                        };
                        if (!manifest_has_last_error) {
                            try appendDocumentExtractionNavigationBackfill(
                                alloc,
                                db,
                                request.doc_key,
                                artifact_name,
                                fingerprint,
                                state,
                                from_generation,
                                artifact_writes,
                                artifact_delete_keys,
                            );
                            try artifact_writes.append(alloc, .{
                                .key = try alloc.dupe(u8, manifest_key),
                                .value = try alloc.dupe(u8, value),
                            });
                            return;
                        }
                    }
                }
            }
        }
    }

    const fetched = template_remote.downloadRemoteContentOutcomeAllocWithConfig(
        alloc,
        db.remote_content,
        db.secret_store,
        source_url,
        if (config.credentials.len > 0) config.credentials else null,
    ) catch |err| switch (err) {
        error.OutOfMemory => return err,
        else => {
            if (!document_extraction_mod.remoteContentErrorIsPermanent(err)) return err;
            try appendDocumentExtractionFailureManifest(alloc, db, request.doc_key, artifact_name, source_url, manifest_key, existing_state, previous_child_ranges, from_generation, to_generation, @errorName(err), "remote content download failed", "remote_content_download", artifact_writes);
            return;
        },
    };
    const downloaded = switch (fetched) {
        .ok => |content| content,
        .http_error => |http_error| {
            if (document_extraction_mod.remoteHttpStatusIsTransient(http_error.status))
                return error.RemoteDocumentFetchFailed;
            const message = try std.fmt.allocPrint(alloc, "{s}: HTTP {d}", .{ http_error.message, http_error.status });
            defer alloc.free(message);
            try appendDocumentExtractionFailureManifest(alloc, db, request.doc_key, artifact_name, source_url, manifest_key, existing_state, previous_child_ranges, from_generation, to_generation, "RemoteDocumentFetchFailed", message, "remote_content_http", artifact_writes);
            return;
        },
    };
    var downloaded_mut = downloaded;
    defer downloaded_mut.deinit(alloc);

    var pdf_decode_reservation: ?resource_manager_mod.Reservation = null;
    defer if (pdf_decode_reservation) |*reservation| reservation.release();
    if (document_extraction_mod.resolvesToPdf(config, source_url, if (config.content_type.len > 0) config.content_type else downloaded_mut.content_type, downloaded_mut.data)) {
        if (db.core.index_manager.resource_manager) |manager| {
            const stats = manager.sliceStats(.document_extraction_working_set);
            const downloaded_bytes: u64 = @intCast(downloaded_mut.data.len);
            const decode_budget = if (stats.hard_limit_bytes == 0)
                @as(u64, @intCast(config.pdf_decode_limits.max_working_set_bytes))
            else
                @min(@as(u64, @intCast(config.pdf_decode_limits.max_working_set_bytes)), stats.hard_limit_bytes -| downloaded_bytes);
            if (decode_budget == 0) return error.DocumentExtractionWorkingSetTooLarge;
            const reservation_bytes = std.math.add(u64, downloaded_bytes, decode_budget) catch return error.DocumentExtractionWorkingSetTooLarge;
            pdf_decode_reservation = try manager.reserve(.document_extraction_working_set, reservation_bytes);
            config.pdf_decode_limits.max_working_set_bytes = @intCast(decode_budget);
            config.pdf_decode_limits.max_decoded_stream_bytes = @min(config.pdf_decode_limits.max_decoded_stream_bytes, config.pdf_decode_limits.max_working_set_bytes);
        }
    }

    var extraction = document_extraction_mod.extractDownloadedAlloc(alloc, downloaded_mut, source_url, config) catch |err| switch (err) {
        error.OutOfMemory => return err,
        else => {
            try appendDocumentExtractionFailureManifest(alloc, db, request.doc_key, artifact_name, source_url, manifest_key, existing_state, previous_child_ranges, from_generation, to_generation, @errorName(err), "document extraction failed", document_extraction_mod.failureStage(err, "document_extraction"), artifact_writes);
            return;
        },
    };
    defer extraction.deinit(alloc);
    if (db.enrichment_runtime) |runtime| {
        try enrichment_runtime_mod.completeDocumentExtractionGeneratedTextForRequest(
            runtime,
            alloc,
            request,
            config,
            source_url,
            downloaded_mut.data,
            extraction.content_type,
            &extraction,
        );
    } else if (document_extraction_mod.ocrEnabledForRoute(config, extraction.route_type) or config.transcription_enabled) {
        return error.MissingAssetProducer;
    }
    document_extraction_mod.rebaseUnitCharOffsets(extraction.units);

    const byte_source_fingerprint = if (metadata_fingerprint == null)
        try documentExtractionFingerprintAlloc(alloc, source_url, config_json, config.content_type, config.filename, downloaded_mut.content_type, downloaded_mut.data)
    else
        null;
    defer if (byte_source_fingerprint) |fingerprint| alloc.free(fingerprint);
    const source_fingerprint = metadata_fingerprint orelse byte_source_fingerprint.?;

    var desired_unit_keys = std.ArrayListUnmanaged([]const u8).empty;
    defer {
        for (desired_unit_keys.items) |key| alloc.free(@constCast(key));
        desired_unit_keys.deinit(alloc);
    }
    var desired_unit_fingerprints = std.ArrayListUnmanaged([]const u8).empty;
    defer {
        for (desired_unit_fingerprints.items) |fingerprint| alloc.free(@constCast(fingerprint));
        desired_unit_fingerprints.deinit(alloc);
    }
    var desired_chunk_keys = std.ArrayListUnmanaged([]const u8).empty;
    defer {
        for (desired_chunk_keys.items) |key| alloc.free(@constCast(key));
        desired_chunk_keys.deinit(alloc);
    }

    try collectDocumentExtractionDesiredKeys(alloc, db, request.doc_key, artifact_name, extraction.units, &desired_unit_keys, &desired_unit_fingerprints, &desired_chunk_keys);

    const desired_unit_descriptors = try documentExtractionUnitDescriptorsFromKeysAlloc(alloc, desired_unit_keys.items, desired_unit_fingerprints.items);
    defer alloc.free(desired_unit_descriptors);

    const navigation_digest = try hierarchyNavigationArtifactDigestAlloc(alloc, desired_unit_descriptors);
    defer alloc.free(navigation_digest);
    const navigation_unit_count = std.math.cast(u32, desired_unit_descriptors.len) orelse
        return error.InvalidDocumentExtractionState;
    const navigation_block_count = hierarchyNavigationBlockCount(navigation_unit_count);

    const new_state = try documentExtractionStateValueAlloc(
        alloc,
        source_fingerprint,
        desired_unit_keys.items,
        desired_unit_descriptors,
        desired_chunk_keys.items,
        navigation_digest,
        navigation_block_count,
        true,
    );
    defer alloc.free(new_state);
    const navigation_summary_key = try internal_keys.documentUnitNavigationSummaryKeyAlloc(alloc, request.doc_key, artifact_name);
    defer alloc.free(navigation_summary_key);
    const existing_navigation_summary = try db.core.getStoreValue(alloc, navigation_summary_key);
    defer if (existing_navigation_summary) |value| alloc.free(value);

    var previous_state = DocumentExtractionPreviousState{};
    defer previous_state.deinit(alloc);

    if (existing_state) |state| {
        if (!force_reprocess and existing_navigation_summary != null and
            std.mem.eql(u8, state, new_state) and
            try hierarchy_navigation.indexMetadataMatches(alloc, state, existing_navigation_summary.?, from_generation))
        {
            if (existing_manifest) |value| {
                if (!(try documentExtractionManifestHasLastError(alloc, value))) {
                    try artifact_writes.append(alloc, .{
                        .key = try alloc.dupe(u8, manifest_key),
                        .value = try alloc.dupe(u8, value),
                    });
                    return;
                }
            }
        }

        previous_state = try loadDocumentExtractionPreviousState(alloc, db, request.doc_key, artifact_name, state);
        for (previous_state.unit_keys) |previous_key| {
            if (containsDeleteKey(desired_unit_keys.items, previous_key)) continue;
            try artifact_delete_keys.append(alloc, try alloc.dupe(u8, previous_key));
        }
        for (previous_state.chunk_keys) |previous_key| {
            if (containsDeleteKey(desired_chunk_keys.items, previous_key)) continue;
            try artifact_delete_keys.append(alloc, try alloc.dupe(u8, previous_key));
        }
        if (previous_state.recovered_from_store_scan) {
            try artifact_delete_keys.append(alloc, try alloc.dupe(u8, state_key));
        }
    }

    // Persist compact, directly addressable hierarchy metadata with the same
    // derived write batch as the manifest and unit payloads. Cursor requests
    // can then validate one summary and fetch only the blocks covering the
    // requested page instead of reparsing every unit descriptor.
    const navigation_summary = try hierarchyNavigationSummaryValueAlloc(
        alloc,
        to_generation,
        navigation_digest,
        navigation_unit_count,
        navigation_block_count,
    );
    defer alloc.free(navigation_summary);
    try artifact_writes.append(alloc, .{
        .key = try alloc.dupe(u8, navigation_summary_key),
        .value = try alloc.dupe(u8, navigation_summary),
    });
    var navigation_block_index: u32 = 0;
    while (navigation_block_index < navigation_block_count) : (navigation_block_index += 1) {
        const start = @as(usize, navigation_block_index) * hierarchy_navigation_block_size;
        const end = @min(start + hierarchy_navigation_block_size, desired_unit_descriptors.len);
        const block_key = try internal_keys.documentUnitNavigationBlockKeyAlloc(
            alloc,
            request.doc_key,
            artifact_name,
            navigation_block_index,
        );
        defer alloc.free(block_key);
        const block_value = try hierarchyNavigationBlockValueAlloc(
            alloc,
            navigation_block_index,
            desired_unit_descriptors[start..end],
        );
        defer alloc.free(block_value);
        try artifact_writes.append(alloc, .{
            .key = try alloc.dupe(u8, block_key),
            .value = try alloc.dupe(u8, block_value),
        });
    }
    var obsolete_navigation_block = navigation_block_count;
    while (obsolete_navigation_block < previous_state.navigation_block_count) : (obsolete_navigation_block += 1) {
        try artifact_delete_keys.append(
            alloc,
            try internal_keys.documentUnitNavigationBlockKeyAlloc(
                alloc,
                request.doc_key,
                artifact_name,
                obsolete_navigation_block,
            ),
        );
    }

    const text_indexes = try db.core.index_manager.textIndexesForChunk(alloc, artifact_name, request.full_text_index);
    defer {
        for (text_indexes) |name| alloc.free(name);
        alloc.free(text_indexes);
    }

    const chunk_range_base_index = documentExtractionUnitRangeCount(extraction.units);
    for (extraction.units, desired_unit_descriptors, 0..) |unit, unit_descriptor, unit_index| {
        const unit_key = try internal_keys.documentUnitArtifactKeyAlloc(alloc, request.doc_key, artifact_name, unit.unit_id);
        defer alloc.free(unit_key);
        const unit_range_id = try documentExtractionRangeIdAlloc(alloc, documentExtractionUnitRangeIndex(extraction.units, unit_index));
        defer alloc.free(unit_range_id);
        const unit_route = documentExtractionRangeRoute(previous_child_ranges, unit_range_id, "unit", artifact_name);
        const unit_unchanged = std.mem.eql(u8, unit_descriptor.key, unit_key) and
            unitDescriptorFingerprintMatches(previous_state.unit_descriptors, unit_key, unit_descriptor.fingerprint);
        if (unit_unchanged and
            try documentUnitCanSkipLocalWrites(alloc, db, request.doc_key, artifact_name, unit_key, unit, text_indexes))
        {
            if (force_reprocess) {
                const payload = try documentUnitPayloadAlloc(alloc, request.doc_key, artifact_name, unit, unit_descriptor.fingerprint, source_url, extraction.content_type, unit_route);
                defer alloc.free(payload);
                try artifact_writes.append(alloc, .{
                    .key = try alloc.dupe(u8, unit_key),
                    .value = try alloc.dupe(u8, payload),
                });
                if (text_indexes.len > 0) {
                    const targets = try alloc.alloc(derived_types.DerivedTargetRef, text_indexes.len);
                    errdefer {
                        for (targets) |target| alloc.free(target.index_name);
                        alloc.free(targets);
                    }
                    for (text_indexes, 0..) |index_name, i| {
                        targets[i] = .{
                            .kind = .full_text,
                            .index_name = try alloc.dupe(u8, index_name),
                        };
                    }
                    try documents.append(alloc, .{
                        .key = try alloc.dupe(u8, unit_key),
                        .action = .upsert,
                        .cleaned_value = try alloc.dupe(u8, payload),
                        .targets = targets,
                    });
                }
                try appendDocumentUnitStoredChunkFullTextDocuments(alloc, db, request.doc_key, artifact_name, unit, documents);
            } else {
                try appendDocumentUnitStoredFullTextDocuments(alloc, db, request.doc_key, artifact_name, unit_key, unit, text_indexes, documents);
            }
            continue;
        }
        const payload = try documentUnitPayloadAlloc(alloc, request.doc_key, artifact_name, unit, unit_descriptor.fingerprint, source_url, extraction.content_type, unit_route);
        defer alloc.free(payload);
        try artifact_writes.append(alloc, .{
            .key = try alloc.dupe(u8, unit_key),
            .value = try alloc.dupe(u8, payload),
        });
        if (text_indexes.len > 0) {
            const targets = try alloc.alloc(derived_types.DerivedTargetRef, text_indexes.len);
            errdefer {
                for (targets) |target| alloc.free(target.index_name);
                alloc.free(targets);
            }
            for (text_indexes, 0..) |index_name, i| {
                targets[i] = .{
                    .kind = .full_text,
                    .index_name = try alloc.dupe(u8, index_name),
                };
            }
            try documents.append(alloc, .{
                .key = try alloc.dupe(u8, unit_key),
                .action = .upsert,
                .cleaned_value = try alloc.dupe(u8, payload),
                .targets = targets,
            });
        }

        try appendDocumentUnitChunkWrites(alloc, db, request.doc_key, artifact_name, unit_key, unit_descriptor.fingerprint, unit, desired_chunk_keys.items, chunk_range_base_index, previous_child_ranges, artifact_writes, documents, dense_embeddings, sparse_embeddings);
    }

    const manifest = try documentExtractionManifestPayloadAlloc(
        alloc,
        request.doc_key,
        artifact_name,
        source_url,
        source_fingerprint,
        extraction,
        desired_unit_keys.items,
        desired_unit_descriptors,
        desired_chunk_keys.items,
        previous_child_ranges,
        previous_state.unit_keys,
        previous_state.unit_descriptors,
        previous_state.chunk_keys,
        to_generation,
        from_generation,
        to_generation,
        "converged",
    );
    defer alloc.free(manifest);
    try artifact_writes.append(alloc, .{
        .key = try alloc.dupe(u8, manifest_key),
        .value = try alloc.dupe(u8, manifest),
    });
    try artifact_writes.append(alloc, .{
        .key = try alloc.dupe(u8, state_key),
        .value = try alloc.dupe(u8, new_state),
    });
}

fn appendDocumentExtractionNavigationBackfill(
    alloc: Allocator,
    db: *DB,
    doc_key: []const u8,
    artifact_name: []const u8,
    source_fingerprint: []const u8,
    state: []const u8,
    generation: u64,
    artifact_writes: *std.ArrayListUnmanaged(types.BatchWrite),
    artifact_delete_keys: *std.ArrayListUnmanaged([]const u8),
) !void {
    const summary_key = try internal_keys.documentUnitNavigationSummaryKeyAlloc(alloc, doc_key, artifact_name);
    defer alloc.free(summary_key);
    const existing_summary = try db.core.getStoreValue(alloc, summary_key);
    defer if (existing_summary) |value| alloc.free(value);
    if (existing_summary) |summary| {
        if (try hierarchy_navigation.indexMetadataMatches(alloc, state, summary, generation)) return;
    }

    const unit_keys = try documentExtractionStateUnitKeysAlloc(alloc, state);
    defer freeOwnedConstKeySlice(alloc, unit_keys);
    const chunk_keys = try documentExtractionStateChunkKeysAlloc(alloc, state);
    defer freeOwnedConstKeySlice(alloc, chunk_keys);
    const descriptors = try documentExtractionStateUnitDescriptorsAlloc(alloc, state);
    defer freeDocumentExtractionUnitDescriptors(alloc, descriptors);
    if (descriptors.len != unit_keys.len) return error.InvalidDocumentExtractionState;

    for (descriptors, unit_keys) |*descriptor, unit_key| {
        if (!std.mem.eql(u8, descriptor.key, unit_key)) return error.InvalidDocumentExtractionState;
        var unit_ref = (try artifact_ids.decodeArtifactRefAlloc(alloc, descriptor.key)) orelse
            return error.InvalidDocumentExtractionState;
        defer unit_ref.deinit(alloc);
        if (unit_ref.kind != .asset or unit_ref.unit_id == null or
            !std.mem.eql(u8, unit_ref.document_id, doc_key) or
            !std.mem.eql(u8, unit_ref.name, artifact_name))
        {
            return error.InvalidDocumentExtractionState;
        }
        if (descriptor.fingerprint.len == 0) {
            const stored = try db.core.getStoreValue(alloc, descriptor.key) orelse
                return error.InvalidDocumentExtractionState;
            defer alloc.free(stored);
            descriptor.fingerprint = try documentExtractionStoredUnitFingerprintAlloc(alloc, stored);
        }
    }

    const digest = try hierarchy_navigation.artifactDigestAlloc(alloc, descriptors);
    defer alloc.free(digest);
    const unit_count = std.math.cast(u32, descriptors.len) orelse return error.InvalidDocumentExtractionState;
    const block_count = hierarchy_navigation.blockCount(unit_count);
    const indexed_state = try documentExtractionStateValueAlloc(
        alloc,
        source_fingerprint,
        unit_keys,
        descriptors,
        chunk_keys,
        digest,
        block_count,
        documentExtractionStateHasChunkUnitFingerprints(alloc, state),
    );
    defer alloc.free(indexed_state);
    const summary = try hierarchy_navigation.summaryValueAlloc(alloc, generation, digest, unit_count, block_count);
    defer alloc.free(summary);
    try artifact_writes.append(alloc, .{
        .key = try alloc.dupe(u8, summary_key),
        .value = try alloc.dupe(u8, summary),
    });

    var block_index: u32 = 0;
    while (block_index < block_count) : (block_index += 1) {
        const start = @as(usize, block_index) * hierarchy_navigation.block_size;
        const end = @min(start + hierarchy_navigation.block_size, descriptors.len);
        const block_key = try internal_keys.documentUnitNavigationBlockKeyAlloc(alloc, doc_key, artifact_name, block_index);
        defer alloc.free(block_key);
        const block_value = try hierarchy_navigation.blockValueAlloc(alloc, block_index, descriptors[start..end]);
        defer alloc.free(block_value);
        try artifact_writes.append(alloc, .{
            .key = try alloc.dupe(u8, block_key),
            .value = try alloc.dupe(u8, block_value),
        });
    }

    const previous_block_count = try documentExtractionStateNavigationBlockCount(alloc, state);
    var obsolete_block = block_count;
    while (obsolete_block < previous_block_count) : (obsolete_block += 1) {
        try artifact_delete_keys.append(
            alloc,
            try internal_keys.documentUnitNavigationBlockKeyAlloc(alloc, doc_key, artifact_name, obsolete_block),
        );
    }
    const state_key = try assetStateKeyAlloc(alloc, doc_key, artifact_name);
    defer alloc.free(state_key);
    try artifact_writes.append(alloc, .{
        .key = try alloc.dupe(u8, state_key),
        .value = try alloc.dupe(u8, indexed_state),
    });
}

fn completeDocumentExtractionGeneratedText(
    alloc: Allocator,
    runtime: ?*enrichment_runtime_mod.EnrichmentRuntime,
    config: document_extraction_mod.Config,
    source_url: []const u8,
    source_bytes: []const u8,
    source_content_type: []const u8,
    extraction: *document_extraction_mod.Result,
) !void {
    const active_runtime = runtime orelse return;
    const producer = active_runtime.config.asset_producer orelse return;
    for (extraction.units) |*unit| {
        if (document_extraction_mod.ocrEnabledForRoute(config, extraction.route_type) and unit.extraction_status != null and std.mem.eql(u8, unit.extraction_status.?, "pending_ocr")) {
            var rendered_page: ?[]u8 = null;
            defer if (rendered_page) |png| alloc.free(png);
            if (std.mem.eql(u8, extraction.route_type, "pdf")) {
                rendered_page = document_extraction_mod.renderPdfPagePngAlloc(
                    alloc,
                    source_bytes,
                    unit.page_number orelse 1,
                    config.ocr_render_dpi,
                    config.ocr_max_rendered_pixels,
                ) catch |err| {
                    const any_err: anyerror = err;
                    if (any_err == error.OutOfMemory) return any_err;
                    try markGeneratedUnitTextFailure(alloc, unit, "ocr_text", .ocr, any_err);
                    continue;
                };
            }
            const parts_json = if (rendered_page) |png|
                try document_extraction_mod.ocrPagePartsJsonAlloc(alloc, config, extraction.route_type, source_content_type, unit.*, png)
            else
                try documentGeneratedTextPartsJsonAlloc(alloc, extraction.route_type, source_content_type, unit.*);
            defer alloc.free(parts_json);
            const produced = producer.produce(alloc, .{
                .producer_type = .reader,
                .config_json = document_extraction_mod.effectiveOcrConfigJson(config),
                .source_text = if (rendered_page != null) "" else source_url,
                .source_parts_json = parts_json,
                .content_type = "text/plain",
            }) catch |err| {
                if (err == error.OutOfMemory) return err;
                if (isUnavailableGeneratedTextModelError(.ocr, err)) {
                    try markGeneratedUnitTextFailure(alloc, unit, "ocr_text", .ocr, err);
                    continue;
                }
                if (isRetryableAssetProducerError(err)) return err;
                try markGeneratedUnitTextFailure(alloc, unit, "ocr_text", .ocr, err);
                continue;
            };
            errdefer alloc.free(produced);
            applyGeneratedUnitText(alloc, unit, produced, "ocr_text", "completed", .ocr) catch |err| {
                if (err == error.OutOfMemory) return err;
                if (isRetryableAssetProducerError(err)) return err;
                try markGeneratedUnitTextFailure(alloc, unit, "ocr_text", .ocr, err);
            };
            continue;
        }
        if (config.transcription_enabled and unit.extraction_status != null and std.mem.eql(u8, unit.extraction_status.?, "pending_transcription")) {
            const parts_json = try documentGeneratedTextPartsJsonAlloc(alloc, extraction.route_type, source_content_type, unit.*);
            defer alloc.free(parts_json);
            const produced = try producer.produce(alloc, .{
                .producer_type = .transcriber,
                .config_json = config.transcription_config_json,
                .source_text = source_url,
                .source_parts_json = parts_json,
                .content_type = "text/plain",
            });
            errdefer alloc.free(produced);
            try applyGeneratedUnitText(alloc, unit, produced, "transcript_text", "completed", .transcript);
        }
    }
}

const GeneratedUnitTextKind = enum { ocr, transcript };

fn isUnavailableGeneratedTextModelError(kind: GeneratedUnitTextKind, err: anyerror) bool {
    if (kind != .ocr) return false;
    return switch (err) {
        error.ModelNotFound,
        error.ModelNotSpecified,
        error.UnsupportedReaderProvider,
        => true,
        else => false,
    };
}

test "precompute OCR error policy distinguishes unavailable models from transient inference failures" {
    try std.testing.expect(isUnavailableGeneratedTextModelError(.ocr, error.ModelNotFound));
    try std.testing.expect(isUnavailableGeneratedTextModelError(.ocr, error.ModelNotSpecified));
    try std.testing.expect(isUnavailableGeneratedTextModelError(.ocr, error.UnsupportedReaderProvider));
    try std.testing.expect(!isUnavailableGeneratedTextModelError(.ocr, error.ConnectionTimedOut));
    try std.testing.expect(isRetryableAssetProducerError(error.ConnectionTimedOut));
    try std.testing.expect(isRetryableAssetProducerError(error.EmbedRateLimited));
    try std.testing.expect(isRetryableAssetProducerError(error.ReadTransientFailure));
    try std.testing.expect(!isRetryableAssetProducerError(error.ReadRequestFailed));
}

test "db document extraction OCR default is scoped to PDF routes" {
    const alloc = std.testing.allocator;
    var defaults = try document_extraction_mod.parseConfig(alloc, "{}");
    defer defaults.deinit(alloc);
    try std.testing.expect(document_extraction_mod.ocrEnabledForRoute(defaults, "pdf"));
    try std.testing.expect(!document_extraction_mod.ocrEnabledForRoute(defaults, "image"));

    var explicit_image = try document_extraction_mod.parseConfig(alloc, "{\"ocr\":true}");
    defer explicit_image.deinit(alloc);
    try std.testing.expect(document_extraction_mod.ocrEnabledForRoute(explicit_image, "image"));
}

fn applyGeneratedUnitText(
    alloc: Allocator,
    unit: *document_extraction_mod.Unit,
    produced: []u8,
    method: []const u8,
    status: []const u8,
    kind: GeneratedUnitTextKind,
) !void {
    if (produced.len == 0) {
        alloc.free(produced);
        return error.EmptyGeneratedText;
    }
    defer alloc.free(produced);
    var parsed = try parseGeneratedUnitTextOutputAlloc(alloc, produced);
    errdefer parsed.deinit(alloc);
    const owned_method = try alloc.dupe(u8, method);
    errdefer alloc.free(owned_method);
    const owned_status = try alloc.dupe(u8, status);
    errdefer alloc.free(owned_status);

    alloc.free(unit.text);
    alloc.free(unit.method);
    if (unit.extraction_status) |value| alloc.free(value);
    if (unit.extraction_warning) |value| alloc.free(value);
    unit.text = parsed.text;
    parsed.text = &.{};
    unit.method = owned_method;
    unit.extraction_status = owned_status;
    switch (kind) {
        .ocr => {
            unit.ocr_used = true;
            unit.ocr_confidence = parsed.confidence;
            unit.ocr_bbox = parsed.bbox;
        },
        .transcript => {
            unit.transcript_used = true;
            unit.transcript_confidence = parsed.confidence;
        },
    }
    unit.extraction_warning = parsed.warning;
    parsed.warning = null;
    const start = unit.char_start orelse 0;
    unit.char_start = start;
    unit.char_end = std.math.cast(u32, @as(usize, @intCast(start)) + unit.text.len);
}

fn markGeneratedUnitTextFailure(
    alloc: Allocator,
    unit: *document_extraction_mod.Unit,
    method: []const u8,
    kind: GeneratedUnitTextKind,
    err: anyerror,
) !void {
    const failed_status = switch (kind) {
        .ocr => "failed_ocr",
        .transcript => "failed_transcription",
    };
    const warning = try std.fmt.allocPrint(alloc, "{s} failed: {s}", .{ method, @errorName(err) });
    errdefer alloc.free(warning);
    const owned_text = try alloc.dupe(u8, "");
    errdefer alloc.free(owned_text);
    const owned_method = try alloc.dupe(u8, method);
    errdefer alloc.free(owned_method);
    const owned_status = try alloc.dupe(u8, failed_status);
    errdefer alloc.free(owned_status);

    alloc.free(unit.text);
    alloc.free(unit.method);
    if (unit.extraction_status) |value| alloc.free(value);
    if (unit.extraction_warning) |value| alloc.free(value);
    unit.text = owned_text;
    unit.method = owned_method;
    unit.extraction_status = owned_status;
    unit.extraction_warning = warning;
    switch (kind) {
        .ocr => {
            unit.ocr_used = false;
            unit.ocr_confidence = null;
            unit.ocr_bbox = null;
        },
        .transcript => {
            unit.transcript_used = false;
            unit.transcript_confidence = null;
        },
    }
    const start = unit.char_start orelse 0;
    unit.char_start = start;
    unit.char_end = start;
}

const ParsedGeneratedUnitText = struct {
    text: []u8,
    confidence: ?f64 = null,
    bbox: ?[4]f64 = null,
    warning: ?[]u8 = null,

    fn deinit(self: *ParsedGeneratedUnitText, alloc: Allocator) void {
        if (self.text.len > 0) alloc.free(self.text);
        if (self.warning) |value| alloc.free(value);
        self.* = undefined;
    }
};

fn parseGeneratedUnitTextOutputAlloc(alloc: Allocator, produced: []const u8) !ParsedGeneratedUnitText {
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, produced, .{}) catch {
        return .{ .text = try alloc.dupe(u8, produced) };
    };
    defer parsed.deinit();
    if (parsed.value != .object) return .{ .text = try alloc.dupe(u8, produced) };
    const text_value = parsed.value.object.get("text") orelse return .{ .text = try alloc.dupe(u8, produced) };
    if (text_value != .string) return .{ .text = try alloc.dupe(u8, produced) };

    var out = ParsedGeneratedUnitText{ .text = try alloc.dupe(u8, text_value.string) };
    errdefer out.deinit(alloc);
    out.confidence = generatedTextJsonFloatField(parsed.value.object, "confidence");
    out.bbox = generatedTextJsonBboxField(parsed.value.object, "ocr_bbox") orelse generatedTextJsonBboxField(parsed.value.object, "bbox") orelse generatedTextJsonBboxField(parsed.value.object, "coordinates");
    if (generatedTextJsonStringField(parsed.value.object, "warning") orelse generatedTextJsonStringField(parsed.value.object, "extraction_warning")) |warning| {
        out.warning = try alloc.dupe(u8, warning);
    }
    return out;
}

fn generatedTextJsonStringField(object: std.json.ObjectMap, field: []const u8) ?[]const u8 {
    const value = object.get(field) orelse return null;
    return if (value == .string) value.string else null;
}

fn generatedTextJsonFloatField(object: std.json.ObjectMap, field: []const u8) ?f64 {
    const value = object.get(field) orelse return null;
    return switch (value) {
        .float => |v| v,
        .integer => |v| @floatFromInt(v),
        else => null,
    };
}

fn generatedTextJsonBboxField(object: std.json.ObjectMap, field: []const u8) ?[4]f64 {
    const value = object.get(field) orelse return null;
    if (value != .array or value.array.items.len != 4) return null;
    var out: [4]f64 = undefined;
    for (value.array.items, 0..) |item, i| {
        out[i] = switch (item) {
            .float => |v| v,
            .integer => |v| @floatFromInt(v),
            else => return null,
        };
    }
    return out;
}

fn documentGeneratedTextPartsJsonAlloc(
    alloc: Allocator,
    route_type: []const u8,
    source_content_type: []const u8,
    unit: document_extraction_mod.Unit,
) ![]u8 {
    return try std.json.Stringify.valueAlloc(alloc, .{
        .schema = "antfly.document_generated_text_request.v1",
        .route_type = route_type,
        .source_content_type = source_content_type,
        .unit_id = unit.unit_id,
        .unit_type = unit.unit_type,
        .method = unit.method,
        .extraction_status = unit.extraction_status,
        .source_path = unit.source_path,
        .page_number = unit.page_number,
        .page_label = unit.page_label,
        .page_bbox = unit.page_bbox,
        .page_rotation = unit.page_rotation,
        .text_regions = unit.text_regions,
        .byte_length = unit.byte_length,
        .source_sha256 = unit.source_sha256,
        .ocr_confidence = unit.ocr_confidence,
        .ocr_bbox = unit.ocr_bbox,
        .transcript_confidence = unit.transcript_confidence,
        .extraction_warning = unit.extraction_warning,
    }, .{});
}

fn appendDocumentExtractionDeleteKeys(
    alloc: Allocator,
    db: *DB,
    doc_key: []const u8,
    artifact_name: []const u8,
    manifest_key: []const u8,
    artifact_delete_keys: *std.ArrayListUnmanaged([]const u8),
) !void {
    try artifact_delete_keys.append(alloc, try alloc.dupe(u8, manifest_key));
    const state_key = try assetStateKeyAlloc(alloc, doc_key, artifact_name);
    errdefer alloc.free(state_key);
    const existing_state = db.core.getStoreValue(alloc, state_key) catch |err| switch (err) {
        error.NotFound => null,
        else => return err,
    };
    defer if (existing_state) |value| alloc.free(value);
    if (existing_state != null) {
        var previous_state = try loadDocumentExtractionPreviousState(alloc, db, doc_key, artifact_name, existing_state);
        defer previous_state.deinit(alloc);
        for (previous_state.unit_keys) |previous_key| {
            try artifact_delete_keys.append(alloc, try alloc.dupe(u8, previous_key));
        }
        for (previous_state.chunk_keys) |previous_key| {
            try artifact_delete_keys.append(alloc, try alloc.dupe(u8, previous_key));
        }
        var block_index: u32 = 0;
        while (block_index < previous_state.navigation_block_count) : (block_index += 1) {
            try artifact_delete_keys.append(
                alloc,
                try internal_keys.documentUnitNavigationBlockKeyAlloc(alloc, doc_key, artifact_name, block_index),
            );
        }
    }
    try artifact_delete_keys.append(
        alloc,
        try internal_keys.documentUnitNavigationSummaryKeyAlloc(alloc, doc_key, artifact_name),
    );
    try artifact_delete_keys.append(alloc, state_key);
}

fn collectDocumentExtractionDesiredKeys(
    alloc: Allocator,
    db: *DB,
    doc_key: []const u8,
    artifact_name: []const u8,
    units: []const document_extraction_mod.Unit,
    desired_unit_keys: *std.ArrayListUnmanaged([]const u8),
    desired_unit_fingerprints: *std.ArrayListUnmanaged([]const u8),
    desired_chunk_keys: *std.ArrayListUnmanaged([]const u8),
) !void {
    for (units) |unit| {
        try desired_unit_keys.append(alloc, try internal_keys.documentUnitArtifactKeyAlloc(alloc, doc_key, artifact_name, unit.unit_id));
        try desired_unit_fingerprints.append(alloc, try documentExtractionUnitFingerprintAlloc(alloc, unit));
        for (db.core.index_manager.enrichments.items) |entry| {
            if (entry.kind != .chunk) continue;
            if (!std.mem.eql(u8, entry.source_artifact_name, artifact_name)) continue;
            const chunks = if (entry.chunker_json.len > 0)
                try chunker_mod.chunkTextWithConfigJson(alloc, unit.text, entry.chunker_json)
            else
                try chunker_mod.chunkText(alloc, unit.text, entry.chunk_size, entry.chunk_overlap);
            defer chunker_mod.freeChunks(alloc, chunks);
            for (chunks) |chunk| {
                try desired_chunk_keys.append(alloc, try internal_keys.documentUnitChunkArtifactKeyAlloc(alloc, doc_key, entry.name, unit.unit_id, @intCast(chunk.chunk_id)));
            }
        }
    }
}

const DocumentExtractionUnitDescriptor = struct {
    key: []const u8,
    fingerprint: []const u8,
};

const DocumentExtractionPreviousState = struct {
    unit_keys: []const []const u8 = &.{},
    unit_descriptors: []DocumentExtractionUnitDescriptor = &.{},
    chunk_keys: []const []const u8 = &.{},
    navigation_block_count: u32 = 0,
    recovered_from_store_scan: bool = false,

    fn deinit(self: *@This(), alloc: Allocator) void {
        freeOwnedConstKeySlice(alloc, self.unit_keys);
        freeDocumentExtractionUnitDescriptors(alloc, self.unit_descriptors);
        freeOwnedConstKeySlice(alloc, self.chunk_keys);
        self.* = undefined;
    }
};

const DocumentExtractionRangeRoute = struct {
    range_id: []const u8,
    route_status: []const u8 = "local_committed",
    owner_group_id: u64 = 0,
};

fn loadDocumentExtractionPreviousState(
    alloc: Allocator,
    db: *DB,
    doc_key: []const u8,
    artifact_name: []const u8,
    existing_state: ?[]const u8,
) !DocumentExtractionPreviousState {
    if (existing_state) |state| {
        if (loadDocumentExtractionPreviousStateFromJson(alloc, state)) |parsed| {
            return parsed;
        } else |err| switch (err) {
            error.OutOfMemory => return err,
            else => {},
        }
    }
    var recovered = try scanDocumentExtractionPreviousStateFromStore(alloc, db, doc_key, artifact_name);
    recovered.recovered_from_store_scan = existing_state != null;
    return recovered;
}

fn loadDocumentExtractionPreviousStateFromJson(alloc: Allocator, state: []const u8) !DocumentExtractionPreviousState {
    var out = DocumentExtractionPreviousState{};
    errdefer out.deinit(alloc);
    out.unit_keys = try documentExtractionStateUnitKeysAlloc(alloc, state);
    out.unit_descriptors = try documentExtractionStateUnitDescriptorsAlloc(alloc, state);
    out.chunk_keys = try documentExtractionStateChunkKeysAlloc(alloc, state);
    out.navigation_block_count = try documentExtractionStateNavigationBlockCount(alloc, state);
    return out;
}

fn scanDocumentExtractionPreviousStateFromStore(
    alloc: Allocator,
    db: *DB,
    doc_key: []const u8,
    artifact_name: []const u8,
) !DocumentExtractionPreviousState {
    var out = DocumentExtractionPreviousState{};
    errdefer out.deinit(alloc);

    var unit_keys = std.ArrayListUnmanaged([]const u8).empty;
    errdefer {
        for (unit_keys.items) |key| alloc.free(@constCast(key));
        unit_keys.deinit(alloc);
    }
    const unit_prefix = try internal_keys.artifactNamedPrefixAlloc(alloc, doc_key, "asset", artifact_name);
    defer alloc.free(unit_prefix);
    const unit_rows = try db.core.store.scanPrefix(alloc, unit_prefix);
    defer docstore_mod.DocStore.freeResults(alloc, unit_rows);
    for (unit_rows) |entry| {
        if (std.mem.eql(u8, entry.key, unit_prefix)) continue;
        if (internal_keys.isDerivedEmbeddingArtifactKey(entry.key)) continue;
        try unit_keys.append(alloc, try alloc.dupe(u8, entry.key));
    }

    var chunk_keys = std.ArrayListUnmanaged([]const u8).empty;
    errdefer {
        for (chunk_keys.items) |key| alloc.free(@constCast(key));
        chunk_keys.deinit(alloc);
    }
    for (db.core.index_manager.enrichments.items) |entry| {
        if (entry.kind != .chunk) continue;
        if (!std.mem.eql(u8, entry.source_artifact_name, artifact_name)) continue;
        const chunk_prefix = try internal_keys.artifactNamedPrefixAlloc(alloc, doc_key, "chunk", entry.name);
        defer alloc.free(chunk_prefix);
        const chunk_rows = try db.core.store.scanPrefix(alloc, chunk_prefix);
        defer docstore_mod.DocStore.freeResults(alloc, chunk_rows);
        for (chunk_rows) |row| {
            if (!internal_keys.isChunkArtifactRecordKey(row.key)) continue;
            try chunk_keys.append(alloc, try alloc.dupe(u8, row.key));
        }
    }

    out.unit_keys = try unit_keys.toOwnedSlice(alloc);
    out.chunk_keys = try chunk_keys.toOwnedSlice(alloc);
    out.unit_descriptors = try alloc.alloc(DocumentExtractionUnitDescriptor, out.unit_keys.len);
    for (out.unit_descriptors) |*descriptor| {
        descriptor.* = .{ .key = "", .fingerprint = "" };
    }
    for (out.unit_descriptors, out.unit_keys) |*descriptor, key| {
        descriptor.* = .{
            .key = try alloc.dupe(u8, key),
            .fingerprint = "",
        };
    }
    return out;
}

fn documentExtractionUnitDescriptorsFromKeysAlloc(
    alloc: Allocator,
    unit_keys: []const []const u8,
    fingerprints: []const []const u8,
) ![]DocumentExtractionUnitDescriptor {
    if (unit_keys.len != fingerprints.len) return error.InvalidDocumentExtractionState;
    const out = try alloc.alloc(DocumentExtractionUnitDescriptor, unit_keys.len);
    for (unit_keys, fingerprints, 0..) |key, fingerprint, i| {
        out[i] = .{
            .key = key,
            .fingerprint = fingerprint,
        };
    }
    return out;
}

fn freeDocumentExtractionUnitDescriptors(alloc: Allocator, descriptors: []DocumentExtractionUnitDescriptor) void {
    for (descriptors) |descriptor| {
        if (descriptor.key.len > 0) alloc.free(@constCast(descriptor.key));
        if (descriptor.fingerprint.len > 0) alloc.free(@constCast(descriptor.fingerprint));
    }
    if (descriptors.len > 0) alloc.free(descriptors);
}

fn appendStoredFullTextDocument(
    alloc: Allocator,
    documents: *std.ArrayListUnmanaged(derived_types.DerivedDocument),
    key: []const u8,
    text_indexes: []const []const u8,
) !void {
    if (text_indexes.len == 0) return;
    const targets = try fullTextTargetRefsAlloc(alloc, text_indexes);
    errdefer {
        for (targets) |target| alloc.free(target.index_name);
        alloc.free(targets);
    }
    try documents.append(alloc, .{
        .key = try alloc.dupe(u8, key),
        .action = .upsert,
        .targets = targets,
    });
}

fn appendInlineFullTextDocument(
    alloc: Allocator,
    documents: *std.ArrayListUnmanaged(derived_types.DerivedDocument),
    key: []const u8,
    value: []const u8,
    text_indexes: []const []const u8,
) !void {
    if (text_indexes.len == 0) return;
    const targets = try fullTextTargetRefsAlloc(alloc, text_indexes);
    errdefer {
        for (targets) |target| alloc.free(target.index_name);
        alloc.free(targets);
    }
    try documents.append(alloc, .{
        .key = try alloc.dupe(u8, key),
        .action = .upsert,
        .cleaned_value = try alloc.dupe(u8, value),
        .targets = targets,
    });
}

fn appendFullTextDeleteDocument(
    alloc: Allocator,
    documents: *std.ArrayListUnmanaged(derived_types.DerivedDocument),
    key: []const u8,
    text_indexes: []const []const u8,
) !void {
    if (text_indexes.len == 0) return;
    const targets = try fullTextTargetRefsAlloc(alloc, text_indexes);
    errdefer {
        for (targets) |target| alloc.free(target.index_name);
        alloc.free(targets);
    }
    try documents.append(alloc, .{
        .key = try alloc.dupe(u8, key),
        .action = .delete,
        .targets = targets,
    });
}

fn fullTextTargetRefsAlloc(
    alloc: Allocator,
    text_indexes: []const []const u8,
) ![]derived_types.DerivedTargetRef {
    const targets = try alloc.alloc(derived_types.DerivedTargetRef, text_indexes.len);
    errdefer {
        for (targets) |target| alloc.free(target.index_name);
        alloc.free(targets);
    }
    for (text_indexes, 0..) |index_name, i| {
        targets[i] = .{
            .kind = .full_text,
            .index_name = try alloc.dupe(u8, index_name),
        };
    }
    return targets;
}

fn appendDocumentUnitStoredFullTextDocuments(
    alloc: Allocator,
    db: *DB,
    doc_key: []const u8,
    source_artifact_name: []const u8,
    unit_key: []const u8,
    unit: document_extraction_mod.Unit,
    unit_text_indexes: []const []const u8,
    documents: *std.ArrayListUnmanaged(derived_types.DerivedDocument),
) !void {
    try appendStoredFullTextDocument(alloc, documents, unit_key, unit_text_indexes);
    try appendDocumentUnitStoredChunkFullTextDocuments(alloc, db, doc_key, source_artifact_name, unit, documents);
}

fn appendDocumentUnitStoredChunkFullTextDocuments(
    alloc: Allocator,
    db: *DB,
    doc_key: []const u8,
    source_artifact_name: []const u8,
    unit: document_extraction_mod.Unit,
    documents: *std.ArrayListUnmanaged(derived_types.DerivedDocument),
) !void {
    for (db.core.index_manager.enrichments.items) |entry| {
        if (entry.kind != .chunk) continue;
        if (!std.mem.eql(u8, entry.source_artifact_name, source_artifact_name)) continue;

        const include_default_full_text = entry.full_text_index or
            try chunking_types_mod.parseHasFullTextIndexFromSlice(alloc, entry.chunker_json);
        const chunk_text_indexes = try db.core.index_manager.textIndexesForChunk(alloc, entry.name, include_default_full_text);
        defer {
            for (chunk_text_indexes) |name| alloc.free(name);
            alloc.free(chunk_text_indexes);
        }
        if (chunk_text_indexes.len == 0) continue;

        const chunks = if (entry.chunker_json.len > 0)
            try chunker_mod.chunkTextWithConfigJson(alloc, unit.text, entry.chunker_json)
        else
            try chunker_mod.chunkText(alloc, unit.text, entry.chunk_size, entry.chunk_overlap);
        defer chunker_mod.freeChunks(alloc, chunks);

        for (chunks) |chunk| {
            if (!chunk.isText()) continue;
            const chunk_key = try internal_keys.documentUnitChunkArtifactKeyAlloc(alloc, doc_key, entry.name, unit.unit_id, @intCast(chunk.chunk_id));
            defer alloc.free(chunk_key);
            try appendStoredFullTextDocument(alloc, documents, chunk_key, chunk_text_indexes);
        }
    }
}

fn storeKeyExists(alloc: Allocator, db: *DB, key: []const u8) !bool {
    const value = db.core.getStoreValue(alloc, key) catch |err| switch (err) {
        error.NotFound => return false,
        else => return err,
    };
    if (value) |owned| alloc.free(owned);
    return true;
}

fn documentUnitCanSkipLocalWrites(
    alloc: Allocator,
    db: *DB,
    doc_key: []const u8,
    source_artifact_name: []const u8,
    unit_key: []const u8,
    unit: document_extraction_mod.Unit,
    unit_text_indexes: []const []const u8,
) !bool {
    _ = unit_text_indexes;
    if (!(try storeKeyExists(alloc, db, unit_key))) return false;

    for (db.core.index_manager.enrichments.items) |entry| {
        if (entry.kind != .chunk) continue;
        if (!std.mem.eql(u8, entry.source_artifact_name, source_artifact_name)) continue;

        const chunks = if (entry.chunker_json.len > 0)
            try chunker_mod.chunkTextWithConfigJson(alloc, unit.text, entry.chunker_json)
        else
            try chunker_mod.chunkText(alloc, unit.text, entry.chunk_size, entry.chunk_overlap);
        defer chunker_mod.freeChunks(alloc, chunks);

        for (chunks) |chunk| {
            if (!chunk.isText()) continue;
            const chunk_key = try internal_keys.documentUnitChunkArtifactKeyAlloc(alloc, doc_key, entry.name, unit.unit_id, @intCast(chunk.chunk_id));
            defer alloc.free(chunk_key);
            if (!(try storeKeyExists(alloc, db, chunk_key))) return false;
            if (!(try documentUnitChunkEmbeddingArtifactsPresent(alloc, db, chunk_key, entry.name))) return false;
        }
    }
    return true;
}

fn documentUnitChunkEmbeddingArtifactsPresent(
    alloc: Allocator,
    db: *DB,
    chunk_key: []const u8,
    chunk_artifact_name: []const u8,
) !bool {
    const runtime = db.enrichment_runtime;
    for (db.core.index_manager.enrichments.items) |entry| {
        if (entry.kind != .embedding) continue;
        if (!std.mem.eql(u8, entry.source_artifact_name, chunk_artifact_name)) continue;

        if (entry.expected_dims > 0) {
            const consumer_indexes = try db.core.index_manager.denseIndexesForEmbedding(alloc, entry.name, entry.expected_dims);
            defer {
                for (consumer_indexes) |name| alloc.free(name);
                alloc.free(consumer_indexes);
            }
            if (consumer_indexes.len == 0 or runtime == null or runtime.?.config.dense_embedder == null) continue;
        } else {
            const consumer_indexes = try db.core.index_manager.sparseIndexesForEmbedding(alloc, entry.name);
            defer {
                for (consumer_indexes) |name| alloc.free(name);
                alloc.free(consumer_indexes);
            }
            if (consumer_indexes.len == 0 or runtime == null or runtime.?.config.sparse_embedder == null) continue;
        }

        const artifact_key = try internal_keys.derivedEmbeddingArtifactKeyAlloc(alloc, chunk_key, entry.name);
        defer alloc.free(artifact_key);
        if (!(try storeKeyExists(alloc, db, artifact_key))) return false;
    }
    return true;
}

fn appendDocumentUnitChunkWrites(
    alloc: Allocator,
    db: *DB,
    doc_key: []const u8,
    source_artifact_name: []const u8,
    unit_key: []const u8,
    unit_fingerprint: []const u8,
    unit: document_extraction_mod.Unit,
    desired_chunk_keys: []const []const u8,
    chunk_range_base_index: usize,
    previous_child_ranges: []const types.DocumentArtifactChildRange,
    artifact_writes: *std.ArrayListUnmanaged(types.BatchWrite),
    documents: *std.ArrayListUnmanaged(derived_types.DerivedDocument),
    dense_embeddings: *std.ArrayListUnmanaged(derived_types.DerivedDenseEmbeddingWrite),
    sparse_embeddings: *std.ArrayListUnmanaged(derived_types.DerivedSparseEmbeddingWrite),
) !void {
    for (db.core.index_manager.enrichments.items) |entry| {
        if (entry.kind != .chunk) continue;
        if (!std.mem.eql(u8, entry.source_artifact_name, source_artifact_name)) continue;
        const chunks = if (entry.chunker_json.len > 0)
            try chunker_mod.chunkTextWithConfigJson(alloc, unit.text, entry.chunker_json)
        else
            try chunker_mod.chunkText(alloc, unit.text, entry.chunk_size, entry.chunk_overlap);
        defer chunker_mod.freeChunks(alloc, chunks);
        if (chunks.len == 0) continue;

        const include_default_full_text = entry.full_text_index or
            try chunking_types_mod.parseHasFullTextIndexFromSlice(alloc, entry.chunker_json);
        const text_indexes = try db.core.index_manager.textIndexesForChunk(alloc, entry.name, include_default_full_text);
        defer {
            for (text_indexes) |name| alloc.free(name);
            alloc.free(text_indexes);
        }

        var arena_state = std.heap.ArenaAllocator.init(alloc);
        defer arena_state.deinit();
        const scratch = arena_state.allocator();

        for (chunks) |chunk| {
            if (!chunk.isText()) continue;
            const chunk_key = try internal_keys.documentUnitChunkArtifactKeyAlloc(alloc, doc_key, entry.name, unit.unit_id, @intCast(chunk.chunk_id));
            defer alloc.free(chunk_key);
            const chunk_key_index = documentExtractionKeyIndex(desired_chunk_keys, chunk_key) orelse return error.DocumentExtractionChunkRangeMissing;
            const chunk_range_id = try documentExtractionRangeIdAlloc(scratch, chunk_range_base_index + (chunk_key_index / document_extraction_range_target_children));
            const chunk_route = documentExtractionRangeRoute(previous_child_ranges, chunk_range_id, "chunk", "derived_chunks");
            const payload = try buildDocumentUnitChunkPayloadAlloc(scratch, doc_key, unit_key, unit_fingerprint, entry.name, source_artifact_name, entry.source_field, unit, chunk, true, chunk_route);
            try artifact_writes.append(alloc, .{
                .key = try alloc.dupe(u8, chunk_key),
                .value = try alloc.dupe(u8, payload),
            });

            if (text_indexes.len > 0) {
                const targets = try alloc.alloc(derived_types.DerivedTargetRef, text_indexes.len);
                errdefer {
                    for (targets) |target| alloc.free(target.index_name);
                    alloc.free(targets);
                }
                for (text_indexes, 0..) |index_name, i| {
                    targets[i] = .{
                        .kind = .full_text,
                        .index_name = try alloc.dupe(u8, index_name),
                    };
                }
                try documents.append(alloc, .{
                    .key = try alloc.dupe(u8, chunk_key),
                    .action = .upsert,
                    .cleaned_value = try alloc.dupe(u8, payload),
                    .targets = targets,
                });
            }

            try appendDocumentUnitChunkDenseEmbeddingWrites(alloc, db, doc_key, chunk_key, entry.name, entry.source_field, chunk, artifact_writes, dense_embeddings);
            try appendDocumentUnitChunkSparseEmbeddingWrites(alloc, db, chunk_key, entry.name, chunk, artifact_writes, sparse_embeddings);

            _ = arena_state.reset(.retain_capacity);
        }
    }
}

fn appendDocumentUnitChunkDenseEmbeddingWrites(
    alloc: Allocator,
    db: *DB,
    doc_key: []const u8,
    chunk_key: []const u8,
    chunk_artifact_name: []const u8,
    source_field: []const u8,
    chunk: chunker_mod.Chunk,
    artifact_writes: *std.ArrayListUnmanaged(types.BatchWrite),
    dense_embeddings: *std.ArrayListUnmanaged(derived_types.DerivedDenseEmbeddingWrite),
) !void {
    const chunk_text = chunk.text orelse return;
    const runtime = db.enrichment_runtime orelse return;
    const dense_embedder = runtime.config.dense_embedder orelse return;

    for (db.core.index_manager.enrichments.items) |entry| {
        if (entry.kind != .embedding) continue;
        if (!std.mem.eql(u8, entry.source_artifact_name, chunk_artifact_name)) continue;
        if (entry.expected_dims == 0) continue;

        const consumer_indexes = try db.core.index_manager.denseIndexesForEmbedding(alloc, entry.name, entry.expected_dims);
        defer {
            for (consumer_indexes) |name| alloc.free(name);
            alloc.free(consumer_indexes);
        }
        if (consumer_indexes.len == 0) continue;

        const vector = try enrichment_runtime_mod.embedDenseTracked(runtime, alloc, dense_embedder, entry.name, chunk_text, entry.expected_dims);
        defer alloc.free(vector);
        const artifact_key = try appendEmbeddingArtifactWrite(
            alloc,
            artifact_writes,
            chunk_key,
            doc_key,
            entry.name,
            source_field,
            chunk_key,
            enrichment_artifact_codec.hashSource(chunk_text),
            vector,
        );
        defer alloc.free(artifact_key);
        try appendDerivedDenseEmbeddingForConsumers(alloc, dense_embeddings, chunk_key, doc_key, artifact_key, vector, consumer_indexes);
    }
}

fn appendDocumentUnitChunkSparseEmbeddingWrites(
    alloc: Allocator,
    db: *DB,
    chunk_key: []const u8,
    chunk_artifact_name: []const u8,
    chunk: chunker_mod.Chunk,
    artifact_writes: *std.ArrayListUnmanaged(types.BatchWrite),
    sparse_embeddings: *std.ArrayListUnmanaged(derived_types.DerivedSparseEmbeddingWrite),
) !void {
    const chunk_text = chunk.text orelse return;
    const runtime = db.enrichment_runtime orelse return;
    const sparse_embedder = runtime.config.sparse_embedder orelse return;

    for (db.core.index_manager.enrichments.items) |entry| {
        if (entry.kind != .embedding) continue;
        if (!std.mem.eql(u8, entry.source_artifact_name, chunk_artifact_name)) continue;
        if (entry.expected_dims != 0) continue;

        const consumer_indexes = try db.core.index_manager.sparseIndexesForEmbedding(alloc, entry.name);
        defer {
            for (consumer_indexes) |name| alloc.free(name);
            alloc.free(consumer_indexes);
        }
        if (consumer_indexes.len == 0) continue;

        var sparse = try sparse_embedder.embedSparse(alloc, entry.name, chunk_text);
        defer sparse.deinit(alloc);
        const artifact_key = try appendSparseEmbeddingArtifactWrite(
            alloc,
            artifact_writes,
            chunk_key,
            entry.name,
            enrichment_artifact_codec.hashSource(chunk_text),
            sparse.indices,
            sparse.values,
        );
        defer alloc.free(artifact_key);
        try appendDerivedSparseEmbeddingForConsumers(alloc, sparse_embeddings, chunk_key, artifact_key, sparse.indices, sparse.values, consumer_indexes);
    }
}

fn buildDocumentUnitChunkPayloadAlloc(
    alloc: Allocator,
    doc_key: []const u8,
    unit_key: []const u8,
    unit_fingerprint: []const u8,
    artifact_name: []const u8,
    source_artifact_name: []const u8,
    source_field: []const u8,
    unit: document_extraction_mod.Unit,
    chunk: chunker_mod.Chunk,
    include_payload: bool,
    route: DocumentExtractionRangeRoute,
) ![]u8 {
    const owner_group_id = std.math.cast(i64, route.owner_group_id) orelse return error.InvalidDocumentExtractionManifest;
    var obj = std.json.ObjectMap.empty;
    try obj.put(alloc, try alloc.dupe(u8, "_parent_doc_key"), .{ .string = try alloc.dupe(u8, doc_key) });
    try obj.put(alloc, try alloc.dupe(u8, "_parent_unit_key"), .{ .string = try alloc.dupe(u8, unit_key) });
    try obj.put(alloc, try alloc.dupe(u8, hierarchy_navigation_unit_fingerprint_field), .{ .string = try alloc.dupe(u8, unit_fingerprint) });
    try obj.put(alloc, try alloc.dupe(u8, "_parent_unit_id"), .{ .string = try alloc.dupe(u8, unit.unit_id) });
    try obj.put(alloc, try alloc.dupe(u8, "_artifact_name"), .{ .string = try alloc.dupe(u8, artifact_name) });
    try obj.put(alloc, try alloc.dupe(u8, "_source_artifact_name"), .{ .string = try alloc.dupe(u8, source_artifact_name) });
    try obj.put(alloc, try alloc.dupe(u8, "_source_field"), .{ .string = try alloc.dupe(u8, source_field) });
    try obj.put(alloc, try alloc.dupe(u8, "_artifact_range_id"), .{ .string = try alloc.dupe(u8, route.range_id) });
    try obj.put(alloc, try alloc.dupe(u8, "_artifact_range_kind"), .{ .string = try alloc.dupe(u8, "chunk") });
    try obj.put(alloc, try alloc.dupe(u8, "_artifact_route_status"), .{ .string = try alloc.dupe(u8, route.route_status) });
    try obj.put(alloc, try alloc.dupe(u8, "_artifact_owner_group_id"), .{ .integer = owner_group_id });
    try chunk_artifact_mod.appendArtifactFieldsWithProvenance(alloc, &obj, source_field, chunk, include_payload, .{
        .scope = .unit,
        .parent_doc_key = doc_key,
        .parent_unit_key = unit_key,
        .parent_unit_id = unit.unit_id,
        .source_artifact_name = source_artifact_name,
        .document_char_base = unit.char_start,
        .page_number = unit.page_number,
        .page_label = unit.page_label,
        .page_bbox = unit.page_bbox,
        .page_rotation = unit.page_rotation,
        .extraction_method = unit.method,
        .extraction_status = unit.extraction_status,
        .confidence = documentUnitConfidence(unit),
        .ocr_used = unit.ocr_used,
        .ocr_attempted = unit.ocr_attempted,
        .ocr_render_dpi = unit.ocr_render_dpi,
        .ocr_effective_render_dpi = unit.ocr_effective_render_dpi,
        .ocr_rendered_width = unit.ocr_rendered_width,
        .ocr_rendered_height = unit.ocr_rendered_height,
        .ocr_rendered_bytes = unit.ocr_rendered_bytes,
        .ocr_failure_stage = unit.ocr_failure_stage,
        .ocr_failure_retryable = unit.ocr_failure_retryable,
        .ocr_trigger_reasons = unit.ocr_trigger_reasons,
        .ocr_embedded_quality = unit.ocr_embedded_quality,
        .ocr_output_quality = unit.ocr_output_quality,
        .ocr_confidence = unit.ocr_confidence,
        .ocr_bbox = unit.ocr_bbox,
        .transcript_used = unit.transcript_used,
        .transcript_confidence = unit.transcript_confidence,
        .extraction_warning = unit.extraction_warning,
    });
    return try std.json.Stringify.valueAlloc(alloc, std.json.Value{ .object = obj }, .{});
}

fn documentExtractionFingerprintAlloc(
    alloc: Allocator,
    source_url: []const u8,
    config_json: []const u8,
    configured_content_type: []const u8,
    configured_filename: []const u8,
    downloaded_content_type: []const u8,
    data: []const u8,
) ![]u8 {
    var hasher = std.crypto.hash.sha2.Sha256.init(.{});
    hasher.update(source_url);
    hasher.update(config_json);
    hasher.update(configured_content_type);
    hasher.update(configured_filename);
    hasher.update(downloaded_content_type);
    hasher.update(data);
    var digest: [std.crypto.hash.sha2.Sha256.digest_length]u8 = undefined;
    hasher.final(&digest);
    return try hexBytesAlloc(alloc, &digest);
}

fn documentExtractionUnitFingerprintAlloc(alloc: Allocator, unit: document_extraction_mod.Unit) ![]u8 {
    return try document_unit_fingerprint.fingerprintAlloc(alloc, unit);
}

/// Reconstruct the legacy extraction fingerprint from a pre-marker stored
/// unit payload. New payloads persist their versioned fingerprint directly;
/// this fallback keeps hierarchy traversal revision-safe during rolling
/// upgrades without forcing a generation-wide migration rewrite.
pub fn documentExtractionStoredUnitFingerprintAlloc(alloc: Allocator, stored: []const u8) ![]u8 {
    var arena = std.heap.ArenaAllocator.init(alloc);
    defer arena.deinit();
    const scratch = arena.allocator();
    var parsed = try std.json.parseFromSlice(std.json.Value, scratch, stored, .{});
    defer parsed.deinit();
    if (parsed.value != .object) return error.InvalidDocumentExtractionState;
    const object = parsed.value.object;
    const provenance_value = object.get("provenance") orelse return error.InvalidDocumentExtractionState;
    if (provenance_value != .object) return error.InvalidDocumentExtractionState;
    const provenance = provenance_value.object;

    const text_regions = try storedUnitTextRegionsAlloc(scratch, provenance.get("text_regions"));
    const unit = document_extraction_mod.Unit{
        .unit_id = @constCast(try storedUnitRequiredString(object, "unit_id")),
        .unit_type = @constCast(try storedUnitRequiredString(object, "unit_type")),
        .text = @constCast(try storedUnitRequiredString(object, "text")),
        .method = @constCast(try storedUnitRequiredString(provenance, "method")),
        .source_path = if (try storedUnitOptionalString(object, "source_path")) |value| @constCast(value) else null,
        .extraction_status = if (try storedUnitOptionalString(object, "extraction_status")) |value| @constCast(value) else null,
        .source_sha256 = if (try storedUnitOptionalString(object, "source_sha256")) |value| @constCast(value) else null,
        .byte_length = try storedUnitOptionalInteger(u64, object, "byte_length"),
        .ocr_used = try storedUnitRequiredBool(provenance, "ocr_used"),
        .ocr_attempted = try storedUnitRequiredBool(object, "ocr_attempted"),
        .ocr_render_dpi = try storedUnitOptionalInteger(u16, object, "ocr_render_dpi"),
        .ocr_effective_render_dpi = try storedUnitOptionalInteger(u16, object, "ocr_effective_render_dpi"),
        .ocr_rendered_width = try storedUnitOptionalInteger(u32, object, "ocr_rendered_width"),
        .ocr_rendered_height = try storedUnitOptionalInteger(u32, object, "ocr_rendered_height"),
        .ocr_rendered_bytes = try storedUnitOptionalInteger(u64, object, "ocr_rendered_bytes"),
        .ocr_failure_stage = if (try storedUnitOptionalString(object, "ocr_failure_stage")) |value| @constCast(value) else null,
        .ocr_failure_retryable = try storedUnitOptionalBool(object, "ocr_failure_retryable"),
        .ocr_trigger_reasons = if (try storedUnitOptionalString(object, "ocr_trigger_reasons")) |value| @constCast(value) else null,
        .ocr_embedded_quality = if (try storedUnitOptionalString(object, "ocr_embedded_quality")) |value| @constCast(value) else null,
        .ocr_output_quality = if (try storedUnitOptionalString(object, "ocr_output_quality")) |value| @constCast(value) else null,
        .ocr_confidence = try storedUnitOptionalFloat(object, "ocr_confidence"),
        .ocr_bbox = try storedUnitOptionalBbox(object, "ocr_bbox"),
        .transcript_used = try storedUnitRequiredBool(provenance, "transcript_used"),
        .transcript_confidence = try storedUnitOptionalFloat(object, "transcript_confidence"),
        .extraction_warning = if (try storedUnitOptionalString(object, "extraction_warning")) |value| @constCast(value) else null,
        .page_number = try storedUnitOptionalInteger(u32, provenance, "page_number"),
        .page_label = if (try storedUnitOptionalString(provenance, "page_label")) |value| @constCast(value) else null,
        .page_bbox = try storedUnitOptionalBbox(provenance, "page_bbox"),
        .page_rotation = try storedUnitOptionalInteger(i32, provenance, "page_rotation"),
        .text_regions = text_regions,
        .char_start = try storedUnitOptionalInteger(u32, provenance, "char_start"),
        .char_end = try storedUnitOptionalInteger(u32, provenance, "char_end"),
    };
    // A payload without the marker predates the canonical fingerprint
    // encoding. Its state descriptor therefore contains the legacy digest;
    // reconstruct that exact value for rolling-upgrade validation. Current
    // payloads always validate through their persisted `duf2:` marker.
    return try document_unit_fingerprint.legacyFingerprintAlloc(alloc, unit);
}

fn storedUnitRequiredString(object: std.json.ObjectMap, name: []const u8) ![]const u8 {
    return (try storedUnitOptionalString(object, name)) orelse error.InvalidDocumentExtractionState;
}

fn storedUnitOptionalString(object: std.json.ObjectMap, name: []const u8) !?[]const u8 {
    const value = object.get(name) orelse return null;
    return switch (value) {
        .null => null,
        .string => |text| text,
        else => error.InvalidDocumentExtractionState,
    };
}

fn storedUnitRequiredBool(object: std.json.ObjectMap, name: []const u8) !bool {
    return (try storedUnitOptionalBool(object, name)) orelse error.InvalidDocumentExtractionState;
}

fn storedUnitOptionalBool(object: std.json.ObjectMap, name: []const u8) !?bool {
    const value = object.get(name) orelse return null;
    return switch (value) {
        .null => null,
        .bool => |boolean| boolean,
        else => error.InvalidDocumentExtractionState,
    };
}

fn storedUnitOptionalInteger(comptime T: type, object: std.json.ObjectMap, name: []const u8) !?T {
    const value = object.get(name) orelse return null;
    return switch (value) {
        .null => null,
        .integer => |integer| std.math.cast(T, integer) orelse error.InvalidDocumentExtractionState,
        .number_string => |text| std.fmt.parseInt(T, text, 10) catch error.InvalidDocumentExtractionState,
        else => error.InvalidDocumentExtractionState,
    };
}

fn storedUnitOptionalFloat(object: std.json.ObjectMap, name: []const u8) !?f64 {
    const value = object.get(name) orelse return null;
    return switch (value) {
        .null => null,
        .integer => |integer| @floatFromInt(integer),
        .float => |float| if (std.math.isFinite(float)) float else error.InvalidDocumentExtractionState,
        .number_string => |text| blk: {
            const parsed = std.fmt.parseFloat(f64, text) catch return error.InvalidDocumentExtractionState;
            if (!std.math.isFinite(parsed)) return error.InvalidDocumentExtractionState;
            break :blk parsed;
        },
        else => error.InvalidDocumentExtractionState,
    };
}

fn storedUnitOptionalBbox(object: std.json.ObjectMap, name: []const u8) !?[4]f64 {
    const value = object.get(name) orelse return null;
    if (value == .null) return null;
    if (value != .array or value.array.items.len != 4) return error.InvalidDocumentExtractionState;
    var bbox: [4]f64 = undefined;
    for (value.array.items, 0..) |coordinate, i| {
        bbox[i] = switch (coordinate) {
            .integer => |integer| @floatFromInt(integer),
            .float => |float| if (std.math.isFinite(float)) float else return error.InvalidDocumentExtractionState,
            .number_string => |text| std.fmt.parseFloat(f64, text) catch return error.InvalidDocumentExtractionState,
            else => return error.InvalidDocumentExtractionState,
        };
        if (!std.math.isFinite(bbox[i])) return error.InvalidDocumentExtractionState;
    }
    return bbox;
}

fn storedUnitTextRegionsAlloc(alloc: Allocator, value: ?std.json.Value) ![]document_extraction_mod.TextRegion {
    const regions_value = value orelse return &.{};
    if (regions_value == .null) return &.{};
    if (regions_value != .array) return error.InvalidDocumentExtractionState;
    const regions = try alloc.alloc(document_extraction_mod.TextRegion, regions_value.array.items.len);
    for (regions_value.array.items, 0..) |item, i| {
        if (item != .object) return error.InvalidDocumentExtractionState;
        const span_value = item.object.get("span") orelse return error.InvalidDocumentExtractionState;
        if (span_value != .array or span_value.array.items.len != 2) return error.InvalidDocumentExtractionState;
        const bbox = (try storedUnitOptionalBbox(item.object, "bbox")) orelse return error.InvalidDocumentExtractionState;
        regions[i] = .{
            .span = .{
                try storedUnitIntegerValue(u32, span_value.array.items[0]),
                try storedUnitIntegerValue(u32, span_value.array.items[1]),
            },
            .bbox = bbox,
        };
    }
    return regions;
}

fn storedUnitIntegerValue(comptime T: type, value: std.json.Value) !T {
    return switch (value) {
        .integer => |integer| std.math.cast(T, integer) orelse error.InvalidDocumentExtractionState,
        .number_string => |text| std.fmt.parseInt(T, text, 10) catch error.InvalidDocumentExtractionState,
        else => error.InvalidDocumentExtractionState,
    };
}

fn hexBytesAlloc(alloc: Allocator, bytes: []const u8) ![]u8 {
    const out = try alloc.alloc(u8, bytes.len * 2);
    for (bytes, 0..) |byte, idx| {
        out[idx * 2] = std.fmt.digitToChar(byte >> 4, .lower);
        out[idx * 2 + 1] = std.fmt.digitToChar(byte & 0x0f, .lower);
    }
    return out;
}

fn documentExtractionStateValueAlloc(
    alloc: Allocator,
    fingerprint: []const u8,
    unit_keys: []const []const u8,
    unit_descriptors: []const DocumentExtractionUnitDescriptor,
    chunk_keys: []const []const u8,
    navigation_digest: []const u8,
    navigation_block_count: u32,
    chunk_unit_fingerprints: bool,
) ![]u8 {
    return try std.json.Stringify.valueAlloc(alloc, .{
        .kind = "document_extraction_state_v1",
        .fingerprint = fingerprint,
        .unit_keys = unit_keys,
        .unit_descriptors = unit_descriptors,
        .chunk_keys = chunk_keys,
        .navigation_digest = navigation_digest,
        .navigation_block_count = navigation_block_count,
        .navigation_block_size = hierarchy_navigation_block_size,
        .chunk_unit_fingerprint_version = if (chunk_unit_fingerprints) document_unit_fingerprint.current_state_version else @as(u8, 0),
    }, .{});
}

fn documentExtractionStateHasChunkUnitFingerprints(alloc: Allocator, state: []const u8) bool {
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, state, .{}) catch return false;
    defer parsed.deinit();
    if (parsed.value != .object) return false;
    const version = parsed.value.object.get("chunk_unit_fingerprint_version") orelse return false;
    return document_unit_fingerprint.stateVersionIsCurrent(version);
}

fn documentExtractionStateHasNavigationMetadata(alloc: Allocator, state: []const u8) !bool {
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, state, .{}) catch
        return error.InvalidDocumentExtractionState;
    defer parsed.deinit();
    if (parsed.value != .object) return error.InvalidDocumentExtractionState;
    return parsed.value.object.get("navigation_digest") != null or
        parsed.value.object.get("navigation_block_count") != null or
        parsed.value.object.get("navigation_block_size") != null;
}

fn documentExtractionStateNavigationBlockCount(alloc: Allocator, state: []const u8) !u32 {
    var parsed = try std.json.parseFromSlice(std.json.Value, alloc, state, .{});
    defer parsed.deinit();
    if (parsed.value != .object) return 0;
    const value = parsed.value.object.get("navigation_block_count") orelse return 0;
    if (value != .integer) return error.InvalidDocumentExtractionState;
    return std.math.cast(u32, value.integer) orelse error.InvalidDocumentExtractionState;
}

fn documentExtractionStateFingerprintMatches(alloc: Allocator, state: []const u8, fingerprint: []const u8) bool {
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, state, .{}) catch return false;
    defer parsed.deinit();
    if (parsed.value != .object) return false;
    const value = parsed.value.object.get("fingerprint") orelse return false;
    return value == .string and std.mem.eql(u8, value.string, fingerprint);
}

fn documentExtractionStateUnitKeysAlloc(alloc: Allocator, state: []const u8) ![]const []const u8 {
    return try documentExtractionStateKeysAlloc(alloc, state, "unit_keys");
}

fn documentExtractionStateChunkKeysAlloc(alloc: Allocator, state: []const u8) ![]const []const u8 {
    return try documentExtractionStateKeysAlloc(alloc, state, "chunk_keys");
}

fn documentExtractionStateUnitDescriptorsAlloc(alloc: Allocator, state: []const u8) ![]DocumentExtractionUnitDescriptor {
    var parsed = try std.json.parseFromSlice(std.json.Value, alloc, state, .{});
    defer parsed.deinit();
    if (parsed.value != .object) return try alloc.alloc(DocumentExtractionUnitDescriptor, 0);
    const descriptors_value = parsed.value.object.get("unit_descriptors") orelse return documentExtractionStateUnitDescriptorFallbackAlloc(alloc, parsed.value.object);
    if (descriptors_value != .array) return error.InvalidDocumentExtractionState;
    const out = try alloc.alloc(DocumentExtractionUnitDescriptor, descriptors_value.array.items.len);
    var initialized: usize = 0;
    errdefer {
        for (out[0..initialized]) |descriptor| {
            alloc.free(@constCast(descriptor.key));
            alloc.free(@constCast(descriptor.fingerprint));
        }
        alloc.free(out);
    }
    for (descriptors_value.array.items, 0..) |item, i| {
        if (item != .object) return error.InvalidDocumentExtractionState;
        const key_value = item.object.get("key") orelse return error.InvalidDocumentExtractionState;
        const fingerprint_value = item.object.get("fingerprint") orelse return error.InvalidDocumentExtractionState;
        if (fingerprint_value != .string) return error.InvalidDocumentExtractionState;
        const key = try documentExtractionStateByteSliceAlloc(alloc, key_value);
        errdefer alloc.free(@constCast(key));
        const fingerprint = try alloc.dupe(u8, fingerprint_value.string);
        errdefer alloc.free(fingerprint);
        out[i] = .{
            .key = key,
            .fingerprint = fingerprint,
        };
        initialized += 1;
    }
    return out;
}

fn documentExtractionStateUnitDescriptorFallbackAlloc(alloc: Allocator, object: std.json.ObjectMap) ![]DocumentExtractionUnitDescriptor {
    const keys_value = object.get("unit_keys") orelse return try alloc.alloc(DocumentExtractionUnitDescriptor, 0);
    if (keys_value != .array) return try alloc.alloc(DocumentExtractionUnitDescriptor, 0);
    const out = try alloc.alloc(DocumentExtractionUnitDescriptor, keys_value.array.items.len);
    var initialized: usize = 0;
    errdefer {
        for (out[0..initialized]) |descriptor| {
            alloc.free(@constCast(descriptor.key));
            if (descriptor.fingerprint.len > 0) alloc.free(@constCast(descriptor.fingerprint));
        }
        alloc.free(out);
    }
    for (keys_value.array.items, 0..) |item, i| {
        out[i] = .{
            .key = try documentExtractionStateByteSliceAlloc(alloc, item),
            .fingerprint = "",
        };
        initialized += 1;
    }
    return out;
}

fn documentExtractionStateKeysAlloc(alloc: Allocator, state: []const u8, field_name: []const u8) ![]const []const u8 {
    var parsed = try std.json.parseFromSlice(std.json.Value, alloc, state, .{});
    defer parsed.deinit();
    if (parsed.value != .object) return try alloc.alloc([]const u8, 0);
    const keys_value = parsed.value.object.get(field_name) orelse return try alloc.alloc([]const u8, 0);
    if (keys_value != .array) return try alloc.alloc([]const u8, 0);
    const out = try alloc.alloc([]const u8, keys_value.array.items.len);
    var initialized: usize = 0;
    errdefer {
        for (out[0..initialized]) |key| alloc.free(@constCast(key));
        alloc.free(out);
    }
    for (keys_value.array.items, 0..) |item, i| {
        out[i] = try documentExtractionStateByteSliceAlloc(alloc, item);
        initialized += 1;
    }
    return out;
}

fn documentExtractionStateByteSliceAlloc(alloc: Allocator, value: std.json.Value) ![]const u8 {
    switch (value) {
        .string => |string| return try alloc.dupe(u8, string),
        .array => |array| {
            const out = try alloc.alloc(u8, array.items.len);
            errdefer alloc.free(out);
            for (array.items, 0..) |item, i| {
                if (item != .integer) return error.InvalidDocumentExtractionState;
                out[i] = std.math.cast(u8, item.integer) orelse return error.InvalidDocumentExtractionState;
            }
            return out;
        },
        else => return error.InvalidDocumentExtractionState,
    }
}

fn documentExtractionUnitKeyStillPresent(
    alloc: Allocator,
    doc_key: []const u8,
    artifact_name: []const u8,
    previous_key: []const u8,
    units: []const document_extraction_mod.Unit,
) !bool {
    for (units) |unit| {
        const key = try internal_keys.documentUnitArtifactKeyAlloc(alloc, doc_key, artifact_name, unit.unit_id);
        defer alloc.free(key);
        if (std.mem.eql(u8, previous_key, key)) return true;
    }
    return false;
}

fn documentUnitPayloadAlloc(
    alloc: Allocator,
