const PrecomputedGraphArtifactMutation = struct {
    key: []const u8,
    value: ?[]const u8,
};

const PrecomputedGraphStateUpdate = struct {
    state_key: []const u8,
    retired_alias_key: []const u8,
    state_value: []const u8,
    previous_keys: []const []const u8,
    graph_writes: []const docstore_mod.KVPair,
};

const PrecomputedGraphReconcileGroup = struct {
    doc_key: []const u8,
    index_name: []const u8,
    sources: []const index_manager_mod.GraphArtifactSource,
    generation: u64,
    edge_limit: usize,
    enforce_edge_limit: bool = false,
    updates: std.ArrayListUnmanaged(PrecomputedGraphStateUpdate) = .empty,
};

fn appendPrecomputedGraphSourceArtifacts(
    self: *DB,
    artifact_writes: []const types.BatchWrite,
    artifact_delete_keys: []const []const u8,
    owned_graph_artifact_writes: *std.ArrayListUnmanaged(types.BatchWrite),
    store_writes: *std.ArrayListUnmanaged(docstore_mod.KVPair),
    delete_keys: *std.ArrayListUnmanaged([]const u8),
    owned_delete_keys: *std.ArrayListUnmanaged([]u8),
    changed_artifact_keys: *std.ArrayListUnmanaged([]u8),
) !void {
    if (!self.core.hasGraphIndexes()) return;

    var arena_state = std.heap.ArenaAllocator.init(self.alloc);
    defer arena_state.deinit();
    const scratch = arena_state.allocator();

    // Coalesce before parsing. A batch is last-write-wins, and processing a
    // source state more than once can otherwise leave an intermediate edge
    // outside its final manifest.
    var mutations = std.ArrayListUnmanaged(PrecomputedGraphArtifactMutation).empty;
    var mutation_positions = std.StringHashMapUnmanaged(usize).empty;
    for (artifact_writes) |write| {
        if (mutation_positions.get(write.key)) |position| {
            mutations.items[position].value = write.value;
        } else {
            const position = mutations.items.len;
            try mutations.append(scratch, .{ .key = write.key, .value = write.value });
            try mutation_positions.put(scratch, write.key, position);
        }
    }
    for (artifact_delete_keys) |key| {
        if (mutation_positions.get(key)) |position| {
            mutations.items[position].value = null;
        } else {
            const position = mutations.items.len;
            try mutations.append(scratch, .{ .key = key, .value = null });
            try mutation_positions.put(scratch, key, position);
        }
    }

    var groups = std.ArrayListUnmanaged(PrecomputedGraphReconcileGroup).empty;
    var group_positions = std.StringHashMapUnmanaged(usize).empty;
    for (mutations.items) |mutation| {
        try preparePrecomputedGraphSourceArtifactMutation(
            self,
            scratch,
            mutation,
            &groups,
            &group_positions,
            store_writes,
            delete_keys,
            owned_delete_keys,
        );
    }

    var pending_graph_positions = StoreWritePositions.empty;
    defer pending_graph_positions.deinit(self.alloc);
    for (groups.items) |group| {
        try reconcilePrecomputedGraphGroup(
            self,
            scratch,
            group,
            owned_graph_artifact_writes,
            store_writes,
            &pending_graph_positions,
            delete_keys,
            owned_delete_keys,
            changed_artifact_keys,
        );
    }
}

fn preparePrecomputedGraphSourceArtifactMutation(
    self: *DB,
    scratch: Allocator,
    mutation: PrecomputedGraphArtifactMutation,
    groups: *std.ArrayListUnmanaged(PrecomputedGraphReconcileGroup),
    group_positions: *std.StringHashMapUnmanaged(usize),
    store_writes: *std.ArrayListUnmanaged(docstore_mod.KVPair),
    delete_keys: *std.ArrayListUnmanaged([]const u8),
    owned_delete_keys: *std.ArrayListUnmanaged([]u8),
) !void {
    var artifact_ref = (try decodeArtifactRefIfKnownAlloc(scratch, mutation.key)) orelse return;
    defer artifact_ref.deinit(scratch);

    for (self.core.graphIndexes()) |graph_entry| {
        const source = self.core.index_manager.graphArtifactSourceForArtifact(graph_entry.config.name, artifact_ref.name) orelse continue;
        if (!graphArtifactSourceConsumesRef(self.core.index_manager, source, artifact_ref)) continue;

        var graph_store_writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
        var graph_write_positions = StoreWritePositions.empty;

        if (mutation.value) |value| {
            const raw_doc = try batchDocumentValueForGraphSource(scratch, self.core.store, store_writes.items, artifact_ref.document_id);
            defer if (raw_doc) |doc_value| scratch.free(doc_value);
            const graph_writes = try graphWritesFromArtifactValueAlloc(scratch, graph_entry.config.name, artifact_ref.document_id, value, source, graphArtifactContentType(self.core.index_manager, source.artifact_name), raw_doc, graph_asset_state.effectiveEdgeLimit(graph_entry.max_edges_per_document));
            defer freeGraphWrites(scratch, graph_writes);
            for (graph_writes) |write| {
                const key = try internal_keys.graphEdgeArtifactKeyAlloc(scratch, write.source, write.index_name, write.edge_type, write.target);
                removePendingDeleteKey(self.alloc, delete_keys, owned_delete_keys, key);
                const payload = try enrichment_artifact_codec.encodeGraphEdgeAlloc(scratch, null, graph_entry.config.coverage_generation, write.weight, write.created_at, write.updated_at, write.metadata_json);
                try upsertPendingStoreWrite(scratch, &graph_store_writes, &graph_write_positions, key, payload);
            }
        }

        const state_name = try graphArtifactStateNameAlloc(scratch, artifact_ref);
        const state_key = try graphAssetStateKeyAlloc(scratch, artifact_ref.document_id, graph_entry.config.name, state_name);
        const previous_keys = try loadGraphAssetStateKeysAlloc(scratch, self.core.store, state_key, graph_entry.config.coverage_generation);
        const legacy_state_name = try graph_state_name.legacyArtifactAlloc(scratch, artifact_ref);
        const legacy_state_key = try graphAssetStateKeyAlloc(scratch, artifact_ref.document_id, graph_entry.config.name, legacy_state_name);
        const legacy_previous_keys = try loadGraphAssetStateKeysAlloc(scratch, self.core.store, legacy_state_key, graph_entry.config.coverage_generation);
        var all_previous_keys = std.ArrayListUnmanaged([]const u8).empty;
        if (previous_keys) |keys| try all_previous_keys.appendSlice(scratch, keys);
        if (legacy_previous_keys) |keys| for (keys) |key| {
            var duplicate = false;
            for (all_previous_keys.items) |existing| {
                if (std.mem.eql(u8, existing, key)) {
                    duplicate = true;
                    break;
                }
            }
            if (!duplicate) try all_previous_keys.append(scratch, key);
        };
        if (!containsDeleteKey(delete_keys.items, legacy_state_key)) {
            const owned_alias_key = try self.alloc.dupe(u8, legacy_state_key);
            try owned_delete_keys.append(self.alloc, owned_alias_key);
            try delete_keys.append(self.alloc, owned_alias_key);
        }
        if (previous_keys == null and legacy_previous_keys == null and self.core.index_manager.graphArtifactSources(graph_entry.config.name).len <= 1 and graphArtifactRefUsesDocumentWideFallback(artifact_ref)) {
            const protected_keys = try resolutionMentionStateKeysForGraphSourceAlloc(scratch, self.core.store, self.core.index_manager, artifact_ref.document_id, graph_entry.config.name, source);
            defer freeOwnedConstKeySlice(scratch, protected_keys);
            const existing = try collectGraphArtifactsForDocIndex(scratch, self.core.store, artifact_ref.document_id, graph_entry.config.name);
            defer docstore_mod.DocStore.freeResults(scratch, existing);
            for (existing) |entry| {
                if (containsStoreWriteKey(graph_store_writes.items, entry.key)) continue;
                if (containsOwnedKey(owned_delete_keys.items, entry.key)) continue;
                if (containsDeleteKey(protected_keys, entry.key)) continue;
                const owned_key = try self.alloc.dupe(u8, entry.key);
                try owned_delete_keys.append(self.alloc, owned_key);
                try delete_keys.append(self.alloc, owned_key);
            }
        }

        const group_key = try internal_keys.graphAssetStateIndexPrefixAlloc(scratch, artifact_ref.document_id, graph_entry.config.name);
        const group_position = if (group_positions.get(group_key)) |position| position else blk: {
            const position = groups.items.len;
            try groups.append(scratch, .{
                .doc_key = try scratch.dupe(u8, artifact_ref.document_id),
                .index_name = graph_entry.config.name,
                .sources = self.core.index_manager.graphArtifactSources(graph_entry.config.name),
                .generation = graph_entry.config.coverage_generation,
                .edge_limit = graph_asset_state.effectiveEdgeLimit(graph_entry.max_edges_per_document),
            });
            try group_positions.put(scratch, group_key, position);
            break :blk position;
        };
        const state_value = try encodeGraphAssetStateKeysAlloc(scratch, graph_entry.config.coverage_generation, graph_store_writes.items);
        groups.items[group_position].enforce_edge_limit = groups.items[group_position].enforce_edge_limit or mutation.value != null;
        try groups.items[group_position].updates.append(scratch, .{
            .state_key = state_key,
            .retired_alias_key = legacy_state_key,
            .state_value = state_value,
            .previous_keys = all_previous_keys.items,
            .graph_writes = try graph_store_writes.toOwnedSlice(scratch),
        });
    }
}

fn reconcilePrecomputedGraphGroup(
    self: *DB,
    scratch: Allocator,
    group: PrecomputedGraphReconcileGroup,
    owned_graph_artifact_writes: *std.ArrayListUnmanaged(types.BatchWrite),
    store_writes: *std.ArrayListUnmanaged(docstore_mod.KVPair),
    pending_graph_positions: *StoreWritePositions,
    delete_keys: *std.ArrayListUnmanaged([]const u8),
    owned_delete_keys: *std.ArrayListUnmanaged([]u8),
    changed_artifact_keys: *std.ArrayListUnmanaged([]u8),
) !void {
    const overrides = try scratch.alloc(docstore_mod.KVPair, group.updates.items.len);
    const retired_alias_keys = try scratch.alloc([]const u8, group.updates.items.len);
    var affected = std.ArrayListUnmanaged([]const u8).empty;
    var affected_set = std.StringHashMapUnmanaged(void).empty;
    for (group.updates.items, 0..) |update, i| {
        overrides[i] = .{ .key = update.state_key, .value = update.state_value };
        retired_alias_keys[i] = update.retired_alias_key;
        for (update.previous_keys) |key| {
            if (try affected_set.fetchPut(scratch, key, {}) == null) try affected.append(scratch, key);
        }
        for (update.graph_writes) |write| {
            if (try affected_set.fetchPut(scratch, write.key, {}) == null) try affected.append(scratch, write.key);
        }
    }

    var winners = try loadGraphEdgeWinnersWithOverrides(scratch, self.core.store, group.doc_key, group.index_name, overrides, retired_alias_keys, group.sources, group.generation);
    defer winners.deinit(scratch);
    if (group.enforce_edge_limit and winners.map.count() > group.edge_limit) return error.ResourceLimitExceeded;
    for (affected.items) |edge_key| {
        try appendUniqueOwnedKey(self.alloc, changed_artifact_keys, edge_key);
        if (winners.map.get(edge_key)) |winner| {
            removePendingDeleteKey(self.alloc, delete_keys, owned_delete_keys, edge_key);
            const owned_key = try self.alloc.dupe(u8, edge_key);
            var owned_key_owned = true;
            errdefer if (owned_key_owned) self.alloc.free(owned_key);
            const payload = try self.alloc.dupe(u8, winner.payload);
            var payload_owned = true;
            errdefer if (payload_owned) self.alloc.free(payload);
            try owned_graph_artifact_writes.append(self.alloc, .{ .key = owned_key, .value = payload });
            owned_key_owned = false;
            payload_owned = false;
            try upsertPendingStoreWrite(self.alloc, store_writes, pending_graph_positions, owned_key, payload);
        } else if (!containsOwnedKey(owned_delete_keys.items, edge_key)) {
            const owned_key = try self.alloc.dupe(u8, edge_key);
            try owned_delete_keys.append(self.alloc, owned_key);
            try delete_keys.append(self.alloc, owned_key);
        }
    }
    for (group.updates.items) |update| {
        const state_key = try self.alloc.dupe(u8, update.state_key);
        var state_key_owned = true;
        errdefer if (state_key_owned) self.alloc.free(state_key);
        const state_value = try self.alloc.dupe(u8, update.state_value);
        var state_value_owned = true;
        errdefer if (state_value_owned) self.alloc.free(state_value);
        try owned_graph_artifact_writes.append(self.alloc, .{ .key = state_key, .value = state_value });
        state_key_owned = false;
        state_value_owned = false;
        try upsertPendingStoreWrite(self.alloc, store_writes, pending_graph_positions, state_key, state_value);
    }
}

fn batchDocumentValueForGraphSource(
    alloc: Allocator,
    store: *docstore_mod.DocStore,
    store_writes: []const docstore_mod.KVPair,
    doc_key: []const u8,
) !?[]u8 {
    const internal_doc_key = try internal_keys.documentKeyAlloc(alloc, doc_key);
    defer alloc.free(internal_doc_key);
    for (store_writes) |write| {
        if (std.mem.eql(u8, write.key, internal_doc_key)) return try alloc.dupe(u8, write.value);
    }
    return try storeDocumentValueForGraphSource(alloc, store, doc_key);
}

fn storeDocumentValueForGraphSource(
    alloc: Allocator,
    store: *docstore_mod.DocStore,
    doc_key: []const u8,
) !?[]u8 {
    const internal_doc_key = try internal_keys.documentKeyAlloc(alloc, doc_key);
    defer alloc.free(internal_doc_key);
    return store.get(alloc, internal_doc_key) catch |err| switch (err) {
        error.NotFound => null,
        else => return err,
    };
}

fn graphArtifactContentType(index_manager: *const index_manager_mod.IndexManager, artifact_name: []const u8) []const u8 {
    if (index_manager.getEnrichment(.asset, artifact_name)) |cfg| return cfg.content_type;
    if (index_manager.getEnrichment(.chunk, artifact_name) != null) return "application/json";
    return "";
}

fn graphArtifactSourceConsumesRef(
    index_manager: *const index_manager_mod.IndexManager,
    source: index_manager_mod.GraphArtifactSource,
    artifact_ref: types.ArtifactRef,
) bool {
    if (!std.mem.eql(u8, source.artifact_name, artifact_ref.name)) return false;
    return switch (artifact_ref.kind) {
        .asset => graphAssetSourceConsumesAssetRef(index_manager, artifact_ref),
        .chunk => index_manager.getEnrichment(.chunk, artifact_ref.name) != null,
        .embedding => false,
    };
}

const GraphArtifactRefView = struct {
    name: []const u8,
    kind: types.ArtifactKind,
    unit_id_present: bool = false,
};

fn graphArtifactSourceConsumesArtifactKey(
    index_manager: *const index_manager_mod.IndexManager,
    source: index_manager_mod.GraphArtifactSource,
    artifact_key: []const u8,
) bool {
    if (decodeArtifactRefViewForGraphApplicability(artifact_key) catch null) |artifact_ref| {
        return graphArtifactSourceConsumesRefView(index_manager, source, artifact_ref);
    }

    var artifact_ref = (artifact_ids.decodeArtifactRefAlloc(index_manager.alloc, artifact_key) catch return false) orelse return false;
    defer artifact_ref.deinit(index_manager.alloc);
    return graphArtifactSourceConsumesRef(index_manager, source, artifact_ref);
}

fn graphArtifactSourceConsumesRefView(
    index_manager: *const index_manager_mod.IndexManager,
    source: index_manager_mod.GraphArtifactSource,
    artifact_ref: GraphArtifactRefView,
) bool {
    if (!std.mem.eql(u8, source.artifact_name, artifact_ref.name)) return false;
    return switch (artifact_ref.kind) {
        .asset => graphAssetSourceConsumesAssetRefView(index_manager, artifact_ref),
        .chunk => index_manager.getEnrichment(.chunk, artifact_ref.name) != null,
        .embedding => false,
    };
}

fn graphAssetSourceConsumesAssetRefView(index_manager: *const index_manager_mod.IndexManager, artifact_ref: GraphArtifactRefView) bool {
    if (index_manager.getEnrichment(.asset, artifact_ref.name) == null) return false;
    if (artifact_ref.unit_id_present) return true;
    const cfg = index_manager.getEnrichment(.asset, artifact_ref.name) orelse return false;
    var producer_cfg = asset_producer_mod.parseProducerConfig(index_manager.alloc, cfg.producer_json) catch return true;
    defer producer_cfg.deinit(index_manager.alloc);
    return producer_cfg.type != .document_extraction;
}

fn decodeArtifactRefViewForGraphApplicability(key: []const u8) !?GraphArtifactRefView {
    if (!internal_keys.isInternalUserKey(key)) return null;

    const doc_term = internal_keys.findComponentTerminator(key, 1) orelse return null;
    var pos = doc_term + 2;
    if (pos >= key.len or key[pos] != internal_keys.artifact_kind) return null;
    pos += 1;

    const type_term = internal_keys.findComponentTerminator(key, pos) orelse return error.InvalidInternalUserKey;
    const raw_kind = (try internal_keys.decodeBodyView(key[pos..type_term])) orelse return null;
    const kind = try artifactKindFromInternalLabel(raw_kind);
    pos = type_term + 2;

    const name_term = internal_keys.findComponentTerminator(key, pos) orelse return error.InvalidInternalUserKey;
    const name = (try internal_keys.decodeBodyView(key[pos..name_term])) orelse return null;
    pos = name_term + 2;

    var unit_id_present = false;
    if (kind == .asset and pos < key.len and key[pos] == internal_keys.document_unit_record_kind) {
        pos += 1;
        const unit_term = internal_keys.findComponentTerminator(key, pos) orelse return error.InvalidInternalUserKey;
        if ((try internal_keys.decodeBodyView(key[pos..unit_term])) == null) return null;
        pos = unit_term + 2;
        if (pos == key.len) return .{ .name = name, .kind = .asset, .unit_id_present = true };
    } else if (kind == .chunk) {
        if (pos < key.len and key[pos] == internal_keys.document_unit_record_kind) {
            pos += 1;
            const unit_term = internal_keys.findComponentTerminator(key, pos) orelse return error.InvalidInternalUserKey;
            if ((try internal_keys.decodeBodyView(key[pos..unit_term])) == null) return null;
            pos = unit_term + 2;
            unit_id_present = true;
        }
        if (pos + 1 + @sizeOf(u32) > key.len or key[pos] != internal_keys.chunk_record_kind) return error.InvalidInternalUserKey;
        pos += 1 + @sizeOf(u32);
        if (pos == key.len) return .{ .name = name, .kind = .chunk, .unit_id_present = unit_id_present };
    }

    if (pos == key.len) return .{ .name = name, .kind = kind, .unit_id_present = unit_id_present };
    if (key[pos] != internal_keys.derived_embedding_kind) return error.InvalidInternalUserKey;
    pos += 1;
    const derived_name_term = internal_keys.findComponentTerminator(key, pos) orelse return error.InvalidInternalUserKey;
    const derived_name = (try internal_keys.decodeBodyView(key[pos..derived_name_term])) orelse return null;
    if (derived_name_term + 2 != key.len) return error.InvalidInternalUserKey;
    return .{ .name = derived_name, .kind = .embedding };
}

fn artifactKindFromInternalLabel(raw_kind: []const u8) !types.ArtifactKind {
    if (std.mem.eql(u8, raw_kind, "chunk")) return .chunk;
    if (std.mem.eql(u8, raw_kind, "asset")) return .asset;
    if (std.mem.eql(u8, raw_kind, "embedding")) return .embedding;
    return error.InvalidInternalUserKey;
}

fn graphAssetSourceConsumesAssetRef(index_manager: *const index_manager_mod.IndexManager, artifact_ref: types.ArtifactRef) bool {
    if (index_manager.getEnrichment(.asset, artifact_ref.name) == null) return false;
    if (artifact_ref.unit_id != null) return true;
    const cfg = index_manager.getEnrichment(.asset, artifact_ref.name) orelse return false;
    var producer_cfg = asset_producer_mod.parseProducerConfig(index_manager.alloc, cfg.producer_json) catch return true;
    defer producer_cfg.deinit(index_manager.alloc);
    return producer_cfg.type != .document_extraction;
}

fn graphArtifactRefUsesDocumentWideFallback(artifact_ref: types.ArtifactRef) bool {
    return artifact_ref.kind == .asset and artifact_ref.unit_id == null and artifact_ref.chunk_id == null and artifact_ref.source == null;
}

fn graphArtifactStateNameAlloc(alloc: Allocator, artifact_ref: types.ArtifactRef) ![]u8 {
    return try graph_state_name.artifactAlloc(alloc, artifact_ref);
}

fn shouldPrecomputeGeneratedRequest(
    self: *DB,
    mode: GeneratedPrecomputeMode,
    request: enrichment_types.GeneratedEnrichmentRequest,
) !bool {
    _ = self;
    _ = request;
    return switch (mode) {
        .none => false,
        .all => true,
    };
}

const VisitState = enum { unvisited, visiting, done };

fn sortGraphQueriesByDependencies(alloc: Allocator, queries: []const types.NamedGraphQuery) ![]usize {
    return try db_query_graph.sortGraphQueriesByDependencies(alloc, queries);
}

fn visitGraphQuery(
    alloc: Allocator,
    queries: []const types.NamedGraphQuery,
    by_name: *std.StringHashMapUnmanaged(usize),
    states: []VisitState,
    sorted: *std.ArrayListUnmanaged(usize),
    index: usize,
) !void {
    switch (states[index]) {
        .done => return,
        .visiting => return error.GraphQueryCycle,
        .unvisited => {},
    }

    states[index] = .visiting;
    const query = queries[index];
    if (graphQueryDependencyName(query.query.start_nodes)) |dep_name| {
        if (by_name.get(dep_name)) |dep_index| try visitGraphQuery(alloc, queries, by_name, states, sorted, dep_index);
    }
    if (query.query.target_nodes) |target_nodes| {
        if (graphQueryDependencyName(target_nodes)) |dep_name| {
            if (by_name.get(dep_name)) |dep_index| try visitGraphQuery(alloc, queries, by_name, states, sorted, dep_index);
        }
    }
    states[index] = .done;
    try sorted.append(alloc, index);
}

fn graphQueryDependencyName(selector: graph_query_mod.NodeSelector) ?[]const u8 {
    return switch (selector) {
        .keys => null,
        .result_ref => |result_ref| blk: {
            if (std.mem.startsWith(u8, result_ref.ref, "$graph_results.")) {
                break :blk result_ref.ref["$graph_results.".len..];
            }
            break :blk null;
        },
    };
}

fn applyGraphUnion(alloc: Allocator, result: *types.SearchResult) !void {
    try db_query_graph.applyGraphUnion(alloc, result);
}

fn externalizeSearchResultArtifactIds(alloc: Allocator, result: *types.SearchResult) !void {
    try db_query_result_shape.externalizeSearchResultArtifactIds(alloc, result);
}

fn externalizeArtifactWritesAlloc(alloc: Allocator, writes: []types.BatchWrite) ![]types.ArtifactWrite {
    var out = try alloc.alloc(types.ArtifactWrite, writes.len);
    var initialized: usize = 0;
    errdefer {
        for (out[0..initialized]) |*write| write.deinit(alloc);
        alloc.free(out);
        for (writes[initialized..]) |write| {
            alloc.free(@constCast(write.key));
            alloc.free(@constCast(write.value));
        }
        alloc.free(writes);
    }

    for (writes, 0..) |write, i| {
        var identity = try artifact_ids.resolvePublicArtifactIdentityAlloc(alloc, write.key);
        defer identity.deinit(alloc);

        out[i] = .{
            .id = try alloc.dupe(u8, identity.id),
            .value = @constCast(write.value),
            .artifact_ref = try identity.artifact_ref.?.clone(alloc),
        };
        initialized += 1;
        alloc.free(@constCast(write.key));
    }

    alloc.free(writes);
    return out;
}

fn dedupeSearchHitsById(alloc: Allocator, result: *types.SearchResult) !void {
    try db_query_result_shape.dedupeSearchHitsById(alloc, result);
}

fn applyGraphIntersection(alloc: Allocator, result: *types.SearchResult) !void {
    try db_query_graph.applyGraphIntersection(alloc, result);
}

fn cloneNamedSetAsResult(alloc: Allocator, set: NamedResultSet, include_stored: bool) !types.SearchResult {
    return try db_query_graph.cloneNamedSetAsResult(alloc, set, include_stored);
}

fn currentTimeNs() u64 {
    return platform_clock.Clock.real().nowRealtimeNs();
}

fn nextArtifactRepairIssueTimestamp(previous: u64, observed_now: u64) u64 {
    // The realtime clock may have coarse resolution. Keep this revision field
    // strictly monotonic per issue so concurrent publication can never compare
    // equal to the stale revision a repair captured before provider work.
    return @max(observed_now, previous +| 1);
}

fn bytesToHexAlloc(alloc: Allocator, bytes: []const u8) ![]u8 {
    const out = try alloc.alloc(u8, bytes.len * 2);
    for (bytes, 0..) |byte, idx| {
        out[idx * 2] = std.fmt.digitToChar(byte >> 4, .lower);
        out[idx * 2 + 1] = std.fmt.digitToChar(byte & 0x0f, .lower);
    }
    return out;
}

fn hexToBytesAlloc(alloc: Allocator, hex: []const u8) ![]u8 {
    if (hex.len % 2 != 0) return error.InvalidArtifactPayload;
    const out = try alloc.alloc(u8, hex.len / 2);
    errdefer alloc.free(out);
    for (out, 0..) |*byte, i| {
        byte.* = try std.fmt.parseInt(u8, hex[i * 2 .. i * 2 + 2], 16);
    }
    return out;
}

fn makeTxnId(self: *DB) transactions_mod.TxnId {
    var txn_id: transactions_mod.TxnId = undefined;
    const now = currentTimeNs();
    const seq = self.core.nextDerivedAppendSequence();
    std.mem.writeInt(u64, txn_id[0..8], now, .little);
    std.mem.writeInt(u64, txn_id[8..16], seq, .little);
    return txn_id;
}

fn shouldWriteTimestamp(key: []const u8) bool {
    return !isMetadataKey(key) and !internal_keys.isInternalUserKey(key);
}

fn makeTimestampKey(alloc: Allocator, key: []const u8) ![]u8 {
    return try internal_keys.ttlKeyAlloc(alloc, key);
}

fn resolveWriteTimestampNs(self: *DB, fallback_timestamp_ns: u64, value_json: []const u8) !u64 {
    const schema = self.core.schema orelse return fallback_timestamp_ns;
    if (schema.ttl_duration_ns == 0) return fallback_timestamp_ns;
    return (try ttlTimestampNsFromDocumentValue(self.alloc, schema, value_json)) orelse fallback_timestamp_ns;
}

fn ttlTimestampNsFromDocumentValue(
    alloc: Allocator,
    schema: schema_mod.TableSchema,
    value_json: []const u8,
) !?u64 {
    var parsed = try std.json.parseFromSlice(std.json.Value, alloc, value_json, .{});
    defer parsed.deinit();
    const root = switch (parsed.value) {
        .object => |object| object,
        else => return null,
    };
    const ttl_value = root.get(schema.ttl_field) orelse return null;
    if (ttl_value == .null) return null;
    return try ttlTimestampNsFromJsonValue(ttl_value);
}

fn ttlTimestampNsFromJsonValue(value: std.json.Value) !u64 {
    return switch (value) {
        .integer => |integer| blk: {
            if (integer < 0) return error.InvalidArgument;
            break :blk std.math.cast(u64, integer) orelse return error.InvalidArgument;
        },
        .number_string => |text| std.fmt.parseInt(u64, std.mem.trim(u8, text, " \t\r\n"), 10) catch return error.InvalidArgument,
        .string => |text| ttlTimestampNsFromString(text),
        else => error.InvalidArgument,
    };
}

fn ttlTimestampNsFromString(text: []const u8) !u64 {
    const trimmed = std.mem.trim(u8, text, " \t\r\n");
    if (trimmed.len == 0) return error.InvalidArgument;
    if (std.fmt.parseInt(u64, trimmed, 10)) |ts| return ts else |_| {}
    if (try parsePatternRfc3339ToNs(trimmed)) |ts| return ts;
    return error.InvalidArgument;
}

fn encodeTimestampValue(alloc: Allocator, timestamp_ns: u64) ![]u8 {
    const buf = try alloc.alloc(u8, 8);
    std.mem.writeInt(u64, buf[0..8], timestamp_ns, .little);
    return buf;
}

fn ttlDurationNs(self: *DB) u64 {
    return if (self.core.schema) |schema| schema.ttl_duration_ns else 0;
}

fn isExpiredDocumentKey(self: *DB, alloc: Allocator, key: []const u8) !bool {
    const duration_ns = ttlDurationNs(self);
    if (duration_ns == 0) return false;
    const ts = try self.getTimestamp(alloc, key);
    if (ts == 0) return false;
    return ttl_mod.isExpired(ts, duration_ns, currentTimeNs());
}

fn loadDocumentTimestampsMany(self: *DB, alloc: Allocator, keys: []const []const u8) ![]u64 {
    const timestamps = try alloc.alloc(u64, keys.len);
    errdefer alloc.free(timestamps);
    @memset(timestamps, 0);
    if (keys.len == 0) return timestamps;

    const PendingTimestampLoad = struct {
        original_index: usize,
        store_key: []u8,
    };

    var pending = std.ArrayListUnmanaged(PendingTimestampLoad).empty;
    defer {
        for (pending.items) |item| alloc.free(item.store_key);
        pending.deinit(alloc);
    }

    for (keys, 0..) |key, i| {
        if (internal_keys.isInternalUserKey(key)) continue;
        try pending.append(alloc, .{
            .original_index = i,
            .store_key = try internal_keys.ttlKeyAlloc(alloc, key),
        });
    }
    if (pending.items.len == 0) return timestamps;

    std.mem.sort(PendingTimestampLoad, pending.items, {}, struct {
        fn lessThan(_: void, lhs: PendingTimestampLoad, rhs: PendingTimestampLoad) bool {
            return std.mem.order(u8, lhs.store_key, rhs.store_key) == .lt;
        }
    }.lessThan);

    const read_keys = try alloc.alloc([]const u8, pending.items.len);
    defer alloc.free(read_keys);
    const read_values = try alloc.alloc(?[]const u8, pending.items.len);
    defer alloc.free(read_values);
    @memset(read_values, null);

    for (pending.items, 0..) |item, i| read_keys[i] = item.store_key;

    var txn = try self.core.store.beginProbeTxn();
    defer txn.abort();
    try txn.getManySorted(read_keys, read_values);

    for (pending.items, 0..) |item, i| {
        const raw = read_values[i] orelse continue;
        if (raw.len != 8) continue;
        timestamps[item.original_index] = std.mem.readInt(u64, raw[0..8], .little);
    }
    return timestamps;
}

fn filterVisibleSearchHitsMany(self: *DB, alloc: Allocator, hits: []const types.SearchHit) ![]bool {
    const keep = try alloc.alloc(bool, hits.len);
    errdefer alloc.free(keep);
    @memset(keep, true);

    const duration_ns = ttlDurationNs(self);
    if (duration_ns == 0 or hits.len == 0) return keep;

    const expiry_now = currentTimeNs();
    const parent_ids = try alloc.alloc([]const u8, hits.len);
    defer alloc.free(parent_ids);

    const needs_stored = try alloc.alloc(bool, hits.len);
    defer alloc.free(needs_stored);
    @memset(needs_stored, false);

    const fallback_to_hit = try alloc.alloc(bool, hits.len);
    defer alloc.free(fallback_to_hit);
    @memset(fallback_to_hit, false);

    for (hits, 0..) |hit, i| {
        if (internal_keys.isChunkArtifactRecordKey(hit.id) or internal_keys.isAssetArtifactKey(hit.id)) {
            const parent = (try internal_keys.decodeDocumentComponentAlloc(alloc, hit.id)) orelse {
                fallback_to_hit[i] = true;
                parent_ids[i] = hit.id;
                continue;
            };
            parent_ids[i] = parent;
            continue;
        }
        if (hit.stored_data != null) {
            parent_ids[i] = parseChunkParentIdFromStoredAlloc(alloc, hit.stored_data.?) catch {
                fallback_to_hit[i] = true;
                parent_ids[i] = hit.id;
                continue;
            };
            continue;
        }
        needs_stored[i] = true;
        parent_ids[i] = hit.id;
    }
    defer {
        for (hits, 0..) |_, i| {
            if (!needs_stored[i] and !std.mem.eql(u8, parent_ids[i], hits[i].id)) alloc.free(parent_ids[i]);
        }
    }

    var pending_indices = std.ArrayListUnmanaged(usize).empty;
    defer pending_indices.deinit(alloc);
    for (needs_stored, 0..) |needed, i| if (needed) try pending_indices.append(alloc, i);
    if (pending_indices.items.len > 0) {
        const pending_keys = try alloc.alloc([]const u8, pending_indices.items.len);
        defer alloc.free(pending_keys);
        for (pending_indices.items, 0..) |hit_index, i| pending_keys[i] = hits[hit_index].id;

        const loaded = try loadStoredSearchDocumentsMany(self, alloc, pending_keys);
        defer freeOptionalOwnedBytes(alloc, loaded);
        for (pending_indices.items, 0..) |hit_index, i| {
            const stored = loaded[i] orelse {
                fallback_to_hit[hit_index] = true;
                continue;
            };
            parent_ids[hit_index] = parseChunkParentIdFromStoredAlloc(alloc, stored) catch {
                fallback_to_hit[hit_index] = true;
                continue;
            };
        }
    }

    const timestamps = try loadDocumentTimestampsMany(self, alloc, parent_ids);
    defer alloc.free(timestamps);
    for (timestamps, 0..) |ts, i| {
        if (ts == 0) continue;
        keep[i] = !ttl_mod.isExpired(ts, duration_ns, expiry_now);
    }
    return keep;
}

fn filterExpiredSearchResult(self: *DB, alloc: Allocator, raw: types.SearchResult) !types.SearchResult {
    if (ttlDurationNs(self) == 0) return raw;
    return try db_query_result_shape.filterVisibleSearchResult(alloc, raw, .{
        .ctx = self,
        .func = isVisibleSearchHitCallback,
        .filter_many = filterVisibleSearchHitsManyCallback,
    });
}

fn isVisibleSearchHit(self: *DB, alloc: Allocator, hit: types.SearchHit) !bool {
    return try db_query_result_shape.isVisibleSearchHit(alloc, hit, .{
        .ctx = self,
        .load_stored = loadStoredForHitCallback,
        .is_expired_key = isExpiredDocumentKeyCallback,
    });
}

fn isVisibleSearchHitCallback(
    ctx: ?*anyopaque,
    alloc: Allocator,
    hit: types.SearchHit,
) anyerror!bool {
    const self: *DB = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
    return try isVisibleSearchHit(self, alloc, hit);
}

fn filterVisibleSearchHitsManyCallback(
    ctx: ?*anyopaque,
    alloc: Allocator,
    hits: []const types.SearchHit,
) anyerror![]bool {
    const self: *DB = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
    return try filterVisibleSearchHitsMany(self, alloc, hits);
}

fn isVisibleNonChunkSearchHitCallback(
    ctx: ?*anyopaque,
    alloc: Allocator,
    hit: types.SearchHit,
) anyerror!bool {
    const self: *DB = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
    return !(try isExpiredDocumentKey(self, alloc, hit.id));
}

fn reshapeChunkBackedResult(self: *DB, alloc: Allocator, req: types.SearchRequest, raw: types.SearchResult) !types.SearchResult {
    return try db_query_result_shape.reshapeChunkBackedResult(alloc, req, raw, .{
        .ctx = self,
        .resolve_parent_id = resolveChunkParentIdCallback,
        .load_parent_stored = loadParentStoredForSearchCallback,
        .load_parent_stored_many = loadParentStoredForSearchManyCallback,
        .load_stored = loadStoredForHitCallback,
        .load_many_stored = loadStoredSearchDocumentManyCallback,
        .load_projected_stored = DB.loadProjectedSearchDocumentCallback,
        .load_many_projected_stored = DB.loadProjectedSearchDocumentManyCallback,
    });
}

const hierarchy_navigation_position_version = hierarchy_navigation.position_version;
const hierarchy_navigation_unit_fingerprint_field = hierarchy_navigation.unit_fingerprint_field;
const hierarchy_navigation_cancel_stride: usize = 64;
const hierarchy_navigation_block_size: u32 = 128;

const HierarchyNavigationArtifact = struct {
    name: []u8,
    generation: u64,
    digest: []u8,
    unit_count: u32,
    block_count: u32,
    block_size: u32,
    /// Legacy extraction states predate compact navigation blocks. They remain
    /// readable until their next extraction rewrites the state in indexed form.
    legacy_units: ?[]DocumentExtractionUnitDescriptor = null,

    fn deinit(self: *@This(), alloc: Allocator) void {
        alloc.free(self.name);
        alloc.free(self.digest);
        if (self.legacy_units) |units| freeDocumentExtractionUnitDescriptors(alloc, units);
        self.* = undefined;
    }
};

const HierarchyNavigationSummary = struct {
    generation: u64,
    digest: []u8,
    unit_count: u32,
    block_count: u32,
    block_size: u32,
};

fn validateHierarchyNavigationUnitDescriptor(
    alloc: Allocator,
    parent_id: []const u8,
    artifact_name: []const u8,
    unit: DocumentExtractionUnitDescriptor,
) !void {
    if (!internal_keys.isDocumentUnitArtifactRecordKey(unit.key) or unit.fingerprint.len == 0) {
        return error.InvalidDocumentExtractionState;
    }
    var unit_ref = (try artifact_ids.decodeArtifactRefAlloc(alloc, unit.key)) orelse
        return error.InvalidDocumentExtractionState;
    defer unit_ref.deinit(alloc);
    if (unit_ref.kind != .asset or unit_ref.unit_id == null or
        !std.mem.eql(u8, unit_ref.document_id, parent_id) or
        !std.mem.eql(u8, unit_ref.name, artifact_name))
    {
        return error.InvalidDocumentExtractionState;
    }
}

fn hierarchyNavigationArtifactBlockUnitsAlloc(
    self: *DB,
    alloc: Allocator,
    parent_id: []const u8,
    artifact: HierarchyNavigationArtifact,
    block_index: u32,
) ![]DocumentExtractionUnitDescriptor {
    if (block_index >= artifact.block_count or artifact.block_size != hierarchy_navigation_block_size) {
        return error.InvalidDocumentExtractionState;
    }
    const block_start = @as(usize, block_index) * @as(usize, artifact.block_size);
    const expected_len = @min(
        @as(usize, artifact.block_size),
        @as(usize, artifact.unit_count) - block_start,
    );
    const units = if (artifact.legacy_units) |legacy| blk: {
        const out = try alloc.alloc(DocumentExtractionUnitDescriptor, expected_len);
        var initialized: usize = 0;
        errdefer {
            for (out[0..initialized]) |descriptor| {
                alloc.free(@constCast(descriptor.key));
                alloc.free(@constCast(descriptor.fingerprint));
            }
            alloc.free(out);
        }
        for (legacy[block_start .. block_start + expected_len], 0..) |descriptor, i| {
            out[i] = .{
                .key = try alloc.dupe(u8, descriptor.key),
                .fingerprint = try alloc.dupe(u8, descriptor.fingerprint),
            };
            initialized += 1;
        }
        break :blk out;
    } else blk: {
        const block_key = try internal_keys.documentUnitNavigationBlockKeyAlloc(
            alloc,
            parent_id,
            artifact.name,
            block_index,
        );
        defer alloc.free(block_key);
        const raw = try self.core.getStoreValue(alloc, block_key) orelse
            return error.InvalidDocumentExtractionState;
        defer alloc.free(raw);
        break :blk try hierarchyNavigationBlockUnitsAlloc(alloc, raw, block_index, expected_len);
    };
    errdefer freeDocumentExtractionUnitDescriptors(alloc, units);
    for (units) |unit| try validateHierarchyNavigationUnitDescriptor(alloc, parent_id, artifact.name, unit);
    return units;
}

fn checkHierarchyNavigationCancelled(req: types.SearchRequest) !void {
    if (req.cancellation) |cancellation| {
        if (cancellation.isCancelled()) return error.Cancelled;
    }
    if (req.execution_deadline_ns) |deadline_ns| {
        if (platform_time.monotonicNs() >= deadline_ns) return error.Timeout;
    }
}

fn checkLookupOptionsActive(opts: types.LookupOptions) !void {
    if (opts.cancellation) |cancellation| {
        if (cancellation.isCancelled()) return error.Cancelled;
    }
    if (opts.execution_deadline_ns) |deadline_ns| {
        if (platform_time.monotonicNs() >= deadline_ns) return error.Timeout;
    }
}

fn hierarchyNavigationArtifactLessThan(_: void, left: HierarchyNavigationArtifact, right: HierarchyNavigationArtifact) bool {
    return std.mem.lessThan(u8, left.name, right.name);
}

const DocumentUnitHierarchyManifestInfo = struct {
    generation: u64,
    /// The last safely published hierarchy generation. An in-progress merge
    /// has no readable generation; a failed merge retains its prior revision.
    published_generation: ?u64,
};

fn documentUnitHierarchyManifestInfo(alloc: Allocator, manifest: []const u8) !DocumentUnitHierarchyManifestInfo {
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, manifest, .{}) catch
        return error.InvalidDocumentExtractionManifest;
    defer parsed.deinit();
    if (parsed.value != .object) return error.InvalidDocumentExtractionManifest;
    const artifact_type = parsed.value.object.get("artifact_type") orelse return error.InvalidDocumentExtractionManifest;
    if (artifact_type != .string) return error.InvalidDocumentExtractionManifest;
    if (!std.mem.eql(u8, artifact_type.string, "document_units")) return error.InvalidDocumentExtractionManifest;
    const generation = parsed.value.object.get("generation") orelse return error.InvalidDocumentExtractionManifest;
    if (generation != .integer or generation.integer < 0) return error.InvalidDocumentExtractionManifest;
    const generation_u64 = std.math.cast(u64, generation.integer) orelse return error.InvalidDocumentExtractionManifest;
    const merge_plan = parsed.value.object.get("merge_plan") orelse return error.InvalidDocumentExtractionManifest;
    if (merge_plan != .object) return error.InvalidDocumentExtractionManifest;
    const status = merge_plan.object.get("status") orelse return error.InvalidDocumentExtractionManifest;
    const from_generation = merge_plan.object.get("from_generation") orelse return error.InvalidDocumentExtractionManifest;
    const to_generation = merge_plan.object.get("to_generation") orelse return error.InvalidDocumentExtractionManifest;
    if (status != .string or from_generation != .integer or to_generation != .integer or
        from_generation.integer < 0 or to_generation.integer <= 0)
    {
        return error.InvalidDocumentExtractionManifest;
    }
    const from_generation_u64 = std.math.cast(u64, from_generation.integer) orelse
        return error.InvalidDocumentExtractionManifest;
    const to_generation_u64 = std.math.cast(u64, to_generation.integer) orelse
        return error.InvalidDocumentExtractionManifest;
    if (from_generation_u64 >= to_generation_u64) {
        return error.InvalidDocumentExtractionManifest;
    }
    if (std.mem.eql(u8, status.string, "converged")) {
        if (generation_u64 == 0 or to_generation_u64 != generation_u64) return error.InvalidDocumentExtractionManifest;
        return .{ .generation = generation_u64, .published_generation = generation_u64 };
    }
    if (std.mem.eql(u8, status.string, "failed")) {
        if (generation_u64 == 0 or to_generation_u64 != generation_u64) return error.InvalidDocumentExtractionManifest;
        // Streaming materialization may have flushed a prefix before failing.
        // The retained prior summary therefore cannot prove that every old
        // payload is intact; fail retryably until repair converges.
        return .{ .generation = generation_u64, .published_generation = null };
    }
    if (std.mem.eql(u8, status.string, "in_progress")) {
        if (from_generation_u64 != generation_u64) return error.InvalidDocumentExtractionManifest;
        return .{ .generation = generation_u64, .published_generation = null };
    }
    return error.InvalidDocumentExtractionManifest;
}

fn hierarchyNavigationSourceRevisionAlloc(
    alloc: Allocator,
    artifacts: []const HierarchyNavigationArtifact,
) ![]u8 {
    var hasher = std.crypto.hash.sha2.Sha256.init(.{});
    hasher.update(hierarchy_navigation_position_version);
    for (artifacts) |artifact| {
        var length: [8]u8 = undefined;
        std.mem.writeInt(u64, &length, @intCast(artifact.name.len), .big);
        hasher.update(&length);
        hasher.update(artifact.name);
        var generation: [8]u8 = undefined;
        std.mem.writeInt(u64, &generation, artifact.generation, .big);
        hasher.update(&generation);
        var unit_count: [8]u8 = undefined;
        std.mem.writeInt(u64, &unit_count, artifact.unit_count, .big);
        hasher.update(&unit_count);
        std.mem.writeInt(u64, &length, @intCast(artifact.digest.len), .big);
        hasher.update(&length);
        hasher.update(artifact.digest);
    }
    var digest: [std.crypto.hash.sha2.Sha256.digest_length]u8 = undefined;
    hasher.final(&digest);
    return try hexBytesAlloc(alloc, &digest);
}

fn hierarchyNavigationArtifactDigestAlloc(
    alloc: Allocator,
    units: []const DocumentExtractionUnitDescriptor,
) ![]u8 {
    var hasher = std.crypto.hash.sha2.Sha256.init(.{});
    hasher.update("antfly-hierarchy-artifact-v1");
    var encoded: [8]u8 = undefined;
    std.mem.writeInt(u64, &encoded, @intCast(units.len), .big);
    hasher.update(&encoded);
    for (units) |unit| {
        std.mem.writeInt(u64, &encoded, @intCast(unit.key.len), .big);
        hasher.update(&encoded);
        hasher.update(unit.key);
        std.mem.writeInt(u64, &encoded, @intCast(unit.fingerprint.len), .big);
        hasher.update(&encoded);
        hasher.update(unit.fingerprint);
    }
    var digest: [std.crypto.hash.sha2.Sha256.digest_length]u8 = undefined;
    hasher.final(&digest);
    return try hexBytesAlloc(alloc, &digest);
}

fn hierarchyNavigationDigestIsValid(digest: []const u8) bool {
    if (digest.len != std.crypto.hash.sha2.Sha256.digest_length * 2) return false;
    for (digest) |byte| {
        if (!((byte >= '0' and byte <= '9') or (byte >= 'a' and byte <= 'f'))) return false;
    }
    return true;
}

fn hierarchyNavigationSummaryValueAlloc(
    alloc: Allocator,
    generation: u64,
    digest: []const u8,
    unit_count: u32,
    block_count: u32,
) ![]u8 {
    if (generation == 0 or !hierarchyNavigationDigestIsValid(digest) or
        block_count != hierarchyNavigationBlockCount(unit_count))
    {
        return error.InvalidDocumentExtractionState;
    }
    return try std.json.Stringify.valueAlloc(alloc, .{
        .kind = "document_unit_navigation_summary_v1",
        .generation = generation,
        .digest = digest,
        .unit_count = unit_count,
        .block_count = block_count,
        .block_size = hierarchy_navigation_block_size,
    }, .{});
}

fn hierarchyNavigationSummaryParseAlloc(alloc: Allocator, raw: []const u8) !HierarchyNavigationSummary {
    var parsed = try std.json.parseFromSlice(std.json.Value, alloc, raw, .{});
    defer parsed.deinit();
    if (parsed.value != .object) return error.InvalidDocumentExtractionState;
    const object = parsed.value.object;
    const kind = object.get("kind") orelse return error.InvalidDocumentExtractionState;
    const generation = object.get("generation") orelse return error.InvalidDocumentExtractionState;
    const digest = object.get("digest") orelse return error.InvalidDocumentExtractionState;
    const unit_count = object.get("unit_count") orelse return error.InvalidDocumentExtractionState;
    const block_count = object.get("block_count") orelse return error.InvalidDocumentExtractionState;
    const block_size = object.get("block_size") orelse return error.InvalidDocumentExtractionState;
    if (kind != .string or !std.mem.eql(u8, kind.string, "document_unit_navigation_summary_v1") or
        generation != .integer or generation.integer <= 0 or
        digest != .string or !hierarchyNavigationDigestIsValid(digest.string) or
        unit_count != .integer or block_count != .integer or block_size != .integer)
    {
        return error.InvalidDocumentExtractionState;
    }
    const summary = HierarchyNavigationSummary{
        .generation = std.math.cast(u64, generation.integer) orelse return error.InvalidDocumentExtractionState,
        .digest = try alloc.dupe(u8, digest.string),
        .unit_count = std.math.cast(u32, unit_count.integer) orelse return error.InvalidDocumentExtractionState,
        .block_count = std.math.cast(u32, block_count.integer) orelse return error.InvalidDocumentExtractionState,
        .block_size = std.math.cast(u32, block_size.integer) orelse return error.InvalidDocumentExtractionState,
    };
    errdefer alloc.free(summary.digest);
    if (summary.block_size != hierarchy_navigation_block_size or
        summary.block_count != hierarchyNavigationBlockCount(summary.unit_count))
    {
        return error.InvalidDocumentExtractionState;
    }
    return summary;
}

fn hierarchyNavigationBlockCount(unit_count: u32) u32 {
    if (unit_count == 0) return 0;
    return std.math.divCeil(u32, unit_count, hierarchy_navigation_block_size) catch unreachable;
}

fn hierarchyNavigationBlockValueAlloc(
    alloc: Allocator,
    block_index: u32,
    units: []const DocumentExtractionUnitDescriptor,
) ![]u8 {
    return try std.json.Stringify.valueAlloc(alloc, .{
        .kind = "document_unit_navigation_block_v1",
        .block_index = block_index,
        .units = units,
    }, .{});
}

fn hierarchyNavigationBlockUnitsAlloc(
    alloc: Allocator,
    raw: []const u8,
    expected_block_index: u32,
    expected_len: usize,
) ![]DocumentExtractionUnitDescriptor {
    var parsed = try std.json.parseFromSlice(std.json.Value, alloc, raw, .{});
    defer parsed.deinit();
    if (parsed.value != .object) return error.InvalidDocumentExtractionState;
    const kind = parsed.value.object.get("kind") orelse return error.InvalidDocumentExtractionState;
    const block_index = parsed.value.object.get("block_index") orelse return error.InvalidDocumentExtractionState;
    const units = parsed.value.object.get("units") orelse return error.InvalidDocumentExtractionState;
    if (kind != .string or !std.mem.eql(u8, kind.string, "document_unit_navigation_block_v1") or
        block_index != .integer or std.math.cast(u32, block_index.integer) != expected_block_index or
        units != .array or units.array.items.len != expected_len)
    {
        return error.InvalidDocumentExtractionState;
    }
    const out = try alloc.alloc(DocumentExtractionUnitDescriptor, units.array.items.len);
    var initialized: usize = 0;
    errdefer {
        for (out[0..initialized]) |descriptor| {
            alloc.free(@constCast(descriptor.key));
            alloc.free(@constCast(descriptor.fingerprint));
        }
        alloc.free(out);
    }
    for (units.array.items, 0..) |item, i| {
        if (item != .object) return error.InvalidDocumentExtractionState;
        const key_value = item.object.get("key") orelse return error.InvalidDocumentExtractionState;
        const fingerprint_value = item.object.get("fingerprint") orelse return error.InvalidDocumentExtractionState;
        if (fingerprint_value != .string or fingerprint_value.string.len == 0) return error.InvalidDocumentExtractionState;
        out[i] = .{
            .key = try documentExtractionStateByteSliceAlloc(alloc, key_value),
            .fingerprint = try alloc.dupe(u8, fingerprint_value.string),
        };
        initialized += 1;
    }
    return out;
}

fn hierarchyNavigationPositionAlloc(
    alloc: Allocator,
    source_revision: []const u8,
    artifact_name: []const u8,
    generation: u64,
    ordinal: usize,
    unit_fingerprint: []const u8,
) ![]u8 {
    return hierarchy_navigation.positionAlloc(
        alloc,
        source_revision,
        artifact_name,
        generation,
        ordinal,
        unit_fingerprint,
    ) catch |err| switch (err) {
        error.InvalidHierarchyNavigationPosition => error.InvalidDocumentExtractionState,
        else => |other| other,
    };
}

fn hierarchyNavigationPositionParse(artifact_name: []const u8, position: []const u8) !hierarchy_navigation.Position {
    return hierarchy_navigation.parsePositionForArtifact(artifact_name, position) catch |err| switch (err) {
        error.InvalidHierarchyNavigationPosition => error.InvalidDocumentExtractionState,
        error.HierarchyNavigationPositionVersionStale => error.HierarchyCursorStale,
    };
}

fn hierarchyNavigationStoredUnitMatchesPosition(
    alloc: Allocator,
    stored: []const u8,
    artifact_name: []const u8,
    position: hierarchy_navigation.Position,
) !bool {
    var parsed = try std.json.parseFromSlice(std.json.Value, alloc, stored, .{});
    defer parsed.deinit();
    if (parsed.value != .object) return error.InvalidDocumentExtractionState;
    if (parsed.value.object.get(hierarchy_navigation_unit_fingerprint_field)) |fingerprint| {
        if (fingerprint != .string) return error.InvalidDocumentExtractionState;
        return hierarchy_navigation.positionUnitFingerprintMatches(position, artifact_name, fingerprint.string);
    }
    const actual = try documentExtractionStoredUnitFingerprintAlloc(alloc, stored);
    defer alloc.free(actual);
    return hierarchy_navigation.positionUnitFingerprintMatches(position, artifact_name, actual);
}

fn hierarchyUnitMatchFilterJsonAlloc(
    alloc: Allocator,
    existing_filter_json: []const u8,
    unit_key: []const u8,
) ![]u8 {
    const encoded_unit_key = try std.json.Stringify.valueAlloc(alloc, unit_key, .{});
    defer alloc.free(encoded_unit_key);
    var out = std.ArrayListUnmanaged(u8).empty;
    defer out.deinit(alloc);
    if (existing_filter_json.len > 0) {
        try out.appendSlice(alloc, "{\"bool\":{\"must\":[");
        try out.appendSlice(alloc, existing_filter_json);
        try out.append(alloc, ',');
    }
    try out.appendSlice(alloc, "{\"term\":{\"path\":\"/_parent_unit_key\",\"value\":");
    try out.appendSlice(alloc, encoded_unit_key);
    try out.appendSlice(alloc, "}}");
    if (existing_filter_json.len > 0) try out.appendSlice(alloc, "]}}");
    return try out.toOwnedSlice(alloc);
}

fn resolveChunkParentId(self: *DB, alloc: Allocator, hit: types.SearchHit) ![]u8 {
    return try db_query_result_shape.resolveChunkParentId(alloc, hit, .{
        .ctx = self,
        .load_stored = loadStoredForHitCallback,
    });
}

fn parseChunkParentIdFromStoredAlloc(alloc: Allocator, stored: []const u8) ![]u8 {
    const parsed = try std.json.parseFromSlice(std.json.Value, alloc, stored, .{});
    defer parsed.deinit();
    if (parsed.value != .object) return error.InvalidChunkArtifact;
    const parent = parsed.value.object.get("_parent_doc_key") orelse parsed.value.object.get("parent_doc_key") orelse return error.InvalidChunkArtifact;
    if (parent != .string) return error.InvalidChunkArtifact;
    return try alloc.dupe(u8, parent.string);
}

fn resolveChunkParentIdCallback(
    ctx: ?*anyopaque,
    alloc: Allocator,
    hit: types.SearchHit,
) anyerror![]u8 {
    const self: *DB = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
    return try resolveChunkParentId(self, alloc, hit);
}

fn loadParentStoredForSearchCallback(
    ctx: ?*anyopaque,
    alloc: Allocator,
    req: types.SearchRequest,
    parent_id: []const u8,
) anyerror!?[]u8 {
    const self: *DB = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
    return if (try self.loadStoredSearchDocumentProbe(alloc, parent_id)) |stored|
        try projectOwnedStoredBytesForSearch(self, alloc, req, parent_id, stored)
    else
        null;
}

fn loadParentStoredForSearchManyCallback(
    ctx: ?*anyopaque,
    alloc: Allocator,
    req: types.SearchRequest,
    parent_ids: []const []const u8,
) anyerror![]?[]u8 {
    const self: *DB = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
    return try self.loadProjectedSearchDocumentMany(alloc, req, parent_ids);
}

fn loadStoredForHitCallback(
    ctx: ?*anyopaque,
    alloc: Allocator,
    key: []const u8,
) anyerror!?[]u8 {
    const self: *DB = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
    return try self.loadStoredSearchDocumentProbe(alloc, key);
}

fn isExpiredDocumentKeyCallback(
    ctx: ?*anyopaque,
    alloc: Allocator,
    key: []const u8,
) anyerror!bool {
    const self: *DB = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
    return try isExpiredDocumentKey(self, alloc, key);
}

fn patternNodeFilterEvaluator(ctx: ?*anyopaque, key: []const u8, filter: graph_pattern_mod.NodeFilter) anyerror!bool {
    const active: *DB.PatternNodeFilterContext = @ptrCast(@alignCast(ctx orelse return error.UnsupportedNodeFilterQuery));
    return try matchesPatternNodeFilter(active, key, filter);
}

fn matchesPatternNodeFilter(active: *DB.PatternNodeFilterContext, key: []const u8, filter: graph_pattern_mod.NodeFilter) !bool {
    if (filter.filter_query_json == null) return true;
    const stored = (try active.db.get(active.db.alloc, key)) orelse return false;
    defer active.db.alloc.free(stored);
    const prepared = try active.cache.getOrPrepare(filter.filter_query_json.?);
    return try prepared.matchesStored(active.db.alloc, key, stored);
}

fn parsePatternRfc3339ToNs(text: []const u8) !?u64 {
    return try db_query_graph.parsePatternRfc3339ToNs(text);
}

fn appendDerivedTargetRefAlloc(
    alloc: Allocator,
    targets: *std.ArrayListUnmanaged(derived_types.DerivedTargetRef),
    kind: derived_types.DerivedTarget,
    index_name: []const u8,
) !void {
    const owned_index_name = try alloc.dupe(u8, index_name);
    errdefer alloc.free(owned_index_name);
    try targets.append(alloc, .{
        .kind = kind,
        .index_name = owned_index_name,
    });
}

fn appendOwnedConstBytes(
    alloc: Allocator,
    values: *std.ArrayListUnmanaged([]const u8),
    value: []const u8,
) !void {
    const owned = try alloc.dupe(u8, value);
    errdefer alloc.free(owned);
    try values.append(alloc, owned);
}

fn buildDerivedBatch(
    alloc: Allocator,
    req: types.BatchRequest,
    extracted: []const mapper.ExtractedWrite,
    deleted_artifact_keys: []const []u8,
    changed_artifact_keys: []const []u8,
) !derived_types.DerivedBatch {
    var documents = try alloc.alloc(derived_types.DerivedDocument, req.writes.len);
    var initialized: usize = 0;
    errdefer {
        for (documents[0..initialized]) |doc| derived_types.deinitDerivedDocument(alloc, doc);
        if (documents.len > 0) alloc.free(documents);
    }

    for (req.writes, 0..) |write, i| {
        var targets = std.ArrayListUnmanaged(derived_types.DerivedTargetRef).empty;
        defer targets.deinit(alloc);
        errdefer for (targets.items) |target| alloc.free(target.index_name);

        if (extracted[i].cleaned_value != null) {
            try appendDerivedTargetRefAlloc(alloc, &targets, .full_text, "*");
        }
        for (extracted[i].dense_embeddings) |embedding| {
            try appendDerivedTargetRefAlloc(alloc, &targets, .dense_vector, embedding.index_name);
        }
        for (extracted[i].sparse_embeddings) |embedding| {
            try appendDerivedTargetRefAlloc(alloc, &targets, .sparse_vector, embedding.index_name);
        }
        for (extracted[i].mentioned_graph_indexes) |index_name| {
            try appendDerivedTargetRefAlloc(alloc, &targets, .graph, index_name);
        }
        for (req.graph_writes) |graph_write| {
            if (std.mem.eql(u8, graph_write.source, write.key)) {
                try appendDerivedTargetRefAlloc(alloc, &targets, .graph, graph_write.index_name);
            }
        }

        const key = try alloc.dupe(u8, write.key);
        errdefer alloc.free(key);
        const owned_targets = try targets.toOwnedSlice(alloc);
        documents[i] = .{
            .key = key,
            .action = if (extracted[i].cleaned_value == null) .preserve_base_document else .upsert,
            .cleaned_value = null,
            .targets = owned_targets,
        };
        initialized += 1;
    }

    var deleted_keys = try alloc.alloc([]const u8, req.deletes.len + deleted_artifact_keys.len);
    var deleted_initialized: usize = 0;
    errdefer {
        for (deleted_keys[0..deleted_initialized]) |key| alloc.free(key);
        alloc.free(deleted_keys);
    }
    for (req.deletes, 0..) |key, i| {
        deleted_keys[i] = try alloc.dupe(u8, key);
        deleted_initialized += 1;
    }
    for (deleted_artifact_keys) |key| {
        deleted_keys[deleted_initialized] = try alloc.dupe(u8, key);
        deleted_initialized += 1;
    }

    var overwritten_doc_keys_list = std.ArrayListUnmanaged([]const u8).empty;
    defer overwritten_doc_keys_list.deinit(alloc);
    errdefer for (overwritten_doc_keys_list.items) |key| alloc.free(@constCast(key));
    for (req.writes, 0..) |write, i| {
        if (extracted[i].cleaned_value != null) {
            try appendOwnedConstBytes(alloc, &overwritten_doc_keys_list, write.key);
        }
    }

    var changed_artifact_keys_list = std.ArrayListUnmanaged([]const u8).empty;
    errdefer {
        for (changed_artifact_keys_list.items) |key| alloc.free(@constCast(key));
        changed_artifact_keys_list.deinit(alloc);
    }
    for (changed_artifact_keys) |key| {
        try appendOwnedConstBytes(alloc, &changed_artifact_keys_list, key);
    }
    for (deleted_artifact_keys) |key| {
        if (!internal_keys.isAssetArtifactKey(key) and !internal_keys.isGraphEdgeArtifactKey(key)) continue;
        try appendOwnedConstBytes(alloc, &changed_artifact_keys_list, key);
    }

    var graph_doc_clears = std.ArrayListUnmanaged(derived_types.DerivedGraphDocClear).empty;
    errdefer {
        for (graph_doc_clears.items) |clear| derived_types.deinitDerivedGraphDocClear(alloc, clear);
        graph_doc_clears.deinit(alloc);
    }
    for (req.writes, 0..) |write, i| {
        if (extracted[i].mentioned_graph_indexes.len == 0) continue;
        const clear = try derived_types.cloneDerivedGraphDocClear(alloc, .{
            .key = write.key,
            .index_names = extracted[i].mentioned_graph_indexes,
        });
        errdefer derived_types.deinitDerivedGraphDocClear(alloc, clear);
        try graph_doc_clears.append(alloc, clear);
    }

    var graph_writes = std.ArrayListUnmanaged(types.GraphEdgeWrite).empty;
    errdefer {
        for (graph_writes.items) |write| derived_types.deinitDerivedGraphWrite(alloc, write);
        graph_writes.deinit(alloc);
    }
    for (extracted) |item| {
        for (item.graph_writes) |write| {
            const cloned = try derived_types.cloneDerivedGraphWrite(alloc, write);
            errdefer derived_types.deinitDerivedGraphWrite(alloc, cloned);
            try graph_writes.append(alloc, cloned);
        }
    }
    for (req.graph_writes) |write| {
        const cloned = try derived_types.cloneDerivedGraphWrite(alloc, write);
        errdefer derived_types.deinitDerivedGraphWrite(alloc, cloned);
        try graph_writes.append(alloc, cloned);
    }

    var graph_deletes = std.ArrayListUnmanaged(types.GraphEdgeDelete).empty;
    errdefer {
        for (graph_deletes.items) |delete| derived_types.deinitDerivedGraphDelete(alloc, delete);
        graph_deletes.deinit(alloc);
    }
    for (req.graph_deletes) |delete| {
        const cloned = try derived_types.cloneDerivedGraphDelete(alloc, delete);
        errdefer derived_types.deinitDerivedGraphDelete(alloc, cloned);
        try graph_deletes.append(alloc, cloned);
    }

    var dense_embeddings = std.ArrayListUnmanaged(derived_types.DerivedDenseEmbeddingWrite).empty;
    errdefer {
        for (dense_embeddings.items) |embedding|
            derived_types.deinitDerivedDenseEmbedding(alloc, embedding);
        dense_embeddings.deinit(alloc);
    }
    for (extracted) |item| {
        for (item.dense_embeddings) |embedding| {
            const cloned = try derived_types.cloneDerivedDenseEmbedding(alloc, .{
                .index_name = embedding.index_name,
                .doc_key = embedding.doc_key,
                .artifact_key = embedding.artifact_key,
                .vector = if (embedding.artifact_key != null) &.{} else embedding.vector,
            });
            errdefer derived_types.deinitDerivedDenseEmbedding(alloc, cloned);
            try dense_embeddings.append(alloc, cloned);
        }
    }

    var sparse_embeddings = std.ArrayListUnmanaged(derived_types.DerivedSparseEmbeddingWrite).empty;
    errdefer {
        for (sparse_embeddings.items) |embedding|
            derived_types.deinitDerivedSparseEmbedding(alloc, embedding);
        sparse_embeddings.deinit(alloc);
    }
    for (extracted) |item| {
        for (item.sparse_embeddings) |embedding| {
            const cloned = try derived_types.cloneDerivedSparseEmbedding(alloc, .{
                .index_name = embedding.index_name,
                .doc_key = embedding.doc_key,
                .artifact_key = embedding.artifact_key,
                .indices = embedding.indices,
                .values = embedding.values,
            });
            errdefer derived_types.deinitDerivedSparseEmbedding(alloc, cloned);
            try sparse_embeddings.append(alloc, cloned);
        }
    }

    const overwritten_doc_keys = try overwritten_doc_keys_list.toOwnedSlice(alloc);
    errdefer {
        for (overwritten_doc_keys) |key| alloc.free(@constCast(key));
        if (overwritten_doc_keys.len > 0) alloc.free(overwritten_doc_keys);
    }
    const owned_changed_artifact_keys = try changed_artifact_keys_list.toOwnedSlice(alloc);
    errdefer {
        for (owned_changed_artifact_keys) |key| alloc.free(@constCast(key));
        if (owned_changed_artifact_keys.len > 0) alloc.free(owned_changed_artifact_keys);
    }
    const owned_graph_doc_clears = try graph_doc_clears.toOwnedSlice(alloc);
    errdefer {
        for (owned_graph_doc_clears) |clear| derived_types.deinitDerivedGraphDocClear(alloc, clear);
        if (owned_graph_doc_clears.len > 0) alloc.free(owned_graph_doc_clears);
    }
    const owned_dense_embeddings = try dense_embeddings.toOwnedSlice(alloc);
    errdefer {
        for (owned_dense_embeddings) |embedding|
            derived_types.deinitDerivedDenseEmbedding(alloc, embedding);
        if (owned_dense_embeddings.len > 0) alloc.free(owned_dense_embeddings);
    }
    const owned_sparse_embeddings = try sparse_embeddings.toOwnedSlice(alloc);
    errdefer {
        for (owned_sparse_embeddings) |embedding|
            derived_types.deinitDerivedSparseEmbedding(alloc, embedding);
        if (owned_sparse_embeddings.len > 0) alloc.free(owned_sparse_embeddings);
    }
    const owned_graph_writes = try graph_writes.toOwnedSlice(alloc);
    errdefer {
        for (owned_graph_writes) |write| derived_types.deinitDerivedGraphWrite(alloc, write);
        if (owned_graph_writes.len > 0) alloc.free(owned_graph_writes);
    }
    const owned_graph_deletes = try graph_deletes.toOwnedSlice(alloc);
    errdefer {
        for (owned_graph_deletes) |delete| derived_types.deinitDerivedGraphDelete(alloc, delete);
        if (owned_graph_deletes.len > 0) alloc.free(owned_graph_deletes);
    }

    return .{
        .sequence = 0,
        .documents = documents,
        .deleted_keys = deleted_keys,
        .overwritten_doc_keys = overwritten_doc_keys,
        .changed_artifact_keys = owned_changed_artifact_keys,
        .graph_doc_clears = owned_graph_doc_clears,
        .dense_embeddings = owned_dense_embeddings,
        .sparse_embeddings = owned_sparse_embeddings,
        .generated_enrichment_refs = &.{},
        .graph_writes = owned_graph_writes,
        .graph_deletes = owned_graph_deletes,
    };
}

fn appendGeneratedEnrichments(
    self: *DB,
    batch: *derived_types.DerivedBatch,
    req: types.BatchRequest,
    extracted: []const mapper.ExtractedWrite,
    force_generated_artifact_names: []const []const u8,
    skip_terminally_covered: bool,
) !void {
    var planned = std.ArrayListUnmanaged(enrichment_types.GeneratedEnrichmentRef).empty;
    errdefer {
        for (planned.items) |request| enrichment_types.freeGeneratedRef(self.alloc, request);
        planned.deinit(self.alloc);
    }

    for (req.writes, 0..) |write, i| {
        const cleaned = extracted[i].cleaned_value orelse continue;
        var explicit_dense = std.ArrayListUnmanaged(types.EnrichmentDenseEmbeddingWrite).empty;
        defer {
            for (explicit_dense.items) |*embedding| embedding.deinit(self.alloc);
            explicit_dense.deinit(self.alloc);
        }
        for (extracted[i].dense_embeddings) |embedding| {
            try appendClonedExplicitDenseEmbedding(
                self.alloc,
                &explicit_dense,
                embedding.index_name,
                embedding.doc_key,
                embedding.vector,
            );
        }
        var explicit_sparse = std.ArrayListUnmanaged(types.EnrichmentSparseEmbeddingWrite).empty;
        defer {
            for (explicit_sparse.items) |*embedding| embedding.deinit(self.alloc);
            explicit_sparse.deinit(self.alloc);
        }
        for (extracted[i].sparse_embeddings) |embedding| {
            try appendClonedExplicitSparseEmbedding(
                self.alloc,
                &explicit_sparse,
                embedding.index_name,
                embedding.doc_key,
                embedding.indices,
                embedding.values,
            );
        }
        const generated = try self.core.planGeneratedEnrichments(
            self.alloc,
            write.key,
            cleaned,
            explicit_dense.items,
            explicit_sparse.items,
        );
        defer enrichment_types.deinitGeneratedRequests(self.alloc, generated);
        for (generated) |request| {
            if (!generatedRequestMatchesForcedArtifact(force_generated_artifact_names, request)) continue;
            if (skip_terminally_covered and try generatedRequestHasTerminalCoverage(self, request)) continue;
            try appendGeneratedEnrichmentRef(self.alloc, &planned, request);
        }
    }

    batch.generated_enrichment_refs = try planned.toOwnedSlice(self.alloc);
}

fn generatedRequestHasTerminalCoverage(self: *DB, request: enrichment_types.GeneratedEnrichmentRequest) !bool {
    const index_names = switch (request.kind) {
        .dense_embedding => try self.core.index_manager.denseIndexesForEmbedding(self.alloc, requestEmbeddingName(request), request.expected_dims),
        .sparse_embedding => try self.core.index_manager.sparseIndexesForEmbedding(self.alloc, requestEmbeddingName(request)),
        .chunk_text => try self.core.index_manager.vectorIndexesForChunk(self.alloc, requestArtifactName(request)),
        .asset => try self.core.index_manager.vectorIndexesDependingOnArtifact(self.alloc, requestArtifactName(request)),
    };
    defer {
        for (index_names) |index_name| self.alloc.free(index_name);
        self.alloc.free(index_names);
    }
    if (index_names.len == 0) return false;

    for (index_names) |index_name| {
        const generation = self.core.index_manager.coverageGenerationForIndex(index_name) orelse return false;
        const marker_key = try internal_keys.derivedCoverageOutcomeKeyAlloc(self.alloc, index_name, generation, request.doc_key);
        defer self.alloc.free(marker_key);
        const outcome = self.core.store.get(self.alloc, marker_key) catch |err| switch (err) {
            error.NotFound => return false,
            else => return err,
        };
        defer self.alloc.free(outcome);
        if (std.meta.stringToEnum(DerivedCoverageOutcome, outcome) == null) return error.InvalidDerivedCoverageOutcome;
    }
    return true;
}

fn collectEnrichmentArtifactDeletesForBatch(
    self: *DB,
    req: types.BatchRequest,
    extracted: []const mapper.ExtractedWrite,
    delete_keys: *std.ArrayListUnmanaged([]const u8),
    owned_delete_keys: *std.ArrayListUnmanaged([]u8),
) ![][]u8 {
    _ = extracted;
    if (!self.core.hasArtifactCleanupMaybe()) return try self.alloc.alloc([]u8, 0);

    var deleted = std.ArrayListUnmanaged([]u8).empty;
    errdefer deleted.deinit(self.alloc);
    var seen_docs = std.StringHashMapUnmanaged(void).empty;
    defer seen_docs.deinit(self.alloc);

    for (req.deletes) |key| {
        const gop = try seen_docs.getOrPut(self.alloc, key);
        if (gop.found_existing) continue;
        try collectEnrichmentArtifactDeleteKeysForDocContext(
            self.alloc,
            self.core.store,
            key,
            delete_keys,
            owned_delete_keys,
            &deleted,
        );
    }
    return try deleted.toOwnedSlice(self.alloc);
}

fn collectEnrichmentArtifactDeleteKeysForDocContext(
    alloc: Allocator,
    store: *docstore_mod.DocStore,
    doc_key: []const u8,
    delete_keys: *std.ArrayListUnmanaged([]const u8),
    owned_delete_keys: *std.ArrayListUnmanaged([]u8),
    deleted_artifact_keys: *std.ArrayListUnmanaged([]u8),
) !void {
    const artifact_prefix = try internal_keys.artifactRootPrefixAlloc(alloc, doc_key);
    defer alloc.free(artifact_prefix);
    try collectDeleteKeysForPrefix(
        alloc,
        store,
        artifact_prefix,
        delete_keys,
        owned_delete_keys,
        deleted_artifact_keys,
    );

    const asset_state_prefix = try internal_keys.assetStateRootPrefixAlloc(alloc, doc_key);
    defer alloc.free(asset_state_prefix);
    try collectDeleteKeysForPrefix(alloc, store, asset_state_prefix, delete_keys, owned_delete_keys, null);

    const graph_asset_state_prefix = try internal_keys.graphAssetStateRootPrefixAlloc(alloc, doc_key);
    defer alloc.free(graph_asset_state_prefix);
    try collectDeleteKeysForPrefix(alloc, store, graph_asset_state_prefix, delete_keys, owned_delete_keys, null);
}

fn collectDeleteKeysForPrefix(
    alloc: Allocator,
    store: *docstore_mod.DocStore,
    prefix: []const u8,
    deletes: *std.ArrayListUnmanaged([]const u8),
    owned_delete_keys: *std.ArrayListUnmanaged([]u8),
    recorded: ?*std.ArrayListUnmanaged([]u8),
) !void {
    const existing = try store.scanPrefix(alloc, prefix);
    defer docstore_mod.DocStore.freeResults(alloc, existing);
    for (existing) |entry| {
        const owned = try alloc.dupe(u8, entry.key);
        errdefer alloc.free(owned);
        try owned_delete_keys.append(alloc, owned);
        errdefer _ = owned_delete_keys.pop();
        try deletes.append(alloc, owned);
        errdefer _ = deletes.pop();
        if (recorded) |out| try out.append(alloc, owned);
    }
}

fn collectGraphArtifactsForDocIndex(
    alloc: Allocator,
    store: *docstore_mod.DocStore,
    doc_key: []const u8,
    index_name: []const u8,
) ![]docstore_mod.OwnedKVPair {
    const prefix = try internal_keys.graphArtifactIndexPrefixAlloc(alloc, doc_key, index_name);
    defer alloc.free(prefix);
    return try store.scanPrefix(alloc, prefix);
}

fn executeDeleteBatchContext(ctx: *const BatchExecutionContext, keys: []const []const u8, sync_level: types.SyncLevel) !void {
    if (keys.len == 0) return;
    var ha_mutation = acquireHAMutationSharedContext(ctx);
    defer if (ha_mutation) |*lease| lease.release();
    try enforceHAWriteGateOptional(ctx.ha_write_gate);
    ctx.apply_mutex.lockExclusive();
    var apply_mutex_held = true;
    errdefer if (apply_mutex_held) ctx.apply_mutex.unlockExclusive();

    var store_writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
    defer store_writes.deinit(ctx.alloc);
    var owned_store_keys = std.ArrayListUnmanaged([]u8).empty;
    defer {
        for (owned_store_keys.items) |key| ctx.alloc.free(key);
        owned_store_keys.deinit(ctx.alloc);
    }
    var owned_store_values = std.ArrayListUnmanaged([]u8).empty;
    defer {
        for (owned_store_values.items) |value| ctx.alloc.free(value);
        owned_store_values.deinit(ctx.alloc);
    }
    var identity_writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
    defer {
        for (identity_writes.items) |item| {
            ctx.alloc.free(@constCast(item.key));
            ctx.alloc.free(@constCast(item.value));
        }
        identity_writes.deinit(ctx.alloc);
    }
    var identity_visibility_deletes = std.ArrayListUnmanaged([]u8).empty;
    defer {
        for (identity_visibility_deletes.items) |key| ctx.alloc.free(key);
        identity_visibility_deletes.deinit(ctx.alloc);
    }
    var delete_keys = std.ArrayListUnmanaged([]const u8).empty;
    defer delete_keys.deinit(ctx.alloc);
    var timestamp_delete_keys = std.ArrayListUnmanaged([]const u8).empty;
    defer {
        for (timestamp_delete_keys.items) |key| ctx.alloc.free(@constCast(key));
        timestamp_delete_keys.deinit(ctx.alloc);
    }
    var owned_delete_keys = std.ArrayListUnmanaged([]u8).empty;
    defer {
        for (owned_delete_keys.items) |key| ctx.alloc.free(key);
        owned_delete_keys.deinit(ctx.alloc);
    }

    for (keys) |key| {
        const store_key = try internal_keys.documentKeyAlloc(ctx.alloc, key);
        try owned_delete_keys.append(ctx.alloc, store_key);
        try delete_keys.append(ctx.alloc, store_key);
        if (!shouldWriteTimestamp(key)) continue;
        const timestamp_key = try makeTimestampKey(ctx.alloc, key);
        try timestamp_delete_keys.append(ctx.alloc, timestamp_key);
        try delete_keys.append(ctx.alloc, timestamp_key);
    }

    var deleted_artifact_keys = std.ArrayListUnmanaged([]u8).empty;
    defer deleted_artifact_keys.deinit(ctx.alloc);
    const should_scan_artifacts = if (ctx.artifact_cleanup_maybe) |artifact_cleanup_maybe|
        artifact_cleanup_maybe.load(.acquire) or ctx.index_manager.hasGeneratedEnrichmentTargets()
    else
        true;
    if (should_scan_artifacts) {
        var seen_docs = std.StringHashMapUnmanaged(void).empty;
        defer seen_docs.deinit(ctx.alloc);
        for (keys) |key| {
            const gop = try seen_docs.getOrPut(ctx.alloc, key);
            if (gop.found_existing) continue;
            try collectEnrichmentArtifactDeleteKeysForDocContext(
                ctx.alloc,
                ctx.store,
                key,
                &delete_keys,
                &owned_delete_keys,
                &deleted_artifact_keys,
            );
        }
    }
    const req = types.BatchRequest{
        .deletes = keys,
        .sync_level = sync_level,
    };
    var derived_batch = try buildDerivedBatch(ctx.alloc, req, &.{}, deleted_artifact_keys.items, &.{});
    defer derived_types.deinitDerivedBatch(ctx.alloc, &derived_batch);
    const sequence = ctx.store.reserveNextReplaySequence(1);
    derived_batch.sequence = sequence;
    const identity_live_before = (try doc_identity.fastStatsFromStore(ctx.store)).live_ordinals;
    try doc_identity.appendBatchIdentityMetadataForNamespaceWithVisibilityDeletesAlloc(
        ctx.alloc,
        ctx.store,
        ctx.identity_namespace,
        sequence,
        &identity_writes,
        &identity_visibility_deletes,
        &.{},
        keys,
    );
    const pending_identity_visibility_summary = try doc_identity.visibilitySummaryFromWrites(identity_writes.items);
    if (pending_identity_visibility_summary) |summary| {
        try range_cardinality.appendIdentityTransitionAlloc(
            ctx.alloc,
            ctx.store,
            ctx.index_manager.byte_range,
            identity_live_before,
            summary.live_ordinals,
            &identity_writes,
        );
    }
    try store_writes.appendSlice(ctx.alloc, identity_writes.items);
    try appendAssetArtifactSourceIndexMutations(
        ctx.alloc,
        &store_writes,
        deleted_artifact_keys.items,
        &delete_keys,
        &owned_store_keys,
        &owned_store_values,
        &owned_delete_keys,
    );
    try DB.appendDenseArtifactCounterMutations(
        ctx.alloc,
        ctx.store,
        ctx.index_manager,
        &store_writes,
        delete_keys.items,
        &owned_store_keys,
        &owned_store_values,
    );
    try delete_keys.appendSlice(ctx.alloc, identity_visibility_deletes.items);
    const replay_payload = try encodeChangeRecordPayload(ctx, derived_batch, sequence);
    defer ctx.alloc.free(replay_payload);
    try ctx.store.putBatchWithReplay(ctx.io, store_writes.items, delete_keys.items, .{
        .sequence = sequence,
        .payload = replay_payload,
    });
    if (pending_identity_visibility_summary) |summary| {
        if (ctx.identity_visibility_owner_slot) |slot| {
            if (slot.load(.acquire)) |owner| {
                owner.identity_visibility_summary_cache = summary;
                owner.clearLiveDocSetCache();
                owner.clearNonVisibleDocSetCache();
            }
        }
    }
    ctx.apply_mutex.unlockExclusive();
    apply_mutex_held = false;
    try mirrorHAReplayPayloadCommitContext(ctx, replay_payload);
    var sync_targets = try collectManagedSyncTargets(ctx.alloc, ctx.index_manager, derived_batch);
    defer sync_targets.deinit(ctx.alloc);
    ctx.executor.trackBacklogBytes(sequence, @intCast(replay_payload.len)) catch {};
    try markPrecomputedEnrichmentAppliedForSyncContext(ctx, sync_level, sequence);
    try applyDerivedBacklogPressureContext(ctx, sequence, sync_level, sync_targets);
    if (ctx.executor.hasWorkers()) {
        notifyExecutorForSyncLevelWithDenseBulkDeferral(ctx.async_context, ctx.executor, sync_level, sequence, sync_targets);
        try waitForSyncLevelContext(ctx, sync_level, sequence, sync_targets);
    } else {
        if (syncLevelRequiresDerivedVisibility(sync_level)) {
            ctx.apply_mutex.lockExclusive();
            defer ctx.apply_mutex.unlockExclusive();
            if (sync_level == .full_text) {
                try applyDerivedBatchTargetsContext(ctx, derived_batch, sync_targets.full_text_indexes);
            } else {
                try applyDerivedBatchContext(ctx, derived_batch);
            }
        }
        try waitForSyncLevelContext(ctx, sync_level, sequence, sync_targets);
    }
    if (ctx.enrichment_runtime) |runtime| runtime.notifySequence(sequence);
    notifyResolverReplayRuntimesForCatalog(ctx.index_manager, ctx.resolution_runtime, ctx.promotion_runtime, sequence);
}

fn deleteExpiredDocumentsFromCandidates(ctx_ptr: *anyopaque, candidates: []const ttl_runtime_mod.DeleteCandidate) !u32 {
    const ctx: *TtlCleanupContext = @ptrCast(@alignCast(ctx_ptr));
    const loaded_schema = try schema_mod.loadSchema(ctx.batch.store, ctx.batch.alloc);
    defer if (loaded_schema) |schema| schema_mod.freeSchema(ctx.batch.alloc, schema);

    const duration_ns = if (loaded_schema) |schema|
        schema.ttl_duration_ns
    else
        0;
    if (duration_ns == 0) return 0;

    const now_ns = currentTimeNs();
    var deletes = std.ArrayListUnmanaged([]const u8).empty;
    defer deletes.deinit(ctx.batch.alloc);

    for (candidates) |candidate| {
        const current_ts = (try ttl_mod.readTimestamp(ctx.batch.store, ctx.batch.alloc, candidate.key)) orelse continue;
        if (current_ts != candidate.timestamp_ns) continue;
        if (!ttl_mod.isExpiredWithGrace(current_ts, duration_ns, ctx.grace_period_ns, now_ns)) continue;
        try deletes.append(ctx.batch.alloc, candidate.key);
    }
    if (deletes.items.len == 0) return 0;

    try executeDeleteBatchContext(&ctx.batch, deletes.items, .full_index);
    return @intCast(deletes.items.len);
}

fn appendDerivedBatchRecord(self: *DB, batch: derived_types.DerivedBatch) !u64 {
    var ctx = self.batchContext();
    return try appendDerivedBatchRecordContext(&ctx, batch);
}

fn appendDerivedBatchRecordContext(ctx: *const BatchExecutionContext, batch: derived_types.DerivedBatch) !u64 {
    var ha_mutation = acquireHAMutationSharedContext(ctx);
    defer if (ha_mutation) |*lease| lease.release();
    try enforceHAWriteGateOptional(ctx.ha_write_gate);
    ctx.apply_mutex.lockExclusive();
    defer ctx.apply_mutex.unlockExclusive();
    const sequence = ctx.store.reserveNextReplaySequence(1);
    const payload = try encodeChangeRecordPayload(ctx, batch, sequence);
    defer ctx.alloc.free(payload);
    try ctx.store.appendReplayOpaque(ctx.alloc, sequence, payload);
    try mirrorHAReplayPayloadCommitContext(ctx, payload);
    ctx.executor.trackBacklogBytes(sequence, @intCast(payload.len)) catch {};
    return sequence;
}

fn appendReplicatedHADerivedEffectContext(ctx: *const BatchExecutionContext, record: ha_replication_record_mod.RecordView) !u64 {
    var decoded = try ha_effects_mod.decodeDerivedChangeRecord(ctx.alloc, record);
    defer decoded.deinit();

    const sequence = ctx.store.reserveNextReplaySequence(1);
    decoded.record.sequence = sequence;
    const payload = try change_journal_mod.encodeRecord(ctx.alloc, decoded.record);
    defer ctx.alloc.free(payload);

    try ctx.store.appendReplayOpaque(ctx.alloc, sequence, payload);
    ctx.executor.trackBacklogBytes(sequence, @intCast(payload.len)) catch {};
    return sequence;
}

fn encodeChangeRecordPayload(ctx: *const BatchExecutionContext, batch: derived_types.DerivedBatch, sequence: u64) ![]u8 {
    return try encodeChangeRecordPayloadWithTargetHints(ctx, batch, sequence, null);
}

fn encodeChangeRecordPayloadWithTargetHints(
    ctx: *const BatchExecutionContext,
    batch: derived_types.DerivedBatch,
    sequence: u64,
    target_hints: ?[]const change_journal_mod.TargetHint,
) ![]u8 {
    var record = if (target_hints) |hints|
        try change_journal_mod.recordFromDerivedBatchWithTargetHints(ctx.alloc, batch, sequence, hints)
    else
        try change_journal_mod.recordFromDerivedBatch(ctx.alloc, batch, sequence);
    defer change_journal_mod.deinitRecord(ctx.alloc, &record);
    return try change_journal_mod.encodeRecord(ctx.alloc, record);
}

fn enforceHAWriteGateOptional(gate: ?HAWriteGate) !void {
    const configured = gate orelse return;
    try configured.check();
}

fn haMutationBarrierFromContext(ctx: *const BatchExecutionContext) ?*HAMutationBarrier {
    var barrier: ?*HAMutationBarrier = null;
    const mirrors = .{
        ctx.ha_async_effect_mirror,
        ctx.ha_async_batch_mirror,
        ctx.ha_async_metadata_mirror,
    };
    inline for (mirrors) |maybe_mirror| {
        if (maybe_mirror) |mirror| {
            if (mirror.mutation_barrier) |candidate| {
                if (barrier) |configured| {
                    std.debug.assert(configured == candidate);
                } else {
                    barrier = candidate;
                }
            }
        }
    }
    return barrier;
}

fn acquireHAMutationSharedContext(ctx: *const BatchExecutionContext) ?HAMutationBarrier.SharedLease {
    const barrier = haMutationBarrierFromContext(ctx) orelse return null;
    return barrier.acquireShared();
}

fn haTransitionMutexFromContext(ctx: *const BatchExecutionContext) ?*std.atomic.Mutex {
    var transition_mutex: ?*std.atomic.Mutex = null;
    const mirrors = .{
        ctx.ha_async_effect_mirror,
        ctx.ha_async_batch_mirror,
        ctx.ha_async_metadata_mirror,
    };
    inline for (mirrors) |maybe_mirror| {
        if (maybe_mirror) |mirror| {
            if (mirror.transition_mutex) |candidate| {
                if (transition_mutex) |configured| {
                    std.debug.assert(configured == candidate);
                } else {
                    transition_mutex = candidate;
                }
            }
        }
    }
    return transition_mutex;
}

fn mirrorHAReplayPayloadBestEffortContext(ctx: *const BatchExecutionContext, payload: []const u8) void {
    const mirror = ctx.ha_async_effect_mirror orelse return;
    const transition_mutex = mirror.transition_mutex;
    if (transition_mutex) |mutex| lockAtomic(mutex);
    defer if (transition_mutex) |mutex| mutex.unlock();
    enforceHAWriteGateOptional(ctx.ha_write_gate) catch return;
    lockAtomic(ctx.log_mutex);
    defer ctx.log_mutex.*.unlock();
    const lsn = ha_effects_mod.appendEncodedDerivedChangeRecord(mirror.primary, payload, .{
        .shard_id = ctx.identity_namespace.shard_id,
        .table_id = ctx.identity_namespace.table_id,
    }) catch |err| {
        if (mirror.failure_count) |counter| _ = counter.fetchAdd(1, .monotonic);
        std.log.warn("failed to mirror DB derived effect into HA stream: {s}", .{@errorName(err)});
        return;
    };
    if (mirror.last_lsn) |last_lsn| last_lsn.store(lsn, .release);
}

fn mirrorHAReplayPayloadCommitContext(ctx: *const BatchExecutionContext, payload: []const u8) !void {
    const mirror = ctx.ha_async_effect_mirror orelse return;
    const transition_mutex = mirror.transition_mutex;
    if (transition_mutex) |mutex| lockAtomic(mutex);
    var transition_locked = transition_mutex != null;
    defer if (transition_locked) transition_mutex.?.unlock();
    // The local store has already committed. Always represent that mutation in
    // the HA tail; a fence that arrived after the preflight gate may reject the
    // client acknowledgement below, but must not create an unlogged local fork.
    const lsn = blk: {
        lockAtomic(ctx.log_mutex);
        defer ctx.log_mutex.*.unlock();
        const lsn = ha_effects_mod.appendEncodedDerivedChangeRecord(mirror.primary, payload, .{
            .shard_id = ctx.identity_namespace.shard_id,
            .table_id = ctx.identity_namespace.table_id,
        }) catch |err| {
            noteHAMirrorFailure(mirror, "derived effect", err);
            if (haMirrorSyncEnabled(mirror)) return err;
            return;
        };
        if (mirror.last_lsn) |last_lsn| last_lsn.store(lsn, .release);
        break :blk lsn;
    };
    // Standby status acknowledgements use the same runtime transition mutex.
    // Release it while waiting for remote progress, then reacquire it to make
    // the final client acknowledgement linearizable with fencing.
    if (transition_mutex) |mutex| {
        mutex.unlock();
        transition_locked = false;
    }
    try evaluateHAMirrorCommitGate(mirror, lsn);
    if (transition_mutex) |mutex| {
        lockAtomic(mutex);
        transition_locked = true;
    }
    // Authority can expire while a synchronous replication wait is in flight.
    // Recheck before returning success while the transition mutex is still held
    // so a stale writer can never acknowledge an already-replicated mutation.
    try enforceHAWriteGateOptional(ctx.ha_write_gate);
}

fn mirrorHABatchMutationBestEffortContext(ctx: *const BatchExecutionContext, request: types.BatchRequest) void {
    const mirror = ctx.ha_async_batch_mirror orelse return;
    const transition_mutex = mirror.transition_mutex;
    if (transition_mutex) |mutex| lockAtomic(mutex);
    defer if (transition_mutex) |mutex| mutex.unlock();
    enforceHAWriteGateOptional(ctx.ha_write_gate) catch return;
    lockAtomic(ctx.log_mutex);
    defer ctx.log_mutex.*.unlock();
    const lsn = ha_effects_mod.appendBatchMutationRequest(ctx.alloc, mirror.primary, request, .{
        .shard_id = ctx.identity_namespace.shard_id,
        .table_id = ctx.identity_namespace.table_id,
    }) catch |err| {
        if (mirror.failure_count) |counter| _ = counter.fetchAdd(1, .monotonic);
        std.log.warn("failed to mirror DB batch mutation into HA stream: {s}", .{@errorName(err)});
        return;
    };
    if (mirror.last_lsn) |last_lsn| last_lsn.store(lsn, .release);
}

fn mirrorHABatchMutationCommitContext(ctx: *const BatchExecutionContext, request: types.BatchRequest) !void {
    const mirror = ctx.ha_async_batch_mirror orelse return;
    const transition_mutex = mirror.transition_mutex;
    if (transition_mutex) |mutex| lockAtomic(mutex);
    var transition_locked = transition_mutex != null;
    defer if (transition_locked) transition_mutex.?.unlock();
    // The local store has already committed. Always append before applying the
    // final authority check so rejoin cannot mistake local divergence for an
    // exact fork boundary.
    const lsn = blk: {
        lockAtomic(ctx.log_mutex);
        defer ctx.log_mutex.*.unlock();
        const lsn = ha_effects_mod.appendBatchMutationRequest(ctx.alloc, mirror.primary, request, .{
            .shard_id = ctx.identity_namespace.shard_id,
            .table_id = ctx.identity_namespace.table_id,
        }) catch |err| {
            noteHAMirrorFailure(mirror, "batch mutation", err);
            if (haMirrorSyncEnabled(mirror)) return err;
            return;
        };
        if (mirror.last_lsn) |last_lsn| last_lsn.store(lsn, .release);
        break :blk lsn;
    };
    if (transition_mutex) |mutex| {
        mutex.unlock();
        transition_locked = false;
    }
    try evaluateHAMirrorCommitGate(mirror, lsn);
    if (transition_mutex) |mutex| {
        lockAtomic(mutex);
        transition_locked = true;
    }
    try enforceHAWriteGateOptional(ctx.ha_write_gate);
}

fn mirrorHAEncodedBatchMutationCommitContext(ctx: *const BatchExecutionContext, payload: []const u8) !void {
    const mirror = ctx.ha_async_batch_mirror orelse return;
    const lsn = blk: {
        lockAtomic(ctx.log_mutex);
        defer ctx.log_mutex.*.unlock();
        const lsn = ha_effects_mod.appendEncodedBatchMutationRequest(mirror.primary, payload, .{
            .shard_id = ctx.identity_namespace.shard_id,
            .table_id = ctx.identity_namespace.table_id,
        }) catch |err| {
            noteHAMirrorFailure(mirror, "batch mutation", err);
