fn readEnvUsize(name: [:0]const u8, default_value: usize) usize {
    if (comptime builtin.os.tag == .freestanding) return default_value;
    const raw = getenv(name) orelse return default_value;
    if (raw.len == 0) return default_value;
    return std.fmt.parseUnsigned(usize, raw, 10) catch default_value;
}

fn readEnvU64(name: [:0]const u8, default_value: u64) u64 {
    if (comptime builtin.os.tag == .freestanding) return default_value;
    const raw = getenv(name) orelse return default_value;
    if (raw.len == 0) return default_value;
    return std.fmt.parseUnsigned(u64, raw, 10) catch default_value;
}

fn profileBenchTestsEnabled() bool {
    if (comptime builtin.os.tag == .freestanding) return false;
    return getenv("ANTFLY_RUN_PROFILE_BENCH_TESTS") != null;
}

fn appendDerivedBatchFromEnrichment(ctx_ptr: *anyopaque, batch: derived_types.DerivedBatch) !u64 {
    const ctx: *EnrichmentAppendContext = @ptrCast(@alignCast(ctx_ptr));
    var batch_ctx = ctx.batchContext();
    const sequence = try appendDerivedBatchRecordContext(&batch_ctx, batch);
    notifyResolverReplayRuntimesForCatalog(ctx.index_manager, ctx.resolution_runtime, ctx.promotion_runtime, sequence);
    if (ctx.executor.hasWorkers()) {
        ctx.executor.forceSequence(sequence);
        return sequence;
    }

    var applied_batch = batch;
    applied_batch.sequence = sequence;
    try applyDerivedBatchContext(&batch_ctx, applied_batch);
    return sequence;
}

const ResolutionHandoffDocStoreSink = struct {
    store: *docstore_mod.DocStore,

    fn write(self: *@This(), writes: []const docstore_mod.KVPair, deletes: []const []const u8) !void {
        try self.store.putBatch(writes, deletes);
    }
};

fn publishResolutionHandoffContext(
    ctx: *const BatchExecutionContext,
    write: resolution_runtime_mod.RecordWrite,
) !void {
    var sink = ResolutionHandoffDocStoreSink{ .store = ctx.store };
    try publishResolutionHandoffContextWithSink(ctx, write, &sink);
}

fn publishResolutionHandoffContextWithSink(
    ctx: *const BatchExecutionContext,
    write: resolution_runtime_mod.RecordWrite,
    sink: anytype,
) !void {
    if (!write.publish_resolution_handoff) return;
    const marker_count = write.artifact_writes.len + write.artifact_deletes.len;
    if (marker_count == 0) return;

    const marker_keys = try ctx.alloc.alloc([]u8, marker_count);
    var marker_keys_initialized: usize = 0;
    defer {
        for (marker_keys[0..marker_keys_initialized]) |key| ctx.alloc.free(key);
        ctx.alloc.free(marker_keys);
    }
    const marker_values = try ctx.alloc.alloc(resolution_handoff.Value, write.artifact_writes.len);
    defer ctx.alloc.free(marker_values);
    const marker_writes = try ctx.alloc.alloc(docstore_mod.KVPair, write.artifact_writes.len);
    defer ctx.alloc.free(marker_writes);
    const marker_deletes = try ctx.alloc.alloc([]const u8, write.artifact_deletes.len);
    defer ctx.alloc.free(marker_deletes);

    for (write.artifact_writes, 0..) |artifact, i| {
        marker_keys[i] = try resolution_handoff.keyAlloc(ctx.alloc, artifact.key);
        marker_keys_initialized += 1;
        marker_values[i] = resolution_handoff.value(artifact.value);
        marker_writes[i] = .{ .key = marker_keys[i], .value = &marker_values[i] };
    }
    for (write.artifact_deletes, 0..) |artifact_key, i| {
        const marker_index = write.artifact_writes.len + i;
        marker_keys[marker_index] = try resolution_handoff.keyAlloc(ctx.alloc, artifact_key);
        marker_keys_initialized += 1;
        marker_deletes[i] = marker_keys[marker_index];
    }

    // Match the established apply -> transition lock order. The encompassing
    // resolution writer still owns the HA mutation lease; the final gate check
    // makes marker publication linearizable with a primary-role fence, while a
    // single metadata batch preserves backfill throughput.
    ctx.apply_mutex.lockExclusive();
    defer ctx.apply_mutex.unlockExclusive();
    const transition_mutex = haTransitionMutexFromContext(ctx);
    if (transition_mutex) |mutex| lockAtomic(mutex);
    defer if (transition_mutex) |mutex| mutex.unlock();
    try enforceHAWriteGateOptional(ctx.ha_write_gate);
    try sink.write(marker_writes, marker_deletes);
}

test "db resolution handoff completion publishes fanout in one metadata batch" {
    const alloc = std.testing.allocator;

    var path_buf: [256]u8 = undefined;
    const path = tempPath(&path_buf);
    defer cleanupTempDir(path);

    var db = try DB.open(alloc, std.mem.span(path), .{
        .start_index_workers = false,
    });
    defer db.close();
    var batch_ctx = db.batchContext();

    const CountingSink = struct {
        store: *docstore_mod.DocStore,
        calls: usize = 0,
        writes: usize = 0,
        deletes: usize = 0,

        fn write(self: *@This(), writes: []const docstore_mod.KVPair, deletes: []const []const u8) !void {
            self.calls += 1;
            self.writes += writes.len;
            self.deletes += deletes.len;
            try self.store.putBatch(writes, deletes);
        }
    };
    var counting_sink = CountingSink{ .store = batch_ctx.store };

    const first_resolution_key = try internal_keys.resolutionArtifactKeyAlloc(alloc, "doc:a", "resolution_v1");
    defer alloc.free(first_resolution_key);
    const second_resolution_key = try internal_keys.resolutionArtifactKeyAlloc(alloc, "doc:b", "resolution_v1");
    defer alloc.free(second_resolution_key);
    const writes = [_]resolution_runtime_mod.ArtifactWrite{
        .{ .key = first_resolution_key, .value = "{\"entities\":[\"a\"]}" },
        .{ .key = second_resolution_key, .value = "{\"entities\":[\"b\"]}" },
    };
    try publishResolutionHandoffContextWithSink(&batch_ctx, .{
        .batch = .{},
        .artifact_writes = &writes,
        .publish_resolution_handoff = true,
    }, &counting_sink);
    try std.testing.expectEqual(@as(usize, 1), counting_sink.calls);
    try std.testing.expectEqual(@as(usize, 2), counting_sink.writes);
    try std.testing.expectEqual(@as(usize, 0), counting_sink.deletes);

    const first_marker_key = try resolution_handoff.keyAlloc(alloc, first_resolution_key);
    defer alloc.free(first_marker_key);
    const second_marker_key = try resolution_handoff.keyAlloc(alloc, second_resolution_key);
    defer alloc.free(second_marker_key);
    for (writes, [_][]const u8{ first_marker_key, second_marker_key }) |artifact, marker_key| {
        const raw = try db.core.store.get(alloc, marker_key);
        defer alloc.free(raw);
        const expected = resolution_handoff.value(artifact.value);
        try std.testing.expectEqualSlices(u8, &expected, raw);
    }
}

test "storage.ha resolution handoff fence rejects completion after durable HA replay" {
    if (builtin.single_threaded or builtin.os.tag == .freestanding) return error.SkipZigTest;

    const alloc = std.heap.c_allocator;
    var db_path_buf: [256]u8 = undefined;
    const db_path = tempPath(&db_path_buf);
    defer cleanupTempDir(db_path);
    var ha_log_path_buf: [256]u8 = undefined;
    const ha_log_path = tempPath(&ha_log_path_buf);
    defer cleanupTempDir(ha_log_path);
    var ha_slots_path_buf: [256]u8 = undefined;
    const ha_slots_path = tempPath(&ha_slots_path_buf);
    defer cleanupTempDir(ha_slots_path);

    var primary = try ha_primary_mod.Primary.open(alloc, ha_log_path, ha_slots_path, .{
        .cluster_id = 271,
        .shard_id = 4,
        .table_id = 10,
        .timeline_id = 1,
        .epoch = 1,
    }, .{});
    defer primary.close();

    var public_gate = ha_public_gate_state_mod.State{};
    public_gate.configurePrimary(&primary, false);
    var transition_mutex: std.atomic.Mutex = .unlocked;
    var barrier: HAMutationBarrier = .{};
    var db = try DB.open(alloc, std.mem.span(db_path), .{
        .identity_namespace = .{ .shard_id = 4, .table_id = 10 },
        .ha_async_effect_mirror = .{
            .primary = &primary,
            .mutation_barrier = &barrier,
            .transition_mutex = &transition_mutex,
        },
        .ha_write_gate = .{ .shared = .{ .state = &public_gate } },
        .start_index_workers = false,
    });
    defer db.close();

    const PauseBeforePublish = struct {
        io: std.Io,
        entered: std.atomic.Value(bool) = .init(false),
        reached: std.Io.Event = .unset,
        release: std.Io.Event = .unset,

        fn run(ptr: *anyopaque) void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            self.entered.store(true, .release);
            self.reached.set(self.io);
            self.release.waitUncancelable(self.io);
        }
    };
    const WriteProbe = struct {
        ctx: *EnrichmentAppendContext,
        resolution_key: []const u8,
        pause: *PauseBeforePublish,
        result: std.atomic.Value(u8) = .init(0),

        fn run(self: *@This()) void {
            // Also wake the test if the writer fails before entering the hook,
            // so a real regression reports its assertion instead of hanging.
            defer self.pause.reached.set(self.pause.io);
            const writes = [_]resolution_runtime_mod.ArtifactWrite{.{
                .key = self.resolution_key,
                .value = "{\"entities\":[\"durable\"]}",
            }};
            _ = appendResolutionRecordWithHook(self.ctx, .{
                .batch = .{ .changed_artifact_keys = &.{self.resolution_key} },
                .artifact_writes = &writes,
                .publish_resolution_handoff = true,
            }, ResolutionHandoffPublishHook{
                .ptr = self.pause,
                .run_fn = PauseBeforePublish.run,
            }) catch |err| {
                self.result.store(if (err == error.HAFencedPrimary) 1 else 2, .release);
                return;
            };
            self.result.store(3, .release);
        }
    };

    const resolution_key = try internal_keys.resolutionArtifactKeyAlloc(alloc, "doc:fenced", "resolution_v1");
    defer alloc.free(resolution_key);
    const marker_key = try resolution_handoff.keyAlloc(alloc, resolution_key);
    defer alloc.free(marker_key);
    var pause = PauseBeforePublish{ .io = std.testing.io };
    var probe = WriteProbe{
        .ctx = db.resolution_append_context.?,
        .resolution_key = resolution_key,
        .pause = &pause,
    };
    const thread = try std.Thread.spawn(.{}, WriteProbe.run, .{&probe});
    var thread_joined = false;
    errdefer {
        pause.release.set(pause.io);
        if (!thread_joined) thread.join();
    }

    pause.reached.waitUncancelable(pause.io);
    try std.testing.expect(pause.entered.load(.acquire));
    try std.testing.expectEqual(@as(u64, 1), primary.lastLsn());
    try std.testing.expectEqual(@as(u64, 1), db.core.nextDerivedSequence());
    const artifact = try db.core.store.get(alloc, resolution_key);
    defer alloc.free(artifact);
    try std.testing.expectEqualStrings("{\"entities\":[\"durable\"]}", artifact);
    try std.testing.expectError(error.NotFound, db.core.store.get(alloc, marker_key));
    // The hook runs inside appendResolutionRecord's shared mutation lease.
    try std.testing.expect(barrier.tryAcquireExclusive() == null);

    lockAtomic(&transition_mutex);
    public_gate.publishPrimaryFence(true);
    pause.release.set(pause.io);
    transition_mutex.unlock();
    thread.join();
    thread_joined = true;

    try std.testing.expectEqual(@as(u8, 1), probe.result.load(.acquire));
    try std.testing.expectError(error.NotFound, db.core.store.get(alloc, marker_key));
    var capture = barrier.tryAcquireExclusive() orelse return error.TestExpectedEqual;
    capture.release();
}

const ResolutionHandoffPublishHook = struct {
    ptr: *anyopaque,
    run_fn: *const fn (ptr: *anyopaque) void,

    fn run(self: @This()) void {
        self.run_fn(self.ptr);
    }
};

const NoopResolutionHandoffPublishHook = struct {
    fn run(_: @This()) void {}
};

fn appendResolutionRecord(ctx_ptr: *anyopaque, write: resolution_runtime_mod.RecordWrite) !u64 {
    return try appendResolutionRecordWithHook(ctx_ptr, write, NoopResolutionHandoffPublishHook{});
}

fn appendResolutionRecordWithHook(
    ctx_ptr: *anyopaque,
    write: resolution_runtime_mod.RecordWrite,
    before_handoff_publish: anytype,
) !u64 {
    const ctx: *EnrichmentAppendContext = @ptrCast(@alignCast(ctx_ptr));
    if (write.artifact_writes.len == 0 and write.artifact_deletes.len == 0 and write.target_hints == null) {
        return appendDerivedBatchFromEnrichment(ctx_ptr, write.batch);
    }

    var batch_ctx = ctx.batchContext();
    var ha_mutation = acquireHAMutationSharedContext(&batch_ctx);
    defer if (ha_mutation) |*lease| lease.release();
    try enforceHAWriteGateOptional(batch_ctx.ha_write_gate);

    const store_writes = try batch_ctx.alloc.alloc(docstore_mod.KVPair, write.artifact_writes.len);
    defer batch_ctx.alloc.free(store_writes);
    for (write.artifact_writes, 0..) |artifact, i| {
        store_writes[i] = .{ .key = artifact.key, .value = artifact.value };
    }

    batch_ctx.apply_mutex.lockExclusive();
    var apply_mutex_held = true;
    errdefer if (apply_mutex_held) batch_ctx.apply_mutex.unlockExclusive();
    const sequence = batch_ctx.store.reserveNextReplaySequence(1);
    const payload = try encodeChangeRecordPayloadWithTargetHints(
        &batch_ctx,
        write.batch,
        sequence,
        write.target_hints,
    );
    defer batch_ctx.alloc.free(payload);
    try batch_ctx.store.putBatchWithReplay(batch_ctx.io, store_writes, write.artifact_deletes, .{
        .sequence = sequence,
        .payload = payload,
    });
    if (shouldAppendSplitDeltaForContext(&batch_ctx)) {
        try batch_ctx.shard_manager.appendSplitDelta(currentTimeNs(), store_writes, write.artifact_deletes);
    }
    batch_ctx.apply_mutex.unlockExclusive();
    apply_mutex_held = false;

    try mirrorHAReplayPayloadCommitContext(&batch_ctx, payload);
    before_handoff_publish.run();
    try publishResolutionHandoffContext(&batch_ctx, write);
    batch_ctx.executor.trackBacklogBytes(sequence, @intCast(payload.len)) catch {};
    notifyResolverReplayRuntimesForCatalog(ctx.index_manager, ctx.resolution_runtime, ctx.promotion_runtime, sequence);
    if (ctx.executor.hasWorkers()) {
        ctx.executor.forceSequence(sequence);
        return sequence;
    }

    var applied_batch = write.batch;
    applied_batch.sequence = sequence;
    try applyDerivedBatchContext(&batch_ctx, applied_batch);
    return sequence;
}

fn enrichmentFailureArtifactKeyAlloc(
    alloc: Allocator,
    kind: enrichment_types.GeneratedEnrichmentKind,
    doc_key: []const u8,
    artifact_name: []const u8,
    source_artifact_name: []const u8,
) ![]u8 {
    return switch (kind) {
        .dense_embedding, .sparse_embedding => if (source_artifact_name.len > 0)
            // A chunked request owns a set of derived embedding keys. Leave the
            // singular artifact key absent so its durable identity is the
            // complete request tuple rather than a fabricated document key.
            try alloc.alloc(u8, 0)
        else
            try internal_keys.embeddingArtifactKeyForDocumentAlloc(alloc, doc_key, artifact_name),
        .asset => try internal_keys.artifactNamedPrefixAlloc(alloc, doc_key, "asset", artifact_name),
        .chunk_text => try internal_keys.artifactNamedPrefixAlloc(alloc, doc_key, "chunk", artifact_name),
    };
}

fn recordEnrichmentRequestFailure(ctx_ptr: *anyopaque, failure: enrichment_runtime_mod.RequestFailure) !void {
    const ctx: *EnrichmentAppendContext = @ptrCast(@alignCast(ctx_ptr));
    const async_ctx = ctx.async_context orelse return;
    const artifact_kind: types.ArtifactRepairKind = switch (failure.kind) {
        .dense_embedding, .sparse_embedding => .embedding,
        .asset => .asset,
        .chunk_text => .chunk,
    };
    const artifact_key = try enrichmentFailureArtifactKeyAlloc(
        ctx.alloc,
        failure.kind,
        failure.doc_key,
        failure.artifact_name,
        failure.source_artifact_name,
    );
    defer ctx.alloc.free(artifact_key);

    try recordArtifactRepairIssueContextDetailed(
        async_ctx,
        artifact_kind,
        failure.index_name,
        failure.doc_key,
        "",
        "",
        failure.source_artifact_name,
        failure.artifact_name,
        artifact_key,
        null,
        failure.sequence,
        .enrichment_failed,
        failure.attempts,
        failure.error_name,
    );
}

fn enrichmentRequestFailurePending(
    ctx_ptr: *anyopaque,
    failure: enrichment_runtime_mod.FailureIdentity,
    index_name: []const u8,
) !bool {
    const ctx: *EnrichmentAppendContext = @ptrCast(@alignCast(ctx_ptr));
    const artifact_kind: types.ArtifactRepairKind = switch (failure.kind) {
        .dense_embedding, .sparse_embedding => .embedding,
        .asset => .asset,
        .chunk_text => .chunk,
    };
    const artifact_key = try enrichmentFailureArtifactKeyAlloc(
        ctx.alloc,
        failure.kind,
        failure.doc_key,
        failure.artifact_name,
        failure.source_artifact_name,
    );
    defer ctx.alloc.free(artifact_key);
    const artifact_key_hex = if (artifact_key.len > 0)
        try bytesToHexAlloc(ctx.alloc, artifact_key)
    else
        try ctx.alloc.dupe(u8, "");
    defer ctx.alloc.free(artifact_key_hex);

    const issue_key = try artifactRepairIssueKeyForIssueAlloc(ctx.alloc, .{
        .artifact_kind = artifact_kind,
        .index_name = index_name,
        .doc_key = failure.doc_key,
        .source_artifact_name = failure.source_artifact_name,
        .artifact_name = failure.artifact_name,
        .artifact_key = artifact_key_hex,
    });
    defer ctx.alloc.free(issue_key);
    const loaded = (try loadArtifactRepairIssueFromStoreByKey(ctx.alloc, ctx.store, issue_key)) orelse return false;
    var issue = loaded;
    defer issue.deinit(ctx.alloc);
    return issue.reason == .enrichment_failed and issue.sequence >= failure.sequence;
}

fn enrichmentRequestFailureRangePending(
    ctx_ptr: *anyopaque,
    after_sequence: u64,
    through_sequence: u64,
) !bool {
    const ctx: *EnrichmentAppendContext = @ptrCast(@alignCast(ctx_ptr));
    const async_ctx = ctx.async_context orelse return error.EnrichmentRuntimeUnavailable;
    lockAtomicWithBackoff(&async_ctx.artifact_repair_issue_mutex);
    defer async_ctx.artifact_repair_issue_mutex.unlock();
    // Ordinary waits inspect (applied_at_entry, requested]. A delayed
    // idempotent recovery may enter after its requested sequence has already
    // been passed; in that case the write's exact source sequence remains the
    // visibility boundary that must be checked.
    const first_sequence = if (after_sequence < through_sequence)
        after_sequence + 1
    else
        through_sequence;
    const lower = try internal_keys.enrichmentTerminalFailureSequencePrefixAlloc(ctx.alloc, first_sequence);
    defer ctx.alloc.free(lower);
    const through_prefix = try internal_keys.enrichmentTerminalFailureSequencePrefixAlloc(ctx.alloc, through_sequence);
    defer ctx.alloc.free(through_prefix);
    const upper = try internal_keys.nextPrefixAlloc(ctx.alloc, through_prefix) orelse
        return error.InvalidInternalUserKey;
    defer ctx.alloc.free(upper);

    const ScanState = struct {
        const page_size: usize = enrichment_terminal_failure_lookup_entry_budget;
        const Candidate = struct {
            sequence_key: []u8,
            issue_key: []u8,
            generation: u64,

            fn deinit(self: *@This(), alloc: Allocator) void {
                alloc.free(self.sequence_key);
                alloc.free(self.issue_key);
            }
        };

        alloc: Allocator,
        candidates: std.ArrayListUnmanaged(Candidate) = .empty,

        fn deinit(self: *@This()) void {
            for (self.candidates.items) |*candidate| candidate.deinit(self.alloc);
            self.candidates.deinit(self.alloc);
        }

        fn scanEntry(raw_ctx: ?*anyopaque, key: []const u8, marker_value: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
            const state: *@This() = @ptrCast(@alignCast(raw_ctx orelse return error.InvalidArgument));
            _ = try internal_keys.enrichmentTerminalFailureSequence(key);
            const decoded = try decodeEnrichmentTerminalFailureMarkerValue(marker_value);
            const owned_sequence_key = try state.alloc.dupe(u8, key);
            errdefer state.alloc.free(owned_sequence_key);
            const owned_issue_key = try state.alloc.dupe(u8, decoded.issue_key);
            errdefer state.alloc.free(owned_issue_key);
            try state.candidates.append(state.alloc, .{
                .sequence_key = owned_sequence_key,
                .issue_key = owned_issue_key,
                .generation = decoded.generation,
            });
            return if (state.candidates.items.len >= page_size) .stop else .@"continue";
        }
    };

    // Page the secondary index so a wide stable-visibility range never scales
    // request memory with the total repair backlog. Authoritative issue reads
    // happen after each short scan transaction; the repair mutex keeps marker
    // creation/retirement stable across those pages.
    var owned_scan_lower: ?[]u8 = null;
    defer if (owned_scan_lower) |value| ctx.alloc.free(value);
    var entries_examined: usize = 0;
    while (true) {
        var state = ScanState{ .alloc = ctx.alloc };
        defer state.deinit();
        const scan_lower = owned_scan_lower orelse lower;
        try ctx.store.scanWithContext(
            scan_lower,
            upper,
            .{ .lower_exclusive = owned_scan_lower != null },
            &state,
            ScanState.scanEntry,
        );
        if (state.candidates.items.len == 0) return false;
        entries_examined += state.candidates.items.len;

        const next_scan_lower = try ctx.alloc.dupe(u8, state.candidates.items[state.candidates.items.len - 1].sequence_key);
        var next_scan_lower_owned = true;
        defer if (next_scan_lower_owned) ctx.alloc.free(next_scan_lower);
        var found = false;
        var stale_deletes = std.ArrayListUnmanaged([]const u8).empty;
        defer stale_deletes.deinit(ctx.alloc);
        var owned_stale_delete_keys = std.ArrayListUnmanaged([]const u8).empty;
        defer {
            for (owned_stale_delete_keys.items) |key| ctx.alloc.free(@constCast(key));
            owned_stale_delete_keys.deinit(ctx.alloc);
        }
        for (state.candidates.items) |candidate| {
            const loaded = try loadArtifactRepairIssueFromStoreByKey(ctx.alloc, ctx.store, candidate.issue_key);
            if (loaded) |value| {
                var issue = value;
                defer issue.deinit(ctx.alloc);
                const candidate_sequence = try internal_keys.enrichmentTerminalFailureSequence(candidate.sequence_key);
                const current_generation = try loadEnrichmentTerminalFailureGeneration(
                    ctx.alloc,
                    ctx.store,
                    candidate.issue_key,
                );
                const candidate_pair_exists = try enrichmentTerminalFailureMarkerPairExists(
                    ctx.alloc,
                    ctx.store,
                    candidate.issue_key,
                    candidate.generation,
                    candidate_sequence,
                );
                // The marker at the issue's current sequence is the incarnation
                // witness. A rollback binary can delete and recreate the issue
                // while leaving an older additive marker behind; it cannot create
                // this witness. Older coalesced markers remain valid while the
                // current witness exists.
                const current_incarnation_exists = candidate.generation == current_generation and
                    (candidate_sequence == issue.sequence or
                        try enrichmentTerminalFailureMarkerPairExists(
                            ctx.alloc,
                            ctx.store,
                            candidate.issue_key,
                            current_generation,
                            issue.sequence,
                        ));
                if (issue.reason == .enrichment_failed and candidate_pair_exists and current_incarnation_exists) {
                    found = true;
                    break;
                }
            }

            // A rollback binary can retire an issue without knowing this additive
            // index. Ignore and lazily remove that stale pair; current binaries
            // create and retire both sides atomically under this same mutex.
            try stale_deletes.append(ctx.alloc, candidate.sequence_key);
            const sequence = try internal_keys.enrichmentTerminalFailureSequence(candidate.sequence_key);
            const reverse_key = try internal_keys.enrichmentTerminalFailureIssueKeyAlloc(ctx.alloc, candidate.issue_key, sequence);
            errdefer ctx.alloc.free(reverse_key);
            try owned_stale_delete_keys.append(ctx.alloc, reverse_key);
            try stale_deletes.append(ctx.alloc, reverse_key);
        }
        if (stale_deletes.items.len > 0) {
            ctx.store.putBatch(&.{}, stale_deletes.items) catch |err| {
                // Cleanup is an optimization. Classification above is based on the
                // authoritative issue record and must not become a false repair
                // result merely because stale-index GC failed.
                std.log.warn("failed to clean stale enrichment terminal failure markers: {s}", .{@errorName(err)});
            };
        }
        if (found) {
            return true;
        }
        // Visibility classification is on the foreground write path and runs
        // after the ordinary wait deadline. Bound total storage work, not just
        // per-page memory. The caller converts this error into a conservative
        // repair-required result; the stale deletes above make retries
        // monotonically converge without extending this request indefinitely.
        if (entries_examined >= enrichment_terminal_failure_lookup_entry_budget) {
            return error.EnrichmentRepairLookupBudgetExceeded;
        }
        if (owned_scan_lower) |value| ctx.alloc.free(value);
        owned_scan_lower = next_scan_lower;
        next_scan_lower_owned = false;
    }
}

const TerminalFailureSequenceEnvelope = struct {
    min: u64 = 0,
    max: u64 = 0,
    entries_examined: u8 = 0,
};

fn enrichmentTerminalFailureSequenceEnvelope(store: *docstore_mod.DocStore) !TerminalFailureSequenceEnvelope {
    const alloc = store.alloc;
    const prefix = try internal_keys.enrichmentTerminalFailureSequenceRootPrefixAlloc(alloc);
    defer alloc.free(prefix);
    const upper = try internal_keys.nextPrefixAlloc(alloc, prefix);
    defer if (upper) |value| alloc.free(value);

    const EndpointState = struct {
        sequence: u64 = 0,
        entries_examined: u8 = 0,

        fn scanEntry(raw_ctx: ?*anyopaque, key: []const u8, _: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
            const state: *@This() = @ptrCast(@alignCast(raw_ctx orelse return error.InvalidArgument));
            state.sequence = try internal_keys.enrichmentTerminalFailureSequence(key);
            state.entries_examined += 1;
            return .stop;
        }
    };

    // Both endpoints come from one read snapshot. Each scan stops after its
    // first entry, so runtime creation/reconfiguration is O(1) regardless of
    // how much durable repair debt accumulated.
    var txn = try store.beginReadTxn();
    defer txn.abort();
    const scan_upper = if (upper) |value| value else "";
    var min_state = EndpointState{};
    try store.scanReadTxnWithContext(&txn, prefix, scan_upper, .{}, &min_state, EndpointState.scanEntry);
    if (min_state.entries_examined == 0) return .{};

    var max_state = EndpointState{};
    try store.scanReadTxnWithContext(&txn, prefix, scan_upper, .{ .reverse = true }, &max_state, EndpointState.scanEntry);
    return .{
        .min = min_state.sequence,
        .max = max_state.sequence,
        .entries_examined = min_state.entries_examined + max_state.entries_examined,
    };
}

const EnrichmentTerminalFailureMarkerPair = struct {
    sequence_key: []u8,
    issue_key: []u8,

    fn init(alloc: Allocator, repair_issue_key: []const u8, sequence: u64) !@This() {
        const sequence_key = try internal_keys.enrichmentTerminalFailureSequenceKeyAlloc(alloc, sequence, repair_issue_key);
        errdefer alloc.free(sequence_key);
        return .{
            .sequence_key = sequence_key,
            .issue_key = try internal_keys.enrichmentTerminalFailureIssueKeyAlloc(alloc, repair_issue_key, sequence),
        };
    }

    fn deinit(self: *@This(), alloc: Allocator) void {
        alloc.free(self.sequence_key);
        alloc.free(self.issue_key);
        self.* = undefined;
    }
};

const enrichment_terminal_failure_marker_value_version: u8 = 1;
const enrichment_terminal_failure_marker_generation_len = @sizeOf(u64);
const enrichment_terminal_failure_lookup_entry_budget: usize = 64;
const enrichment_terminal_failure_retirement_page_size: usize = 64;

const EnrichmentTerminalFailureMarkerValue = struct {
    generation: u64,
    issue_key: []const u8,
};

fn decodeEnrichmentTerminalFailureMarkerValue(value: []const u8) !EnrichmentTerminalFailureMarkerValue {
    if (value.len > 0 and value[0] == enrichment_terminal_failure_marker_value_version) {
        if (value.len <= 1 + enrichment_terminal_failure_marker_generation_len)
            return error.InvalidEnrichmentTerminalFailureMarker;
        return .{
            .generation = std.mem.readInt(u64, value[1..][0..enrichment_terminal_failure_marker_generation_len], .big),
            .issue_key = value[1 + enrichment_terminal_failure_marker_generation_len ..],
        };
    }
    // Development/rollback compatibility for markers written before durable
    // incarnation fencing. Repair issue keys live in replay namespace 0x02,
    // so they cannot alias the version byte above.
    if (value.len == 0) return error.InvalidEnrichmentTerminalFailureMarker;
    return .{ .generation = 0, .issue_key = value };
}

fn encodeEnrichmentTerminalFailureMarkerValueAlloc(
    alloc: Allocator,
    repair_issue_key: []const u8,
    generation: u64,
) ![]u8 {
    const value = try alloc.alloc(u8, 1 + enrichment_terminal_failure_marker_generation_len + repair_issue_key.len);
    value[0] = enrichment_terminal_failure_marker_value_version;
    std.mem.writeInt(u64, value[1..][0..enrichment_terminal_failure_marker_generation_len], generation, .big);
    @memcpy(value[1 + enrichment_terminal_failure_marker_generation_len ..], repair_issue_key);
    return value;
}

fn loadEnrichmentTerminalFailureGeneration(
    alloc: Allocator,
    store: *docstore_mod.DocStore,
    repair_issue_key: []const u8,
) !u64 {
    const key = try internal_keys.enrichmentTerminalFailureGenerationKeyAlloc(alloc, repair_issue_key);
    defer alloc.free(key);
    const value = store.get(alloc, key) catch |err| switch (err) {
        error.NotFound => return 0,
        else => return err,
    };
    defer alloc.free(value);
    if (value.len != enrichment_terminal_failure_marker_generation_len)
        return error.InvalidEnrichmentTerminalFailureGeneration;
    return std.mem.readInt(u64, value[0..enrichment_terminal_failure_marker_generation_len], .big);
}

fn loadEnrichmentTerminalFailureGenerationCounter(
    alloc: Allocator,
    store: *docstore_mod.DocStore,
) !u64 {
    const value = store.get(
        alloc,
        &internal_keys.enrichment_terminal_failure_generation_counter_key,
    ) catch |err| switch (err) {
        error.NotFound => return 0,
        else => return err,
    };
    defer alloc.free(value);
    if (value.len != enrichment_terminal_failure_marker_generation_len)
        return error.InvalidEnrichmentTerminalFailureGenerationCounter;
    return std.mem.readInt(u64, value[0..enrichment_terminal_failure_marker_generation_len], .big);
}

fn encodeEnrichmentTerminalFailureGeneration(
    out: *[enrichment_terminal_failure_marker_generation_len]u8,
    generation: u64,
) void {
    std.mem.writeInt(u64, out, generation, .big);
}

fn nextEnrichmentTerminalFailureGeneration(current: u64) !u64 {
    if (current == std.math.maxInt(u64)) return error.EnrichmentTerminalFailureGenerationExhausted;
    return current + 1;
}

fn enrichmentTerminalFailureMarkerPairExists(
    alloc: Allocator,
    store: *docstore_mod.DocStore,
    repair_issue_key: []const u8,
    generation: u64,
    sequence: u64,
) !bool {
    var marker = try EnrichmentTerminalFailureMarkerPair.init(alloc, repair_issue_key, sequence);
    defer marker.deinit(alloc);

    const primary_value = store.get(alloc, marker.sequence_key) catch |err| switch (err) {
        error.NotFound => return false,
        else => return err,
    };
    defer alloc.free(primary_value);
    const decoded = try decodeEnrichmentTerminalFailureMarkerValue(primary_value);
    if (decoded.generation != generation or !std.mem.eql(u8, decoded.issue_key, repair_issue_key)) return false;

    const reverse_value = store.get(alloc, marker.issue_key) catch |err| switch (err) {
        error.NotFound => return false,
        else => return err,
    };
    defer alloc.free(reverse_value);
    return std.mem.eql(u8, reverse_value, marker.sequence_key);
}

/// Reuse a generation only while the previous authoritative issue retains its
/// exact marker pair. Otherwise advance the durable incarnation generation so
/// leftover markers from rollback or bounded retirement cannot resurrect when
/// the new current witness is published.
const EnrichmentTerminalFailureGenerationSelection = struct {
    issue_generation: u64,
    counter: u64,
};

fn enrichmentTerminalFailureGenerationForWrite(
    alloc: Allocator,
    store: *docstore_mod.DocStore,
    repair_issue_key: []const u8,
    previous_sequence: ?u64,
    deletes: *std.ArrayListUnmanaged([]const u8),
    owned_delete_keys: *std.ArrayListUnmanaged([]const u8),
) !EnrichmentTerminalFailureGenerationSelection {
    const current_generation = loadEnrichmentTerminalFailureGeneration(alloc, store, repair_issue_key) catch |err| switch (err) {
        // A new counter token safely supersedes an unreadable live token, and
        // the final atomic write repairs this sidecar. Preserve ordinary
        // storage failures so parking cannot acknowledge debt that was never
        // made durable.
        error.InvalidEnrichmentTerminalFailureGeneration => 0,
        else => return err,
    };
    const persisted_counter = try loadEnrichmentTerminalFailureGenerationCounter(alloc, store);
    const high_water = @max(current_generation, persisted_counter);
    if (previous_sequence) |previous| {
        if (try enrichmentTerminalFailureMarkerPairExists(
            alloc,
            store,
            repair_issue_key,
            current_generation,
            previous,
        )) return .{
            .issue_generation = current_generation,
            .counter = high_water,
        };
    }
    try appendEnrichmentTerminalFailureMarkerDeletesForIssue(
        alloc,
        store,
        repair_issue_key,
        deletes,
        owned_delete_keys,
        false,
    );
    // Allocate from one durable store-wide high-water mark. This survives
    // bounded retirement without retaining a tombstone for every repaired
    // artifact, and cannot reuse an old token when an identical source
    // sequence is replayed later.
    const next = try nextEnrichmentTerminalFailureGeneration(high_water);
    return .{ .issue_generation = next, .counter = next };
}

const EnrichmentTerminalFailureMarkerWrite = struct {
    marker: EnrichmentTerminalFailureMarkerPair,
    generation_key: []u8,
    marker_value: []u8,
    generation_value: [enrichment_terminal_failure_marker_generation_len]u8,
    generation_counter_value: [enrichment_terminal_failure_marker_generation_len]u8,

    fn init(
        alloc: Allocator,
        store: *docstore_mod.DocStore,
        repair_issue_key: []const u8,
        previous_sequence: ?u64,
        sequence: u64,
        deletes: *std.ArrayListUnmanaged([]const u8),
        owned_delete_keys: *std.ArrayListUnmanaged([]const u8),
    ) !@This() {
        const generation = try enrichmentTerminalFailureGenerationForWrite(
            alloc,
            store,
            repair_issue_key,
            previous_sequence,
            deletes,
            owned_delete_keys,
        );
        var marker = try EnrichmentTerminalFailureMarkerPair.init(alloc, repair_issue_key, sequence);
        errdefer marker.deinit(alloc);
        const generation_key = try internal_keys.enrichmentTerminalFailureGenerationKeyAlloc(alloc, repair_issue_key);
        errdefer alloc.free(generation_key);
        const marker_value = try encodeEnrichmentTerminalFailureMarkerValueAlloc(
            alloc,
            repair_issue_key,
            generation.issue_generation,
        );
        errdefer alloc.free(marker_value);
        var generation_value: [enrichment_terminal_failure_marker_generation_len]u8 = undefined;
        encodeEnrichmentTerminalFailureGeneration(&generation_value, generation.issue_generation);
        var generation_counter_value: [enrichment_terminal_failure_marker_generation_len]u8 = undefined;
        encodeEnrichmentTerminalFailureGeneration(&generation_counter_value, generation.counter);
        return .{
            .marker = marker,
            .generation_key = generation_key,
            .marker_value = marker_value,
            .generation_value = generation_value,
            .generation_counter_value = generation_counter_value,
        };
    }

    fn deinit(self: *@This(), alloc: Allocator) void {
        self.marker.deinit(alloc);
        alloc.free(self.generation_key);
        alloc.free(self.marker_value);
        self.* = undefined;
    }
};

/// Append at most one bounded page of marker pairs owned by a coalesced repair
/// issue. The authoritative issue transition and generation fence make any
/// remainder stale immediately; foreground lookup removes it incrementally.
fn appendEnrichmentTerminalFailureMarkerDeletesForIssue(
    alloc: Allocator,
    store: *docstore_mod.DocStore,
    repair_issue_key: []const u8,
    deletes: *std.ArrayListUnmanaged([]const u8),
    owned_delete_keys: *std.ArrayListUnmanaged([]const u8),
    retire_generation: bool,
) !void {
    _ = try appendEnrichmentTerminalFailureMarkerDeletePageForIssue(
        alloc,
        store,
        repair_issue_key,
        deletes,
        owned_delete_keys,
    );
    if (retire_generation) {
        const generation_key = try internal_keys.enrichmentTerminalFailureGenerationKeyAlloc(alloc, repair_issue_key);
        errdefer alloc.free(generation_key);
        const owned_len = owned_delete_keys.items.len;
        try owned_delete_keys.append(alloc, generation_key);
        errdefer owned_delete_keys.shrinkRetainingCapacity(owned_len);
        try deletes.append(alloc, generation_key);
    }
}

fn appendEnrichmentTerminalFailureMarkerDeletePageForIssue(
    alloc: Allocator,
    store: *docstore_mod.DocStore,
    repair_issue_key: []const u8,
    deletes: *std.ArrayListUnmanaged([]const u8),
    owned_delete_keys: *std.ArrayListUnmanaged([]const u8),
) !usize {
    const prefix = try internal_keys.enrichmentTerminalFailureIssuePrefixAlloc(alloc, repair_issue_key);
    defer alloc.free(prefix);
    const upper = try internal_keys.nextPrefixAlloc(alloc, prefix);
    defer if (upper) |value| alloc.free(value);

    const ScanState = struct {
        alloc: Allocator,
        repair_issue_key: []const u8,
        deletes: *std.ArrayListUnmanaged([]const u8),
        owned_delete_keys: *std.ArrayListUnmanaged([]const u8),
        entries_examined: usize = 0,

        fn appendOwned(self: *@This(), value: []const u8) !void {
            const owned = try self.alloc.dupe(u8, value);
            errdefer self.alloc.free(owned);
            const owned_len = self.owned_delete_keys.items.len;
            try self.owned_delete_keys.append(self.alloc, owned);
            errdefer self.owned_delete_keys.shrinkRetainingCapacity(owned_len);
            try self.deletes.append(self.alloc, owned);
        }

        fn scanEntry(raw_ctx: ?*anyopaque, secondary_key: []const u8, sequence_key: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
            const state: *@This() = @ptrCast(@alignCast(raw_ctx orelse return error.InvalidArgument));
            try state.appendOwned(secondary_key);

            const sequence = internal_keys.enrichmentTerminalFailureSequence(sequence_key) catch {
                state.entries_examined += 1;
                return if (state.entries_examined >= enrichment_terminal_failure_retirement_page_size) .stop else .@"continue";
            };

            // A reverse entry is untrusted durable metadata. Reconstruct the
            // only primary key this issue can own before allowing its value to
            // name a second deletion. A malformed or cross-issue value retires
            // only the corrupt reverse entry, preserving the other issue's
            // authoritative marker and therefore failing visibility closed.
            const expected_sequence_key = try internal_keys.enrichmentTerminalFailureSequenceKeyAlloc(
                state.alloc,
                sequence,
                state.repair_issue_key,
            );
            defer state.alloc.free(expected_sequence_key);
            if (std.mem.eql(u8, sequence_key, expected_sequence_key)) try state.appendOwned(sequence_key);

            state.entries_examined += 1;
            return if (state.entries_examined >= enrichment_terminal_failure_retirement_page_size) .stop else .@"continue";
        }
    };

    var state = ScanState{
        .alloc = alloc,
        .repair_issue_key = repair_issue_key,
        .deletes = deletes,
        .owned_delete_keys = owned_delete_keys,
    };
    try store.scanWithContext(prefix, if (upper) |value| value else "", .{}, &state, ScanState.scanEntry);
    return state.entries_examined;
}

fn lockEnrichmentFailurePendingFence(ctx_ptr: *anyopaque) void {
    const ctx: *EnrichmentAppendContext = @ptrCast(@alignCast(ctx_ptr));
    const async_ctx = ctx.async_context orelse return;
    lockAtomicWithBackoff(&async_ctx.artifact_repair_issue_mutex);
}

fn unlockEnrichmentFailurePendingFence(ctx_ptr: *anyopaque) void {
    const ctx: *EnrichmentAppendContext = @ptrCast(@alignCast(ctx_ptr));
    const async_ctx = ctx.async_context orelse return;
    async_ctx.artifact_repair_issue_mutex.unlock();
}

fn appendGeneratedBatchFromEnrichment(ctx_ptr: *anyopaque, batch: derived_types.DerivedBatch, artifact_delete_keys: []const []const u8) !u64 {
    if (artifact_delete_keys.len == 0) return appendDerivedBatchFromEnrichment(ctx_ptr, batch);

    const ctx: *EnrichmentAppendContext = @ptrCast(@alignCast(ctx_ptr));
    var batch_ctx = ctx.batchContext();
    var ha_mutation = acquireHAMutationSharedContext(&batch_ctx);
    defer if (ha_mutation) |*lease| lease.release();
    try enforceHAWriteGateOptional(batch_ctx.ha_write_gate);
    const replay_deleted_keys = try concatKeyViews(batch_ctx.alloc, batch.deleted_keys, artifact_delete_keys);
    defer batch_ctx.alloc.free(replay_deleted_keys);
    var replay_batch = batch;
    replay_batch.deleted_keys = replay_deleted_keys;

    batch_ctx.apply_mutex.lockExclusive();
    const sequence = blk: {
        defer batch_ctx.apply_mutex.unlockExclusive();
        const reserved_sequence = batch_ctx.store.reserveNextReplaySequence(1);
        const payload = try encodeChangeRecordPayload(&batch_ctx, replay_batch, reserved_sequence);
        defer batch_ctx.alloc.free(payload);
        var counter_writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
        defer counter_writes.deinit(batch_ctx.alloc);
        var owned_counter_keys = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (owned_counter_keys.items) |key| batch_ctx.alloc.free(key);
            owned_counter_keys.deinit(batch_ctx.alloc);
        }
        var owned_counter_values = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (owned_counter_values.items) |value| batch_ctx.alloc.free(value);
            owned_counter_values.deinit(batch_ctx.alloc);
        }
        try DB.appendDenseArtifactCounterMutations(
            batch_ctx.alloc,
            batch_ctx.store,
            batch_ctx.index_manager,
            &counter_writes,
            artifact_delete_keys,
            &owned_counter_keys,
            &owned_counter_values,
        );
        try batch_ctx.store.putBatchWithReplay(batch_ctx.io, counter_writes.items, artifact_delete_keys, .{
            .sequence = reserved_sequence,
            .payload = payload,
        });
        if (shouldAppendSplitDeltaForContext(&batch_ctx)) {
            try batch_ctx.shard_manager.appendSplitDelta(currentTimeNs(), &.{}, artifact_delete_keys);
        }
        try mirrorHAReplayPayloadCommitContext(&batch_ctx, payload);
        batch_ctx.executor.trackBacklogBytes(reserved_sequence, @intCast(payload.len)) catch {};
        break :blk reserved_sequence;
    };

    notifyResolverReplayRuntimesForCatalog(ctx.index_manager, ctx.resolution_runtime, ctx.promotion_runtime, sequence);
    if (ctx.executor.hasWorkers()) {
        ctx.executor.forceSequence(sequence);
        return sequence;
    }

    var applied_batch = replay_batch;
    applied_batch.sequence = sequence;
    try applyDerivedBatchContext(&batch_ctx, applied_batch);
    return sequence;
}

fn replayPendingDerivedBatchesContext(ctx: *const BatchExecutionContext) !void {
    const managed_indexes = try ctx.index_manager.managedIndexes(ctx.alloc);
    defer {
        for (managed_indexes) |index_ref| ctx.alloc.free(@constCast(index_ref.name));
        ctx.alloc.free(managed_indexes);
    }
    if (managed_indexes.len == 0) return;

    var saw_entries = false;
    var updates = std.ArrayListUnmanaged(apply_state.AppliedSequenceUpdate).empty;
    defer updates.deinit(ctx.alloc);
    var replay_ctx = ReplayApplyContextBatch{
        .batch = ctx,
        .dense_bulk_session_scope = .external,
    };
    for (managed_indexes) |index_ref| {
        const applied = try apply_state.loadAppliedSequenceWithCheckpoint(
            ctx.alloc,
            ctx.index_manager.checkpointIo(),
            ctx.store,
            ctx.applied_sequence_checkpoint_path,
            index_ref.name,
        );
        const target_sequence = try ctx.replay_source.latestMatchingSequence(
            ctx.alloc,
            applied,
            managedIndexReplayHint(index_ref.kind),
        );
        const use_dense_maintenance = index_ref.kind == .dense_vector;
        const stats = try derived_worker.catchUpIndexWithOptions(
            ctx.alloc,
            ctx.replay_source,
            index_ref,
            applied,
            &replay_ctx,
            applyDerivedBatchToIndexReplayContext,
            .{
                .resource_manager = ctx.index_manager.resource_manager,
                .window_ctx = &replay_ctx,
                .begin_window_fn = @field(@This(), "beginDerivedCatchUpWindowContext"),
                .finish_window_fn = @field(@This(), "finishDerivedCatchUpWindowContext"),
                .target_sequence = target_sequence,
            },
        );
        if (openProfileEnabled()) logReplayCatchUpProfile(index_ref, applied, stats);
        if (use_dense_maintenance) {
            _ = try ctx.index_manager.runDenseLsmMaintenanceByName(index_ref.name, denseCatchUpMaintenanceSteps());
        }
        saw_entries = saw_entries or stats.scanned_entries > 0;
        if (stats.appliedSequenceAdvance(applied)) |sequence| {
            try ctx.index_manager.checkpointLsmWalForManagedIndex(index_ref);
            try updates.append(ctx.alloc, .{
                .index_name = index_ref.name,
                .sequence = sequence,
            });
        } else if (stats.shouldTryTargetAdvance(applied, target_sequence) and
            try canAdvanceDerivedReplayTargetContext(ctx, index_ref, applied, target_sequence))
        {
            try ctx.index_manager.checkpointLsmWalForManagedIndex(index_ref);
            try updates.append(ctx.alloc, .{
                .index_name = index_ref.name,
                .sequence = target_sequence,
            });
        }
    }
    try saveAppliedSequencesBatchContext(ctx, updates.items);
    try truncateReplayJournalIfSafeContext(ctx);
}

fn canAdvanceDerivedReplayTargetContext(
    ctx: *const BatchExecutionContext,
    index_ref: index_manager_mod.ManagedIndexRef,
    from_sequence: u64,
    target_sequence: u64,
) !bool {
    if (target_sequence <= from_sequence) return true;
    if (ctx.async_context) |async_ctx| {
        return try canAdvanceDerivedToTargetAsync(async_ctx, index_ref, from_sequence, target_sequence);
    }

    var async_ctx = AsyncContext{
        .alloc = ctx.alloc,
        .io = ctx.io,
        .store = ctx.store,
        .applied_sequence_checkpoint_path = ctx.applied_sequence_checkpoint_path,
        .index_manager = ctx.index_manager,
        .apply_mutex = ctx.apply_mutex,
        .dense_bulk_session_scope = ctx.dense_bulk_session_scope,
        .resolution_runtime = ctx.resolution_runtime,
        .promotion_runtime = ctx.promotion_runtime,
    };
    defer async_ctx.deinit(ctx.alloc);
    return try canAdvanceDerivedToTargetAsync(&async_ctx, index_ref, from_sequence, target_sequence);
}

fn applyDerivedBatchToIndexReplayContext(
    ctx_ptr: *anyopaque,
    batch: derived_types.DerivedBatch,
    index_ref: index_manager_mod.ManagedIndexRef,
) !bool {
    const replay_ctx: *const ReplayApplyContextBatch = @ptrCast(@alignCast(ctx_ptr));
    const ctx = replay_ctx.batch;
    if (!try batchAdvancesManagedIndexApplyStateForReplay(ctx.index_manager, batch, index_ref)) return false;

    const async_ctx = AsyncContext{
        .alloc = ctx.alloc,
        .store = ctx.store,
        .applied_sequence_checkpoint_path = ctx.applied_sequence_checkpoint_path,
        .index_manager = ctx.index_manager,
        .apply_mutex = ctx.apply_mutex,
        .dense_bulk_session_scope = replay_ctx.dense_bulk_session_scope,
        .require_graph_resolution_contract = true,
        .text_merge_runtime = if (ctx.async_context) |active| active.text_merge_runtime else null,
    };
    if (benchMetricsEnabled()) {
        var profile = BatchProfile{};
        const total_start_ns = monotonicTimeNs();
        try applyDerivedBatchToIndexContextProfiled(&async_ctx, batch, index_ref, &profile);
        const index_sync_start_ns = monotonicTimeNs();
        try ctx.index_manager.syncReplayStateByName(ctx.store, index_ref.name);
        recordProfileNs(&profile, &profile.index_sync_ns, index_sync_start_ns);
        profile.total_ns += monotonicTimeNs() - total_start_ns;
        logDerivedWorkerProfile(index_ref, batch, profile);
    } else {
        try applyDerivedBatchToIndexContext(&async_ctx, batch, index_ref);
        try ctx.index_manager.syncReplayStateByName(ctx.store, index_ref.name);
    }
    return true;
}

fn notifyDerivedExecutorSequence(ctx_ptr: *anyopaque, sequence: u64) void {
    const executor: *derived_executor_mod.Executor = @ptrCast(@alignCast(ctx_ptr));
    executor.notifySequence(sequence);
}

fn applyDerivedBatch(self: *DB, batch: derived_types.DerivedBatch) !void {
    try applyDerivedBatchProfiled(self, batch, null);
}

fn applyDerivedBatchProfiled(self: *DB, batch: derived_types.DerivedBatch, profile: ?*BatchProfile) !void {
    var ctx = self.batchContext();
    try applyDerivedBatchContextProfiled(&ctx, batch, profile);
    if (self.text_merge_runtime) |runtime| {
        runtime.notify();
    }
    if (self.sparse_compaction_runtime) |runtime| runtime.notify();
}

fn applyDerivedBatchTargetsProfiled(self: *DB, batch: derived_types.DerivedBatch, index_names: []const []const u8, profile: ?*BatchProfile) !void {
    var ctx = self.batchContext();
    try applyDerivedBatchTargetsContextProfiled(&ctx, batch, index_names, profile);
    if (self.text_merge_runtime) |runtime| {
        runtime.notify();
    }
    if (self.sparse_compaction_runtime) |runtime| runtime.notify();
}

fn applyDerivedBatchContext(ctx: *const BatchExecutionContext, batch: derived_types.DerivedBatch) !void {
    try applyDerivedBatchContextProfiled(ctx, batch, null);
}

fn applyDerivedBatchTargetsContext(ctx: *const BatchExecutionContext, batch: derived_types.DerivedBatch, index_names: []const []const u8) !void {
    try applyDerivedBatchTargetsContextProfiled(ctx, batch, index_names, null);
}

fn applyDerivedBatchContextProfiled(ctx: *const BatchExecutionContext, batch: derived_types.DerivedBatch, profile: ?*BatchProfile) !void {
    try applyDerivedBatchTargetsContextProfiled(ctx, batch, &.{}, profile);
}

fn applyDerivedBatchTargetsContextProfiled(ctx: *const BatchExecutionContext, batch: derived_types.DerivedBatch, index_names: []const []const u8, profile: ?*BatchProfile) !void {
    const managed_indexes = try ctx.index_manager.managedIndexes(ctx.alloc);
    defer {
        for (managed_indexes) |index_ref| ctx.alloc.free(@constCast(index_ref.name));
        ctx.alloc.free(managed_indexes);
    }
    var updates = std.ArrayListUnmanaged(apply_state.AppliedSequenceUpdate).empty;
    defer updates.deinit(ctx.alloc);
    for (managed_indexes) |index_ref| {
        if (index_names.len != 0 and !indexNameInSlice(index_ref.name, index_names)) continue;
        if (try batchAdvancesManagedIndexApplyState(ctx.index_manager, batch, index_ref)) {
            const async_ctx = AsyncContext{
                .alloc = ctx.alloc,
                .store = ctx.store,
                .applied_sequence_checkpoint_path = ctx.applied_sequence_checkpoint_path,
                .index_manager = ctx.index_manager,
                .apply_mutex = ctx.apply_mutex,
                .dense_bulk_session_scope = ctx.dense_bulk_session_scope,
                .text_merge_runtime = if (ctx.async_context) |active| active.text_merge_runtime else null,
            };
            try applyDerivedBatchToIndexContextProfiled(&async_ctx, batch, index_ref, profile);
            const index_sync_start_ns = monotonicTimeNs();
            try ctx.index_manager.syncReplayStateByName(ctx.store, index_ref.name);
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.index_sync_ns, index_sync_start_ns);
            try updates.append(ctx.alloc, .{
                .index_name = index_ref.name,
                .sequence = batch.sequence,
            });
        }
    }
    const applied_sequence_start_ns = monotonicTimeNs();
    try saveAppliedSequencesBatchContext(ctx, updates.items);
    if (profile) |active_profile| recordProfileNs(profile, &active_profile.applied_sequence_save_ns, applied_sequence_start_ns);
    const truncate_start_ns = monotonicTimeNs();
    try truncateReplayJournalIfSafeContext(ctx);
    if (profile) |active_profile| recordProfileNs(profile, &active_profile.replay_journal_truncate_ns, truncate_start_ns);
}

fn indexNameInSlice(name: []const u8, index_names: []const []const u8) bool {
    for (index_names) |candidate| {
        if (std.mem.eql(u8, name, candidate)) return true;
    }
    return false;
}

fn saveAppliedSequencesBatchContext(
    ctx: *const BatchExecutionContext,
    updates: []const apply_state.AppliedSequenceUpdate,
) !void {
    if (updates.len == 0) return;
    const enriched_updates = try appliedSequenceUpdatesWithConfigHashes(ctx.alloc, ctx.index_manager, updates);
    defer ctx.alloc.free(enriched_updates);
    if (ctx.async_context) |async_ctx| {
        var seq_lock = lockAtomicWithBackoffProfiled(
            &async_ctx.applied_sequence_mutex,
            &async_ctx.stats.applied_sequence_mutex,
        );
        defer seq_lock.unlock();
        try saveDenseProjectionMetadataForAppliedSequenceUpdates(ctx.index_manager, enriched_updates);
        try checkpointManagedProjectionEffectsForAppliedSequenceUpdates(ctx.index_manager, enriched_updates);
        try apply_state.saveAppliedSequencesWithCheckpoint(
            ctx.alloc,
            ctx.index_manager.checkpointIo(),
            ctx.store,
            ctx.applied_sequence_checkpoint_path,
            enriched_updates,
        );
        for (enriched_updates) |update| _ = try finalizeCoveredDenseProjectionCheckpoint(async_ctx, update.index_name, update.sequence);
        try DB.saveIndexStatusSnapshots(ctx.alloc, ctx.store, ctx.index_manager, enriched_updates);
        return;
    }
    try saveDenseProjectionMetadataForAppliedSequenceUpdates(ctx.index_manager, enriched_updates);
    try checkpointManagedProjectionEffectsForAppliedSequenceUpdates(ctx.index_manager, enriched_updates);
    try apply_state.saveAppliedSequencesWithCheckpoint(
        ctx.alloc,
        ctx.index_manager.checkpointIo(),
        ctx.store,
        ctx.applied_sequence_checkpoint_path,
        enriched_updates,
    );
    try DB.saveIndexStatusSnapshots(ctx.alloc, ctx.store, ctx.index_manager, enriched_updates);
}

fn appliedSequenceUpdatesWithConfigHashes(
    alloc: Allocator,
    index_manager: *const index_manager_mod.IndexManager,
    updates: []const apply_state.AppliedSequenceUpdate,
) ![]apply_state.AppliedSequenceUpdate {
    const enriched = try alloc.alloc(apply_state.AppliedSequenceUpdate, updates.len);
    for (updates, 0..) |update, i| {
        enriched[i] = update;
        if (enriched[i].config_hash == 0) {
            if (index_manager.get(update.index_name)) |cfg| {
                enriched[i].config_hash = types.indexConfigHash(cfg.*);
            }
        }
    }
    return enriched;
}

fn saveDenseProjectionMetadataForAppliedSequenceUpdates(
    index_manager: *index_manager_mod.IndexManager,
    updates: []const apply_state.AppliedSequenceUpdate,
) !void {
    for (updates) |update| {
        const current = index_manager.denseProjectionCheckpointMetadata(update.index_name) orelse continue;
        try index_manager.saveDenseProjectionCheckpointMetadata(update.index_name, .{
            .applied_sequence = update.sequence,
            .status = current.status,
            .generation = if (update.generation != 0) update.generation else current.generation,
            .config_hash = if (update.config_hash != 0) update.config_hash else current.config_hash,
        });
    }
}

fn checkpointManagedProjectionEffectsForAppliedSequenceUpdates(
    index_manager: *index_manager_mod.IndexManager,
    updates: []const apply_state.AppliedSequenceUpdate,
) !void {
    for (updates) |update| {
        const cfg = index_manager.get(update.index_name) orelse continue;
        try index_manager.checkpointLsmWalForManagedIndex(.{
            .name = update.index_name,
            .kind = cfg.kind,
        });
    }
}

fn replayPendingDerivedBatches(
    self: *DB,
    progress_ctx: ?*anyopaque,
    progress_hook: ?ReplayProgressHook,
    options: DB.ReplayDrainOptions,
) !void {
    if (!self.core.hasManagedIndexes()) return;

    const dense_catch_up_watchdog_interval_ns = 5 * std.time.ns_per_s;

    const PersistReplayProgressContext = struct {
        db: *DB,
        progress_ctx: ?*anyopaque,
        progress_hook: ?ReplayProgressHook,
        track_dense: bool = false,
        target_sequence: u64 = 0,
        scanned_entries: u64 = 0,
        applied_entries: u64 = 0,
        replay_scan_batches: u64 = 0,
        replay_hint_filter_skips: u64 = 0,
        active: bool = false,

        fn publish(state: *@This(), index_name: []const u8) !void {
            const progress: ReplayProgress = .{
                .sequence = try state.db.core.loadAppliedSequence(state.db.alloc, index_name),
                .target_sequence = state.target_sequence,
                .scanned_entries = state.scanned_entries,
                .applied_entries = state.applied_entries,
                .replay_scan_batches = state.replay_scan_batches,
                .replay_hint_filter_skips = state.replay_hint_filter_skips,
                .active = state.active,
            };
            if (state.track_dense) setDenseCatchUpProgress(state.db.async_context, progress);
            if (state.progress_hook) |hook| {
                try hook(state.progress_ctx.?, index_name, progress);
            }
        }
    };

    const PersistReplayProgress = struct {
        fn run(ctx: *anyopaque, index_name: []const u8, sequence: u64) !void {
            const progress: *PersistReplayProgressContext = @ptrCast(@alignCast(ctx));
            try progress.db.core.saveAppliedSequence(index_name, sequence);
            try progress.publish(index_name);
        }
    };

    const DenseReplayProgressContext = struct {
        db: *DB,
        persist: *PersistReplayProgressContext,
        index_name: []const u8,
        last_log_ns: u64 = 0,
        last_applied_entries: u64 = 0,

        fn maybeLogStall(replay: *@This(), progress: derived_worker.CatchUpProgress) void {
            if (!replay.persist.active) return;
            const now_ns = monotonicTimeNs();
            if (replay.last_log_ns != 0 and now_ns - replay.last_log_ns < dense_catch_up_watchdog_interval_ns) return;
            replay.last_log_ns = now_ns;

            const dense_entry = replay.db.core.index_manager.denseIndex(replay.index_name) orelse return;
            const profile = dense_entry.index.getWriteProfile();
            const hbc_cache = dense_entry.index.hbcCacheStats();
            const manager = replay.db.core.index_manager.resource_manager;
            const resource_snapshot = if (manager) |value| value.snapshot() else null;
            const hbc_policy: resource_manager_mod.HbcCachePolicy = if (manager) |value| value.hbcCachePolicy() else .{};
            const retry_stats: resource_manager_mod.DerivedRecoverableRetryStats = if (manager) |value| value.derivedRecoverableRetryStats() else .{};
            const hbc_slice: resource_manager_mod.SliceStats = if (resource_snapshot) |stats| stats.slices[@intFromEnum(resource_manager_mod.Slice.hbc_node_metadata_cache)] else .{ .name = "hbc_node_metadata_cache" };
            const dense_apply_slice: resource_manager_mod.SliceStats = if (resource_snapshot) |stats| stats.slices[@intFromEnum(resource_manager_mod.Slice.dense_apply_working_set)] else .{ .name = "dense_apply_working_set" };

            std.log.warn(
                "dense catch-up watchdog progress index={s} sequence={} target={} scanned={} applied={} delta_applied={} local_cache_gates={{nodes={},vectors={}}} shared_hbc={{target={},used={},peak={},soft={},hard={},node_protected={},quantized_protected={},vector_protected={},metadata_protected={},reclaim_requests={},reclaimed_bytes={}}}",
                .{
                    replay.index_name,
                    progress.sequence,
                    replay.persist.target_sequence,
                    progress.scanned_entries,
                    progress.applied_entries,
                    progress.applied_entries -| replay.last_applied_entries,
                    dense_entry.index.config.max_cached_nodes,
                    dense_entry.index.config.max_cached_vectors,
                    hbc_policy.target_bytes,
                    hbc_slice.used_bytes,
                    hbc_slice.peak_bytes,
                    hbc_slice.soft_limit_bytes,
                    hbc_slice.hard_limit_bytes,
                    hbc_policy.node_protected_bytes,
                    hbc_policy.quantized_protected_bytes,
                    hbc_policy.vector_protected_bytes,
                    hbc_policy.metadata_protected_bytes,
                    if (resource_snapshot) |stats| stats.reclaim_requests else 0,
                    if (resource_snapshot) |stats| stats.reclaimed_bytes else 0,
                },
            );
            std.log.warn(
                "dense catch-up watchdog resources index={s} namespace_hbc={{total={},accounted={},node_used={},quantized_used={},vector_used={},vector_peak={},vector_evictions={},metadata_used={}}} rm={{lsm_cache={},dense_search={},dense_apply_used={},dense_apply_peak={},replay_window={},full_text_pending={},full_text_build={}}} retries={{total={},not_found={}}} profile={{find_leaf_ns={},mutate_leaf_ns={},store_vector_ns={},quantized_vector_load_ns={}}}",
                .{
                    replay.index_name,
                    hbc_cache.total_bytes,
                    hbc_cache.accounted_bytes,
                    hbc_cache.node.used_bytes,
                    hbc_cache.quantized.used_bytes,
                    hbc_cache.vector.used_bytes,
                    hbc_cache.vector.peak_bytes,
                    hbc_cache.vector.evictions,
                    hbc_cache.metadata.used_bytes,
                    if (resource_snapshot) |stats| stats.slices[@intFromEnum(resource_manager_mod.Slice.lsm_block_table_cache)].used_bytes else 0,
                    if (resource_snapshot) |stats| stats.slices[@intFromEnum(resource_manager_mod.Slice.dense_search_working_set)].used_bytes else 0,
                    dense_apply_slice.used_bytes,
                    dense_apply_slice.peak_bytes,
                    if (resource_snapshot) |stats| stats.slices[@intFromEnum(resource_manager_mod.Slice.derived_replay_window)].used_bytes else 0,
                    if (resource_snapshot) |stats| stats.slices[@intFromEnum(resource_manager_mod.Slice.full_text_pending_segments)].used_bytes else 0,
                    if (resource_snapshot) |stats| stats.slices[@intFromEnum(resource_manager_mod.Slice.full_text_build_working_set)].used_bytes else 0,
                    retry_stats.total,
                    retry_stats.not_found,
                    profile.insert_find_leaf_ns,
                    profile.insert_mutate_leaf_ns,
                    profile.insert_store_vector_ns,
                    profile.quantized_vector_load_ns,
                },
            );
            replay.last_applied_entries = progress.applied_entries;
        }

        fn run(ctx: *anyopaque, index_name: []const u8, progress: derived_worker.CatchUpProgress) !void {
            const replay: *@This() = @ptrCast(@alignCast(ctx));
            replay.persist.scanned_entries = progress.scanned_entries;
            replay.persist.applied_entries = progress.applied_entries;
            replay.persist.replay_scan_batches = progress.replay_scan_batches;
            replay.persist.replay_hint_filter_skips = progress.replay_hint_filter_skips;
            const snapshot: ReplayProgress = .{
                .sequence = progress.sequence,
                .target_sequence = replay.persist.target_sequence,
                .scanned_entries = progress.scanned_entries,
                .applied_entries = progress.applied_entries,
                .replay_scan_batches = progress.replay_scan_batches,
                .replay_hint_filter_skips = progress.replay_hint_filter_skips,
                .active = replay.persist.active,
            };
            setDenseCatchUpProgress(replay.db.async_context, snapshot);
            replay.maybeLogStall(progress);
            if (replay.persist.progress_hook) |hook| {
                try hook(replay.persist.progress_ctx.?, index_name, snapshot);
            }
        }
    };

    var persist_progress_ctx = PersistReplayProgressContext{
        .db = self,
        .progress_ctx = progress_ctx,
        .progress_hook = progress_hook,
    };

    const managed_indexes = try self.core.managedIndexes(self.alloc);
    defer {
        for (managed_indexes) |index_ref| self.alloc.free(@constCast(index_ref.name));
        self.alloc.free(managed_indexes);
    }
    if (managed_indexes.len == 0) return;

    var saw_entries = false;
    var replay_ctx = ReplayApplyContext{
        .db = self,
        .dense_bulk_session_scope = .external,
    };
    for (managed_indexes) |index_ref| {
        const applied = try self.core.loadAppliedSequence(self.alloc, index_ref.name);
        const use_dense_catch_up = index_ref.kind == .dense_vector;
        const resources = self.core.batchExecutionResources();
        const target_sequence = try self.probeDerivedReplayTargetSequence(
            self.alloc,
            resources.replay_source,
            index_ref,
            applied,
        );
        persist_progress_ctx.target_sequence = target_sequence;
        persist_progress_ctx.scanned_entries = 0;
        persist_progress_ctx.applied_entries = 0;
        persist_progress_ctx.track_dense = use_dense_catch_up;
        persist_progress_ctx.active = use_dense_catch_up and target_sequence > applied;
        if (use_dense_catch_up) {
            setDenseCatchUpProgress(self.async_context, .{
                .sequence = applied,
                .target_sequence = target_sequence,
                .scanned_entries = 0,
                .applied_entries = 0,
                .active = persist_progress_ctx.active,
            });
            if (progress_hook) |hook| {
                try hook(progress_ctx.?, index_ref.name, .{
                    .sequence = applied,
                    .target_sequence = target_sequence,
                    .scanned_entries = 0,
                    .applied_entries = 0,
                    .active = persist_progress_ctx.active,
                });
            }
        }
        var dense_replay_progress_ctx = DenseReplayProgressContext{
            .db = self,
            .persist = &persist_progress_ctx,
            .index_name = index_ref.name,
            .last_log_ns = monotonicTimeNs(),
        };
        const stats = try derived_worker.catchUpIndexWithOptions(
            self.alloc,
            resources.replay_source,
            index_ref,
            applied,
            &replay_ctx,
            applyDerivedBatchToIndexReplay,
            .{
                .resource_manager = resources.index_manager.resource_manager,
                .window_ctx = &replay_ctx,
                .begin_window_fn = @field(@This(), "beginDerivedCatchUpWindow"),
                .finish_window_fn = @field(@This(), "finishDerivedCatchUpWindow"),
                .progress_ctx = if (use_dense_catch_up) &dense_replay_progress_ctx else null,
                .progress_fn = if (use_dense_catch_up) DenseReplayProgressContext.run else null,
                .persist_ctx = &persist_progress_ctx,
                .persist_progress_fn = PersistReplayProgress.run,
                .max_records_per_window = if (progress_hook != null and use_dense_catch_up) denseCatchUpStartupMaxRecords() else derived_worker.catch_up_max_records_per_window_default,
                .max_chunk_bytes = if (progress_hook != null and use_dense_catch_up) denseCatchUpStartupMaxChunkBytes() else derived_worker.catch_up_max_chunk_bytes_default,
            },
        );
        if (openProfileEnabled()) logReplayCatchUpProfile(index_ref, applied, stats);
        if (use_dense_catch_up) {
            _ = try resources.index_manager.runDenseLsmMaintenanceByName(index_ref.name, denseCatchUpMaintenanceSteps());
            persist_progress_ctx.active = false;
            const final_progress: ReplayProgress = .{
                .sequence = @max(stats.last_sequence, applied),
                .target_sequence = target_sequence,
                .scanned_entries = @intCast(stats.scanned_entries),
                .applied_entries = @intCast(stats.applied_entries),
                .active = false,
            };
            setDenseCatchUpProgress(self.async_context, final_progress);
            if (progress_hook) |hook| {
                try hook(progress_ctx.?, index_ref.name, final_progress);
            }
        }
        saw_entries = saw_entries or stats.scanned_entries > 0;
        if (stats.appliedSequenceAdvance(applied)) |sequence| {
            try resources.index_manager.checkpointLsmWalForManagedIndex(index_ref);
            try self.core.saveAppliedSequence(index_ref.name, sequence);
        } else if (stats.shouldTryTargetAdvance(applied, target_sequence) and
            try canAdvanceDerivedToTargetAsync(self.async_context, index_ref, applied, target_sequence))
        {
            try resources.index_manager.checkpointLsmWalForManagedIndex(index_ref);
            try self.core.saveAppliedSequence(index_ref.name, target_sequence);
        }
    }
    if (options.truncate_replay) try truncateReplayJournalIfSafe(self);
}

fn applyDerivedBatchToIndex(self: *DB, batch: derived_types.DerivedBatch, index_ref: index_manager_mod.ManagedIndexRef) !void {
    const resources = self.core.asyncResources();
    const ctx = AsyncContext{
        .alloc = self.alloc,
        .store = resources.store,
        .applied_sequence_checkpoint_path = resources.applied_sequence_checkpoint_path,
        .index_manager = resources.index_manager,
        .apply_mutex = resources.apply_mutex,
        .text_merge_runtime = self.text_merge_runtime,
    };
    try applyDerivedBatchToIndexContext(&ctx, batch, index_ref);
}

fn applyDerivedBatchToIndexContext(ctx: *const AsyncContext, batch: derived_types.DerivedBatch, index_ref: index_manager_mod.ManagedIndexRef) !void {
    try applyDerivedBatchToIndexContextProfiled(ctx, batch, index_ref, null);
}

fn loadDerivedCoverageOutcomeCounterFromStore(
    alloc: Allocator,
    store: *docstore_mod.DocStore,
    index_name: []const u8,
    generation: u64,
    outcome: []const u8,
) !?u64 {
    const counter_key = try internal_keys.derivedCoverageOutcomeCountKeyAlloc(alloc, index_name, generation, outcome);
    defer alloc.free(counter_key);
    const raw = store.get(alloc, counter_key) catch |err| switch (err) {
        error.NotFound => return null,
        else => return err,
    };
    defer alloc.free(raw);
    return try internal_keys.decodeDerivedCoverageOutcomeCount(raw);
}

fn scanDerivedCoverageOutcomeFromStore(
    alloc: Allocator,
    store: *docstore_mod.DocStore,
    index_name: []const u8,
    generation: u64,
    outcome: []const u8,
) !u64 {
    const lower = try internal_keys.derivedCoverageOutcomeMarkerPrefixAlloc(alloc, index_name, generation);
    defer alloc.free(lower);
    const upper = try internal_keys.nextPrefixAlloc(alloc, lower);
    defer if (upper) |key| alloc.free(key);
    const upper_bound = if (upper) |key| key else "";

    var skipped: u64 = 0;
    const CountState = struct {
        count: *u64,
        outcome_name: []const u8,

        fn scanEntry(ctx: ?*anyopaque, key: []const u8, value: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
            _ = key;
            const state: *@This() = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
            if (std.mem.eql(u8, value, state.outcome_name)) state.count.* += 1;
            return .@"continue";
        }
    };

    var state = CountState{ .count = &skipped, .outcome_name = outcome };
    try store.scanWithContext(lower, upper_bound, .{}, &state, CountState.scanEntry);
    return skipped;
}

fn derivedCoverageOutcomeCounterValueForStore(
    alloc: Allocator,
    store: *docstore_mod.DocStore,
    index_name: []const u8,
    generation: u64,
    outcome: []const u8,
) !u64 {
    return (try loadDerivedCoverageOutcomeCounterFromStore(alloc, store, index_name, generation, outcome)) orelse
        try scanDerivedCoverageOutcomeFromStore(alloc, store, index_name, generation, outcome);
}

const DerivedCoverageOutcome = enum { produced, skipped, terminal_failed };

const DerivedCoverageDocOutcome = struct {
    doc_key: []const u8,
    outcome: DerivedCoverageOutcome,
};

fn setDerivedCoverageOutcomes(
    alloc: Allocator,
    store: *docstore_mod.DocStore,
    index_manager: *index_manager_mod.IndexManager,
    index_name: []const u8,
    outcomes: []const DerivedCoverageDocOutcome,
) !void {
    if (outcomes.len == 0) return;
    const generation = index_manager.coverageGenerationForIndex(index_name) orelse return;
    const tags = std.meta.tags(DerivedCoverageOutcome);

    var counter_counts: [tags.len]u64 = undefined;
    var counter_keys: [tags.len][]u8 = undefined;
    var initialized_counters: usize = 0;
    defer for (counter_keys[0..initialized_counters]) |key| alloc.free(key);
    inline for (tags, 0..) |outcome, i| {
        counter_counts[i] = try derivedCoverageOutcomeCounterValueForStore(alloc, store, index_name, generation, @tagName(outcome));
        counter_keys[i] = try internal_keys.derivedCoverageOutcomeCountKeyAlloc(alloc, index_name, generation, @tagName(outcome));
        initialized_counters += 1;
    }

    var owned_marker_keys = std.ArrayListUnmanaged([]u8).empty;
    defer {
        for (owned_marker_keys.items) |key| alloc.free(key);
        owned_marker_keys.deinit(alloc);
    }
    var writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
    defer writes.deinit(alloc);
    var seen = std.StringHashMapUnmanaged(void).empty;
    defer seen.deinit(alloc);
    var changed = false;

    for (outcomes) |transition| {
        if (seen.contains(transition.doc_key)) continue;
        try seen.put(alloc, transition.doc_key, {});
        const target_index = @intFromEnum(transition.outcome);
        const marker_key = try internal_keys.derivedCoverageOutcomeKeyAlloc(alloc, index_name, generation, transition.doc_key);
        owned_marker_keys.append(alloc, marker_key) catch |err| {
            alloc.free(marker_key);
            return err;
        };
        const existing = store.get(alloc, marker_key) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
        const existing_outcome: ?DerivedCoverageOutcome = if (existing) |value| blk: {
            defer alloc.free(value);
            break :blk std.meta.stringToEnum(DerivedCoverageOutcome, value) orelse return error.InvalidDerivedCoverageOutcome;
        } else null;
        if (existing_outcome == null or existing_outcome.? != transition.outcome) {
            if (existing_outcome) |previous| {
                const previous_index = @intFromEnum(previous);
                if (counter_counts[previous_index] == 0) return error.InvalidDerivedCoverageCounter;
                counter_counts[previous_index] -= 1;
            }
            counter_counts[target_index] +|= 1;
            try writes.append(alloc, .{ .key = marker_key, .value = @tagName(transition.outcome) });
            changed = true;
        }
    }
    if (!changed) return;

    var counter_values: [tags.len][8]u8 = undefined;
    inline for (tags, 0..) |_, i| {
        try writes.append(alloc, .{
            .key = counter_keys[i],
            .value = internal_keys.encodeDerivedCoverageOutcomeCount(&counter_values[i], counter_counts[i]),
        });
    }
    try store.putBatch(writes.items, &.{});
}

fn accountDenseCoverage(
    ctx: *const AsyncContext,
    index_name: []const u8,
    batch: derived_types.DerivedBatch,
    writes: []const mapper.DenseEmbeddingWrite,
) !void {
    const external = ctx.index_manager.denseIndexUsesExternalCoverage(index_name);
    var produced = std.StringHashMapUnmanaged(void).empty;
    defer produced.deinit(ctx.alloc);
    for (writes) |write| {
        try produced.put(ctx.alloc, write.parent_doc_key orelse write.doc_key, {});
    }
    var outcomes = std.ArrayListUnmanaged(DerivedCoverageDocOutcome).empty;
    defer outcomes.deinit(ctx.alloc);
    if (!external) {
        for (batch.documents) |doc| {
            if (doc.action == .delete or internal_keys.isInternalUserKey(doc.key) or !ctx.index_manager.byte_range.contains(doc.key)) continue;
            try outcomes.append(ctx.alloc, .{
                .doc_key = doc.key,
                .outcome = if (produced.contains(doc.key))
                    .produced
                else
                    try denseMissingArtifactCoverageOutcome(ctx, index_name, doc.key),
            });
        }
    } else {
        var iter = produced.keyIterator();
        while (iter.next()) |doc_key| {
            if (internal_keys.isInternalUserKey(doc_key.*) or !ctx.index_manager.byte_range.contains(doc_key.*)) continue;
            try outcomes.append(ctx.alloc, .{ .doc_key = doc_key.*, .outcome = .produced });
        }
    }
    try setDerivedCoverageOutcomes(ctx.alloc, ctx.store, ctx.index_manager, index_name, outcomes.items);
}

fn denseMissingArtifactCoverageOutcome(
    ctx: *const AsyncContext,
    index_name: []const u8,
    doc_key: []const u8,
) !DerivedCoverageOutcome {
    const dense = ctx.index_manager.denseIndex(index_name) orelse return .skipped;
    const chunk_name = dense.chunk_name orelse return .skipped;
    const chunk_cfg = ctx.index_manager.getEnrichment(.chunk, chunk_name) orelse return .skipped;
    if (chunk_cfg.source_artifact_name.len == 0) return .skipped;

    const manifest_key = try internal_keys.artifactNamedPrefixAlloc(ctx.alloc, doc_key, "asset", chunk_cfg.source_artifact_name);
    defer ctx.alloc.free(manifest_key);
    const manifest = ctx.store.get(ctx.alloc, manifest_key) catch |err| switch (err) {
        error.NotFound => return .skipped,
        else => return err,
    };
    defer ctx.alloc.free(manifest);
    var parsed = try std.json.parseFromSlice(std.json.Value, ctx.alloc, manifest, .{});
    defer parsed.deinit();
    if (parsed.value != .object) return error.InvalidDocumentExtractionManifest;
    const object = parsed.value.object;
    if (object.get("last_error") != null) return .terminal_failed;
    if (object.get("merge_status")) |value| {
        if (value == .string and std.mem.eql(u8, value.string, "failed")) return .terminal_failed;
    }
    if (object.get("route_type")) |value| {
        if (value == .string and std.mem.eql(u8, value.string, "error")) return .terminal_failed;
    }
    const chunk_count = try jsonObjectU64(object, "chunk_count");
    const ocr_failed_count = try jsonObjectU64(object, "ocr_failed_count");
    const failed_pages = if (object.get("ocr_failed_page_numbers")) |value|
        if (value == .array) value.array.items.len else 0
    else
        0;
    return if (chunk_count == 0 and (ocr_failed_count > 0 or failed_pages > 0)) .terminal_failed else .skipped;
}

fn accountSparseCoverage(
    ctx: *const AsyncContext,
    index_name: []const u8,
    batch: derived_types.DerivedBatch,
    writes: []const mapper.SparseEmbeddingWrite,
) !void {
    const external = ctx.index_manager.sparseIndexUsesExternalCoverage(index_name);
    var produced = std.StringHashMapUnmanaged(void).empty;
    defer produced.deinit(ctx.alloc);
    for (writes) |write| {
        try produced.put(ctx.alloc, write.doc_key, {});
    }
    var outcomes = std.ArrayListUnmanaged(DerivedCoverageDocOutcome).empty;
    defer outcomes.deinit(ctx.alloc);
    if (!external) {
        for (batch.documents) |doc| {
            if (doc.action == .delete or internal_keys.isInternalUserKey(doc.key) or !ctx.index_manager.byte_range.contains(doc.key)) continue;
            try outcomes.append(ctx.alloc, .{
                .doc_key = doc.key,
                .outcome = if (produced.contains(doc.key)) .produced else .skipped,
            });
        }
    } else {
        var iter = produced.keyIterator();
        while (iter.next()) |doc_key| {
            if (internal_keys.isInternalUserKey(doc_key.*) or !ctx.index_manager.byte_range.contains(doc_key.*)) continue;
            try outcomes.append(ctx.alloc, .{ .doc_key = doc_key.*, .outcome = .produced });
        }
    }
    try setDerivedCoverageOutcomes(ctx.alloc, ctx.store, ctx.index_manager, index_name, outcomes.items);
}

fn deleteDerivedCoverageForDocKeys(
    alloc: Allocator,
    store: *docstore_mod.DocStore,
    index_manager: *index_manager_mod.IndexManager,
    index_name: []const u8,
    doc_keys: []const []const u8,
) !void {
    if (doc_keys.len == 0) return;
    const generation = index_manager.coverageGenerationForIndex(index_name) orelse return;

    var deletes = std.ArrayListUnmanaged([]const u8).empty;
    defer {
        for (deletes.items) |key| alloc.free(@constCast(key));
        deletes.deinit(alloc);
    }
    var unique_deletes = std.StringHashMapUnmanaged(void).empty;
    defer unique_deletes.deinit(alloc);

    const outcomes = std.meta.tags(DerivedCoverageOutcome);
    var removed_counts = [_]u64{0} ** outcomes.len;
    for (doc_keys) |doc_key| {
        const marker_key = try internal_keys.derivedCoverageOutcomeKeyAlloc(alloc, index_name, generation, doc_key);
        errdefer alloc.free(marker_key);
        if (unique_deletes.contains(marker_key)) {
            alloc.free(marker_key);
            continue;
        }
        const existing = store.get(alloc, marker_key) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
        if (existing) |value| {
            defer alloc.free(value);
            const outcome = std.meta.stringToEnum(DerivedCoverageOutcome, value) orelse return error.InvalidDerivedCoverageOutcome;
            removed_counts[@intFromEnum(outcome)] +|= 1;
        }
        try deletes.append(alloc, marker_key);
        errdefer _ = deletes.pop();
        try unique_deletes.put(alloc, marker_key, {});
    }

    if (deletes.items.len == 0) return;
    var total_removed: u64 = 0;
    for (removed_counts) |count| total_removed +|= count;
    if (total_removed == 0) {
        try store.putBatch(&.{}, deletes.items);
        return;
    }

    var counter_keys: [outcomes.len]?[]u8 = .{null} ** outcomes.len;
    defer for (counter_keys) |key| if (key) |value| alloc.free(value);
    var counter_values: [outcomes.len][8]u8 = undefined;
    var counter_writes: [outcomes.len]docstore_mod.KVPair = undefined;
    var counter_write_count: usize = 0;
    for (outcomes, removed_counts, 0..) |outcome, removed_count, outcome_index| {
        if (removed_count == 0) continue;
        const current_count = try derivedCoverageOutcomeCounterValueForStore(alloc, store, index_name, generation, @tagName(outcome));
        if (current_count < removed_count) return error.InvalidDerivedCoverageCounter;
        counter_keys[outcome_index] = try internal_keys.derivedCoverageOutcomeCountKeyAlloc(alloc, index_name, generation, @tagName(outcome));
        counter_writes[counter_write_count] = .{
            .key = counter_keys[outcome_index].?,
            .value = internal_keys.encodeDerivedCoverageOutcomeCount(&counter_values[outcome_index], current_count - removed_count),
        };
        counter_write_count += 1;
    }
    try store.putBatch(counter_writes[0..counter_write_count], deletes.items);
}

fn artifactRepairIssueKeyForIssueAlloc(alloc: Allocator, issue: types.ArtifactRepairIssue) ![]u8 {
    const issue_id = try artifactRepairIssueIdAlloc(alloc, issue);
    defer alloc.free(issue_id);
    return try internal_keys.artifactRepairIssueKeyAlloc(alloc, issue.index_name, @tagName(issue.artifact_kind), issue_id);
}

fn artifactRepairIssueKindKeyForIssueAlloc(alloc: Allocator, issue: types.ArtifactRepairIssue) ![]u8 {
    const issue_id = try artifactRepairIssueIdAlloc(alloc, issue);
    defer alloc.free(issue_id);
    return try internal_keys.artifactRepairIssueKindKeyAlloc(alloc, @tagName(issue.artifact_kind), issue.index_name, issue_id);
}

fn artifactRepairIssueIdAlloc(alloc: Allocator, issue: types.ArtifactRepairIssue) ![]u8 {
    if (issue.artifact_key.len > 0) return try alloc.dupe(u8, issue.artifact_key);
    var hasher = std.crypto.hash.sha2.Sha256.init(.{});
    artifactRepairIssueIdHashString(&hasher, issue.doc_key);
    artifactRepairIssueIdHashString(&hasher, issue.parent_doc_key);
    artifactRepairIssueIdHashString(&hasher, issue.source_artifact_name);
    artifactRepairIssueIdHashString(&hasher, issue.artifact_name);
    artifactRepairIssueIdHashString(&hasher, issue.unit_id);
    artifactRepairIssueIdHashOptionalU64(&hasher, if (issue.chunk_id) |chunk_id| @as(u64, chunk_id) else null);
    artifactRepairIssueIdHashString(&hasher, @tagName(issue.artifact_kind));
    var digest: [std.crypto.hash.sha2.Sha256.digest_length]u8 = undefined;
    hasher.final(&digest);
    const hex = try bytesToHexAlloc(alloc, &digest);
    defer alloc.free(hex);
    return try std.fmt.allocPrint(alloc, "tuple-sha256:{s}", .{hex});
}

fn artifactRepairIssueIdHashString(hasher: *std.crypto.hash.sha2.Sha256, value: []const u8) void {
    var len_buf: [8]u8 = undefined;
    std.mem.writeInt(u64, &len_buf, value.len, .little);
    hasher.update(&len_buf);
    hasher.update(value);
}

fn artifactRepairIssueIdHashOptionalU64(hasher: *std.crypto.hash.sha2.Sha256, value: ?u64) void {
    hasher.update(if (value == null) "\x00" else "\x01");
    if (value) |raw| {
        var buf: [8]u8 = undefined;
        std.mem.writeInt(u64, &buf, raw, .little);
        hasher.update(&buf);
    }
}

fn artifactRepairKindHasAutomatedReprocessor(kind: types.ArtifactRepairKind) bool {
    return switch (kind) {
        .embedding, .asset, .chunk => true,
        .graph, .full_text, .algebraic => false,
    };
}

fn artifactRepairUnsupportedReason(kind: types.ArtifactRepairKind) []const u8 {
    return switch (kind) {
        .embedding, .asset, .chunk => "",
        .graph => "graph_reprocessor_unavailable",
        .full_text => "full_text_reprocessor_unavailable",
        .algebraic => "algebraic_artifact_reprocessor_unavailable",
    };
}

fn encodeArtifactRepairIssueValueAlloc(alloc: Allocator, issue: types.ArtifactRepairIssue) ![]u8 {
    return try std.json.Stringify.valueAlloc(alloc, issue, .{ .emit_null_optional_fields = false });
}

fn decodeArtifactRepairIssueValueAlloc(alloc: Allocator, raw: []const u8) !types.ArtifactRepairIssue {
    var parsed = try std.json.parseFromSlice(std.json.Value, alloc, raw, .{});
    defer parsed.deinit();
    if (parsed.value != .object) return error.InvalidArtifactPayload;
    const obj = parsed.value.object;
    const Fields = struct {
        fn string(object: std.json.ObjectMap, name: []const u8) []const u8 {
            const value = object.get(name) orelse return "";
            if (value != .string) return "";
            return value.string;
        }
        fn u64Value(object: std.json.ObjectMap, name: []const u8) u64 {
            const value = object.get(name) orelse return 0;
            if (value != .integer or value.integer < 0) return 0;
            return std.math.cast(u64, value.integer) orelse 0;
        }
        fn optionalU32(object: std.json.ObjectMap, name: []const u8) ?u32 {
            const value = object.get(name) orelse return null;
            if (value == .null) return null;
            if (value != .integer or value.integer < 0) return null;
            return std.math.cast(u32, value.integer);
        }
        fn boolValue(object: std.json.ObjectMap, name: []const u8, default: bool) bool {
            const value = object.get(name) orelse return default;
            if (value != .bool) return default;
            return value.bool;
        }
    };
    const kind = std.meta.stringToEnum(types.ArtifactRepairKind, Fields.string(obj, "artifact_kind")) orelse .embedding;
    const reason = std.meta.stringToEnum(types.ArtifactRepairReason, Fields.string(obj, "reason")) orelse .missing_artifact;
    const default_repairable = artifactRepairKindHasAutomatedReprocessor(kind);
    var issue = types.ArtifactRepairIssue{
        .artifact_kind = kind,
        .chunk_id = Fields.optionalU32(obj, "chunk_id"),
        .repairable = Fields.boolValue(obj, "repairable", default_repairable),
        .sequence = Fields.u64Value(obj, "sequence"),
        .reason = reason,
        .generation_attempts = Fields.u64Value(obj, "generation_attempts"),
        .attempts = Fields.u64Value(obj, "attempts"),
        .first_seen_ns = Fields.u64Value(obj, "first_seen_ns"),
        .last_seen_ns = Fields.u64Value(obj, "last_seen_ns"),
    };
    errdefer issue.deinit(alloc);
    issue.index_name = try alloc.dupe(u8, Fields.string(obj, "index_name"));
    issue.doc_key = try alloc.dupe(u8, Fields.string(obj, "doc_key"));
    issue.parent_doc_key = try alloc.dupe(u8, Fields.string(obj, "parent_doc_key"));
    issue.unit_id = try alloc.dupe(u8, Fields.string(obj, "unit_id"));
    issue.source_artifact_name = try alloc.dupe(u8, Fields.string(obj, "source_artifact_name"));
    issue.artifact_name = try alloc.dupe(u8, Fields.string(obj, "artifact_name"));
    issue.artifact_key = try alloc.dupe(u8, Fields.string(obj, "artifact_key"));
    issue.unsupported_reason = try alloc.dupe(u8, Fields.string(obj, "unsupported_reason"));
    issue.generation_error = try alloc.dupe(u8, Fields.string(obj, "generation_error"));
    issue.last_error = try alloc.dupe(u8, Fields.string(obj, "last_error"));
    return issue;
}

fn loadArtifactRepairIssueFromStoreByKey(
    alloc: Allocator,
    store: *docstore_mod.DocStore,
    key: []const u8,
) !?types.ArtifactRepairIssue {
    const raw = store.get(alloc, key) catch |err| switch (err) {
        error.NotFound => return null,
        else => return err,
    };
    defer alloc.free(raw);
    return try decodeArtifactRepairIssueValueAlloc(alloc, raw);
}

fn cloneArtifactRepairIssueAlloc(alloc: Allocator, issue: types.ArtifactRepairIssue) !types.ArtifactRepairIssue {
    var out = types.ArtifactRepairIssue{
        .artifact_kind = issue.artifact_kind,
        .chunk_id = issue.chunk_id,
        .repairable = issue.repairable,
        .sequence = issue.sequence,
        .reason = issue.reason,
        .generation_attempts = issue.generation_attempts,
        .attempts = issue.attempts,
        .first_seen_ns = issue.first_seen_ns,
        .last_seen_ns = issue.last_seen_ns,
    };
    errdefer out.deinit(alloc);
    out.index_name = try alloc.dupe(u8, issue.index_name);
    out.doc_key = try alloc.dupe(u8, issue.doc_key);
    out.parent_doc_key = try alloc.dupe(u8, issue.parent_doc_key);
    out.unit_id = try alloc.dupe(u8, issue.unit_id);
    out.source_artifact_name = try alloc.dupe(u8, issue.source_artifact_name);
    out.artifact_name = try alloc.dupe(u8, issue.artifact_name);
    out.artifact_key = try alloc.dupe(u8, issue.artifact_key);
    out.unsupported_reason = try alloc.dupe(u8, issue.unsupported_reason);
    out.generation_error = try alloc.dupe(u8, issue.generation_error);
    out.last_error = try alloc.dupe(u8, issue.last_error);
    return out;
}

fn replaceRepairIssueLastError(alloc: Allocator, issue: *types.ArtifactRepairIssue, value: []const u8) !void {
    const owned = try alloc.dupe(u8, value);
    if (issue.last_error.len > 0) alloc.free(@constCast(issue.last_error));
    issue.last_error = owned;
}

fn saveArtifactRepairIssueToStore(
    alloc: Allocator,
    store: *docstore_mod.DocStore,
    issue: types.ArtifactRepairIssue,
) !void {
    const key = try artifactRepairIssueKeyForIssueAlloc(alloc, issue);
    defer alloc.free(key);
    const kind_key = try artifactRepairIssueKindKeyForIssueAlloc(alloc, issue);
    defer alloc.free(kind_key);
    const encoded = try encodeArtifactRepairIssueValueAlloc(alloc, issue);
    defer alloc.free(encoded);
    const writes = [_]docstore_mod.KVPair{
        .{ .key = key, .value = encoded },
        .{ .key = kind_key, .value = encoded },
    };
    try store.putBatch(writes[0..], &.{});
}

fn appendKeysForPrefixDeleteInStore(
    alloc: Allocator,
    store: *docstore_mod.DocStore,
    deletes: *std.ArrayListUnmanaged([]const u8),
    owned_keys: *std.ArrayListUnmanaged([]const u8),
    prefix: []const u8,
) !void {
    const upper = try internal_keys.nextPrefixAlloc(alloc, prefix);
    defer if (upper) |buf| alloc.free(buf);
    const ScanState = struct {
        alloc: Allocator,
        deletes: *std.ArrayListUnmanaged([]const u8),
        owned_keys: *std.ArrayListUnmanaged([]const u8),

        fn scanEntry(ctx: ?*anyopaque, key: []const u8, _: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
            const state: *@This() = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
            const key_copy = try state.alloc.dupe(u8, key);
            errdefer state.alloc.free(key_copy);
            const owned_len = state.owned_keys.items.len;
            try state.owned_keys.append(state.alloc, key_copy);
            errdefer state.owned_keys.shrinkRetainingCapacity(owned_len);
            try state.deletes.append(state.alloc, key_copy);
            return .@"continue";
        }
    };
    var state = ScanState{ .alloc = alloc, .deletes = deletes, .owned_keys = owned_keys };
    try store.scanWithContext(prefix, if (upper) |buf| buf else "", .{}, &state, ScanState.scanEntry);
}

fn appendArtifactRepairSummaryRebuildInvalidationForStore(
    alloc: Allocator,
    store: *docstore_mod.DocStore,
    writes: ?*std.ArrayListUnmanaged(docstore_mod.KVPair),
    deletes: *std.ArrayListUnmanaged([]const u8),
    owned_keys: *std.ArrayListUnmanaged([]const u8),
) !void {
    const progress_key = try internal_keys.artifactRepairSummaryProgressKeyAlloc(alloc);
    errdefer alloc.free(progress_key);
    const owned_len = owned_keys.items.len;
    try owned_keys.append(alloc, progress_key);
    errdefer owned_keys.shrinkRetainingCapacity(owned_len);
    if (writes) |out| {
        const dirty_value = try alloc.dupe(u8, artifact_repair_summary_dirty_marker);
        errdefer alloc.free(dirty_value);
        try out.append(alloc, .{ .key = progress_key, .value = dirty_value });
    } else {
        try deletes.append(alloc, progress_key);
    }

    const rebuild_prefix = try internal_keys.artifactRepairSummaryRebuildRootKeyAlloc(alloc);
    defer alloc.free(rebuild_prefix);
    try appendKeysForPrefixDeleteInStore(alloc, store, deletes, owned_keys, rebuild_prefix);
}

fn appendArtifactRepairSummaryDirtyForStore(
    alloc: Allocator,
    store: *docstore_mod.DocStore,
    writes: *std.ArrayListUnmanaged(docstore_mod.KVPair),
    deletes: *std.ArrayListUnmanaged([]const u8),
    owned_delete_keys: *std.ArrayListUnmanaged([]const u8),
) !void {
    const ready_key = try internal_keys.artifactRepairSummaryReadyKeyAlloc(alloc);
    errdefer alloc.free(ready_key);
    const owned_len = owned_delete_keys.items.len;
    try owned_delete_keys.append(alloc, ready_key);
    errdefer owned_delete_keys.shrinkRetainingCapacity(owned_len);
    try deletes.append(alloc, ready_key);
    try appendArtifactRepairSummaryRebuildInvalidationForStore(alloc, store, writes, deletes, owned_delete_keys);
}

/// Invalidate summary publication in constant space. Retired-index cleanup
/// already owns the global apply lock, so a rebuild cannot commit over this
/// marker; maintenance drains any shadow state in bounded pages before it
/// starts a fresh summary pass.
fn appendArtifactRepairSummaryDirtyMarkerForStore(
    alloc: Allocator,
    writes: *std.ArrayListUnmanaged(docstore_mod.KVPair),
    deletes: *std.ArrayListUnmanaged([]const u8),
    owned_keys: *std.ArrayListUnmanaged([]const u8),
) !void {
    const ready_key = try internal_keys.artifactRepairSummaryReadyKeyAlloc(alloc);
    errdefer alloc.free(ready_key);
    const ready_owned_len = owned_keys.items.len;
    try owned_keys.append(alloc, ready_key);
    errdefer owned_keys.shrinkRetainingCapacity(ready_owned_len);
    try deletes.append(alloc, ready_key);

    const progress_key = try internal_keys.artifactRepairSummaryProgressKeyAlloc(alloc);
    errdefer alloc.free(progress_key);
    const progress_owned_len = owned_keys.items.len;
    try owned_keys.append(alloc, progress_key);
    errdefer owned_keys.shrinkRetainingCapacity(progress_owned_len);
    const dirty_value = try alloc.dupe(u8, artifact_repair_summary_dirty_marker);
    errdefer alloc.free(dirty_value);
    try writes.append(alloc, .{ .key = progress_key, .value = dirty_value });
}

const artifact_repair_completion_state_len = 24;

const ArtifactRepairCompletionState = struct {
    /// Incremented for every failure publication for this physical artifact.
    /// A repair may commit only if the epoch observed before provider work is
    /// still current afterward.
    epoch: u64 = 0,
    completed_sequence: u64 = 0,
    pending_issues: u64 = 0,
};

fn encodeArtifactRepairCompletionState(
    out: *[artifact_repair_completion_state_len]u8,
    state: ArtifactRepairCompletionState,
) void {
    std.mem.writeInt(u64, out[0..8], state.epoch, .little);
    std.mem.writeInt(u64, out[8..16], state.completed_sequence, .little);
    std.mem.writeInt(u64, out[16..24], state.pending_issues, .little);
}

fn loadArtifactRepairCompletionStateFromStore(
    alloc: Allocator,
    store: *docstore_mod.DocStore,
    key: []const u8,
) !?ArtifactRepairCompletionState {
    const raw = store.get(alloc, key) catch |err| switch (err) {
        error.NotFound => return null,
        else => return err,
    };
    defer alloc.free(raw);
    // This fence is an optimization, never authoritative repair debt. Treat a
    // malformed value as absent so metadata corruption cannot wedge repair;
    // the next issue transition overwrites or deletes it atomically.
    if (raw.len != artifact_repair_completion_state_len) return null;
    return .{
        .epoch = std.mem.readInt(u64, raw[0..8], .little),
        .completed_sequence = std.mem.readInt(u64, raw[8..16], .little),
        .pending_issues = std.mem.readInt(u64, raw[16..24], .little),
    };
}

fn saveArtifactRepairIssueToStoreWithSummary(
    alloc: Allocator,
    store: *docstore_mod.DocStore,
    key: []const u8,
    issue: types.ArtifactRepairIssue,
    new_issue: bool,
    extra_writes: []const docstore_mod.KVPair,
    extra_deletes: []const []const u8,
) !void {
    const kind_key = try artifactRepairIssueKindKeyForIssueAlloc(alloc, issue);
    defer alloc.free(kind_key);
    const encoded = try encodeArtifactRepairIssueValueAlloc(alloc, issue);
    defer alloc.free(encoded);
    if (!new_issue) {
        var writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
        defer writes.deinit(alloc);
        try writes.append(alloc, .{ .key = key, .value = encoded });
        try writes.append(alloc, .{ .key = kind_key, .value = encoded });
        try writes.appendSlice(alloc, extra_writes);
        try store.putBatch(writes.items, extra_deletes);
        return;
    }

    var writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
    var borrowed_write_count: usize = 0;
    defer {
        for (writes.items[borrowed_write_count..]) |item| alloc.free(@constCast(item.value));
        writes.deinit(alloc);
    }
    var deletes = std.ArrayListUnmanaged([]const u8).empty;
    defer deletes.deinit(alloc);
    var owned_delete_keys = std.ArrayListUnmanaged([]const u8).empty;
    defer {
        for (owned_delete_keys.items) |owned_key| alloc.free(@constCast(owned_key));
        owned_delete_keys.deinit(alloc);
    }

    try writes.append(alloc, .{ .key = key, .value = encoded });
    try writes.append(alloc, .{ .key = kind_key, .value = encoded });
    borrowed_write_count = writes.items.len;
    try writes.appendSlice(alloc, extra_writes);
    borrowed_write_count = writes.items.len;
    try deletes.appendSlice(alloc, extra_deletes);
    try appendArtifactRepairSummaryDirtyForStore(alloc, store, &writes, &deletes, &owned_delete_keys);
    try store.putBatch(writes.items, deletes.items);
}

fn recordEmbeddingArtifactRepairIssueContext(
    ctx: *const AsyncContext,
    index_name: []const u8,
    artifact_key: []const u8,
    sequence: u64,
    reason: types.ArtifactRepairReason,
) !void {
    const mutable_ctx = @constCast(ctx);
    lockAtomicWithBackoff(&mutable_ctx.artifact_repair_issue_mutex);
    defer mutable_ctx.artifact_repair_issue_mutex.unlock();
    var identity = (try artifact_ids.decodeEmbeddingArtifactIdentityAlloc(ctx.alloc, artifact_key)) orelse return;
    defer identity.deinit(ctx.alloc);

    const artifact_key_hex = try bytesToHexAlloc(ctx.alloc, artifact_key);
    defer ctx.alloc.free(artifact_key_hex);
    const issue_key = try internal_keys.artifactRepairIssueKeyAlloc(ctx.alloc, index_name, "embedding", artifact_key_hex);
    defer ctx.alloc.free(issue_key);

    const now_ns = currentTimeNs();
    const existing = try loadArtifactRepairIssueFromStoreByKey(ctx.alloc, ctx.store, issue_key);
    var issue = if (existing) |loaded|
        loaded
    else
        types.ArtifactRepairIssue{
            .artifact_kind = .embedding,
            .index_name = try ctx.alloc.dupe(u8, index_name),
            .doc_key = try ctx.alloc.dupe(u8, identity.doc_key),
            .parent_doc_key = try ctx.alloc.dupe(u8, identity.parent_doc_key orelse ""),
            .unit_id = try ctx.alloc.dupe(u8, identity.unit_id orelse ""),
            .source_artifact_name = try ctx.alloc.dupe(u8, identity.source_artifact_name orelse ""),
            .artifact_name = try ctx.alloc.dupe(u8, identity.embedding_name),
            .artifact_key = try ctx.alloc.dupe(u8, artifact_key_hex),
            .chunk_id = identity.chunk_id,
            .repairable = true,
            .first_seen_ns = now_ns,
        };
    defer issue.deinit(ctx.alloc);

    issue.sequence = sequence;
    issue.reason = reason;
    issue.chunk_id = identity.chunk_id;
    issue.repairable = true;
    issue.last_seen_ns = nextArtifactRepairIssueTimestamp(issue.last_seen_ns, now_ns);
    if (issue.artifact_key.len == 0) {
        issue.artifact_key = try ctx.alloc.dupe(u8, artifact_key_hex);
    }
    if (issue.parent_doc_key.len == 0) {
        issue.parent_doc_key = try ctx.alloc.dupe(u8, identity.parent_doc_key orelse "");
    }
    if (issue.unit_id.len == 0) {
        issue.unit_id = try ctx.alloc.dupe(u8, identity.unit_id orelse "");
    }
    if (issue.source_artifact_name.len == 0) {
        issue.source_artifact_name = try ctx.alloc.dupe(u8, identity.source_artifact_name orelse "");
    }

    const completion_key = try internal_keys.artifactRepairCompletionKeyAlloc(ctx.alloc, "embedding", artifact_key_hex);
    defer ctx.alloc.free(completion_key);
    try saveArtifactRepairIssueToStoreWithSummary(
        ctx.alloc,
        ctx.store,
        issue_key,
        issue,
        existing == null,
        &.{},
        &.{completion_key},
    );
    if (ctx.repair_issue_counter) |counter| _ = counter.fetchAdd(1, .monotonic);
}

/// Successful index publication is the authoritative resolution boundary for
/// artifact diagnoses. Retire only diagnoses that are no newer than the batch
/// which proved the artifact readable and consumable. Provider failures also
/// require produced/skipped coverage and settle their shared completion fence
/// in the same metadata transaction.
fn clearPublishedEmbeddingArtifactRepairIssueContext(
    ctx: *const AsyncContext,
    index_name: []const u8,
    artifact_key: []const u8,
    published_sequence: u64,
) !void {
    const artifact_key_hex = try bytesToHexAlloc(ctx.alloc, artifact_key);
    defer ctx.alloc.free(artifact_key_hex);
    const issue_key = try internal_keys.artifactRepairIssueKeyAlloc(ctx.alloc, index_name, "embedding", artifact_key_hex);
    defer ctx.alloc.free(issue_key);

    const mutable_ctx = @constCast(ctx);
    lockAtomicWithBackoff(&mutable_ctx.artifact_repair_issue_mutex);
    defer mutable_ctx.artifact_repair_issue_mutex.unlock();

    const loaded = (try loadArtifactRepairIssueFromStoreByKey(ctx.alloc, ctx.store, issue_key)) orelse return;
    var issue = loaded;
    defer issue.deinit(ctx.alloc);
    if (issue.sequence > published_sequence) return;

    var completion_key: ?[]u8 = null;
    defer if (completion_key) |key| ctx.alloc.free(key);
    var completion: ArtifactRepairCompletionState = .{};
    var encoded_completion: [artifact_repair_completion_state_len]u8 = undefined;
    if (issue.reason == .enrichment_failed) {
        if (ctx.index_manager.denseIndex(index_name) == null and
            ctx.index_manager.sparseIndex(index_name) == null)
        {
            return;
        }
        const generation = ctx.index_manager.coverageGenerationForIndex(index_name) orelse return;
        const marker_key = try internal_keys.derivedCoverageOutcomeKeyAlloc(ctx.alloc, index_name, generation, issue.doc_key);
        defer ctx.alloc.free(marker_key);
        const raw_outcome = ctx.store.get(ctx.alloc, marker_key) catch |err| switch (err) {
            error.NotFound => return,
            else => return err,
        };
        defer ctx.alloc.free(raw_outcome);
        const outcome = std.meta.stringToEnum(DerivedCoverageOutcome, raw_outcome) orelse
            return error.InvalidDerivedCoverageOutcome;
        if (outcome != .produced and outcome != .skipped) return;

        completion_key = try internal_keys.artifactRepairCompletionKeyAlloc(ctx.alloc, "embedding", artifact_key_hex);
        completion = (try loadArtifactRepairCompletionStateFromStore(ctx.alloc, ctx.store, completion_key.?)) orelse .{};
        completion.completed_sequence = @max(completion.completed_sequence, published_sequence);
        completion.pending_issues -|= 1;
    }

    const kind_key = try artifactRepairIssueKindKeyForIssueAlloc(ctx.alloc, issue);
    defer ctx.alloc.free(kind_key);
    var writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
    var borrowed_write_count: usize = 0;
    defer {
        for (writes.items[borrowed_write_count..]) |write| ctx.alloc.free(@constCast(write.value));
        writes.deinit(ctx.alloc);
    }
    var deletes = std.ArrayListUnmanaged([]const u8).empty;
    defer deletes.deinit(ctx.alloc);
    var owned_delete_keys = std.ArrayListUnmanaged([]const u8).empty;
    defer {
        for (owned_delete_keys.items) |key| ctx.alloc.free(@constCast(key));
        owned_delete_keys.deinit(ctx.alloc);
    }

    try deletes.append(ctx.alloc, issue_key);
    try deletes.append(ctx.alloc, kind_key);
    if (issue.reason == .enrichment_failed) {
        try appendEnrichmentTerminalFailureMarkerDeletesForIssue(
            ctx.alloc,
            ctx.store,
            issue_key,
            &deletes,
            &owned_delete_keys,
            true,
        );
    }
    if (completion_key) |key| {
        if (completion.pending_issues == 0) {
            try deletes.append(ctx.alloc, key);
        } else {
            encodeArtifactRepairCompletionState(&encoded_completion, completion);
            try writes.append(ctx.alloc, .{ .key = key, .value = &encoded_completion });
        }
    }
    borrowed_write_count = writes.items.len;
    try appendArtifactRepairSummaryDirtyForStore(ctx.alloc, ctx.store, &writes, &deletes, &owned_delete_keys);
    try ctx.store.putBatch(writes.items, deletes.items);
}

fn clearPublishedEmbeddingArtifactRepairIssuesContext(
    ctx: *const AsyncContext,
    index_name: []const u8,
    writes: anytype,
    published_sequence: u64,
) !void {
    for (writes) |write| {
        const artifact_key = write.artifact_key orelse continue;
        try clearPublishedEmbeddingArtifactRepairIssueContext(ctx, index_name, artifact_key, published_sequence);
    }
}

fn repairKindFromArtifactKind(kind: types.ArtifactKind) types.ArtifactRepairKind {
    return switch (kind) {
        .asset => .asset,
        .chunk => .chunk,
        .embedding => .embedding,
    };
}

fn recordArtifactRepairIssueContextDetailed(
    ctx: *const AsyncContext,
    artifact_kind: types.ArtifactRepairKind,
    index_name: []const u8,
    doc_key: []const u8,
    parent_doc_key: []const u8,
    unit_id: []const u8,
    source_artifact_name: []const u8,
    artifact_name: []const u8,
    artifact_key: []const u8,
    chunk_id: ?u32,
    sequence: u64,
    reason: types.ArtifactRepairReason,
    generation_attempts: u64,
    generation_error: []const u8,
) !void {
    const kind_name = @tagName(artifact_kind);
    const artifact_key_hex = if (artifact_key.len > 0)
        try bytesToHexAlloc(ctx.alloc, artifact_key)
    else
        try ctx.alloc.dupe(u8, "");
    defer ctx.alloc.free(artifact_key_hex);
    const issue_id = try artifactRepairIssueIdAlloc(ctx.alloc, .{
        .artifact_kind = artifact_kind,
        .index_name = index_name,
        .doc_key = doc_key,
        .parent_doc_key = parent_doc_key,
        .unit_id = unit_id,
        .source_artifact_name = source_artifact_name,
        .artifact_name = artifact_name,
        .artifact_key = artifact_key_hex,
        .chunk_id = chunk_id,
    });
    defer ctx.alloc.free(issue_id);
    const issue_key = try internal_keys.artifactRepairIssueKeyAlloc(ctx.alloc, index_name, kind_name, issue_id);
    defer ctx.alloc.free(issue_key);

    const mutable_ctx = @constCast(ctx);
    lockAtomicWithBackoff(&mutable_ctx.artifact_repair_issue_mutex);
    defer mutable_ctx.artifact_repair_issue_mutex.unlock();

    const now_ns = currentTimeNs();
    const existing = try loadArtifactRepairIssueFromStoreByKey(ctx.alloc, ctx.store, issue_key);
    const existing_was_pending = if (existing) |loaded| loaded.reason == .enrichment_failed else false;
    const previous_terminal_sequence: ?u64 = if (existing) |loaded|
        if (loaded.reason == .enrichment_failed) loaded.sequence else null
    else
        null;
    var issue = if (existing) |loaded|
        loaded
    else
        types.ArtifactRepairIssue{
            .artifact_kind = artifact_kind,
            .index_name = try ctx.alloc.dupe(u8, index_name),
            .doc_key = try ctx.alloc.dupe(u8, doc_key),
            .parent_doc_key = try ctx.alloc.dupe(u8, parent_doc_key),
            .unit_id = try ctx.alloc.dupe(u8, unit_id),
            .source_artifact_name = try ctx.alloc.dupe(u8, source_artifact_name),
            .artifact_name = try ctx.alloc.dupe(u8, artifact_name),
            .artifact_key = if (artifact_key_hex.len > 0) try ctx.alloc.dupe(u8, artifact_key_hex) else "",
            .chunk_id = chunk_id,
            .repairable = artifactRepairKindHasAutomatedReprocessor(artifact_kind),
            .unsupported_reason = try ctx.alloc.dupe(u8, artifactRepairUnsupportedReason(artifact_kind)),
            .first_seen_ns = now_ns,
        };
    defer issue.deinit(ctx.alloc);

    const merged_generation_attempts = mergeGenerationFailureAttempts(
        issue.reason,
        issue.sequence,
        issue.generation_error,
        issue.generation_attempts,
        reason,
        sequence,
        generation_error,
        generation_attempts,
    );
    issue.artifact_kind = artifact_kind;
    issue.sequence = sequence;
    issue.reason = reason;
    issue.generation_attempts = merged_generation_attempts;
    issue.chunk_id = chunk_id;
    issue.repairable = artifactRepairKindHasAutomatedReprocessor(artifact_kind);
    issue.last_seen_ns = nextArtifactRepairIssueTimestamp(issue.last_seen_ns, now_ns);
    if (issue.artifact_key.len == 0 and artifact_key_hex.len > 0) {
        issue.artifact_key = try ctx.alloc.dupe(u8, artifact_key_hex);
    }
    if (issue.parent_doc_key.len == 0 and parent_doc_key.len > 0) {
        issue.parent_doc_key = try ctx.alloc.dupe(u8, parent_doc_key);
    }
    if (issue.unit_id.len == 0 and unit_id.len > 0) {
        issue.unit_id = try ctx.alloc.dupe(u8, unit_id);
    }
    if (issue.source_artifact_name.len == 0 and source_artifact_name.len > 0) {
        issue.source_artifact_name = try ctx.alloc.dupe(u8, source_artifact_name);
    }
    if (issue.unsupported_reason.len == 0 and !issue.repairable) {
        issue.unsupported_reason = try ctx.alloc.dupe(u8, artifactRepairUnsupportedReason(artifact_kind));
    }
    if (!std.mem.eql(u8, issue.generation_error, generation_error)) {
        const owned_generation_error = if (generation_error.len > 0)
            try ctx.alloc.dupe(u8, generation_error)
        else
            "";
        if (issue.generation_error.len > 0) ctx.alloc.free(@constCast(issue.generation_error));
        issue.generation_error = owned_generation_error;
    }

    const completion_key = try internal_keys.artifactRepairCompletionKeyAlloc(ctx.alloc, kind_name, issue_id);
    defer ctx.alloc.free(completion_key);
    if (reason == .enrichment_failed) {
        var marker_deletes = std.ArrayListUnmanaged([]const u8).empty;
        defer marker_deletes.deinit(ctx.alloc);
        var owned_marker_delete_keys = std.ArrayListUnmanaged([]const u8).empty;
        defer {
            for (owned_marker_delete_keys.items) |key| ctx.alloc.free(@constCast(key));
            owned_marker_delete_keys.deinit(ctx.alloc);
        }
        var terminal_marker = try EnrichmentTerminalFailureMarkerWrite.init(
            ctx.alloc,
            ctx.store,
            issue_key,
            previous_terminal_sequence,
            sequence,
            &marker_deletes,
            &owned_marker_delete_keys,
        );
        defer terminal_marker.deinit(ctx.alloc);
        var completion = (try loadArtifactRepairCompletionStateFromStore(ctx.alloc, ctx.store, completion_key)) orelse ArtifactRepairCompletionState{
            .pending_issues = @intFromBool(existing_was_pending),
        };
        if (existing_was_pending) completion.pending_issues = @max(completion.pending_issues, 1);
        completion.epoch +%= 1;
        if (completion.epoch == 0) completion.epoch = 1;
        completion.completed_sequence = 0;
        if (!existing_was_pending) completion.pending_issues +|= 1;
        var encoded_completion: [artifact_repair_completion_state_len]u8 = undefined;
        encodeArtifactRepairCompletionState(&encoded_completion, completion);
        try saveArtifactRepairIssueToStoreWithSummary(
            ctx.alloc,
            ctx.store,
            issue_key,
            issue,
            existing == null,
            &.{
                .{ .key = completion_key, .value = &encoded_completion },
                .{ .key = &internal_keys.enrichment_terminal_failure_generation_counter_key, .value = &terminal_marker.generation_counter_value },
                .{ .key = terminal_marker.generation_key, .value = &terminal_marker.generation_value },
                // The primary key is ordered by source sequence for exact
                // visibility checks. The reverse key owns its lifecycle and
                // points back to the primary key for bounded retirement.
                .{ .key = terminal_marker.marker.sequence_key, .value = terminal_marker.marker_value },
                .{ .key = terminal_marker.marker.issue_key, .value = terminal_marker.marker.sequence_key },
            },
            marker_deletes.items,
        );
    } else {
        // A non-enrichment diagnosis supersedes the shared success fence. It
        // must be invalidated in the same metadata transaction as the issue so
        // neither crashes nor concurrent repair can leave a stale marker.
        var marker_deletes = std.ArrayListUnmanaged([]const u8).empty;
        defer marker_deletes.deinit(ctx.alloc);
        var owned_marker_delete_keys = std.ArrayListUnmanaged([]const u8).empty;
        defer {
            for (owned_marker_delete_keys.items) |key| ctx.alloc.free(@constCast(key));
            owned_marker_delete_keys.deinit(ctx.alloc);
        }
        try appendEnrichmentTerminalFailureMarkerDeletesForIssue(
            ctx.alloc,
            ctx.store,
            issue_key,
            &marker_deletes,
            &owned_marker_delete_keys,
            true,
        );
        try marker_deletes.append(ctx.alloc, completion_key);
        try saveArtifactRepairIssueToStoreWithSummary(
            ctx.alloc,
            ctx.store,
            issue_key,
            issue,
            existing == null,
            &.{},
            marker_deletes.items,
        );
    }
    if (ctx.repair_issue_counter) |counter| _ = counter.fetchAdd(1, .monotonic);
}

fn mergeGenerationFailureAttempts(
    previous_reason: types.ArtifactRepairReason,
    previous_sequence: u64,
    previous_error: []const u8,
    previous_attempts: u64,
    reason: types.ArtifactRepairReason,
    sequence: u64,
    generation_error: []const u8,
    generation_attempts: u64,
) u64 {
    const same_window = previous_reason == .enrichment_failed and
        reason == .enrichment_failed and
        previous_sequence == sequence and
        std.mem.eql(u8, previous_error, generation_error);
    return if (same_window) @max(previous_attempts, generation_attempts) else generation_attempts;
}

test "artifact repair enrichment generation attempts are exact per failure window" {
    try std.testing.expectEqual(@as(u64, 6), mergeGenerationFailureAttempts(
        .enrichment_failed,
        41,
        "EmbedRateLimited",
        6,
        .enrichment_failed,
        41,
        "EmbedRateLimited",
        4,
    ));
    try std.testing.expectEqual(@as(u64, 1), mergeGenerationFailureAttempts(
        .enrichment_failed,
        41,
        "EmbedRateLimited",
        6,
        .enrichment_failed,
        42,
        "EmbedRateLimited",
        1,
    ));
    try std.testing.expectEqual(@as(u64, 2), mergeGenerationFailureAttempts(
        .enrichment_failed,
        42,
        "EmbedRateLimited",
        6,
        .enrichment_failed,
        42,
        "ProviderUnavailable",
        2,
    ));
}

fn recordArtifactRepairIssueContext(
    ctx: *const AsyncContext,
    artifact_kind: types.ArtifactRepairKind,
    index_name: []const u8,
    doc_key: []const u8,
    parent_doc_key: []const u8,
    unit_id: []const u8,
    source_artifact_name: []const u8,
    artifact_name: []const u8,
    artifact_key: []const u8,
    chunk_id: ?u32,
    sequence: u64,
    reason: types.ArtifactRepairReason,
) !void {
    return recordArtifactRepairIssueContextDetailed(ctx, artifact_kind, index_name, doc_key, parent_doc_key, unit_id, source_artifact_name, artifact_name, artifact_key, chunk_id, sequence, reason, 0, "");
}

fn recordArtifactRepairIssueForRefContext(
    ctx: *const AsyncContext,
    index_name: []const u8,
    artifact_ref: types.ArtifactRef,
    artifact_key: []const u8,
    sequence: u64,
    reason: types.ArtifactRepairReason,
) !void {
    const unit_id = artifact_ref.unit_id orelse if (artifact_ref.source) |source| source.unit_id orelse "" else "";
    const parent_doc_key = if (unit_id.len > 0) artifact_ref.document_id else "";
    const source_artifact_name = if (artifact_ref.source) |source| source.name else "";
    try recordArtifactRepairIssueContext(
        ctx,
        repairKindFromArtifactKind(artifact_ref.kind),
        index_name,
        artifact_ref.document_id,
        parent_doc_key,
        unit_id,
        source_artifact_name,
        artifact_ref.name,
        artifact_key,
        artifact_ref.chunk_id,
        sequence,
        reason,
    );
}

fn denseEmbeddingArtifactRepairReason(
    ctx: *const AsyncContext,
    dims: u32,
    artifact_key: []const u8,
) !?types.ArtifactRepairReason {
    const raw = ctx.store.get(ctx.alloc, artifact_key) catch |err| switch (err) {
        error.NotFound => return .missing_artifact,
        else => return err,
    };
    defer ctx.alloc.free(raw);

    const dims_usize: usize = @intCast(dims);
    if (enrichment_artifact_codec.denseEmbeddingVectorView(raw)) |maybe_view| {
        if (maybe_view) |view| {
            return if (view.len == dims_usize) null else .corrupt_artifact;
        }
    } else |err| {
        if (DB.isRecoverableEmbeddingArtifactError(err)) return .corrupt_artifact;
        return err;
    }

    const decoded = enrichment_artifact_codec.decodeDenseEmbeddingAlloc(ctx.alloc, raw) catch |err| {
        if (DB.isRecoverableEmbeddingArtifactError(err)) return .corrupt_artifact;
        return err;
    };
    defer ctx.alloc.free(decoded);
    return if (decoded.len == dims_usize) null else .corrupt_artifact;
}

fn sparseEmbeddingArtifactRepairReason(
    ctx: *const AsyncContext,
    artifact_key: []const u8,
) !?types.ArtifactRepairReason {
    const raw = ctx.store.get(ctx.alloc, artifact_key) catch |err| switch (err) {
        error.NotFound => return .missing_artifact,
        else => return err,
    };
    defer ctx.alloc.free(raw);

    if (enrichment_artifact_codec.sparseEmbeddingVectorView(raw)) |maybe_view| {
        if (maybe_view != null) return null;
    } else |err| {
        if (DB.isRecoverableEmbeddingArtifactError(err)) return .corrupt_artifact;
        return err;
    }

    var decoded = enrichment_artifact_codec.decodeSparseEmbeddingAlloc(ctx.alloc, raw) catch |err| {
        if (DB.isRecoverableEmbeddingArtifactError(err)) return .corrupt_artifact;
        return err;
    };
    decoded.deinit(ctx.alloc);
    return null;
}

fn replaySourceDocumentExists(
    ctx: *const AsyncContext,
    source_doc_key: []const u8,
) !bool {
    const store_key = try replayDocumentStoreKeyAlloc(ctx.alloc, source_doc_key);
    defer ctx.alloc.free(store_key);
    const raw = ctx.store.get(ctx.alloc, store_key) catch |err| switch (err) {
        error.NotFound => return false,
        else => return err,
    };
    ctx.alloc.free(raw);
    return true;
}

fn denseEmbeddingWriteSourceDocumentExists(
    ctx: *const AsyncContext,
    write: mapper.DenseEmbeddingWrite,
) !bool {
    return try replaySourceDocumentExists(ctx, write.parent_doc_key orelse write.doc_key);
}

fn filterAndRecordDenseEmbeddingArtifactRepairIssuesForReplay(
    ctx: *const AsyncContext,
    index_name: []const u8,
    dims: u32,
    owned: *OwnedDenseEmbeddingWrites,
    sequence: u64,
) !void {
    var removed_indices = std.ArrayListUnmanaged(usize).empty;
    defer removed_indices.deinit(ctx.alloc);
    for (owned.writes, 0..) |write, write_idx| {
        const artifact_key = write.artifact_key orelse continue;
        if (try denseEmbeddingArtifactRepairReason(ctx, dims, artifact_key)) |reason| {
            // A delete can commit after this journal record but before replay
            // reads its artifact. That is an ordinary supersession, not
            // corruption: advance past the stale upsert and let the following
            // delete record remove any indexed value. This also prevents TTL
            // cleanup from wedging replay on an artifact it correctly removed.
            if (reason == .missing_artifact and !try denseEmbeddingWriteSourceDocumentExists(ctx, write)) {
                try removed_indices.append(ctx.alloc, write_idx);
                continue;
            }
            try recordEmbeddingArtifactRepairIssueContext(ctx, index_name, artifact_key, sequence, reason);
        }
    }
    if (removed_indices.items.len == 0) return;

    const kept_len = owned.writes.len - removed_indices.items.len;
    const kept = try owned.alloc.alloc(mapper.DenseEmbeddingWrite, kept_len);
    var kept_idx: usize = 0;
    var removed_idx: usize = 0;
    for (owned.writes, 0..) |write, write_idx| {
        if (removed_idx < removed_indices.items.len and removed_indices.items[removed_idx] == write_idx) {
            removed_idx += 1;
            if (owned.owns_doc_keys) {
                owned.alloc.free(@constCast(write.doc_key));
                if (write.parent_doc_key) |parent_doc_key| owned.alloc.free(@constCast(parent_doc_key));
            }
            continue;
        }
        kept[kept_idx] = write;
        kept_idx += 1;
    }
    if (owned.allocation_len > 0) owned.alloc.free(owned.writes.ptr[0..owned.allocation_len]);
    owned.writes = kept;
    owned.allocation_len = kept.len;
}

fn filterAndRecordSparseEmbeddingArtifactRepairIssuesForReplay(
    ctx: *const AsyncContext,
    index_name: []const u8,
    owned: *OwnedSparseEmbeddingWrites,
    sequence: u64,
) !void {
    var removed_indices = std.ArrayListUnmanaged(usize).empty;
    defer removed_indices.deinit(ctx.alloc);
    for (owned.writes, 0..) |write, write_idx| {
        const artifact_key = write.artifact_key orelse continue;
        if (try sparseEmbeddingArtifactRepairReason(ctx, artifact_key)) |reason| {
            // Sparse artifact cleanup follows the same primary/journal
            // ordering as dense cleanup. If a later delete already removed
            // both the source and artifact, this stale upsert is superseded;
            // the later delete record remains responsible for index removal.
            if (reason == .missing_artifact and !try replaySourceDocumentExists(ctx, write.doc_key)) {
                try removed_indices.append(ctx.alloc, write_idx);
                continue;
            }
            try recordEmbeddingArtifactRepairIssueContext(ctx, index_name, artifact_key, sequence, reason);
        }
    }
    if (removed_indices.items.len == 0) return;

    const kept_len = owned.writes.len - removed_indices.items.len;
    const kept = try owned.alloc.alloc(mapper.SparseEmbeddingWrite, kept_len);
    var kept_idx: usize = 0;
    var removed_idx: usize = 0;
    for (owned.writes, 0..) |write, write_idx| {
        if (removed_idx < removed_indices.items.len and removed_indices.items[removed_idx] == write_idx) {
            removed_idx += 1;
            continue;
        }
        kept[kept_idx] = write;
        kept_idx += 1;
    }
    if (owned.allocation_len > 0) owned.alloc.free(owned.writes.ptr[0..owned.allocation_len]);
    owned.writes = kept;
    owned.allocation_len = kept.len;
}

fn applyDerivedBatchToIndexContextProfiled(ctx: *const AsyncContext, batch: derived_types.DerivedBatch, index_ref: index_manager_mod.ManagedIndexRef, profile: ?*BatchProfile) !void {
    if (index_ref.kind == .full_text) {
        const apply_start_ns = monotonicTimeNs();
        const text_replay_options: index_manager_mod.IndexBatchOptions = .{
            .compact_text = false,
            .compact_text_segment_threshold = null,
            .defer_text_compaction = true,
        };
        const delete_keys = try collectTextReplayDeleteKeys(ctx.alloc, batch);
        defer if (delete_keys.len > 0) ctx.alloc.free(delete_keys);
        var publication_context = try ctx.index_manager.acquireTextPublicationContext(ctx.alloc, index_ref.name);
        defer publication_context.deinit();
        var collected = try collectTextDocumentWritesForIndex(
            ctx.alloc,
            ctx.store,
            batch.documents,
            index_ref.name,
            publication_context.chunk_backed,
            ctx.index_manager.byte_range,
            .{ .prefer_inline_when_store_tip_matches_sequence = batch.sequence },
        );
        defer collected.deinit();
        if (collected.missing_required != 0) return error.ReplayDocumentNotVisible;

        const reservation_limit = if (ctx.text_merge_runtime) |runtime| runtime.producerSegmentReservationLimit() else std.math.maxInt(usize);
        var write_start: usize = 0;
        var applied_first_chunk = false;
        while (!applied_first_chunk or write_start < collected.writes.items.len) {
            const plan_base = write_start;
            var publication_plan = try ctx.index_manager.planTextBatchPublication(
                index_ref.name,
                publication_context,
                collected.writes.items[plan_base..],
                reservation_limit,
            );
            defer publication_plan.deinit();

            var relative_start: usize = 0;
            var replan_suffix = false;
            for (publication_plan.chunks) |planned| {
                const write_end = plan_base + planned.end;
                const write_chunk = collected.writes.items[plan_base + relative_start .. write_end];
                var applied_chunk = false;
                var merge_permit: ?text_merge_runtime_mod.TextMergeRuntime.ProducerPermit = null;
                if (ctx.text_merge_runtime) |runtime| {
                    merge_permit = try runtime.acquireProducerPermit(
                        index_ref.name,
                        planned.estimate.segment_count,
                        planned.estimate.byte_count,
                    );
                }
                defer if (merge_permit) |*permit| permit.release();

                var index_apply_guard = try ctx.index_manager.lockManagedIndexApply(index_ref);
                defer index_apply_guard.unlock();

                // Admission may wait without holding catalog/apply locks. A
                // same-instance schema or analyzer update invalidates only
                // the unpublished suffix, which is replanned below. An index
                // replacement still fails closed through IndexNotFound.
                const before_apply = try ctx.index_manager.refreshTextPublicationContextAssumeCatalogLocked(
                    index_ref.name,
                    &publication_context,
                );
                if (before_apply == .projection_changed) {
                    replan_suffix = true;
                } else {
                    try ctx.index_manager.applyTextBatchByNameWithOptions(
                        ctx.store,
                        index_ref.name,
                        if (applied_first_chunk) &.{} else delete_keys,
                        write_chunk,
                        text_replay_options,
                    );
                    applied_chunk = true;
                    const after_apply = try ctx.index_manager.refreshTextPublicationContextAssumeCatalogLocked(
                        index_ref.name,
                        &publication_context,
                    );
                    replan_suffix = after_apply == .projection_changed;
                    if (ctx.text_merge_runtime) |runtime| runtime.notify();
                }

                if (!applied_chunk) break;
                applied_first_chunk = true;
                write_start = write_end;
                relative_start = planned.end;
                if (replan_suffix and write_start < collected.writes.items.len) break;
            }

            if (write_start == collected.writes.items.len) break;
            std.debug.assert(replan_suffix);
        }
        std.debug.assert(applied_first_chunk and write_start == collected.writes.items.len);
        if (profile) |active_profile| recordProfileNs(profile, &active_profile.full_text_apply_ns, apply_start_ns);
        return;
    }

    var index_apply_guard = try ctx.index_manager.lockManagedIndexApply(index_ref);
    defer index_apply_guard.unlock();
    switch (index_ref.kind) {
        .full_text => unreachable,
        .dense_vector => {
            const dense_apply_start_ns = monotonicTimeNs();
            const dense_finish_options = denseCatchUpFinishOptions();
            const use_local_streaming_session = denseApplyUsesLocalStreamingSession(ctx, index_ref.name);
            var dense_streaming_session_open = false;
            if (use_local_streaming_session) {
                try ctx.index_manager.beginDenseStreamingReplaySessionByName(index_ref.name);
                dense_streaming_session_open = true;
                errdefer if (dense_streaming_session_open) ctx.index_manager.abortDenseStreamingReplaySessionByName(index_ref.name);
            }
            const before_hbc_profile = if (profile != null) ctx.index_manager.denseWriteProfileByName(index_ref.name) else null;
            const batch_options: backend_types.BatchOptions = .{ .mode = .bulk_ingest };
            var dense_embeddings = try collectDenseEmbeddingWritesForBatch(
                ctx.alloc,
                ctx.index_manager,
                batch.dense_embeddings,
                batch.changed_artifact_keys,
                index_ref.name,
            );
            defer dense_embeddings.deinit();
            if (ctx.index_manager.denseIndex(index_ref.name)) |entry| {
                try filterAndRecordDenseEmbeddingArtifactRepairIssuesForReplay(ctx, index_ref.name, entry.dims, &dense_embeddings, batch.sequence);
            }
            try ctx.index_manager.validateDenseEmbeddingArtifactsByName(ctx.store, index_ref.name, dense_embeddings.writes);

            const dense_delete_start_ns = monotonicTimeNs();
            try ctx.index_manager.deleteDenseBatchByNameWithOptions(ctx.store, index_ref.name, batch.deleted_keys, batch_options);
            const chunk_backed = if (ctx.index_manager.denseIndex(index_ref.name)) |entry|
                entry.chunk_name != null
            else
                false;
            // Chunk-backed vectors have deterministic artifact identities and
            // a complete stale-chunk delete lifecycle. Erasing every vector
            // for an overwritten parent races asynchronous enrichment replay,
            // causes needless HBC churn, and can leave a ready chunked index
            // with only a partial physical corpus. Non-chunked generated and
            // inline vectors still require parent-wide replacement to retire
            // provisional or previous identities.
            if (!chunk_backed) {
                try ctx.index_manager.deleteDenseBatchByNameWithOptions(ctx.store, index_ref.name, batch.overwritten_doc_keys, batch_options);
            }
            try deleteDerivedCoverageForDocKeys(ctx.alloc, ctx.store, ctx.index_manager, index_ref.name, batch.deleted_keys);
            try deleteDerivedCoverageForDocKeys(ctx.alloc, ctx.store, ctx.index_manager, index_ref.name, batch.overwritten_doc_keys);
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.dense_delete_ns, dense_delete_start_ns);

            var dense_embedding_doc_keys = try denseEmbeddingDocKeySet(ctx.alloc, dense_embeddings.writes);
            defer dense_embedding_doc_keys.deinit(ctx.alloc);

            var index_writes = try collectDocumentWritesProfiled(
                ctx.alloc,
                ctx.store,
                batch.documents,
                ctx.index_manager.byte_range,
                .{ .skip_doc_keys = &dense_embedding_doc_keys },
                null,
            );
            defer index_writes.deinit();
            if (index_writes.missing_required != 0) return error.ReplayDocumentNotVisible;
            const dense_doc_index_start_ns = monotonicTimeNs();
            try ctx.index_manager.indexDenseBatchByNameWithOptions(ctx.store, index_ref.name, index_writes.items, batch_options);
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.dense_doc_index_ns, dense_doc_index_start_ns);

            const dense_embedding_start_ns = monotonicTimeNs();
            try ctx.index_manager.applyDenseEmbeddingWritesByNameWithOptions(ctx.store, index_ref.name, dense_embeddings.writes, batch_options);
            try accountDenseCoverage(ctx, index_ref.name, batch, dense_embeddings.writes);
            if (profile) |active_profile| {
                recordProfileNs(profile, &active_profile.dense_embedding_apply_ns, dense_embedding_start_ns);
                if (before_hbc_profile) |before| {
                    if (ctx.index_manager.denseWriteProfileByName(index_ref.name)) |after| {
                        addHbcWriteProfileDelta(active_profile, before, after);
                    }
                }
            }
            if (use_local_streaming_session) {
                try ctx.index_manager.finishDenseStreamingReplaySessionByNameWithOptions(index_ref.name, dense_finish_options);
                dense_streaming_session_open = false;
            }
            try clearPublishedEmbeddingArtifactRepairIssuesContext(ctx, index_ref.name, dense_embeddings.writes, batch.sequence);
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.dense_apply_ns, dense_apply_start_ns);
        },
        .sparse_vector => {
            const apply_start_ns = monotonicTimeNs();
            const emit_sparse_write_profile = benchMetricsEnabled();
            const before_sparse_profile = if (emit_sparse_write_profile) ctx.index_manager.sparseWriteProfileByName(index_ref.name) else null;
            const batch_options: backend_types.BatchOptions = .{ .mode = .bulk_ingest };
            var collect_doc_profile: CollectSparseFieldWritesProfile = .{};
            var sparse_delete_ns: u64 = 0;
            var sparse_collect_doc_ns: u64 = 0;
            var sparse_doc_index_ns: u64 = 0;
            var sparse_collect_embedding_ns: u64 = 0;
            var sparse_embedding_apply_ns: u64 = 0;
            const sparse_collect_embedding_start_ns = if (emit_sparse_write_profile) monotonicTimeNs() else 0;
            var sparse_embeddings = try collectSparseEmbeddingWritesForBatch(
                ctx.alloc,
                ctx.index_manager,
                batch.sparse_embeddings,
                batch.changed_artifact_keys,
                index_ref.name,
            );
            defer sparse_embeddings.deinit();
            if (emit_sparse_write_profile) sparse_collect_embedding_ns = monotonicTimeNs() - sparse_collect_embedding_start_ns;
            try filterAndRecordSparseEmbeddingArtifactRepairIssuesForReplay(ctx, index_ref.name, &sparse_embeddings, batch.sequence);
            try ctx.index_manager.validateSparseEmbeddingArtifactsByName(ctx.store, index_ref.name, sparse_embeddings.writes);

            const sparse_delete_start_ns = if (emit_sparse_write_profile) monotonicTimeNs() else 0;
            try ctx.index_manager.deleteSparseBatchByNameWithOptions(index_ref.name, batch.deleted_keys, batch_options);
            try ctx.index_manager.deleteSparseBatchByNameWithOptions(index_ref.name, batch.overwritten_doc_keys, batch_options);
            try deleteDerivedCoverageForDocKeys(ctx.alloc, ctx.store, ctx.index_manager, index_ref.name, batch.deleted_keys);
            try deleteDerivedCoverageForDocKeys(ctx.alloc, ctx.store, ctx.index_manager, index_ref.name, batch.overwritten_doc_keys);
            if (emit_sparse_write_profile) sparse_delete_ns = monotonicTimeNs() - sparse_delete_start_ns;

            var sparse_embedding_doc_keys = try sparseEmbeddingDocKeySet(ctx.alloc, sparse_embeddings.writes);
            defer sparse_embedding_doc_keys.deinit(ctx.alloc);

            const sparse_collect_doc_start_ns = if (emit_sparse_write_profile) monotonicTimeNs() else 0;
            const sparse_field_name = ctx.index_manager.sparseFieldNameByName(index_ref.name) orelse return error.IndexNotFound;
            var index_writes = try collectSparseFieldWritesProfiled(
                ctx.alloc,
                ctx.store,
                batch.documents,
                ctx.index_manager.byte_range,
                sparse_field_name,
                .{
                    .prefer_inline_when_store_tip_matches_sequence = batch.sequence,
                    .prefer_available_inline_values = true,
                    .skip_doc_keys = &sparse_embedding_doc_keys,
                },
                if (emit_sparse_write_profile) &collect_doc_profile else null,
            );
            defer index_writes.deinit();
            if (emit_sparse_write_profile) sparse_collect_doc_ns = monotonicTimeNs() - sparse_collect_doc_start_ns;
            if (index_writes.missing_required != 0) return error.ReplayDocumentNotVisible;
            const sparse_doc_index_start_ns = if (emit_sparse_write_profile) monotonicTimeNs() else 0;
            try ctx.index_manager.indexSparsePreparedWritesByNameWithOptions(index_ref.name, index_writes.items, batch_options);
            if (emit_sparse_write_profile) sparse_doc_index_ns = monotonicTimeNs() - sparse_doc_index_start_ns;

            const sparse_embedding_apply_start_ns = if (emit_sparse_write_profile) monotonicTimeNs() else 0;
            try ctx.index_manager.applySparseEmbeddingWritesByNameWithOptions(ctx.store, index_ref.name, sparse_embeddings.writes, batch_options);
            try accountSparseCoverage(ctx, index_ref.name, batch, sparse_embeddings.writes);
            try clearPublishedEmbeddingArtifactRepairIssuesContext(ctx, index_ref.name, sparse_embeddings.writes, batch.sequence);
            if (emit_sparse_write_profile) sparse_embedding_apply_ns = monotonicTimeNs() - sparse_embedding_apply_start_ns;
            if (before_sparse_profile) |before| {
                if (ctx.index_manager.sparseWriteProfileByName(index_ref.name)) |after| {
                    logSparseWriteProfileDelta(index_ref.name, sparse_mod.WriteProfile.delta(after, before));
                }
            }
            if (emit_sparse_write_profile) {
                std.log.info(
                    "antfly_bench_sparse_doc_replay index={s} sequence={} documents={d} sparse_embeddings={d} total_ms={d} delete_ms={d} collect_doc_ms={d} collect_doc_scan_ms={d} collect_doc_sort_ms={d} collect_doc_read_ms={d} collect_doc_extract_ms={d} collect_doc_pending={d} collect_doc_output={d} collect_doc_store_hits={d} collect_doc_inline_hits={d} collect_doc_missing={d} collect_doc_no_vector={d} doc_index_ms={d} collect_embedding_ms={d} embedding_apply_ms={d}",
                    .{
                        index_ref.name,
                        batch.sequence,
                        batch.documents.len,
                        batch.sparse_embeddings.len,
                        nsToMs(monotonicTimeNs() - apply_start_ns),
                        nsToMs(sparse_delete_ns),
                        nsToMs(sparse_collect_doc_ns),
                        nsToMs(collect_doc_profile.scan_ns),
                        nsToMs(collect_doc_profile.sort_ns),
                        nsToMs(collect_doc_profile.read_ns),
                        nsToMs(collect_doc_profile.extract_ns),
                        collect_doc_profile.pending_documents,
                        collect_doc_profile.output_writes,
                        collect_doc_profile.store_hits,
                        collect_doc_profile.inline_hits,
                        collect_doc_profile.missing_required,
                        collect_doc_profile.skipped_without_vector,
                        nsToMs(sparse_doc_index_ns),
                        nsToMs(sparse_collect_embedding_ns),
                        nsToMs(sparse_embedding_apply_ns),
                    },
                );
            }
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.sparse_apply_ns, apply_start_ns);
        },
        .graph => {
            const apply_start_ns = monotonicTimeNs();
            try ctx.index_manager.deleteGraphDocsByName(index_ref.name, batch.deleted_keys);
            try applyGraphDocClearsForIndex(ctx, batch.graph_doc_clears, index_ref.name);

            const materialized_artifact_keys = if (ctx.allow_graph_materialization)
                try materializeGraphSourceArtifactsForIndex(
                    ctx.alloc,
                    ctx.store,
                    ctx.index_manager,
                    batch.changed_artifact_keys,
                    index_ref.name,
                    .{
                        .require_resolution_contract = ctx.require_graph_resolution_contract,
                        .repair_ctx = ctx,
                        .sequence = batch.sequence,
                    },
                )
            else
                try ctx.alloc.alloc([]u8, 0);
            defer freeOwnedKeySlice(ctx.alloc, materialized_artifact_keys);

            if (batch.graph_writes.len > 0 or batch.graph_deletes.len > 0) {
                const graph_deletes = try collectGraphDeletes(ctx.alloc, batch.graph_deletes, index_ref.name);
                defer if (graph_deletes.len > 0) ctx.alloc.free(graph_deletes);

                const graph_writes = try collectGraphWrites(ctx.alloc, batch.graph_writes, index_ref.name);
                defer if (graph_writes.len > 0) ctx.alloc.free(graph_writes);
                try ctx.index_manager.applyGraphMutationsByName(index_ref.name, graph_writes, graph_deletes);
            }
            if (batch.changed_artifact_keys.len > 0 or materialized_artifact_keys.len > 0) {
                const graph_artifact_keys = try concatArtifactKeyViews(ctx.alloc, batch.changed_artifact_keys, materialized_artifact_keys);
                defer ctx.alloc.free(graph_artifact_keys);
                var graph_mutations = try collectGraphMutationsForArtifacts(ctx.alloc, ctx.store, graph_artifact_keys, index_ref.name, .{
                    .expected_generation = (ctx.index_manager.graphIndex(index_ref.name) orelse return error.IndexNotFound).config.coverage_generation,
                    .repair_ctx = ctx,
                    .sequence = batch.sequence,
                });
                defer graph_mutations.deinit();
                if (graph_mutations.generation_bindings.len > 0) {
                    try ctx.store.putBatch(graph_mutations.generation_bindings, &.{});
                }
                try ctx.index_manager.applyGraphMutationsByName(index_ref.name, graph_mutations.writes, graph_mutations.deletes);
            }
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.graph_apply_ns, apply_start_ns);
        },
        .algebraic => {
            try ctx.index_manager.applyAlgebraicBatchByNameWithOptions(ctx.store, index_ref.name, batch, .{ .mode = .bulk_ingest });
        },
    }
}

fn batchHasEmbeddingArtifactForManagedIndex(
    index_manager: *index_manager_mod.IndexManager,
    index_ref: index_manager_mod.ManagedIndexRef,
    artifact_keys: []const []const u8,
) bool {
    const alloc = index_manager.alloc;
    for (artifact_keys) |artifact_key| {
        var identity = artifact_ids.decodeEmbeddingArtifactIdentityAlloc(alloc, artifact_key) catch |err| switch (err) {
            error.InvalidInternalUserKey => continue,
            else => continue,
        } orelse continue;
        defer identity.deinit(alloc);
        if (managedIndexConsumesEmbeddingName(index_manager, index_ref, identity.embedding_name)) return true;
    }

    return false;
}

fn managedIndexConsumesEmbeddingName(
    index_manager: *index_manager_mod.IndexManager,
    index_ref: index_manager_mod.ManagedIndexRef,
    embedding_name: []const u8,
) bool {
    return switch (index_ref.kind) {
        .dense_vector => index_manager.denseIndexConsumesEmbedding(index_ref.name, embedding_name),
        .sparse_vector => index_manager.sparseIndexConsumesEmbedding(index_ref.name, embedding_name),
        else => false,
    };
}

const ManagedIndexBatchApplicability = enum {
    irrelevant,
    relevant,
    missing_dependency,
};

fn managedIndexBatchApplicability(
    index_manager: *index_manager_mod.IndexManager,
    batch: derived_types.DerivedBatch,
    index_ref: index_manager_mod.ManagedIndexRef,
) ManagedIndexBatchApplicability {
    switch (index_ref.kind) {
        .full_text, .algebraic => {
            if (batch.deleted_keys.len > 0 or batch.overwritten_doc_keys.len > 0) return .relevant;
            for (batch.documents) |doc| {
                if (doc.action == .upsert) return .relevant;
            }
            return .irrelevant;
        },
        .dense_vector => {
            if (batch.deleted_keys.len > 0 or batch.overwritten_doc_keys.len > 0) return .relevant;
            for (batch.documents) |doc| {
                if (doc.action == .upsert) return .relevant;
            }
            for (batch.dense_embeddings) |embedding| {
                if (std.mem.eql(u8, embedding.index_name, index_ref.name)) return .relevant;
            }
            if (batchHasEmbeddingArtifactForManagedIndex(index_manager, index_ref, batch.changed_artifact_keys)) return .relevant;
            return .irrelevant;
        },
        .sparse_vector => {
            if (batch.deleted_keys.len > 0 or batch.overwritten_doc_keys.len > 0) return .relevant;
            for (batch.documents) |doc| {
                if (doc.action == .upsert) return .relevant;
            }
            for (batch.sparse_embeddings) |embedding| {
                if (std.mem.eql(u8, embedding.index_name, index_ref.name)) return .relevant;
            }
            if (batchHasEmbeddingArtifactForManagedIndex(index_manager, index_ref, batch.changed_artifact_keys)) return .relevant;
            return .irrelevant;
        },
        .graph => {
            if (batch.deleted_keys.len > 0) return .relevant;
            for (batch.graph_doc_clears) |clear| {
                for (clear.index_names) |index_name| {
                    if (std.mem.eql(u8, index_name, index_ref.name)) return .relevant;
                }
            }
            for (batch.graph_writes) |write| {
                if (std.mem.eql(u8, write.index_name, index_ref.name)) return .relevant;
            }
            for (batch.graph_deletes) |delete| {
                if (std.mem.eql(u8, delete.index_name, index_ref.name)) return .relevant;
            }
            for (batch.changed_artifact_keys) |artifact_key| {
                if (!internal_keys.isResolutionArtifactKey(artifact_key) and !internal_keys.isGraphEdgeArtifactKey(artifact_key)) {
                    for (index_manager.graphArtifactSources(index_ref.name)) |source| {
                        if (graphArtifactSourceConsumesArtifactKey(index_manager, source, artifact_key)) return .relevant;
                    }
                    continue;
                }
                if (internal_keys.isResolutionArtifactKey(artifact_key)) {
                    const parsed = (internal_keys.parseResolutionArtifactKeyAlloc(index_manager.alloc, artifact_key) catch continue) orelse continue;
                    defer {
                        index_manager.alloc.free(parsed.doc_key);
                        index_manager.alloc.free(parsed.artifact_name);
                    }
                    for (index_manager.graphArtifactSources(index_ref.name)) |source| {
                        if (source.mention_edge_type.len == 0) continue;
                        if (resolverConfigForResolution(index_manager, source.artifact_name, parsed.artifact_name) != null) return .relevant;
                    }
                    if (resolverConfigForResolutionArtifact(index_manager, parsed.artifact_name) != null) continue;
                    return .missing_dependency;
                }
                if (internal_keys.isGraphEdgeArtifactKey(artifact_key)) {
                    const parsed = (internal_keys.parseGraphEdgeArtifactKeyAlloc(index_manager.alloc, artifact_key) catch continue) orelse continue;
                    defer {
                        index_manager.alloc.free(parsed.doc_key);
                        index_manager.alloc.free(parsed.index_name);
                        index_manager.alloc.free(parsed.edge_type);
                        index_manager.alloc.free(parsed.target_doc_key);
                    }
                    if (std.mem.eql(u8, parsed.index_name, index_ref.name)) return .relevant;
                }
            }
            return .irrelevant;
        },
    }
}

fn batchAffectsManagedIndex(
    index_manager: *index_manager_mod.IndexManager,
    batch: derived_types.DerivedBatch,
    index_ref: index_manager_mod.ManagedIndexRef,
) bool {
    return managedIndexBatchApplicability(index_manager, batch, index_ref) == .relevant;
}

fn batchAffectsManagedIndexForReplay(
    index_manager: *index_manager_mod.IndexManager,
    batch: derived_types.DerivedBatch,
    index_ref: index_manager_mod.ManagedIndexRef,
) !bool {
    return switch (managedIndexBatchApplicability(index_manager, batch, index_ref)) {
        .irrelevant => false,
        .relevant => true,
        .missing_dependency => true,
    };
}

fn batchAdvancesManagedIndexApplyState(
    index_manager: *index_manager_mod.IndexManager,
    batch: derived_types.DerivedBatch,
    index_ref: index_manager_mod.ManagedIndexRef,
) !bool {
    if (!batchAffectsManagedIndex(index_manager, batch, index_ref)) return false;

    switch (index_ref.kind) {
        .dense_vector, .sparse_vector => {
            if (batch.deleted_keys.len > 0 or batch.overwritten_doc_keys.len > 0) return true;
            const artifact_backed_dense = if (index_ref.kind == .dense_vector)
                if (index_manager.denseIndex(index_ref.name)) |entry| denseIndexIsArtifactBacked(entry) else false
            else
                false;
            if (!try index_manager.requiresEnrichmentReplay(index_ref.name) and !artifact_backed_dense) return true;
            if (batch.changed_artifact_keys.len > 0) return true;
            if (index_ref.kind == .dense_vector) {
                for (batch.dense_embeddings) |embedding| {
                    if (std.mem.eql(u8, embedding.index_name, index_ref.name)) return true;
                }
                return false;
            }
            for (batch.sparse_embeddings) |embedding| {
                if (std.mem.eql(u8, embedding.index_name, index_ref.name)) return true;
            }
            return false;
        },
        else => return true,
    }
}

fn batchAdvancesManagedIndexApplyStateForReplay(
    index_manager: *index_manager_mod.IndexManager,
    batch: derived_types.DerivedBatch,
    index_ref: index_manager_mod.ManagedIndexRef,
) !bool {
    return switch (managedIndexBatchApplicability(index_manager, batch, index_ref)) {
        .irrelevant => false,
        .missing_dependency => true,
        .relevant => try batchAdvancesManagedIndexApplyState(index_manager, batch, index_ref),
    };
}

fn managedIndexRecordApplicability(
    index_manager: *index_manager_mod.IndexManager,
    record: change_journal_mod.Record,
    index_ref: index_manager_mod.ManagedIndexRef,
) ManagedIndexBatchApplicability {
    switch (index_ref.kind) {
        .full_text, .algebraic => {
            if (record.changed_doc_keys.len > 0 or
                record.deleted_doc_keys.len > 0 or
                record.overwritten_doc_keys.len > 0) return .relevant;
            return .irrelevant;
        },
        .dense_vector => {
            if (record.deleted_doc_keys.len > 0 or record.overwritten_doc_keys.len > 0) return .relevant;
            // Artifact-backed indexes consume generated artifact records, not
            // the source document record that scheduled enrichment. Treating
            // that source record as perpetually applicable prevents a clean
            // target advance after an idempotent index recreate reuses already
            // durable artifacts. The artifact target counter and active index
            // cardinality below remain the completeness gate.
            if (record.changed_doc_keys.len > 0) {
                const entry = index_manager.denseIndex(index_ref.name);
                if (entry == null or !denseIndexIsArtifactBacked(entry.?)) return .relevant;
            }
            if (batchHasEmbeddingArtifactForManagedIndex(index_manager, index_ref, record.changed_artifact_keys)) return .relevant;
            return .irrelevant;
        },
        .sparse_vector => {
            if (record.changed_doc_keys.len > 0 or
                record.deleted_doc_keys.len > 0 or
                record.overwritten_doc_keys.len > 0) return .relevant;
            if (batchHasEmbeddingArtifactForManagedIndex(index_manager, index_ref, record.changed_artifact_keys)) return .relevant;
            return .irrelevant;
        },
        .graph => {
            if (record.deleted_doc_keys.len > 0) return .relevant;
            for (record.changed_artifact_keys) |artifact_key| {
                if (!internal_keys.isResolutionArtifactKey(artifact_key) and !internal_keys.isGraphEdgeArtifactKey(artifact_key)) {
                    for (index_manager.graphArtifactSources(index_ref.name)) |source| {
                        if (graphArtifactSourceConsumesArtifactKey(index_manager, source, artifact_key)) return .relevant;
                    }
                    continue;
                }
                if (internal_keys.isResolutionArtifactKey(artifact_key)) {
                    const parsed = (internal_keys.parseResolutionArtifactKeyAlloc(index_manager.alloc, artifact_key) catch continue) orelse continue;
                    defer {
                        index_manager.alloc.free(parsed.doc_key);
                        index_manager.alloc.free(parsed.artifact_name);
                    }
                    for (index_manager.graphArtifactSources(index_ref.name)) |source| {
                        if (source.mention_edge_type.len == 0) continue;
                        if (resolverConfigForResolution(index_manager, source.artifact_name, parsed.artifact_name) != null) return .relevant;
                    }
                    if (resolverConfigForResolutionArtifact(index_manager, parsed.artifact_name) != null) continue;
                    return .missing_dependency;
                }
                if (internal_keys.isGraphEdgeArtifactKey(artifact_key)) {
                    const parsed = (internal_keys.parseGraphEdgeArtifactKeyAlloc(index_manager.alloc, artifact_key) catch continue) orelse continue;
                    defer {
                        index_manager.alloc.free(parsed.doc_key);
                        index_manager.alloc.free(parsed.index_name);
                        index_manager.alloc.free(parsed.edge_type);
                        index_manager.alloc.free(parsed.target_doc_key);
                    }
                    if (std.mem.eql(u8, parsed.index_name, index_ref.name)) return .relevant;
                }
            }
            return .irrelevant;
        },
    }
}

const OwnedBatchWrites = struct {
    alloc: Allocator,
    items: []types.BatchWrite = &.{},
    missing_required: usize = 0,

    fn deinit(self: *@This()) void {
        for (self.items) |item| self.alloc.free(@constCast(item.value));
        if (self.items.len > 0) self.alloc.free(self.items);
        self.* = undefined;
    }
};

const CollectDocumentWritesProfile = struct {
    scan_ns: u64 = 0,
    sort_ns: u64 = 0,
    read_ns: u64 = 0,
    materialize_ns: u64 = 0,
    input_documents: usize = 0,
    pending_documents: usize = 0,
    output_writes: usize = 0,
    missing_required: usize = 0,
    inline_hits: usize = 0,
    store_hits: usize = 0,
};

const CollectSparseFieldWritesProfile = struct {
    scan_ns: u64 = 0,
    sort_ns: u64 = 0,
    read_ns: u64 = 0,
    extract_ns: u64 = 0,
    input_documents: usize = 0,
    pending_documents: usize = 0,
    output_writes: usize = 0,
    missing_required: usize = 0,
    inline_hits: usize = 0,
    store_hits: usize = 0,
    skipped_without_vector: usize = 0,
};

const OwnedDenseEmbeddingWrites = struct {
    alloc: Allocator,
    owns_doc_keys: bool = false,
    writes: []mapper.DenseEmbeddingWrite = &.{},
    allocation_len: usize = 0,

    fn deinit(self: *@This()) void {
        if (self.owns_doc_keys) {
            for (self.writes) |write| {
                self.alloc.free(@constCast(write.doc_key));
                if (write.parent_doc_key) |parent_doc_key| self.alloc.free(@constCast(parent_doc_key));
            }
        }
        if (self.allocation_len > 0) self.alloc.free(self.writes.ptr[0..self.allocation_len]);
        self.* = undefined;
    }
};

const OwnedEmbeddingArtifactWriteIdentity = struct {
    doc_key: []u8,
    parent_doc_key: ?[]u8 = null,

    fn deinit(self: *@This(), alloc: Allocator) void {
        alloc.free(self.doc_key);
        if (self.parent_doc_key) |parent_doc_key| alloc.free(parent_doc_key);
        self.* = undefined;
    }
};

fn decodeEmbeddingArtifactWriteIdentityAlloc(
    alloc: Allocator,
    artifact_key: []const u8,
    expected_embedding_name: []const u8,
) !?OwnedEmbeddingArtifactWriteIdentity {
    if (artifact_ids.decodeEmbeddingArtifactIdentityAlloc(alloc, artifact_key)) |maybe_identity| {
        var identity = maybe_identity orelse return null;
        defer identity.deinit(alloc);
        if (!std.mem.eql(u8, identity.embedding_name, expected_embedding_name)) return null;

        const doc_key = try alloc.dupe(u8, identity.doc_key);
        errdefer alloc.free(doc_key);
        const parent_doc_key = if (identity.parent_doc_key) |parent_key| try alloc.dupe(u8, parent_key) else null;
        errdefer if (parent_doc_key) |owned_parent| alloc.free(owned_parent);
        return .{
            .doc_key = doc_key,
            .parent_doc_key = parent_doc_key,
        };
    } else |err| switch (err) {
        error.InvalidInternalUserKey => {},
        else => return err,
    }

    if (try internal_keys.parseEmbeddingArtifactKeyView(artifact_key)) |identity| {
        if (!std.mem.eql(u8, identity.artifact_name, expected_embedding_name)) return null;
        return .{
            .doc_key = try alloc.dupe(u8, identity.doc_key),
        };
    }

    return null;
}

fn decodeEmbeddingArtifactWriteIdentityForManagedIndexAlloc(
    alloc: Allocator,
    index_manager: *index_manager_mod.IndexManager,
    index_ref: index_manager_mod.ManagedIndexRef,
    artifact_key: []const u8,
) !?OwnedEmbeddingArtifactWriteIdentity {
    if (artifact_ids.decodeEmbeddingArtifactIdentityAlloc(alloc, artifact_key)) |maybe_identity| {
        var identity = maybe_identity orelse return null;
        defer identity.deinit(alloc);
        if (!managedIndexConsumesEmbeddingName(index_manager, index_ref, identity.embedding_name)) return null;

        const doc_key = try alloc.dupe(u8, identity.doc_key);
        errdefer alloc.free(doc_key);
        const parent_doc_key = if (identity.parent_doc_key) |parent_key| try alloc.dupe(u8, parent_key) else null;
        errdefer if (parent_doc_key) |owned_parent| alloc.free(owned_parent);
        return .{ .doc_key = doc_key, .parent_doc_key = parent_doc_key };
    } else |err| switch (err) {
        error.InvalidInternalUserKey => {},
        else => return err,
    }

    if (try internal_keys.parseEmbeddingArtifactKeyView(artifact_key)) |identity| {
        if (!managedIndexConsumesEmbeddingName(index_manager, index_ref, identity.artifact_name)) return null;
        return .{ .doc_key = try alloc.dupe(u8, identity.doc_key) };
    }
    return null;
}

const OwnedSparseEmbeddingWrites = struct {
    alloc: Allocator,
    owned_doc_keys: []const []const u8 = &.{},
    writes: []mapper.SparseEmbeddingWrite = &.{},
    allocation_len: usize = 0,

    fn deinit(self: *@This()) void {
        for (self.owned_doc_keys) |doc_key| self.alloc.free(@constCast(doc_key));
        if (self.owned_doc_keys.len > 0) self.alloc.free(self.owned_doc_keys);
        if (self.allocation_len > 0) self.alloc.free(self.writes.ptr[0..self.allocation_len]);
        self.* = undefined;
    }
};

const CollectTextDocumentWritesOptions = struct {
    prefer_inline_when_store_tip_matches_sequence: ?u64 = null,
};

const CollectDocumentWritesOptions = struct {
    prefer_inline_when_store_tip_matches_sequence: ?u64 = null,
    prefer_available_inline_values: bool = false,
    skip_doc_keys: ?*const std.StringHashMapUnmanaged(void) = null,
};

fn replayDocumentStoreKeyAlloc(alloc: Allocator, key: []const u8) ![]u8 {
    return if (internal_keys.isInternalUserKey(key))
        try alloc.dupe(u8, key)
    else
        try internal_keys.documentKeyAlloc(alloc, key);
}

fn replayDocumentKeyInRange(byte_range: types.ByteRange, key: []const u8) bool {
    return internal_keys.isInternalUserKey(key) or byte_range.contains(key);
}

fn replayDocumentIsDurablyDeleted(alloc: Allocator, txn: anytype, doc_key: []const u8) !bool {
    const ordinal = (try doc_identity.lookupOrdinalTxn(alloc, txn, doc_key)) orelse return false;
    const state = (try doc_identity.lookupStateTxn(txn, ordinal)) orelse return false;
    return !state.isLive();
}

const OwnedSparseFieldWrites = struct {
    alloc: Allocator,
    items: []sparse_mod.SparseWrite = &.{},
    missing_required: usize = 0,

    fn deinit(self: *@This()) void {
        for (self.items) |item| {
            self.alloc.free(@constCast(item.vec.indices));
            self.alloc.free(@constCast(item.vec.values));
        }
        if (self.items.len > 0) self.alloc.free(self.items);
        self.* = undefined;
    }
};

fn collectSparseFieldWritesProfiled(
    alloc: Allocator,
    store: *docstore_mod.DocStore,
    documents: []const derived_types.DerivedDocument,
    byte_range: types.ByteRange,
    field_name: []const u8,
    opts: CollectDocumentWritesOptions,
    profile: ?*CollectSparseFieldWritesProfile,
) !OwnedSparseFieldWrites {
    const PendingDocumentWrite = struct {
        doc_key: []const u8,
        store_key: []u8,
        inline_value: ?[]const u8,
    };

    var pending = std.ArrayListUnmanaged(PendingDocumentWrite).empty;
    defer {
        for (pending.items) |item| alloc.free(item.store_key);
        pending.deinit(alloc);
    }

    var writes = std.ArrayListUnmanaged(sparse_mod.SparseWrite).empty;
    errdefer {
        for (writes.items) |item| {
            alloc.free(@constCast(item.vec.indices));
            alloc.free(@constCast(item.vec.values));
        }
        writes.deinit(alloc);
    }

    var txn = try store.beginProbeTxn();
    defer txn.abort();
    var missing_required: usize = 0;
    const trust_inline = opts.prefer_available_inline_values or
        if (opts.prefer_inline_when_store_tip_matches_sequence) |sequence|
            store.nextReplaySequence(sequence + 1) == sequence + 1
        else
            false;

    if (profile) |p| p.input_documents = documents.len;
    const scan_start_ns = if (profile != null) monotonicTimeNs() else 0;
    for (documents) |doc| {
        if (doc.action != .upsert) continue;
        if (!replayDocumentKeyInRange(byte_range, doc.key)) continue;
        if (opts.skip_doc_keys) |skip_doc_keys| {
            if (skip_doc_keys.contains(doc.key)) continue;
        }
        if (trust_inline and doc.cleaned_value != null) {
            const extract_start_ns = if (profile != null) monotonicTimeNs() else 0;
            if (try mapper.extractSparseVectorField(alloc, doc.cleaned_value.?, field_name)) |raw_sparse_vec| {
                var sparse_vec = raw_sparse_vec;
                writes.append(alloc, .{
                    .doc_id = doc.key,
                    .vec = .{
                        .indices = sparse_vec.indices,
                        .values = sparse_vec.values,
                    },
                }) catch |err| {
                    sparse_vec.deinit(alloc);
                    return err;
                };
                if (profile) |p| p.output_writes += 1;
            } else if (profile) |p| {
                p.skipped_without_vector += 1;
            }
            if (profile) |p| {
                p.extract_ns += monotonicTimeNs() - extract_start_ns;
                p.inline_hits += 1;
            }
            continue;
        }
        try pending.append(alloc, .{
            .doc_key = doc.key,
            .store_key = try replayDocumentStoreKeyAlloc(alloc, doc.key),
            .inline_value = doc.cleaned_value,
        });
    }
    if (profile) |p| {
        p.scan_ns = monotonicTimeNs() - scan_start_ns -| p.extract_ns;
        p.pending_documents = pending.items.len;
    }

    if (pending.items.len == 0) {
        return .{
            .alloc = alloc,
            .items = try writes.toOwnedSlice(alloc),
            .missing_required = missing_required,
        };
    }

    const SortContext = struct {};
    const sort_start_ns = if (profile != null) monotonicTimeNs() else 0;
    std.mem.sort(PendingDocumentWrite, pending.items, SortContext{}, struct {
        fn lessThan(_: SortContext, lhs: PendingDocumentWrite, rhs: PendingDocumentWrite) bool {
            return std.mem.order(u8, lhs.store_key, rhs.store_key) == .lt;
        }
    }.lessThan);
    if (profile) |p| p.sort_ns = monotonicTimeNs() - sort_start_ns;

    const read_keys = try alloc.alloc([]const u8, pending.items.len);
    defer alloc.free(read_keys);
    const read_values = try alloc.alloc(?[]const u8, pending.items.len);
    defer alloc.free(read_values);

    for (pending.items, 0..) |item, i| {
        read_keys[i] = item.store_key;
        read_values[i] = null;
    }
    const read_start_ns = if (profile != null) monotonicTimeNs() else 0;
    try txn.getManySorted(read_keys, read_values);
    if (profile) |p| p.read_ns = monotonicTimeNs() - read_start_ns;

    for (pending.items, 0..) |item, i| {
        const value = if (read_values[i]) |store_value| blk: {
            if (profile) |p| p.store_hits += 1;
            break :blk store_value;
        } else if (item.inline_value) |inline_value| blk: {
            if (profile) |p| p.inline_hits += 1;
            break :blk inline_value;
        } else {
            if (try replayDocumentIsDurablyDeleted(alloc, &txn, item.doc_key)) continue;
            missing_required += 1;
            continue;
        };
        const extract_start_ns = if (profile != null) monotonicTimeNs() else 0;
        if (try mapper.extractSparseVectorField(alloc, value, field_name)) |raw_sparse_vec| {
            var sparse_vec = raw_sparse_vec;
            writes.append(alloc, .{
                .doc_id = item.doc_key,
                .vec = .{
                    .indices = sparse_vec.indices,
                    .values = sparse_vec.values,
                },
            }) catch |err| {
                sparse_vec.deinit(alloc);
                return err;
            };
            if (profile) |p| p.output_writes += 1;
        } else if (profile) |p| {
            p.skipped_without_vector += 1;
        }
        if (profile) |p| p.extract_ns += monotonicTimeNs() - extract_start_ns;
    }
    if (profile) |p| {
        p.missing_required = missing_required;
        p.output_writes = writes.items.len;
    }

    return .{
        .alloc = alloc,
        .items = try writes.toOwnedSlice(alloc),
        .missing_required = missing_required,
    };
}

fn collectDocumentWrites(
    alloc: Allocator,
    store: *docstore_mod.DocStore,
    documents: []const derived_types.DerivedDocument,
    byte_range: types.ByteRange,
) !OwnedBatchWrites {
    return try collectDocumentWritesProfiled(alloc, store, documents, byte_range, .{}, null);
}

fn collectDocumentWritesProfiled(
    alloc: Allocator,
    store: *docstore_mod.DocStore,
    documents: []const derived_types.DerivedDocument,
    byte_range: types.ByteRange,
    opts: CollectDocumentWritesOptions,
    profile: ?*CollectDocumentWritesProfile,
) !OwnedBatchWrites {
    const PendingDocumentWrite = struct {
        doc_key: []const u8,
        store_key: []u8,
        inline_value: ?[]const u8,
    };

    var pending = std.ArrayListUnmanaged(PendingDocumentWrite).empty;
    defer {
        for (pending.items) |item| alloc.free(item.store_key);
        pending.deinit(alloc);
    }

    var writes = std.ArrayListUnmanaged(types.BatchWrite).empty;
    errdefer {
        for (writes.items) |item| alloc.free(@constCast(item.value));
        writes.deinit(alloc);
    }

    var txn = try store.beginProbeTxn();
    defer txn.abort();
    var missing_required: usize = 0;
    const trust_inline = opts.prefer_available_inline_values or
        if (opts.prefer_inline_when_store_tip_matches_sequence) |sequence|
            store.nextReplaySequence(sequence + 1) == sequence + 1
        else
            false;

    if (profile) |p| p.input_documents = documents.len;
    const scan_start_ns = if (profile != null) monotonicTimeNs() else 0;
    for (documents) |doc| {
        if (doc.action != .upsert) continue;
        if (!replayDocumentKeyInRange(byte_range, doc.key)) continue;
        if (opts.skip_doc_keys) |skip_doc_keys| {
            if (skip_doc_keys.contains(doc.key)) continue;
        }
        if (trust_inline and doc.cleaned_value != null) {
            const owned_value = try alloc.dupe(u8, doc.cleaned_value.?);
            try writes.append(alloc, .{
                .key = doc.key,
                .value = owned_value,
            });
            if (profile) |p| p.inline_hits += 1;
            continue;
        }
        try pending.append(alloc, .{
            .doc_key = doc.key,
            .store_key = try replayDocumentStoreKeyAlloc(alloc, doc.key),
            .inline_value = doc.cleaned_value,
        });
    }
    if (profile) |p| {
        p.scan_ns = monotonicTimeNs() - scan_start_ns;
        p.pending_documents = pending.items.len;
        p.output_writes = writes.items.len;
    }

    if (pending.items.len == 0) {
        return .{
            .alloc = alloc,
            .items = try writes.toOwnedSlice(alloc),
        };
    }

    const SortContext = struct {};
    const sort_start_ns = if (profile != null) monotonicTimeNs() else 0;
    std.mem.sort(PendingDocumentWrite, pending.items, SortContext{}, struct {
        fn lessThan(_: SortContext, lhs: PendingDocumentWrite, rhs: PendingDocumentWrite) bool {
            return std.mem.order(u8, lhs.store_key, rhs.store_key) == .lt;
        }
    }.lessThan);
    if (profile) |p| p.sort_ns = monotonicTimeNs() - sort_start_ns;

    const read_keys = try alloc.alloc([]const u8, pending.items.len);
    defer alloc.free(read_keys);
    const read_values = try alloc.alloc(?[]const u8, pending.items.len);
    defer alloc.free(read_values);

    for (pending.items, 0..) |item, i| {
        read_keys[i] = item.store_key;
        read_values[i] = null;
    }
    const read_start_ns = if (profile != null) monotonicTimeNs() else 0;
    try txn.getManySorted(read_keys, read_values);
    if (profile) |p| p.read_ns = monotonicTimeNs() - read_start_ns;

    const materialize_start_ns = if (profile != null) monotonicTimeNs() else 0;
    for (pending.items, 0..) |item, i| {
        const value = if (read_values[i]) |store_value| blk: {
            if (profile) |p| p.store_hits += 1;
            break :blk store_value;
        } else if (item.inline_value) |inline_value| blk: {
            if (profile) |p| p.inline_hits += 1;
            break :blk inline_value;
        } else {
            if (try replayDocumentIsDurablyDeleted(alloc, &txn, item.doc_key)) continue;
            missing_required += 1;
            continue;
        };
        const owned_value = try alloc.dupe(u8, value);
        try writes.append(alloc, .{
            .key = item.doc_key,
            .value = owned_value,
        });
    }
    if (profile) |p| {
        p.materialize_ns = monotonicTimeNs() - materialize_start_ns;
        p.output_writes = writes.items.len;
        p.missing_required = missing_required;
    }

    return .{
        .alloc = alloc,
        .items = try writes.toOwnedSlice(alloc),
        .missing_required = missing_required,
    };
}

fn appendUniqueBorrowedKey(
    alloc: Allocator,
    out: *std.ArrayListUnmanaged([]const u8),
    key: []const u8,
) !void {
    if (key.len == 0) return;
    for (out.items) |existing| {
        if (std.mem.eql(u8, existing, key)) return;
    }
    try out.append(alloc, key);
}

fn collectTextReplayDeleteKeys(alloc: Allocator, batch: derived_types.DerivedBatch) ![]const []const u8 {
    var keys = std.ArrayListUnmanaged([]const u8).empty;
    errdefer keys.deinit(alloc);

    for (batch.deleted_keys) |key| try appendUniqueBorrowedKey(alloc, &keys, key);
    for (batch.overwritten_doc_keys) |key| try appendUniqueBorrowedKey(alloc, &keys, key);
    for (batch.documents) |doc| {
        if (doc.action != .upsert) continue;
        try appendUniqueBorrowedKey(alloc, &keys, doc.key);
    }

    return try keys.toOwnedSlice(alloc);
}

fn denseEmbeddingDocKeySet(
    alloc: Allocator,
    embeddings: []const mapper.DenseEmbeddingWrite,
) !std.StringHashMapUnmanaged(void) {
