    var io_impl = threadedIo();
    defer io_impl.deinit();
    const io = io_impl.io();
    var file = try fs_paths.createFilePortable(io, path, .{ .truncate = true });
    defer file.close(io);
    var buf: [4096]u8 = undefined;
    var writer = file.writer(io, &buf);
    try writer.interface.writeAll(raw);
    try writer.end();
}

