    defer template_remote.setHostRenderer(null);

    try std.testing.expectError(
        error.PermanentPromptFailure,
        renderSourceTemplateParts(
            alloc,
            null,
            null,
            "{{remoteMedia url=this}}",
            "\"https://example.com/photo.png\"",
            null,
        ),
    );
}

