    const final_stats = try db.stats(alloc);
    defer types.freeDBStats(alloc, final_stats);
    try std.testing.expectEqual(@as(u64, 0), final_stats.enrichment.fatal_error_count);
    try std.testing.expect(!final_stats.enrichment.worker_failed);
    for (final_stats.indexes) |index_stats| {
        if (!std.mem.eql(u8, index_stats.name, "sp_v1")) continue;
        try std.testing.expectEqual(@as(u64, 1), index_stats.doc_count);
        try std.testing.expectEqual(@as(u64, 1), index_stats.coverage_produced_count);
        try std.testing.expectEqual(@as(u64, 0), index_stats.coverage_terminal_failed_count);
        try std.testing.expect(!index_stats.enrichment_failed);
    }

    var query = try gated.deterministic.interface().embedSparse(alloc, "sp_v1", "alpha concept overview");
    defer query.deinit(alloc);
    var result = try db.search(alloc, .{
        .index_name = "sp_v1",
        .query = .{ .sparse_knn = .{
            .indices = query.indices,
            .values = query.values,
            .k = 1,
        } },
        .limit = 1,
    });
    defer result.deinit();
    try std.testing.expectEqual(@as(u32, 1), result.total_hits);
    try std.testing.expectEqualStrings("doc:a", result.hits[0].id);
}

test "db chunked dense enrichment retries temporary model capacity without terminal coverage" {
    const alloc = std.testing.allocator;

    var path_buf: [256]u8 = undefined;
    const path = tempPath(&path_buf);
    defer cleanupTempDir(path);

    var gated = GateDenseEmbedder{
        .allowed_successes = .init(0),
        .blocked_error = error.ResourceTemporarilyUnavailable,
    };
    var db = try DB.open(alloc, std.mem.span(path), .{
        .enrichment = .{
            .owner_id = "worker-a",
            .dense_embedder = gated.interface(),
            .inline_retry_max_attempts = 1,
        },
    });
    defer db.close();

    try db.addIndex(.{
        .name = "dv_v1",
        .kind = .dense_vector,
        .config_json = "{\"field\":\"embedding\",\"dims\":3,\"generator\":{\"kind\":\"dense_embedding\",\"source_field\":\"body\",\"chunk_name\":\"body_chunks_v1\",\"chunk_size\":8,\"chunk_overlap\":2,\"embedding_name\":\"chunk_dense_v1\"}}",
    });
    try db.batch(.{
        .writes = &.{.{ .key = "doc:a", .value = "{\"body\":\"abcdefghijklmno\"}" }},
        .sync_level = .write,
    });

    var observed_retry = false;
    var attempts: usize = 0;
    while (attempts < default_test_wait_attempts) : (attempts += 1) {
        const stats = try db.stats(alloc);
        if (gated.snapshot().blocked_requests > 0 and stats.enrichment.retryable_error_count > 0) {
            try std.testing.expectEqual(@as(u64, 0), stats.enrichment.fatal_error_count);
            for (stats.indexes) |index_stats| {
                if (!std.mem.eql(u8, index_stats.name, "dv_v1")) continue;
                try std.testing.expect(!index_stats.enrichment_failed);
                try std.testing.expectEqual(@as(u64, 0), index_stats.coverage_terminal_failed_count);
            }
            observed_retry = true;
        }
        types.freeDBStats(alloc, stats);
        if (observed_retry) break;
        sleepNs(10 * std.time.ns_per_ms);
    }
    try std.testing.expect(observed_retry);

    gated.allowAll();
    try db.runUntilIdle();

    const final_stats = try db.stats(alloc);
    defer types.freeDBStats(alloc, final_stats);
    try std.testing.expectEqual(@as(u64, 0), final_stats.enrichment.fatal_error_count);
    for (final_stats.indexes) |index_stats| {
        if (!std.mem.eql(u8, index_stats.name, "dv_v1")) continue;
        try std.testing.expectEqual(@as(u64, 0), index_stats.coverage_terminal_failed_count);
        try std.testing.expect(!index_stats.enrichment_failed);
    }
    try std.testing.expectEqual(@as(u64, 3), db.core.index_manager.denseIndex("dv_v1").?.index.metadata.active_count);

    const query_vec = try gated.interface().embedDense(alloc, "chunk_dense_v1", "abcdefgh", 3);
    defer alloc.free(query_vec);
    var result = try db.search(alloc, .{
        .index_name = "dv_v1",
        .dense = .{ .vector = query_vec, .k = 3 },
        .return_mode = .parent,
    });
    defer result.deinit();
    try std.testing.expectEqual(@as(u32, 1), result.total_hits);
    try std.testing.expectEqualStrings("doc:a", result.hits[0].id);
}

test "db managed dense delete quiesces rate-limited enrichment and recreates cleanly" {
    const alloc = std.testing.allocator;

    var path_buf: [256]u8 = undefined;
    const path = tempPath(&path_buf);
    defer cleanupTempDir(path);

    var gated = GateDenseEmbedder{};
    var db = try DB.open(alloc, std.mem.span(path), .{
        .enrichment = .{
            .owner_id = "worker-a",
            .dense_embedder = gated.interface(),
        },
    });
    defer db.close();

    const cfg: types.IndexConfig = .{
        .name = "semantic_idx",
        .kind = .dense_vector,
        .config_json = "{\"field\":\"embedding\",\"dims\":3,\"metric\":\"cosine\",\"generator\":{\"kind\":\"dense_embedding\",\"source_field\":\"body\",\"embedding_name\":\"semantic_idx\"}}",
    };
    try db.addIndex(cfg);
    try db.batch(.{
        .writes = &.{
            .{ .key = "doc:a", .value = "{\"body\":\"alpha concept overview\"}" },
            .{ .key = "doc:b", .value = "{\"body\":\"beta architecture notes\"}" },
            .{ .key = "doc:c", .value = "{\"body\":\"gamma implementation details\"}" },
        },
        .sync_level = .write,
    });

    var attempts: usize = 0;
    while (attempts < 200 and gated.snapshot().blocked_requests == 0) : (attempts += 1) {
        sleepNs(10 * std.time.ns_per_ms);
    }
    try std.testing.expect(gated.snapshot().blocked_requests > 0);

    // One coalesced issue may accumulate more terminal-failure history than a
    // single retirement page during a prolonged provider outage. Admission
    // must remain fenced until all of it is gone, rather than shifting cleanup
    // and fail-closed retries onto the replacement generation's first writes.
    const retired_issue: types.ArtifactRepairIssue = .{
        .artifact_kind = .embedding,
        .index_name = cfg.name,
        .doc_key = "doc:retired",
        .artifact_name = cfg.name,
        .artifact_key = "retired-generation-artifact",
        .reason = .enrichment_failed,
    };
    for (0..enrichment_terminal_failure_retirement_page_size + 7) |i| {
        var sequenced = retired_issue;
        sequenced.sequence = 10_000 + @as(u64, @intCast(i));
        try db.recordArtifactRepairIssue(alloc, sequenced);
    }
    const retired_issue_key = try artifactRepairIssueKeyForIssueAlloc(alloc, retired_issue);
    defer alloc.free(retired_issue_key);
    const retired_marker_prefix = try internal_keys.enrichmentTerminalFailureIssuePrefixAlloc(alloc, retired_issue_key);
    defer alloc.free(retired_marker_prefix);
    {
        const marker_rows = try db.core.store.scanPrefixPage(alloc, retired_marker_prefix, null, 1);
        defer docstore_mod.DocStore.freeResults(alloc, marker_rows);
        try std.testing.expectEqual(@as(usize, 1), marker_rows.len);
    }
    const retired_generation_key = try internal_keys.enrichmentTerminalFailureGenerationKeyAlloc(alloc, retired_issue_key);
    defer alloc.free(retired_generation_key);
    const retired_completion_key = try db.artifactRepairCompletionKeyForIssueAlloc(alloc, retired_issue);
    defer alloc.free(retired_completion_key);

    const delete_started_ns = monotonicTimeNs();
    try std.testing.expect(try db.deleteIndex("semantic_idx"));
    try std.testing.expect(monotonicTimeNs() - delete_started_ns < 2 * std.time.ns_per_s);

    gated.allowAll();
    db.backend_runtime.durable_jobs.drainOwner(db.repair_cleanup_owner_id);
    {
        const issues = try db.listArtifactRepairIssues(alloc, .embedding, cfg.name, 0);
        defer types.freeArtifactRepairIssues(alloc, issues);
        try std.testing.expectEqual(@as(usize, 0), issues.len);
        const marker_rows = try db.core.store.scanPrefixPage(alloc, retired_marker_prefix, null, 1);
        defer docstore_mod.DocStore.freeResults(alloc, marker_rows);
        try std.testing.expectEqual(@as(usize, 0), marker_rows.len);
        try std.testing.expectError(error.NotFound, db.core.store.get(alloc, retired_generation_key));
        try std.testing.expectError(error.NotFound, db.core.store.get(alloc, retired_completion_key));
    }
    try db.addIndex(cfg);
    try db.runUntilIdle();

    const stats = try db.stats(alloc);
    defer types.freeDBStats(alloc, stats);
    try std.testing.expectEqual(@as(usize, 1), stats.indexes.len);
    try std.testing.expect(!stats.enrichment.worker_failed);
    try std.testing.expectEqual(@as(u64, 3), stats.indexes[0].doc_count);
    try std.testing.expect(stats.indexes[0].replay_applied_sequence >= stats.indexes[0].replay_target_sequence);
    try std.testing.expect(stats.indexes[0].repair_summary_ready);
    try std.testing.expect(!stats.indexes[0].repair_degraded);
    try std.testing.expectEqual(@as(u64, 0), stats.indexes[0].repair_issue_count);
}

test "retired repair cleanup propagates allocation failures from durable metadata parsing" {
    const alloc = std.testing.allocator;
    const issue: types.ArtifactRepairIssue = .{
        .artifact_kind = .embedding,
        .index_name = "retired_index",
        .doc_key = "doc:retired",
        .artifact_name = "retired_index",
        .artifact_key = "retired-physical-artifact",
        .reason = .enrichment_failed,
    };
    const issue_key = try artifactRepairIssueKeyForIssueAlloc(alloc, issue);
    defer alloc.free(issue_key);
    const encoded_issue = try encodeArtifactRepairIssueValueAlloc(alloc, issue);
    defer alloc.free(encoded_issue);

    try std.testing.checkAllAllocationFailures(
        alloc,
        struct {
            fn run(failing_alloc: Allocator, key: []const u8) !void {
                var parsed = try DB.parseRetiredArtifactRepairIssueKeyAlloc(failing_alloc, key);
                switch (parsed) {
                    .valid => |*parts| parts.deinit(failing_alloc),
                    .malformed => return error.UnexpectedMalformedRepairIssueKey,
                }
            }
        }.run,
        .{issue_key},
    );
    try std.testing.checkAllAllocationFailures(
        alloc,
        struct {
            fn run(failing_alloc: Allocator, raw: []const u8) !void {
                var decoded = try DB.decodeRetiredArtifactRepairIssueAlloc(failing_alloc, raw);
                switch (decoded) {
                    .valid => |*value| value.deinit(failing_alloc),
                    .malformed => return error.UnexpectedMalformedRepairIssueValue,
                }
            }
        }.run,
        .{encoded_issue},
    );

    const malformed_key = try DB.parseRetiredArtifactRepairIssueKeyAlloc(alloc, "not-an-internal-key");
    switch (malformed_key) {
        .valid => |value| {
            var owned = value;
            owned.deinit(alloc);
            return error.ExpectedMalformedRepairIssueKey;
        },
        .malformed => {},
    }
    const malformed_value = try DB.decodeRetiredArtifactRepairIssueAlloc(alloc, "{");
    switch (malformed_value) {
        .valid => |value| {
            var owned = value;
            owned.deinit(alloc);
            return error.ExpectedMalformedRepairIssueValue;
        },
        .malformed => {},
    }
}

test "retired repair cleanup resumes marker retirement and removes corrupt sidecars after reopen" {
    const alloc = std.testing.allocator;

    var path_buf: [256]u8 = undefined;
    const path = tempPath(&path_buf);
    defer cleanupTempDir(path);

    const issue: types.ArtifactRepairIssue = .{
        .artifact_kind = .embedding,
        .index_name = "retired_index",
        .doc_key = "doc:retired",
        .artifact_name = "retired_index",
        .artifact_key = "retired-physical-artifact",
        .reason = .enrichment_failed,
    };
    const issue_key = try artifactRepairIssueKeyForIssueAlloc(alloc, issue);
    defer alloc.free(issue_key);
    const marker_prefix = try internal_keys.enrichmentTerminalFailureIssuePrefixAlloc(alloc, issue_key);
    defer alloc.free(marker_prefix);
    const generation_key = try internal_keys.enrichmentTerminalFailureGenerationKeyAlloc(alloc, issue_key);
    defer alloc.free(generation_key);
    const completion_key = try internal_keys.artifactRepairCompletionKeyAlloc(
        alloc,
        @tagName(issue.artifact_kind),
        issue.artifact_key,
    );
    defer alloc.free(completion_key);
    const kind_key = try artifactRepairIssueKindKeyForIssueAlloc(alloc, issue);
    defer alloc.free(kind_key);

    {
        var db = try DB.open(alloc, std.mem.span(path), .{
            .start_index_workers = false,
            .start_optional_runtime_workers = false,
            .ttl_cleanup = .{ .enabled = false },
        });
        defer db.close();

        for (0..enrichment_terminal_failure_retirement_page_size + 7) |i| {
            var sequenced = issue;
            sequenced.sequence = 20_000 + @as(u64, @intCast(i));
            try db.recordArtifactRepairIssue(alloc, sequenced);
        }
        try db.runArtifactRepairMetadataMaintenanceUntilIdle();
        // The primary key remains trustworthy even when the payload does not.
        // Cleanup must use it to drain marker, generation, secondary, and
        // single-flight sidecars without following corrupt value fields.
        try db.core.store.put(issue_key, "malformed-repair-issue");

        try std.testing.expect(try DB.drainRetiredIndexArtifactRepairIssuesPageContext(
            db.async_context,
            issue.index_name,
        ));
        const primary = try db.core.store.get(alloc, issue_key);
        alloc.free(primary);
        const remaining_markers = try db.core.store.scanPrefixPage(
            alloc,
            marker_prefix,
            null,
            enrichment_terminal_failure_retirement_page_size,
        );
        defer docstore_mod.DocStore.freeResults(alloc, remaining_markers);
        try std.testing.expectEqual(@as(usize, 7), remaining_markers.len);
    }

    var reopened = try DB.open(alloc, std.mem.span(path), .{
        .start_index_workers = false,
        .start_optional_runtime_workers = false,
        .ttl_cleanup = .{ .enabled = false },
    });
    defer reopened.close();

    var drained = false;
    for (0..8) |_| {
        if (!try DB.drainRetiredIndexArtifactRepairIssuesPageContext(
            reopened.async_context,
            issue.index_name,
        )) {
            drained = true;
            break;
        }
    }
    try std.testing.expect(drained);
    try std.testing.expectError(error.NotFound, reopened.core.store.get(alloc, issue_key));
    try std.testing.expectError(error.NotFound, reopened.core.store.get(alloc, kind_key));
    try std.testing.expectError(error.NotFound, reopened.core.store.get(alloc, generation_key));
    try std.testing.expectError(error.NotFound, reopened.core.store.get(alloc, completion_key));
    const remaining_markers = try reopened.core.store.scanPrefixPage(alloc, marker_prefix, null, 1);
    defer docstore_mod.DocStore.freeResults(alloc, remaining_markers);
    try std.testing.expectEqual(@as(usize, 0), remaining_markers.len);

    try reopened.runArtifactRepairMetadataMaintenanceUntilIdle();
    try std.testing.expect(try reopened.artifactRepairSummaryReady(alloc));
}

test "db dense checkpoint persistence serializes with index apply" {
    const alloc = std.testing.allocator;

    var path_buf: [256]u8 = undefined;
    const path = tempPath(&path_buf);
    defer cleanupTempDir(path);

    var db = try DB.open(alloc, std.mem.span(path), .{
        .start_index_workers = false,
        .ttl_cleanup = .{ .enabled = false },
    });
    defer db.close();
    try db.addIndex(.{
        .name = "dense_checkpoint_lock",
        .kind = .dense_vector,
        .config_json = "{\"field\":\"embedding\",\"dims\":3}",
    });

    var apply_guard = try db.core.index_manager.lockManagedIndexApply(.{
        .name = "dense_checkpoint_lock",
        .kind = .dense_vector,
    });
    var apply_locked = true;
    defer if (apply_locked) apply_guard.unlock();

    const Persist = struct {
        db: *DB,
        started: std.atomic.Value(bool) = .init(false),
        done: std.atomic.Value(bool) = .init(false),
        err: ?anyerror = null,

        fn run(state: *@This()) void {
            state.started.store(true, .release);
            state.db.core.index_manager.saveDenseProjectionCheckpointMetadata(
                "dense_checkpoint_lock",
                .{ .applied_sequence = 1, .status = .clean },
            ) catch |err| {
                state.err = err;
            };
            state.done.store(true, .release);
        }
    };
    var persist = Persist{ .db = &db };
    const thread = try std.Thread.spawn(.{}, Persist.run, .{&persist});
    while (!persist.started.load(.acquire)) std.atomic.spinLoopHint();
    sleepNs(25 * std.time.ns_per_ms);
    const completed_while_apply_active = persist.done.load(.acquire);

    apply_guard.unlock();
    apply_locked = false;
    thread.join();

    try std.testing.expect(!completed_while_apply_active);
    if (persist.err) |err| return err;
    try std.testing.expect(persist.done.load(.acquire));
}

test "db open quarantines dense index with unsupported artifact version" {
    const alloc = std.testing.allocator;

    var path_buf: [256]u8 = undefined;
    const path = tempPath(&path_buf);
    defer cleanupTempDir(path);

    const dense_cfg: types.IndexConfig = .{
        .name = "dv_quarantine",
        .kind = .dense_vector,
        .config_json = "{\"field\":\"embedding\",\"dims\":3,\"generator\":{\"kind\":\"dense_embedding\",\"source_field\":\"body\",\"embedding_name\":\"dv_quarantine\"}}",
    };

    var deterministic = embedder_mod.DeterministicDenseEmbedder{};
    const open_options: OpenOptions = .{
        .enrichment = .{
            .owner_id = "quarantine-worker",
            .dense_embedder = deterministic.interface(),
        },
    };

    {
        var db = try DB.open(alloc, std.mem.span(path), open_options);
        defer db.close();

        try db.addIndex(.{ .name = "ft_v1", .kind = .full_text, .config_json = "{}" });
        try db.addIndex(dense_cfg);
        try db.batch(.{
            .writes = &.{
                .{ .key = "doc:a", .value = "{\"title\":\"alpha\",\"body\":\"alpha concept overview\"}" },
            },
            .sync_level = .write,
        });
        try db.runUntilIdle();

        // Persist an HBC metadata record with a version this build does not
        // support, simulating an artifact written by an incompatible build.
        const entry = db.core.denseIndex("dv_quarantine") orelse return error.TestUnexpectedResult;
        var bad_meta = entry.index.metadata;
        bad_meta.version = 99;
        var meta_buf: [vectorindex_mod.hbc.IndexMetadata.encoded_size]u8 = undefined;
        const encoded = bad_meta.encode(&meta_buf);
        var txn = try entry.index.beginWriteTxn();
        errdefer txn.abort();
        try txn.put(.meta, vectorindex_mod.hbc.meta_key, encoded);
        try txn.commit();
    }

    var db = try DB.open(alloc, std.mem.span(path), open_options);
    defer db.close();

    // The broken dense index is quarantined: absent from the runtime, its
    // load error recorded, and the rest of the table fully usable.
    try std.testing.expect(db.core.denseIndex("dv_quarantine") == null);
    const recorded = db.core.index_manager.loadFailure("dv_quarantine") orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("UnsupportedVersion", recorded);

    var ft_result = try db.search(alloc, .{
        .index_name = "ft_v1",
        .full_text = .{ .match = .{ .field = "title", .text = "alpha" } },
    });
    defer ft_result.deinit();
    try std.testing.expectEqual(@as(u32, 1), ft_result.total_hits);

    {
        const stats = try db.stats(alloc);
        defer types.freeDBStats(alloc, stats);
        var found = false;
        for (stats.indexes) |item| {
            if (!std.mem.eql(u8, item.name, "dv_quarantine")) continue;
            found = true;
            const load_error = item.load_error orelse return error.TestUnexpectedResult;
            try std.testing.expectEqualStrings("UnsupportedVersion", load_error);
            try std.testing.expect(!item.backfill_active);
        }
        try std.testing.expect(found);
    }

    // Queries that explicitly reference the quarantined index get a distinct
    // error instead of IndexNotFound or a stall.
    const query_vec = [_]f32{ 0.1, 0.2, 0.3 };
    try std.testing.expectError(error.IndexUnavailable, db.search(alloc, .{
        .index_name = "dv_quarantine",
        .dense = .{
            .vector = &query_vec,
            .k = 1,
        },
        .limit = 1,
    }));

    // Drop + recreate recovers and clears the recorded failure.
    try std.testing.expect(try db.deleteIndex("dv_quarantine"));
    try std.testing.expect(db.core.index_manager.loadFailure("dv_quarantine") == null);
    db.backend_runtime.durable_jobs.drainOwner(db.repair_cleanup_owner_id);
    try db.addIndex(dense_cfg);
    try db.runUntilIdle();
    try std.testing.expect(db.core.denseIndex("dv_quarantine") != null);

    const recovered_vec = try deterministic.interface().embedDense(alloc, "dv_quarantine", "alpha concept overview", 3);
    defer alloc.free(recovered_vec);
    var recovered = try waitForSearchResult(alloc, &db, .{
        .index_name = "dv_quarantine",
        .dense = .{
            .vector = recovered_vec,
            .k = 1,
        },
        .limit = 1,
    }, 1);
    defer recovered.deinit();
    try std.testing.expect(recovered.total_hits >= 1);
}

fn corruptNonEmptyFilesUnderDir(alloc: Allocator, root_path: []const u8) !usize {
    var io_impl = threadedIo();
    defer io_impl.deinit();
    const io = io_impl.io();

    var root_dir = try std.Io.Dir.cwd().openDir(io, root_path, .{ .iterate = true });
    defer root_dir.close(io);

    var walker = try root_dir.walk(alloc);
    defer walker.deinit();

    var corrupted: usize = 0;
    while (try walker.next(io)) |entry| {
        if (entry.kind != .file) continue;
        const full_path = try std.fmt.allocPrint(alloc, "{s}/{s}", .{ root_path, entry.path });
        defer alloc.free(full_path);
        const stat = try std.Io.Dir.cwd().statFile(io, full_path, .{});
        if (stat.size == 0) continue;

        const bytes = try alloc.alloc(u8, @intCast(stat.size));
        defer alloc.free(bytes);
        for (bytes, 0..) |*byte, i| {
            byte.* = @truncate((i *% 131) +% 17);
        }
        try std.Io.Dir.cwd().writeFile(io, .{
            .sub_path = full_path,
            .data = bytes,
        });
        corrupted += 1;
    }
    return corrupted;
}

test "db drops quarantined dense index after persisted index directory corruption" {
    const alloc = std.testing.allocator;

    var path_buf: [256]u8 = undefined;
    const path = tempPath(&path_buf);
    defer cleanupTempDir(path);
    const path_slice = std.mem.span(path);

    const dense_cfg: types.IndexConfig = .{
        .name = "dv_corrupt",
        .kind = .dense_vector,
