test "db generated enrichment backfill drains stored docs beyond first replay chunk" {
    const alloc = std.testing.allocator;

    var path_buf: [256]u8 = undefined;
    const path = tempPath(&path_buf);
    defer cleanupTempDir(path);

    var deterministic = embedder_mod.DeterministicDenseEmbedder{};
    var db = try DB.open(alloc, std.mem.span(path), .{
        .enrichment = .{
            .owner_id = "embedded-worker",
            .dense_embedder = deterministic.interface(),
        },
    });
    defer db.close();

    const total_docs: usize = 129;
    const writes = try alloc.alloc(types.BatchWrite, total_docs);
    defer {
        for (writes) |write| {
            alloc.free(@constCast(write.key));
            alloc.free(@constCast(write.value));
        }
        alloc.free(writes);
    }
    for (writes, 0..) |*write, i| {
        write.* = .{
            .key = try std.fmt.allocPrint(alloc, "doc:{d:0>3}", .{i}),
            .value = try std.fmt.allocPrint(alloc, "{{\"title\":\"doc {d}\",\"body\":\"generated vector text {d}\"}}", .{ i, i }),
        };
    }
    try db.batch(.{
        .writes = writes,
        .sync_level = .write,
    });

    try db.addIndex(.{
        .name = "dv_v1",
        .kind = .dense_vector,
        .config_json = "{\"field\":\"embedding\",\"dims\":3,\"generator\":{\"kind\":\"dense_embedding\",\"source_field\":\"body\",\"embedding_name\":\"body_dense_v1\"}}",
    });
    try db.runUntilIdle();

    const pending_after = db.pendingWorkStats();
    try std.testing.expectEqual(pending_after.enrichment.target_sequence, pending_after.enrichment.applied_sequence);

    const last_artifact_key = try expectedDocumentEmbeddingArtifactKeyAlloc(alloc, "doc:128", "body_dense_v1");
    defer alloc.free(last_artifact_key);
    const last_artifact = try db.core.store.get(alloc, last_artifact_key);
    defer alloc.free(last_artifact);
    try expectDenseEmbeddingArtifactWithSourceHash(alloc, last_artifact, 3);

    const dense_entry = db.core.denseIndex("dv_v1") orelse return error.IndexNotFound;
    try std.testing.expectEqual(@as(u64, @intCast(total_docs)), dense_entry.index.stats().active_count);
}

test "db runUntilIdle drains lazy dense posting maintenance" {
    const alloc = std.testing.allocator;

    var path_buf: [256]u8 = undefined;
    const path = tempPath(&path_buf);
    defer cleanupTempDir(path);

    var db = try DB.open(alloc, std.mem.span(path), .{});
    defer db.close();

    try db.addIndex(.{
        .name = "dv_v1",
        .kind = .dense_vector,
        .config_json = "{\"field\":\"embedding\",\"dims\":2,\"metric\":\"l2_squared\",\"use_quantization\":false,\"lazy_posting_maintenance\":true,\"auto_posting_maintenance_max_postings\":0}",
    });

    try db.batch(.{
        .writes = &.{
            .{ .key = "doc:a", .value = "{\"embedding\":[1.0,0.0]}" },
            .{ .key = "doc:b", .value = "{\"embedding\":[3.0,0.0]}" },
        },
        .sync_level = .full_index,
    });

    {
        const entry = db.core.denseIndex("dv_v1") orelse return error.IndexNotFound;
        var txn = try entry.index.beginWriteTxn();
        errdefer txn.abort();
        var root = try entry.index.loadNode(&txn, entry.index.metadata.root_node);
        defer root.deinit(alloc);
        try root.ensureUnbacked(alloc);
        root.posting_state.noteMembersChanged(root.members.len);
        try entry.index.saveNode(&txn, &root);
        try entry.index.finishWriteTxn(&txn);
        entry.index.invalidateNodeCache(root.id);
    }

    {
        const stats = try db.diagnosticStats(alloc);
        defer types.freeDBStats(alloc, stats);
        try std.testing.expectEqual(@as(u64, 1), stats.indexes[0].hbc_posting.dirty_postings);
    }

    try db.runUntilIdle();

    {
        const stats = try db.diagnosticStats(alloc);
        defer types.freeDBStats(alloc, stats);
        try std.testing.expectEqual(@as(u64, 0), stats.indexes[0].hbc_posting.dirty_postings);
        try std.testing.expect(stats.indexes[0].hbc_posting.maintenance_repaired_postings > 0);
    }
}

test "db leased enrichment worker materializes chunk artifacts" {
    const alloc = std.testing.allocator;

    var path_buf: [256]u8 = undefined;
    const path = tempPath(&path_buf);
    defer cleanupTempDir(path);

    var deterministic = embedder_mod.DeterministicDenseEmbedder{};
    var db = try DB.open(alloc, std.mem.span(path), .{
        .enrichment = .{
            .owner_id = "worker-a",
            .dense_embedder = deterministic.interface(),
        },
    });
    defer db.close();

    try db.addIndex(.{
        .name = "dv_v1",
        .kind = .dense_vector,
        .config_json = "{\"field\":\"embedding\",\"dims\":3,\"generator\":{\"kind\":\"dense_embedding\",\"source_field\":\"body\",\"chunk_name\":\"body_chunks_v1\",\"chunk_size\":8,\"chunk_overlap\":2}}",
    });

    try db.batch(.{
        .writes = &.{
            .{ .key = "doc:a", .value = "{\"body\":\"abcdefghijklmno\"}" },
        },
        .sync_level = .write,
    });

    try db.enrichment_runtime.?.waitForApplied(1);
    try waitForDerivedReplayTarget(&db);

    const chunk_prefix = try internal_keys.artifactNamedPrefixAlloc(alloc, "doc:a", "chunk", "body_chunks_v1");
    defer alloc.free(chunk_prefix);
    const chunk_zero = try expectedChunkArtifactKeyAlloc(alloc, "doc:a", "body_chunks_v1", 0);
    defer alloc.free(chunk_zero);
    const artifacts = try db.core.store.scanPrefix(alloc, chunk_prefix);
    defer docstore_mod.DocStore.freeResults(alloc, artifacts);

    var chunk_count: usize = 0;
    var embedding_count: usize = 0;
    for (artifacts) |entry| {
        if (internal_keys.isChunkArtifactRecordKey(entry.key)) {
            if (chunk_count == 0) {
                try std.testing.expectEqualStrings(chunk_zero, entry.key);
                try std.testing.expect(std.mem.indexOf(u8, entry.value, "\"abcdefgh\"") != null);
            }
            chunk_count += 1;
            continue;
        }
        if (internal_keys.isDerivedEmbeddingArtifactKey(entry.key)) {
            embedding_count += 1;
            try expectDenseEmbeddingArtifactWithSourceHash(alloc, entry.value, 3);
        }
    }
    try std.testing.expect(chunk_count > 0);
    try std.testing.expectEqual(@as(usize, 3), embedding_count);
}

