test "db full-text index backfill and search routing" {
    const alloc = std.testing.allocator;

    var path_buf: [256]u8 = undefined;
    const path = tempPath(&path_buf);
    defer cleanupTempDir(path);

    var db = try DB.open(alloc, std.mem.span(path), .{});
    defer db.close();

    try db.batch(.{
        .writes = &.{
            .{ .key = "doc:a", .value = "{\"title\":\"alpha\",\"body\":\"first body\"}" },
            .{ .key = "doc:b", .value = "{\"title\":\"beta\",\"body\":\"second alpha\"}" },
        },
    });

    try db.addIndex(.{
        .name = "ft_v1",
        .kind = .full_text,
        .config_json = "{}",
    });

    var term_result = try db.search(alloc, .{
        .index_name = "ft_v1",
        .query = .{ .term = .{ .field = "title", .term = "alpha" } },
        .limit = 10,
    });
    defer term_result.deinit();

    try std.testing.expectEqual(@as(u32, 1), term_result.total_hits);
    try std.testing.expectEqualStrings("doc:a", term_result.hits[0].id);

    try db.batch(.{
        .writes = &.{
            .{ .key = "doc:c", .value = "{\"title\":\"gamma\",\"body\":\"alpha third\"}" },
        },
        .sync_level = .full_index,
    });

    var match_result = try waitForSearchResult(alloc, &db, .{
        .index_name = "ft_v1",
        .query = .{ .match = .{ .field = "body", .text = "alpha" } },
        .limit = 10,
    }, 2);
    defer match_result.deinit();

    try std.testing.expectEqual(@as(u32, 2), match_result.total_hits);

    var match_all_result = try db.search(alloc, .{
        .index_name = "ft_v1",
        .query = .{ .match_all = {} },
        .limit = 10,
    });
    defer match_all_result.deinit();

    try std.testing.expectEqual(@as(u32, 3), match_all_result.total_hits);
}

test "db full-text backfill resumes after interrupted reopen" {
    const alloc = std.testing.allocator;

    var path_buf: [256]u8 = undefined;
    const path = tempPath(&path_buf);
    defer cleanupTempDir(path);

    {
        var db = try DB.open(alloc, std.mem.span(path), .{});
        defer db.close();

        var writes = std.ArrayListUnmanaged(types.BatchWrite).empty;
        defer {
            for (writes.items) |item| {
                alloc.free(@constCast(item.key));
                alloc.free(@constCast(item.value));
            }
            writes.deinit(alloc);
        }

        for (0..10) |i| {
            try writes.append(alloc, .{
                .key = try std.fmt.allocPrint(alloc, "doc:{d:0>4}", .{i}),
                .value = try std.fmt.allocPrint(alloc, "{{\"title\":\"alpha\",\"n\":{d}}}", .{i}),
            });
        }

        try db.batch(.{ .writes = writes.items });
        try db.core.index_manager.addAllNoBackfill(db.core.store, &.{.{
            .name = "ft_v1",
            .kind = .full_text,
            .config_json = "{}",
        }});
    }

    index_manager_mod.test_text_backfill_batch_size = 4;
    defer index_manager_mod.test_text_backfill_batch_size = null;
    index_manager_mod.test_abort_text_backfill_after_batches = 1;
    defer index_manager_mod.test_abort_text_backfill_after_batches = null;
    var state_path: ?[]u8 = null;
    defer if (state_path) |owned| alloc.free(owned);
    {
        // A per-index load failure no longer fails the whole open; the index
        // is quarantined with its error recorded and retried on next open.
        var interrupted = try DB.open(alloc, std.mem.span(path), .{});
        defer interrupted.close();
        const recorded = interrupted.core.index_manager.loadFailure("ft_v1") orelse return error.TestUnexpectedResult;
        try std.testing.expectEqualStrings("TestInjectedBackfillFailure", recorded);

        const cfg = interrupted.core.index_manager.get("ft_v1") orelse return error.IndexNotFound;
        const rebuild_root = try interrupted.denseIndexRebuildStatePathAlloc(alloc, cfg.name);
        defer alloc.free(rebuild_root);
        const rebuild_state = interrupted.core.index_manager.rebuildState(cfg.kind, rebuild_root, cfg.*);
        state_path = try rebuild_state.pathAlloc(alloc);
    }

    const interrupted_state = try std.Io.Dir.cwd().readFileAlloc(std.testing.io, state_path.?, alloc, .limited(1024));
    defer alloc.free(interrupted_state);
    try std.testing.expect(interrupted_state.len > 0);

    index_manager_mod.test_abort_text_backfill_after_batches = null;

    var reopened = try DB.open(alloc, std.mem.span(path), .{});
    defer reopened.close();

    try std.testing.expectError(error.FileNotFound, std.Io.Dir.cwd().readFileAlloc(std.testing.io, state_path.?, alloc, .limited(1024)));

    var result = try reopened.search(alloc, .{
        .index_name = "ft_v1",
        .query = .{ .term = .{ .field = "title", .term = "alpha" } },
        .limit = 20,
    });
    defer result.deinit();
    try std.testing.expectEqual(@as(u32, 10), result.total_hits);

    const stats = try reopened.stats(alloc);
    defer types.freeDBStats(alloc, stats);
    try std.testing.expectEqual(@as(usize, 1), stats.indexes.len);
    try std.testing.expectEqual(false, stats.indexes[0].backfill_active);
}

test "db full-text backfill retires segment fanout at durable batch boundaries" {
    const alloc = std.testing.allocator;

    var path_buf: [256]u8 = undefined;
    const path = tempPath(&path_buf);
    defer cleanupTempDir(path);

    {
        var db = try DB.open(alloc, std.mem.span(path), .{});
        defer db.close();

        var writes = std.ArrayListUnmanaged(types.BatchWrite).empty;
        defer {
            for (writes.items) |item| {
                alloc.free(@constCast(item.key));
                alloc.free(@constCast(item.value));
            }
            writes.deinit(alloc);
        }
        for (0..24) |i| {
            try writes.append(alloc, .{
                .key = try std.fmt.allocPrint(alloc, "doc:{d:0>4}", .{i}),
                .value = try std.fmt.allocPrint(alloc, "{{\"title\":\"bulk backfill {d}\"}}", .{i}),
            });
        }
        try db.batch(.{ .writes = writes.items });
        try db.core.index_manager.addAllNoBackfill(db.core.store, &.{.{
            .name = "ft_v1",
            .kind = .full_text,
            .config_json = "{\"field\":\"title\"}",
        }});
    }

    // Force the pathological pre-fix shape: one published segment per
    // backfill checkpoint. Production backfill uses much larger byte-bounded
    // batches, but must also keep even this worst case policy-settled.
    index_manager_mod.test_text_backfill_batch_size = 1;
    defer index_manager_mod.test_text_backfill_batch_size = null;

    var reopened = try DB.open(alloc, std.mem.span(path), .{});
    defer reopened.close();

    const entry = reopened.core.index_manager.textIndexEntry("ft_v1") orelse return error.IndexNotFound;
    try std.testing.expect(entry.persistent.snapshot().segments.len <= index_manager_mod.default_text_merge_max_segments_per_tier);

    var result = try reopened.search(alloc, .{
        .index_name = "ft_v1",
        .query = .{ .term = .{ .field = "title", .term = "bulk" } },
        .limit = 32,
    });
    defer result.deinit();
    try std.testing.expectEqual(@as(u32, 24), result.total_hits);
}

test "db sparse backfill restarts safely from a legacy cursor after interrupted reopen" {
    const alloc = std.testing.allocator;

    var path_buf: [256]u8 = undefined;
    const path = tempPath(&path_buf);
    defer cleanupTempDir(path);

    {
        var db = try DB.open(alloc, std.mem.span(path), .{});
        defer db.close();

        var writes = std.ArrayListUnmanaged(types.BatchWrite).empty;
        defer {
            for (writes.items) |item| {
                alloc.free(@constCast(item.key));
                alloc.free(@constCast(item.value));
            }
            writes.deinit(alloc);
        }

        for (0..10) |i| {
            try writes.append(alloc, .{
                .key = try std.fmt.allocPrint(alloc, "doc:{d:0>4}", .{i}),
                .value = try alloc.dupe(u8, "{\"sparse\":{\"indices\":[0,1],\"values\":[1.0,0.5]}}"),
            });
        }

        try db.batch(.{ .writes = writes.items });
        try db.core.index_manager.addAllNoBackfill(db.core.store, &.{.{
            .name = "sp_v1",
            .kind = .sparse_vector,
            .config_json = "{\"field\":\"sparse\"}",
        }});
    }

    index_manager_mod.test_sparse_backfill_batch_size = 4;
    defer index_manager_mod.test_sparse_backfill_batch_size = null;
    index_manager_mod.test_abort_sparse_backfill_after_batches = 1;
    defer index_manager_mod.test_abort_sparse_backfill_after_batches = null;
    const rebuild_root = try std.fmt.allocPrint(alloc, "{s}/indexes/sp_v1", .{std.mem.span(path)});
    defer alloc.free(rebuild_root);
    var owned_state_path: ?[]u8 = null;
    defer if (owned_state_path) |owned| alloc.free(owned);
    var resume_key: ?[]u8 = null;
    defer if (resume_key) |owned| alloc.free(owned);
    {
        // A per-index load failure no longer fails the whole open; the index
        // is quarantined with its error recorded and retried on next open.
        var interrupted = try DB.open(alloc, std.mem.span(path), .{});
        defer interrupted.close();
        const recorded = interrupted.core.index_manager.loadFailure("sp_v1") orelse return error.TestUnexpectedResult;
        try std.testing.expectEqualStrings("TestInjectedBackfillFailure", recorded);

        const cfg = interrupted.core.index_manager.get("sp_v1") orelse return error.IndexNotFound;
        const rebuild_state = interrupted.core.index_manager.rebuildState(cfg.kind, rebuild_root, cfg.*);
        owned_state_path = try rebuild_state.pathAlloc(alloc);
        resume_key = (try rebuild_state.checkWithIo(alloc, std.testing.io)) orelse return error.TestExpectedEqual;
        try std.testing.expect(resume_key.?.len > 0);
    }

    // Simulate an upgrade from the legacy raw-cursor format. It cannot be
    // trusted, so reopen must restart from the beginning without inflating the
    // persisted sparse document count for rows already indexed above.
    try std.Io.Dir.cwd().deleteFile(std.testing.io, owned_state_path.?);
    const legacy_rebuild_state = backfill_state_mod.RebuildState.init(rebuild_root);
    const legacy_state_path = try legacy_rebuild_state.pathAlloc(alloc);
    defer alloc.free(legacy_state_path);
    try std.Io.Dir.cwd().writeFile(std.testing.io, .{ .sub_path = legacy_state_path, .data = resume_key.? });

    index_manager_mod.test_abort_sparse_backfill_after_batches = null;

    var reopened = try DB.open(alloc, std.mem.span(path), .{});
    defer reopened.close();

    try std.testing.expectError(error.FileNotFound, std.Io.Dir.cwd().readFileAlloc(std.testing.io, owned_state_path.?, alloc, .limited(1024)));
    try std.testing.expectError(error.FileNotFound, std.Io.Dir.cwd().readFileAlloc(std.testing.io, legacy_state_path, alloc, .limited(1024)));

    var result = try reopened.search(alloc, .{
        .index_name = "sp_v1",
        .query = .{ .sparse_knn = .{
            .indices = &.{0},
            .values = &.{1.0},
            .k = 10,
        } },
        .limit = 10,
    });
    defer result.deinit();
    try std.testing.expect(result.total_hits > 0);

    const stats = try reopened.stats(alloc);
    defer types.freeDBStats(alloc, stats);
    for (stats.indexes) |entry| {
        if (std.mem.eql(u8, entry.name, "sp_v1")) {
            try std.testing.expectEqual(false, entry.backfill_active);
            try std.testing.expectEqual(@as(u64, 10), entry.doc_count);
            return;
        }
    }
    return error.TestExpectedEqual;
}

fn waitForAtomicFlag(flag: *const std.atomic.Value(u8), expected: u8, max_attempts: usize) bool {
    var attempts: usize = 0;
    while (attempts < max_attempts) : (attempts += 1) {
        if (flag.load(.monotonic) == expected) return true;
        std.Thread.yield() catch {};
    }
    return flag.load(.monotonic) == expected;
}

const SharedReadLockHold = struct {
    db: *DB,
    acquired: std.atomic.Value(u8) = .init(0),
    release: std.atomic.Value(u8) = .init(0),

    fn run(self: *@This()) void {
        self.db.core.lockApplyShared();
        self.acquired.store(1, .monotonic);
        while (self.release.load(.monotonic) == 0) {
            std.Thread.yield() catch {};
        }
        self.db.core.unlockApplyShared();
    }
};

const ConcurrentReadProbe = struct {
    db: *DB,
    started: std.atomic.Value(u8) = .init(0),
    done: std.atomic.Value(u8) = .init(0),
    failed: std.atomic.Value(u8) = .init(0),

    fn runSearch(self: *@This()) void {
        self.started.store(1, .monotonic);
        var result = self.db.search(std.heap.c_allocator, .{
            .index_name = "ft_v1",
            .full_text = .{ .match = .{ .field = "title", .text = "alpha" } },
        }) catch {
            self.failed.store(1, .monotonic);
            return;
        };
        defer result.deinit();
        self.done.store(1, .monotonic);
    }

    fn runScan(self: *@This()) void {
        self.started.store(1, .monotonic);
        var result = self.db.scan(std.heap.c_allocator, "", "", .{
            .include_documents = true,
            .limit = 10,
        }) catch {
            self.failed.store(1, .monotonic);
            return;
        };
        defer result.deinit(std.heap.c_allocator);
        self.done.store(1, .monotonic);
    }
};

const ConcurrentWriteProbe = struct {
    db: *DB,
    started: std.atomic.Value(u8) = .init(0),
    done: std.atomic.Value(u8) = .init(0),
    failed: std.atomic.Value(u8) = .init(0),

    fn runBatch(self: *@This()) void {
        self.started.store(1, .monotonic);
        self.db.batch(.{
            .writes = &.{
                .{ .key = "doc:b", .value = "{\"title\":\"bravo\"}" },
            },
        }) catch {
            self.failed.store(1, .monotonic);
            return;
        };
        self.done.store(1, .monotonic);
    }
};

