        .graph_writes = &.{
            .{ .index_name = "gr_alg", .source = "n:a", .target = "n:b", .edge_type = "links" },
            .{ .index_name = "gr_alg", .source = "n:a", .target = "n:c", .edge_type = "links" },
        },
