            .{ .key = "doc:c", .value = "{\"body\":\"common gamma\",\"_embeddings\":{\"dv_v1\":[0,0,1]}}" },
        },
        .sync_level = .full_index,
    });

    const dense_queries = [_]types.NamedDenseQuery{.{
