        });

        const record_key = blk_key: {
            const prefix = "\x00\x00__txn_records__:";
            var key: [prefix.len + @sizeOf(transactions_mod.TxnId)]u8 = undefined;
            @memcpy(key[0..prefix.len], prefix);
            @memcpy(key[prefix.len..], &txn_id);
